-- Clean-room baseline (PostgreSQL 17) for a fresh project only; fails closed if
-- public already holds application relations.
DO $clean_baseline_guard$
DECLARE
  application_relations integer;
BEGIN
  SELECT count(*)
    INTO application_relations
    FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
   WHERE n.nspname = 'public'
     AND c.relkind IN ('r', 'p', 'v', 'm', 'S', 'f')
     AND NOT EXISTS (
       SELECT 1
         FROM pg_catalog.pg_depend d
        WHERE d.classid = 'pg_class'::regclass
          AND d.objid = c.oid
          AND d.deptype = 'e'
     );

  IF application_relations <> 0 THEN
    RAISE EXCEPTION
      'clean baseline requires an empty public schema; found % application relation(s)',
      application_relations;
  END IF;

  IF current_setting('server_version_num')::integer < 170000 THEN
    RAISE EXCEPTION 'clean baseline requires PostgreSQL 17 or newer';
  END IF;
END
$clean_baseline_guard$;

DO $clean_baseline_roles$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_roles
     WHERE rolname = 'command_center_rpc_owner'
  ) THEN
    CREATE ROLE command_center_rpc_owner
      NOLOGIN NOINHERIT NOBYPASSRLS;
  END IF;
END
$clean_baseline_roles$;

-- Temporary membership so ownership can be reassigned; revoked after the restore.
GRANT command_center_rpc_owner TO postgres;


SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

CREATE SCHEMA IF NOT EXISTS monitoring;

ALTER SCHEMA monitoring OWNER TO postgres;

CREATE SCHEMA IF NOT EXISTS public;

ALTER SCHEMA public OWNER TO pg_database_owner;

-- ALTER ... OWNER needs CREATE on the schema; revoked again after the restore.
GRANT USAGE, CREATE ON SCHEMA public TO command_center_rpc_owner;

COMMENT ON SCHEMA public IS 'standard public schema';

