CREATE FUNCTION monitoring.capture_slow_queries(threshold_ms numeric DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
    queries_logged INTEGER := 0;
BEGIN
    -- This function is a placeholder for manual slow query logging
    -- In production, you would integrate with pg_stat_statements
    -- or parse query logs

    -- Example: Log a test slow query for verification
    IF NOT EXISTS (SELECT 1 FROM monitoring.slow_queries LIMIT 1) THEN
        INSERT INTO monitoring.slow_queries (
            query_id, query, duration_ms, calls, mean_ms, min_ms, max_ms, total_ms, rows_returned
        ) VALUES (
            1,
            'SELECT * FROM EOT_GR_data WHERE Season = $1 /* SAMPLE TEST QUERY */',
            1500,
            10,
            1500,
            1000,
            2000,
            15000,
            1000
        );
        queries_logged := 1;
    END IF;

    RETURN queries_logged;
END;
$_$;

ALTER FUNCTION monitoring.capture_slow_queries(threshold_ms numeric) OWNER TO postgres;

CREATE FUNCTION monitoring.check_query_alerts() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    alert RECORD;
    slow_query RECORD;
    alerts_triggered INTEGER := 0;
BEGIN
    FOR alert IN
        SELECT * FROM monitoring.query_alerts
        WHERE enabled = true
    LOOP
        FOR slow_query IN
            SELECT * FROM monitoring.slow_queries
            WHERE duration_ms > alert.threshold_ms
            AND logged_at > COALESCE(alert.last_triggered, NOW() - INTERVAL '1 hour')
            AND (alert.query_pattern IS NULL OR query LIKE alert.query_pattern)
            LIMIT 1
        LOOP
            -- Log alert
            INSERT INTO monitoring.alert_log (
                alert_id,
                query_id,
                triggered_at,
                duration_ms
            ) VALUES (
                alert.id,
                slow_query.id,
                NOW(),
                slow_query.duration_ms
            );

            -- Update last triggered
            UPDATE monitoring.query_alerts
            SET last_triggered = NOW()
            WHERE id = alert.id;

            alerts_triggered := alerts_triggered + 1;
        END LOOP;
    END LOOP;

    RETURN alerts_triggered;
END;
$$;

ALTER FUNCTION monitoring.check_query_alerts() OWNER TO postgres;

CREATE FUNCTION monitoring.get_query_statistics(time_range interval DEFAULT '24:00:00'::interval) RETURNS TABLE(total_slow_queries bigint, unique_queries bigint, avg_duration numeric, max_duration numeric, p95_duration numeric, p99_duration numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*)::BIGINT as total_slow_queries,
        COUNT(DISTINCT query_fingerprint)::BIGINT as unique_queries,
        ROUND(AVG(duration_ms), 2) as avg_duration,
        ROUND(MAX(duration_ms), 2) as max_duration,
        ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY duration_ms)::NUMERIC, 2) as p95_duration,
        ROUND(PERCENTILE_CONT(0.99) WITHIN GROUP (ORDER BY duration_ms)::NUMERIC, 2) as p99_duration
    FROM monitoring.slow_queries
    WHERE logged_at >= NOW() - time_range;
END;
$$;

ALTER FUNCTION monitoring.get_query_statistics(time_range interval) OWNER TO postgres;

CREATE FUNCTION monitoring.notify(p_alert_key text, p_status text, p_title text, p_body text DEFAULT NULL::text, p_quiet boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  prev_status TEXT;
  prev_since  TIMESTAMPTZ;
  webhook_url TEXT;
  colour int;
  prefix text;
  since_txt text := '';
  payload jsonb;
BEGIN
  IF p_status NOT IN ('firing', 'cleared') THEN
    RAISE EXCEPTION 'monitoring.notify: status must be firing|cleared, got %', p_status;
  END IF;

  -- Per-key lock: without it two concurrent reporters can both observe the old
  -- status and both post the same transition.
  SELECT s.status, s.since INTO prev_status, prev_since
    FROM monitoring.alert_state s
   WHERE s.alert_key = p_alert_key
     FOR UPDATE;

  -- Unchanged: refresh liveness only. Never posts.
  IF prev_status IS NOT DISTINCT FROM p_status THEN
    UPDATE monitoring.alert_state
       SET last_seen_at = now(), last_title = p_title, last_body = p_body
     WHERE alert_key = p_alert_key;
    RETURN false;
  END IF;

  -- First sighting of an already-healthy key is not news, but DO register it so
  -- the table is a complete coverage index rather than a list of things that
  -- have happened to break.
  IF prev_status IS NULL AND p_status = 'cleared' THEN
    INSERT INTO monitoring.alert_state (alert_key, status, since, last_seen_at, last_title, last_body)
    VALUES (p_alert_key, 'cleared', now(), now(), p_title, p_body)
    ON CONFLICT (alert_key) DO UPDATE
       SET last_seen_at = now(), last_title = EXCLUDED.last_title, last_body = EXCLUDED.last_body;
    RETURN false;
  END IF;

  -- A real transition. Record it ONLY after delivery is accepted (defect 1),
  -- except in quiet mode where there is nothing to deliver.
  IF NOT p_quiet THEN
    webhook_url := current_setting('app.settings.monitoring_webhook_url', true);
    IF webhook_url IS NULL OR webhook_url = '' THEN
      -- Deliberately does NOT write state: leaving it untouched is what lets
      -- the next run retry instead of silently swallowing the transition.
      RAISE WARNING '[monitoring.notify] % -> % NOT recorded: no monitoring_webhook_url configured (will retry next run)',
        p_alert_key, p_status;
      RETURN false;
    END IF;

    IF p_status = 'firing' THEN
      colour := 15548997; prefix := '🔴 ';
    ELSE
      colour := 3066993;  prefix := '🟢 RESOLVED — ';
      -- prev_since, captured before any write (defect 2).
      IF prev_since IS NOT NULL THEN
        since_txt := format(E'\nWas firing for %s.', justify_interval(now() - prev_since));
      END IF;
    END IF;

    payload := jsonb_build_object(
      'embeds', jsonb_build_array(jsonb_build_object(
        'title', prefix || p_title,
        'description', LEFT(COALESCE(p_body, '') || since_txt, 1900),
        'color', colour,
        'footer', jsonb_build_object('text', 'alert_key: ' || p_alert_key),
        'timestamp', now()::text
      )));

    BEGIN
      PERFORM net.http_post(url := webhook_url,
                            headers := '{"Content-Type": "application/json"}'::jsonb,
                            body := payload);
    EXCEPTION WHEN undefined_function THEN
      -- Legacy pg_net exposes a TEXT body (defect 4) — same fallback
      -- call_edge_function() carries.
      PERFORM net.http_post(url := webhook_url,
                            headers := '{"Content-Type": "application/json"}'::jsonb,
                            body := payload::text);
    END;
  END IF;

  INSERT INTO monitoring.alert_state (alert_key, status, since, last_seen_at, last_title, last_body)
  VALUES (p_alert_key, p_status, now(), now(), p_title, p_body)
  ON CONFLICT (alert_key) DO UPDATE
     SET status = EXCLUDED.status, since = now(), last_seen_at = now(),
         last_title = EXCLUDED.last_title, last_body = EXCLUDED.last_body;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  -- A notifier must never take down its caller. State is deliberately left
  -- as-is so the transition is retried rather than lost.
  RAISE WARNING '[monitoring.notify] % -> % failed (state unchanged, will retry): %',
    p_alert_key, p_status, SQLERRM;
  RETURN false;
END;
$$;

ALTER FUNCTION monitoring.notify(p_alert_key text, p_status text, p_title text, p_body text, p_quiet boolean) OWNER TO postgres;

