CREATE FUNCTION public._sync_guild_cluster_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Normalize empty cluster_code to NULL.
  IF NEW.cluster_code IS NOT NULL AND length(trim(NEW.cluster_code)) = 0 THEN
    NEW.cluster_code := NULL;
  END IF;

  -- If cluster_code is set but cluster_id is unset (or doesn't match), resolve
  -- it from clusters.cluster_code → clusters.id. Leaves cluster_id NULL when
  -- no clusters row resolves (so unresolvable codes stay flagged for humans).
  IF NEW.cluster_code IS NOT NULL THEN
    IF NEW.cluster_id IS NULL
       OR NOT EXISTS (
         SELECT 1 FROM public.clusters c
         WHERE c.id = NEW.cluster_id
           AND c.cluster_code = NEW.cluster_code
       )
    THEN
      SELECT c.id INTO NEW.cluster_id
      FROM public.clusters c
      WHERE c.cluster_code = NEW.cluster_code
      LIMIT 1;
    END IF;
  ELSE
    -- cluster_code cleared → clear cluster_id too. The fk_guild_cluster
    -- ON DELETE SET NULL handles the cluster-deletion case; this handles the
    -- explicit "leave cluster" path.
    NEW.cluster_id := NULL;
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION public._sync_guild_cluster_id() OWNER TO postgres;

CREATE FUNCTION public.activate_discord_identity_generation(p_unlink_id uuid, p_relink_nonce uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $_$
DECLARE
  v_user_id uuid := auth.uid();
  v_pending record;
  v_mapping_count integer;
  v_mapping_id integer;
  v_mapping_player_id text;
  v_mapping_attestation_id uuid;
  v_identity_count integer;
  v_identity_id uuid;
  v_identity_provider_id text;
  v_identity_updated_at timestamptz;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '42501';
  END IF;
  IF p_unlink_id IS NULL OR p_relink_nonce IS NULL THEN
    RAISE EXCEPTION 'Relink generation and nonce are required'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(6208, hashtext(v_user_id::text));
  SELECT pending.*
  INTO v_pending
  FROM public.player_identity_discord_unlink_pending AS pending
  WHERE pending.id = p_unlink_id
    AND pending.subject_user_id = v_user_id
    AND pending.generation = (
      SELECT max(latest.generation)
      FROM public.player_identity_discord_unlink_pending AS latest
      WHERE latest.subject_user_id = v_user_id
    )
  FOR UPDATE;
  IF NOT FOUND OR v_pending.relink_nonce_sha256 IS DISTINCT FROM encode(
    extensions.digest(convert_to(p_relink_nonce::text, 'UTF8'), 'sha256'), 'hex'
  ) OR EXISTS (
    SELECT 1
    FROM public.player_identity_discord_generation_activations AS activation
    WHERE activation.pending_id = p_unlink_id
  ) THEN
    RAISE EXCEPTION 'Relink generation or nonce is stale'
      USING ERRCODE = '42501';
  END IF;

  SELECT count(*),
         (array_agg(mapping.id ORDER BY mapping.id))[1],
         (array_agg(mapping.player_id ORDER BY mapping.id))[1],
         (array_agg(mapping.ownership_attestation_id ORDER BY mapping.id))[1]
  INTO v_mapping_count, v_mapping_id, v_mapping_player_id,
       v_mapping_attestation_id
  FROM public.player_mapping AS mapping
  CROSS JOIN LATERAL (
    SELECT count(*) AS proof_count
    FROM public.player_identity_attestations AS attestation
    WHERE attestation.id = mapping.ownership_attestation_id
      AND attestation.mapping_id = mapping.id
      AND attestation.player_id = mapping.player_id
      AND attestation.subject_user_id = mapping.user_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_attestation_revocations AS revoked
        WHERE revoked.attestation_id = attestation.id
      )
  ) AS proof
  WHERE mapping.is_current IS TRUE
    AND mapping.user_id = v_user_id
    AND proof.proof_count = 1;
  IF v_mapping_count <> 1 THEN
    RAISE EXCEPTION 'Fresh Discord relink requires one proven player mapping'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*),
         (array_agg(identity.id ORDER BY identity.id))[1],
         (array_agg(identity.provider_id ORDER BY identity.id))[1],
         (array_agg(coalesce(identity.updated_at, identity.created_at)
                    ORDER BY identity.id))[1]
  INTO v_identity_count, v_identity_id, v_identity_provider_id,
       v_identity_updated_at
  FROM auth.identities AS identity
  WHERE identity.user_id = v_user_id
    AND identity.provider = 'discord'
    AND identity.provider_id ~ '^[0-9]{17,20}$';
  IF v_identity_count <> 1 OR v_identity_updated_at IS NULL
    OR (
      v_identity_id IS NOT DISTINCT FROM v_pending.prior_auth_identity_id
      AND v_identity_updated_at <= v_pending.prepared_at
    )
  THEN
    RAISE EXCEPTION
      'Fresh provider generation is not proven after unlink preparation'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.player_identity_discord_generation_activations (
    pending_id, subject_user_id, ownership_attestation_id,
    auth_identity_id, provider_id_sha256, identity_updated_at
  ) VALUES (
    p_unlink_id, v_user_id, v_mapping_attestation_id,
    v_identity_id,
    encode(extensions.digest(convert_to(v_identity_provider_id, 'UTF8'),
                             'sha256'), 'hex'),
    v_identity_updated_at
  );

  UPDATE public.player_mapping AS mapping
  SET discord_user_id = v_identity_provider_id,
      discord_username = NULL,
      updated_at = clock_timestamp()
  WHERE mapping.id = v_mapping_id;

  UPDATE auth.users AS target
  SET raw_user_meta_data = jsonb_set(
    jsonb_set(
      coalesce(target.raw_user_meta_data, '{}'::jsonb),
      '{discord_user_id}', to_jsonb(v_identity_provider_id), true
    ),
    '{discord_synced}', 'true'::jsonb, true
  ) - 'discord_username'
  WHERE target.id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'unlink_id', p_unlink_id,
    'generation', v_pending.generation,
    'mapping_id', v_mapping_id,
    'discord_user_id', v_identity_provider_id,
    'fresh_generation_activated', true
  );
END
$_$;

ALTER FUNCTION public.activate_discord_identity_generation(p_unlink_id uuid, p_relink_nonce uuid) OWNER TO postgres;

CREATE FUNCTION public.add_column_if_not_exists(p_table_name text, p_column_name text, p_column_definition text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  column_exists boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_name = p_table_name
    AND column_name = p_column_name
  ) INTO column_exists;

  IF NOT column_exists THEN
    EXECUTE format('ALTER TABLE %I ADD COLUMN %I %s', p_table_name, p_column_name, p_column_definition);
  END IF;
END;
$$;

ALTER FUNCTION public.add_column_if_not_exists(p_table_name text, p_column_name text, p_column_definition text) OWNER TO postgres;

CREATE FUNCTION public.add_guild_to_cluster(p_guild_code text, p_display_name text, p_cluster_code text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_role text;
  v_user_cluster text;
  v_cluster_id uuid;
  v_result json;
BEGIN
  -- Check if user is a leader
  SELECT role INTO v_user_role
  FROM player_mapping
  WHERE user_id = auth.uid()
    AND is_current = true
  LIMIT 1;

  IF v_user_role != 'leader' THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Only leaders can add guilds to clusters'
    );
  END IF;

  -- Get user's cluster
  SELECT gc.cluster_code INTO v_user_cluster
  FROM player_mapping pm
  JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = auth.uid()
    AND pm.is_current = true
  LIMIT 1;

  -- Verify user can add to this cluster
  IF p_cluster_code IS NOT NULL AND v_user_cluster != p_cluster_code THEN
    RETURN json_build_object(
      'success', false,
      'message', 'You can only add guilds to your own cluster'
    );
  END IF;

  -- Get cluster_id from cluster_code
  IF COALESCE(p_cluster_code, v_user_cluster) IS NOT NULL THEN
    SELECT id INTO v_cluster_id
    FROM clusters
    WHERE cluster_code = COALESCE(p_cluster_code, v_user_cluster)
    LIMIT 1;

    IF v_cluster_id IS NULL THEN
      RETURN json_build_object(
        'success', false,
        'message', 'Invalid cluster code'
      );
    END IF;
  END IF;

  -- Check if guild already exists
  IF EXISTS (SELECT 1 FROM guild_config WHERE guild_code = p_guild_code) THEN
    -- Update existing guild (removed api_key update)
    UPDATE guild_config
    SET cluster_code = COALESCE(p_cluster_code, v_user_cluster),
        cluster_id = v_cluster_id,
        display_name = COALESCE(p_display_name, display_name),
        enabled = true
    WHERE guild_code = p_guild_code;

    RETURN json_build_object(
      'success', true,
      'message', 'Guild updated and added to cluster',
      'guild_code', p_guild_code
    );
  ELSE
    -- Insert new guild (removed api_key field)
    INSERT INTO guild_config (
      guild_code,
      display_name,
      cluster_code,
      cluster_id,
      enabled,
      token_offender_threshold,
      token_abuser_threshold
    ) VALUES (
      p_guild_code,
      p_display_name,
      COALESCE(p_cluster_code, v_user_cluster),
      v_cluster_id,
      true,
      10,
      15
    );

    RETURN json_build_object(
      'success', true,
      'message', 'Guild created and added to cluster',
      'guild_code', p_guild_code
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Error adding guild: ' || SQLERRM
    );
END;
$$;

ALTER FUNCTION public.add_guild_to_cluster(p_guild_code text, p_display_name text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.add_guild_to_cluster(p_guild_code text, p_display_name text, p_cluster_code text, p_api_key text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user_role text;
  v_user_cluster text;
  v_cluster_id uuid;
  v_result json;
BEGIN
  -- Check if user is a leader
  SELECT role INTO v_user_role
  FROM player_mapping
  WHERE user_id = auth.uid()
    AND is_current = true
  LIMIT 1;

  IF v_user_role != 'leader' THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Only leaders can add guilds to clusters'
    );
  END IF;

  -- Get user's cluster
  SELECT gc.cluster_code INTO v_user_cluster
  FROM player_mapping pm
  JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = auth.uid()
    AND pm.is_current = true
  LIMIT 1;

  -- Verify user can add to this cluster
  IF p_cluster_code IS NOT NULL AND v_user_cluster != p_cluster_code THEN
    RETURN json_build_object(
      'success', false,
      'message', 'You can only add guilds to your own cluster'
    );
  END IF;

  -- Get cluster_id from cluster_code
  IF COALESCE(p_cluster_code, v_user_cluster) IS NOT NULL THEN
    SELECT id INTO v_cluster_id
    FROM clusters
    WHERE cluster_code = COALESCE(p_cluster_code, v_user_cluster)
    LIMIT 1;

    IF v_cluster_id IS NULL THEN
      RETURN json_build_object(
        'success', false,
        'message', 'Invalid cluster code'
      );
    END IF;
  END IF;

  -- Check if guild already exists
  IF EXISTS (SELECT 1 FROM guild_config WHERE guild_code = p_guild_code) THEN
    -- Update existing guild
    UPDATE guild_config
    SET cluster_code = COALESCE(p_cluster_code, v_user_cluster),
        cluster_id = v_cluster_id,  -- Set cluster_id properly
        display_name = COALESCE(p_display_name, display_name),
        api_key = COALESCE(p_api_key, api_key),
        enabled = true
    WHERE guild_code = p_guild_code;

    RETURN json_build_object(
      'success', true,
      'message', 'Guild updated and added to cluster',
      'guild_code', p_guild_code
    );
  ELSE
    -- Insert new guild
    INSERT INTO guild_config (
      guild_code,
      display_name,
      cluster_code,
      cluster_id,  -- Include cluster_id in insert
      api_key,
      enabled,
      token_offender_threshold,
      token_abuser_threshold
    ) VALUES (
      p_guild_code,
      p_display_name,
      COALESCE(p_cluster_code, v_user_cluster),
      v_cluster_id,  -- Set cluster_id properly
      p_api_key,
      true,
      10,
      15
    );

    RETURN json_build_object(
      'success', true,
      'message', 'Guild created and added to cluster',
      'guild_code', p_guild_code
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Error adding guild: ' || SQLERRM
    );
END;
$$;

ALTER FUNCTION public.add_guild_to_cluster(p_guild_code text, p_display_name text, p_cluster_code text, p_api_key text) OWNER TO postgres;

CREATE FUNCTION public.add_guild_to_cluster_safe(p_guild_code text, p_display_name text, p_cluster_code text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_role text;
  v_user_cluster text;
  v_cluster_id uuid;
BEGIN
  -- Check if user is authenticated
  IF auth.uid() IS NULL THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Authentication required'
    );
  END IF;

  -- Check if user is a leader
  SELECT role INTO v_user_role
  FROM player_mapping
  WHERE user_id = auth.uid()
    AND is_current = true
  LIMIT 1;

  IF v_user_role != 'leader' THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Only leaders can add guilds to clusters'
    );
  END IF;

  -- Basic input validation
  IF p_guild_code IS NULL OR p_guild_code = '' THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Guild code is required'
    );
  END IF;

  IF p_display_name IS NULL OR p_display_name = '' THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Display name is required'
    );
  END IF;

  -- Get user's cluster (if any)
  SELECT gc.cluster_code INTO v_user_cluster
  FROM player_mapping pm
  JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = auth.uid()
    AND pm.is_current = true
  LIMIT 1;

  -- Use provided cluster or user's cluster
  p_cluster_code := COALESCE(p_cluster_code, v_user_cluster);

  -- Get cluster_id from cluster_code if we have one
  IF p_cluster_code IS NOT NULL THEN
    SELECT id INTO v_cluster_id
    FROM clusters
    WHERE cluster_code = p_cluster_code
    LIMIT 1;

    IF v_cluster_id IS NULL THEN
      RETURN json_build_object(
        'success', false,
        'message', 'Invalid cluster code: ' || p_cluster_code
      );
    END IF;
  END IF;

  -- Check if guild already exists
  IF EXISTS (SELECT 1 FROM guild_config WHERE guild_code = p_guild_code) THEN
    -- Update existing guild (removed api_key update)
    UPDATE guild_config
    SET cluster_code = p_cluster_code,
        cluster_id = v_cluster_id,
        display_name = p_display_name,
        enabled = true
    WHERE guild_code = p_guild_code;

    RETURN json_build_object(
      'success', true,
      'message', 'Guild updated successfully',
      'guild_code', p_guild_code
    );
  ELSE
    -- Insert new guild (removed api_key field)
    INSERT INTO guild_config (
      guild_code,
      display_name,
      cluster_code,
      cluster_id,
      enabled,
      token_offender_threshold,
      token_abuser_threshold
    ) VALUES (
      p_guild_code,
      p_display_name,
      p_cluster_code,
      v_cluster_id,
      true,
      10,
      15
    );

    RETURN json_build_object(
      'success', true,
      'message', 'Guild created successfully',
      'guild_code', p_guild_code
    );
  END IF;

EXCEPTION
  WHEN unique_violation THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Guild code already exists'
    );
  WHEN OTHERS THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Error: ' || SQLERRM
    );
END;
$$;

ALTER FUNCTION public.add_guild_to_cluster_safe(p_guild_code text, p_display_name text, p_cluster_code text) OWNER TO postgres;

