CREATE FUNCTION public.admin_add_alpha_tester(p_user_email text, p_notes text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id uuid;
    v_caller_id uuid;
BEGIN
    v_caller_id := auth.uid();

    -- When auth.uid() is NULL, the call is from a service_role client (server-side).
    -- The API layer enforces admin access, so allow through.
    IF v_caller_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM player_mapping pm
        WHERE pm.user_id = v_caller_id
            AND pm.is_current = true
            AND pm.is_app_admin = true
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only app admins can add alpha testers'
        );
    END IF;

    SELECT id INTO v_user_id
    FROM auth.users
    WHERE email = p_user_email;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User not found with that email'
        );
    END IF;

    INSERT INTO feature_access_grants (user_id, access_level, granted_by, notes, expires_at)
    VALUES (v_user_id, 'alpha_tester', v_caller_id, p_notes, p_expires_at)
    ON CONFLICT (user_id, access_level) DO UPDATE SET
        granted_by = v_caller_id,
        granted_at = now(),
        notes = COALESCE(p_notes, feature_access_grants.notes),
        expires_at = p_expires_at;

    RETURN jsonb_build_object(
        'success', true,
        'user_id', v_user_id,
        'access_level', 'alpha_tester'
    );
END;
$$;

ALTER FUNCTION public.admin_add_alpha_tester(p_user_email text, p_notes text, p_expires_at timestamp with time zone) OWNER TO postgres;

CREATE FUNCTION public.admin_remove_alpha_tester(p_user_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id uuid;
    v_caller_id uuid;
BEGIN
    v_caller_id := auth.uid();

    -- When auth.uid() is NULL, the call is from a service_role client (server-side).
    -- The API layer enforces admin access, so allow through.
    IF v_caller_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM player_mapping pm
        WHERE pm.user_id = v_caller_id
            AND pm.is_current = true
            AND pm.is_app_admin = true
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only app admins can remove alpha testers'
        );
    END IF;

    SELECT id INTO v_user_id
    FROM auth.users
    WHERE email = p_user_email;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User not found with that email'
        );
    END IF;

    DELETE FROM feature_access_grants
    WHERE user_id = v_user_id AND access_level = 'alpha_tester';

    RETURN jsonb_build_object(
        'success', true,
        'user_id', v_user_id
    );
END;
$$;

ALTER FUNCTION public.admin_remove_alpha_tester(p_user_email text) OWNER TO postgres;

CREATE FUNCTION public.admin_update_feature_stage(p_feature_key text, p_new_stage text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_is_service boolean := COALESCE(
    NULLIF(NULLIF(current_setting('role', true), ''), 'none'),
    NULLIF(session_user, '')
  ) = 'service_role';
BEGIN
    -- WI-3139: enforce app-admin authority inside the trusted path. The route
    -- also gates with withAppAdmin, but the database is the authoritative
    -- boundary. Effective service_role (database role) bypasses. app-admin is
    -- the WI-630 player_mapping.is_app_admin predicate via _pm_caller_is_app_admin().
    IF NOT v_is_service AND NOT public._pm_caller_is_app_admin() THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only app admins can update feature stages'
        );
    END IF;

    IF p_new_stage NOT IN ('alpha', 'beta', 'early_access', 'premium', 'coming_soon', 'public') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Invalid release stage'
        );
    END IF;

    UPDATE feature_releases
    SET
        release_stage = p_new_stage,
        updated_at = now(),
        released_at = CASE WHEN p_new_stage = 'public' THEN now() ELSE released_at END
    WHERE feature_key = p_feature_key;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Feature not found'
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'feature_key', p_feature_key,
        'new_stage', p_new_stage
    );
END;
$$;

ALTER FUNCTION public.admin_update_feature_stage(p_feature_key text, p_new_stage text) OWNER TO postgres;

CREATE FUNCTION public.analyze_inactive_guilds() RETURNS TABLE(guild_id integer, guild_code text, display_name text, enabled boolean, total_members bigint, active_members bigint, recent_battles bigint, last_activity timestamp with time zone, activity_score numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  WITH guild_activity AS (
    SELECT
      gc.id as guild_id,
      gc.guild_code,
      gc.display_name,
      gc.enabled,
      COUNT(pm.player_id) FILTER (WHERE pm.is_current = true) as total_members,
      COUNT(pm.player_id) FILTER (WHERE pm.is_current = true AND pm.last_battle_time > NOW() - INTERVAL '30 days') as active_members,
      COUNT(pm.player_id) FILTER (WHERE pm.is_current = true AND pm.last_battle_time > NOW() - INTERVAL '7 days') as recent_battles,
      MAX(pm.last_battle_time) as last_activity
    FROM guild_config gc
    LEFT JOIN player_mapping pm ON gc.guild_code = pm.guild_code
    GROUP BY gc.id, gc.guild_code, gc.display_name, gc.enabled
  ),
  scored_guilds AS (
    SELECT
      guild_id,
      guild_code,
      display_name,
      enabled,
      total_members,
      active_members,
      recent_battles,
      last_activity,
      CASE
        WHEN total_members = 0 THEN 0
        WHEN last_activity IS NULL THEN 0
        WHEN last_activity < NOW() - INTERVAL '90 days' THEN 1
        WHEN last_activity < NOW() - INTERVAL '30 days' THEN 2
        WHEN active_members::NUMERIC / total_members < 0.1 THEN 3
        WHEN active_members::NUMERIC / total_members < 0.3 THEN 4
        ELSE 5
      END as activity_score
    FROM guild_activity
  )
  SELECT *
  FROM scored_guilds
  WHERE enabled = false OR activity_score <= 3
  ORDER BY enabled DESC, activity_score ASC, last_activity DESC NULLS LAST;
$$;

ALTER FUNCTION public.analyze_inactive_guilds() OWNER TO postgres;

CREATE FUNCTION public.analyze_player_progression(p_guild_code text, p_player_name text) RETURNS TABLE(player_id text, player_name text, season text, avg_damage numeric, total_battles bigint, improvement_pct numeric, guild_rank integer, season_rank integer)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  target_player_id TEXT;
BEGIN
  -- Resolve player name to player_id
  SELECT pm.player_id INTO target_player_id
  FROM player_mapping pm
  WHERE pm.display_name = p_player_name
    AND pm.is_current = true
  LIMIT 1;

  IF target_player_id IS NULL THEN
    SELECT pm.player_id INTO target_player_id
    FROM player_mapping pm
    WHERE pm.display_name = p_player_name
    ORDER BY pm.updated_at DESC
    LIMIT 1;
  END IF;

  IF target_player_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH player_season_stats AS (
    SELECT
      e."userId" as player_id,
      pm.display_name as current_player_name,
      e."Season",
      AVG(e."damageDealt") as avg_damage,
      COUNT(*) as total_battles
    FROM "EOT_GR_data" e
    LEFT JOIN player_mapping pm ON e."userId" = pm.player_id AND pm.is_current = true
    WHERE e."Guild" = p_guild_code
      AND e."userId" = target_player_id
      AND e."damageDealt" > 0
      AND e."Season" ~ '^\d+$'
    GROUP BY e."userId", pm.display_name, e."Season"
  ),
  with_improvement AS (
    SELECT
      pss.*,
      LAG(pss.avg_damage) OVER (ORDER BY pss."Season"::INTEGER) as prev_avg_damage
    FROM player_season_stats pss
  ),
  with_ranks AS (
    SELECT
      wi.*,
      CASE
        WHEN wi.prev_avg_damage IS NOT NULL AND wi.prev_avg_damage > 0
        THEN ROUND(((wi.avg_damage - wi.prev_avg_damage) / wi.prev_avg_damage * 100)::numeric, 1)
        ELSE NULL
      END as improvement_pct,
      -- Guild rank calculation would require a separate subquery for each season
      NULL::INTEGER as guild_rank,
      ROW_NUMBER() OVER (ORDER BY wi."Season"::INTEGER) as season_rank
    FROM with_improvement wi
  )
  SELECT
    wr.player_id::TEXT,
    COALESCE(wr.current_player_name, 'Unknown Player')::TEXT as player_name,
    wr."Season"::TEXT,
    wr.avg_damage,
    wr.total_battles,
    wr.improvement_pct,
    wr.guild_rank,
    wr.season_rank
  FROM with_ranks wr
  ORDER BY wr."Season"::INTEGER;
END;
$_$;

ALTER FUNCTION public.analyze_player_progression(p_guild_code text, p_player_name text) OWNER TO postgres;

CREATE FUNCTION public.analyze_team_composition(p_guild_code text, p_hero_keys text[], p_season_count integer DEFAULT 4) RETURNS TABLE(total_uses bigint, wins bigint, losses bigint, win_rate numeric, avg_score numeric, zone_breakdown jsonb, buff_breakdown jsonb, matchup_summary jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min_season INT;
  v_hero_set TEXT[];
BEGIN
  SELECT MAX(war_season) - p_season_count + 1 INTO v_min_season
  FROM guild_war_matches
  WHERE guild_code = p_guild_code;

  IF v_min_season IS NULL THEN
    v_min_season := 0;
  END IF;

  v_hero_set := ARRAY(SELECT unnest(p_hero_keys) ORDER BY 1);

  RETURN QUERY
  WITH team_battles AS (
    SELECT
      -- Prod table has `id`, NOT `battle_id` (second nonexistent-column bug in the
      -- original: verified against live information_schema 2026-07-08; the cores
      -- fix 20260402000003 made this same correction).
      b.id AS battle_id,
      b.score_earned,
      b.zone_type,
      b.attempt_debuff,
      war_zone_captured(b.attempt_result, b.defender_units_json) AS is_win,
      ARRAY(
        SELECT h->>'heroKey'
        FROM jsonb_array_elements(b.attacker_units_json) AS h
        ORDER BY h->>'heroKey'
      ) AS attacker_heroes
    FROM guild_war_battles b
    JOIN guild_war_matches m ON m.war_id = b.war_id AND m.guild_code = b.guild_code
    WHERE b.guild_code = p_guild_code
      AND b.is_guild_member = TRUE
      AND b.attacker_units_json IS NOT NULL
      AND m.war_season >= v_min_season
  ),
  exact_matches AS (
    SELECT *
    FROM team_battles
    WHERE attacker_heroes = v_hero_set
  ),
  zone_stats AS (
    SELECT
      zone_type,
      COUNT(*) AS uses,
      COUNT(*) FILTER (WHERE is_win) AS wins,
      ROUND((COUNT(*) FILTER (WHERE is_win)::NUMERIC / NULLIF(COUNT(*), 0)) * 100, 1) AS win_rate
    FROM exact_matches
    GROUP BY zone_type
    ORDER BY uses DESC
  ),
  buff_stats AS (
    SELECT
      COALESCE(attempt_debuff, 0) AS debuff_level,
      COUNT(*) AS uses,
      COUNT(*) FILTER (WHERE is_win) AS wins,
      ROUND((COUNT(*) FILTER (WHERE is_win)::NUMERIC / NULLIF(COUNT(*), 0)) * 100, 1) AS win_rate
    FROM exact_matches
    GROUP BY COALESCE(attempt_debuff, 0)
    ORDER BY debuff_level
  ),
  summary AS (
    SELECT
      COUNT(*) AS total_uses,
      COUNT(*) FILTER (WHERE is_win) AS wins,
      COUNT(*) FILTER (WHERE NOT is_win) AS losses,
      ROUND((COUNT(*) FILTER (WHERE is_win)::NUMERIC / NULLIF(COUNT(*), 0)) * 100, 1) AS win_rate,
      ROUND(AVG(score_earned), 1) AS avg_score
    FROM exact_matches
  )
  SELECT
    s.total_uses,
    s.wins,
    s.losses,
    s.win_rate,
    s.avg_score,
    COALESCE((SELECT jsonb_agg(jsonb_build_object('zoneName', zone_type, 'uses', uses, 'winRate', zone_stats.win_rate)) FROM zone_stats), '[]'::jsonb) AS zone_breakdown,
    COALESCE((SELECT jsonb_agg(jsonb_build_object('debuffLevel', 'Buff ' || debuff_level, 'uses', uses, 'winRate', buff_stats.win_rate)) FROM buff_stats), '[]'::jsonb) AS buff_breakdown,
    '[]'::jsonb AS matchup_summary
  FROM summary s;
END;
$$;

ALTER FUNCTION public.analyze_team_composition(p_guild_code text, p_hero_keys text[], p_season_count integer) OWNER TO postgres;

CREATE FUNCTION public.append_player_identity_revocation(p_attestation_id uuid, p_reason text, p_actor_user_id uuid, p_source text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_actor_role text := coalesce(
    nullif(nullif(current_setting('role', true), ''), 'none'),
    session_user
  );
BEGIN
  IF p_attestation_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF p_reason NOT IN (
    'account_delete', 'gdpr_erasure', 'admin_unlink',
    'player_id_correction', 'mapping_delete', 'guild_delete',
    'support_reverify', 'authority_recovery', 'roster_deactivation'
  ) THEN
    RAISE EXCEPTION 'Unsupported player-identity revocation reason'
      USING ERRCODE = '22023';
  END IF;
  IF p_source IS NULL OR length(btrim(p_source)) < 3 OR length(p_source) > 120 THEN
    RAISE EXCEPTION 'A bounded revocation source is required'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.player_identity_attestation_revocations (
    attestation_id, reason, actor_user_id, actor_role, source
  ) VALUES (
    p_attestation_id, p_reason, p_actor_user_id, v_actor_role, btrim(p_source)
  )
  ON CONFLICT (attestation_id) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
    FROM public.player_identity_attestation_revocations
    WHERE attestation_id = p_attestation_id;
  END IF;
  RETURN v_id;
END
$$;

