CREATE FUNCTION public.apply_pending_patreon_grant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
DECLARE
    v_pending record;
BEGIN
    SELECT * INTO v_pending
    FROM pending_patreon_grants
    WHERE email = NEW.email;

    IF FOUND THEN
        INSERT INTO feature_access_grants (user_id, access_level, notes)
        VALUES (
            NEW.id,
            v_pending.access_level,
            'Patreon pledge: $' || (v_pending.amount_cents / 100.0)::text || '/month (applied on registration)'
        )
        ON CONFLICT (user_id, access_level) DO UPDATE SET
            notes = EXCLUDED.notes,
            granted_at = now();

        IF v_pending.patreon_user_id IS NOT NULL THEN
            UPDATE player_mapping
            SET patreon_user_id = v_pending.patreon_user_id
            WHERE user_id = NEW.id AND is_current = true;
        END IF;

        DELETE FROM pending_patreon_grants WHERE id = v_pending.id;
    END IF;

    RETURN NEW;
END;
$_$;

ALTER FUNCTION public.apply_pending_patreon_grant() OWNER TO postgres;

CREATE FUNCTION public.apply_pending_supporter_grants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
DECLARE
    v_patreon record;
    v_bmc record;
BEGIN
    -- Check for pending Patreon grant
    SELECT * INTO v_patreon
    FROM pending_patreon_grants
    WHERE email = NEW.email;

    IF FOUND THEN
        INSERT INTO feature_access_grants (user_id, access_level, notes)
        VALUES (
            NEW.id,
            v_patreon.access_level,
            'Patreon pledge: $' || (v_patreon.amount_cents / 100.0)::text || '/month (applied on registration)'
        )
        ON CONFLICT (user_id, access_level) DO UPDATE SET
            notes = EXCLUDED.notes,
            granted_at = now();

        IF v_patreon.patreon_user_id IS NOT NULL THEN
            UPDATE player_mapping
            SET patreon_user_id = v_patreon.patreon_user_id
            WHERE user_id = NEW.id AND is_current = true;
        END IF;

        DELETE FROM pending_patreon_grants WHERE id = v_patreon.id;
    END IF;

    -- Check for pending BMC grant
    SELECT * INTO v_bmc
    FROM pending_bmc_grants
    WHERE email = NEW.email;

    IF FOUND THEN
        INSERT INTO feature_access_grants (user_id, access_level, notes)
        VALUES (
            NEW.id,
            v_bmc.access_level,
            'Buy Me a Coffee: ' || COALESCE(v_bmc.membership_level, 'Member') || ' (applied on registration)'
        )
        ON CONFLICT (user_id, access_level) DO UPDATE SET
            notes = EXCLUDED.notes,
            granted_at = now();

        DELETE FROM pending_bmc_grants WHERE id = v_bmc.id;
    END IF;

    RETURN NEW;
END;
$_$;

