CREATE FUNCTION public.assert_matview_health() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record;
  v_unhealthy integer := 0;
begin
  for r in select * from public.matview_refresh_health() where is_unhealthy loop
    v_unhealthy := v_unhealthy + 1;
    raise warning 'matview-health: % is UNHEALTHY — %', r.signal, r.detail;
  end loop;
  return v_unhealthy;
end;
$$;

