CREATE FUNCTION public.audit_war_visibility_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- INSERT branch (db review 2026-07-16): a row born with a non-default
  -- visibility is itself a consent event — without this, a service upsert
  -- that resolves to INSERT could establish 'public' with no audit row.
  IF TG_OP = 'INSERT' THEN
    IF NEW.war_visibility IS DISTINCT FROM 'guild' THEN
      INSERT INTO public.guild_war_visibility_audit
        (guild_code, old_visibility, new_visibility, actor, actor_db_role)
      VALUES (
        NEW.guild_code,
        NULL,
        NEW.war_visibility,
        auth.uid(),
        NULLIF(current_setting('role', true), '')
      );
    END IF;
  ELSIF NEW.war_visibility IS DISTINCT FROM OLD.war_visibility THEN
    INSERT INTO public.guild_war_visibility_audit
      (guild_code, old_visibility, new_visibility, actor, actor_db_role)
    VALUES (
      NEW.guild_code,
      OLD.war_visibility,
      NEW.war_visibility,
      auth.uid(),
      NULLIF(current_setting('role', true), '')
    );
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.audit_war_visibility_change() OWNER TO postgres;

CREATE FUNCTION public.auto_claim_on_login() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_player_record player_mapping%ROWTYPE;
  v_claim_result JSON;
BEGIN
  -- Only run for new sessions (INSERT)
  IF TG_OP != 'INSERT' THEN
    RETURN NEW;
  END IF;

  -- Check if user has any player_mapping
  SELECT * INTO v_player_record
  FROM player_mapping
  WHERE user_id = NEW.user_id
  LIMIT 1;

  IF NOT FOUND THEN
    -- User has no player mapping, try to auto-claim based on email
    -- This is a safety net for users who somehow got created without claiming
    RAISE NOTICE 'User % has no player mapping, attempting auto-claim', NEW.user_id;

    -- You could add logic here to match by email or other criteria
    -- For now, just log it
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION public.auto_claim_on_login() OWNER TO postgres;

CREATE FUNCTION public.auto_complete_onboarding_on_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- If last_successful_sync is being set and onboarding isn't completed
    IF NEW.last_successful_sync IS NOT NULL
       AND OLD.last_successful_sync IS NULL
       AND (NEW.onboarding_completed = false OR NEW.onboarding_completed IS NULL)
    THEN
        NEW.onboarding_completed := true;
        NEW.onboarding_completed_at := COALESCE(NEW.onboarding_completed_at, NOW());
        NEW.registration_status := 'completed';
        NEW.registration_completed_at := COALESCE(NEW.registration_completed_at, NOW());

        -- Log this auto-completion
        INSERT INTO system_logs (log_type, message, metadata)
        VALUES (
            'auto_complete_onboarding',
            format('Auto-completed onboarding for guild %s on first successful sync', NEW.guild_code),
            jsonb_build_object(
                'guild_code', NEW.guild_code,
                'first_sync_at', NEW.last_successful_sync,
                'auto_completed_at', NOW()
            )
        );
    END IF;

    RETURN NEW;
END;
$$;

ALTER FUNCTION public.auto_complete_onboarding_on_sync() OWNER TO postgres;

CREATE FUNCTION public.backfill_boss_mapping_unit_ids() RETURNS TABLE(updated_count integer, boss_types_updated text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_updated int := 0;
  v_boss_types text[] := ARRAY[]::text[];
BEGIN
  UPDATE boss_mapping bm
  SET unit_id = subq.unit_id
  FROM (
    SELECT DISTINCT ON (e."Name", e."encounterId")
      e."Name" as boss_type,
      e."encounterId"::int as encounter_index,
      e."unitId" as unit_id
    FROM "EOT_GR_data" e
    WHERE e."unitId" IS NOT NULL
      AND e."damageType" = 'Battle'
    ORDER BY e."Name", e."encounterId", e."Season" DESC
  ) subq
  WHERE bm.boss_type = subq.boss_type
    AND bm.encounter_index = subq.encounter_index
    AND bm.unit_id IS NULL
    AND subq.unit_id IS NOT NULL;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  SELECT array_agg(DISTINCT boss_type) INTO v_boss_types
  FROM boss_mapping
  WHERE unit_id IS NOT NULL;

  RETURN QUERY SELECT v_updated, v_boss_types;
END;
$$;

ALTER FUNCTION public.backfill_boss_mapping_unit_ids() OWNER TO postgres;

CREATE FUNCTION public.batch_categorize_teams(p_teams jsonb) RETURNS TABLE(team_id text, category text, hero_count integer)
    LANGUAGE plpgsql STABLE
    AS $$
    BEGIN
      RETURN QUERY
      SELECT
        (team->>'id')::text as team_id,
        CASE
          WHEN jsonb_array_length(team->'heroes') = 0 THEN 'Unknown'
          WHEN jsonb_array_length(team->'heroes') <= 3 THEN 'Partial'
          WHEN jsonb_array_length(team->'heroes') = 5 THEN 'Full'
          ELSE 'Mixed'
        END as category,
        jsonb_array_length(team->'heroes')::integer as hero_count
      FROM jsonb_array_elements(p_teams) as team;
    END;
    $$;

ALTER FUNCTION public.batch_categorize_teams(p_teams jsonb) OWNER TO postgres;

CREATE FUNCTION public.batch_repair_unmapped_players(p_guild text, p_user_mappings jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    mapping RECORD;
    total_updated INTEGER := 0;
    current_updated INTEGER;
BEGIN
    FOR mapping IN SELECT * FROM jsonb_to_recordset(p_user_mappings)
                   AS x(user_id TEXT, new_display_name TEXT)
    LOOP
        UPDATE EOT_GR_data
        SET displayName = mapping.new_display_name,
            timestamp = NOW()
        WHERE Guild = p_guild
          AND userId = mapping.user_id;

        GET DIAGNOSTICS current_updated = ROW_COUNT;
        total_updated := total_updated + current_updated;
    END LOOP;

    RETURN total_updated;
END;
$$;

ALTER FUNCTION public.batch_repair_unmapped_players(p_guild text, p_user_mappings jsonb) OWNER TO postgres;

CREATE FUNCTION public.block_player_identity_subject_authority(p_user_id uuid, p_reason text, p_source text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_blocked_at timestamptz;
BEGIN
  IF p_user_id IS NULL
    OR p_reason NOT IN ('account_delete', 'gdpr_erasure', 'auth_delete')
    OR p_source IS NULL OR length(btrim(p_source)) < 3
    OR length(p_source) > 120
  THEN
    RAISE EXCEPTION 'Invalid subject authority block request'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(6208, hashtext(p_user_id::text));
  INSERT INTO public.player_identity_subject_authority_blocks (
    subject_user_id, reason, source
  ) VALUES (p_user_id, p_reason, btrim(p_source))
  ON CONFLICT (subject_user_id) DO NOTHING
  RETURNING blocked_at INTO v_blocked_at;
  IF v_blocked_at IS NULL THEN
    SELECT block.blocked_at INTO STRICT v_blocked_at
    FROM public.player_identity_subject_authority_blocks AS block
    WHERE block.subject_user_id = p_user_id;
  END IF;
  RETURN v_blocked_at;
END
$$;

ALTER FUNCTION public.block_player_identity_subject_authority(p_user_id uuid, p_reason text, p_source text) OWNER TO postgres;

