CREATE FUNCTION public.bulk_insert_battle_data(p_records jsonb, p_guild_code text DEFAULT NULL::text) RETURNS TABLE(inserted_count integer, duplicate_count integer, error_count integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_inserted_count integer := 0;
    v_duplicate_count integer := 0;
    v_error_count integer := 0;
    v_batch_size integer := 1000;
    v_offset integer := 0;
    v_total_records integer;
    v_batch jsonb;
BEGIN
    -- Get total record count
    v_total_records := jsonb_array_length(p_records);

    -- Process in batches to manage memory
    WHILE v_offset < v_total_records LOOP
        -- Extract batch
        SELECT jsonb_agg(elem)
        INTO v_batch
        FROM (
            SELECT jsonb_array_elements(p_records) AS elem
            LIMIT v_batch_size
            OFFSET v_offset
        ) t;

        -- Bulk insert with conflict handling
        WITH inserted AS (
            INSERT INTO "EOT_GR_data"
            SELECT * FROM jsonb_populate_recordset(null::"EOT_GR_data", v_batch)
            ON CONFLICT ("Guild", "Season", "userId", "encounterId", "startedOn", "completedOn", "damageDealt", "damageType")
            DO NOTHING
            RETURNING 1
        )
        SELECT COUNT(*) INTO v_inserted_count FROM inserted;

        -- Count duplicates (total - inserted)
        v_duplicate_count := v_duplicate_count + (jsonb_array_length(v_batch) - v_inserted_count);

        -- Move to next batch
        v_offset := v_offset + v_batch_size;
    END LOOP;

    -- Return statistics
    RETURN QUERY SELECT v_inserted_count, v_duplicate_count, v_error_count;

EXCEPTION
    WHEN OTHERS THEN
        -- Log error and return counts
        RAISE NOTICE 'Bulk insert error: %', SQLERRM;
        v_error_count := v_total_records - v_inserted_count;
        RETURN QUERY SELECT v_inserted_count, v_duplicate_count, v_error_count;
END;
$$;

ALTER FUNCTION public.bulk_insert_battle_data(p_records jsonb, p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.bulk_upsert_player_mappings(p_mappings jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_upserted_count integer;
BEGIN
    -- First, mark all existing mappings as not current for players in the batch
    WITH player_ids AS (
        SELECT DISTINCT (value->>'player_id')::text as player_id
        FROM jsonb_array_elements(p_mappings)
    )
    UPDATE player_mapping
    SET is_current = false
    WHERE player_id IN (SELECT player_id FROM player_ids);

    -- Now insert/update the new mappings
    INSERT INTO player_mapping
    SELECT
        (value->>'player_id')::text,
        (value->>'guild_code')::text,
        (value->>'display_name')::text,
        (value->>'api_key_encrypted')::text,
        (value->>'user_id')::uuid,
        true, -- is_current
        COALESCE((value->>'joined_at')::timestamp, NOW()),
        NOW(),
        (value->>'tacticus_user_id')::text,
        (value->>'tacticus_api_key_encrypted')::text
    FROM jsonb_array_elements(p_mappings)
    ON CONFLICT (player_id, guild_code)
    DO UPDATE SET
        display_name = EXCLUDED.display_name,
        is_current = true,
        updated_at = NOW();

    GET DIAGNOSTICS v_upserted_count = ROW_COUNT;
    RETURN v_upserted_count;
END;
$$;

ALTER FUNCTION public.bulk_upsert_player_mappings(p_mappings jsonb) OWNER TO postgres;

CREATE FUNCTION public.calc_boss_performance_pct(p_non_sweep_damage numeric, p_non_sweep_count numeric, p_sweep_damages numeric[], p_reference_avg numeric, p_gate_avg numeric DEFAULT NULL::numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN p_reference_avg > 0 THEN
    ((
      (COALESCE(p_non_sweep_damage, 0)
        + COALESCE(qualifying_sweep_sum(p_sweep_damages, GREATEST(p_gate_avg, p_reference_avg)), 0))
      / NULLIF(
          COALESCE(p_non_sweep_count, 0)
          + COALESCE(qualifying_sweep_count(p_sweep_damages, GREATEST(p_gate_avg, p_reference_avg)), 0),
        0)
      / p_reference_avg
    ) - 1) * 100
  ELSE NULL END
$$;

ALTER FUNCTION public.calc_boss_performance_pct(p_non_sweep_damage numeric, p_non_sweep_count numeric, p_sweep_damages numeric[], p_reference_avg numeric, p_gate_avg numeric) OWNER TO postgres;

CREATE FUNCTION public.calc_effective_battle_count(p_non_sweep_count numeric, p_sweep_damages numeric[], p_reference_avg numeric, p_gate_avg numeric DEFAULT NULL::numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN p_reference_avg > 0 THEN
    COALESCE(p_non_sweep_count, 0)
      + COALESCE(qualifying_sweep_count(p_sweep_damages, GREATEST(p_gate_avg, p_reference_avg)), 0)
  ELSE 0 END
$$;

ALTER FUNCTION public.calc_effective_battle_count(p_non_sweep_count numeric, p_sweep_damages numeric[], p_reference_avg numeric, p_gate_avg numeric) OWNER TO postgres;

CREATE FUNCTION public.calculate_player_reliability(p_user_id text, p_guild_code text, p_season text, p_cluster_code text DEFAULT NULL::text) RETURNS TABLE(reliability_score numeric, consistency_rating text, avg_performance numeric, performance_stddev numeric, coefficient_of_variation numeric, battles_analyzed integer, performance_range_min numeric, performance_range_max numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_performance_data NUMERIC[];
  v_avg_performance NUMERIC;
  v_stddev NUMERIC;
  v_cv NUMERIC;
  v_reliability NUMERIC;
  v_battles_count INTEGER;
  v_min_perf NUMERIC;
  v_max_perf NUMERIC;
  v_consistency_text TEXT;
BEGIN
  -- Collect performance ratios for regular battles only (exclude bombs and sweeps)
  WITH battle_performance AS (
    SELECT
      d."userId",
      d."Name" as boss_name,
      d."damageDealt",
      d."remainingHp",
      d."maxHp",
      d."damageType",
      -- Each hit over THIS PLAYER'S OWN average on that boss. The CTE is
      -- already filtered to p_user_id above, so this window sees a single
      -- player: it is a self-consistency ratio, NOT a comparison against
      -- peers. (Proof: avg_performance always comes back as exactly 1.0.)
      d."damageDealt"::NUMERIC / NULLIF(
        AVG(d."damageDealt") OVER (
          PARTITION BY d."Name", d."Guild"
        ), 0
      ) as performance_ratio,
      -- How many times THIS PLAYER hit this boss — same one-player window.
      COUNT(*) OVER (PARTITION BY d."Name", d."Guild") as boss_hit_count
    FROM "EOT_GR_data" d
    WHERE d."userId" = p_user_id
      AND d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND (p_cluster_code IS NULL OR d."cluster_code" = p_cluster_code)
      -- EXCLUDE BOMBS
      AND (d."damageType" IS NULL OR d."damageType" NOT IN ('Bomb', 'Bombardment'))
      -- EXCLUDE SWEEPS (killing blows with damage less than max HP)
      AND NOT (d."remainingHp" = 0 AND d."maxHp" > 0 AND d."damageDealt" < d."maxHp")
      -- Exclude crashes (zero damage)
      AND d."damageDealt" > 0
      -- Only include regular battle damage
      AND (d."damageType" IS NULL OR d."damageType" IN ('Battle', 'Normal', 'Standard'))
  ),
  -- Keep only bosses this player hit more than once. Required, not optional:
  -- a boss hit exactly once yields a ratio of exactly 1.0, which would fake
  -- perfect consistency.
  filtered_performance AS (
    SELECT
      performance_ratio
    FROM battle_performance
    WHERE performance_ratio IS NOT NULL
      -- 2+ attacks by this player on the same boss
      AND boss_hit_count > 1
  ),
  performance_array AS (
    SELECT
      array_agg(performance_ratio ORDER BY performance_ratio) as perf_array,
      COUNT(*)::INTEGER as battle_count,
      AVG(performance_ratio) as avg_ratio,
      STDDEV_POP(performance_ratio) as stddev_ratio,
      MIN(performance_ratio) as min_ratio,
      MAX(performance_ratio) as max_ratio
    FROM filtered_performance
  )
  SELECT
    perf_array,
    battle_count,
    avg_ratio,
    stddev_ratio,
    min_ratio,
    max_ratio
  INTO
    v_performance_data,
    v_battles_count,
    v_avg_performance,
    v_stddev,
    v_min_perf,
    v_max_perf
  FROM performance_array;

  -- Not enough repeat attacks to measure variance. The returned message says
  -- 'attacks on one boss', not 'battles': measured on season 106, 443 of the
  -- 709 players who land here already had 2+ battles (the highest had 10), so
  -- the old 'Min 2 battles' wording read as a bug to every one of them.
  IF v_battles_count IS NULL OR v_battles_count < 2 THEN
    -- Try to provide partial data even with insufficient battles
    SELECT
      COUNT(*)::INTEGER,
      AVG("damageDealt")::NUMERIC
    INTO
      v_battles_count,
      v_avg_performance
    FROM "EOT_GR_data"
    WHERE "userId" = p_user_id
      AND "Guild" = p_guild_code
      AND "Season" = p_season
      AND (p_cluster_code IS NULL OR "cluster_code" = p_cluster_code)
      -- Exclude bombs and sweeps
      AND ("damageType" IS NULL OR "damageType" NOT IN ('Bomb', 'Bombardment'))
      AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp")
      AND "damageDealt" > 0;

    RETURN QUERY
    SELECT
      NULL::NUMERIC as reliability_score,
      'Insufficient Data (needs 2+ attacks on one boss)'::TEXT as consistency_rating,
      v_avg_performance,
      NULL::NUMERIC as performance_stddev,
      NULL::NUMERIC as coefficient_of_variation,
      v_battles_count,
      NULL::NUMERIC as performance_range_min,
      NULL::NUMERIC as performance_range_max;
    RETURN;
  END IF;

  -- Calculate coefficient of variation
  IF v_avg_performance > 0 THEN
    v_cv := (v_stddev / v_avg_performance) * 100;
  ELSE
    v_cv := 100; -- Max CV if average is 0
  END IF;

  -- Calculate reliability score (0-100 scale)
  -- Lower CV = Higher reliability
  v_reliability := GREATEST(0, 100 - v_cv);

  -- Determine consistency rating
  v_consistency_text := CASE
    WHEN v_reliability >= 90 THEN 'Elite Consistency'
    WHEN v_reliability >= 80 THEN 'Very Consistent'
    WHEN v_reliability >= 70 THEN 'Consistent'
    WHEN v_reliability >= 60 THEN 'Moderately Consistent'
    WHEN v_reliability >= 50 THEN 'Average Consistency'
    WHEN v_reliability >= 40 THEN 'Variable'
    WHEN v_reliability >= 30 THEN 'Highly Variable'
    WHEN v_reliability >= 20 THEN 'Very Inconsistent'
    ELSE 'Extremely Variable'
  END;

  -- Return results
  RETURN QUERY
  SELECT
    v_reliability,
    v_consistency_text,
    v_avg_performance,
    v_stddev,
    v_cv,
    v_battles_count,
    v_min_perf,
    v_max_perf;
END;
$$;

ALTER FUNCTION public.calculate_player_reliability(p_user_id text, p_guild_code text, p_season text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.calculate_player_tokens(p_player_name text, p_guild_code text, p_season text DEFAULT NULL::text) RETURNS TABLE(player_name text, guild_code text, tokens_available integer, battles_today integer, last_battle_time timestamp with time zone, time_until_next_token interval, is_capped boolean)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_season TEXT;
    v_battle_count INT;
    v_max_tokens INT := 3;
    v_initial_tokens INT := 2;
    v_twelve_hours_secs BIGINT := 12 * 60 * 60;
    v_now_secs BIGINT;
    v_token_count INT;
    v_refresh_time BIGINT;
    v_anchor_ts BIGINT := NULL;
    v_n_recharged INT;
    v_time_since_refresh BIGINT;
    v_time_until_next INTERVAL := NULL;
    v_last_battle TIMESTAMPTZ;
    v_battle RECORD;
    v_battle_ts BIGINT;
    v_prev_count INT;
BEGIN
    v_now_secs := EXTRACT(EPOCH FROM NOW())::BIGINT;

    IF p_season IS NULL THEN
        -- LEX-FIX 2026-05-07: was MAX("Season") (TEXT lex max -> '99' at S100).
        SELECT MAX(season_num)::text INTO v_season
        FROM "EOT_GR_data"
        WHERE "Guild" = p_guild_code;
    ELSE
        v_season := p_season;
    END IF;

    SELECT COUNT(DISTINCT "startedOn")
    INTO v_battle_count
    FROM "EOT_GR_data"
    WHERE "displayName" = p_player_name
    AND "Guild" = p_guild_code
    AND "Season" = v_season
    AND "damageType" = 'Battle';

    -- WI-2640 Phase 2 season-window anchor (mirrors 20260716160000).
    IF v_season ~ '^\d+$' THEN
        SELECT EXTRACT(EPOCH FROM sc.starts_at)::BIGINT INTO v_anchor_ts
        FROM public.season_calendar sc
        WHERE sc.season_id = (v_season::INT - 1);

        IF v_anchor_ts IS NULL THEN
            SELECT EXTRACT(EPOCH FROM sc.starts_at)::BIGINT INTO v_anchor_ts
            FROM public.season_calendar sc
            WHERE sc.season_id = v_season::INT;
        END IF;

        IF v_anchor_ts IS NOT NULL AND v_anchor_ts > v_now_secs THEN
            v_anchor_ts := NULL;
        END IF;
    END IF;

    v_token_count := v_initial_tokens;
    v_refresh_time := NULL;

    FOR v_battle IN
        SELECT DISTINCT "startedOn"::TIMESTAMPTZ as battle_time
        FROM "EOT_GR_data"
        WHERE "displayName" = p_player_name
        AND "Guild" = p_guild_code
        AND "damageType" = 'Battle'
        AND "startedOn" IS NOT NULL
        AND "Season" IN (v_season, (v_season::INT - 1)::TEXT)
        ORDER BY "startedOn"::TIMESTAMPTZ ASC
    LOOP
        v_battle_ts := EXTRACT(EPOCH FROM v_battle.battle_time)::BIGINT;
        v_last_battle := v_battle.battle_time;

        IF v_refresh_time IS NULL THEN
            v_refresh_time := LEAST(COALESCE(v_anchor_ts, v_battle_ts), v_battle_ts);
        END IF;

        IF v_token_count < v_max_tokens THEN
            v_n_recharged := FLOOR((v_battle_ts - v_refresh_time)::NUMERIC / v_twelve_hours_secs);

            IF v_n_recharged + v_token_count >= v_max_tokens THEN
                v_token_count := v_max_tokens;
                v_refresh_time := v_battle_ts;
            ELSE
                v_token_count := v_token_count + v_n_recharged;
                v_refresh_time := v_refresh_time + (v_n_recharged * v_twelve_hours_secs);
            END IF;
        END IF;

        v_prev_count := v_token_count;
        v_token_count := v_token_count - 1;

        IF v_prev_count = v_max_tokens THEN
            v_refresh_time := v_battle_ts;
        END IF;

        IF v_token_count <= 0 THEN
            v_token_count := 0;
        END IF;
    END LOOP;

    IF v_refresh_time IS NULL AND v_anchor_ts IS NOT NULL THEN
        v_refresh_time := v_anchor_ts;
    END IF;

    IF v_token_count < v_max_tokens AND v_refresh_time IS NOT NULL THEN
        v_n_recharged := FLOOR((v_now_secs - v_refresh_time)::NUMERIC / v_twelve_hours_secs);

        IF v_n_recharged + v_token_count >= v_max_tokens THEN
            v_token_count := v_max_tokens;
            v_refresh_time := v_now_secs;
        ELSE
            v_token_count := v_token_count + v_n_recharged;
            v_refresh_time := v_refresh_time + (v_n_recharged * v_twelve_hours_secs);
        END IF;
    END IF;

    IF v_token_count < v_max_tokens AND v_refresh_time IS NOT NULL THEN
        v_time_since_refresh := v_now_secs - v_refresh_time;
        v_time_until_next := make_interval(secs => (v_twelve_hours_secs - (v_time_since_refresh % v_twelve_hours_secs)));
    END IF;

    v_token_count := LEAST(v_max_tokens, GREATEST(0, v_token_count));

    RETURN QUERY
    SELECT
        p_player_name,
        p_guild_code,
        v_token_count,
        v_battle_count,
        v_last_battle,
        v_time_until_next,
        v_token_count = v_max_tokens;
END;
$_$;

ALTER FUNCTION public.calculate_player_tokens(p_player_name text, p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.calculate_player_tokens_by_user(p_user_id text, p_guild_code text, p_season text DEFAULT NULL::text) RETURNS TABLE(player_user_id text, guild_code text, tokens_available integer, battles_today integer, last_battle_time timestamp with time zone, time_until_next_token interval, is_capped boolean)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_season TEXT;
    v_battle_count INT;
    v_max_tokens INT := 3;
    v_initial_tokens INT := 2;
    v_twelve_hours_secs BIGINT := 12 * 60 * 60;
    v_now_secs BIGINT;
    v_token_count INT;
    v_refresh_time BIGINT;
    v_anchor_ts BIGINT := NULL;
    v_n_recharged INT;
    v_time_since_refresh BIGINT;
    v_time_until_next INTERVAL := NULL;
    v_last_battle TIMESTAMPTZ;
    v_battle RECORD;
    v_battle_ts BIGINT;
    v_prev_count INT;
BEGIN
    v_now_secs := EXTRACT(EPOCH FROM NOW())::BIGINT;

    IF p_season IS NULL THEN
        SELECT MAX(season_num)::text INTO v_season
        FROM "EOT_GR_data"
        WHERE "Guild" = p_guild_code;
    ELSE
        v_season := p_season;
    END IF;

    SELECT COUNT(DISTINCT "startedOn")
    INTO v_battle_count
    FROM "EOT_GR_data"
    WHERE "userId" = p_user_id
    AND "Guild" = p_guild_code
    AND "Season" = v_season
    AND "damageType" = 'Battle';

    -- WI-2640 Phase 2 season-window anchor: earliest season in the replay
    -- window (v_season - 1 when the calendar knows it, else v_season).
    -- NULL (no calendar rows) degrades to the legacy first-battle anchor.
    IF v_season ~ '^\d+$' THEN
        SELECT EXTRACT(EPOCH FROM sc.starts_at)::BIGINT INTO v_anchor_ts
        FROM public.season_calendar sc
        WHERE sc.season_id = (v_season::INT - 1);

        IF v_anchor_ts IS NULL THEN
            SELECT EXTRACT(EPOCH FROM sc.starts_at)::BIGINT INTO v_anchor_ts
            FROM public.season_calendar sc
            WHERE sc.season_id = v_season::INT;
        END IF;

        -- A future-dated calendar row must not anchor the replay: regen
        -- cannot run over a negative interval (mirrors the TS-side
        -- evaluateToken clamp).
        IF v_anchor_ts IS NOT NULL AND v_anchor_ts > v_now_secs THEN
            v_anchor_ts := NULL;
        END IF;
    END IF;

    v_token_count := v_initial_tokens;
    v_refresh_time := NULL;

    FOR v_battle IN
        SELECT DISTINCT "startedOn"::TIMESTAMPTZ as battle_time
        FROM "EOT_GR_data"
        WHERE "userId" = p_user_id
        AND "Guild" = p_guild_code
        AND "damageType" = 'Battle'
        AND "startedOn" IS NOT NULL
        AND "Season" IN (v_season, (v_season::INT - 1)::TEXT)
        ORDER BY "startedOn"::TIMESTAMPTZ ASC
    LOOP
        v_battle_ts := EXTRACT(EPOCH FROM v_battle.battle_time)::BIGINT;
        v_last_battle := v_battle.battle_time;

        IF v_refresh_time IS NULL THEN
            v_refresh_time := LEAST(COALESCE(v_anchor_ts, v_battle_ts), v_battle_ts);
        END IF;

        IF v_token_count < v_max_tokens THEN
            v_n_recharged := FLOOR((v_battle_ts - v_refresh_time)::NUMERIC / v_twelve_hours_secs);

            IF v_n_recharged + v_token_count >= v_max_tokens THEN
                v_token_count := v_max_tokens;
                v_refresh_time := v_battle_ts;
            ELSE
                v_token_count := v_token_count + v_n_recharged;
                v_refresh_time := v_refresh_time + (v_n_recharged * v_twelve_hours_secs);
            END IF;
        END IF;

        v_prev_count := v_token_count;
        v_token_count := v_token_count - 1;

        IF v_prev_count = v_max_tokens THEN
            v_refresh_time := v_battle_ts;
        END IF;

        IF v_token_count <= 0 THEN
            v_token_count := 0;
        END IF;
    END LOOP;

    -- No battles at all: regen the anchor state to now (idle players sit at
    -- the cap, not at a frozen 2/3 — WI-2570 follow-up 3 kept them pinned
    -- only in the CALCULATED fallback; the anchor makes the replay itself
    -- correct for them).
    IF v_refresh_time IS NULL AND v_anchor_ts IS NOT NULL THEN
        v_refresh_time := v_anchor_ts;
    END IF;

    IF v_token_count < v_max_tokens AND v_refresh_time IS NOT NULL THEN
        v_n_recharged := FLOOR((v_now_secs - v_refresh_time)::NUMERIC / v_twelve_hours_secs);

        IF v_n_recharged + v_token_count >= v_max_tokens THEN
            v_token_count := v_max_tokens;
            v_refresh_time := v_now_secs;
        ELSE
            v_token_count := v_token_count + v_n_recharged;
            v_refresh_time := v_refresh_time + (v_n_recharged * v_twelve_hours_secs);
        END IF;
    END IF;

    IF v_token_count < v_max_tokens AND v_refresh_time IS NOT NULL THEN
        v_time_since_refresh := v_now_secs - v_refresh_time;
        v_time_until_next := make_interval(secs => (v_twelve_hours_secs - (v_time_since_refresh % v_twelve_hours_secs)));
    END IF;

    v_token_count := LEAST(v_max_tokens, GREATEST(0, v_token_count));

    RETURN QUERY
    SELECT
        p_user_id,
        p_guild_code,
        v_token_count,
        v_battle_count,
        v_last_battle,
        v_time_until_next,
        v_token_count = v_max_tokens;
END;
$_$;

ALTER FUNCTION public.calculate_player_tokens_by_user(p_user_id text, p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.calculate_votlw_for_completed_seasons() RETURNS TABLE(seasons_processed integer[], message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
DECLARE
    current_season INTEGER;
    last_votlw_season INTEGER;
    seasons_to_process INTEGER[];
    season_num INTEGER;
BEGIN
    -- Get current season
    SELECT MAX("Season"::integer) INTO current_season
    FROM "EOT_GR_data"
    WHERE "Season" ~ '^\d+$'
        AND "Guild" NOT IN ('TEST', 'EOT', 'TBD');

    -- Get last VOTLW season
    SELECT COALESCE(MAX(season::integer), 0) INTO last_votlw_season
    FROM votlw_winners
    WHERE season ~ '^\d+$';

    -- Build array of seasons to process (completed seasons only)
    SELECT ARRAY_AGG(s) INTO seasons_to_process
    FROM generate_series(last_votlw_season + 1, current_season - 1) s;

    IF seasons_to_process IS NULL OR array_length(seasons_to_process, 1) = 0 THEN
        RETURN QUERY
        SELECT
            ARRAY[]::INTEGER[] as seasons_processed,
            'No seasons need processing. VOTLW data is up to date.' as message;
        RETURN;
    END IF;

    -- Process each season
    FOREACH season_num IN ARRAY seasons_to_process
    LOOP
        -- Similar calculation logic as above, but wrapped in a function
        -- (Implementation would be the same as the DO block above)
        RAISE NOTICE 'Processing season %', season_num;
    END LOOP;

    RETURN QUERY
    SELECT
        seasons_to_process as seasons_processed,
        format('Processed %s seasons: %s',
            array_length(seasons_to_process, 1),
            array_to_string(seasons_to_process, ', ')
        ) as message;
END;
$_$;

ALTER FUNCTION public.calculate_votlw_for_completed_seasons() OWNER TO postgres;

CREATE FUNCTION public.calculate_votlw_for_season(p_season text DEFAULT NULL::text, p_guild text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  kong_url TEXT := COALESCE(NULLIF(current_setting('app.settings.supabase_internal_url', true), ''), 'http://supabase-kong:8000');
  service_key TEXT;
  v_result BIGINT;
BEGIN
  service_key := current_setting('app.settings.service_role_key', true);

  IF service_key IS NULL THEN
    RAISE EXCEPTION 'Service role key not configured. Set via: ALTER DATABASE postgres SET app.settings.service_role_key = ''your-key'';';
  END IF;

  -- Call local Edge Function via Kong gateway
  SELECT net.http_post(
    url := kong_url || '/functions/v1/calculate-votlw',
    headers := jsonb_build_object(
      'Authorization', 'Bearer ' || service_key,
      'Content-Type', 'application/json'
    ),
    body := jsonb_build_object(
      'season', p_season,
      'guild', p_guild,
      'source', 'manual'
    )::text,
    timeout_milliseconds := 60000
  ) INTO v_result;

  RETURN jsonb_build_object(
    'status', 'triggered',
    'request_id', v_result,
    'season', p_season,
    'guild', p_guild
  );
END;
$$;

ALTER FUNCTION public.calculate_votlw_for_season(p_season text, p_guild text) OWNER TO postgres;

CREATE FUNCTION public.calculate_votlw_if_scheduled() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  kong_url TEXT := COALESCE(NULLIF(current_setting('app.settings.supabase_internal_url', true), ''), 'http://supabase-kong:8000');
  service_key TEXT;
BEGIN
  -- Check if today is the right day (14 days from start date)
  IF EXTRACT(EPOCH FROM (CURRENT_DATE - DATE '2025-08-12'))::INTEGER % (14 * 86400) = 0 THEN
    service_key := current_setting('app.settings.service_role_key', true);

    IF service_key IS NULL THEN
      RAISE WARNING 'Service role key not configured for VOTLW calculation';
      RETURN;
    END IF;

    PERFORM net.http_post(
      url := kong_url || '/functions/v1/calculate-votlw',
      headers := jsonb_build_object(
        'Authorization', 'Bearer ' || service_key,
        'Content-Type', 'application/json'
      ),
      body := '{}'::text
    );

    RAISE NOTICE 'VOTLW calculation triggered at %', now();
  END IF;
END;
$$;

ALTER FUNCTION public.calculate_votlw_if_scheduled() OWNER TO postgres;

CREATE FUNCTION public.call_edge_function(function_name text, payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  base_url TEXT;
  cron_secret TEXT;
  service_key TEXT;
  api_route TEXT;
  req_headers JSONB;
  v_request_id BIGINT;   -- v_ prefix: `request_id` is also a ledger COLUMN name
  v_fn TEXT;             -- ditto for `function_name` (which is also a PARAMETER)
  target_url TEXT;
BEGIN
  base_url := get_api_base_url();

  -- Map edge function names to local API routes
  api_route := CASE function_name
    -- Discord webhook functions
    WHEN 'discord-notifications' THEN '/api/discord-webhooks/event-notification'
    WHEN 'discord-kill-notifications' THEN '/api/discord-webhooks/boss-assignments'
    WHEN 'update-discord-leaderboards' THEN '/api/discord/leaderboard-refresh'
    WHEN 'daily-summary' THEN '/api/cron/daily-alert-summary'
    WHEN 'detect-season-end' THEN '/api/cron/season-transition-monitor'
    WHEN 'process-cap-notifications' THEN '/api/discord-webhooks/cap-notification'

    -- Data sync functions
    WHEN 'check-capped-players' THEN '/api/cron/token-reminders'
    WHEN 'gr-availability' THEN '/api/discord-webhooks/post-availability'
    WHEN 'guild-raid-sync' THEN '/api/cron/guild-batch-sync'

    -- Token economy audit (WI-2640 Phase 0)
    WHEN 'token-audit' THEN '/api/cron/token-audit'

    -- Calculation functions - use local Edge Functions via Kong
    WHEN 'calculate-votlw' THEN NULL
    WHEN 'votlw_history' THEN NULL

    -- Backfill - manual operation
    WHEN 'historical-backfill' THEN NULL
    WHEN 'historical-backfill-modular' THEN NULL

    -- Default: assume API route matches function name
    ELSE '/api/' || REPLACE(function_name, '_', '-')
  END;

  IF api_route IS NULL THEN
    -- Supabase Edge Function via the configured internal gateway.
    base_url := COALESCE(NULLIF(current_setting('app.settings.supabase_internal_url', true), ''), 'http://supabase-kong:8000');
    api_route := '/functions/v1/' || function_name;

    -- Kong requires the service-role key, not the cron secret. If this key
    -- drifts from the cluster's SUPABASE_SERVICE_ROLE_KEY, Kong answers 401 and
    -- pg_cron still reports `succeeded` — the WI-6160 failure mode. The
    -- fingerprint comparison that catches it lives in the deploy-drift-check
    -- `check_service_key` lane (it needs kubectl, so it cannot live here).
    service_key := current_setting('app.settings.service_role_key', true);
    IF service_key IS NULL OR service_key = '' THEN
      RAISE WARNING 'call_edge_function: app.settings.service_role_key not configured (needed for %). Set via ALTER DATABASE postgres SET app.settings.service_role_key = ''...'';', function_name;
      RETURN jsonb_build_object('error', 'service_role_key not configured', 'function', function_name);
    END IF;
    req_headers := jsonb_build_object(
      'Authorization', 'Bearer ' || service_key,
      'apikey', service_key,
      'Content-Type', 'application/json',
      'X-Cron-Source', 'pg_cron'
    );
  ELSE
    cron_secret := get_cron_secret();
    req_headers := jsonb_build_object(
      'Authorization', 'Bearer ' || COALESCE(cron_secret, ''),
      'Content-Type', 'application/json',
      'X-Cron-Source', 'pg_cron'
    );
  END IF;

  target_url := base_url || api_route;

  -- pg_net queues the request and returns a request id (async). 120s timeout
  -- (endpoints can take 30-90s for multi-guild ops — 20260410000006).
  BEGIN
    SELECT net.http_post(
      url := target_url,
      body := payload,
      headers := req_headers,
      timeout_milliseconds := 120000
    ) INTO v_request_id;
  EXCEPTION WHEN undefined_function THEN
    -- Legacy pg_net installs expose a TEXT body instead of JSONB.
    SELECT net.http_post(
      url := target_url,
      headers := req_headers,
      body := payload::text,
      timeout_milliseconds := 120000
    ) INTO v_request_id;
  END;

  -- WI-6160: attribute the request so a later failure can name this caller.
  -- Swallowing errors here is DELIBERATE and load-bearing: this is an
  -- observability side-effect, and it must never be able to break the
  -- cron -> HTTP bridge it exists to observe. A lost ledger row degrades a
  -- future alert to today's behaviour (unattributed); a raised exception here
  -- would take down every cron job that dispatches HTTP.
  BEGIN
    v_fn := function_name;
    INSERT INTO monitoring.pgnet_request_ledger (request_id, function_name, url)
    VALUES (v_request_id, v_fn, target_url)
    ON CONFLICT (request_id) DO UPDATE
      SET function_name = EXCLUDED.function_name,
          url           = EXCLUDED.url,
          called_at     = now();
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'call_edge_function: ledger write failed for % (request %): %',
      function_name, v_request_id, SQLERRM;
  END;

  RETURN jsonb_build_object(
    'request_id', v_request_id,
    'url', target_url,
    'status', 'queued'
  );
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'call_edge_function failed for %: %', function_name, SQLERRM;
  RETURN jsonb_build_object('error', SQLERRM, 'function', function_name);
END;
$$;

ALTER FUNCTION public.call_edge_function(function_name text, payload jsonb) OWNER TO postgres;

CREATE FUNCTION public.can_author_playbooks(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
BEGIN
  -- Mirrors can_edit_playbooks' caller guards so the two cannot drift:
  -- reachable only as authenticated/service_role, and self-only when
  -- authenticated (no probing another user's authority).
  v_role := lower(trim(COALESCE(
    NULLIF(NULLIF(current_setting('role', true), ''), 'none'),
    NULLIF(session_user, '')
  )));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  IF v_role = 'authenticated'
    AND (
      auth.uid() IS NULL
      OR p_user_id IS NULL
      OR p_user_id IS DISTINCT FROM auth.uid()
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  -- P2: no feature_access_grants branch. P3: no is_active.
  RETURN EXISTS (
    SELECT 1
    FROM public.player_mapping AS pm
    WHERE pm.user_id = p_user_id
      AND pm.is_current IS TRUE
      AND (pm.is_app_admin IS TRUE OR lower(pm.role::text) IN ('leader', 'officer'))
  );
END;
$$;

ALTER FUNCTION public.can_author_playbooks(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.can_edit_playbook_row(p_cluster_code text, p_guild_code text, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Caller guards + authorship. Raises 42501 for anon/other-user probes.
  IF NOT public.can_author_playbooks(p_user_id) THEN
    RETURN false;
  END IF;

  -- App admins keep global reach, including rows with no scope columns at all.
  IF EXISTS (
    SELECT 1
    FROM public.player_mapping AS pm
    WHERE pm.user_id = p_user_id
      AND pm.is_current IS TRUE
      AND pm.is_app_admin IS TRUE
  ) THEN
    RETURN true;
  END IF;

  -- P1 + P4: own guild, or cluster-pooled row in the caller's authoritative
  -- cluster (resolved from guild_config, never from player_mapping's copy).
  RETURN EXISTS (
    SELECT 1
    FROM public.player_mapping AS pm
    JOIN public.guild_config AS gc
      ON gc.guild_code = pm.guild_code
    WHERE pm.user_id = p_user_id
      AND pm.is_current IS TRUE
      AND lower(pm.role::text) IN ('leader', 'officer')
      AND (
        (p_guild_code IS NOT NULL AND p_guild_code = pm.guild_code)
        OR (
          p_guild_code IS NULL
          AND p_cluster_code IS NOT NULL
          AND gc.cluster_code IS NOT NULL
          AND p_cluster_code = gc.cluster_code
        )
      )
  );
END;
$$;

ALTER FUNCTION public.can_edit_playbook_row(p_cluster_code text, p_guild_code text, p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.can_edit_playbooks(user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_allowed boolean;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  IF v_role = 'authenticated'
    AND (
      auth.uid() IS NULL
      OR can_edit_playbooks.user_id IS NULL
      OR can_edit_playbooks.user_id IS DISTINCT FROM auth.uid()
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT count(pm.id) FILTER (
    WHERE pm.is_app_admin IS TRUE
      OR lower(pm.role::text) IN ('leader', 'officer')
  ) > 0
  INTO v_allowed
  FROM public.player_mapping AS pm
  WHERE pm.user_id = can_edit_playbooks.user_id
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;

  SELECT coalesce(v_allowed, false) OR count(fag.user_id) FILTER (
    WHERE fag.access_level IN ('alpha_tester', 'beta_tester')
      AND (fag.expires_at IS NULL OR fag.expires_at > now())
  ) > 0
  INTO v_allowed
  FROM public.feature_access_grants AS fag
  WHERE fag.user_id = can_edit_playbooks.user_id;

  RETURN coalesce(v_allowed, false);
END;
$$;

ALTER FUNCTION public.can_edit_playbooks(user_id uuid) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.can_upload_guild_images(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM player_mapping pm
    WHERE pm.user_id = p_user_id
    AND (
      pm.is_app_admin = true
      OR pm.role::text IN ('leader', 'officer', 'Leader', 'Officer')
    )
  );
$$;

ALTER FUNCTION public.can_upload_guild_images(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.can_view_assigned_playbook(p_boss_id text, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_matches BOOLEAN;
BEGIN
  IF p_user_id IS NULL OR p_boss_id IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM player_mapping pm
    WHERE pm.user_id = p_user_id
      AND pm.is_current = true
      AND (pm.primary_boss = p_boss_id OR pm.secondary_boss = p_boss_id)
  ) INTO v_matches;

  RETURN COALESCE(v_matches, FALSE);
END;
$$;

ALTER FUNCTION public.can_view_assigned_playbook(p_boss_id text, p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.can_view_playbook(p_cluster_code character varying, p_guild_code text, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_user_cluster VARCHAR;
  v_user_guild TEXT;
BEGIN
  IF p_cluster_code IS NULL THEN
    RETURN TRUE;
  END IF;
  SELECT gc.cluster_code, pm.guild_code
  INTO v_user_cluster, v_user_guild
  FROM player_mapping pm
  JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = p_user_id
    AND pm.is_current = true
  LIMIT 1;
  IF v_user_cluster IS NULL OR v_user_cluster <> p_cluster_code THEN
    RETURN FALSE;
  END IF;
  IF p_guild_code IS NULL THEN
    RETURN TRUE;
  END IF;
  RETURN v_user_guild = p_guild_code;
END;
$$;

ALTER FUNCTION public.can_view_playbook(p_cluster_code character varying, p_guild_code text, p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.can_view_playbook_full(p_cluster_code character varying, p_guild_code text, p_boss_id text, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- First check cluster/guild access
  IF NOT public.can_view_playbook(p_cluster_code, p_guild_code, p_user_id) THEN
    RETURN FALSE;
  END IF;

  -- If guild doesn't restrict by assignment, allow access
  IF NOT public.guild_restricts_playbook_access(p_user_id) THEN
    RETURN TRUE;
  END IF;

  -- Officers and leaders always have full access
  IF public.is_user_officer_or_leader(p_user_id) THEN
    RETURN TRUE;
  END IF;

  -- Regular members: check if assigned to this boss
  RETURN public.is_user_assigned_to_boss(p_boss_id, p_user_id);
END;
$$;

ALTER FUNCTION public.can_view_playbook_full(p_cluster_code character varying, p_guild_code text, p_boss_id text, p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.categorize_team_composition(hero_names text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  hero_name text;
  category_record RECORD;
  matches_count integer;
  required_count integer;
BEGIN
  -- Check each meta team category
  FOR category_record IN
    SELECT team_name, trigger_heroes, match_type
    FROM meta_teams
    WHERE is_meta = true
    ORDER BY sort_order
  LOOP
    required_count := jsonb_array_length(category_record.trigger_heroes);

    -- Skip if no trigger heroes defined
    IF required_count = 0 THEN
      CONTINUE;
    END IF;

    IF category_record.match_type = 'any' THEN
      -- Match if ANY trigger hero is present
      FOR hero_name IN SELECT jsonb_array_elements_text(category_record.trigger_heroes)
      LOOP
        -- Check for partial match (case-insensitive, substring match)
        FOR i IN 1..array_length(hero_names, 1) LOOP
          IF LOWER(hero_names[i]) LIKE '%' || LOWER(hero_name) || '%' OR
             LOWER(hero_name) LIKE '%' || LOWER(hero_names[i]) || '%' THEN
            RETURN category_record.team_name;
          END IF;
        END LOOP;
      END LOOP;

    ELSIF category_record.match_type = 'all' THEN
      -- Match if ALL trigger heroes are present
      matches_count := 0;

      FOR hero_name IN SELECT jsonb_array_elements_text(category_record.trigger_heroes)
      LOOP
        -- Check for exact match first
        IF hero_name = ANY(hero_names) THEN
          matches_count := matches_count + 1;
        ELSE
          -- Also check for partial matches
          FOR i IN 1..array_length(hero_names, 1) LOOP
            IF LOWER(hero_names[i]) LIKE '%' || LOWER(hero_name) || '%' OR
               LOWER(hero_name) LIKE '%' || LOWER(hero_names[i]) || '%' THEN
              matches_count := matches_count + 1;
              EXIT; -- Found a match, move to next trigger hero
            END IF;
          END LOOP;
        END IF;
      END LOOP;

      IF matches_count = required_count THEN
        RETURN category_record.team_name;
      END IF;

    ELSIF category_record.match_type = 'exact' THEN
      -- Match if team has EXACTLY these heroes (not implemented yet)
      -- This would require more complex matching logic
      NULL;
    END IF;
  END LOOP;

  -- No category matched, return 'Other'
  RETURN 'Other';
END;
$$;

ALTER FUNCTION public.categorize_team_composition(hero_names text[]) OWNER TO postgres;

CREATE FUNCTION public.change_own_player_account(p_proof_invite_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_auth_uid uuid := auth.uid();
  v_request_role text := coalesce(
    nullif(nullif(current_setting('role', true), ''), 'none'),
    session_user
  );
  v_invite record;
  v_receipt record;
  -- Scalars, not records: the idempotent path never resolves a target, and a
  -- record field read on an unresolved target would raise instead of returning.
  v_source_id integer;
  v_source_guild text;
  v_source_attestation_id uuid;
  v_target_id integer;
  v_target_player text;
  v_target_guild text;
  v_bound_mapping_id integer;
  v_target_ids integer[];
  v_locked_ids integer[];
  v_attestation_id uuid := gen_random_uuid();
  v_revocation_id uuid;
  v_digest text;
  v_error_code text;
  v_error text;
  v_outcome text;
  v_audit_player text;
  v_audit_guild text;
  v_now timestamptz;
  -- Set true once the proof's created_by has been proven to be the caller. From
  -- that point a bearer who reaches ANY rejection has demonstrated custody, so
  -- the single-use token is spent rather than left live for the rest of its TTL
  -- (security M2).
  v_subject_proven boolean := false;
  v_idempotent boolean := false;
  v_success boolean := false;
BEGIN
  IF v_request_role <> 'authenticated' OR v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required to change your player account'
      USING ERRCODE = '42501';
  END IF;

  -- Claims, account preparation, Auth deletion, and this transfer all serialize
  -- on the same subject key, BEFORE any decision read.
  PERFORM pg_advisory_xact_lock(6208, hashtext(v_auth_uid::text));

  <<transfer>>
  BEGIN
    IF EXISTS (
      SELECT 1
      FROM public.player_identity_subject_authority_blocks AS block
      WHERE block.subject_user_id = v_auth_uid
    ) THEN
      v_error_code := 'SUBJECT_AUTHORITY_BLOCKED';
      v_error := 'Account authority is permanently blocked';
      v_outcome := 'rejected_auth_required';
      EXIT transfer;
    END IF;
    PERFORM 1
    FROM auth.users AS subject
    WHERE subject.id = v_auth_uid
    FOR KEY SHARE;
    IF NOT FOUND THEN
      v_error_code := 'AUTH_SUBJECT_ABSENT';
      v_error := 'Authenticated account no longer exists';
      v_outcome := 'rejected_auth_required';
      EXIT transfer;
    END IF;

    IF p_proof_invite_id IS NULL THEN
      v_error_code := 'PROOF_REQUIRED';
      v_error := 'A possession proof is required';
      v_outcome := 'rejected_invalid_input';
      EXIT transfer;
    END IF;

    -- Proof consumption. The primary key makes "exactly one row" structural;
    -- FOR UPDATE holds it for the whole transaction, so the used/revoked/expired
    -- predicates below are evaluated against a row nobody else can stamp first.
    -- The invite table is locked BEFORE player_mapping, matching the claim RPC.
    SELECT invite.id, invite.code, invite.player_id, invite.guild_code,
           invite.created_by, invite.used_at, invite.revoked_at,
           invite.expires_at
    INTO v_invite
    FROM public.player_invite_codes AS invite
    WHERE invite.id = p_proof_invite_id
    FOR UPDATE;
    IF NOT FOUND THEN
      v_error_code := 'PROOF_NOT_FOUND';
      v_error := 'That possession proof does not exist';
      v_outcome := 'rejected_invalid_input';
      EXIT transfer;
    END IF;
    IF v_invite.used_at IS NOT NULL THEN
      v_error_code := 'PROOF_ALREADY_USED';
      v_error := 'That possession proof has already been used';
      v_outcome := 'rejected_invalid_input';
      EXIT transfer;
    END IF;
    IF v_invite.revoked_at IS NOT NULL THEN
      v_error_code := 'PROOF_REVOKED';
      v_error := 'That possession proof was revoked';
      v_outcome := 'rejected_invalid_input';
      EXIT transfer;
    END IF;
    IF v_invite.expires_at <= clock_timestamp() THEN
      v_error_code := 'PROOF_EXPIRED';
      v_error := 'That possession proof has expired';
      v_outcome := 'rejected_invalid_input';
      EXIT transfer;
    END IF;
    -- Reserved namespace, via the ONE shared definition (B1): an officer invite
    -- can never reach this corridor, and the officer corridor can never consume
    -- what does.
    IF NOT public.is_possession_proof_code(v_invite.code) THEN
      v_error_code := 'PROOF_NOT_POSSESSION';
      v_error := 'That invite is not a possession proof';
      v_outcome := 'rejected_invalid_input';
      EXIT transfer;
    END IF;
    -- Subject binding. Mismatch fails closed.
    IF v_invite.created_by IS NULL
      OR v_invite.created_by IS DISTINCT FROM v_auth_uid
    THEN
      v_error_code := 'PROOF_SUBJECT_MISMATCH';
      v_error := 'That possession proof belongs to another account';
      v_outcome := 'rejected_user_mismatch';
      EXIT transfer;
    END IF;
    -- Custody proven. Every rejection from here on burns the token (M2).
    v_subject_proven := true;

    -- Mint receipt: proves the row came from mint_player_possession_invite, and
    -- carries the mint-time upstream digest quoted in every audit row below.
    -- Bound to the minting subject and a successful mint (security S1) so a
    -- stray same-invite_id audit row can never satisfy it.
    SELECT audit.details ->> 'upstream_digest' AS upstream_digest,
           audit.player_id AS player_id
    INTO v_receipt
    FROM public.player_claim_audit AS audit
    WHERE audit.source_path = 'profile/change-player-id/mint'
      AND audit.details ->> 'invite_id' = p_proof_invite_id::text
      AND audit.user_id = v_invite.created_by
      AND audit.outcome = 'success'
    ORDER BY audit.id DESC
    LIMIT 1;
    IF NOT FOUND OR v_receipt.upstream_digest IS NULL THEN
      v_error_code := 'PROOF_NOT_MINTED';
      v_error := 'That possession proof has no upstream verification receipt';
      v_outcome := 'rejected_invalid_input';
      EXIT transfer;
    END IF;
    v_digest := v_receipt.upstream_digest;
    -- Player binding, cross-checked against the receipt. Mismatch fails closed.
    IF v_receipt.player_id IS DISTINCT FROM v_invite.player_id THEN
      v_error_code := 'PROOF_PLAYER_MISMATCH';
      v_error := 'That possession proof does not match its verified player';
      v_outcome := 'rejected_invalid_input';
      EXIT transfer;
    END IF;
    v_audit_player := v_invite.player_id;
    v_audit_guild := v_invite.guild_code;

    -- Source: the caller's ONE current mapping carrying a live attestation.
    SELECT mapping.id, mapping.guild_code, mapping.ownership_attestation_id
    INTO v_source_id, v_source_guild, v_source_attestation_id
    FROM public.player_mapping AS mapping
    JOIN public.player_identity_attestations AS proof
      ON proof.id = mapping.ownership_attestation_id
    WHERE mapping.user_id = v_auth_uid
      AND mapping.is_current IS TRUE
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_attestation_revocations AS revoked
        WHERE revoked.attestation_id = proof.id
      );
    IF NOT FOUND THEN
      v_error_code := 'NO_ATTESTED_SOURCE';
      v_error := 'You have no proven player profile to move';
      v_outcome := 'rejected_not_found';
      EXIT transfer;
    END IF;
    IF (
      SELECT count(*)
      FROM public.player_mapping AS mapping
      WHERE mapping.user_id = v_auth_uid
        AND mapping.is_current IS TRUE
    ) <> 1 THEN
      v_error_code := 'SOURCE_NOT_EXACT';
      v_error := 'Your account does not identify one current profile';
      v_outcome := 'rejected_not_found';
      EXIT transfer;
    END IF;

    -- Target, derived ONLY from the proof -- never from caller input.
    SELECT array_agg(mapping.id ORDER BY mapping.id)
    INTO v_target_ids
    FROM public.player_mapping AS mapping
    WHERE mapping.player_id = v_invite.player_id
      AND mapping.is_current IS TRUE;
    IF v_target_ids IS NULL THEN
      -- architect R4: the absent-target case is its own code and its own copy.
      -- It is NOT papered over with a sync-and-retry.
      v_error_code := 'PLAYER_NOT_ON_TRACKED_ROSTER';
      v_error := 'That player is not on a tracked guild roster yet';
      v_outcome := 'rejected_not_found';
      EXIT transfer;
    END IF;
    IF cardinality(v_target_ids) <> 1 THEN
      v_error_code := 'TARGET_NOT_EXACT';
      v_error := 'That player does not identify one current mapping';
      v_outcome := 'rejected_not_found';
      EXIT transfer;
    END IF;

    -- Same row: the caller already holds this player. Idempotent success, and
    -- checked BEFORE the rate limit so a retry is never answered RATE_LIMITED.
    IF v_target_ids[1] = v_source_id THEN
      UPDATE public.player_invite_codes AS invite
      SET used_at = clock_timestamp(), used_by = v_auth_uid
      WHERE invite.id = v_invite.id;
      v_audit_guild := v_source_guild;
      v_bound_mapping_id := v_source_id;
      v_idempotent := true;
      v_success := true;
      EXIT transfer;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.player_identity_attestations AS prior
      WHERE prior.subject_user_id = v_auth_uid
        AND prior.source = 'self_player_id_change'
        AND prior.attested_at > now() - interval '7 days'
    ) THEN
      v_error_code := 'RATE_LIMITED';
      v_error := 'You can only move your account once every 7 days';
      v_outcome := 'rejected_invalid_input';
      EXIT transfer;
    END IF;

    -- Both mapping rows locked FOR UPDATE in deterministic id order.
    --
    -- Reliance, stated per architect R3: pg_advisory_xact_lock(6208, subject)
    -- serializes ONE subject against itself; it does NOT serialize two DIFFERENT
    -- subjects racing for the same target row. The row lock is what does. Under
    -- READ COMMITTED the loser blocks here, then re-evaluates the predicate
    -- below against the winner's committed row -- which returns zero rows, so
    -- the loser fails closed with TARGET_ALREADY_CLAIMED and writes no binding.
    SELECT array_agg(locked.id ORDER BY locked.id)
    INTO v_locked_ids
    FROM (
      SELECT mapping.id
      FROM public.player_mapping AS mapping
      WHERE mapping.id IN (v_source_id, v_target_ids[1])
      ORDER BY mapping.id
      FOR UPDATE
    ) AS locked;
    IF cardinality(coalesce(v_locked_ids, ARRAY[]::integer[])) <> 2 THEN
      v_error_code := 'MAPPING_LOCK_INCOMPLETE';
      v_error := 'The profiles changed while the move was being prepared';
      v_outcome := 'rejected_update_failed';
      EXIT transfer;
    END IF;

    SELECT mapping.guild_code, mapping.ownership_attestation_id
    INTO v_source_guild, v_source_attestation_id
    FROM public.player_mapping AS mapping
    JOIN public.player_identity_attestations AS proof
      ON proof.id = mapping.ownership_attestation_id
    WHERE mapping.id = v_source_id
      AND mapping.user_id = v_auth_uid
      AND mapping.is_current IS TRUE
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_attestation_revocations AS revoked
        WHERE revoked.attestation_id = proof.id
      );
    IF NOT FOUND THEN
      v_error_code := 'SOURCE_CHANGED';
      v_error := 'Your profile changed while the move was being prepared';
      v_outcome := 'rejected_update_failed';
      EXIT transfer;
    END IF;

    -- ownership_attestation_id IS NULL as well as user_id: a row that somehow
    -- carried a stale attestation id would otherwise pass this predicate and
    -- then hard-abort in the provenance trigger; requiring both turns that into
    -- a clean TARGET_ALREADY_CLAIMED (db D4).
    SELECT mapping.id, mapping.player_id, mapping.guild_code
    INTO v_target_id, v_target_player, v_target_guild
    FROM public.player_mapping AS mapping
    WHERE mapping.id = v_target_ids[1]
      AND mapping.is_current IS TRUE
      AND mapping.player_id = v_invite.player_id
      AND mapping.user_id IS NULL
      AND mapping.ownership_attestation_id IS NULL;
    IF NOT FOUND THEN
      v_error_code := 'TARGET_ALREADY_CLAIMED';
      v_error := 'That player profile has already been claimed';
      v_outcome := 'rejected_already_claimed';
      EXIT transfer;
    END IF;
    v_audit_guild := v_target_guild;
    v_bound_mapping_id := v_target_id;

    -- ---- architect R2 statement order, exactly ----------------------------
    -- 1) revoke the source attestation
    v_revocation_id := public.append_player_identity_revocation(
      v_source_attestation_id,
      'player_id_correction',
      v_auth_uid,
      'profile/change-player-id'
    );
    -- 2) unbind the source row: no user, no proof, no Discord, no app-admin,
    --    no stored credential, no Patreon link, no retained role authority
    --    (WI-6240 r2, security F2 -- see the demotion note in the clear block).
    --    patreon_user_id is a server-authority column (M3).
    UPDATE public.player_mapping AS mapping
    SET user_id = NULL,
        ownership_attestation_id = NULL,
        discord_user_id = NULL,
        discord_username = NULL,
        is_app_admin = false,
        patreon_user_id = NULL,
        tacticus_api_key_encrypted = NULL,
        api_key_is_valid = NULL,
        api_key_last_verified = NULL,
        api_key_added_at = NULL,
        -- WI-6240 r2 finding N2 (profile-PII residue): the previous holder's
        -- user-supplied personal profile values must not survive on this row.
        -- Default-vs-NULL decided per column against the recaptured baseline's
        -- DDL (prod-baseline.sql player_mapping): a column with a non-null
        -- DEFAULT is reset to that default, everything else to NULL.
        username = NULL,
        avatar_url = NULL,
        timezone = 'UTC',                -- column DEFAULT 'UTC'::text
        tacticus_share_url = NULL,
        player_notes = NULL,
        theme_preference = NULL,         -- column DEFAULT is NULL::character varying
        boss_preferences = '{}'::jsonb,  -- column DEFAULT '{}'::jsonb
        preferences_updated_at = now(),  -- column DEFAULT now()
        notify_boss_kills = false,       -- column DEFAULT false
        notify_prime_kills = false,      -- column DEFAULT false
        notify_when_capped = false,      -- column DEFAULT false
        -- WI-6240 r2 security F2 (SOURCE-UNBIND ONLY): requireRole()/
        -- requireRoleForApi() read player_mapping.role as live authority, and
        -- Roster deactivation demotes authority on unbind. Match it:
        -- between this unbind and the next roster sync, an unclaimed,
        -- officer-invitable row must not carry the departing holder's role.
        role = 'member'::public.app_role,
        updated_at = clock_timestamp()
    WHERE mapping.id = v_source_id;
    -- 3) the new attestation, carrying the REAL proof invite. One clock read for
    --    the consumed_at/attested_at pair (S3): the >= CHECK is not covered by
    --    this function's exception handler, so it must not depend on two calls.
    v_now := clock_timestamp();
    INSERT INTO public.player_identity_attestations (
      id, mapping_id, player_id, subject_user_id, source_invite_id,
      consumed_at, attested_at, source, guild_code_snapshot
    ) VALUES (
      v_attestation_id, v_target_id, v_target_player, v_auth_uid,
      v_invite.id, v_now, v_now,
      'self_player_id_change', v_target_guild
    );
    -- 4) ONE update binding the target: user_id and ownership_attestation_id
    --    move together, the new binding carries no privilege (architect D8), and
    --    the target row's OWN stored credential / Patreon link are wiped so the
    --    incoming user never inherits the previous holder's game credential
    --    (security M1 / db D1) or Patreon identity (M3).
    UPDATE public.player_mapping AS mapping
    SET user_id = v_auth_uid,
        ownership_attestation_id = v_attestation_id,
        is_app_admin = false,
        discord_user_id = NULL,
        discord_username = NULL,
        patreon_user_id = NULL,
        tacticus_api_key_encrypted = NULL,
        api_key_is_valid = NULL,
        api_key_last_verified = NULL,
        api_key_added_at = NULL,
        -- WI-6240 r2 finding N2 (profile-PII residue): the previous holder's
        -- user-supplied personal profile values must not survive on this row.
        -- Default-vs-NULL decided per column against the recaptured baseline's
        -- DDL (prod-baseline.sql player_mapping): a column with a non-null
        -- DEFAULT is reset to that default, everything else to NULL.
        username = NULL,
        avatar_url = NULL,
        timezone = 'UTC',                -- column DEFAULT 'UTC'::text
        tacticus_share_url = NULL,
        player_notes = NULL,
        theme_preference = NULL,         -- column DEFAULT is NULL::character varying
        boss_preferences = '{}'::jsonb,  -- column DEFAULT '{}'::jsonb
        preferences_updated_at = now(),  -- column DEFAULT now()
        notify_boss_kills = false,       -- column DEFAULT false
        notify_prime_kills = false,      -- column DEFAULT false
        notify_when_capped = false,      -- column DEFAULT false
        updated_at = clock_timestamp()
    WHERE mapping.id = v_target_id;
    -- -----------------------------------------------------------------------

    UPDATE public.player_invite_codes AS invite
    SET used_at = clock_timestamp(), used_by = v_auth_uid
    WHERE invite.id = v_invite.id;

    v_success := true;
  END;

  IF v_success THEN
    INSERT INTO public.player_claim_audit (
      user_id, player_id, guild_code, source_path, outcome, details
    ) VALUES (
      v_auth_uid, v_audit_player, v_audit_guild,
      'profile/change-player-id', 'success',
      jsonb_build_object(
        'action', 'change_own_player_account',
        'idempotent', v_idempotent,
        'proof_invite_id', p_proof_invite_id::text,
        'upstream_digest', v_digest,
        'source_mapping_id', v_source_id,
        'target_mapping_id', v_bound_mapping_id,
        'revoked_attestation_id',
          CASE WHEN v_idempotent THEN NULL ELSE v_source_attestation_id END,
        'revocation_id', v_revocation_id,
        'attestation_id',
          CASE WHEN v_idempotent THEN NULL ELSE v_attestation_id END
      )
    );
    RETURN jsonb_build_object(
      'success', true,
      'idempotent', v_idempotent,
      'player_id', v_audit_player,
      'guild_code', v_audit_guild,
      'mapping_id', v_bound_mapping_id,
      'attestation_id',
        CASE WHEN v_idempotent THEN NULL ELSE v_attestation_id END
    );
  END IF;

  -- Burn the single-use token on any rejection reached AFTER custody was proven
  -- (M2). The bearer demonstrated it holds the proof, so it must not stay live
  -- for the rest of its TTL. Pre-custody faults (PROOF_SUBJECT_MISMATCH and
  -- everything before it) leave the proof untouched -- a wrong-owner or
  -- malformed attempt must not consume the real owner's token.
  IF v_subject_proven THEN
    UPDATE public.player_invite_codes AS invite
    SET used_at = clock_timestamp(), used_by = v_auth_uid
    WHERE invite.id = v_invite.id
      AND invite.used_at IS NULL;
  END IF;

  INSERT INTO public.player_claim_audit (
    user_id, player_id, guild_code, source_path, outcome, details
  ) VALUES (
    v_auth_uid, v_audit_player, v_audit_guild,
    'profile/change-player-id', coalesce(v_outcome, 'rejected_invalid_input'),
    jsonb_build_object(
      'action', 'change_own_player_account',
      'error_code', v_error_code,
      'proof_invite_id', p_proof_invite_id::text,
      'upstream_digest', v_digest
    )
  );
  RETURN jsonb_build_object(
    'success', false,
    'error', v_error,
    'error_code', v_error_code
  );
EXCEPTION
  -- The handler's own statements survive: the rollback is to the start of this
  -- block, so the audit row below is written after it and commits with the
  -- caller's transaction. Every rejection path is audited, this one included.
  WHEN unique_violation OR exclusion_violation THEN
    -- Same M2 rule: a conflict is reached only after custody was proven, and the
    -- block's own used_at stamp (if any) rolled back with the failed transfer,
    -- so re-burn here. The row lock is re-acquired by this UPDATE.
    IF v_subject_proven THEN
      UPDATE public.player_invite_codes AS invite
      SET used_at = clock_timestamp(), used_by = v_auth_uid
      WHERE invite.id = v_invite.id
        AND invite.used_at IS NULL;
    END IF;
    INSERT INTO public.player_claim_audit (
      user_id, player_id, guild_code, source_path, outcome, details
    ) VALUES (
      v_auth_uid, v_audit_player, v_audit_guild,
      'profile/change-player-id', 'rejected_database_error',
      jsonb_build_object(
        'action', 'change_own_player_account',
        'error_code', 'TRANSFER_CONFLICT',
        'proof_invite_id', p_proof_invite_id::text,
        'upstream_digest', v_digest
      )
    );
    RETURN jsonb_build_object(
      'success', false,
      'error', 'The profile was claimed concurrently',
      'error_code', 'TRANSFER_CONFLICT'
    );
END
$$;

ALTER FUNCTION public.change_own_player_account(p_proof_invite_id uuid) OWNER TO postgres;

CREATE FUNCTION public.check_database_health() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    health_report jsonb;
    cache_stats record;
    connection_stats record;
    vacuum_needed integer;
    slow_queries integer;
BEGIN
    -- Get cache hit rates
    SELECT * INTO cache_stats FROM get_cache_hit_rates() WHERE name = 'table hit rate';

    -- Get connection statistics
    SELECT * INTO connection_stats FROM get_connection_stats();

    -- Count tables needing vacuum
    SELECT COUNT(*) INTO vacuum_needed FROM get_tables_needing_vacuum();

    -- Count slow queries
    SELECT count INTO slow_queries FROM count_slow_queries();

    -- Build health report
    health_report = jsonb_build_object(
        'timestamp', current_timestamp,
        'cache_hit_rate', COALESCE(cache_stats.ratio, 0),
        'active_connections', connection_stats.active_connections,
        'total_connections', connection_stats.total_connections,
        'tables_needing_vacuum', vacuum_needed,
        'slow_queries', slow_queries,
        'health_score', CASE
            WHEN cache_stats.ratio < 90 THEN 'critical'
            WHEN cache_stats.ratio < 95 THEN 'warning'
            WHEN connection_stats.active_connections > 50 THEN 'warning'
            WHEN vacuum_needed > 5 THEN 'warning'
            WHEN slow_queries > 5 THEN 'warning'
            ELSE 'good'
        END,
        'recommendations', CASE
            WHEN cache_stats.ratio < 90 THEN
                jsonb_build_array(
                    'Critical: Cache hit rate too low. Add indexes immediately.',
                    'Run: scripts/database/optimize-heavy-queries.sql'
                )
            WHEN cache_stats.ratio < 95 THEN
                jsonb_build_array('Warning: Cache hit rate below optimal. Consider adding indexes.')
            ELSE jsonb_build_array()
        END ||
        CASE
            WHEN connection_stats.active_connections > 50 THEN
                jsonb_build_array('High connection count. Enable connection pooling.')
            ELSE jsonb_build_array()
        END ||
        CASE
            WHEN vacuum_needed > 5 THEN
                jsonb_build_array('Multiple tables need vacuum. Run VACUUM ANALYZE.')
            ELSE jsonb_build_array()
        END
    );

    RETURN health_report;
END;
$$;

ALTER FUNCTION public.check_database_health() OWNER TO postgres;

