CREATE FUNCTION public.check_guild_registration_status(guild_code_param text) RETURNS TABLE(guild_exists boolean, registration_status text, can_resume boolean, registration_age_hours numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        TRUE as guild_exists,
        CASE
            WHEN gc.onboarding_completed = true THEN 'completed'
            WHEN gc.api_key_encrypted IS NOT NULL THEN 'pending_sync'
            ELSE 'pending_api_key'
        END as registration_status,
        CASE
            WHEN gc.onboarding_completed = false
                 AND gc.api_key_encrypted IS NULL
            THEN TRUE
            ELSE FALSE
        END as can_resume,
        EXTRACT(HOURS FROM (now() - gc.onboarding_started_at)) as registration_age_hours
    FROM guild_config gc
    WHERE gc.guild_code = UPPER(guild_code_param)
    LIMIT 1;

    -- If no record found, return false
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, NULL::TEXT, FALSE, NULL::NUMERIC;
    END IF;
END;
$$;

ALTER FUNCTION public.check_guild_registration_status(guild_code_param text) OWNER TO postgres;

CREATE FUNCTION public.check_http_response_errors() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  error_count INTEGER;
  error_summary TEXT;
BEGIN
  SELECT count(*), string_agg(line, E'\n')
  INTO error_count, error_summary
  FROM (
    SELECT DISTINCT
      COALESCE(led.function_name, '(unattributed)')
      || ' → '
      || COALESCE(
           resp.status_code::text,
           CASE WHEN resp.timed_out THEN 'TIMEOUT' ELSE 'CONN_ERR' END
         )
      || COALESCE(' ' || led.url, '')
      || COALESCE(': ' || LEFT(COALESCE(resp.error_msg, resp.content), 160), '')
      AS line
    FROM net._http_response resp
    LEFT JOIN monitoring.pgnet_request_ledger led ON led.request_id = resp.id
    WHERE resp.created >= NOW() - INTERVAL '30 minutes'
      AND (resp.status_code < 200 OR resp.status_code >= 400
           OR resp.error_msg IS NOT NULL OR resp.timed_out = true)
  ) s;

  DELETE FROM monitoring.pgnet_request_ledger
  WHERE called_at < NOW() - INTERVAL '7 days';

  IF error_count > 0 THEN
    PERFORM monitoring.notify(
      'pgnet.http_errors', 'firing',
      format('pg_net HTTP errors (%s in last 30min)', error_count),
      LEFT(COALESCE(error_summary, 'Unknown errors'), 1800));
  ELSE
    PERFORM monitoring.notify(
      'pgnet.http_errors', 'cleared',
      'pg_net HTTP errors',
      'No failed pg_net responses in the last 30 minutes.');
  END IF;
END;
$$;

ALTER FUNCTION public.check_http_response_errors() OWNER TO postgres;

CREATE FUNCTION public.check_log_export_cooldown(p_guild_code character varying) RETURNS TABLE(can_export boolean, last_export timestamp with time zone, next_available timestamp with time zone, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_last_export TIMESTAMPTZ;
  v_cooldown_period INTERVAL := INTERVAL '14 days';
BEGIN
  -- Get the most recent completed export for this guild
  SELECT MAX(requested_at) INTO v_last_export
  FROM log_export_requests
  WHERE guild_code = p_guild_code
  AND status IN ('completed', 'pending', 'processing');

  IF v_last_export IS NULL THEN
    -- No previous exports
    RETURN QUERY
    SELECT
      TRUE AS can_export,
      NULL::TIMESTAMPTZ AS last_export,
      NOW() AS next_available,
      'Ready to export'::TEXT AS message;
  ELSIF v_last_export + v_cooldown_period > NOW() THEN
    -- Still in cooldown
    RETURN QUERY
    SELECT
      FALSE AS can_export,
      v_last_export AS last_export,
      v_last_export + v_cooldown_period AS next_available,
      FORMAT('Export available in %s',
        age(v_last_export + v_cooldown_period, NOW())::TEXT
      ) AS message;
  ELSE
    -- Cooldown expired
    RETURN QUERY
    SELECT
      TRUE AS can_export,
      v_last_export AS last_export,
      NOW() AS next_available,
      'Ready to export'::TEXT AS message;
  END IF;
END;
$$;

ALTER FUNCTION public.check_log_export_cooldown(p_guild_code character varying) OWNER TO postgres;

CREATE FUNCTION public.check_pgnet_freshness() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  last_success timestamptz;
  last_any timestamptz;
  recent_cron_runs integer;
  msg text;
  reset_at timestamptz;
  window_start timestamptz;
  was_reset boolean;
  grace interval := INTERVAL '1 hour';
BEGIN
  reset_at := pg_postmaster_start_time();
  window_start := GREATEST(NOW() - INTERVAL '4 hours', reset_at);
  was_reset := reset_at > NOW() - INTERVAL '4 hours';

  SELECT MAX(created) FILTER (WHERE status_code >= 200 AND status_code < 300),
         MAX(created)
    INTO last_success, last_any
    FROM net._http_response
   WHERE created >= window_start;

  IF last_success IS NOT NULL THEN
    -- WI-6170: an explicit all-clear, not a silent re-arm.
    PERFORM monitoring.notify(
      'pgnet.bridge', 'cleared',
      'pg_net cron → HTTP bridge',
      format('Bridge is delivering again (last 2xx: %s).', last_success));
    RETURN;
  END IF;

  -- WI-6160: too soon after a promotion wiped the UNLOGGED response history to
  -- judge. Report NEITHER state — "I cannot tell" is not "cleared".
  IF was_reset AND NOW() - reset_at < grace THEN
    RAISE NOTICE '[check_pgnet_freshness] deferring: unlogged response history was reset at % (postmaster restart/promotion), only % ago — no verdict is possible yet.',
      reset_at, NOW() - reset_at;
    RETURN;
  END IF;

  SELECT count(*) INTO recent_cron_runs
    FROM cron.job_run_details
   WHERE start_time >= window_start;

  msg := format(
    'pg_net has delivered NO successful HTTP response since %s '
    || '(last 2xx: %s, last response of any kind: %s, cron runs in window: %s). '
    || 'The cron -> HTTP bridge may be silently broken again — see WI-2530/WI-2560.%s',
    window_start,
    COALESCE(last_success::text, 'none in window'),
    COALESCE(last_any::text, 'none'),
    recent_cron_runs,
    CASE WHEN was_reset THEN format(
      E'\nNOTE: net._http_response is UNLOGGED and was emptied by a postmaster '
      || 'restart/promotion at %s, so the window starts there rather than 4h '
      || 'back. This is NOT purge noise — more than %s has since elapsed with '
      || 'zero successes, which a healthy bridge cannot do.', reset_at, grace)
    ELSE '' END
  );

  PERFORM monitoring.notify(
    'pgnet.bridge', 'firing', 'pg_net freshness watchdog: bridge may be down', msg);
EXCEPTION WHEN OTHERS THEN
  -- Never let the watchdog kill its own cron slot.
  RAISE WARNING '[check_pgnet_freshness] watchdog error: %', SQLERRM;
END;
$$;

ALTER FUNCTION public.check_pgnet_freshness() OWNER TO postgres;

CREATE FUNCTION public.check_votlw_data_freshness() RETURNS TABLE(status text, current_season integer, last_votlw_season integer, needs_update boolean, message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
DECLARE
    current_season_val INTEGER;
    last_votlw_season_val INTEGER;
    completed_season INTEGER;
BEGIN
    -- Get current season from battle data
    SELECT MAX("Season"::integer) INTO current_season_val
    FROM "EOT_GR_data"
    WHERE "Season" ~ '^\d+$'
        AND "Guild" NOT IN ('TEST', 'EOT', 'TBD');

    -- Get last season in VOTLW table
    SELECT MAX(season::integer) INTO last_votlw_season_val
    FROM votlw_winners
    WHERE season ~ '^\d+$';

    -- The completed season is current - 1
    completed_season := current_season_val - 1;

    RETURN QUERY
    SELECT
        CASE
            WHEN last_votlw_season_val IS NULL THEN 'NO_DATA'
            WHEN last_votlw_season_val < completed_season THEN 'OUTDATED'
            WHEN last_votlw_season_val = completed_season THEN 'CURRENT'
            ELSE 'FUTURE_DATA'
        END AS status,
        current_season_val AS current_season,
        last_votlw_season_val AS last_votlw_season,
        COALESCE(last_votlw_season_val, 0) < completed_season AS needs_update,
        CASE
            WHEN last_votlw_season_val IS NULL THEN
                'No VOTLW data found. Need to calculate for all completed seasons.'
            WHEN last_votlw_season_val < completed_season THEN
                'VOTLW data is outdated. Need to calculate for season ' || completed_season::text
            WHEN last_votlw_season_val = completed_season THEN
                'VOTLW data is current (has data for last completed season ' || completed_season::text || ')'
            ELSE
                'Warning: VOTLW data exists for future season'
        END AS message;
END;
$_$;

ALTER FUNCTION public.check_votlw_data_freshness() OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

CREATE TABLE public.sync_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    guild_code text NOT NULL,
    job_type text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    priority integer DEFAULT 5 NOT NULL,
    scheduled_for timestamp with time zone DEFAULT now(),
    attempts integer DEFAULT 0,
    max_attempts integer DEFAULT 3,
    worker_id text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    payload jsonb DEFAULT '{}'::jsonb,
    progress jsonb DEFAULT '{}'::jsonb,
    error_log jsonb DEFAULT '[]'::jsonb,
    CONSTRAINT sync_queue_job_type_check CHECK ((job_type = ANY (ARRAY['full_sync'::text, 'incremental_sync'::text, 'realtime_sync'::text, 'player_sync'::text, 'validation_sync'::text]))),
    CONSTRAINT sync_queue_priority_check CHECK (((priority >= 1) AND (priority <= 10))),
    CONSTRAINT sync_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'completed'::text, 'failed'::text, 'retrying'::text])))
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_scale_factor='0.025');

ALTER TABLE public.sync_queue OWNER TO postgres;

CREATE FUNCTION public.claim_next_job(p_worker_id text, p_job_types text[] DEFAULT NULL::text[]) RETURNS public.sync_queue
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_job sync_queue;
BEGIN
  -- Select next available job
  -- priority ASC: lower number = higher urgency (1=critical, 9=routine)
  SELECT * INTO v_job
  FROM sync_queue
  WHERE status = 'pending'
    AND scheduled_for <= NOW()
    AND (p_job_types IS NULL OR job_type = ANY(p_job_types))
    AND attempts < max_attempts
  ORDER BY priority ASC, scheduled_for ASC
  LIMIT 1
  FOR UPDATE SKIP LOCKED;

  -- Update if found
  IF v_job.id IS NOT NULL THEN
    UPDATE sync_queue
    SET
      status = 'processing',
      worker_id = p_worker_id,
      started_at = NOW(),
      attempts = attempts + 1,
      updated_at = NOW()
    WHERE id = v_job.id
    RETURNING * INTO v_job;
  END IF;

  RETURN v_job;
END;
$$;

ALTER FUNCTION public.claim_next_job(p_worker_id text, p_job_types text[]) OWNER TO postgres;

CREATE TABLE public.work_queue (
    id bigint NOT NULL,
    job_type text NOT NULL,
    job_class text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    dedupe_key text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    priority smallint DEFAULT 5 NOT NULL,
    attempts smallint DEFAULT 0 NOT NULL,
    max_attempts smallint DEFAULT 3 NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone,
    scheduled_for timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_queue_class_check CHECK ((job_class = ANY (ARRAY['batch'::text, 'sync'::text, 'webhook'::text, 'alert'::text, 'notification'::text, 'hook'::text, 'heavy'::text, 'verify'::text, 'volunteer'::text]))),
    CONSTRAINT work_queue_priority_check CHECK (((priority >= 1) AND (priority <= 9))),
    CONSTRAINT work_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'completed'::text, 'failed'::text, 'dead'::text])))
);

ALTER TABLE public.work_queue OWNER TO postgres;

CREATE FUNCTION public.claim_next_work_job(p_worker_id text, p_classes text[]) RETURNS SETOF public.work_queue
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  UPDATE public.work_queue q
  SET status      = 'processing',
      claimed_by  = p_worker_id,
      claimed_at  = now(),
      started_at  = now(),
      attempts    = q.attempts + 1,
      updated_at  = now()
  WHERE q.id = (
    SELECT id
    FROM public.work_queue
    WHERE status = 'pending'
      AND job_class = ANY(p_classes)
      AND scheduled_for <= now()
      AND attempts < max_attempts
    ORDER BY priority ASC, scheduled_for ASC
    FOR UPDATE SKIP LOCKED
    LIMIT 1
  )
  RETURNING q.*;
END;
$$;

ALTER FUNCTION public.claim_next_work_job(p_worker_id text, p_classes text[]) OWNER TO postgres;

CREATE TABLE public.write_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    operation_type text NOT NULL,
    target_table text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    rpc_name text,
    rpc_params jsonb,
    status text DEFAULT 'pending'::text NOT NULL,
    priority integer DEFAULT 5 NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    last_error text,
    error_log jsonb DEFAULT '[]'::jsonb,
    queued_at timestamp with time zone DEFAULT now() NOT NULL,
    scheduled_for timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval),
    context jsonb DEFAULT '{}'::jsonb,
    worker_id text,
    circuit_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT write_queue_operation_type_check CHECK ((operation_type = ANY (ARRAY['insert'::text, 'update'::text, 'delete'::text, 'upsert'::text]))),
    CONSTRAINT write_queue_priority_check CHECK (((priority >= 1) AND (priority <= 10))),
    CONSTRAINT write_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'completed'::text, 'failed'::text, 'expired'::text])))
);

ALTER TABLE public.write_queue OWNER TO postgres;

CREATE FUNCTION public.claim_write_job(p_worker_id text, p_circuit_name text DEFAULT NULL::text) RETURNS public.write_queue
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_job write_queue;
BEGIN
    -- Select next available job
    SELECT * INTO v_job
    FROM write_queue
    WHERE status = 'pending'
        AND scheduled_for <= NOW()
        AND (expires_at IS NULL OR expires_at > NOW())
        AND attempts < max_attempts
        AND (p_circuit_name IS NULL OR circuit_name = p_circuit_name OR circuit_name IS NULL)
    ORDER BY priority DESC, scheduled_for ASC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    -- Update if found
    IF v_job.id IS NOT NULL THEN
        UPDATE write_queue
        SET
            status = 'processing',
            worker_id = p_worker_id,
            started_at = NOW(),
            attempts = attempts + 1,
            updated_at = NOW()
        WHERE id = v_job.id
        RETURNING * INTO v_job;
    END IF;

    RETURN v_job;
END;
$$;

ALTER FUNCTION public.claim_write_job(p_worker_id text, p_circuit_name text) OWNER TO postgres;

CREATE FUNCTION public.cleanup_abandoned_onboarding(p_dry_run boolean DEFAULT false, p_hours_threshold integer DEFAULT 24) RETURNS TABLE(type text, code text, name text, hours_since_start numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    guild_record RECORD;
    cluster_record RECORD;
BEGIN
    -- Find abandoned guild registrations
    FOR guild_record IN
        SELECT
            gc.guild_code,
            gc.display_name,
            EXTRACT(EPOCH FROM (now() - gc.onboarding_started_at)) / 3600 as hours_old
        FROM guild_config gc
        WHERE gc.onboarding_completed = false
          AND gc.onboarding_completed_at IS NULL
          AND gc.api_key_encrypted IS NULL
          AND gc.onboarding_started_at < (now() - (p_hours_threshold || ' hours')::INTERVAL)
          AND NOT is_protected_guild(gc.guild_code)
          -- No data exists
          AND NOT EXISTS (
              SELECT 1 FROM "EOT_GR_data" WHERE "Guild" = gc.guild_code LIMIT 1
          )
          AND NOT EXISTS (
              SELECT 1 FROM player_mapping pm
              WHERE pm.guild_code = gc.guild_code AND pm.is_current = true LIMIT 1
          )
    LOOP
        IF NOT p_dry_run THEN
            DELETE FROM guild_config WHERE guild_code = guild_record.guild_code;

            -- Use ON CONFLICT to ignore duplicate log entries
            INSERT INTO system_logs (log_type, message, metadata)
            VALUES (
                'cleanup_abandoned_onboarding',
                format('Deleted abandoned guild: %s', guild_record.guild_code),
                jsonb_build_object(
                    'guild_code', guild_record.guild_code,
                    'hours_old', guild_record.hours_old
                )
            )
            ON CONFLICT (log_type, message) DO NOTHING;
        END IF;

        RETURN QUERY SELECT
            'guild'::TEXT,
            guild_record.guild_code::TEXT,
            guild_record.display_name::TEXT,
            guild_record.hours_old::NUMERIC;
    END LOOP;

    -- Find abandoned cluster registrations (clusters with no guilds)
    FOR cluster_record IN
        SELECT
            c.cluster_code,
            c.display_name,
            EXTRACT(EPOCH FROM (now() - c.created_at)) / 3600 as hours_old
        FROM clusters c
        WHERE c.created_at < (now() - (p_hours_threshold || ' hours')::INTERVAL)
          -- No guilds in this cluster
          AND NOT EXISTS (
              SELECT 1 FROM guild_config gc WHERE gc.cluster_id = c.id LIMIT 1
          )
    LOOP
        IF NOT p_dry_run THEN
            DELETE FROM clusters WHERE cluster_code = cluster_record.cluster_code;

            -- Use ON CONFLICT to ignore duplicate log entries
            INSERT INTO system_logs (log_type, message, metadata)
            VALUES (
                'cleanup_abandoned_onboarding',
                format('Deleted abandoned cluster: %s', cluster_record.cluster_code),
                jsonb_build_object(
                    'cluster_code', cluster_record.cluster_code,
                    'hours_old', cluster_record.hours_old
                )
            )
            ON CONFLICT (log_type, message) DO NOTHING;
        END IF;

        RETURN QUERY SELECT
            'cluster'::TEXT,
            cluster_record.cluster_code::TEXT,
            cluster_record.display_name::TEXT,
            cluster_record.hours_old::NUMERIC;
    END LOOP;
END;
$$;

ALTER FUNCTION public.cleanup_abandoned_onboarding(p_dry_run boolean, p_hours_threshold integer) OWNER TO postgres;

CREATE FUNCTION public.cleanup_discord_webhook_logs() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM discord_webhook_logs
  WHERE created_at < now() - interval '30 days';

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;

ALTER FUNCTION public.cleanup_discord_webhook_logs() OWNER TO postgres;

CREATE FUNCTION public.cleanup_expired_coaching_task_deliveries_v1(p_batch_size integer DEFAULT 200) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_deleted INTEGER;
BEGIN
  IF p_batch_size < 1 OR p_batch_size > 200 THEN
    RAISE EXCEPTION 'cleanup batch must be between 1 and 200'
      USING ERRCODE = '22023';
  END IF;

  WITH expired AS MATERIALIZED (
    SELECT d.id
    FROM public.coaching_task_deliveries d
    WHERE d.expires_at <= clock_timestamp()
    ORDER BY d.expires_at, d.created_at
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  ),
  tombstoned_unknown AS (
    INSERT INTO public.coaching_task_delivery_dedup(
      task_id,
      destination_id,
      payload_sha256,
      delivered_at
    )
    SELECT
      d.task_id,
      d.destination_id,
      d.payload_sha256,
      clock_timestamp()
    FROM public.coaching_task_deliveries d
    JOIN expired ON expired.id = d.id
    WHERE d.status = 'pending'
    ON CONFLICT (task_id, destination_id, payload_sha256) DO NOTHING
    RETURNING task_id
  )
  DELETE FROM public.coaching_task_deliveries d
  USING expired
  WHERE d.id = expired.id;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;

ALTER FUNCTION public.cleanup_expired_coaching_task_deliveries_v1(p_batch_size integer) OWNER TO postgres;

CREATE FUNCTION public.cleanup_expired_gdpr_data() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    deleted_count INTEGER := 0;
    rows_deleted INTEGER := 0;
BEGIN
    -- Only service_role should invoke cleanup.
    IF current_setting('role', true) <> 'service_role'
       AND auth.role() IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'Forbidden: cleanup requires service role'
            USING ERRCODE = '42501';
    END IF;

    DELETE FROM gdpr_processing_log
    WHERE retention_until IS NOT NULL
      AND retention_until < NOW();
    GET DIAGNOSTICS deleted_count = ROW_COUNT;

    DELETE FROM gdpr_data_exports
    WHERE expires_at IS NOT NULL
      AND expires_at < NOW();
    GET DIAGNOSTICS rows_deleted = ROW_COUNT;
    deleted_count := deleted_count + rows_deleted;

    RETURN deleted_count;
END;
$$;

ALTER FUNCTION public.cleanup_expired_gdpr_data() OWNER TO postgres;

CREATE FUNCTION public.cleanup_incomplete_registrations() RETURNS TABLE(cleaned_count integer, guild_codes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    cleanup_threshold INTERVAL := '24 hours';  -- Reduced from 30 days to 24 hours
    cleaned_guilds TEXT[] := ARRAY[]::TEXT[];
    guild_record RECORD;
    total_cleaned INTEGER := 0;
BEGIN
    -- Find candidates for cleanup: abandoned registrations with no data
    FOR guild_record IN
        SELECT gc.guild_code, gc.onboarding_started_at
        FROM guild_config gc
        WHERE gc.onboarding_completed = false
          AND gc.onboarding_completed_at IS NULL
          AND gc.api_key_encrypted IS NULL  -- No API key ever set
          AND gc.onboarding_started_at < (now() - cleanup_threshold)
          AND NOT is_protected_guild(gc.guild_code)
          -- No battle data exists
          AND NOT EXISTS (
              SELECT 1 FROM "EOT_GR_data"
              WHERE "Guild" = gc.guild_code
              LIMIT 1
          )
          -- No player mappings exist
          AND NOT EXISTS (
              SELECT 1 FROM player_mapping pm
              WHERE pm.guild_code = gc.guild_code
                AND pm.is_current = true
              LIMIT 1
          )
    LOOP
        -- Delete the incomplete registration
        DELETE FROM guild_config
        WHERE guild_code = guild_record.guild_code;

        -- Track what we cleaned
        cleaned_guilds := array_append(cleaned_guilds, guild_record.guild_code);
        total_cleaned := total_cleaned + 1;

        -- Log the cleanup action
        INSERT INTO system_logs (log_type, message, metadata)
        VALUES (
            'cleanup_incomplete_registrations',
            format('Cleaned up abandoned onboarding for guild %s (age: %s)',
                   guild_record.guild_code,
                   age(now(), guild_record.onboarding_started_at)),
            jsonb_build_object(
                'guild_code', guild_record.guild_code,
                'onboarding_started_at', guild_record.onboarding_started_at,
                'cleanup_time', now(),
                'threshold', '24 hours'
            )
        );
    END LOOP;

    -- Log summary if anything was cleaned
    IF total_cleaned > 0 THEN
        INSERT INTO system_logs (log_type, message, metadata)
        VALUES (
            'cleanup_incomplete_registrations',
            format('Cleanup completed: %s abandoned guilds removed', total_cleaned),
            jsonb_build_object(
                'total_cleaned', total_cleaned,
                'guild_codes', cleaned_guilds,
                'cleanup_time', now(),
                'threshold', '24 hours'
            )
        );
    END IF;

    RETURN QUERY SELECT total_cleaned, cleaned_guilds;
END;
$$;

ALTER FUNCTION public.cleanup_incomplete_registrations() OWNER TO postgres;

CREATE FUNCTION public.cleanup_old_sync_data() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_deleted INTEGER := 0;
  v_count INTEGER;
BEGIN
  -- Convert zombie pending rows to failed so they no longer block enqueue/claim.
  UPDATE sync_queue
  SET
    status = 'failed',
    completed_at = COALESCE(completed_at, NOW()),
    updated_at = NOW(),
    error_log = COALESCE(error_log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'attempt', attempts,
      'error', 'Auto-failed zombie pending job during cleanup (attempts >= max_attempts)',
      'timestamp', NOW()
    ))
  WHERE status = 'pending'
    AND attempts >= max_attempts;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted + v_count;

  -- Delete old completed jobs (24 hours — metrics live in sync_metrics)
  DELETE FROM sync_queue
  WHERE status = 'completed'
    AND completed_at < NOW() - INTERVAL '24 hours';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted + v_count;

  -- Delete old failed jobs (3 days — keep for debugging)
  DELETE FROM sync_queue
  WHERE status = 'failed'
    AND completed_at < NOW() - INTERVAL '3 days';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted + v_count;

  -- Delete expired locks
  DELETE FROM execution_locks
  WHERE expires_at < NOW() - INTERVAL '1 hour';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted + v_count;

  -- Delete old metrics
  DELETE FROM sync_metrics
  WHERE created_at < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted + v_count;

  RETURN v_deleted;
END;
$$;

ALTER FUNCTION public.cleanup_old_sync_data() OWNER TO postgres;

CREATE FUNCTION public.cleanup_orphaned_guilds() RETURNS TABLE(cleaned_count integer, guild_codes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
    cleanup_threshold INTERVAL := '24 hours';
    cleaned_guilds TEXT[] := ARRAY[]::TEXT[];
    guild_record RECORD;
    total_cleaned INTEGER := 0;
BEGIN
    FOR guild_record IN
        SELECT
            gc.guild_code,
            gc.display_name,
            gc.onboarding_started_at,
            gc.last_successful_sync
        FROM guild_config gc
        WHERE gc.onboarding_started_at < (now() - cleanup_threshold)
          AND NOT is_protected_guild(gc.guild_code)
          AND gc.last_successful_sync IS NOT NULL
          AND NOT EXISTS (
              SELECT 1 FROM player_mapping pm
              WHERE pm.guild_code = gc.guild_code
                AND pm.is_current = true
                AND pm.user_id IS NOT NULL
              LIMIT 1
          )
          AND gc.cluster_id IS NULL
    LOOP
        -- Delete battle data first
        DELETE FROM "EOT_GR_data" WHERE "Guild" = guild_record.guild_code AND ("Season" !~ '^[0-9]+$' OR "Season"::int < 71);

        -- Delete guild war leaderboards (FK constraint fix)
        DELETE FROM guild_war_leaderboards WHERE guild_code = guild_record.guild_code;

        -- Delete player mappings (unclaimed profiles)
        DELETE FROM player_mapping WHERE guild_code = guild_record.guild_code;

        -- Delete any pending invite codes
        DELETE FROM player_invite_codes WHERE guild_code = guild_record.guild_code;

        -- Delete the guild config
        DELETE FROM guild_config WHERE guild_code = guild_record.guild_code;

        cleaned_guilds := array_append(cleaned_guilds, guild_record.guild_code);
        total_cleaned := total_cleaned + 1;

        INSERT INTO system_logs (log_type, message, metadata)
        VALUES (
            'cleanup_orphaned_guilds',
            format('Cleaned up orphaned guild %s (synced but no users claimed profiles)', guild_record.guild_code),
            jsonb_build_object(
                'guild_code', guild_record.guild_code,
                'display_name', guild_record.display_name,
                'onboarding_started_at', guild_record.onboarding_started_at,
                'last_successful_sync', guild_record.last_successful_sync,
                'cleanup_time', now(),
                'reason', 'No users claimed profiles within 24 hours of registration'
            )
        )
        ON CONFLICT DO NOTHING;
    END LOOP;

    IF total_cleaned > 0 THEN
        INSERT INTO system_logs (log_type, message, metadata)
        VALUES (
            'cleanup_orphaned_guilds',
            format('Orphaned guild cleanup completed: %s guilds removed', total_cleaned),
            jsonb_build_object(
                'total_cleaned', total_cleaned,
                'guild_codes', cleaned_guilds,
                'cleanup_time', now()
            )
        )
        ON CONFLICT DO NOTHING;
    END IF;

    RETURN QUERY SELECT total_cleaned, cleaned_guilds;
END;
$_$;

ALTER FUNCTION public.cleanup_orphaned_guilds() OWNER TO postgres;

CREATE FUNCTION public.cleanup_work_queue() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  WITH deleted AS (
    DELETE FROM public.work_queue
    WHERE (status = 'completed' AND completed_at < now() - INTERVAL '48 hours')
       OR (status = 'dead'      AND completed_at < now() - INTERVAL '7 days')
    RETURNING id
  )
  SELECT COUNT(*)::int INTO v_count FROM deleted;
  RETURN v_count;
END;
$$;

ALTER FUNCTION public.cleanup_work_queue() OWNER TO postgres;

CREATE FUNCTION public.cleanup_write_queue(p_completed_retention interval DEFAULT '7 days'::interval, p_failed_retention interval DEFAULT '30 days'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_deleted INTEGER := 0;
    v_count INTEGER;
BEGIN
    -- Mark expired pending jobs
    UPDATE write_queue
    SET status = 'expired', updated_at = NOW()
    WHERE status = 'pending' AND expires_at < NOW();

    -- Delete old completed jobs
    DELETE FROM write_queue
    WHERE status = 'completed' AND completed_at < NOW() - p_completed_retention;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted + v_count;

    -- Delete old failed/expired jobs
    DELETE FROM write_queue
    WHERE status IN ('failed', 'expired') AND updated_at < NOW() - p_failed_retention;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted + v_count;

    RETURN v_deleted;
END;
$$;

ALTER FUNCTION public.cleanup_write_queue(p_completed_retention interval, p_failed_retention interval) OWNER TO postgres;

CREATE FUNCTION public.clear_season_assignments(p_guild_code text, p_season_number text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_role TEXT;
  v_user_guild_code TEXT;
  v_user_cluster TEXT;
  v_target_cluster TEXT;
  v_assignments_deleted INTEGER := 0;
  v_bosses_deleted INTEGER := 0;
BEGIN
  IF p_guild_code IS NULL OR btrim(p_guild_code) = '' THEN
    RAISE EXCEPTION 'Invalid guild code';
  END IF;

  IF p_season_number IS NULL OR btrim(p_season_number) = '' THEN
    RAISE EXCEPTION 'Invalid season number';
  END IF;

  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Auth required';
    END IF;

    SELECT role, guild_code
      INTO v_user_role, v_user_guild_code
    FROM player_mapping
    WHERE user_id = auth.uid()
      AND is_current = true
    LIMIT 1;

    IF v_user_role IS NULL THEN
      RAISE EXCEPTION 'User profile not found';
    END IF;

    IF v_user_role NOT IN ('officer', 'leader') THEN
      RAISE EXCEPTION 'Insufficient permissions';
    END IF;

    IF v_user_role = 'officer' THEN
      IF v_user_guild_code IS DISTINCT FROM p_guild_code THEN
        RAISE EXCEPTION 'Access denied for guild';
      END IF;
    ELSE
      SELECT gc.cluster_code INTO v_user_cluster
      FROM guild_config gc
      WHERE gc.guild_code = v_user_guild_code;

      SELECT gc.cluster_code INTO v_target_cluster
      FROM guild_config gc
      WHERE gc.guild_code = p_guild_code;

      IF v_user_guild_code IS DISTINCT FROM p_guild_code AND
         (v_user_cluster IS NULL OR v_target_cluster IS NULL OR v_user_cluster != v_target_cluster) THEN
        RAISE EXCEPTION 'Access denied for cluster';
      END IF;
    END IF;
  END IF;

  DELETE FROM upcoming_season_assignments
  WHERE guild_code = p_guild_code
    AND season_number = p_season_number;
  GET DIAGNOSTICS v_assignments_deleted = ROW_COUNT;

  DELETE FROM upcoming_season_bosses
  WHERE guild_code = p_guild_code
    AND season_number = p_season_number;
  GET DIAGNOSTICS v_bosses_deleted = ROW_COUNT;

  BEGIN
    INSERT INTO audit_logs (action, user_id, details)
    VALUES (
      'assignment_clear',
      auth.uid(),
      jsonb_build_object(
        'guild_code', p_guild_code,
        'season', p_season_number,
        'assignments_deleted', v_assignments_deleted,
        'bosses_deleted', v_bosses_deleted
      )
    );
  EXCEPTION WHEN OTHERS THEN
    -- Ignore audit log failures
  END;

  RETURN jsonb_build_object(
    'assignmentsDeleted', v_assignments_deleted,
    'bossesDeleted', v_bosses_deleted
  );
END;
$$;

ALTER FUNCTION public.clear_season_assignments(p_guild_code text, p_season_number text) OWNER TO postgres;

CREATE FUNCTION public.compare_guilds(p_guilds text[], p_season text DEFAULT NULL::text) RETURNS TABLE("Guild" text, "Season" text, player_count bigint, guild_total_damage bigint, guild_avg_damage_per_hit double precision, guild_avg_damage_per_player double precision, max_loop_reached integer, unique_bosses_hit bigint, damage_types_used text[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_season IS NULL THEN
        RETURN QUERY
        SELECT * FROM public.guild_season_summary
        WHERE "Guild" = ANY(p_guilds)
        ORDER BY "Season", "Guild";
    ELSE
        RETURN QUERY
        SELECT * FROM public.guild_season_summary
        WHERE "Guild" = ANY(p_guilds) AND "Season" = p_season
        ORDER BY "Guild";
    END IF;
END;
$$;

ALTER FUNCTION public.compare_guilds(p_guilds text[], p_season text) OWNER TO postgres;

CREATE FUNCTION public.complete_coaching_task_delivery_v1(p_delivery_id uuid, p_actor_user_id uuid, p_status text, p_provider_status smallint DEFAULT NULL::smallint, p_error_code text DEFAULT NULL::text) RETURNS TABLE(delivery_id uuid, request_id uuid, delivery_status text, provider_status smallint, error_code text, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_delivery public.coaching_task_deliveries%ROWTYPE;
BEGIN
  IF p_status NOT IN ('delivered', 'failed')
    OR (p_provider_status IS NOT NULL
      AND p_provider_status NOT BETWEEN 100 AND 599)
    OR (p_error_code IS NOT NULL
      AND length(p_error_code) NOT BETWEEN 1 AND 64)
  THEN
    RAISE EXCEPTION 'invalid coaching delivery completion input'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.coaching_task_deliveries d
  SET status = p_status,
      provider_status = p_provider_status,
      error_code = p_error_code,
      completed_at = clock_timestamp()
  WHERE d.id = p_delivery_id
    AND d.actor_user_id = p_actor_user_id
    AND d.status = 'pending'
  RETURNING d.* INTO v_delivery;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_delivery.status = 'delivered' THEN
    INSERT INTO public.coaching_task_delivery_dedup(
      task_id,
      destination_id,
      payload_sha256,
      delivered_at
    )
    VALUES (
      v_delivery.task_id,
      v_delivery.destination_id,
      v_delivery.payload_sha256,
      v_delivery.completed_at
    )
    ON CONFLICT (task_id, destination_id, payload_sha256) DO NOTHING;
  END IF;

  RETURN QUERY SELECT
    v_delivery.id,
    v_delivery.request_id,
    v_delivery.status,
    v_delivery.provider_status,
    v_delivery.error_code,
    v_delivery.completed_at;
END;
$$;

ALTER FUNCTION public.complete_coaching_task_delivery_v1(p_delivery_id uuid, p_actor_user_id uuid, p_status text, p_provider_status smallint, p_error_code text) OWNER TO postgres;

CREATE FUNCTION public.complete_job(p_job_id uuid, p_worker_id text, p_progress jsonb DEFAULT '{}'::jsonb, p_metrics jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_guild_code TEXT;
  v_job_type TEXT;
  v_started_at TIMESTAMPTZ;
BEGIN
  SELECT guild_code, job_type, started_at
  INTO v_guild_code, v_job_type, v_started_at
  FROM sync_queue
  WHERE id = p_job_id AND worker_id = p_worker_id;

  IF NOT FOUND THEN
    RETURN FALSE;
  END IF;

  UPDATE sync_queue
  SET
    status = 'completed',
    completed_at = NOW(),
    progress = p_progress,
    updated_at = NOW()
  WHERE id = p_job_id;

  IF v_job_type IN ('full_sync', 'incremental_sync', 'realtime_sync') THEN
    UPDATE guild_sync_status
    SET
      last_sync = NOW(),
      status = 'completed',
      records_synced = COALESCE((p_progress->>'records_processed')::INT, 0),
      error_message = NULL,
      last_error = NULL,
      updated_at = NOW()
    WHERE guild_code = v_guild_code;

    IF v_job_type = 'full_sync' THEN
      UPDATE guild_sync_status
      SET
        full_sync_at = NOW(),
        full_sync_success = TRUE
      WHERE guild_code = v_guild_code;
    END IF;
  ELSE
    UPDATE guild_sync_status
    SET
      status = 'completed',
      error_message = NULL,
      last_error = NULL,
      updated_at = NOW()
    WHERE guild_code = v_guild_code;
  END IF;

  INSERT INTO sync_metrics (
    guild_code, job_id, job_type,
    processing_time_ms,
    records_processed,
    players_updated,
    success
  ) VALUES (
    v_guild_code, p_job_id, v_job_type,
    EXTRACT(EPOCH FROM (NOW() - v_started_at)) * 1000,
    COALESCE((p_metrics->>'records_processed')::INT, 0),
    COALESCE((p_metrics->>'players_updated')::INT, 0),
    TRUE
  );

  PERFORM update_sync_health(v_guild_code, TRUE);

  RETURN TRUE;
END;
$$;

ALTER FUNCTION public.complete_job(p_job_id uuid, p_worker_id text, p_progress jsonb, p_metrics jsonb) OWNER TO postgres;

CREATE FUNCTION public.complete_work_job(p_job_id bigint, p_worker_id text, p_result jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_updated int;
BEGIN
  UPDATE public.work_queue
  SET status       = 'completed',
      completed_at = now(),
      payload      = payload || jsonb_build_object('result', p_result),
      updated_at   = now()
  WHERE id = p_job_id
    AND claimed_by = p_worker_id
    AND status = 'processing';
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated = 1;
END;
$$;

ALTER FUNCTION public.complete_work_job(p_job_id bigint, p_worker_id text, p_result jsonb) OWNER TO postgres;

CREATE FUNCTION public.complete_write_job(p_job_id uuid, p_success boolean DEFAULT true, p_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_job write_queue;
BEGIN
    SELECT * INTO v_job FROM write_queue WHERE id = p_job_id FOR UPDATE;

    IF v_job.id IS NULL THEN
        RETURN false;
    END IF;

    IF p_success THEN
        UPDATE write_queue
        SET
            status = 'completed',
            completed_at = NOW(),
            updated_at = NOW()
        WHERE id = p_job_id;
    ELSE
        -- Check if we should retry or fail permanently
        IF v_job.attempts >= v_job.max_attempts THEN
            UPDATE write_queue
            SET
                status = 'failed',
                last_error = p_error,
                error_log = error_log || jsonb_build_object(
                    'attempt', v_job.attempts,
                    'error', p_error,
                    'timestamp', NOW()
                ),
                completed_at = NOW(),
                updated_at = NOW()
            WHERE id = p_job_id;
        ELSE
            -- Return to pending for retry (with backoff)
            UPDATE write_queue
            SET
                status = 'pending',
                last_error = p_error,
                error_log = error_log || jsonb_build_object(
                    'attempt', v_job.attempts,
                    'error', p_error,
                    'timestamp', NOW()
                ),
                scheduled_for = NOW() + (INTERVAL '1 second' * POWER(2, v_job.attempts)), -- Exponential backoff
                worker_id = NULL,
                started_at = NULL,
                updated_at = NOW()
            WHERE id = p_job_id;
        END IF;
    END IF;

    RETURN true;
END;
$$;

ALTER FUNCTION public.complete_write_job(p_job_id uuid, p_success boolean, p_error text) OWNER TO postgres;

CREATE FUNCTION public.compute_player_token_burn(p_guild_code text, p_season text, p_player_id text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(burned_tokens integer, time_over_cap_seconds integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_max_tokens integer := 3;
  v_starting_tokens integer := 2;
  v_regen_seconds bigint := 12 * 60 * 60;
  v_season_start_at timestamptz;
  v_season_end_at timestamptz;
  v_effective_now timestamptz;
  v_effective_now_secs bigint;
  v_tokens integer;
  v_refresh_time bigint;
  v_burned_total bigint := 0;
  v_over_cap_secs bigint := 0;
  v_battle record;
  v_battle_ts bigint;
  v_n_recharged integer;
  v_excess integer;
  v_prev_tokens integer;
  v_cap_start bigint;
begin
  if p_guild_code is null or p_season is null or p_player_id is null then
    return query select 0::integer, 0::integer;
    return;
  end if;

  -- Resolve season window. Prefer calendar; fall back to battle data.
  if to_regclass('public.season_calendar') is not null
     and p_season ~ '^\d+$' then
    select sc.starts_at, sc.ends_at
    into v_season_start_at, v_season_end_at
    from public.season_calendar sc
    where sc.season_id = p_season::integer
    limit 1;
  end if;

  if v_season_start_at is null then
    select min(d."startedOn")
    into v_season_start_at
    from public."EOT_GR_data" d
    where d."Guild" = p_guild_code
      and d."Season" = p_season
      and d."startedOn" is not null;
  end if;

  if v_season_end_at is null and p_season ~ '^\d+$' then
    select min(d."startedOn")
    into v_season_end_at
    from public."EOT_GR_data" d
    where d."Guild" = p_guild_code
      and d."Season" = (p_season::integer + 1)::text
      and d."startedOn" is not null;
  end if;

  v_effective_now := coalesce(p_now, now());
  if v_season_end_at is not null and v_effective_now > v_season_end_at then
    v_effective_now := v_season_end_at;
  end if;
  v_effective_now_secs := extract(epoch from v_effective_now)::bigint;

  -- WI-859: anchor at season_start so pre-first-battle over-cap accrues
  -- correctly. Fall back to null (then to first-battle in-loop) only when
  -- we have no season window at all.
  v_tokens := v_starting_tokens;
  if v_season_start_at is not null then
    v_refresh_time := extract(epoch from v_season_start_at)::bigint;
  else
    v_refresh_time := null;
  end if;

  for v_battle in
    select distinct d."startedOn"::timestamptz as battle_time
    from public."EOT_GR_data" d
    where d."userId" = p_player_id
      and d."Guild" = p_guild_code
      and d."Season" = p_season
      and d."damageType" = 'Battle'
      and d."startedOn" is not null
    order by d."startedOn"::timestamptz asc
  loop
    v_battle_ts := extract(epoch from v_battle.battle_time)::bigint;

    -- Defensive: if season_start was unknown, fall back to first battle
    -- as the anchor (legacy WI-847 behavior).
    if v_refresh_time is null then
      v_refresh_time := v_battle_ts;
    end if;

    if v_battle_ts > v_effective_now_secs then
      exit;
    end if;

    -- Tokens at loop entry are always under MAX (a prior cap-hit always
    -- deducts to MAX-1 before next iteration), so we don't need a separate
    -- "already at cap" branch.
    v_n_recharged := floor((v_battle_ts - v_refresh_time)::numeric / v_regen_seconds)::integer;
    if v_n_recharged > 0 then
      if v_n_recharged + v_tokens >= v_max_tokens then
        v_cap_start := v_refresh_time + (v_max_tokens - v_tokens)::bigint * v_regen_seconds;
        v_excess := v_n_recharged + v_tokens - v_max_tokens;
        if v_excess > 0 then
          v_burned_total := v_burned_total + v_excess;
        end if;
        v_over_cap_secs := v_over_cap_secs + greatest(0, v_battle_ts - v_cap_start);
        v_tokens := v_max_tokens;
        v_refresh_time := v_battle_ts;
      else
        v_tokens := v_tokens + v_n_recharged;
        v_refresh_time := v_refresh_time + v_n_recharged::bigint * v_regen_seconds;
      end if;
    end if;

    v_prev_tokens := v_tokens;
    v_tokens := v_tokens - 1;

    if v_prev_tokens = v_max_tokens then
      v_refresh_time := v_battle_ts;
    end if;

    if v_tokens < 0 then v_tokens := 0; end if;
  end loop;

  -- Tail accrual between final battle (or season start, if no battles)
  -- and effective_now.
  if v_refresh_time is not null and v_tokens < v_max_tokens then
    v_n_recharged := floor((v_effective_now_secs - v_refresh_time)::numeric / v_regen_seconds)::integer;
    if v_n_recharged > 0 then
      if v_n_recharged + v_tokens >= v_max_tokens then
        v_cap_start := v_refresh_time + (v_max_tokens - v_tokens)::bigint * v_regen_seconds;
        v_excess := v_n_recharged + v_tokens - v_max_tokens;
        if v_excess > 0 then
          v_burned_total := v_burned_total + v_excess;
        end if;
        v_over_cap_secs := v_over_cap_secs + greatest(0, v_effective_now_secs - v_cap_start);
      else
        v_tokens := v_tokens + v_n_recharged;
        v_refresh_time := v_refresh_time + v_n_recharged::bigint * v_regen_seconds;
      end if;
    end if;
  end if;

  return query select greatest(0, v_burned_total)::integer,
                      greatest(0, v_over_cap_secs)::integer;
end;
$_$;

ALTER FUNCTION public.compute_player_token_burn(p_guild_code text, p_season text, p_player_id text, p_now timestamp with time zone) OWNER TO postgres;

CREATE FUNCTION public.compute_player_tokens_available(p_guild_code text, p_season text, p_player_id text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(tokens_available integer, token_next_in_seconds integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_max_tokens integer := 3;
  v_initial_tokens integer := 2;
  v_regen_seconds bigint := 12 * 60 * 60;
  v_season_start_at timestamptz;
  v_now_secs bigint;
  v_count integer;
  v_refresh_time bigint;
  v_battle record;
  v_battle_ts bigint;
  v_n_recharged integer;
  v_prev_count integer;
  v_first_battle_ts bigint := null;
  v_time_since_refresh bigint;
  v_time_until_next bigint;
begin
  if p_guild_code is null or p_season is null or p_player_id is null then
    return query select v_max_tokens::integer, 0::integer;
    return;
  end if;

  v_now_secs := extract(epoch from coalesce(p_now, now()))::bigint;

  -- Resolve season_start for the "no battles yet" branch.
  if to_regclass('public.season_calendar') is not null
     and p_season ~ '^\d+$' then
    select sc.starts_at into v_season_start_at
    from public.season_calendar sc
    where sc.season_id = p_season::integer
    limit 1;
  end if;

  -- Find the first battle so we can branch on "has battles" vs "no battles".
  select extract(epoch from min(d."startedOn"::timestamptz))::bigint
    into v_first_battle_ts
  from public."EOT_GR_data" d
  where d."userId" = p_player_id
    and d."Guild" = p_guild_code
    and d."Season" = p_season
    and d."damageType" = 'Battle'
    and d."startedOn" is not null;

  if v_first_battle_ts is null then
    -- No battles yet this season. Mirror calculateTokenAvailability's
    -- "no battles" branch: anchor at season_start (if known), regen to
    -- current time, otherwise assume full tokens.
    if v_season_start_at is not null then
      v_count := v_initial_tokens;
      v_refresh_time := extract(epoch from v_season_start_at)::bigint;
      v_n_recharged := floor((v_now_secs - v_refresh_time)::numeric / v_regen_seconds)::integer;
      if v_n_recharged + v_count >= v_max_tokens then
        v_count := v_max_tokens;
        v_refresh_time := v_now_secs;
      else
        v_count := v_count + v_n_recharged;
        v_refresh_time := v_refresh_time + v_n_recharged::bigint * v_regen_seconds;
      end if;
    else
      v_count := v_max_tokens;
      v_refresh_time := v_now_secs;
    end if;
  else
    -- Has battles. Anchor at first battle per calculateTokenAvailability:
    -- "Refresh timer starts at first battle time since they're not at max".
    v_count := v_initial_tokens;
    v_refresh_time := v_first_battle_ts;

    -- Walk every battle (including the first) chronologically.
    for v_battle in
      select distinct d."startedOn"::timestamptz as battle_time
      from public."EOT_GR_data" d
      where d."userId" = p_player_id
        and d."Guild" = p_guild_code
        and d."Season" = p_season
        and d."damageType" = 'Battle'
        and d."startedOn" is not null
      order by d."startedOn"::timestamptz asc
    loop
      v_battle_ts := extract(epoch from v_battle.battle_time)::bigint;

      -- evaluateToken at battle_ts (regen-since-refresh, cap at max).
      if v_count < v_max_tokens then
        v_n_recharged := floor((v_battle_ts - v_refresh_time)::numeric / v_regen_seconds)::integer;
        if v_n_recharged + v_count >= v_max_tokens then
          v_count := v_max_tokens;
          v_refresh_time := v_battle_ts;
        else
          v_count := v_count + v_n_recharged;
          v_refresh_time := v_refresh_time + v_n_recharged::bigint * v_regen_seconds;
        end if;
      end if;

      v_prev_count := v_count;
      v_count := v_count - 1;
      if v_count <= 0 then
        v_count := 0;
        -- Only reset timer when transitioning positive -> 0 (per the TS
        -- implementation's exact comment).
        if v_prev_count > 0 then
          v_refresh_time := v_battle_ts;
        end if;
      end if;
    end loop;

    -- Final evaluateToken at now.
    if v_count < v_max_tokens then
      v_n_recharged := floor((v_now_secs - v_refresh_time)::numeric / v_regen_seconds)::integer;
      if v_n_recharged + v_count >= v_max_tokens then
        v_count := v_max_tokens;
        v_refresh_time := v_now_secs;
      else
        v_count := v_count + v_n_recharged;
        v_refresh_time := v_refresh_time + v_n_recharged::bigint * v_regen_seconds;
      end if;
    end if;
  end if;

  -- Compute token_next_in_seconds — same formula as the TS algo.
  v_time_until_next := null;
  if v_count < v_max_tokens then
    v_time_since_refresh := v_now_secs - v_refresh_time;
    v_time_until_next := v_regen_seconds - (v_time_since_refresh % v_regen_seconds);
    if v_time_until_next <= 0 or v_time_until_next >= v_regen_seconds then
      v_time_until_next := null;
    end if;
  end if;

  return query select
    least(v_max_tokens, greatest(0, v_count))::integer,
    case
      when v_time_until_next is null then null::integer
      else v_time_until_next::integer
    end;
end;
$_$;

ALTER FUNCTION public.compute_player_tokens_available(p_guild_code text, p_season text, p_player_id text, p_now timestamp with time zone) OWNER TO postgres;

CREATE FUNCTION public.confirm_discord_identity_unlink(p_unlink_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_identity_present boolean;
  v_pending record;
  v_cleared integer;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '42501';
  END IF;
  IF p_unlink_id IS NULL THEN
    RAISE EXCEPTION 'Unlink generation is required'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(6208, hashtext(v_user_id::text));
  SELECT pending.id, pending.generation
  INTO v_pending
  FROM public.player_identity_discord_unlink_pending AS pending
  WHERE pending.id = p_unlink_id
    AND pending.subject_user_id = v_user_id
    AND pending.generation = (
      SELECT max(latest.generation)
      FROM public.player_identity_discord_unlink_pending AS latest
      WHERE latest.subject_user_id = v_user_id
    )
  FOR UPDATE;
  IF NOT FOUND OR EXISTS (
    SELECT 1
    FROM public.player_identity_discord_generation_activations AS activation
    WHERE activation.pending_id = p_unlink_id
  ) THEN
    RAISE EXCEPTION 'Unlink generation is stale or already superseded'
      USING ERRCODE = '55000';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM auth.identities AS identity
    WHERE identity.user_id = v_user_id AND identity.provider = 'discord'
  ) INTO v_identity_present;

  IF v_identity_present THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Discord identity is still linked',
      'error_code', 'IDENTITY_STILL_LINKED'
    );
  END IF;

  UPDATE public.player_mapping AS mapping
  SET discord_user_id = NULL,
      discord_username = NULL,
      updated_at = clock_timestamp()
  WHERE mapping.user_id = v_user_id
    AND (mapping.discord_user_id IS NOT NULL
         OR mapping.discord_username IS NOT NULL);
  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  UPDATE auth.users AS target
  SET raw_user_meta_data = coalesce(target.raw_user_meta_data, '{}'::jsonb)
    - 'discord_user_id' - 'discord_username' - 'discord_synced'
  WHERE target.id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'unlink_id', p_unlink_id,
    'generation', v_pending.generation,
    'identity_absent', true,
    'cleared_mappings', v_cleared,
    'relink_requires_nonce', true
  );
END
$$;

ALTER FUNCTION public.confirm_discord_identity_unlink(p_unlink_id uuid) OWNER TO postgres;

CREATE FUNCTION public.count_veteran_players(p_guild_code text) RETURNS TABLE(total_veterans bigint, veteran_details jsonb)
    LANGUAGE plpgsql
    AS $_$
BEGIN
  RETURN QUERY
  WITH player_seasons AS (
    SELECT
      e."userId" as player_id,
      pm.display_name as current_player_name,
      COUNT(DISTINCT e."Season") as season_count
    FROM "EOT_GR_data" e
    LEFT JOIN player_mapping pm ON e."userId" = pm.player_id AND pm.is_current = true
    WHERE e."Guild" = p_guild_code
      AND e."damageDealt" > 0
      AND e."Season" ~ '^\d+$'
      AND e."userId" IS NOT NULL
    GROUP BY e."userId", pm.display_name
    HAVING COUNT(DISTINCT e."Season") >= 5
  ),
  veteran_stats AS (
    SELECT
      COUNT(*) as total_veterans,
      jsonb_agg(
        jsonb_build_object(
          'player_id', ps.player_id,
          'player_name', COALESCE(ps.current_player_name, 'Unknown Player'),
          'seasons_played', ps.season_count
        )
        ORDER BY ps.season_count DESC, ps.current_player_name
      ) as veteran_details
    FROM player_seasons ps
  )
  SELECT
    vs.total_veterans,
    vs.veteran_details
  FROM veteran_stats vs;
END;
$_$;

ALTER FUNCTION public.count_veteran_players(p_guild_code text) OWNER TO postgres;

