CREATE FUNCTION public.create_player_invite_code(p_mapping_id bigint, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_caller record;
  v_target record;
  v_invite_id uuid := gen_random_uuid();
  v_code text;
  v_attempt integer;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '42501';
  END IF;
  IF p_mapping_id IS NULL OR p_mapping_id < -2147483648
     OR p_mapping_id > 2147483647
     OR p_expires_at IS NULL
     OR p_expires_at < clock_timestamp() + interval '5 minutes'
     OR p_expires_at > clock_timestamp() + interval '30 days'
  THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Invalid mapping or expiry',
      'error_code', 'INVALID_INPUT'
    );
  END IF;

  SELECT count(*)::integer AS match_count,
         (array_agg(verified.guild_code ORDER BY verified.mapping_id))[1]
           AS guild_code,
         (array_agg(verified.role ORDER BY verified.mapping_id))[1] AS role,
         bool_or(verified.is_app_admin) AS is_app_admin
  INTO v_caller
  FROM public.resolve_verified_players(ARRAY[v_user_id]) AS verified;
  IF v_caller.match_count <> 1 THEN
    RAISE EXCEPTION 'Verified player ownership required'
      USING ERRCODE = '42501';
  END IF;

  SELECT mapping.id, mapping.player_id, mapping.display_name,
         mapping.guild_code, mapping.user_id
  INTO v_target
  FROM public.player_mapping AS mapping
  WHERE mapping.id = p_mapping_id::integer
    AND mapping.is_current IS TRUE
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Current player mapping not found',
      'error_code', 'NOT_FOUND'
    );
  END IF;
  IF v_target.user_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Player profile is already claimed',
      'error_code', 'ALREADY_CLAIMED'
    );
  END IF;
  IF NOT v_caller.is_app_admin
    AND (
      lower(v_caller.role::text) NOT IN ('leader', 'officer')
      OR v_caller.guild_code IS DISTINCT FROM v_target.guild_code
    )
  THEN
    RAISE EXCEPTION 'Invite creation is limited to caller-owned guild authority'
      USING ERRCODE = '42501';
  END IF;

  FOR v_attempt IN 1..8 LOOP
    v_code := upper(encode(extensions.gen_random_bytes(6), 'hex'));
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.player_invite_codes AS invite
      WHERE invite.code = v_code
    );
  END LOOP;
  IF EXISTS (
    SELECT 1 FROM public.player_invite_codes AS invite
    WHERE invite.code = v_code
  ) THEN
    RAISE EXCEPTION 'Could not allocate a unique invite code'
      USING ERRCODE = '40001';
  END IF;

  INSERT INTO public.player_invite_codes (
    id, code, player_id, display_name, guild_code,
    created_by, created_at, expires_at
  ) VALUES (
    v_invite_id, v_code, v_target.player_id, v_target.display_name,
    v_target.guild_code, v_user_id, clock_timestamp(), p_expires_at
  );

  RETURN jsonb_build_object(
    'success', true,
    'invite_id', v_invite_id,
    'code', v_code,
    'expires_at', p_expires_at,
    'player_name', v_target.display_name,
    'guild_code', v_target.guild_code
  );
END
$$;

ALTER FUNCTION public.create_player_invite_code(p_mapping_id bigint, p_expires_at timestamp with time zone) OWNER TO postgres;

