CREATE FUNCTION public.debug_auth_system(p_user_id uuid DEFAULT NULL::uuid, p_player_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_result JSONB;
  v_user_count INTEGER;
  v_player_count INTEGER;
  v_current_user UUID;
BEGIN
  -- Get current user if not provided
  v_current_user := COALESCE(p_user_id, auth.uid());

  -- Count users
  SELECT COUNT(*) INTO v_user_count FROM auth.users;

  -- Count player mappings
  SELECT COUNT(*) INTO v_player_count FROM player_mapping WHERE is_current = true;

  v_result := jsonb_build_object(
    'debug_timestamp', NOW(),
    'total_users', v_user_count,
    'total_current_players', v_player_count,
    'current_user_id', v_current_user,
    'functions_exist', jsonb_build_object(
      'get_user_auth_context', EXISTS(
        SELECT 1 FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE p.proname = 'get_user_auth_context' AND n.nspname = 'public'
      ),
      'verify_player_for_claim', EXISTS(
        SELECT 1 FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE p.proname = 'verify_player_for_claim' AND n.nspname = 'public'
      ),
      'claim_player_mapping_v2', EXISTS(
        SELECT 1 FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE p.proname = 'claim_player_mapping_v2' AND n.nspname = 'public'
      )
    )
  );

  -- Add user-specific info if user provided
  IF v_current_user IS NOT NULL THEN
    v_result := v_result || jsonb_build_object(
      'user_profile_exists', EXISTS(
        SELECT 1 FROM player_mapping
        WHERE user_id = v_current_user AND is_current = true
      )
    );
  END IF;

  -- Add player-specific info if player ID provided
  IF p_player_id IS NOT NULL THEN
    v_result := v_result || jsonb_build_object(
      'player_exists', EXISTS(
        SELECT 1 FROM player_mapping
        WHERE LOWER(player_id) = LOWER(p_player_id) AND is_current = true
      ),
      'player_claimed', EXISTS(
        SELECT 1 FROM player_mapping
        WHERE LOWER(player_id) = LOWER(p_player_id)
        AND is_current = true
        AND user_id IS NOT NULL
      )
    );
  END IF;

  RETURN v_result;
END;
$$;

ALTER FUNCTION public.debug_auth_system(p_user_id uuid, p_player_id text) OWNER TO postgres;

CREATE FUNCTION public.debug_jwt_claims() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN jsonb_build_object(
    'claim_sub', current_setting('request.jwt.claim.sub', true),
    'claim_role', current_setting('request.jwt.claim.role', true),
    'claims_json', current_setting('request.jwt.claims', true),
    'auth_uid', auth.uid()::text,
    'auth_role', auth.role()
  );
END;
$$;

ALTER FUNCTION public.debug_jwt_claims() OWNER TO postgres;

CREATE FUNCTION public.debug_player_duplicates(p_guild_code text DEFAULT NULL::text) RETURNS TABLE(suspected_player text, display_names text[], player_ids text[], battle_counts bigint[], seasons_active text[])
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH normalized_names AS (
    SELECT
      LOWER(TRIM(e."displayName")) as normalized_name,
      e."userId" as player_id,
      e."displayName" as original_name,
      e."Guild",
      COUNT(*) as battle_count,
      array_agg(DISTINCT e."Season" ORDER BY e."Season") as seasons
    FROM "EOT_GR_data" e
    WHERE (p_guild_code IS NULL OR e."Guild" = p_guild_code)
      AND e."displayName" IS NOT NULL
      AND e."userId" IS NOT NULL
    GROUP BY LOWER(TRIM(e."displayName")), e."userId", e."displayName", e."Guild"
  ),
  potential_duplicates AS (
    SELECT
      nn.normalized_name,
      array_agg(DISTINCT nn.original_name ORDER BY nn.original_name) as display_names,
      array_agg(DISTINCT nn.player_id ORDER BY nn.player_id) as player_ids,
      array_agg(nn.battle_count ORDER BY nn.battle_count DESC) as battle_counts,
      array_agg(DISTINCT unnest(nn.seasons) ORDER BY unnest(nn.seasons)) as all_seasons
    FROM normalized_names nn
    GROUP BY nn.normalized_name
    HAVING COUNT(DISTINCT nn.player_id) > 1 -- Multiple player_ids for same normalized name
  )
  SELECT
    pd.normalized_name::TEXT as suspected_player,
    pd.display_names,
    pd.player_ids,
    pd.battle_counts,
    pd.all_seasons
  FROM potential_duplicates pd
  ORDER BY array_length(pd.player_ids, 1) DESC, array_length(pd.display_names, 1) DESC;
END;
$$;

ALTER FUNCTION public.debug_player_duplicates(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.delete_player_guild(p_guild_id bigint, p_reason text, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_request_role text := coalesce(
    nullif(nullif(current_setting('role', true), ''), 'none'), session_user
  );
  v_initial_guild record;
  v_guild record;
  v_pre_subject_ids uuid[] := ARRAY[]::uuid[];
  v_locked_subject_ids uuid[] := ARRAY[]::uuid[];
  v_subject_id uuid;
  v_mapping_ids integer[] := ARRAY[]::integer[];
  v_attestation record;
  v_revoked integer := 0;
  v_invites integer := 0;
  v_deleted_mappings integer := 0;
  v_deleted_guilds integer := 0;
BEGIN
  IF v_request_role NOT IN ('service_role', 'postgres') THEN
    RAISE EXCEPTION 'Guild deletion requires service authority'
      USING ERRCODE = '42501';
  END IF;
  IF p_guild_id IS NULL OR p_guild_id < -2147483648
    OR p_guild_id > 2147483647
    OR p_reason IS DISTINCT FROM 'guild_delete'
    OR p_source IS NULL OR length(btrim(p_source)) < 3
    OR length(p_source) > 120
  THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Invalid exact guild-deletion request',
      'error_code', 'INVALID_INPUT'
    );
  END IF;

  SELECT config.id, config.guild_code, config.cluster_code
  INTO v_initial_guild
  FROM public.guild_config AS config
  WHERE config.id = p_guild_id::integer;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Guild not found', 'error_code', 'NOT_FOUND'
    );
  END IF;
  IF v_initial_guild.guild_code = 'TEST'
    OR v_initial_guild.cluster_code = 'TEST'
  THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Protected system guild cannot be deleted',
      'error_code', 'PROTECTED_GUILD'
    );
  END IF;

  SELECT coalesce(array_agg(DISTINCT mapping.user_id
                            ORDER BY mapping.user_id), ARRAY[]::uuid[])
  INTO v_pre_subject_ids
  FROM public.player_mapping AS mapping
  WHERE mapping.guild_code = v_initial_guild.guild_code
    AND mapping.user_id IS NOT NULL;
  FOREACH v_subject_id IN ARRAY v_pre_subject_ids
  LOOP
    PERFORM pg_advisory_xact_lock(6208, hashtext(v_subject_id::text));
  END LOOP;

  SELECT config.id, config.guild_code, config.cluster_code
  INTO v_guild
  FROM public.guild_config AS config
  WHERE config.id = p_guild_id::integer
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Guild disappeared while locking',
      'error_code', 'TARGET_SET_NOT_EXACT'
    );
  END IF;
  IF v_guild.guild_code IS DISTINCT FROM v_initial_guild.guild_code
    OR v_guild.cluster_code IS DISTINCT FROM v_initial_guild.cluster_code
  THEN
    RAISE EXCEPTION 'Guild identity changed while locking'
      USING ERRCODE = '40001';
  END IF;
  IF v_guild.guild_code = 'TEST'
    OR v_guild.cluster_code = 'TEST'
  THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Protected system guild cannot be deleted',
      'error_code', 'PROTECTED_GUILD'
    );
  END IF;

  SELECT count(*)::integer INTO v_invites
  FROM (
    SELECT invite.id
    FROM public.player_invite_codes AS invite
    WHERE invite.guild_code = v_guild.guild_code
    ORDER BY invite.id
    FOR UPDATE
  ) AS locked_invite;

  SELECT coalesce(array_agg(locked.id ORDER BY locked.id), ARRAY[]::integer[]),
         coalesce(array_agg(DISTINCT locked.user_id
                            ORDER BY locked.user_id)
                  FILTER (WHERE locked.user_id IS NOT NULL), ARRAY[]::uuid[])
  INTO v_mapping_ids, v_locked_subject_ids
  FROM (
    SELECT mapping.id, mapping.user_id
    FROM public.player_mapping AS mapping
    WHERE mapping.guild_code = v_guild.guild_code
    ORDER BY mapping.id
    FOR UPDATE
  ) AS locked;
  IF v_locked_subject_ids IS DISTINCT FROM v_pre_subject_ids THEN
    RAISE EXCEPTION 'Guild mapping subject set changed while locking'
      USING ERRCODE = '40001';
  END IF;

  FOR v_attestation IN
    SELECT attestation.id
    FROM public.player_identity_attestations AS attestation
    WHERE attestation.mapping_id = ANY(v_mapping_ids)
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_attestation_revocations AS revoked
        WHERE revoked.attestation_id = attestation.id
      )
    ORDER BY attestation.id
    FOR UPDATE
  LOOP
    PERFORM public.append_player_identity_revocation(
      v_attestation.id, 'guild_delete', NULL, btrim(p_source)
    );
    v_revoked := v_revoked + 1;
  END LOOP;

  UPDATE auth.users AS target
  SET raw_user_meta_data = coalesce(target.raw_user_meta_data, '{}'::jsonb)
    - 'discord_user_id' - 'discord_username' - 'discord_synced'
  WHERE target.id = ANY(v_locked_subject_ids);

  UPDATE public.player_mapping AS mapping
  SET user_id = NULL,
      ownership_attestation_id = NULL,
      discord_user_id = NULL,
      discord_username = NULL,
      is_app_admin = false,
      updated_at = clock_timestamp()
  WHERE mapping.id = ANY(v_mapping_ids);

  DELETE FROM public.player_mapping AS mapping
  WHERE mapping.id = ANY(v_mapping_ids);
  GET DIAGNOSTICS v_deleted_mappings = ROW_COUNT;
  IF v_deleted_mappings <> cardinality(v_mapping_ids) THEN
    RAISE EXCEPTION 'Guild deletion lost its exact locked mapping set'
      USING ERRCODE = '55000';
  END IF;

  DELETE FROM public.guild_config AS config
  WHERE config.id = v_guild.id;
  GET DIAGNOSTICS v_deleted_guilds = ROW_COUNT;
  IF v_deleted_guilds <> 1 THEN
    RAISE EXCEPTION 'Guild deletion lost its exact locked guild row'
      USING ERRCODE = '55000';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'guild_id', v_guild.id,
    'guild_code', v_guild.guild_code,
    'deleted_mapping_count', v_deleted_mappings,
    'deleted_invite_count', v_invites,
    'revoked_attestations', v_revoked,
    'authority_cleared', true,
    'guild_deleted', true
  );
END
$$;

ALTER FUNCTION public.delete_player_guild(p_guild_id bigint, p_reason text, p_source text) OWNER TO postgres;

