CREATE FUNCTION public.diagnose_profile_claim_issues(p_player_id text) RETURNS TABLE(issue_type text, details text, suggested_fix text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  -- Check if player exists in EOT_GR_data
  IF NOT EXISTS (SELECT 1 FROM "EOT_GR_data" WHERE "userId" = p_player_id) THEN
    RETURN QUERY
    SELECT
      'PLAYER_NOT_FOUND'::TEXT,
      'Player ID not found in battle data'::TEXT,
      'Ensure player has participated in guild raids'::TEXT;
  END IF;

  -- Check if player_mapping exists
  IF NOT EXISTS (SELECT 1 FROM player_mapping WHERE player_id = p_player_id) THEN
    RETURN QUERY
    SELECT
      'NO_MAPPING'::TEXT,
      'Player mapping record does not exist'::TEXT,
      'Run guild data sync to create player mappings'::TEXT;
  END IF;

  -- Check if already claimed
  IF EXISTS (SELECT 1 FROM player_mapping WHERE player_id = p_player_id AND user_id IS NOT NULL) THEN
    RETURN QUERY
    SELECT
      'ALREADY_CLAIMED'::TEXT,
      'Player ID is already claimed by another user'::TEXT,
      'Contact admin if this is incorrect'::TEXT;
  END IF;

  -- Check for duplicate current mappings
  IF (SELECT COUNT(*) FROM player_mapping WHERE player_id = p_player_id AND is_current = true) > 1 THEN
    RETURN QUERY
    SELECT
      'DUPLICATE_CURRENT'::TEXT,
      'Multiple is_current=true records for this player'::TEXT,
      'Clean up duplicate mappings'::TEXT;
  END IF;

  -- Check case sensitivity issues
  IF EXISTS (
    SELECT 1 FROM player_mapping
    WHERE LOWER(player_id) = LOWER(p_player_id)
    AND player_id != p_player_id
  ) THEN
    RETURN QUERY
    SELECT
      'CASE_MISMATCH'::TEXT,
      'Player ID exists with different casing'::TEXT,
      'Use exact case from the game'::TEXT;
  END IF;

  -- No issues found
  RETURN QUERY
  SELECT
    'NO_ISSUES'::TEXT,
    'No obvious issues detected'::TEXT,
    'Profile should be claimable'::TEXT;
END;
$$;

ALTER FUNCTION public.diagnose_profile_claim_issues(p_player_id text) OWNER TO postgres;

CREATE FUNCTION public.dispatch_token_notification_events_discord(p_max_guilds integer DEFAULT 20, p_max_events_per_guild integer DEFAULT 50, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(guild_code text, processed_events integer, sent_events integer, skipped_events integer, failed_events integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_guild_code text;
  v_guild_name text;
  v_webhook_url text;
  v_event_ids uuid[];
  v_capped_names text[];
  v_near_cap_names text[];
  v_pre_burn_names text[];
  v_burned_names text[];
  v_capped_count integer;
  v_near_cap_count integer;
  v_pre_burn_count integer;
  v_burned_count integer;
  v_message text;
begin
  if current_setting('app.settings.discord_posting_enabled', true) = 'false' then
    return;
  end if;

  for v_guild_code in
    select pending.guild_code
    from (
      select
        e.guild_code,
        min(e.created_at) as first_created_at
      from public.token_notification_events e
      where e.delivery_channel = 'discord'
        and e.status in ('pending', 'failed')
        and (e.next_attempt_at is null or e.next_attempt_at <= p_now)
        and e.attempts < 5
      group by e.guild_code
      order by min(e.created_at)
      limit greatest(p_max_guilds, 1)
    ) pending
  loop
    select gc.display_name
    into v_guild_name
    from public.guild_config gc
    where gc.guild_code = v_guild_code;

    select wc.webhook_url
    into v_webhook_url
    from public.webhook_config wc
    where wc.guild_code = v_guild_code
      and wc.webhook_type = 'token_cap_notification'
      and wc.enabled = true
      and wc.webhook_url is not null
      and trim(wc.webhook_url) <> ''
    order by wc.updated_at desc nulls last
    limit 1;

    select
      array_agg(batch.id order by batch.created_at),
      array_remove(array_agg(case when batch.notification_type = 'capped' then batch.display_name end), null),
      array_remove(array_agg(case when batch.notification_type = 'near_cap' then batch.display_name end), null),
      array_remove(array_agg(case when batch.notification_type = 'burn_warning' then batch.display_name end), null),
      array_remove(
        array_agg(
          case
            when batch.notification_type = 'burn_occurred'
              then coalesce(batch.display_name, 'Unknown')
                   || ' (total burned: '
                   || coalesce(batch.payload ->> 'burned_tokens', '?')
                   || ')'
          end
        ),
        null
      )
    into v_event_ids, v_capped_names, v_near_cap_names, v_pre_burn_names, v_burned_names
    from (
      select
        e.id,
        e.display_name,
        e.notification_type,
        e.payload,
        e.created_at
      from public.token_notification_events e
      where e.guild_code = v_guild_code
        and e.delivery_channel = 'discord'
        and e.status in ('pending', 'failed')
        and (e.next_attempt_at is null or e.next_attempt_at <= p_now)
        and e.attempts < 5
      order by e.created_at
      limit greatest(p_max_events_per_guild, 1)
      for update skip locked
    ) batch;

    if v_event_ids is null or array_length(v_event_ids, 1) is null then
      continue;
    end if;

    if v_webhook_url is null then
      update public.token_notification_events
      set
        status = 'failed',
        attempts = attempts + 1,
        last_error = 'Missing enabled token_cap_notification webhook',
        next_attempt_at = p_now + interval '15 minutes'
      where id = any(v_event_ids);

      guild_code := v_guild_code;
      processed_events := array_length(v_event_ids, 1);
      sent_events := 0;
      skipped_events := 0;
      failed_events := array_length(v_event_ids, 1);
      return next;
    end if;

    v_capped_count := coalesce(array_length(v_capped_names, 1), 0);
    v_near_cap_count := coalesce(array_length(v_near_cap_names, 1), 0);
    v_pre_burn_count := coalesce(array_length(v_pre_burn_names, 1), 0);
    v_burned_count := coalesce(array_length(v_burned_names, 1), 0);

    -- Message format: previously included `(v_guild_code)` after the name,
    -- which leaked the guild UUID into Discord. Dropped here.
    v_message := format(
      'Token alert for %s: %s capped, %s near cap, %s pre-burn, %s burn events.',
      coalesce(v_guild_name, v_guild_code),
      v_capped_count,
      v_near_cap_count,
      v_pre_burn_count,
      v_burned_count
    );

    if v_capped_count > 0 then
      v_message := v_message || E'\nCapped: '
        || array_to_string(v_capped_names[1:least(v_capped_count, 8)], ', ');
    end if;

    if v_near_cap_count > 0 then
      v_message := v_message || E'\nNear cap: '
        || array_to_string(v_near_cap_names[1:least(v_near_cap_count, 8)], ', ');
    end if;

    if v_pre_burn_count > 0 then
      v_message := v_message || E'\nPre-burn warning: '
        || array_to_string(v_pre_burn_names[1:least(v_pre_burn_count, 8)], ', ');
    end if;

    if v_burned_count > 0 then
      v_message := v_message || E'\nBurn occurred: '
        || array_to_string(v_burned_names[1:least(v_burned_count, 8)], ', ');
    end if;

    begin
      perform net.http_post(
        url := v_webhook_url,
        headers := jsonb_build_object('Content-Type', 'application/json'),
        body := jsonb_build_object(
          'username', 'Token Manager',
          'content', v_message
        ),
        timeout_milliseconds := 15000
      );

      update public.token_notification_events
      set
        status = 'sent',
        attempts = attempts + 1,
        dispatched_at = p_now,
        next_attempt_at = null,
        last_error = null
      where id = any(v_event_ids);

      guild_code := v_guild_code;
      processed_events := array_length(v_event_ids, 1);
      sent_events := array_length(v_event_ids, 1);
      skipped_events := 0;
      failed_events := 0;
      return next;
    exception when others then
      update public.token_notification_events
      set
        status = 'failed',
        attempts = attempts + 1,
        next_attempt_at = p_now + interval '15 minutes',
        last_error = left(sqlerrm, 400)
      where id = any(v_event_ids);

      guild_code := v_guild_code;
      processed_events := array_length(v_event_ids, 1);
      sent_events := 0;
      skipped_events := 0;
      failed_events := array_length(v_event_ids, 1);
      return next;
    end;
  end loop;
end;
$$;

ALTER FUNCTION public.dispatch_token_notification_events_discord(p_max_guilds integer, p_max_events_per_guild integer, p_now timestamp with time zone) OWNER TO postgres;

CREATE FUNCTION public.enforce_coaching_task_snooze_window() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.snoozed_until IS NOT NULL
       AND NEW.snoozed_until > clock_timestamp() + INTERVAL '7 days'
    THEN
        RAISE EXCEPTION 'coaching task snooze cannot exceed 7 days'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

ALTER FUNCTION public.enforce_coaching_task_snooze_window() OWNER TO postgres;

CREATE FUNCTION public.enforce_player_identity_provenance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
DECLARE
  v_attestation public.player_identity_attestations%ROWTYPE;
  v_discord_matches integer;
  v_identity_id uuid;
  v_pending_id uuid;
  v_activation record;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'Player mapping stable id is immutable'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.ownership_attestation_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_attestation_revocations AS revoked
        WHERE revoked.attestation_id = OLD.ownership_attestation_id
      )
    THEN
      RAISE EXCEPTION 'Revoke player ownership before deleting mapping %', OLD.id
        USING ERRCODE = '42501';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE'
    AND OLD.is_current IS TRUE
    AND OLD.ownership_attestation_id IS NOT NULL
    AND (
      NEW.user_id IS DISTINCT FROM OLD.user_id
      OR NEW.player_id IS DISTINCT FROM OLD.player_id
      OR NEW.ownership_attestation_id IS DISTINCT FROM OLD.ownership_attestation_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.player_identity_attestation_revocations AS revoked
      WHERE revoked.attestation_id = OLD.ownership_attestation_id
    )
  THEN
    RAISE EXCEPTION 'Revoke existing player ownership before changing mapping %', OLD.id
      USING ERRCODE = '42501';
  END IF;

  IF NEW.is_current IS NOT TRUE AND (
    NEW.user_id IS NOT NULL
    OR NEW.ownership_attestation_id IS NOT NULL
    OR NEW.discord_user_id IS NOT NULL
    OR NEW.discord_username IS NOT NULL
    OR NEW.is_app_admin IS TRUE
    OR lower(coalesce(NEW.role::text, '')) IN ('leader', 'officer')
  ) THEN
    RAISE EXCEPTION
      'Inactive player mappings cannot retain user, Discord, or privilege authority'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.is_current IS TRUE AND NEW.user_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.player_identity_subject_authority_blocks AS block
      WHERE block.subject_user_id = NEW.user_id
    ) THEN
      RAISE EXCEPTION 'Blocked subject cannot receive player authority'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.ownership_attestation_id IS NULL THEN
      RAISE EXCEPTION 'Current player ownership requires an attestation'
        USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_attestation
    FROM public.player_identity_attestations AS attestation
    WHERE attestation.id = NEW.ownership_attestation_id
      AND attestation.mapping_id = NEW.id
      AND attestation.player_id = NEW.player_id
      AND attestation.subject_user_id = NEW.user_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_attestation_revocations AS revoked
        WHERE revoked.attestation_id = attestation.id
      );
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Current player ownership attestation is missing, mismatched, or revoked'
        USING ERRCODE = '42501';
    END IF;
  ELSIF NEW.is_current IS TRUE THEN
    IF NEW.ownership_attestation_id IS NOT NULL
      OR NEW.discord_user_id IS NOT NULL
      OR NEW.discord_username IS NOT NULL
      OR NEW.is_app_admin IS TRUE
    THEN
      RAISE EXCEPTION 'Unowned current mappings cannot retain ownership, Discord, or app-admin authority'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NEW.discord_user_id IS NOT NULL THEN
    IF NEW.is_current IS NOT TRUE OR NEW.user_id IS NULL
      OR NEW.discord_user_id !~ '^[0-9]{17,20}$'
    THEN
      RAISE EXCEPTION
        'Discord authority requires a current proven user and strict snowflake'
        USING ERRCODE = '42501';
    END IF;

    -- Serialize provider link/unlink and mapping restoration on one user key.
    PERFORM pg_advisory_xact_lock(6208, hashtext(NEW.user_id::text));

    SELECT count(*), (array_agg(identity.id ORDER BY identity.id))[1]
    INTO v_discord_matches, v_identity_id
    FROM auth.identities AS identity
    WHERE identity.provider = 'discord'
      AND identity.provider_id = NEW.discord_user_id
      AND identity.user_id = NEW.user_id;
    IF v_discord_matches <> 1 THEN
      RAISE EXCEPTION 'Discord authority does not match one live Auth identity'
        USING ERRCODE = '42501';
    END IF;

    SELECT pending.id
    INTO v_pending_id
    FROM public.player_identity_discord_unlink_pending AS pending
    WHERE pending.subject_user_id = NEW.user_id
    ORDER BY pending.generation DESC
    LIMIT 1;
    IF FOUND THEN
      SELECT activation.pending_id, activation.auth_identity_id,
             activation.ownership_attestation_id,
             activation.provider_id_sha256
      INTO v_activation
      FROM public.player_identity_discord_generation_activations AS activation
      WHERE activation.pending_id = v_pending_id;
      IF NOT FOUND
        OR v_activation.auth_identity_id IS DISTINCT FROM v_identity_id
        OR v_activation.ownership_attestation_id IS DISTINCT FROM
          NEW.ownership_attestation_id
        OR v_activation.provider_id_sha256 IS DISTINCT FROM encode(
          extensions.digest(convert_to(NEW.discord_user_id, 'UTF8'), 'sha256'),
          'hex'
        )
      THEN
        RAISE EXCEPTION
          'Discord unlink is pending; stale provider state cannot restore authority'
          USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END
$_$;

ALTER FUNCTION public.enforce_player_identity_provenance() OWNER TO postgres;

CREATE FUNCTION public.enqueue_sync(p_guild_code text, p_job_type text DEFAULT 'incremental_sync'::text, p_priority integer DEFAULT 5, p_scheduled_for timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_job_id UUID;
BEGIN
  -- Auto-fail zombie pending rows for this guild/job_type so they cannot block enqueue.
  UPDATE sync_queue
  SET
    status = 'failed',
    completed_at = COALESCE(completed_at, NOW()),
    updated_at = NOW(),
    error_log = COALESCE(error_log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'attempt', attempts,
      'error', 'Auto-failed zombie pending job during enqueue (attempts >= max_attempts)',
      'timestamp', NOW()
    ))
  WHERE guild_code = p_guild_code
    AND job_type = p_job_type
    AND status = 'pending'
    AND attempts >= max_attempts;

  -- Check for existing actionable job only.
  SELECT id INTO v_job_id
  FROM sync_queue
  WHERE guild_code = p_guild_code
    AND job_type = p_job_type
    AND (
      status = 'processing'
      OR (status = 'pending' AND attempts < max_attempts)
    )
  ORDER BY created_at DESC
  LIMIT 1;

  -- Create new job if none exists. Wrap INSERT in unique_violation handler
  -- to swallow the race-condition path: if a concurrent caller wins the
  -- race between our SELECT above and our INSERT below, the unique_active_job
  -- partial index fires 23505. Re-SELECT and return the winner's id.
  IF v_job_id IS NULL THEN
    BEGIN
      INSERT INTO sync_queue (
        guild_code, job_type, priority, scheduled_for
      ) VALUES (
        p_guild_code, p_job_type, p_priority, p_scheduled_for
      ) RETURNING id INTO v_job_id;

      -- Initialize guild_sync_status if needed
      INSERT INTO guild_sync_status (guild_code, status)
      VALUES (p_guild_code, 'pending')
      ON CONFLICT (guild_code) DO UPDATE
      SET status = 'pending', updated_at = NOW();

    EXCEPTION
      WHEN unique_violation THEN
        -- Race lost: another concurrent caller inserted between our SELECT
        -- and our INSERT. Re-SELECT the winner and return its id. Same
        -- contract as the no-race path: caller gets an actionable job id.
        SELECT id INTO v_job_id
        FROM sync_queue
        WHERE guild_code = p_guild_code
          AND job_type = p_job_type
          AND status IN ('pending', 'processing')
        ORDER BY created_at DESC
        LIMIT 1;
        -- If somehow the row vanished (winner finished + cleanup ran in
        -- the microseconds between the constraint fire and re-select),
        -- v_job_id stays NULL and we return NULL — caller already handles
        -- that case (treat as "couldn't enqueue, will retry next tick").
    END;
  END IF;

  RETURN v_job_id;
END;
$$;

ALTER FUNCTION public.enqueue_sync(p_guild_code text, p_job_type text, p_priority integer, p_scheduled_for timestamp with time zone) OWNER TO postgres;

CREATE FUNCTION public.enqueue_write(p_operation_type text, p_target_table text, p_payload jsonb, p_priority integer DEFAULT 5, p_circuit_name text DEFAULT NULL::text, p_context jsonb DEFAULT '{}'::jsonb, p_max_attempts integer DEFAULT 3, p_expires_in interval DEFAULT '24:00:00'::interval) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_job_id UUID;
BEGIN
    INSERT INTO write_queue (
        operation_type,
        target_table,
        payload,
        priority,
        circuit_name,
        context,
        max_attempts,
        expires_at
    ) VALUES (
        p_operation_type,
        p_target_table,
        p_payload,
        p_priority,
        p_circuit_name,
        p_context,
        p_max_attempts,
        NOW() + p_expires_in
    )
    RETURNING id INTO v_job_id;

    RETURN v_job_id;
END;
$$;

