CREATE FUNCTION public.fail_job(p_job_id uuid, p_worker_id text, p_error text, p_progress jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_guild_code TEXT;
  v_attempts INTEGER;
  v_max_attempts INTEGER;
  v_jitter_seconds INTEGER;
BEGIN
  -- Get job details
  SELECT guild_code, attempts, max_attempts
  INTO v_guild_code, v_attempts, v_max_attempts
  FROM sync_queue
  WHERE id = p_job_id AND worker_id = p_worker_id;

  IF NOT FOUND THEN
    RETURN FALSE;
  END IF;

  -- Append error to log
  UPDATE sync_queue
  SET
    error_log = error_log || jsonb_build_array(jsonb_build_object(
      'attempt', v_attempts,
      'error', p_error,
      'timestamp', NOW()
    )),
    progress = p_progress,
    updated_at = NOW()
  WHERE id = p_job_id;

  -- Check if we should retry
  IF v_attempts < v_max_attempts THEN
    -- Calculate jitter: random 0-30 seconds
    v_jitter_seconds := floor(random() * 30)::INTEGER;

    -- Schedule retry with exponential backoff + jitter
    -- Base: attempts * 1 minute, plus 0-30 seconds jitter
    UPDATE sync_queue
    SET
      status = 'pending',
      worker_id = NULL,
      started_at = NULL,
      scheduled_for = NOW() + (v_attempts * INTERVAL '1 minute') + (v_jitter_seconds * INTERVAL '1 second')
    WHERE id = p_job_id;
  ELSE
    -- Max attempts reached, mark as failed
    UPDATE sync_queue
    SET
      status = 'failed',
      completed_at = NOW()
    WHERE id = p_job_id;

    -- Update guild_sync_status
    UPDATE guild_sync_status
    SET
      status = 'error',
      error_message = p_error,
      last_error = p_error,
      updated_at = NOW()
    WHERE guild_code = v_guild_code;
  END IF;

  -- Update health metrics
  PERFORM update_sync_health(v_guild_code, FALSE);

  RETURN TRUE;
END;
$$;

ALTER FUNCTION public.fail_job(p_job_id uuid, p_worker_id text, p_error text, p_progress jsonb) OWNER TO postgres;

CREATE FUNCTION public.fail_work_job(p_job_id bigint, p_worker_id text, p_error text, p_backoff_seconds integer DEFAULT 60) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_job public.work_queue;
BEGIN
  SELECT * INTO v_job
  FROM public.work_queue
  WHERE id = p_job_id
    AND claimed_by = p_worker_id
    AND status = 'processing'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF v_job.attempts >= v_job.max_attempts THEN
    UPDATE public.work_queue
    SET status       = 'dead',
        completed_at = now(),
        error        = p_error,
        updated_at   = now()
    WHERE id = p_job_id;
  ELSE
    UPDATE public.work_queue
    SET status        = 'pending',
        claimed_by    = NULL,
        claimed_at    = NULL,
        started_at    = NULL,
        scheduled_for = now() + make_interval(secs => p_backoff_seconds),
        error         = p_error,
        updated_at    = now()
    WHERE id = p_job_id;
  END IF;
  RETURN true;
END;
$$;

ALTER FUNCTION public.fail_work_job(p_job_id bigint, p_worker_id text, p_error text, p_backoff_seconds integer) OWNER TO postgres;

