CREATE FUNCTION public.finalize_onboarding_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  target_role text;
begin
  if new.profile_status = 'complete'
     and (old.profile_status is distinct from 'complete') then

    target_role := coalesce(new.role_intent, 'member');

    if to_regclass('public.profiles') is not null then
      update public.profiles
      set
        role = target_role,
        onboarding_complete = true,
        onboarding_role_intent = target_role,
        last_onboarding_step = 'profile_complete',
        updated_at = now()
      where user_id = new.user_id;
    end if;

    if target_role = 'leader' and new.guild_code is not null then
      update public.guild_config
      set "API_Owner" = coalesce(
        (select email from auth.users where id = new.user_id),
        "API_Owner"
      )
      where guild_code = new.guild_code;
    end if;
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.finalize_onboarding_profile() OWNER TO postgres;

