CREATE FUNCTION public.find_token_accrual_violations(p_guild_code text DEFAULT NULL::text) RETURNS TABLE(guild_code text, season text, player_id text, display_name text, tokens_used integer, tokens_available integer, max_accruable integer, excess integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  g record;
  v_season text;
  v_first timestamptz;
  v_bound int;
begin
  for g in
    select distinct d."Guild" as guild
    from public."EOT_GR_data" d
    where (p_guild_code is null or d."Guild" = p_guild_code)
      and d."startedOn" >= now() - interval '20 days'
  loop
    select max(d.season_num)::text into v_season
    from public."EOT_GR_data" d
    where d."Guild" = g.guild;
    if v_season is null then
      continue;
    end if;

    select min(d."startedOn")::timestamptz into v_first
    from public."EOT_GR_data" d
    where d."Guild" = g.guild
      and d."Season" = v_season
      and d."damageType" = 'Battle';
    if v_first is null then
      continue;
    end if;

    v_bound := 3 + floor(extract(epoch from (now() - v_first)) / 43200)::int;

    return query
    select g.guild,
           v_season,
           s.player_id,
           s.display_name,
           s.tokens_used,
           s.tokens_available,
           -- WI-2640: calculated rows carry the +1 estimator slack in the
           -- reported bound so `excess` stays honest for both branches.
           v_bound + (case when s.data_source = 'calculated' then 1 else 0 end),
           (s.tokens_used + s.tokens_available)
             - (v_bound + (case when s.data_source = 'calculated' then 1 else 0 end))
    from public.get_player_token_state(g.guild, v_season, null, null) s
    where s.tokens_used + s.tokens_available
          > v_bound + (case when s.data_source = 'calculated' then 1 else 0 end);
  end loop;
end;
$$;

ALTER FUNCTION public.find_token_accrual_violations(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.find_unmapped_players_optimized() RETURNS TABLE(guild_code text, user_id text, record_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    data."Guild" as guild_code,
    data."userId" as user_id,
    COUNT(*) as record_count
  FROM "EOT_GR_data" data
  LEFT JOIN "player_mapping" pm ON (
    data."userId" = pm.player_id AND (
      pm.guild_code = data."Guild" OR pm.guild_code = 'GLOBAL'
    )
  )
  WHERE data."userId" IS NOT NULL
    AND pm.player_id IS NULL
  GROUP BY data."Guild", data."userId"
  ORDER BY data."Guild", record_count DESC
  LIMIT 1000;
END;
$$;

