CREATE FUNCTION public.fix_duplicate_current_mappings() RETURNS TABLE(fixed_player_id text, fixed_display_name text, kept_guild text, disabled_guilds text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY
  WITH duplicates AS (
    -- Find all players with multiple is_current = true
    SELECT
      LOWER(player_id) as player_id_lower,
      COUNT(*) as current_count
    FROM player_mapping
    WHERE is_current = true
    GROUP BY LOWER(player_id)
    HAVING COUNT(*) > 1
  ),
  ranked_mappings AS (
    -- Rank them by role importance and update time
    SELECT
      pm.id,
      LOWER(pm.player_id) as player_id_lower,
      pm.player_id,
      pm.guild_code,
      pm.display_name,
      pm.role,
      pm.updated_at,
      ROW_NUMBER() OVER (
        PARTITION BY LOWER(pm.player_id)
        ORDER BY
          CASE
            WHEN pm.role = 'leader' THEN 1
            WHEN pm.role = 'officer' THEN 2
            ELSE 3
          END,
          pm.updated_at DESC
      ) as rn
    FROM player_mapping pm
    INNER JOIN duplicates d ON LOWER(pm.player_id) = d.player_id_lower
    WHERE pm.is_current = true
  ),
  updates AS (
    -- Set all non-primary records to is_current = false
    UPDATE player_mapping pm
    SET
      is_current = false,
      updated_at = NOW()
    FROM ranked_mappings rm
    WHERE pm.id = rm.id
    AND rm.rn > 1
    RETURNING LOWER(pm.player_id) as player_id, pm.display_name, pm.guild_code
  )
  -- Return summary of fixes
  SELECT
    u.player_id as fixed_player_id,
    MAX(u.display_name) as fixed_display_name,
    MAX(CASE WHEN rm.rn = 1 THEN rm.guild_code END) as kept_guild,
    STRING_AGG(CASE WHEN rm.rn > 1 THEN rm.guild_code END, ', ' ORDER BY rm.guild_code) as disabled_guilds
  FROM updates u
  JOIN ranked_mappings rm ON LOWER(rm.player_id) = u.player_id
  GROUP BY u.player_id;
END;
$$;

ALTER FUNCTION public.fix_duplicate_current_mappings() OWNER TO postgres;

CREATE FUNCTION public.format_team_composition(team_comp jsonb, mow text) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
  formatted_team text := '';
  unit_record record;
  unit_id text;
begin
  -- Format main team members
  for unit_id in select jsonb_array_elements_text(team_comp)
  loop
    select discord_emoji into unit_record from hero_mappings where unit_id = unit_id;
    if unit_record.discord_emoji is not null then
      formatted_team := formatted_team || unit_record.discord_emoji || ' ';
    end if;
  end loop;

  -- Add MOW
  select discord_emoji into unit_record from hero_mappings where unit_id = mow and category = 'MOW';
  if unit_record.discord_emoji is not null then
    formatted_team := formatted_team || '+ ' || unit_record.discord_emoji;
  end if;

  return trim(formatted_team);
end;
$$;

ALTER FUNCTION public.format_team_composition(team_comp jsonb, mow text) OWNER TO postgres;

CREATE FUNCTION public.format_team_with_emojis(hero_details text, mow_details text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  heroes_json jsonb;
  mows_json jsonb;
  hero_obj jsonb;
  hero_ids TEXT[] := '{}';
  mow_ids TEXT[] := '{}';
  current_unit_id TEXT;
  result TEXT := '';
  hero_result TEXT := '';
  mow_result TEXT := '';
  emoji TEXT;
  temp_text TEXT;
BEGIN
  -- Parse hero details JSON and extract unit IDs
  IF hero_details IS NOT NULL AND hero_details != '' THEN
    BEGIN
      -- Check if it's already an array
      IF LEFT(TRIM(hero_details), 1) = '[' THEN
        temp_text := TRIM(hero_details);
      ELSE
        -- Might be missing brackets
        temp_text := '[' || hero_details || ']';
      END IF;

      heroes_json := temp_text::jsonb;

      -- Extract unitId from each hero object
      FOR hero_obj IN SELECT * FROM jsonb_array_elements(heroes_json)
      LOOP
        current_unit_id := hero_obj->>'unitId';
        IF current_unit_id IS NOT NULL AND current_unit_id != '' THEN
          hero_ids := array_append(hero_ids, current_unit_id);
        END IF;
      END LOOP;
    EXCEPTION WHEN OTHERS THEN
      -- If JSON parsing fails, try to extract unitIds using regex
      BEGIN
        FOR current_unit_id IN
          SELECT DISTINCT(regexp_matches(hero_details, '"unitId"\s*:\s*"([^"]+)"', 'g'))[1]
        LOOP
          IF current_unit_id IS NOT NULL THEN
            hero_ids := array_append(hero_ids, current_unit_id);
          END IF;
        END LOOP;
      EXCEPTION WHEN OTHERS THEN
        -- Continue without hero data
      END;
    END;
  END IF;

  -- Parse MOW details JSON and extract unit IDs
  IF mow_details IS NOT NULL AND mow_details != '' THEN
    BEGIN
      -- Check if it's already an array
      IF LEFT(TRIM(mow_details), 1) = '[' THEN
        temp_text := TRIM(mow_details);
      ELSE
        -- Might be missing brackets
        temp_text := '[' || mow_details || ']';
      END IF;

      mows_json := temp_text::jsonb;

      -- Extract unitId from each MOW object
      FOR hero_obj IN SELECT * FROM jsonb_array_elements(mows_json)
      LOOP
        current_unit_id := hero_obj->>'unitId';
        IF current_unit_id IS NOT NULL AND current_unit_id != '' THEN
          mow_ids := array_append(mow_ids, current_unit_id);
        END IF;
      END LOOP;
    EXCEPTION WHEN OTHERS THEN
      -- If JSON parsing fails, try to extract unitIds using regex
      BEGIN
        FOR current_unit_id IN
          SELECT DISTINCT(regexp_matches(mow_details, '"unitId"\s*:\s*"([^"]+)"', 'g'))[1]
        LOOP
          IF current_unit_id IS NOT NULL THEN
            mow_ids := array_append(mow_ids, current_unit_id);
          END IF;
        END LOOP;
      EXCEPTION WHEN OTHERS THEN
        -- Continue without MOW data
      END;
    END;
  END IF;

  -- Sort hero IDs alphabetically and remove duplicates
  hero_ids := ARRAY(SELECT DISTINCT unnest(hero_ids) ORDER BY 1);

  -- Get emojis for each hero
  IF array_length(hero_ids, 1) > 0 THEN
    FOREACH current_unit_id IN ARRAY hero_ids
    LOOP
      -- Look up emoji in hero_mappings for heroes
      SELECT COALESCE(hm.discord_emoji, hm.display_name) INTO emoji
      FROM hero_mappings hm
      WHERE hm.unit_id = current_unit_id AND hm.category = 'Hero';

      -- Use the emoji if found, otherwise use the unit ID
      hero_result := hero_result || COALESCE(emoji, current_unit_id) || ' ';
    END LOOP;
  END IF;

  -- Get emojis for each MOW (no sorting needed)
  IF array_length(mow_ids, 1) > 0 THEN
    FOREACH current_unit_id IN ARRAY mow_ids
    LOOP
      -- Look up emoji in hero_mappings for MOWs
      SELECT COALESCE(hm.discord_emoji, hm.display_name) INTO emoji
      FROM hero_mappings hm
      WHERE hm.unit_id = current_unit_id AND hm.category = 'MOW';

      -- Use the emoji if found, otherwise use the unit ID
      mow_result := mow_result || COALESCE(emoji, current_unit_id) || ' ';
    END LOOP;
  END IF;

  -- Combine results with & separator
  hero_result := TRIM(hero_result);
  mow_result := TRIM(mow_result);

  IF hero_result != '' AND mow_result != '' THEN
    result := hero_result || ' & ' || mow_result;
  ELSIF hero_result != '' THEN
    result := hero_result;
  ELSIF mow_result != '' THEN
    result := mow_result;
  ELSE
    result := 'No team data';
  END IF;

  RETURN result;
END;
$$;

ALTER FUNCTION public.format_team_with_emojis(hero_details text, mow_details text) OWNER TO postgres;

CREATE FUNCTION public.generate_boss_assignments(p_guild_code text, p_season text DEFAULT NULL::text, p_skip_side_bosses boolean DEFAULT false, p_max_tokens_per_player integer DEFAULT 3, p_dry_run boolean DEFAULT false, p_excluded_bosses text[] DEFAULT ARRAY[]::text[], p_season_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_season text;
    v_assignments jsonb := '[]'::jsonb;
    v_warnings text[] := '{}';
    v_player_tokens jsonb := '{}'::jsonb;
    v_boss_record record;
    v_player_record record;
    v_tokens_needed integer;
    v_tokens_assigned integer;
    v_current_player_tokens integer;
    v_run_id uuid;
    v_result jsonb;
    v_assign_tokens integer;
    v_boss_identifier text;
BEGIN
    -- Validate caller is officer+ in the guild (skip for service role / edge functions)
    IF auth.uid() IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM player_mapping pm
        WHERE pm.guild_code = p_guild_code
        AND pm.user_id = auth.uid()
        AND pm.is_current = true
        AND pm.role IN ('officer', 'leader', 'Officer', 'Leader')
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Unauthorized: Must be officer or leader'
        );
    END IF;

    -- Get current season if not provided
    -- LEX-FIX 2026-05-07: was MAX("Season") (TEXT lex max -> '99' at S100).
    v_season := COALESCE(p_season, (
        SELECT MAX(season_num)::text FROM "EOT_GR_data" WHERE "Guild" = p_guild_code
    ));

    IF v_season IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'No season data found for guild'
        );
    END IF;

    -- Get boss data with HP estimates and priority order
    -- Priority: Mythic side > Mythic main > Legendary side > Legendary main
    FOR v_boss_record IN (
        WITH boss_data AS (
            SELECT DISTINCT
                "Name" as boss_name,
                "rarity",
                "set" as boss_set,
                "encounterId" as encounter_id,
                MAX("maxHp") as boss_hp,
                AVG(CASE WHEN "damageDealt" > 0 THEN "damageDealt" END)::bigint as avg_damage
            FROM "EOT_GR_data"
            WHERE "Guild" = p_guild_code
            AND "Season" = v_season
            AND "rarity" IN ('Legendary', 'Mythic')
            AND "Name" IS NOT NULL
            GROUP BY "Name", "rarity", "set", "encounterId"
        )
        SELECT
            boss_name,
            rarity,
            boss_set,
            encounter_id,
            boss_hp,
            avg_damage,
            GREATEST(3, CEIL(boss_hp::decimal / NULLIF(avg_damage, 0)))::integer as tokens_needed,
            CASE rarity WHEN 'Mythic' THEN 0 ELSE 1 END as rarity_order,
            CASE WHEN encounter_id > 0 THEN 0 ELSE 1 END as encounter_order,
            CASE rarity WHEN 'Mythic' THEN 'M' ELSE 'L' END || (boss_set + 1) || ' ' || boss_name as boss_level
        FROM boss_data
        WHERE (
            -- Legacy support: if p_skip_side_bosses is true and no excluded_bosses provided, skip all side bosses
            (NOT p_skip_side_bosses OR array_length(p_excluded_bosses, 1) > 0 OR encounter_id = 0)
        )
        ORDER BY rarity_order, encounter_order, boss_set DESC, boss_name
    )
    LOOP
        -- Build boss identifier for exclusion check (format: "BossName - Rarity" or just boss_level)
        v_boss_identifier := v_boss_record.boss_name || ' - ' || v_boss_record.rarity;

        -- Check if this boss should be excluded (check multiple formats)
        IF v_boss_record.boss_name = ANY(p_excluded_bosses)
           OR v_boss_identifier = ANY(p_excluded_bosses)
           OR v_boss_record.boss_level = ANY(p_excluded_bosses) THEN
            CONTINUE;
        END IF;

        v_tokens_needed := v_boss_record.tokens_needed;
        v_tokens_assigned := 0;

        -- Get ranked players for this boss
        FOR v_player_record IN (
            WITH player_perf AS (
                SELECT
                    d."displayName",
                    AVG(d."damageDealt") as avg_damage,
                    COUNT(*) as battle_count
                FROM "EOT_GR_data" d
                WHERE d."Guild" = p_guild_code
                AND d."Name" = v_boss_record.boss_name
                AND d."damageType" = 'Battle'
                AND d."damageDealt" > 0
                GROUP BY d."displayName"
            ),
            guild_avg AS (
                SELECT AVG(avg_damage) as guild_avg_damage FROM player_perf
            )
            SELECT
                pm.player_id,
                pm.display_name,
                COALESCE(
                    CASE WHEN ga.guild_avg_damage > 0
                        THEN ROUND(((pp.avg_damage / ga.guild_avg_damage) - 1) * 100, 1)
                        ELSE 0
                    END,
                    -100
                ) as performance,
                COALESCE(pp.battle_count, 0)::integer as battles,
                pm.boss_preferences
            FROM player_mapping pm
            LEFT JOIN player_perf pp ON pp."displayName" = pm.display_name
            CROSS JOIN guild_avg ga
            WHERE pm.guild_code = p_guild_code
            AND pm.is_current = true
            ORDER BY
                CASE WHEN pm.boss_preferences->>v_boss_record.boss_name = 'preferred' THEN 0 ELSE 1 END,
                COALESCE(pp.avg_damage, 0) DESC,
                COALESCE(pp.battle_count, 0) DESC
        )
        LOOP
            v_current_player_tokens := COALESCE((v_player_tokens->>v_player_record.player_id)::integer, 0);

            IF v_current_player_tokens >= p_max_tokens_per_player THEN
                CONTINUE;
            END IF;

            IF v_player_record.boss_preferences->>v_boss_record.boss_name = 'avoid' THEN
                CONTINUE;
            END IF;

            v_assign_tokens := LEAST(
                v_tokens_needed - v_tokens_assigned,
                p_max_tokens_per_player - v_current_player_tokens
            );

            IF v_assign_tokens > 0 THEN
                v_assignments := v_assignments || jsonb_build_object(
                    'boss_name', v_boss_record.boss_name,
                    'boss_level', v_boss_record.boss_level,
                    'rarity', v_boss_record.rarity,
                    'encounter_id', v_boss_record.encounter_id,
                    'player_id', v_player_record.player_id,
                    'display_name', v_player_record.display_name,
                    'tokens', v_assign_tokens,
                    'performance', v_player_record.performance,
                    'battles', v_player_record.battles,
                    'status', 'pending',
                    'reason', CASE
                        WHEN v_player_record.boss_preferences->>v_boss_record.boss_name = 'preferred'
                        THEN 'Player preference'
                        ELSE 'Performance ranking'
                    END
                );

                v_player_tokens := jsonb_set(
                    v_player_tokens,
                    ARRAY[v_player_record.player_id],
                    to_jsonb(v_current_player_tokens + v_assign_tokens)
                );
                v_tokens_assigned := v_tokens_assigned + v_assign_tokens;
            END IF;

            IF v_tokens_assigned >= v_tokens_needed THEN
                EXIT;
            END IF;
        END LOOP;

        IF v_tokens_assigned < v_tokens_needed THEN
            v_warnings := array_append(v_warnings,
                format('%s needs %s tokens but only %s assigned',
                    v_boss_record.boss_level, v_tokens_needed, v_tokens_assigned));
        END IF;
    END LOOP;

    -- Persist run if not dry run
    IF NOT p_dry_run THEN
        INSERT INTO assignment_runs (
            guild_code, season, generated_by, strategy,
            skip_side_bosses, max_tokens_per_player,
            assignments, warnings, is_dry_run, excluded_bosses
        ) VALUES (
            p_guild_code, v_season, auth.uid(), 'waterfall',
            p_skip_side_bosses, p_max_tokens_per_player,
            v_assignments, v_warnings, false, p_excluded_bosses
        )
        RETURNING id INTO v_run_id;
    END IF;

    -- Build result
    v_result := jsonb_build_object(
        'success', true,
        'meta', jsonb_build_object(
            'guild_code', p_guild_code,
            'season', v_season,
            'season_id', p_season_id,
            'strategy', 'waterfall',
            'skip_side_bosses', p_skip_side_bosses,
            'excluded_bosses', p_excluded_bosses,
            'max_tokens_per_player', p_max_tokens_per_player,
            'generated_at', now(),
            'generated_by', auth.uid(),
            'dry_run', p_dry_run,
            'run_id', v_run_id
        ),
        'assignments', v_assignments,
        'warnings', to_jsonb(v_warnings),
        'stats', jsonb_build_object(
            'total_assignments', jsonb_array_length(v_assignments),
            'players_assigned', (SELECT COUNT(DISTINCT a->>'player_id') FROM jsonb_array_elements(v_assignments) a),
            'bosses_covered', (SELECT COUNT(DISTINCT a->>'boss_name') FROM jsonb_array_elements(v_assignments) a)
        )
    );

    RETURN v_result;
END;
$$;

ALTER FUNCTION public.generate_boss_assignments(p_guild_code text, p_season text, p_skip_side_bosses boolean, p_max_tokens_per_player integer, p_dry_run boolean, p_excluded_bosses text[], p_season_id text) OWNER TO postgres;

CREATE FUNCTION public.generate_invite_code() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  result TEXT := '';
  i INTEGER;
BEGIN
  FOR i IN 1..8 LOOP
    result := result || substr(chars, floor(random() * length(chars) + 1)::int, 1);
  END LOOP;
  RETURN result;
END;
$$;

ALTER FUNCTION public.generate_invite_code() OWNER TO postgres;

CREATE FUNCTION public.generate_team_hash(hero_details text, mow_details text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  hero_ids text[];
  mow_id text;
  hash_input text;
BEGIN
  -- Return NULL for invalid/empty hero details
  IF hero_details IS NULL OR hero_details = '' OR hero_details = '[]' THEN
    RETURN NULL;
  END IF;

  BEGIN
    -- Extract and sort hero unitIds
    SELECT array_agg(unit_id ORDER BY unit_id)
    INTO hero_ids
    FROM (
      SELECT jsonb_array_elements(hero_details::jsonb) ->> 'unitId' as unit_id
    ) heroes
    WHERE unit_id IS NOT NULL;

    -- Return NULL if no valid heroes found
    IF hero_ids IS NULL OR array_length(hero_ids, 1) = 0 THEN
      RETURN NULL;
    END IF;

    -- Extract MoW unitId (single object, not array)
    IF mow_details IS NOT NULL AND mow_details != '' AND mow_details != 'null' THEN
      mow_id := mow_details::jsonb ->> 'unitId';
    END IF;

    -- Build hash input: sorted_hero_ids|mow_id
    hash_input := array_to_string(hero_ids, ',') || '|' || COALESCE(mow_id, 'none');

    RETURN md5(hash_input);
  EXCEPTION WHEN OTHERS THEN
    -- Return NULL if JSON parsing fails
    RETURN NULL;
  END;
END;
$$;

ALTER FUNCTION public.generate_team_hash(hero_details text, mow_details text) OWNER TO postgres;

CREATE FUNCTION public.generate_verification_code() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$BEGIN
    RETURN upper(substring(gen_random_uuid()::text from 1 for 8));
END;$$;

ALTER FUNCTION public.generate_verification_code() OWNER TO postgres;

CREATE FUNCTION public.get_ability_stat(base_stat integer, ability_level integer, rarity text DEFAULT 'Common'::text) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    power_mult REAL;
    rarity_mult REAL;
BEGIN
    SELECT multiplier INTO power_mult FROM power_levels WHERE level = ability_level;
    SELECT bonus INTO rarity_mult FROM rarity_bonuses WHERE rarity_bonuses.rarity = get_ability_stat.rarity;

    IF power_mult IS NULL THEN power_mult := 1.0; END IF;
    IF rarity_mult IS NULL THEN rarity_mult := 1.0; END IF;

    RETURN ROUND(base_stat * power_mult * rarity_mult)::INTEGER;
END;
$$;

ALTER FUNCTION public.get_ability_stat(base_stat integer, ability_level integer, rarity text) OWNER TO postgres;

CREATE FUNCTION public.get_accurate_battle_count(p_guild_code text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    IF p_guild_code IS NULL THEN
        -- Return total count across all guilds (excluding TEST and EOT)
        RETURN (
            SELECT COUNT(*)
            FROM "EOT_GR_data"
        );
    ELSE
        -- Return count for specific guild
        RETURN (
            SELECT COUNT(*)
            FROM "EOT_GR_data"
            WHERE "Guild" = p_guild_code
        );
    END IF;
END;
$$;

ALTER FUNCTION public.get_accurate_battle_count(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_active_clusters() RETURNS TABLE(cluster_code character varying, cluster_name character varying, guild_count bigint, has_discord_webhook boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.cluster_code,
    c.display_name AS cluster_name,
    COUNT(DISTINCT gc.guild_code) as guild_count,
    EXISTS(
      SELECT 1 FROM cluster_discord_config cdc
      WHERE cdc.cluster_id = c.id
      AND cdc.enabled = true
    ) as has_discord_webhook
  FROM clusters c
  LEFT JOIN guild_config gc ON gc.cluster_id = c.id AND gc.enabled = true
  WHERE c.is_active = true
  GROUP BY c.id, c.cluster_code, c.cluster_name;
END;
$$;

ALTER FUNCTION public.get_active_clusters() OWNER TO postgres;

CREATE FUNCTION public.get_activity_heatmap(p_guild_code text, p_days integer DEFAULT 14) RETURNS TABLE(player_name text, activity_date date, activity_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    gwa.player_name::TEXT,
    gwa.attempt_start_time::DATE as activity_date,
    COUNT(*)::BIGINT as activity_count
  FROM guild_war_player_attempts gwa
  WHERE gwa.guild_code = p_guild_code
    AND gwa.is_guild_member = TRUE
    AND gwa.attempt_start_time >= NOW() - (p_days || ' days')::INTERVAL
  GROUP BY gwa.player_name, gwa.attempt_start_time::DATE
  ORDER BY gwa.player_name, gwa.attempt_start_time::DATE;
END;
$$;

ALTER FUNCTION public.get_activity_heatmap(p_guild_code text, p_days integer) OWNER TO postgres;

CREATE FUNCTION public.get_admin_support_unread_count() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  DECLARE
    total_unread INTEGER;
  BEGIN
    SELECT COALESCE(SUM(admin_unread_count), 0)
    INTO total_unread
    FROM support_tickets
    WHERE status IN ('open', 'in_progress')
      AND admin_unread_count > 0;

    RETURN total_unread;
  END;
  $$;

