CREATE FUNCTION public.get_all_boss_hp(p_guild_code text DEFAULT NULL::text) RETURNS TABLE(boss_name text, rarity text, set_level integer, encounter_id integer, max_hp bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH boss_battles AS (
    -- Get all boss battles with damage and remaining HP
    SELECT
      g."Name" as boss_name,
      g."rarity" as rarity,
      g."set" as set_level,
      g."encounterId" as encounter_id,
      g."damageDealt" + g."remainingHp" as total_hp
    FROM "EOT_GR_data" g
    WHERE
      g."rarity" IN ('Legendary', 'Mythic')
      AND g."damageType" = 'Battle'
      AND g."damageDealt" > 0
      AND g."Name" IS NOT NULL
      AND (p_guild_code IS NULL OR g."Guild" = p_guild_code)
  ),
  max_hp_per_boss AS (
    -- Get the maximum HP seen for each boss/level/encounter combination
    SELECT
      boss_name,
      rarity,
      set_level,
      encounter_id,
      MAX(total_hp) as max_hp
    FROM boss_battles
    GROUP BY boss_name, rarity, set_level, encounter_id
  )
  SELECT
    boss_name::TEXT,
    rarity::TEXT,
    set_level::INT,
    encounter_id::INT,
    max_hp::BIGINT
  FROM max_hp_per_boss
  WHERE max_hp > 0
  ORDER BY
    CASE rarity
      WHEN 'Mythic' THEN 1
      WHEN 'Legendary' THEN 2
      ELSE 3
    END,
    set_level DESC,
    encounter_id,
    boss_name;
END;
$$;

ALTER FUNCTION public.get_all_boss_hp(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_api_base_url() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  base_url TEXT;
BEGIN
  -- Configured URL wins
  base_url := current_setting('app.settings.api_base_url', true);

  -- Default to the conventional application service name for self-hosting.
  IF base_url IS NULL OR base_url = '' THEN
    base_url := 'http://nextjs-web:3000';
  END IF;

  RETURN base_url;
END;
$$;

ALTER FUNCTION public.get_api_base_url() OWNER TO postgres;

CREATE FUNCTION public.get_app_health_for_support() RETURNS TABLE(db_ok boolean, sync_recent boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Access denied: authentication required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    true,
    EXISTS (
      SELECT 1 FROM public.guild_sync_status gss
      WHERE gss.last_sync > now() - interval '6 hours'
    );
END;
$$;

ALTER FUNCTION public.get_app_health_for_support() OWNER TO postgres;

