CREATE FUNCTION public.get_boss_best_hits(p_season text DEFAULT NULL::text, p_cluster_code text DEFAULT NULL::text, p_guild_code text DEFAULT NULL::text, p_rarity text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(boss_name text, rarity text, set integer, damage_dealt integer, player_name text, guild_code text, guild_name text, cluster_code text, cluster_name text, damage_type text, boss_order integer, team_composition jsonb)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_season TEXT;
BEGIN
    -- Use provided season or get latest
    IF p_season IS NULL THEN
        SELECT MAX(e."Season") INTO v_season
        FROM "EOT_GR_data" e
        WHERE e."Season" ~ '^\d+$';
    ELSE
        v_season := p_season;
    END IF;

    RETURN QUERY
    WITH best_hits AS (
        SELECT
            e."Name" AS boss_name,
            e."rarity"::TEXT,
            e."set"::INTEGER,
            e."damageDealt"::INTEGER AS damage_dealt,
            e."displayName"::TEXT AS player_name,
            e."Guild"::TEXT AS guild_code,
            e."damageType"::TEXT AS damage_type,
            -- Boss order for sorting (Mythic first, then by set descending)
            CASE
                WHEN e."rarity" = 'Mythic' THEN 0
                ELSE 1
            END * 100 + (4 - COALESCE(e."set", 0)) AS boss_order,
            -- Team composition data
            jsonb_build_object(
                'heroes', e."heroDetails",
                'mow', e."machineOfWarDetails"
            ) AS team_composition,
            e."Season"
        FROM "EOT_GR_data" e
        WHERE e."damageDealt" > 0
            AND e."Guild" NOT IN ('TEST', 'EOT', 'TBD')
            AND e."rarity" IN ('Legendary', 'Mythic')
            AND e."Season" = v_season
            AND (p_rarity IS NULL OR e."rarity" = p_rarity)
            AND (p_guild_code IS NULL OR e."Guild" = p_guild_code)
    ),
    enriched_hits AS (
        SELECT
            bh.*,
            COALESCE(gc.display_name, bh.guild_code)::TEXT AS guild_name,
            COALESCE(gc.cluster_code, 'INDEPENDENT')::TEXT AS cluster_code_final,
            COALESCE(c.display_name,
                CASE
                    WHEN gc.cluster_code IS NULL THEN 'Independent'
                    ELSE gc.cluster_code
                END
            )::TEXT AS cluster_name,
            gc.enabled
        FROM best_hits bh
        LEFT JOIN guild_config gc ON gc.guild_code = bh.guild_code
        LEFT JOIN clusters c ON c.cluster_code = gc.cluster_code
        WHERE (gc.enabled = true OR gc.enabled IS NULL OR gc.guild_code IS NULL)
            AND (p_cluster_code IS NULL OR
                 (p_cluster_code = 'INDEPENDENT' AND gc.cluster_code IS NULL) OR
                 gc.cluster_code = p_cluster_code)
    )
    SELECT
        eh.boss_name,
        eh.rarity,
        eh.set,
        eh.damage_dealt,
        eh.player_name,
        eh.guild_code,
        eh.guild_name,
        eh.cluster_code_final AS cluster_code,
        eh.cluster_name,
        eh.damage_type,
        eh.boss_order,
        eh.team_composition
    FROM enriched_hits eh
    ORDER BY
        eh.boss_order ASC,  -- Mythic first, then by set
        eh.boss_name ASC,   -- Then by boss name
        eh.damage_dealt DESC  -- Then by damage (highest first)
    LIMIT p_limit;
END;
$_$;

ALTER FUNCTION public.get_boss_best_hits(p_season text, p_cluster_code text, p_guild_code text, p_rarity text, p_limit integer) OWNER TO postgres;

CREATE FUNCTION public.get_boss_difficulty_analysis(p_guild_code text, p_season text, p_rarities text[] DEFAULT ARRAY['Legendary'::text, 'Mythic'::text]) RETURNS TABLE(boss_name text, display_name text, rarity text, set_num integer, encounter_id integer, avg_attempts numeric, avg_time_minutes numeric, hit_count integer, total_damage bigint, completed_loops integer, total_loops integer, completion_rate numeric, avg_damage_per_attempt numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH battle_records AS (
    SELECT
      d."Name",
      d.rarity,
      d.set,
      d."encounterId",
      d."damageDealt",
      d."remainingHp",
      d."maxHp",
      d."loopIndex",
      d.timestamp,
      d."startedOn",
      d."completedOn",
      CASE
        WHEN d.rarity = 'Mythic' THEN 'M' || (COALESCE(d.set, 0) + 1)::TEXT
        ELSE 'L' || (COALESCE(d.set, 0) + 1)::TEXT
      END || ' ' || d."Name" AS boss_display_name
    FROM "EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND d."damageDealt" > 0
      AND d.rarity = ANY(p_rarities)
  ),
  boss_loop_stats AS (
    SELECT
      br."Name",
      br.rarity,
      br.set,
      br."encounterId",
      br.boss_display_name,
      br."loopIndex",
      COUNT(*)::INTEGER AS loop_attempts,
      SUM(br."damageDealt")::BIGINT AS loop_damage,
      MIN(COALESCE(br."startedOn", br.timestamp)) AS first_hit,
      MAX(COALESCE(br."completedOn", br.timestamp)) AS last_hit,
      MAX(br."maxHp") AS max_hp,
      (SELECT br2."remainingHp"
       FROM battle_records br2
       WHERE br2."Name" = br."Name"
         AND br2.rarity = br.rarity
         AND br2.set = br.set
         AND br2."encounterId" = br."encounterId"
         AND br2."loopIndex" = br."loopIndex"
       ORDER BY br2."completedOn" DESC NULLS LAST, br2.timestamp DESC NULLS LAST
       LIMIT 1) AS final_remaining_hp
    FROM battle_records br
    WHERE br."loopIndex" IS NOT NULL
    GROUP BY br."Name", br.rarity, br.set, br."encounterId", br.boss_display_name, br."loopIndex"
  ),
  boss_aggregates AS (
    SELECT
      bls."Name",
      bls.rarity,
      bls.set,
      bls."encounterId",
      bls.boss_display_name,
      COUNT(DISTINCT bls."loopIndex")::INTEGER AS total_loop_count,
      COUNT(DISTINCT bls."loopIndex") FILTER (
        WHERE bls.final_remaining_hp IS NOT NULL AND bls.final_remaining_hp <= 0
           OR (bls.max_hp > 0 AND bls.loop_damage >= bls.max_hp)
      )::INTEGER AS completed_loop_count,
      SUM(bls.loop_attempts) FILTER (
        WHERE bls.final_remaining_hp IS NOT NULL AND bls.final_remaining_hp <= 0
           OR (bls.max_hp > 0 AND bls.loop_damage >= bls.max_hp)
      )::INTEGER AS attempts_in_completed_loops,
      SUM(bls.loop_attempts)::INTEGER AS total_hits,
      SUM(bls.loop_damage)::BIGINT AS total_dmg,
      SUM(
        CASE
          WHEN (bls.final_remaining_hp IS NOT NULL AND bls.final_remaining_hp <= 0
                OR (bls.max_hp > 0 AND bls.loop_damage >= bls.max_hp))
               AND bls.first_hit IS NOT NULL AND bls.last_hit IS NOT NULL
               AND bls.last_hit > bls.first_hit
          THEN EXTRACT(EPOCH FROM (bls.last_hit - bls.first_hit)) / 60.0
          ELSE 0
        END
      ) AS total_completion_time_minutes
    FROM boss_loop_stats bls
    GROUP BY bls."Name", bls.rarity, bls.set, bls."encounterId", bls.boss_display_name
  )
  SELECT
    ba."Name" AS boss_name,
    ba.boss_display_name AS display_name,
    ba.rarity,
    ba.set AS set_num,
    ba."encounterId" AS encounter_id,
    CASE
      WHEN ba.completed_loop_count > 0
      THEN ROUND(ba.attempts_in_completed_loops::NUMERIC / ba.completed_loop_count, 2)
      ELSE 0
    END AS avg_attempts,
    CASE
      WHEN ba.completed_loop_count > 0
      THEN ROUND(ba.total_completion_time_minutes / ba.completed_loop_count, 2)
      ELSE 0
    END AS avg_time_minutes,
    ba.total_hits AS hit_count,
    ba.total_dmg AS total_damage,
    ba.completed_loop_count AS completed_loops,
    ba.total_loop_count AS total_loops,
    CASE
      WHEN ba.total_loop_count > 0
      THEN ROUND(ba.completed_loop_count::NUMERIC / ba.total_loop_count, 3)
      ELSE 0
    END AS completion_rate,
    CASE
      WHEN ba.total_hits > 0
      THEN ROUND(ba.total_dmg::NUMERIC / ba.total_hits, 0)
      ELSE 0
    END AS avg_damage_per_attempt
  FROM boss_aggregates ba
  ORDER BY
    CASE WHEN ba.rarity = 'Mythic' THEN 0 ELSE 1 END,
    ba.set DESC,
    avg_attempts DESC;
END;
$$;

ALTER FUNCTION public.get_boss_difficulty_analysis(p_guild_code text, p_season text, p_rarities text[]) OWNER TO postgres;

CREATE FUNCTION public.get_boss_encounters(p_guild_code text DEFAULT NULL::text, p_cluster_code text DEFAULT NULL::text, p_include_primes boolean DEFAULT true) RETURNS TABLE(guild_code text, guild_name text, cluster_code text, boss_name text, rarity text, set integer, encounter_id integer, is_prime boolean, players_attempted bigint, total_attacks bigint, times_killed bigint, avg_damage integer, max_damage bigint, total_damage numeric, champion_name text, level_label text, rarity_sort_order integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    IF p_guild_code IS NOT NULL THEN
        -- Return guild-specific data
        RETURN QUERY
        SELECT
            bg.guild_code,
            bg.guild_name,
            bg.cluster_code,
            bg.boss_name,
            bg.rarity,
            bg.set,
            bg.encounter_id,
            bg.is_prime,
            bg.players_attempted,
            bg.total_attacks,
            bg.times_killed,
            bg.avg_damage,
            bg.max_damage,
            bg.total_damage,
            bg.champion_name,
            bg.level_label,
            bg.rarity_sort_order
        FROM boss_encounters_guild_public bg
        WHERE bg.guild_code = p_guild_code
            AND (p_include_primes OR bg.encounter_id = 0);
    ELSIF p_cluster_code IS NOT NULL THEN
        -- Return cluster-aggregated data
        RETURN QUERY
        SELECT
            NULL::TEXT AS guild_code,
            NULL::TEXT AS guild_name,
            p_cluster_code AS cluster_code,
            bc.boss_name,
            bc.rarity,
            bc.set,
            bc.encounter_id,
            bc.is_prime,
            bc.players_attempted,
            bc.total_attacks,
            bc.times_killed,
            bc.avg_damage,
            bc.max_damage,
            bc.total_damage,
            bc.champion_name,
            bc.level_label,
            bc.rarity_sort_order
        FROM boss_encounters_cluster_public bc
        WHERE p_include_primes OR bc.encounter_id = 0;
    ELSE
        -- Return all cluster data if no filter
        RETURN QUERY
        SELECT
            NULL::TEXT AS guild_code,
            NULL::TEXT AS guild_name,
            'ALL'::TEXT AS cluster_code,
            bc.boss_name,
            bc.rarity,
            bc.set,
            bc.encounter_id,
            bc.is_prime,
            bc.players_attempted,
            bc.total_attacks,
            bc.times_killed,
            bc.avg_damage,
            bc.max_damage,
            bc.total_damage,
            bc.champion_name,
            bc.level_label,
            bc.rarity_sort_order
        FROM boss_encounters_cluster_public bc
        WHERE p_include_primes OR bc.encounter_id = 0;
    END IF;
END;
$$;

ALTER FUNCTION public.get_boss_encounters(p_guild_code text, p_cluster_code text, p_include_primes boolean) OWNER TO postgres;

CREATE FUNCTION public.get_boss_encounters_by_cluster(p_season text DEFAULT NULL::text) RETURNS TABLE(boss_name text, cluster_code text, rarity text, set integer, total_damage bigint, unique_players bigint, tokens_used bigint, max_damage integer, champion text, champion_guild text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_season TEXT;
BEGIN
    -- Use provided season or get latest
    IF p_season IS NULL THEN
        SELECT MAX(e."Season") INTO v_season
        FROM "EOT_GR_data" e
        WHERE e."Season" ~ '^\d+$';
    ELSE
        v_season := p_season;
    END IF;

    RETURN QUERY
    WITH all_data AS (
        SELECT
            e."Name" AS boss_name,
            e."Guild" AS guild_code,
            e."rarity",
            e."set",
            e."damageDealt",
            e."displayName" AS player_name,
            e."damageType",
            e."Season"
        FROM "EOT_GR_data" e
        WHERE e."damageDealt" > 0
            AND e."Guild" NOT IN ('TEST', 'EOT', 'TBD')
            AND e."rarity" IN ('Legendary', 'Mythic')
            AND e."Season" = v_season
    ),
    enriched_data AS (
        SELECT
            ad.*,
            gc.display_name AS guild_name,
            COALESCE(gc.cluster_code, 'INDEPENDENT')::TEXT AS cluster_code_final,
            gc.enabled
        FROM all_data ad
        LEFT JOIN guild_config gc ON gc.guild_code = ad.guild_code
        WHERE (gc.enabled = true OR gc.enabled IS NULL OR gc.guild_code IS NULL)
    ),
    cluster_aggregates AS (
        SELECT
            ed.boss_name::TEXT,
            ed.cluster_code_final,
            ed.rarity::TEXT,
            MAX(ed.set)::INTEGER AS set,
            SUM(ed."damageDealt")::BIGINT AS total_damage,
            COUNT(DISTINCT ed.player_name)::BIGINT AS unique_players,
            COUNT(CASE WHEN ed."damageType" = 'Battle' THEN 1 END)::BIGINT AS tokens_used,
            MAX(ed."damageDealt")::INTEGER AS max_damage
        FROM enriched_data ed
        GROUP BY ed.boss_name, ed.cluster_code_final, ed.rarity
    ),
    cluster_champions AS (
        SELECT DISTINCT ON (ed.boss_name, ed.cluster_code_final)
            ed.boss_name::TEXT,
            ed.cluster_code_final,
            ed.player_name::TEXT AS champion,
            ed.guild_name::TEXT AS champion_guild
        FROM enriched_data ed
        WHERE ed."damageType" = 'Battle'
        ORDER BY ed.boss_name, ed.cluster_code_final, ed."damageDealt" DESC
    )
    SELECT
        ca.boss_name,
        ca.cluster_code_final,
        ca.rarity,
        ca.set,
        ca.total_damage,
        ca.unique_players,
        ca.tokens_used,
        ca.max_damage,
        cc.champion,
        cc.champion_guild
    FROM cluster_aggregates ca
    LEFT JOIN cluster_champions cc
        ON cc.boss_name = ca.boss_name
        AND cc.cluster_code_final = ca.cluster_code_final
    ORDER BY ca.total_damage DESC;
END;
$_$;

ALTER FUNCTION public.get_boss_encounters_by_cluster(p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_boss_encounters_by_guild(p_season text DEFAULT NULL::text, p_guild_code text DEFAULT NULL::text) RETURNS TABLE(boss_name text, guild_code text, guild_name text, cluster_code text, rarity text, set integer, total_damage bigint, unique_players bigint, tokens_used bigint, max_damage integer, champion text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_season TEXT;
BEGIN
    -- Use provided season or get latest
    IF p_season IS NULL THEN
        SELECT MAX(e."Season") INTO v_season
        FROM "EOT_GR_data" e
        WHERE e."Season" ~ '^\d+$';
    ELSE
        v_season := p_season;
    END IF;

    RETURN QUERY
    WITH all_data AS (
        SELECT
            e."Name" AS boss_name,
            e."Guild" AS guild_code,
            e."rarity",
            e."set",
            e."damageDealt",
            e."displayName" AS player_name,
            e."damageType",
            e."Season"
        FROM "EOT_GR_data" e
        WHERE e."damageDealt" > 0
            AND e."Guild" NOT IN ('TEST', 'EOT', 'TBD')
            AND e."rarity" IN ('Legendary', 'Mythic')
            AND e."Season" = v_season
            AND (p_guild_code IS NULL OR e."Guild" = p_guild_code)
    ),
    enriched_data AS (
        SELECT
            ad.*,
            COALESCE(gc.display_name, ad.guild_code)::TEXT AS guild_name,
            COALESCE(gc.cluster_code, 'INDEPENDENT')::TEXT AS cluster_code_final,
            gc.enabled
        FROM all_data ad
        LEFT JOIN guild_config gc ON gc.guild_code = ad.guild_code
        WHERE (gc.enabled = true OR gc.enabled IS NULL OR gc.guild_code IS NULL)
    ),
    guild_aggregates AS (
        SELECT
            ed.boss_name::TEXT,
            ed.guild_code::TEXT,
            ed.guild_name,
            ed.cluster_code_final,
            ed.rarity::TEXT,
            MAX(ed.set)::INTEGER AS set,
            SUM(ed."damageDealt")::BIGINT AS total_damage,
            COUNT(DISTINCT ed.player_name)::BIGINT AS unique_players,
            COUNT(CASE WHEN ed."damageType" = 'Battle' THEN 1 END)::BIGINT AS tokens_used,
            MAX(ed."damageDealt")::INTEGER AS max_damage
        FROM enriched_data ed
        GROUP BY ed.boss_name, ed.guild_code, ed.guild_name, ed.cluster_code_final, ed.rarity
    ),
    guild_champions AS (
        SELECT DISTINCT ON (ed.boss_name, ed.guild_code)
            ed.boss_name::TEXT,
            ed.guild_code::TEXT,
            ed.player_name::TEXT AS champion
        FROM enriched_data ed
        WHERE ed."damageType" = 'Battle'
        ORDER BY ed.boss_name, ed.guild_code, ed."damageDealt" DESC
    )
    SELECT
        ga.boss_name,
        ga.guild_code,
        ga.guild_name,
        ga.cluster_code_final,
        ga.rarity,
        ga.set,
        ga.total_damage,
        ga.unique_players,
        ga.tokens_used,
        ga.max_damage,
        gc.champion
    FROM guild_aggregates ga
    LEFT JOIN guild_champions gc
        ON gc.boss_name = ga.boss_name
        AND gc.guild_code = ga.guild_code
    ORDER BY ga.guild_code, ga.total_damage DESC;
END;
$_$;

ALTER FUNCTION public.get_boss_encounters_by_guild(p_season text, p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_boss_encounters_cluster(p_season text, p_cluster_code text DEFAULT NULL::text) RETURNS TABLE(boss_level text, boss_name text, rarity text, set_number integer, encounter_count bigint, unique_players bigint, total_damage numeric, avg_damage numeric, max_damage numeric, success_rate numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    CASE
      WHEN e.rarity = 'Mythic' THEN 'M' || (e.set + 1)::text
      WHEN e.rarity = 'Legendary' THEN 'L' || (e.set + 1)::text
      WHEN e.rarity = 'Epic' THEN 'E' || (e.set + 1)::text
      WHEN e.rarity = 'Rare' THEN 'R' || (e.set + 1)::text
      WHEN e.rarity = 'Uncommon' THEN 'U' || (e.set + 1)::text
      WHEN e.rarity = 'Common' THEN 'C' || (e.set + 1)::text
      ELSE e.rarity || (e.set + 1)::text
    END as boss_level,
    COALESCE(e."Name", 'Unknown Boss') as boss_name,
    e.rarity,
    e.set as set_number,
    COUNT(*) as encounters,
    COUNT(DISTINCT e."displayName") as players,
    SUM(e."damageDealt") as total_dmg,
    ROUND(AVG(e."damageDealt"), 0) as avg_dmg,
    MAX(e."damageDealt") as max_dmg,
    ROUND(100.0 * SUM(CASE WHEN e."damageDealt" > 0 THEN 1 ELSE 0 END) / COUNT(*), 1) as success_rt
  FROM "EOT_GR_data" e
  WHERE e."Season" = p_season
    AND (p_cluster_code IS NULL OR e.cluster_code = p_cluster_code)
    AND e.rarity IN ('Common', 'Uncommon', 'Rare', 'Epic', 'Legendary', 'Mythic')
  GROUP BY e.rarity, e.set, e."Name"
  ORDER BY
    CASE e.rarity
      WHEN 'Mythic' THEN 1
      WHEN 'Legendary' THEN 2
      WHEN 'Epic' THEN 3
      WHEN 'Rare' THEN 4
      WHEN 'Uncommon' THEN 5
      WHEN 'Common' THEN 6
    END,
    e.set DESC;
END;
$$;

ALTER FUNCTION public.get_boss_encounters_cluster(p_season text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_boss_leaderboard(p_guild_code text, p_season text, p_boss_level text, p_limit integer DEFAULT 10) RETURNS TABLE(player_name text, damage_dealt numeric, battle_time interval, team_composition text[], rank integer)
    LANGUAGE plpgsql STABLE
    AS $_$
    BEGIN
      RETURN QUERY
      WITH ranked_battles AS (
        SELECT
          e."displayName" as player_name,
          e."damageDealt" as damage_dealt,
          (e."completedOn" - e."startedOn") as battle_time,
          CASE
            WHEN e."heroDetails" IS NOT NULL AND e."heroDetails"::text != '[]'
            THEN ARRAY(
              SELECT jsonb_array_elements_text(
                jsonb_path_query_array(e."heroDetails"::jsonb, '$[*].unitId')
              )
            )
            ELSE ARRAY[]::text[]
          END as team_comp,
          ROW_NUMBER() OVER (ORDER BY e."damageDealt" DESC) as rank
        FROM "EOT_GR_data" e
        WHERE e."Guild" = p_guild_code
          AND e."Season" = p_season
          AND CASE
            WHEN e.rarity = 'Mythic' THEN 'M' || (e.set + 1)::text
            WHEN e.rarity = 'Legendary' THEN 'L' || (e.set + 1)::text
            WHEN e.rarity = 'Epic' THEN 'E' || (e.set + 1)::text
            WHEN e.rarity = 'Rare' THEN 'R' || (e.set + 1)::text
            WHEN e.rarity = 'Uncommon' THEN 'U' || (e.set + 1)::text
            WHEN e.rarity = 'Common' THEN 'C' || (e.set + 1)::text
            ELSE e.rarity || (e.set + 1)::text
          END = p_boss_level
          AND e."damageDealt" > 0
      )
      SELECT
        player_name,
        damage_dealt,
        battle_time,
        team_comp,
        rank::integer
      FROM ranked_battles
      WHERE rank <= p_limit
      ORDER BY rank;
    END;
    $_$;

ALTER FUNCTION public.get_boss_leaderboard(p_guild_code text, p_season text, p_boss_level text, p_limit integer) OWNER TO postgres;

CREATE FUNCTION public.get_boss_performance_overview(p_guild_code text, p_season text, p_level text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_rarity text;
  v_level_number integer;
  v_set integer;
  v_cluster text;
  v_result jsonb;
  v_is_service boolean := COALESCE(
    NULLIF(NULLIF(current_setting('role', true), ''), 'none'),
    NULLIF(session_user, '')
  ) = 'service_role';
BEGIN
  -- WI-3139 caller-bound scope guard; effective service_role bypasses.
  -- Unauthorized callers get a NULL payload (the browser hook renders the
  -- empty state), matching the RLS-style no-leak convention.
  IF NOT v_is_service AND NOT COALESCE(
    p_guild_code IN (SELECT public._pm_caller_guild_codes())
    OR p_guild_code IN (SELECT public._pm_caller_cluster_guild_codes())
    OR public._pm_caller_is_app_admin(),
    FALSE
  ) THEN
    RETURN NULL;
  END IF;
  IF p_level IS NULL OR length(p_level) = 0 THEN
    RAISE EXCEPTION 'Level is required';
  END IF;

  v_rarity := CASE upper(left(p_level, 1))
    WHEN 'M' THEN 'Mythic'
    WHEN 'E' THEN 'Epic'
    WHEN 'R' THEN 'Rare'
    WHEN 'U' THEN 'Uncommon'
    WHEN 'C' THEN 'Common'
    ELSE 'Legendary'
  END;

  v_level_number := NULLIF(regexp_replace(p_level, '[^0-9]', '', 'g'), '')::integer;
  v_set := GREATEST(0, COALESCE(v_level_number, 1) - 1);

  SELECT cluster_code INTO v_cluster
  FROM guild_config
  WHERE guild_code = p_guild_code
  LIMIT 1;

  WITH filtered AS (
    SELECT *
    FROM "EOT_GR_data"
    WHERE "Guild" = p_guild_code
      AND "Season" = p_season
      AND "set" = v_set
      AND "rarity" = v_rarity
      AND "damageType" = 'Battle'
      AND (
        v_cluster IS NULL
        OR v_cluster = ''
        OR "cluster_code" = v_cluster
      )
  ),
  boss_meta AS (
    SELECT
      COALESCE(
        (
          SELECT bm.boss_name
          FROM boss_mapping bm
          WHERE bm.boss_type = base_type
            AND bm.encounter_index = 0
          ORDER BY bm.auto_generated ASC NULLS LAST
          LIMIT 1
        ),
        base_type,
        'Boss ' || p_level
      ) AS boss_name,
      COALESCE(base_type, 'Unknown') AS boss_type
    FROM (
      SELECT
        COALESCE(
          MAX(NULLIF("type", '')),
          MAX(NULLIF("Name", ''))
        ) AS base_type
      FROM filtered
      WHERE COALESCE("encounterId", 0) = 0
    ) bt
  ),
  non_sweep AS (
    SELECT *
    FROM filtered
    WHERE COALESCE("encounterId", 0) = 0
      AND COALESCE("damageDealt", 0) > 0
      -- WI-2520: sweep-free but ONE-SHOT-INCLUSIVE. The old blanket
      -- `remainingHp <> 0` also dropped one-shots from card averages,
      -- biggest-hit and distributions.
      AND NOT (
        COALESCE("remainingHp", 0) = 0
        AND COALESCE("maxHp", 0) > 0
        AND COALESCE("damageDealt", 0) < "maxHp"
      )
  ),
  -- TRUE token counts: ALL boss tokens per player (no damage/sweep filter)
  boss_all_token_counts AS (
    SELECT "displayName", COUNT(*) AS all_tokens
    FROM filtered
    WHERE COALESCE("encounterId", 0) = 0
    GROUP BY "displayName"
  ),
  -- TRUE token counts: ALL boss tokens per lap
  boss_all_lap_counts AS (
    SELECT COALESCE("loopIndex", 0) AS lap, COUNT(*) AS all_tokens
    FROM filtered
    WHERE COALESCE("encounterId", 0) = 0
    GROUP BY COALESCE("loopIndex", 0)
  ),
  -- TRUE token counts: ALL prime tokens per player
  prime_all_token_counts AS (
    SELECT "displayName", COUNT(*) AS all_tokens
    FROM filtered
    WHERE COALESCE("encounterId", 0) > 0
    GROUP BY "displayName"
  ),
  main_hits AS (
    SELECT COALESCE("damageDealt", 0)::numeric AS dmg
    FROM non_sweep
  ),
  prime_rows AS (
    SELECT *
    FROM filtered
    WHERE COALESCE("encounterId", 0) > 0
      AND COALESCE("damageDealt", 0) > 0
  ),
  prime_named_rows AS (
    SELECT
      pr.*,
      COALESCE(
        (
          SELECT bm.boss_name
          FROM boss_mapping bm
          WHERE bm.boss_type = COALESCE(NULLIF(pr."type", ''), bm_base.boss_type)
            AND bm.encounter_index = COALESCE(pr."encounterId", 0)
          ORDER BY bm.auto_generated ASC NULLS LAST
          LIMIT 1
        ),
        COALESCE(NULLIF(pr."type", ''), pr."Name", 'Prime Boss')
      ) AS resolved_boss_name
    FROM prime_rows pr
    CROSS JOIN boss_meta bm_base
  ),
  player_stats AS (
    SELECT
      ns."displayName" AS display_name,
      AVG(ns."damageDealt") AS avg_damage,
      MAX(ns."damageDealt") AS max_hit,
      SUM(ns."damageDealt") AS total_damage,
      COALESCE(bat.all_tokens, COUNT(*))::bigint AS token_count,
      SUM(ns."damageDealt") / NULLIF(COUNT(*), 0) AS efficiency
    FROM non_sweep ns
    LEFT JOIN boss_all_token_counts bat ON bat."displayName" = ns."displayName"
    GROUP BY ns."displayName", bat.all_tokens
  ),
  prime_stats AS (
    SELECT
      pr."displayName" AS display_name,
      AVG(pr."damageDealt") AS avg_damage,
      MAX(pr."damageDealt") AS max_hit,
      COALESCE(pat.all_tokens, COUNT(*))::bigint AS token_count
    FROM prime_rows pr
    LEFT JOIN prime_all_token_counts pat ON pat."displayName" = pr."displayName"
    GROUP BY pr."displayName", pat.all_tokens
  ),
  prime_ranked AS (
    SELECT *,
      ROW_NUMBER() OVER (ORDER BY token_count DESC, avg_damage DESC) AS rnk
    FROM prime_stats
  ),
  prime_boss_players AS (
    SELECT
      resolved_boss_name AS boss_name,
      "displayName" AS display_name,
      AVG("damageDealt") AS avg_damage,
      MAX("damageDealt") AS max_hit,
      COUNT(*) AS token_count
    FROM prime_named_rows
    GROUP BY resolved_boss_name, "displayName"
  ),
  prime_boss_ranked AS (
    SELECT *,
      ROW_NUMBER() OVER (PARTITION BY boss_name ORDER BY avg_damage DESC, token_count DESC) AS boss_rank
    FROM prime_boss_players
  ),
  lap_trends AS (
    SELECT
      COALESCE(ns."loopIndex", 0) AS lap,
      AVG(ns."damageDealt") AS avg_damage,
      COALESCE(blc.all_tokens, COUNT(*))::bigint AS token_count
    FROM non_sweep ns
    LEFT JOIN boss_all_lap_counts blc ON blc.lap = COALESCE(ns."loopIndex", 0)
    GROUP BY COALESCE(ns."loopIndex", 0), blc.all_tokens
  ),
  top_stats AS (
    SELECT jsonb_build_object(
      'topTotalDamagePlayer',
      (SELECT display_name FROM player_stats ORDER BY total_damage DESC LIMIT 1),
      'topTotalDamage',
      COALESCE((SELECT total_damage FROM player_stats ORDER BY total_damage DESC LIMIT 1), 0),
      'biggestHitPlayer',
      (SELECT "displayName" FROM non_sweep ORDER BY COALESCE("damageDealt", 0) DESC LIMIT 1),
      'biggestHit',
      COALESCE((SELECT MAX("damageDealt") FROM non_sweep), 0),
      'totalBossTokens',
      (SELECT COUNT(*) FROM filtered WHERE COALESCE("encounterId", 0) = 0),
      'totalPrimeTokens',
      (SELECT COUNT(*) FROM filtered WHERE COALESCE("encounterId", 0) > 0),
      'overallAvgDamage',
      COALESCE((SELECT AVG("damageDealt") FROM non_sweep), 0)
    ) AS payload
  ),
  main_distribution AS (
    SELECT CASE
      WHEN EXISTS (SELECT 1 FROM main_hits)
        THEN jsonb_build_object(
          'name', (SELECT boss_name FROM boss_meta),
          'min', MIN(dmg),
          'q1', percentile_cont(0.25) WITHIN GROUP (ORDER BY dmg),
          'median', percentile_cont(0.5) WITHIN GROUP (ORDER BY dmg),
          'q3', percentile_cont(0.75) WITHIN GROUP (ORDER BY dmg),
          'max', MAX(dmg),
          'sampleSize', COUNT(*)
        )
      ELSE NULL
    END AS payload
    FROM main_hits
  ),
  prime_distribution_stats AS (
    SELECT jsonb_build_object(
      'name', resolved_boss_name,
      'min', MIN(dmg),
      'q1', percentile_cont(0.25) WITHIN GROUP (ORDER BY dmg),
      'median', percentile_cont(0.5) WITHIN GROUP (ORDER BY dmg),
      'q3', percentile_cont(0.75) WITHIN GROUP (ORDER BY dmg),
      'max', MAX(dmg),
      'sampleSize', COUNT(*)
    ) AS payload
    FROM (
      SELECT
        resolved_boss_name,
        COALESCE("damageDealt", 0)::numeric AS dmg
      FROM prime_named_rows
    ) p
    GROUP BY resolved_boss_name
  ),
  prime_distributions AS (
    SELECT COALESCE(
      jsonb_agg(payload ORDER BY payload->>'name'),
      '[]'::jsonb
    ) AS payload
    FROM prime_distribution_stats
  ),
  assigned_players AS (
    SELECT jsonb_build_object(
      'primary', COALESCE(
        (
          SELECT jsonb_agg(display_name ORDER BY display_name)
          FROM player_with_cluster pwc
          WHERE pwc.guild_code = p_guild_code
            AND (v_cluster IS NULL OR v_cluster = '' OR pwc.cluster_code = v_cluster)
            AND pwc.primary_boss = (SELECT boss_name FROM boss_meta)
        ),
        '[]'::jsonb
      ),
      'secondary', COALESCE(
        (
          SELECT jsonb_agg(display_name ORDER BY display_name)
          FROM player_with_cluster pwc
          WHERE pwc.guild_code = p_guild_code
            AND (v_cluster IS NULL OR v_cluster = '' OR pwc.cluster_code = v_cluster)
            AND pwc.secondary_boss = (SELECT boss_name FROM boss_meta)
        ),
        '[]'::jsonb
      )
    ) AS payload
  ),
  prime_boss_json AS (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'bossName', boss_name,
          'playerStats', players
        )
        ORDER BY boss_name
      ),
      '[]'::jsonb
    ) AS payload
    FROM (
      SELECT
        boss_name,
        jsonb_agg(
          jsonb_build_object(
            'displayName', display_name,
            'avgDamage', avg_damage,
            'maxHit', max_hit,
            'tokenCount', token_count
          )
          ORDER BY avg_damage DESC, token_count DESC
        ) AS players
      FROM prime_boss_ranked
      WHERE boss_rank <= 20
      GROUP BY boss_name
    ) s
  )
  SELECT jsonb_build_object(
    'bossName', (SELECT boss_name FROM boss_meta), 'bossType', (SELECT boss_type FROM boss_meta),
    'playerStats', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'displayName', display_name,
            'avgDamage', avg_damage,
            'maxHit', max_hit,
            'totalDamage', total_damage,
            'tokenCount', token_count,
            'efficiency', efficiency
          )
          ORDER BY avg_damage DESC
        )
        FROM player_stats
      ),
      '[]'::jsonb
    ),
    'primeStats', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'displayName', display_name,
            'avgDamage', avg_damage,
            'maxHit', max_hit,
            'tokenCount', token_count
          )
          ORDER BY token_count DESC, avg_damage DESC
        )
        FROM prime_ranked
        WHERE rnk <= 30
      ),
      '[]'::jsonb
    ),
    'primeBossStats', (SELECT payload FROM prime_boss_json),
    'primeDistributions', (SELECT payload FROM prime_distributions),
    'lapTrends', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'lap', lap + 1,
            'avgDamage', avg_damage,
            'tokenCount', token_count
          )
          ORDER BY lap
        )
        FROM lap_trends
      ),
      '[]'::jsonb
    ),
    'topStats', (SELECT payload FROM top_stats),
    'mainDistribution', (SELECT payload FROM main_distribution),
    'assignedPlayers', (SELECT payload FROM assigned_players),
    'hasPrimeData', EXISTS(SELECT 1 FROM prime_rows),
    'hasCluster', (v_cluster IS NOT NULL AND v_cluster <> '')
  )
  INTO v_result;

  RETURN v_result;
END;
$$;

ALTER FUNCTION public.get_boss_performance_overview(p_guild_code text, p_season text, p_level text) OWNER TO postgres;

CREATE FUNCTION public.get_boss_playbook(p_boss_id text) RETURNS TABLE(content text, updated_at timestamp with time zone, updated_by uuid, version integer, updater_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        bp.content,
        bp.updated_at,
        bp.updated_by,
        bp.version,
        COALESCE(p.username, 'Unknown') as updater_name
    FROM public.boss_playbooks bp
    LEFT JOIN public.profiles p ON p.id = bp.updated_by
    WHERE bp.boss_id = p_boss_id;
END;
$$;

ALTER FUNCTION public.get_boss_playbook(p_boss_id text) OWNER TO postgres;

CREATE FUNCTION public.get_boss_summary(p_season text DEFAULT NULL::text, p_cluster_code text DEFAULT NULL::text, p_guild_code text DEFAULT NULL::text, p_rarity text DEFAULT NULL::text, p_tier_min integer DEFAULT NULL::integer, p_tier_max integer DEFAULT NULL::integer) RETURNS TABLE(boss_name text, rarity text, set integer, total_damage bigint, unique_players integer, battle_count integer, max_hit integer, avg_hit numeric, top_player text, top_player_guild text, boss_order integer, tier_min integer, tier_max integer, loop_number integer, encounter_index integer, sub_boss_name text)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_season text;
  v_loop_number integer;
BEGIN
  IF auth.uid() IS NOT NULL
     AND p_guild_code IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.player_mapping pm
       WHERE pm.user_id = auth.uid()
         AND pm.guild_code = p_guild_code
         AND COALESCE(pm.is_current, false) = true
     ) THEN
    RAISE EXCEPTION 'Not authorized for guild %', p_guild_code
      USING ERRCODE = '42501';
  END IF;

  IF p_tier_min IS NOT NULL AND p_tier_max IS NOT NULL AND p_tier_min > p_tier_max THEN
    RAISE EXCEPTION 'p_tier_min must be less than or equal to p_tier_max';
  END IF;

  IF p_tier_min IS NOT NULL
     AND p_tier_max IS NOT NULL
     AND p_tier_min >= 4
     AND p_tier_max = p_tier_min + 1
     AND MOD(p_tier_min, 2) = 0 THEN
    v_loop_number := (p_tier_min - 4) / 2;
  END IF;

  IF p_season IS NULL THEN
    SELECT MAX(e."Season") INTO v_season
    FROM public."EOT_GR_data" e
    WHERE e."Season" ~ '^\d+$';
  ELSE
    v_season := p_season;
  END IF;

  RETURN QUERY
  WITH boss_data AS (
    SELECT
      e."Name"::text AS boss_name,
      e."rarity"::text AS rarity,
      e."set"::integer AS set,
      e."tier"::integer AS tier,
      CASE
        WHEN e."encounterId"::text ~ '^\d+$' THEN e."encounterId"::integer
        ELSE 0
      END AS encounter_index,
      e."damageDealt"::integer AS damage_dealt,
      e."displayName"::text AS player_name,
      e."Guild"::text AS guild_code,
      e."damageType"::text AS damage_type,
      CASE
        WHEN e."rarity" = 'Mythic' THEN 0
        ELSE 1
      END * 100 + (4 - COALESCE(e."set", 0)) AS boss_order
    FROM public."EOT_GR_data" e
    WHERE e."damageDealt" > 0
      AND e."Guild" NOT IN ('TEST', 'EOT', 'TBD')
      AND e."rarity" IN ('Legendary', 'Mythic')
      AND e."Season" = v_season
      AND (p_rarity IS NULL OR e."rarity" = p_rarity)
      AND (p_guild_code IS NULL OR e."Guild" = p_guild_code)
      AND (
        v_loop_number IS NULL
        OR COALESCE(
          e."loopIndex"::integer,
          CASE
            WHEN e."tier" IS NULL THEN NULL
            WHEN e."tier" >= 4 THEN ((e."tier"::integer - 4) / 2)
            ELSE 0
          END
        ) = v_loop_number
      )
      AND (p_tier_min IS NULL OR e."tier" >= p_tier_min)
      AND (p_tier_max IS NULL OR e."tier" <= p_tier_max)
  ),
  enriched_data AS (
    SELECT
      bd.*,
      gc.display_name AS guild_name,
      gc.cluster_code,
      gc.enabled
    FROM boss_data bd
    LEFT JOIN public.guild_config gc ON gc.guild_code = bd.guild_code
    WHERE (gc.enabled = true OR gc.enabled IS NULL OR gc.guild_code IS NULL)
      AND (
        p_guild_code IS NOT NULL
        OR p_cluster_code IS NULL
        OR (p_cluster_code = 'INDEPENDENT' AND gc.cluster_code IS NULL)
        OR gc.cluster_code = p_cluster_code
      )
  ),
  boss_aggregates AS (
    SELECT
      ed.boss_name::text,
      ed.rarity,
      MAX(ed.set)::integer AS set,
      SUM(ed.damage_dealt)::bigint AS total_damage,
      COUNT(DISTINCT ed.player_name)::integer AS unique_players,
      COUNT(CASE WHEN ed.damage_type = 'Battle' THEN 1 END)::integer AS battle_count,
      MAX(ed.damage_dealt)::integer AS max_hit,
      AVG(CASE WHEN ed.damage_type = 'Battle' THEN ed.damage_dealt END)::numeric(10, 0) AS avg_hit,
      MIN(ed.boss_order)::integer AS boss_order,
      MIN(ed.tier)::integer AS tier_min,
      MAX(ed.tier)::integer AS tier_max,
      ed.encounter_index::integer
    FROM enriched_data ed
    GROUP BY ed.boss_name, ed.rarity, ed.encounter_index
  ),
  top_players AS (
    SELECT DISTINCT ON (ed.boss_name, ed.rarity, ed.encounter_index)
      ed.boss_name::text,
      ed.rarity,
      ed.encounter_index,
      ed.player_name::text AS top_player,
      ed.guild_name::text AS top_player_guild
    FROM enriched_data ed
    WHERE ed.damage_type = 'Battle'
    ORDER BY ed.boss_name, ed.rarity, ed.encounter_index, ed.damage_dealt DESC
  )
  SELECT
    ba.boss_name,
    ba.rarity,
    ba.set,
    ba.total_damage,
    ba.unique_players,
    ba.battle_count,
    ba.max_hit,
    ba.avg_hit,
    tp.top_player,
    tp.top_player_guild,
    ba.boss_order,
    ba.tier_min,
    ba.tier_max,
    CASE
      WHEN ba.tier_min >= 4 AND ba.tier_min = ba.tier_max THEN (ba.tier_min - 4) / 2
      WHEN v_loop_number IS NOT NULL THEN v_loop_number
      ELSE NULL
    END AS loop_number,
    ba.encounter_index,
    CASE
      WHEN ba.encounter_index = 1 THEN ba.boss_name || ' [Prime Left]'
      WHEN ba.encounter_index = 2 THEN ba.boss_name || ' [Prime Right]'
      WHEN ba.encounter_index > 2 THEN ba.boss_name || ' [Prime ' || ba.encounter_index::text || ']'
      ELSE ba.boss_name
    END AS sub_boss_name
  FROM boss_aggregates ba
  LEFT JOIN top_players tp ON (
    tp.boss_name = ba.boss_name
    AND tp.rarity = ba.rarity
    AND tp.encounter_index = ba.encounter_index
  )
  ORDER BY ba.boss_order ASC, ba.boss_name ASC, ba.encounter_index ASC;
END;
$_$;

