CREATE FUNCTION public.get_checkout_session_data(p_guild_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    v_user_id uuid;
    v_is_leader boolean;
    v_guild_name text;
    v_existing_subscription record;
    v_tier record;
BEGIN
    v_user_id := auth.uid();

    -- Check if user is a guild leader
    SELECT EXISTS (
        SELECT 1 FROM player_mapping pm
        WHERE pm.user_id = v_user_id
            AND pm.guild_code = p_guild_code
            AND pm.is_current = true
            AND pm.role IN ('leader', 'officer')
    ) INTO v_is_leader;

    IF NOT v_is_leader THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only guild leaders can manage subscriptions'
        );
    END IF;

    -- Get guild name
    SELECT guild_name INTO v_guild_name
    FROM guild_config
    WHERE guild_code = p_guild_code;

    -- Check for existing active subscription
    SELECT * INTO v_existing_subscription
    FROM guild_subscriptions
    WHERE guild_code = p_guild_code
        AND status IN ('active', 'trialing');

    IF FOUND AND v_existing_subscription.stripe_subscription_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Guild already has an active subscription',
            'has_subscription', true,
            'stripe_customer_id', v_existing_subscription.stripe_customer_id
        );
    END IF;

    -- Get tier info
    SELECT * INTO v_tier
    FROM subscription_tiers
    WHERE tier_name = 'premium' AND is_active = true;

    RETURN jsonb_build_object(
        'success', true,
        'guild_code', p_guild_code,
        'guild_name', v_guild_name,
        'tier', jsonb_build_object(
            'name', v_tier.tier_name,
            'display_name', v_tier.display_name,
            'price_monthly', v_tier.price_monthly,
            'price_yearly', v_tier.price_yearly,
            'stripe_price_id_monthly', v_tier.stripe_price_id_monthly,
            'stripe_price_id_yearly', v_tier.stripe_price_id_yearly
        ),
        'existing_customer_id', v_existing_subscription.stripe_customer_id
    );
END;
$$;

ALTER FUNCTION public.get_checkout_session_data(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_api_key_coverage(p_cluster_code text) RETURNS TABLE(guild_code text, total_players bigint, active_players bigint, players_claimed bigint, players_with_api_key bigint, coverage_percentage numeric, guild_api_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_cluster_code IS NULL OR length(trim(p_cluster_code)) = 0 THEN
    RAISE EXCEPTION 'p_cluster_code is required'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.player_mapping pm
      JOIN public.guild_config gc ON gc.guild_code = pm.guild_code
      WHERE pm.user_id = (SELECT auth.uid())
        AND pm.is_current = true
        AND gc.cluster_code = p_cluster_code
    ) THEN
      RAISE EXCEPTION 'Access denied: cluster membership required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    cov.guild_code::text,
    cov.total_players::bigint,
    cov.active_players::bigint,
    cov.players_claimed::bigint,
    cov.players_with_api_key::bigint,
    cov.coverage_percentage::numeric,
    cov.guild_api_status::text
  FROM public.api_key_coverage cov
  JOIN public.guild_config gc ON gc.guild_code = cov.guild_code
  WHERE gc.cluster_code = p_cluster_code
    AND gc.enabled = true;
END;
$$;

ALTER FUNCTION public.get_cluster_api_key_coverage(p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_battle_data(season_num text DEFAULT NULL::text) RETURNS TABLE("Guild" text, "Season" text, "displayName" text, "userId" text, "damageDealt" bigint, "damageType" text, tier bigint, set bigint, "loopIndex" bigint, "encounterId" text, "Name" text, rarity text, "maxHp" bigint, "remainingHp" bigint, "startedOn" timestamp with time zone, "completedOn" timestamp with time zone, "heroDetails" text, "machineOfWarDetails" text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  user_cluster_code text;
  user_guild_code text;
BEGIN
  -- Get the user's cluster and guild from player_mapping
  SELECT
    pm.guild_code,
    gc.cluster_code
  INTO
    user_guild_code,
    user_cluster_code
  FROM player_mapping pm
  LEFT JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = auth.uid()
    AND pm.is_current = true
  LIMIT 1;

  -- If no valid mapping found, return empty
  IF user_cluster_code IS NULL THEN
    RETURN;
  END IF;

  -- Return battle data for the user's cluster, filtered by season if provided
  RETURN QUERY
  SELECT
    e."Guild",
    e."Season",
    e."displayName",
    e."userId",  -- Include userId in the SELECT
    e."damageDealt",
    e."damageType",
    e."tier",
    e."set"::bigint,
    e."loopIndex",
    e."encounterId"::text,
    e."Name",
    e."rarity",
    e."maxHp",
    e."remainingHp",
    e."startedOn",
    e."completedOn",
    e."heroDetails"::text,
    e."machineOfWarDetails"::text
  FROM "EOT_GR_data" e
  LEFT JOIN guild_config gc ON gc.guild_code = e."Guild"
  WHERE gc.cluster_code = user_cluster_code
    AND (season_num IS NULL OR e."Season" = season_num)
    AND e."damageDealt" > 0;
END;
$$;

ALTER FUNCTION public.get_cluster_battle_data(season_num text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_battle_data_for_cluster(p_cluster_code text, p_season_num text DEFAULT NULL::text) RETURNS TABLE("Guild" text, "Season" text, "displayName" text, "userId" text, "damageDealt" bigint, "damageType" text, tier bigint, set bigint, "loopIndex" bigint, "encounterId" text, "Name" text, rarity text, "maxHp" bigint, "remainingHp" bigint, "startedOn" timestamp with time zone, "completedOn" timestamp with time zone, "heroDetails" text, "machineOfWarDetails" text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  user_cluster_code TEXT;
  user_guild_code TEXT;
  user_role TEXT;
BEGIN
  -- Get the current user's cluster and role for permission check
  SELECT
    pm.guild_code,
    gc.cluster_code,
    pm.role
  INTO
    user_guild_code,
    user_cluster_code,
    user_role
  FROM player_mapping pm
  LEFT JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = auth.uid()
    AND pm.is_current = true
  LIMIT 1;

  -- Permission check: Only allow if user is officer/leader and cluster matches, or if user is leader
  IF NOT (
    (user_role IN ('officer', 'leader') AND user_cluster_code = p_cluster_code) OR
    (user_role = 'leader')
  ) THEN
    RETURN;
  END IF;

  -- Return battle data for the specified cluster
  RETURN QUERY
  SELECT
    e."Guild",
    e."Season",
    e."displayName",
    e."userId",  -- Include userId in the SELECT
    e."damageDealt",
    e."damageType",
    e."tier",
    e."set"::bigint,
    e."loopIndex",
    e."encounterId"::text,
    e."Name",
    e."rarity",
    e."maxHp",
    e."remainingHp",
    e."startedOn",
    e."completedOn",
    e."heroDetails"::text,
    e."machineOfWarDetails"::text
  FROM "EOT_GR_data" e
  LEFT JOIN guild_config gc ON gc.guild_code = e."Guild"
  WHERE gc.cluster_code = p_cluster_code
    AND (p_season_num IS NULL OR e."Season" = p_season_num)
    AND e."damageDealt" > 0;
END;
$$;

ALTER FUNCTION public.get_cluster_battle_data_for_cluster(p_cluster_code text, p_season_num text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_boss_averages(p_season text) RETURNS TABLE(boss_name text, encounter_type text, set integer, cluster_avg_damage numeric, cluster_hit_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    d."Name"::TEXT as boss_name,
    CASE
      WHEN d."encounterId" = 0 THEN 'Boss'::TEXT
      ELSE 'Prime'::TEXT
    END as encounter_type,
    d."set"::INTEGER,
    AVG(d."damageDealt")::NUMERIC as cluster_avg_damage,
    COUNT(*)::BIGINT as cluster_hit_count
  FROM "EOT_GR_data" d
  WHERE d."Season" = p_season
    AND d."damageType" = 'Battle'
    AND d."rarity" IN ('Legendary', 'Mythic')
    AND d."damageDealt" > 0
    AND d."Guild" NOT IN ('TEST', 'BA')  -- Exclude test and removed guilds
  GROUP BY d."Name", d."encounterId", d."set";
END;
$$;

ALTER FUNCTION public.get_cluster_boss_averages(p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_boss_averages(p_cluster_code text, p_season text) RETURNS TABLE(boss_name text, encounter_id integer, set_num integer, rarity text, avg_damage numeric, hit_count bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    "Name" as boss_name,
    "encounterId" as encounter_id,
    "set" as set_num,
    "rarity" as rarity,
    COALESCE(AVG("damageDealt"), 0)::numeric as avg_damage,
    COUNT(*)::bigint as hit_count
  FROM "EOT_GR_data"
  WHERE "cluster_code" = p_cluster_code
    AND "Season" = p_season
    AND "damageDealt" > 0
  GROUP BY "Name", "encounterId", "set", "rarity"
$$;

ALTER FUNCTION public.get_cluster_boss_averages(p_cluster_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_boss_avg_damage(p_cluster_code text, p_season text, p_boss_name text, p_encounter_id integer, p_set integer, p_rarity text) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(AVG("damageDealt"), 0)::numeric
  FROM "EOT_GR_data"
  WHERE "cluster_code" = p_cluster_code
    AND "Season" = p_season
    AND "Name" = p_boss_name
    AND "encounterId" = p_encounter_id
    AND "set" = p_set
    AND "rarity" = p_rarity
    AND "damageDealt" > 0
$$;

ALTER FUNCTION public.get_cluster_boss_avg_damage(p_cluster_code text, p_season text, p_boss_name text, p_encounter_id integer, p_set integer, p_rarity text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_boss_matrix(p_cluster_code text, p_season text) RETURNS TABLE(guild_code text, boss_name text, rarity text, set integer, encounter_id integer, loop_index integer, tokens integer, total_damage bigint, finisher_tokens integer, finisher_damage bigint, killed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_cluster_code IS NULL OR length(trim(p_cluster_code)) = 0 THEN
    RAISE EXCEPTION 'p_cluster_code is required'
      USING ERRCODE = '22023';
  END IF;
  IF p_season IS NULL OR length(trim(p_season)) = 0 THEN
    RAISE EXCEPTION 'p_season is required'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.player_mapping pm
      JOIN public.guild_config gc ON gc.guild_code = pm.guild_code
      WHERE pm.user_id = (SELECT auth.uid())
        AND pm.is_current = true
        AND gc.cluster_code = p_cluster_code
    ) THEN
      RAISE EXCEPTION 'Access denied: cluster membership required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH cluster_guilds AS (
    SELECT gc.guild_code
    FROM public.guild_config gc
    WHERE gc.cluster_code = p_cluster_code
      AND gc.enabled = true
  )
  SELECT
    d."Guild"::text                                                    AS guild_code,
    d."Name"::text                                                     AS boss_name,
    d.rarity::text                                                     AS rarity,
    d."set"::integer                                                   AS set,
    d."encounterId"::integer                                           AS encounter_id,
    d."loopIndex"::integer                                             AS loop_index,
    COUNT(*) FILTER (WHERE d."damageType" = 'Battle')::integer         AS tokens,
    COALESCE(
      SUM(d."damageDealt") FILTER (WHERE d."damageType" = 'Battle'), 0
    )::bigint                                                          AS total_damage,
    COUNT(*) FILTER (
      WHERE d."damageType" = 'Battle' AND d."remainingHp" = 0
    )::integer                                                         AS finisher_tokens,
    COALESCE(
      SUM(d."damageDealt") FILTER (
        WHERE d."damageType" = 'Battle' AND d."remainingHp" = 0
      ), 0
    )::bigint                                                          AS finisher_damage,
    bool_or(d."remainingHp" = 0)                                       AS killed
  FROM "EOT_GR_data" d
  WHERE d."Season" = p_season
    AND d."Guild" IN (SELECT cg.guild_code FROM cluster_guilds cg)
    AND d."encounterId" IN (0, 1, 2)
    AND d.rarity IN ('Legendary', 'Mythic')
    AND d."damageType" IN ('Battle', 'Bomb')
  GROUP BY
    d."Guild",
    d."Name",
    d.rarity,
    d."set",
    d."encounterId",
    d."loopIndex";
END;
$$;

ALTER FUNCTION public.get_cluster_boss_matrix(p_cluster_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_discord_webhooks(p_cluster_code character varying) RETURNS TABLE(webhook_url text, webhook_type character varying, channel_name character varying, enabled boolean, settings jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    cdc.webhook_url,
    cdc.webhook_type,
    cdc.channel_name,
    cdc.enabled,
    cdc.settings
  FROM cluster_discord_config cdc
  JOIN clusters c ON cdc.cluster_id = c.id
  WHERE c.cluster_code = p_cluster_code
  AND c.is_active = true
  AND cdc.enabled = true;
END;
$$;

ALTER FUNCTION public.get_cluster_discord_webhooks(p_cluster_code character varying) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_historical_rankings(p_seasons text[], p_cluster_code text DEFAULT NULL::text) RETURNS TABLE(season text, stable_key text, display_name text, guild text, percent_vs_cluster numeric, season_rank integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cluster_code TEXT;
  v_guild_code TEXT;
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  IF p_cluster_code IS NOT NULL THEN
    v_cluster_code := p_cluster_code;
  ELSE
    SELECT gc.cluster_code, pm.guild_code
    INTO v_cluster_code, v_guild_code
    FROM player_mapping pm
    JOIN guild_config gc ON gc.guild_code = pm.guild_code
    WHERE pm.user_id = v_user_id
      AND pm.is_current = true
    LIMIT 1;
  END IF;

  IF v_cluster_code IS NULL THEN
    v_cluster_code := v_guild_code;
  END IF;

  IF v_cluster_code IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    mv.season,
    mv.stable_key,
    mv.display_name,
    mv.guild,
    mv.percent_vs_cluster,
    mv.season_rank
  FROM mv_cluster_season_rankings mv
  WHERE mv.cluster_code = v_cluster_code
    AND mv.season = ANY(p_seasons)
  ORDER BY mv.season DESC, mv.season_rank;
END;
$$;

ALTER FUNCTION public.get_cluster_historical_rankings(p_seasons text[], p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_latest_season() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_guild_code   TEXT;
  v_cluster_code TEXT;
  v_latest_season TEXT;
BEGIN
  -- Resolve the caller's guild + cluster (same path as get_cluster_battle_data)
  SELECT pm.guild_code, gc.cluster_code
  INTO v_guild_code, v_cluster_code
  FROM player_mapping pm
  LEFT JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = auth.uid()
    AND pm.is_current = true
  LIMIT 1;

  IF v_cluster_code IS NOT NULL THEN
    -- Newest NUMERIC season across all guilds in the caller's cluster.
    -- Per-guild LATERAL max so each guild is one descending index walk; see the
    -- header for the two slower forms that were measured and rejected.
    SELECT max(per_guild.season_num)::text
    INTO v_latest_season
    FROM guild_config gc
    CROSS JOIN LATERAL (
      SELECT max(e.season_num) AS season_num
      FROM "EOT_GR_data" e
      WHERE e."Guild" = gc.guild_code
    ) AS per_guild
    WHERE gc.cluster_code = v_cluster_code;
  ELSIF v_guild_code IS NOT NULL THEN
    -- Independent guild (not in a cluster): newest season for that guild
    SELECT max(e.season_num)::text
    INTO v_latest_season
    FROM "EOT_GR_data" e
    WHERE e."Guild" = v_guild_code;
  END IF;

  -- NULL when unresolved (no mapping / no data); callers fall back to a literal.
  RETURN v_latest_season;
END;
$$;

ALTER FUNCTION public.get_cluster_latest_season() OWNER TO postgres;

CREATE FUNCTION public.get_cluster_overall_leaderboard(p_season text, p_cluster_code text DEFAULT NULL::text) RETURNS TABLE(stable_key text, display_name text, guild text, user_id text, total_damage bigint, battle_count integer, avg_damage bigint, bombs_used integer, bosses_killed integer, all_battle_count integer, all_bosses_killed integer, percent_vs_cluster numeric, current_rank integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cluster_code TEXT;
  v_guild_code TEXT;
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  IF p_cluster_code IS NOT NULL THEN
    v_cluster_code := p_cluster_code;
  ELSE
    SELECT gc.cluster_code, pm.guild_code
    INTO v_cluster_code, v_guild_code
    FROM player_mapping pm
    JOIN guild_config gc ON gc.guild_code = pm.guild_code
    WHERE pm.user_id = v_user_id
      AND pm.is_current = true
    LIMIT 1;
  END IF;

  IF v_cluster_code IS NULL AND v_guild_code IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH cluster_guilds AS (
    SELECT gc.guild_code
    FROM guild_config gc
    WHERE (v_cluster_code IS NOT NULL AND gc.cluster_code = v_cluster_code)
       OR (v_cluster_code IS NULL AND v_guild_code IS NOT NULL AND gc.guild_code = v_guild_code)
  ),
  -- Boss averages are sweep-free (this is correct - baseline should exclude sweeps)
  boss_averages AS (
    SELECT
      ab."Name" || '_' || ab.rarity || '_' || ab.set AS boss_key,
      AVG(ab."damageDealt") AS cluster_avg
    FROM "EOT_GR_data" ab
    WHERE ab."Season" = p_season
      AND ab."Guild" IN (SELECT cg.guild_code FROM cluster_guilds cg)
      AND ab."damageType" = 'Battle'
      AND ab.rarity IN ('Legendary', 'Mythic')
      AND ab."damageDealt" > 0
      AND NOT (ab."remainingHp" = 0 AND ab."maxHp" > 0 AND ab."damageDealt" < ab."maxHp")
    GROUP BY ab."Name", ab.rarity, ab.set
  ),
  -- Player boss stats for performance calculation (sweeps excluded from avg, included via qualifying exception)
  player_boss_stats AS (
    SELECT
      COALESCE(ab."userId", ab."Guild" || '::' || LOWER(TRIM(ab."displayName"))) AS stable_key,
      ab."displayName",
      ab."Guild",
      ab."userId",
      ab."Name" || '_' || ab.rarity || '_' || ab.set AS boss_key,
      SUM(ab."damageDealt") FILTER (WHERE NOT (ab."remainingHp" = 0 AND ab."maxHp" > 0 AND ab."damageDealt" < ab."maxHp")) AS non_sweep_damage,
      COUNT(*) FILTER (WHERE NOT (ab."remainingHp" = 0 AND ab."maxHp" > 0 AND ab."damageDealt" < ab."maxHp")) AS non_sweep_count,
      AVG(ab."damageDealt") FILTER (WHERE NOT (ab."remainingHp" = 0 AND ab."maxHp" > 0 AND ab."damageDealt" < ab."maxHp")) AS player_avg,
      array_agg(ab."damageDealt"::numeric) FILTER (WHERE ab."remainingHp" = 0 AND ab."maxHp" > 0 AND ab."damageDealt" < ab."maxHp") AS sweep_damages
    FROM "EOT_GR_data" ab
    WHERE ab."Season" = p_season
      AND ab."Guild" IN (SELECT cg.guild_code FROM cluster_guilds cg)
      AND ab."damageType" = 'Battle'
      AND ab.rarity IN ('Legendary', 'Mythic')
      AND ab."damageDealt" > 0
    GROUP BY
      COALESCE(ab."userId", ab."Guild" || '::' || LOWER(TRIM(ab."displayName"))),
      ab."displayName",
      ab."Guild",
      ab."userId",
      ab."Name",
      ab.rarity,
      ab.set
  ),
  -- Performance calculation (sweeps included via qualifying exception logic)
  player_weighted_performance AS (
    SELECT
      pbs.stable_key,
      pbs."displayName",
      pbs."Guild",
      pbs."userId",
      SUM(
        calc_boss_performance_pct(pbs.non_sweep_damage, pbs.non_sweep_count, pbs.sweep_damages, ba.cluster_avg::numeric, pbs.player_avg::numeric)
        * calc_effective_battle_count(pbs.non_sweep_count, pbs.sweep_damages, ba.cluster_avg::numeric, pbs.player_avg::numeric)
      ) / NULLIF(SUM(
        calc_effective_battle_count(pbs.non_sweep_count, pbs.sweep_damages, ba.cluster_avg::numeric, pbs.player_avg::numeric)
      ), 0) AS percent_vs_cluster,
      SUM(
        calc_effective_battle_count(pbs.non_sweep_count, pbs.sweep_damages, ba.cluster_avg::numeric, pbs.player_avg::numeric)
      )::INT AS total_battles
    FROM player_boss_stats pbs
    JOIN boss_averages ba ON ba.boss_key = pbs.boss_key
    GROUP BY pbs.stable_key, pbs."displayName", pbs."Guild", pbs."userId"
  ),
  -- FIX: total_damage now INCLUDES sweeps (removed sweep exclusion filter)
  player_totals AS (
    SELECT
      COALESCE(d."userId", d."Guild" || '::' || LOWER(TRIM(d."displayName"))) AS stable_key,
      SUM(d."damageDealt") AS total_damage,
      COUNT(*) FILTER (WHERE d."damageType" = 'Battle') AS battle_count,
      COUNT(*) FILTER (WHERE d."damageType" = 'Bomb') AS bombs_used,
      COUNT(*) FILTER (WHERE d."remainingHp" = 0) AS bosses_killed
    FROM "EOT_GR_data" d
    WHERE d."Season" = p_season
      AND d."Guild" IN (SELECT cg.guild_code FROM cluster_guilds cg)
      AND d.rarity IN ('Legendary', 'Mythic')
      AND d."damageDealt" > 0
      -- FIX: Removed sweep exclusion to include all damage in total
    GROUP BY COALESCE(d."userId", d."Guild" || '::' || LOWER(TRIM(d."displayName")))
  ),
  -- all_battle_count already includes sweeps (correct)
  player_all_counts AS (
    SELECT
      COALESCE(d."userId", d."Guild" || '::' || LOWER(TRIM(d."displayName"))) AS stable_key,
      COUNT(*) FILTER (WHERE d."damageType" = 'Battle') AS all_battle_count,
      COUNT(*) FILTER (WHERE d."remainingHp" = 0) AS all_bosses_killed
    FROM "EOT_GR_data" d
    WHERE d."Season" = p_season
      AND d."Guild" IN (SELECT cg.guild_code FROM cluster_guilds cg)
      AND d."damageDealt" > 0
    GROUP BY COALESCE(d."userId", d."Guild" || '::' || LOWER(TRIM(d."displayName")))
  ),
  ranked_players AS (
    SELECT
      pwp.stable_key,
      pwp."displayName" AS display_name,
      pwp."Guild" AS guild,
      pwp."userId" AS user_id,
      COALESCE(pt.total_damage, 0)::BIGINT AS total_damage,
      COALESCE(pt.battle_count, 0)::INT AS battle_count,
      CASE WHEN COALESCE(pt.battle_count, 0) > 0
           THEN (COALESCE(pt.total_damage, 0) / pt.battle_count)::BIGINT
           ELSE 0 END AS avg_damage,
      COALESCE(pt.bombs_used, 0)::INT AS bombs_used,
      COALESCE(pt.bosses_killed, 0)::INT AS bosses_killed,
      COALESCE(pac.all_battle_count, 0)::INT AS all_battle_count,
      COALESCE(pac.all_bosses_killed, 0)::INT AS all_bosses_killed,
      ROUND(pwp.percent_vs_cluster, 2) AS percent_vs_cluster,
      ROW_NUMBER() OVER (
        ORDER BY
          CASE WHEN pwp.total_battles > 0 THEN 0 ELSE 1 END,
          pwp.percent_vs_cluster DESC NULLS LAST,
          pwp."displayName"
      )::INT AS current_rank
    FROM player_weighted_performance pwp
    LEFT JOIN player_totals pt ON pt.stable_key = pwp.stable_key
    LEFT JOIN player_all_counts pac ON pac.stable_key = pwp.stable_key
  )
  SELECT * FROM ranked_players
  ORDER BY current_rank;
END;
$$;

ALTER FUNCTION public.get_cluster_overall_leaderboard(p_season text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_cluster_stats_filtered(season_num text DEFAULT NULL::text) RETURNS TABLE(season text, boss_name text, boss_id text, total_damage numeric, battle_count bigint, player_count bigint, avg_damage numeric, max_damage numeric, min_damage numeric, std_dev numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  user_cluster_code text;
  user_guild_code text;
  target_season text;
BEGIN
  -- Get user's cluster context from player_mapping
  SELECT
    pm.guild_code,
    gc.cluster_code
  INTO
    user_guild_code,
    user_cluster_code
  FROM player_mapping pm
  LEFT JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = auth.uid()
    AND pm.is_current = true
  LIMIT 1;

  -- If user has no guild, return empty
  IF user_guild_code IS NULL THEN
    RETURN;
  END IF;

  -- Determine the season to filter by
  target_season := COALESCE(season_num, (
    SELECT MAX(e."Season")::text
    FROM "EOT_GR_data" e
    LEFT JOIN guild_config gc2 ON gc2.guild_code = e."Guild"
    WHERE (user_cluster_code IS NOT NULL AND gc2.cluster_code = user_cluster_code)
       OR (user_cluster_code IS NULL AND e."Guild" = user_guild_code)
  ));

  -- Return stats based on user's cluster
  RETURN QUERY
  SELECT
    e."Season"::text as season,
    e."Name" as boss_name,
    e."encounterId"::text as boss_id,
    SUM(e."damageDealt")::numeric as total_damage,
    COUNT(*)::bigint as battle_count,
    COUNT(DISTINCT e."displayName")::bigint as player_count,
    AVG(e."damageDealt")::numeric as avg_damage,
    MAX(e."damageDealt")::numeric as max_damage,
    MIN(e."damageDealt")::numeric as min_damage,
    STDDEV(e."damageDealt")::numeric as std_dev
  FROM "EOT_GR_data" e
  LEFT JOIN guild_config gc ON gc.guild_code = e."Guild"
  WHERE
    e."Season"::text = target_season
    AND e."damageType" = 'Battle'
    AND e."damageDealt" > 0
    AND (
      -- If user has a cluster, show cluster-wide stats
      (user_cluster_code IS NOT NULL AND gc.cluster_code = user_cluster_code)
      OR
      -- If user is in an independent guild, only show their guild stats
      (user_cluster_code IS NULL AND e."Guild" = user_guild_code)
    )
  GROUP BY
    e."Season",
    e."Name",
    e."encounterId"
  ORDER BY
    e."encounterId";
END;
$$;

ALTER FUNCTION public.get_cluster_stats_filtered(season_num text) OWNER TO postgres;

CREATE FUNCTION public.get_command_center_cluster_guild_metadata_v1() RETURNS TABLE(guild_code text, display_name text, cluster_code text, enabled boolean, gr_ranking integer, gw_ranking integer, token_offender_threshold integer, token_abuser_threshold integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_guild text;
  v_cluster text;
  v_guild_role text;
  v_result_count integer;
  v_result_bytes integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT
    count(pm.id)::integer,
    max(pm.guild_code),
    max(pm.cluster_code),
    max(pm.role::text)
  INTO v_mapping_count, v_guild, v_cluster, v_guild_role
  FROM public.player_mapping AS pm
  WHERE pm.user_id = auth.uid()
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;

  IF v_mapping_count <> 1
    OR lower(coalesce(v_guild_role, '')) NOT IN ('officer', 'leader')
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT
    count(*)::integer,
    octet_length(
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'guild_code', gc.guild_code,
            'display_name', gc.display_name,
            'cluster_code', gc.cluster_code::text,
            'enabled', gc.enabled,
            'gr_ranking', gc."GR_Ranking"::integer,
            'gw_ranking', gc."GW_Ranking"::integer,
            'token_offender_threshold', gc.token_offender_threshold,
            'token_abuser_threshold', gc.token_abuser_threshold
          )
          ORDER BY gc.guild_code
        )::text,
        '[]'
      )
    )
  INTO v_result_count, v_result_bytes
  FROM public.guild_config AS gc
  WHERE gc.enabled IS TRUE
    AND (
      (v_cluster IS NOT NULL AND gc.cluster_code = v_cluster)
      OR (v_cluster IS NULL AND gc.guild_code = v_guild)
    );

  IF v_result_count > 50 OR v_result_bytes > 65536 THEN
    RAISE EXCEPTION 'command-center cluster guild metadata exceeds its response bound'
      USING ERRCODE = '54000';
  END IF;

  RETURN QUERY
  SELECT
    gc.guild_code,
    gc.display_name,
    gc.cluster_code::text,
    gc.enabled,
    gc."GR_Ranking"::integer,
    gc."GW_Ranking"::integer,
    gc.token_offender_threshold,
    gc.token_abuser_threshold
  FROM public.guild_config AS gc
  WHERE gc.enabled IS TRUE
    AND (
      (v_cluster IS NOT NULL AND gc.cluster_code = v_cluster)
      OR (v_cluster IS NULL AND gc.guild_code = v_guild)
  )
  ORDER BY gc.guild_code
  LIMIT 50;
END;
$$;

ALTER FUNCTION public.get_command_center_cluster_guild_metadata_v1() OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_current_boss_status_v1(p_guild_code text, p_season text) RETURNS TABLE(boss_name text, rarity text, set integer, encounter_id integer, max_hp numeric, remaining_hp numeric, loop_index integer, completed_on timestamp with time zone, lifecycle_state text, warded boolean, alive_primes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT count(pm.id)::integer
    INTO v_mapping_count
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.guild_code = p_guild_code
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE;
    IF v_mapping_count <> 1 THEN
      RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH guild_rows AS MATERIALIZED (
    SELECT
      e."Name" AS row_name,
      e.rarity,
      e.set AS set_num,
      COALESCE(e."encounterId", 0)::integer AS encounter_id,
      e."maxHp" AS raw_max_hp,
      e."remainingHp" AS raw_remaining_hp,
      COALESCE(e."loopIndex", 0)::integer AS loop_zero,
      COALESCE(e."completedOn", e.timestamp, e."startedOn") AS activity_at
    FROM public."EOT_GR_data" AS e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" IN ('Battle', 'Bomb')
      AND e."Name" IS NOT NULL
  ),
  stage_anchor AS MATERIALIZED (
    SELECT
      rows.rarity AS anchor_rarity,
      rows.set_num AS anchor_set,
      rows.loop_zero AS anchor_loop
    FROM guild_rows AS rows
    ORDER BY rows.activity_at DESC NULLS LAST
    LIMIT 1
  ),
  scoped AS MATERIALIZED (
    SELECT
      rows.row_name,
      rows.rarity,
      rows.set_num,
      rows.encounter_id,
      rows.raw_max_hp,
      rows.raw_remaining_hp,
      rows.loop_zero,
      rows.activity_at
    FROM guild_rows AS rows
    LEFT JOIN stage_anchor AS anchor
      ON TRUE
    WHERE rows.encounter_id = 0
      OR (
        anchor.anchor_set IS NOT NULL
        AND rows.rarity IS NOT DISTINCT FROM anchor.anchor_rarity
        AND rows.set_num IS NOT DISTINCT FROM anchor.anchor_set
        AND rows.loop_zero = anchor.anchor_loop
      )
  ),
  latest AS MATERIALIZED (
    SELECT
      scoped.row_name AS boss_name,
      scoped.rarity,
      scoped.set_num,
      scoped.encounter_id,
      NULLIF(scoped.raw_max_hp, 0)::numeric AS max_hp,
      NULLIF(scoped.raw_remaining_hp, 0)::numeric AS remaining_hp,
      NULLIF(scoped.loop_zero, 0)::integer AS loop_index,
      scoped.activity_at AS completed_on,
      scoped.rarity AS stage_rarity,
      scoped.set_num AS stage_set,
      scoped.loop_zero AS stage_loop,
      bool_or(
        scoped.raw_remaining_hp IS NOT NULL
        AND scoped.raw_remaining_hp <= 0
      ) OVER (
        PARTITION BY
          scoped.encounter_id,
          scoped.rarity,
          scoped.set_num,
          scoped.loop_zero
      ) AS stage_kill_seen,
      row_number() OVER (
        PARTITION BY scoped.encounter_id
        ORDER BY scoped.activity_at DESC NULLS LAST
      ) AS row_number
    FROM scoped
  ),
  current_rows AS MATERIALIZED (
    SELECT
      latest.boss_name,
      latest.rarity,
      latest.set_num,
      latest.encounter_id,
      latest.max_hp,
      latest.remaining_hp,
      latest.loop_index,
      latest.completed_on,
      (
        latest.stage_kill_seen
        OR (
          latest.max_hp > 0
          AND EXISTS (
            SELECT 1
            FROM guild_rows AS newer
            WHERE (
              newer.rarity,
              newer.set_num,
              newer.loop_zero
            ) IS DISTINCT FROM (
              latest.stage_rarity,
              latest.stage_set,
              latest.stage_loop
            )
              AND newer.activity_at > latest.completed_on
          )
        )
      ) AS is_defeated
    FROM latest
    WHERE latest.row_number = 1
  ),
  decorated AS MATERIALIZED (
    SELECT
      current_rows.boss_name,
      current_rows.rarity,
      current_rows.set_num,
      current_rows.encounter_id,
      current_rows.max_hp,
      current_rows.remaining_hp,
      current_rows.loop_index,
      current_rows.completed_on,
      current_rows.is_defeated,
      (
        current_rows.max_hp > 0
        AND NOT current_rows.is_defeated
      ) AS is_active
    FROM current_rows
  ),
  prime_counts AS MATERIALIZED (
    SELECT count(*)::integer AS alive_primes
    FROM decorated
    WHERE decorated.encounter_id IN (1, 2)
      AND decorated.is_active
  )
  SELECT
    decorated.boss_name,
    decorated.rarity,
    decorated.set_num,
    decorated.encounter_id,
    decorated.max_hp,
    decorated.remaining_hp,
    decorated.loop_index,
    decorated.completed_on,
    CASE
      WHEN decorated.is_defeated THEN 'defeated'
      WHEN decorated.encounter_id = 0
        AND prime_counts.alive_primes > 0
        AND decorated.is_active
      THEN 'warded'
      WHEN decorated.is_active THEN 'active'
      ELSE 'upcoming'
    END,
    (
      decorated.encounter_id = 0
      AND prime_counts.alive_primes > 0
      AND NOT decorated.is_defeated
    ),
    prime_counts.alive_primes
  FROM decorated
  CROSS JOIN prime_counts
  ORDER BY decorated.encounter_id
  LIMIT 3;
END;
$$;

ALTER FUNCTION public.get_command_center_current_boss_status_v1(p_guild_code text, p_season text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_guild_members_v1() RETURNS TABLE(player_mapping_id integer, player_id text, display_name text, guild_code text, role text, is_current boolean, is_active boolean, last_sync_at timestamp with time zone, avatar_unit_id text, player_level integer, primary_boss text, secondary_boss text, assignment_updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_guild text;
  v_guild_role text;
  v_result_count integer;
  v_result_bytes integer;
  v_result jsonb;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT
    count(pm.id)::integer,
    max(pm.guild_code),
    max(pm.role::text)
  INTO v_mapping_count, v_guild, v_guild_role
  FROM public.player_mapping AS pm
  WHERE pm.user_id = auth.uid()
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;

  IF v_mapping_count <> 1
    OR lower(coalesce(v_guild_role, '')) NOT IN ('officer', 'leader')
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::integer
  INTO v_result_count
  FROM public.player_mapping AS pm
  WHERE pm.guild_code = v_guild
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;

  IF v_result_count > 255 THEN
    RAISE EXCEPTION 'command-center guild members exceeds its response bound'
      USING ERRCODE = '54000';
  END IF;

  WITH latest_assignments AS MATERIALIZED (
    SELECT DISTINCT ON (usa.guild_code, usa.player_id)
      usa.guild_code,
      usa.player_id,
      usa.primary_boss,
      usa.secondary_boss,
      usa.updated_at
    FROM public.upcoming_season_assignments AS usa
    WHERE usa.guild_code = v_guild
    ORDER BY
      usa.guild_code,
      usa.player_id,
      usa.season_number DESC
  )
  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'player_mapping_id', pm.id,
        'player_id', pm.player_id,
        'display_name', pm.display_name,
        'guild_code', pm.guild_code,
        'role', pm.role::text,
        'is_current', pm.is_current,
        'is_active', pm.is_active,
        'last_sync_at', pm.last_sync_at::timestamptz,
        'avatar_unit_id', pm.avatar_unit_id::text,
        'player_level', pm.player_level,
        'primary_boss', latest.primary_boss,
        'secondary_boss', latest.secondary_boss,
        'assignment_updated_at', latest.updated_at
      )
      ORDER BY pm.id
    ),
    '[]'::jsonb
  )
  INTO v_result
  FROM public.player_mapping AS pm
  LEFT JOIN latest_assignments AS latest
    ON latest.guild_code = pm.guild_code
   AND latest.player_id = pm.player_id
  WHERE pm.guild_code = v_guild
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;

  v_result_bytes := octet_length(v_result::text);
  IF v_result_bytes > 262144 THEN
    RAISE EXCEPTION 'command-center guild members exceeds its response bound'
      USING ERRCODE = '54000';
  END IF;

  RETURN QUERY
  SELECT
    (member.value ->> 'player_mapping_id')::integer,
    member.value ->> 'player_id',
    member.value ->> 'display_name',
    member.value ->> 'guild_code',
    member.value ->> 'role',
    (member.value ->> 'is_current')::boolean,
    (member.value ->> 'is_active')::boolean,
    (member.value ->> 'last_sync_at')::timestamptz,
    member.value ->> 'avatar_unit_id',
    (member.value ->> 'player_level')::integer,
    member.value ->> 'primary_boss',
    member.value ->> 'secondary_boss',
    (member.value ->> 'assignment_updated_at')::timestamptz
  FROM jsonb_array_elements(v_result) AS member
  ORDER BY 1;
END;
$$;

ALTER FUNCTION public.get_command_center_guild_members_v1() OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_guild_season_summary_v1(p_guild_code text, p_season text) RETURNS TABLE(total_damage numeric, total_battles integer, max_hit numeric, boss_kills integer, recent_activity integer, avg_damage_per_hour numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT count(pm.id)::integer
    INTO v_mapping_count
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.guild_code = p_guild_code
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE;
    IF v_mapping_count <> 1 THEN
      RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH base AS MATERIALIZED (
    SELECT
      COALESCE(sum(e."damageDealt"), 0)::numeric AS total_damage,
      count(*) FILTER (
        WHERE e."damageType" = 'Battle'
      )::integer AS total_battles,
      max(NULLIF(e."damageDealt", 0))::numeric AS max_hit,
      count(*) FILTER (
        WHERE e."damageType" = 'Battle'
          AND e."remainingHp" = 0
          AND e."maxHp" > 0
          AND e."damageDealt" >= e."maxHp"
      )::integer AS boss_kills
    FROM public."EOT_GR_data" AS e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" IN ('Battle', 'Bomb')
  ),
  recent AS MATERIALIZED (
    SELECT count(*)::integer AS recent_activity
    FROM public."EOT_GR_data" AS e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" IN ('Battle', 'Bomb')
      AND COALESCE(e."completedOn", e.timestamp, e."startedOn")
        >= statement_timestamp() - interval '1 day'
  ),
  duration AS MATERIALIZED (
    SELECT
      extract(
        epoch FROM (
          max(COALESCE(e."completedOn", e.timestamp, e."startedOn"))
          - min(COALESCE(e."completedOn", e.timestamp, e."startedOn"))
        )
      ) / 3600.0 AS hours_span
    FROM public."EOT_GR_data" AS e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" IN ('Battle', 'Bomb')
      AND COALESCE(e."completedOn", e.timestamp, e."startedOn") IS NOT NULL
  )
  SELECT
    base.total_damage,
    base.total_battles,
    base.max_hit,
    base.boss_kills,
    recent.recent_activity,
    CASE
      WHEN duration.hours_span > 0
        THEN base.total_damage / duration.hours_span
      ELSE NULL::numeric
    END
  FROM base
  CROSS JOIN recent
  CROSS JOIN duration;
END;
$$;

ALTER FUNCTION public.get_command_center_guild_season_summary_v1(p_guild_code text, p_season text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_member_season_forecast_v1(p_guild_code text, p_season_number integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_result jsonb;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT count(pm.id)::integer
  INTO v_mapping_count
  FROM public.player_mapping AS pm
  WHERE pm.user_id = auth.uid()
    AND pm.guild_code = p_guild_code
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  WITH season_window AS MATERIALIZED (
    SELECT
      to_timestamp(
        1646128800
        + 86400
        + ((p_season_number + 10 - 1)::bigint * 1209600)
      ) AS starts_at
  ),
  timing AS MATERIALIZED (
    SELECT
      season_window.starts_at,
      season_window.starts_at + interval '1123200 seconds' AS ends_at,
      CASE
        WHEN statement_timestamp() < season_window.starts_at THEN 0
        ELSE GREATEST(
          0,
          extract(
            epoch FROM
              season_window.starts_at
              + interval '1123200 seconds'
              - statement_timestamp()
          )::bigint
        )
      END AS seconds_remaining
    FROM season_window
  ),
  players AS MATERIALIZED (
    SELECT
      pm.id,
      pm.user_id,
      pm.player_id,
      COALESCE(pm.last_sync_tokens, 0)::integer AS tokens_now,
      GREATEST(COALESCE(pm.next_token_seconds, 0), 0)::integer
        AS next_token_seconds,
      COALESCE(pm.last_sync_bombs, 0)::integer AS bombs_now,
      GREATEST(COALESCE(pm.next_bomb_seconds, 0), 0)::integer
        AS next_bomb_seconds,
      COALESCE(burn.time_over_cap_seconds, 0)::bigint
        AS time_over_cap_seconds
    FROM public.player_mapping AS pm
    LEFT JOIN public.token_burn_state AS burn
      ON burn.guild_code = pm.guild_code
     AND burn.player_id = pm.player_id
     AND burn.season = p_season_number::text
    WHERE pm.guild_code = p_guild_code
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
      AND pm.player_id IS NOT NULL
  ),
  computed AS MATERIALIZED (
    SELECT
      players.id,
      players.user_id,
      players.tokens_now,
      players.next_token_seconds,
      GREATEST(
        0,
        LEAST(
          3 - players.tokens_now,
          CASE
            WHEN timing.seconds_remaining > players.next_token_seconds
            THEN floor(
              (
                timing.seconds_remaining
                - players.next_token_seconds
              )::numeric / 43200
            )::integer + 1
            ELSE 0
          END
        )
      )::integer AS tokens_will_regen,
      floor(timing.seconds_remaining::numeric / 43200)::integer
        AS theoretical_regen,
      players.time_over_cap_seconds,
      players.bombs_now,
      CASE
        WHEN players.bombs_now < 1
          AND timing.seconds_remaining > players.next_bomb_seconds
        THEN 1 - players.bombs_now
        ELSE 0
      END::integer AS bombs_will_regen
    FROM players
    CROSS JOIN timing
  ),
  full_player AS MATERIALIZED (
    SELECT
      computed.id,
      computed.user_id,
      computed.tokens_now,
      computed.next_token_seconds,
      computed.tokens_will_regen,
      LEAST(
        3,
        computed.tokens_now + computed.tokens_will_regen
      )::integer AS tokens_at_season_end,
      (
        computed.tokens_now + computed.tokens_will_regen >= 3
        AND computed.time_over_cap_seconds > 0
      ) AS will_cap,
      GREATEST(
        0,
        computed.theoretical_regen - computed.tokens_will_regen
      )::integer AS estimated_cap_waste,
      computed.bombs_now,
      computed.bombs_will_regen
    FROM computed
  ),
  envelope AS MATERIALIZED (
    SELECT
      COALESCE(sum(full_player.tokens_now), 0)::integer AS tokens_available,
      COALESCE(sum(full_player.tokens_will_regen), 0)::integer
        AS tokens_regen,
      COALESCE(
        sum(full_player.tokens_now + full_player.tokens_will_regen),
        0
      )::integer AS tokens_capacity,
      COALESCE(
        sum(CASE WHEN full_player.will_cap THEN 1 ELSE 0 END),
        0
      )::integer AS cap_bound_players,
      COALESCE(sum(full_player.estimated_cap_waste), 0)::integer
        AS estimated_cap_waste,
      COALESCE(sum(full_player.bombs_now), 0)::integer AS bombs_available,
      COALESCE(sum(full_player.bombs_will_regen), 0)::integer AS bombs_regen,
      COALESCE(
        sum(full_player.bombs_now + full_player.bombs_will_regen),
        0
      )::integer AS bombs_capacity
    FROM full_player
  ),
  lap_state AS MATERIALIZED (
    SELECT COALESCE(max(e."loopIndex"), 0)::integer AS current_lap
    FROM public."EOT_GR_data" AS e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season_number::text
      AND e."damageType" = 'Battle'
      AND e."loopIndex" IS NOT NULL
  ),
  current_lap AS MATERIALIZED (
    SELECT
      lap_state.current_lap,
      count(e."loopIndex")::integer AS tokens_into_current_lap
    FROM lap_state
    LEFT JOIN public."EOT_GR_data" AS e
      ON e."Guild" = p_guild_code
     AND e."Season" = p_season_number::text
     AND e."damageType" = 'Battle'
     AND e."loopIndex" = lap_state.current_lap
    GROUP BY lap_state.current_lap
  ),
  lap_costs AS MATERIALIZED (
    SELECT count(*)::integer AS tokens_used
    FROM current_lap
    JOIN public."EOT_GR_data" AS e
      ON e."Guild" = p_guild_code
     AND e."Season" = p_season_number::text
     AND e."damageType" = 'Battle'
     AND e."loopIndex" IS NOT NULL
     AND e."loopIndex" < current_lap.current_lap
    GROUP BY e."loopIndex"
    ORDER BY e."loopIndex" DESC
    LIMIT 2
  ),
  lap_stats AS MATERIALIZED (
    SELECT
      avg(lap_costs.tokens_used)::numeric AS projected_lap_cost,
      count(*)::integer AS sample_size
    FROM lap_costs
  ),
  player_output AS MATERIALIZED (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'player_mapping_id', full_player.id,
          'tokens_now', full_player.tokens_now,
          'next_token_seconds', full_player.next_token_seconds,
          'tokens_will_regen', full_player.tokens_will_regen,
          'tokens_at_season_end', full_player.tokens_at_season_end,
          'will_cap', full_player.will_cap,
          'estimated_cap_waste', full_player.estimated_cap_waste
        )
        ORDER BY full_player.id
      ) FILTER (
        WHERE full_player.user_id = auth.uid()
      ),
      '[]'::jsonb
    ) AS rows
    FROM full_player
  )
  SELECT jsonb_build_object(
    'season', jsonb_build_object(
      'number', p_season_number,
      'starts_at', timing.starts_at,
      'ends_at', timing.ends_at,
      'seconds_remaining', timing.seconds_remaining
    ),
    'tokens', jsonb_build_object(
      'available_now', envelope.tokens_available,
      'yet_to_regen', envelope.tokens_regen,
      'capacity', envelope.tokens_capacity,
      'cap_bound_players', envelope.cap_bound_players,
      'estimated_cap_waste', envelope.estimated_cap_waste
    ),
    'bombs', jsonb_build_object(
      'available_now', envelope.bombs_available,
      'yet_to_regen', envelope.bombs_regen,
      'capacity', envelope.bombs_capacity
    ),
    'lap_projection', CASE
      WHEN lap_stats.sample_size = 0
        OR lap_stats.projected_lap_cost IS NULL
      THEN NULL::jsonb
      ELSE jsonb_build_object(
        'current_lap', current_lap.current_lap,
        'tokens_into_current_lap', current_lap.tokens_into_current_lap,
        'projected_lap_cost', round(lap_stats.projected_lap_cost, 2),
        'basis', 'last_n_laps',
        'n', lap_stats.sample_size,
        'projected_finish_lap', CASE
          WHEN envelope.tokens_capacity
            >= GREATEST(
              lap_stats.projected_lap_cost
              - current_lap.tokens_into_current_lap,
              0
            )
          THEN current_lap.current_lap
          ELSE GREATEST(0, current_lap.current_lap - 1)
        END,
        'projected_finish_pct', round(
          LEAST(
            CASE
              WHEN envelope.tokens_capacity
                >= GREATEST(
                  lap_stats.projected_lap_cost
                  - current_lap.tokens_into_current_lap,
                  0
                )
              THEN (
                envelope.tokens_capacity
                - GREATEST(
                  lap_stats.projected_lap_cost
                  - current_lap.tokens_into_current_lap,
                  0
                )
              ) / NULLIF(lap_stats.projected_lap_cost, 0)
              ELSE (
                current_lap.tokens_into_current_lap
                + envelope.tokens_capacity
              ) / NULLIF(lap_stats.projected_lap_cost, 0)
            END,
            0.999
          ),
          4
        ),
        'confidence', CASE
          WHEN lap_stats.sample_size <= 1 THEN 'low'
          WHEN lap_stats.sample_size <= 3 THEN 'medium'
          ELSE 'high'
        END
      )
    END,
    'per_player', player_output.rows
  )
  INTO v_result
  FROM timing
  CROSS JOIN envelope
  CROSS JOIN current_lap
  CROSS JOIN lap_stats
  CROSS JOIN player_output;

  RETURN v_result;
END;
$$;

ALTER FUNCTION public.get_command_center_member_season_forecast_v1(p_guild_code text, p_season_number integer) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_member_token_state_v1(p_season text) RETURNS TABLE(player_mapping_id integer, tokens_available integer, is_capped boolean, time_to_next_token interval, data_source text, token_next_in_seconds integer, last_sync_at timestamp with time zone, tokens_used integer, max_possible integer, burned_tokens integer, time_over_cap_seconds integer, last_battle_time timestamp with time zone, bombs_available integer, bomb_next_in_seconds integer, post_snapshot_spends integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT count(pm.id)::integer
  INTO v_mapping_count
  FROM public.player_mapping AS pm
  WHERE pm.user_id = auth.uid()
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH caller AS MATERIALIZED (
    SELECT
      pm.id,
      pm.player_id,
      pm.guild_code,
      pm.last_sync_tokens,
      pm.last_sync_bombs,
      pm.last_sync_at,
      pm.next_bomb_seconds
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
  ),
  recent AS MATERIALIZED (
    SELECT
      count(DISTINCT e.timestamp) FILTER (
        WHERE e."damageType" = 'Battle'
          AND caller.last_sync_at IS NOT NULL
          AND e.timestamp > caller.last_sync_at
      )::integer AS post_snapshot_spends,
      max(e.timestamp) FILTER (
        WHERE e."damageType" = 'Battle'
      ) AS last_battle_time,
      max(e.timestamp) FILTER (
        WHERE e."damageType" = 'Bomb'
      ) AS last_bomb_time
    FROM caller
    LEFT JOIN public."EOT_GR_data" AS e
      ON e."Guild" = caller.guild_code
     AND e."Season" = p_season
     AND e."userId" = caller.player_id
     AND e."damageType" IN ('Battle', 'Bomb')
  ),
  usage AS MATERIALIZED (
    SELECT
      token_usage.player_mapping_id,
      token_usage.tokens_available,
      token_usage.token_next_in_seconds,
      token_usage.tokens_used,
      token_usage.max_possible,
      token_usage.burned_tokens,
      token_usage.time_over_cap_seconds,
      token_usage.bombs_available
    FROM public.get_command_center_self_token_usage_v1(p_season) AS token_usage
  )
  SELECT
    caller.id,
    usage.tokens_available,
    usage.tokens_available >= 3,
    CASE
      WHEN usage.token_next_in_seconds IS NULL THEN NULL::interval
      ELSE make_interval(secs => usage.token_next_in_seconds)
    END,
    CASE
      WHEN caller.last_sync_at IS NOT NULL
        AND caller.last_sync_tokens IS NOT NULL
      THEN 'live'::text
      ELSE 'calculated'::text
    END,
    usage.token_next_in_seconds,
    caller.last_sync_at::timestamptz,
    usage.tokens_used,
    usage.max_possible,
    usage.burned_tokens,
    usage.time_over_cap_seconds,
    recent.last_battle_time,
    usage.bombs_available,
    CASE
      WHEN usage.bombs_available >= 1 THEN NULL::integer
      WHEN recent.last_bomb_time IS NOT NULL
        AND recent.last_bomb_time
          > statement_timestamp() - interval '18 hours'
      THEN GREATEST(
        0,
        floor(
          64800
          - extract(
            epoch FROM statement_timestamp() - recent.last_bomb_time
          )
        )
      )::integer
      WHEN caller.last_sync_at IS NOT NULL
        AND caller.last_sync_bombs IS NOT NULL
        AND COALESCE(caller.next_bomb_seconds, 0) > 0
      THEN GREATEST(
        0,
        caller.next_bomb_seconds
        - floor(
          extract(epoch FROM statement_timestamp() - caller.last_sync_at)
        )::integer
      )
      ELSE NULL::integer
    END,
    CASE
      WHEN caller.last_sync_at IS NULL THEN NULL::integer
      ELSE COALESCE(recent.post_snapshot_spends, 0)
    END
  FROM caller
  JOIN usage
    ON usage.player_mapping_id = caller.id
  CROSS JOIN recent;
END;
$$;

ALTER FUNCTION public.get_command_center_member_token_state_v1(p_season text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_officer_boss_performance_v1(p_guild_code text, p_season text, p_player_mapping_ids integer[], p_boss_name text, p_rarity text, p_sets integer[]) RETURNS TABLE(player_mapping_id integer, display_name text, boss_name text, encounter_id integer, player_avg numeric, guild_avg numeric, cluster_avg numeric, battle_count integer, biggest_hit bigint, weighted_contribution numeric, vs_cluster_pct numeric, vs_guild_pct numeric, set_num integer, tier integer, rarity text, boss_preference text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_requested_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  v_requested_count := cardinality(p_player_mapping_ids);
  IF v_requested_count < 1
    OR v_requested_count > 32
    OR v_requested_count <> (
      SELECT count(DISTINCT requested_mapping_id)::integer
      FROM unnest(p_player_mapping_ids) AS requested_mapping_id
    )
    OR (
      p_sets IS NOT NULL
      AND (
        cardinality(p_sets) > 5
        OR cardinality(p_sets) <> (
          SELECT count(DISTINCT requested_set)::integer
          FROM unnest(p_sets) AS requested_set
        )
      )
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT count(pm.id)::integer
    INTO v_mapping_count
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.guild_code = p_guild_code
      AND lower(pm.role::text) IN ('officer', 'leader')
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE;
    IF v_mapping_count <> 1 THEN
      RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT count(pm.id)::integer
  INTO v_mapping_count
  FROM public.player_mapping AS pm
  WHERE pm.id = ANY(p_player_mapping_ids)
    AND pm.guild_code = p_guild_code
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> v_requested_count THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH selected AS MATERIALIZED (
    SELECT
      pm.id,
      pm.player_id,
      pm.display_name,
      pm.boss_preferences
    FROM public.player_mapping AS pm
    WHERE pm.id = ANY(p_player_mapping_ids)
      AND pm.guild_code = p_guild_code
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
  ),
  target_cluster AS MATERIALIZED (
    SELECT gc.cluster_code
    FROM public.guild_config AS gc
    WHERE gc.guild_code = p_guild_code
  ),
  player_boss_stats AS MATERIALIZED (
    SELECT
      selected.id,
      selected.display_name,
      selected.boss_preferences,
      e."Name" AS boss_name,
      COALESCE(e."encounterId", 0)::integer AS encounter_id,
      e.tier::integer AS tier,
      e.set::integer AS set_num,
      e.rarity AS rarity,
      sum(e."damageDealt") FILTER (
        WHERE NOT (
          e."remainingHp" = 0
          AND e."maxHp" > 0
          AND e."damageDealt" < e."maxHp"
        )
      )::numeric AS non_sweep_damage,
      count(*) FILTER (
        WHERE NOT (
          e."remainingHp" = 0
          AND e."maxHp" > 0
          AND e."damageDealt" < e."maxHp"
        )
      )::integer AS non_sweep_count,
      array_agg(e."damageDealt"::numeric) FILTER (
        WHERE e."remainingHp" = 0
          AND e."maxHp" > 0
          AND e."damageDealt" < e."maxHp"
      ) AS sweep_damages,
      max(e."damageDealt")::bigint AS biggest_hit,
      sum(e."damageDealt")::numeric AS total_damage
    FROM selected
    JOIN public."EOT_GR_data" AS e
      ON e."Guild" = p_guild_code
     AND e."userId" = selected.player_id
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND (p_boss_name IS NULL OR e."Name" = p_boss_name)
      AND (p_rarity IS NULL OR e.rarity = p_rarity)
      AND (p_sets IS NULL OR e.set = ANY(p_sets))
    GROUP BY
      selected.id,
      selected.display_name,
      selected.boss_preferences,
      e."Name",
      e."encounterId",
      e.tier,
      e.set,
      e.rarity
  ),
  guild_average AS MATERIALIZED (
    SELECT
      e."Name" AS boss_name,
      COALESCE(e."encounterId", 0)::integer AS encounter_id,
      e.rarity,
      avg(e."damageDealt")::numeric AS average_damage
    FROM public."EOT_GR_data" AS e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (
        e."remainingHp" = 0
        AND e."maxHp" > 0
        AND e."damageDealt" < e."maxHp"
      )
    GROUP BY e."Name", e."encounterId", e.rarity
  ),
  cluster_average AS MATERIALIZED (
    SELECT
      e."Name" AS boss_name,
      COALESCE(e."encounterId", 0)::integer AS encounter_id,
      e.rarity,
      avg(e."damageDealt")::numeric AS average_damage
    FROM target_cluster
    JOIN public.guild_config AS gc
      ON gc.cluster_code = target_cluster.cluster_code
    JOIN public."EOT_GR_data" AS e
      ON e."Guild" = gc.guild_code
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (
        e."remainingHp" = 0
        AND e."maxHp" > 0
        AND e."damageDealt" < e."maxHp"
      )
    GROUP BY e."Name", e."encounterId", e.rarity
  ),
  guild_total AS MATERIALIZED (
    SELECT COALESCE(sum(e."damageDealt"), 0)::numeric AS total_damage
    FROM public."EOT_GR_data" AS e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
  ),
  evaluated AS (
    SELECT
      stats.id,
      stats.display_name,
      stats.boss_preferences,
      stats.boss_name,
      stats.encounter_id,
      stats.tier,
      stats.set_num,
      stats.rarity,
      stats.non_sweep_damage,
      stats.non_sweep_count,
      stats.sweep_damages,
      stats.biggest_hit,
      stats.total_damage,
      guild_average.average_damage AS guild_average,
      cluster_average.average_damage AS cluster_average,
      (
        COALESCE(stats.non_sweep_count, 0)
        + COALESCE(
          public.qualifying_sweep_count(
            stats.sweep_damages,
            GREATEST(
              stats.non_sweep_damage / NULLIF(stats.non_sweep_count, 0),
              guild_average.average_damage
            )
          ),
          0
        )
      )::integer AS qualifying_count,
      (
        COALESCE(stats.non_sweep_damage, 0)
        + COALESCE(
          public.qualifying_sweep_sum(
            stats.sweep_damages,
            GREATEST(
              stats.non_sweep_damage / NULLIF(stats.non_sweep_count, 0),
              guild_average.average_damage
            )
          ),
          0
        )
      )::numeric AS qualifying_guild_damage,
      (
        COALESCE(stats.non_sweep_damage, 0)
        + COALESCE(
          public.qualifying_sweep_sum(
            stats.sweep_damages,
            GREATEST(
              stats.non_sweep_damage / NULLIF(stats.non_sweep_count, 0),
              cluster_average.average_damage
            )
          ),
          0
        )
      )::numeric AS qualifying_cluster_damage,
      (
        COALESCE(stats.non_sweep_count, 0)
        + COALESCE(
          public.qualifying_sweep_count(
            stats.sweep_damages,
            GREATEST(
              stats.non_sweep_damage / NULLIF(stats.non_sweep_count, 0),
              cluster_average.average_damage
            )
          ),
          0
        )
      )::integer AS qualifying_cluster_count
    FROM player_boss_stats AS stats
    LEFT JOIN guild_average
      ON guild_average.boss_name = stats.boss_name
     AND guild_average.encounter_id = stats.encounter_id
     AND guild_average.rarity = stats.rarity
    LEFT JOIN cluster_average
      ON cluster_average.boss_name = stats.boss_name
     AND cluster_average.encounter_id = stats.encounter_id
     AND cluster_average.rarity = stats.rarity
  )
  SELECT
    evaluated.id,
    evaluated.display_name,
    evaluated.boss_name,
    evaluated.encounter_id,
    evaluated.qualifying_guild_damage
      / NULLIF(evaluated.qualifying_count, 0),
    evaluated.guild_average,
    evaluated.cluster_average,
    evaluated.qualifying_count,
    evaluated.biggest_hit,
    CASE
      WHEN guild_total.total_damage > 0
        THEN evaluated.total_damage / guild_total.total_damage * 100
      ELSE 0
    END,
    CASE
      WHEN evaluated.cluster_average > 0 THEN round(
        (
          evaluated.qualifying_cluster_damage
          / NULLIF(evaluated.qualifying_cluster_count, 0)
          / evaluated.cluster_average
          - 1
        ) * 100,
        2
      )
      ELSE 0
    END,
    CASE
      WHEN evaluated.guild_average > 0 THEN round(
        (
          evaluated.qualifying_guild_damage
          / NULLIF(evaluated.qualifying_count, 0)
          / evaluated.guild_average
          - 1
        ) * 100,
        2
      )
      ELSE 0
    END,
    evaluated.set_num,
    evaluated.tier,
    evaluated.rarity,
    COALESCE(
      evaluated.boss_preferences ->> concat('main_', evaluated.boss_name),
      'neutral'
    )
  FROM evaluated
  CROSS JOIN guild_total
  ORDER BY evaluated.id, evaluated.boss_name, evaluated.encounter_id
  LIMIT 2048;
END;
$$;

ALTER FUNCTION public.get_command_center_officer_boss_performance_v1(p_guild_code text, p_season text, p_player_mapping_ids integer[], p_boss_name text, p_rarity text, p_sets integer[]) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_officer_performance_summary_v1(p_guild_code text, p_season text, p_player_mapping_ids integer[]) RETURNS TABLE(player_mapping_id integer, display_name text, avg_vs_cluster numeric, avg_vs_guild numeric, avg_vs_cluster_boss_only numeric, avg_vs_guild_boss_only numeric, bosses_played integer, boss_hits integer, prime_hits integer, primes_played integer, total_battles integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_requested_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  v_requested_count := cardinality(p_player_mapping_ids);
  IF v_requested_count < 1
    OR v_requested_count > 32
    OR v_requested_count <> (
      SELECT count(DISTINCT requested_mapping_id)::integer
      FROM unnest(p_player_mapping_ids) AS requested_mapping_id
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT count(pm.id)::integer
    INTO v_mapping_count
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.guild_code = p_guild_code
      AND lower(pm.role::text) IN ('officer', 'leader')
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE;
    IF v_mapping_count <> 1 THEN
      RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT count(pm.id)::integer
  INTO v_mapping_count
  FROM public.player_mapping AS pm
  WHERE pm.id = ANY(p_player_mapping_ids)
    AND pm.guild_code = p_guild_code
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> v_requested_count THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    pm.id,
    pm.display_name,
    summary.avg_vs_cluster,
    summary.avg_vs_guild,
    summary.avg_vs_cluster_boss_only,
    summary.avg_vs_guild_boss_only,
    summary.bosses_played,
    summary.boss_hits,
    summary.prime_hits,
    summary.primes_played,
    summary.total_battles
  FROM public.get_player_performance_summary(
    p_guild_code,
    p_season,
    ARRAY['Legendary', 'Mythic']::text[]
  ) AS summary
  JOIN public.player_mapping AS pm
    ON pm.player_id = summary.user_id
   AND pm.id = ANY(p_player_mapping_ids)
  WHERE pm.id = ANY(p_player_mapping_ids)
    AND pm.guild_code = p_guild_code
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE
  ORDER BY pm.id
  LIMIT 32;
END;
$$;

ALTER FUNCTION public.get_command_center_officer_performance_summary_v1(p_guild_code text, p_season text, p_player_mapping_ids integer[]) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_officer_roster_v1(p_guild_code text, p_unit_ids text[]) RETURNS TABLE(player_mapping_id integer, player_display_name text, guild_role text, unit_id text, hero_display_name text, category text, web_icon_url text, stars integer, progression_index integer, rarity text, rank_name text, xp_level integer, active_ability_level integer, passive_ability_level integer, synced_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_requested_count integer;
  v_unique_count integer;
  v_max_unit_id_bytes integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT
    count(requested)::integer,
    count(DISTINCT requested)::integer,
    coalesce(max(octet_length(requested)), 0)::integer
  INTO v_requested_count, v_unique_count, v_max_unit_id_bytes
  FROM unnest(p_unit_ids) AS requested;
  IF v_requested_count < 1
    OR v_requested_count > 64
    OR v_requested_count <> v_unique_count
    OR v_max_unit_id_bytes > 128
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT count(pm.id)::integer
    INTO v_mapping_count
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.guild_code = p_guild_code
      AND lower(pm.role::text) IN ('officer', 'leader')
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE;
    IF v_mapping_count <> 1 THEN
      RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    pm.id,
    pm.display_name,
    pm.role::text,
    hm.unit_id,
    hm.display_name,
    hm.category,
    hm.web_icon_url,
    pr.stars,
    pr.progression_index,
    pr.rarity,
    pr.rank_name,
    pr.xp_level,
    pr.active_ability_level,
    pr.passive_ability_level,
    pr.synced_at
  FROM public.player_mapping AS pm
  JOIN public.player_roster AS pr
    ON pr.player_mapping_id = pm.id
  JOIN public.hero_mappings AS hm
    ON hm.id = pr.hero_mapping_id
  WHERE pm.guild_code = p_guild_code
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE
    AND hm.unit_id = ANY(p_unit_ids)
  ORDER BY pm.id, hm.unit_id
  LIMIT 2048;
END;
$$;

ALTER FUNCTION public.get_command_center_officer_roster_v1(p_guild_code text, p_unit_ids text[]) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_officer_season_forecast_v1(p_guild_code text, p_season_number integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_result jsonb;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT count(pm.id)::integer
    INTO v_mapping_count
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.guild_code = p_guild_code
      AND lower(pm.role::text) IN ('officer', 'leader')
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE;
    IF v_mapping_count <> 1 THEN
      RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
  END IF;

  WITH season_window AS MATERIALIZED (
    SELECT
      to_timestamp(
        1646128800
        + 86400
        + ((p_season_number + 10 - 1)::bigint * 1209600)
      ) AS starts_at
  ),
  timing AS MATERIALIZED (
    SELECT
      season_window.starts_at,
      season_window.starts_at + interval '1123200 seconds' AS ends_at,
      CASE
        WHEN statement_timestamp() < season_window.starts_at THEN 0
        ELSE GREATEST(
          0,
          extract(
            epoch FROM
              season_window.starts_at
              + interval '1123200 seconds'
              - statement_timestamp()
          )::bigint
        )
      END AS seconds_remaining
    FROM season_window
  ),
  players AS MATERIALIZED (
    SELECT
      pm.id,
      pm.display_name,
      COALESCE(pm.last_sync_tokens, 0)::integer AS tokens_now,
      GREATEST(COALESCE(pm.next_token_seconds, 0), 0)::integer
        AS next_token_seconds,
      COALESCE(pm.last_sync_bombs, 0)::integer AS bombs_now,
      GREATEST(COALESCE(pm.next_bomb_seconds, 0), 0)::integer
        AS next_bomb_seconds,
      COALESCE(burn.time_over_cap_seconds, 0)::bigint
        AS time_over_cap_seconds
    FROM public.player_mapping AS pm
    LEFT JOIN public.token_burn_state AS burn
      ON burn.guild_code = pm.guild_code
     AND burn.player_id = pm.player_id
     AND burn.season = p_season_number::text
    WHERE pm.guild_code = p_guild_code
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
      AND pm.player_id IS NOT NULL
  ),
  computed AS MATERIALIZED (
    SELECT
      players.id,
      players.display_name,
      players.tokens_now,
      players.next_token_seconds,
      GREATEST(
        0,
        LEAST(
          3 - players.tokens_now,
          CASE
            WHEN timing.seconds_remaining > players.next_token_seconds
            THEN floor(
              (
                timing.seconds_remaining
                - players.next_token_seconds
              )::numeric / 43200
            )::integer + 1
            ELSE 0
          END
        )
      )::integer AS tokens_will_regen,
      floor(timing.seconds_remaining::numeric / 43200)::integer
        AS theoretical_regen,
      players.time_over_cap_seconds,
      players.bombs_now,
      CASE
        WHEN players.bombs_now < 1
          AND timing.seconds_remaining > players.next_bomb_seconds
        THEN 1 - players.bombs_now
        ELSE 0
      END::integer AS bombs_will_regen
    FROM players
    CROSS JOIN timing
  ),
  full_player AS MATERIALIZED (
    SELECT
      computed.id,
      computed.display_name,
      computed.tokens_now,
      computed.next_token_seconds,
      computed.tokens_will_regen,
      LEAST(
        3,
        computed.tokens_now + computed.tokens_will_regen
      )::integer AS tokens_at_season_end,
      (
        computed.tokens_now + computed.tokens_will_regen >= 3
        AND computed.time_over_cap_seconds > 0
      ) AS will_cap,
      GREATEST(
        0,
        computed.theoretical_regen - computed.tokens_will_regen
      )::integer AS estimated_cap_waste,
      computed.bombs_now,
      computed.bombs_will_regen
    FROM computed
  ),
  envelope AS MATERIALIZED (
    SELECT
      COALESCE(sum(full_player.tokens_now), 0)::integer AS tokens_available,
      COALESCE(sum(full_player.tokens_will_regen), 0)::integer
        AS tokens_regen,
      COALESCE(
        sum(full_player.tokens_now + full_player.tokens_will_regen),
        0
      )::integer AS tokens_capacity,
      COALESCE(
        sum(CASE WHEN full_player.will_cap THEN 1 ELSE 0 END),
        0
      )::integer AS cap_bound_players,
      COALESCE(sum(full_player.estimated_cap_waste), 0)::integer
        AS estimated_cap_waste,
      COALESCE(sum(full_player.bombs_now), 0)::integer AS bombs_available,
      COALESCE(sum(full_player.bombs_will_regen), 0)::integer AS bombs_regen,
      COALESCE(
        sum(full_player.bombs_now + full_player.bombs_will_regen),
        0
      )::integer AS bombs_capacity
    FROM full_player
  ),
  lap_state AS MATERIALIZED (
    SELECT COALESCE(max(e."loopIndex"), 0)::integer AS current_lap
    FROM public."EOT_GR_data" AS e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season_number::text
      AND e."damageType" = 'Battle'
      AND e."loopIndex" IS NOT NULL
  ),
  current_lap AS MATERIALIZED (
    SELECT
      lap_state.current_lap,
      count(e."loopIndex")::integer AS tokens_into_current_lap
    FROM lap_state
    LEFT JOIN public."EOT_GR_data" AS e
      ON e."Guild" = p_guild_code
     AND e."Season" = p_season_number::text
     AND e."damageType" = 'Battle'
     AND e."loopIndex" = lap_state.current_lap
    GROUP BY lap_state.current_lap
  ),
  lap_costs AS MATERIALIZED (
    SELECT count(*)::integer AS tokens_used
    FROM current_lap
    JOIN public."EOT_GR_data" AS e
      ON e."Guild" = p_guild_code
     AND e."Season" = p_season_number::text
     AND e."damageType" = 'Battle'
     AND e."loopIndex" IS NOT NULL
     AND e."loopIndex" < current_lap.current_lap
    GROUP BY e."loopIndex"
    ORDER BY e."loopIndex" DESC
    LIMIT 2
  ),
  lap_stats AS MATERIALIZED (
    SELECT
      avg(lap_costs.tokens_used)::numeric AS projected_lap_cost,
      count(*)::integer AS sample_size
    FROM lap_costs
  ),
  player_output AS MATERIALIZED (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'player_mapping_id', full_player.id,
          'display_name', full_player.display_name,
          'tokens_now', full_player.tokens_now,
          'next_token_seconds', full_player.next_token_seconds,
          'tokens_will_regen', full_player.tokens_will_regen,
          'tokens_at_season_end', full_player.tokens_at_season_end,
          'will_cap', full_player.will_cap,
          'estimated_cap_waste', full_player.estimated_cap_waste
        )
        ORDER BY full_player.id
      ),
      '[]'::jsonb
    ) AS rows
    FROM full_player
  )
  SELECT jsonb_build_object(
    'season', jsonb_build_object(
      'number', p_season_number,
      'starts_at', timing.starts_at,
      'ends_at', timing.ends_at,
      'seconds_remaining', timing.seconds_remaining
    ),
    'tokens', jsonb_build_object(
      'available_now', envelope.tokens_available,
      'yet_to_regen', envelope.tokens_regen,
      'capacity', envelope.tokens_capacity,
      'cap_bound_players', envelope.cap_bound_players,
      'estimated_cap_waste', envelope.estimated_cap_waste
    ),
    'bombs', jsonb_build_object(
      'available_now', envelope.bombs_available,
      'yet_to_regen', envelope.bombs_regen,
      'capacity', envelope.bombs_capacity
    ),
    'lap_projection', CASE
      WHEN lap_stats.sample_size = 0
        OR lap_stats.projected_lap_cost IS NULL
      THEN NULL::jsonb
      ELSE jsonb_build_object(
        'current_lap', current_lap.current_lap,
        'tokens_into_current_lap', current_lap.tokens_into_current_lap,
        'projected_lap_cost', round(lap_stats.projected_lap_cost, 2),
        'basis', 'last_n_laps',
        'n', lap_stats.sample_size,
        'projected_finish_lap', CASE
          WHEN envelope.tokens_capacity
            >= GREATEST(
              lap_stats.projected_lap_cost
              - current_lap.tokens_into_current_lap,
              0
            )
          THEN current_lap.current_lap
          ELSE GREATEST(0, current_lap.current_lap - 1)
        END,
        'projected_finish_pct', round(
          LEAST(
            CASE
              WHEN envelope.tokens_capacity
                >= GREATEST(
                  lap_stats.projected_lap_cost
                  - current_lap.tokens_into_current_lap,
                  0
                )
              THEN (
                envelope.tokens_capacity
                - GREATEST(
                  lap_stats.projected_lap_cost
                  - current_lap.tokens_into_current_lap,
                  0
                )
              ) / NULLIF(lap_stats.projected_lap_cost, 0)
              ELSE (
                current_lap.tokens_into_current_lap
                + envelope.tokens_capacity
              ) / NULLIF(lap_stats.projected_lap_cost, 0)
            END,
            0.999
          ),
          4
        ),
        'confidence', CASE
          WHEN lap_stats.sample_size <= 1 THEN 'low'
          WHEN lap_stats.sample_size <= 3 THEN 'medium'
          ELSE 'high'
        END
      )
    END,
    'per_player', player_output.rows
  )
  INTO v_result
  FROM timing
  CROSS JOIN envelope
  CROSS JOIN current_lap
  CROSS JOIN lap_stats
  CROSS JOIN player_output;

  RETURN v_result;
END;
$$;

ALTER FUNCTION public.get_command_center_officer_season_forecast_v1(p_guild_code text, p_season_number integer) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_officer_team_usage_v1(p_guild_code text, p_season text, p_player_mapping_ids integer[], p_boss_name text, p_rarity_set text) RETURNS TABLE(player_mapping_id integer, display_name text, boss_name text, boss_type text, rarity text, set_num integer, rarity_set text, encounter_index integer, encounter_type text, team_hash text, team_composition text, attack_count bigint, avg_damage numeric, meta_team text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_requested_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  v_requested_count := cardinality(p_player_mapping_ids);
  IF v_requested_count < 1
    OR v_requested_count > 32
    OR v_requested_count <> (
      SELECT count(DISTINCT requested_mapping_id)::integer
      FROM unnest(p_player_mapping_ids) AS requested_mapping_id
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT count(pm.id)::integer
    INTO v_mapping_count
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.guild_code = p_guild_code
      AND lower(pm.role::text) IN ('officer', 'leader')
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE;
    IF v_mapping_count <> 1 THEN
      RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT count(pm.id)::integer
  INTO v_mapping_count
  FROM public.player_mapping AS pm
  WHERE pm.id = ANY(p_player_mapping_ids)
    AND pm.guild_code = p_guild_code
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> v_requested_count THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH current_season AS MATERIALIZED (
    SELECT max(e.season_num)::text AS season
    FROM public."EOT_GR_data" AS e
    WHERE e.season_num IS NOT NULL
  ),
  player_battles AS MATERIALIZED (
    SELECT
      pm.id AS player_mapping_id,
      pm.display_name,
      e."Name" AS boss_name,
      e.type AS boss_type,
      e.rarity,
      e.set AS set_num,
      e."encounterIndex" AS encounter_index,
      e."encounterType" AS encounter_type,
      e."damageDealt" AS damage,
      md5(
        array_to_string(team.unit_ids, ',')
        || '|'
        || COALESCE(team.mow_unit_id, 'none')
      ) AS team_hash,
      team.hero_display
        || CASE
          WHEN team.mow_display IS NULL THEN ''
          ELSE ' + ' || team.mow_display
        END AS team_composition,
      team.hero_names
    FROM public.player_mapping AS pm
    JOIN public."EOT_GR_data" AS e
      ON e."Guild" = pm.guild_code
     AND e."userId" = pm.player_id
    CROSS JOIN current_season
    CROSS JOIN LATERAL (
      SELECT
        array_agg(hero.unit_id ORDER BY hero.unit_id) AS unit_ids,
        array_agg(
          COALESCE(hm.display_name, hero.unit_id)
          ORDER BY COALESCE(hm.display_name, hero.unit_id)
        ) AS hero_names,
        string_agg(
          COALESCE(hm.display_name, hero.unit_id),
          ', '
          ORDER BY COALESCE(hm.display_name, hero.unit_id)
        ) AS hero_display,
        mow.unit_id AS mow_unit_id,
        COALESCE(mow_mapping.display_name, mow.unit_id) AS mow_display
      FROM (
        SELECT hero_element ->> 'unitId' AS unit_id
        FROM jsonb_array_elements(e."heroDetails"::jsonb) AS hero_element
      ) AS hero
      LEFT JOIN public.hero_mappings AS hm
        ON hm.unit_id = hero.unit_id
      CROSS JOIN LATERAL (
        SELECT CASE
          WHEN e."machineOfWarDetails" IS NULL
            OR e."machineOfWarDetails" IN ('', 'null')
          THEN NULL::text
          ELSE e."machineOfWarDetails"::jsonb ->> 'unitId'
        END AS unit_id
      ) AS mow
      LEFT JOIN public.hero_mappings AS mow_mapping
        ON mow_mapping.unit_id = mow.unit_id
      WHERE hero.unit_id IS NOT NULL
      GROUP BY mow.unit_id, mow_mapping.display_name
    ) AS team
    WHERE pm.id = ANY(p_player_mapping_ids)
      AND pm.guild_code = p_guild_code
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
      AND e."Season" = COALESCE(p_season, current_season.season)
      AND e."damageType" IN ('Battle', 'Bomb')
      AND e."heroDetails" IS NOT NULL
      AND e."heroDetails" NOT IN ('', '[]')
      AND (p_boss_name IS NULL OR e."Name" = p_boss_name)
  ),
  aggregated AS MATERIALIZED (
    SELECT
      battles.player_mapping_id,
      battles.display_name,
      battles.boss_name,
      battles.boss_type,
      battles.rarity,
      battles.set_num,
      battles.encounter_index,
      battles.encounter_type,
      battles.team_hash,
      battles.team_composition,
      battles.hero_names,
      count(*)::bigint AS attack_count,
      avg(battles.damage)::numeric AS avg_damage
    FROM player_battles AS battles
    CROSS JOIN current_season
    WHERE battles.team_hash IS NOT NULL
      AND battles.team_composition IS NOT NULL
    GROUP BY
      battles.player_mapping_id,
      battles.display_name,
      battles.boss_name,
      battles.boss_type,
      battles.rarity,
      battles.set_num,
      battles.encounter_index,
      battles.encounter_type,
      battles.team_hash,
      battles.team_composition,
      battles.hero_names,
      current_season.season
    HAVING count(*) >= CASE
      WHEN COALESCE(p_season, current_season.season) = current_season.season
        THEN 1
      ELSE 2
    END
  )
  SELECT
    aggregated.player_mapping_id,
    aggregated.display_name,
    aggregated.boss_name,
    aggregated.boss_type,
    aggregated.rarity,
    aggregated.set_num,
    CASE
      WHEN aggregated.rarity = 'Legendary'
        THEN 'L' || (COALESCE(aggregated.set_num, 0) + 1)::text
      WHEN aggregated.rarity = 'Mythic'
        THEN 'M' || (COALESCE(aggregated.set_num, 0) + 1)::text
      ELSE NULL::text
    END,
    aggregated.encounter_index,
    aggregated.encounter_type,
    aggregated.team_hash,
    aggregated.team_composition,
    aggregated.attack_count,
    aggregated.avg_damage,
    meta.team_name
  FROM aggregated
  LEFT JOIN LATERAL (
    SELECT mt.team_name
    FROM public.meta_teams AS mt
    WHERE mt.is_meta IS TRUE
      AND mt.trigger_heroes IS NOT NULL
      AND jsonb_typeof(mt.trigger_heroes) = 'array'
      AND jsonb_array_length(mt.trigger_heroes) > 0
      AND CASE mt.match_type
        WHEN 'any' THEN (
          SELECT count(*) > 0
          FROM jsonb_array_elements_text(mt.trigger_heroes) AS trigger_hero
          WHERE trigger_hero = ANY(aggregated.hero_names)
        )
        WHEN 'all' THEN (
          SELECT count(*) = jsonb_array_length(mt.trigger_heroes)
          FROM jsonb_array_elements_text(mt.trigger_heroes) AS trigger_hero
          WHERE trigger_hero = ANY(aggregated.hero_names)
        )
        WHEN 'exact' THEN (
          SELECT
            count(*) = jsonb_array_length(mt.trigger_heroes)
            AND cardinality(aggregated.hero_names)
              = jsonb_array_length(mt.trigger_heroes)
          FROM jsonb_array_elements_text(mt.trigger_heroes) AS trigger_hero
          WHERE trigger_hero = ANY(aggregated.hero_names)
        )
        ELSE FALSE
      END
    ORDER BY mt.sort_order
    LIMIT 1
  ) AS meta
    ON TRUE
  WHERE p_rarity_set IS NULL
    OR CASE
      WHEN aggregated.rarity = 'Legendary'
        THEN 'L' || (COALESCE(aggregated.set_num, 0) + 1)::text
      WHEN aggregated.rarity = 'Mythic'
        THEN 'M' || (COALESCE(aggregated.set_num, 0) + 1)::text
      ELSE NULL::text
    END = p_rarity_set
  ORDER BY
    aggregated.player_mapping_id,
    aggregated.attack_count DESC,
    aggregated.boss_name
  LIMIT 2048;
END;
$$;

ALTER FUNCTION public.get_command_center_officer_team_usage_v1(p_guild_code text, p_season text, p_player_mapping_ids integer[], p_boss_name text, p_rarity_set text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_officer_token_summary_v1(p_guild_code text, p_season text) RETURNS TABLE(player_mapping_id integer, display_name text, total_tokens_used integer, max_tokens_allowed integer, bosses_assigned integer, token_allocations jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT count(pm.id)::integer
    INTO v_mapping_count
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.guild_code = p_guild_code
      AND lower(pm.role::text) IN ('officer', 'leader')
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE;
    IF v_mapping_count <> 1 THEN
      RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    pm.id,
    pm.display_name,
    COALESCE(usa.total_tokens_allocated, 0),
    COALESCE(gc.primary_assignment_tokens, 5),
    (
      SELECT count(*)::integer
      FROM jsonb_each_text(
        COALESCE(usa.token_allocations, '{}'::jsonb)
      ) AS allocation
      WHERE allocation.value::integer > 0
    ),
    COALESCE(usa.token_allocations, '{}'::jsonb)
  FROM public.player_mapping AS pm
  JOIN public.guild_config AS gc
    ON gc.guild_code = pm.guild_code
  LEFT JOIN public.upcoming_season_assignments AS usa
    ON usa.guild_code = pm.guild_code
   AND usa.player_id = pm.player_id
   AND usa.season_number = p_season
  WHERE pm.guild_code = p_guild_code
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE
    AND usa.uses_flexible_tokens IS TRUE
  ORDER BY usa.total_tokens_allocated DESC, pm.id
  LIMIT 255;
END;
$$;

ALTER FUNCTION public.get_command_center_officer_token_summary_v1(p_guild_code text, p_season text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_officer_token_usage_v1(p_guild_code text, p_season text) RETURNS TABLE(player_mapping_id integer, display_name text, tokens_used integer, max_possible integer, tokens_below_offender boolean, tokens_below_abuser boolean, boss_tokens integer, prime_tokens integer, bombs_used integer, bombs_available integer, burned_tokens integer, time_over_cap_seconds integer, tokens_available integer, token_next_in_seconds integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_role text;
  v_mapping_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT count(pm.id)::integer
    INTO v_mapping_count
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.guild_code = p_guild_code
      AND lower(pm.role::text) IN ('officer', 'leader')
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE;
    IF v_mapping_count <> 1 THEN
      RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH members AS MATERIALIZED (
    SELECT
      pm.id,
      pm.player_id,
      pm.display_name,
      pm.last_sync_tokens,
      pm.last_sync_bombs,
      pm.last_sync_at,
      pm.next_token_seconds,
      pm.next_bomb_seconds
    FROM public.player_mapping AS pm
    WHERE pm.guild_code = p_guild_code
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
  ),
  config AS MATERIALIZED (
    SELECT
      COALESCE(gc.token_offender_threshold, 4)::integer AS offender_threshold,
      COALESCE(gc.token_abuser_threshold, 5)::integer AS abuser_threshold
    FROM public.guild_config AS gc
    WHERE gc.guild_code = p_guild_code
  ),
  battle_usage AS MATERIALIZED (
    SELECT
      members.player_id,
      count(*) FILTER (
        WHERE e."Season" = p_season
          AND e."damageType" = 'Battle'
          AND e."damageDealt" > 0
      )::integer AS tokens_used,
      count(*) FILTER (
        WHERE e."Season" = p_season
          AND e."damageType" = 'Battle'
          AND e."damageDealt" > 0
          AND COALESCE(e."encounterId", 0) = 0
      )::integer AS boss_tokens,
      count(*) FILTER (
        WHERE e."Season" = p_season
          AND e."damageType" = 'Battle'
          AND e."damageDealt" > 0
          AND COALESCE(e."encounterId", 0) <> 0
      )::integer AS prime_tokens,
      count(*) FILTER (
        WHERE e."Season" = p_season
          AND e."damageType" = 'Bomb'
      )::integer AS bombs_used,
      count(DISTINCT coalesce(e."startedOn", e.timestamp)) FILTER (
        WHERE e."damageType" = 'Battle'
          AND coalesce(e."startedOn", e.timestamp)
            >= statement_timestamp() - interval '12 hours'
      )::integer AS recent_battles,
      max(coalesce(e."startedOn", e.timestamp)) FILTER (
        WHERE e."damageType" = 'Battle'
      ) AS last_battle_time,
      array_agg(
        DISTINCT coalesce(e."startedOn", e.timestamp)
        ORDER BY coalesce(e."startedOn", e.timestamp)
      ) FILTER (
        WHERE e."damageType" = 'Battle'
          AND members.last_sync_at IS NOT NULL
          AND coalesce(e."startedOn", e.timestamp) > members.last_sync_at
      ) AS battle_spend_times,
      array_agg(
        DISTINCT coalesce(e."startedOn", e.timestamp)
        ORDER BY coalesce(e."startedOn", e.timestamp)
      ) FILTER (
        WHERE e."damageType" = 'Bomb'
          AND members.last_sync_at IS NOT NULL
          AND coalesce(e."startedOn", e.timestamp) > members.last_sync_at
      ) AS bomb_spend_times
    FROM members
    LEFT JOIN public."EOT_GR_data" AS e
      ON e."Guild" = p_guild_code
     AND (
       e."Season" = p_season
       OR (
         p_season ~ '^\d+$'
         AND e."Season" = (p_season::integer - 1)::text
       )
     )
     AND e."userId" = members.player_id
     AND e."displayName" IS NOT NULL
     AND e."damageType" IN ('Battle', 'Bomb')
    GROUP BY members.player_id, members.last_sync_at
  ),
  projection AS MATERIALIZED (
    SELECT
      members.id,
      members.player_id,
      members.display_name,
      members.last_sync_at,
      members.next_token_seconds,
      members.next_bomb_seconds,
      CASE
        WHEN members.last_sync_tokens IS NULL THEN NULL::integer
        ELSE GREATEST(0, LEAST(3, members.last_sync_tokens))::integer
      END AS synced_tokens,
      CASE
        WHEN members.last_sync_bombs IS NULL THEN NULL::integer
        ELSE GREATEST(0, LEAST(1, members.last_sync_bombs))::integer
      END AS synced_bombs,
      battle_usage.tokens_used,
      battle_usage.boss_tokens,
      battle_usage.prime_tokens,
      battle_usage.bombs_used,
      battle_usage.recent_battles,
      battle_usage.last_battle_time,
      battle_usage.battle_spend_times,
      battle_usage.bomb_spend_times
    FROM members
    JOIN battle_usage
      ON battle_usage.player_id = members.player_id
  ),
  state AS MATERIALIZED (
    SELECT
      projection.id,
      projection.player_id,
      projection.display_name,
      projection.tokens_used,
      projection.boss_tokens,
      projection.prime_tokens,
      projection.bombs_used,
      CASE
        WHEN projection.last_sync_at IS NULL
          OR projection.synced_tokens IS NULL
        THEN CASE
          WHEN projection.last_battle_time IS NULL
            OR projection.last_battle_time
              <= statement_timestamp() - interval '12 hours'
          THEN 3
          ELSE GREATEST(0, 2 - projection.recent_battles)
        END
        ELSE token_projection.available
      END::integer AS tokens_available,
      CASE
        WHEN projection.last_sync_at IS NULL
          OR projection.synced_tokens IS NULL
        THEN NULL::integer
        ELSE token_projection.next_in_seconds
      END AS token_next_in_seconds,
      CASE
        WHEN projection.last_sync_at IS NULL
          OR projection.synced_bombs IS NULL
        THEN CASE
          WHEN projection.bombs_used = 0 THEN 1
          ELSE 0
        END
        ELSE bomb_projection.available
      END::integer AS bombs_available,
      COALESCE(burn.burned_tokens, 0)::integer AS burned_tokens,
      COALESCE(burn.time_over_cap_seconds, 0)::integer AS time_over_cap_seconds
    FROM projection
    CROSS JOIN LATERAL public.project_token_snapshot(
      projection.synced_tokens,
      projection.next_token_seconds,
      projection.last_sync_at,
      coalesce(
        projection.battle_spend_times,
        ARRAY[]::timestamptz[]
      ),
      statement_timestamp(),
      3,
      43200
    ) AS token_projection
    CROSS JOIN LATERAL public.project_token_snapshot(
      projection.synced_bombs,
      projection.next_bomb_seconds,
      projection.last_sync_at,
      coalesce(
        projection.bomb_spend_times,
        ARRAY[]::timestamptz[]
      ),
      statement_timestamp(),
      1,
      64800
    ) AS bomb_projection
    LEFT JOIN public.token_burn_state AS burn
      ON burn.guild_code = p_guild_code
     AND burn.season = p_season
     AND burn.player_id = projection.player_id
  ),
  max_tokens AS (
    SELECT LEAST(
      28,
      COALESCE(max(state.tokens_used + state.tokens_available), 0)
    )::integer AS max_possible
    FROM state
  )
  SELECT
    state.id,
    state.display_name,
    COALESCE(state.tokens_used, 0)::integer,
    max_tokens.max_possible,
    (max_tokens.max_possible - COALESCE(state.tokens_used, 0))
      >= config.offender_threshold,
    (max_tokens.max_possible - COALESCE(state.tokens_used, 0))
      >= config.abuser_threshold,
    COALESCE(state.boss_tokens, 0)::integer,
    COALESCE(state.prime_tokens, 0)::integer,
    COALESCE(state.bombs_used, 0)::integer,
    COALESCE(state.bombs_available, 0)::integer,
    COALESCE(state.burned_tokens, 0)::integer,
    COALESCE(state.time_over_cap_seconds, 0)::integer,
    COALESCE(state.tokens_available, 0)::integer,
    state.token_next_in_seconds::integer
  FROM state
  CROSS JOIN config
  CROSS JOIN max_tokens
  ORDER BY state.id
  LIMIT 255;
END;
$_$;

ALTER FUNCTION public.get_command_center_officer_token_usage_v1(p_guild_code text, p_season text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_self_boss_performance_v1(p_season text, p_boss_name text, p_rarity text, p_sets integer[]) RETURNS TABLE(player_mapping_id integer, boss_name text, encounter_id integer, player_avg numeric, battle_count integer, biggest_hit bigint, player_vs_guild_avg numeric, player_vs_cluster_avg numeric, set_num integer, tier integer, rarity text, boss_preference text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  IF p_sets IS NOT NULL
    AND (
      cardinality(p_sets) > 5
      OR cardinality(p_sets) <> (
        SELECT count(DISTINCT requested_set)::integer
        FROM unnest(p_sets) AS requested_set
      )
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023';
  END IF;

  SELECT count(pm.id)::integer
  INTO v_mapping_count
  FROM public.player_mapping AS pm
  WHERE pm.user_id = auth.uid()
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH caller AS MATERIALIZED (
    SELECT
      pm.id,
      pm.player_id,
      pm.guild_code,
      pm.cluster_code,
      pm.boss_preferences
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
  ),
  player_boss_stats AS MATERIALIZED (
    SELECT
      e."Name" AS boss_name,
      COALESCE(e."encounterId", 0)::integer AS encounter_id,
      e.tier::integer AS tier,
      e.set::integer AS set_num,
      e.rarity AS rarity,
      sum(e."damageDealt") FILTER (
        WHERE NOT (
          e."remainingHp" = 0
          AND e."maxHp" > 0
          AND e."damageDealt" < e."maxHp"
        )
      )::numeric AS non_sweep_damage,
      count(*) FILTER (
        WHERE NOT (
          e."remainingHp" = 0
          AND e."maxHp" > 0
          AND e."damageDealt" < e."maxHp"
        )
      )::integer AS non_sweep_count,
      array_agg(e."damageDealt"::numeric) FILTER (
        WHERE e."remainingHp" = 0
          AND e."maxHp" > 0
          AND e."damageDealt" < e."maxHp"
      ) AS sweep_damages,
      max(e."damageDealt")::bigint AS biggest_hit
    FROM caller
    JOIN public."EOT_GR_data" AS e
      ON e."Guild" = caller.guild_code
     AND e."userId" = caller.player_id
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND (p_boss_name IS NULL OR e."Name" = p_boss_name)
      AND (p_rarity IS NULL OR e.rarity = p_rarity)
      AND (p_sets IS NULL OR e.set = ANY(p_sets))
    GROUP BY e."Name", e."encounterId", e.tier, e.set, e.rarity
  ),
  guild_average AS MATERIALIZED (
    SELECT
      e."Name" AS boss_name,
      COALESCE(e."encounterId", 0)::integer AS encounter_id,
      e.rarity,
      avg(e."damageDealt")::numeric AS average_damage
    FROM caller
    JOIN public."EOT_GR_data" AS e
      ON e."Guild" = caller.guild_code
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (
        e."remainingHp" = 0
        AND e."maxHp" > 0
        AND e."damageDealt" < e."maxHp"
      )
    GROUP BY e."Name", e."encounterId", e.rarity
  ),
  cluster_average AS MATERIALIZED (
    SELECT
      e."Name" AS boss_name,
      COALESCE(e."encounterId", 0)::integer AS encounter_id,
      e.rarity,
      avg(e."damageDealt")::numeric AS average_damage
    FROM caller
    JOIN public.guild_config AS gc
      ON gc.cluster_code = caller.cluster_code
    JOIN public."EOT_GR_data" AS e
      ON e."Guild" = gc.guild_code
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (
        e."remainingHp" = 0
        AND e."maxHp" > 0
        AND e."damageDealt" < e."maxHp"
      )
    GROUP BY e."Name", e."encounterId", e.rarity
  ),
  evaluated AS (
    SELECT
      stats.boss_name,
      stats.encounter_id,
      stats.tier,
      stats.set_num,
      stats.rarity,
      stats.non_sweep_damage,
      stats.non_sweep_count,
      stats.sweep_damages,
      stats.biggest_hit,
      guild_average.average_damage AS guild_average,
      cluster_average.average_damage AS cluster_average,
      (
        COALESCE(stats.non_sweep_count, 0)
        + COALESCE(
          public.qualifying_sweep_count(
            stats.sweep_damages,
            GREATEST(
              stats.non_sweep_damage / NULLIF(stats.non_sweep_count, 0),
              guild_average.average_damage
            )
          ),
          0
        )
      )::integer AS qualifying_count,
      (
        COALESCE(stats.non_sweep_damage, 0)
        + COALESCE(
          public.qualifying_sweep_sum(
            stats.sweep_damages,
            GREATEST(
              stats.non_sweep_damage / NULLIF(stats.non_sweep_count, 0),
              guild_average.average_damage
            )
          ),
          0
        )
      )::numeric AS qualifying_guild_damage,
      (
        COALESCE(stats.non_sweep_damage, 0)
        + COALESCE(
          public.qualifying_sweep_sum(
            stats.sweep_damages,
            GREATEST(
              stats.non_sweep_damage / NULLIF(stats.non_sweep_count, 0),
              cluster_average.average_damage
            )
          ),
          0
        )
      )::numeric AS qualifying_cluster_damage,
      (
        COALESCE(stats.non_sweep_count, 0)
        + COALESCE(
          public.qualifying_sweep_count(
            stats.sweep_damages,
            GREATEST(
              stats.non_sweep_damage / NULLIF(stats.non_sweep_count, 0),
              cluster_average.average_damage
            )
          ),
          0
        )
      )::integer AS qualifying_cluster_count
    FROM player_boss_stats AS stats
    LEFT JOIN guild_average
      ON guild_average.boss_name = stats.boss_name
     AND guild_average.encounter_id = stats.encounter_id
     AND guild_average.rarity = stats.rarity
    LEFT JOIN cluster_average
      ON cluster_average.boss_name = stats.boss_name
     AND cluster_average.encounter_id = stats.encounter_id
     AND cluster_average.rarity = stats.rarity
  )
  SELECT
    caller.id,
    evaluated.boss_name,
    evaluated.encounter_id,
    evaluated.qualifying_guild_damage
      / NULLIF(evaluated.qualifying_count, 0),
    evaluated.qualifying_count,
    evaluated.biggest_hit,
    CASE
      WHEN evaluated.guild_average > 0 THEN round(
        (
          evaluated.qualifying_guild_damage
          / NULLIF(evaluated.qualifying_count, 0)
          / evaluated.guild_average
          - 1
        ) * 100,
        2
      )
      ELSE 0
    END,
    CASE
      WHEN evaluated.cluster_average > 0 THEN round(
        (
          evaluated.qualifying_cluster_damage
          / NULLIF(evaluated.qualifying_cluster_count, 0)
          / evaluated.cluster_average
          - 1
        ) * 100,
        2
      )
      ELSE 0
    END,
    evaluated.set_num,
    evaluated.tier,
    evaluated.rarity,
    COALESCE(
      caller.boss_preferences ->> concat('main_', evaluated.boss_name),
      'neutral'
    )
  FROM caller
  CROSS JOIN evaluated
  ORDER BY evaluated.boss_name, evaluated.encounter_id
  LIMIT 255;
END;
$$;

ALTER FUNCTION public.get_command_center_self_boss_performance_v1(p_season text, p_boss_name text, p_rarity text, p_sets integer[]) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_self_performance_summary_v1(p_season text) RETURNS TABLE(player_mapping_id integer, avg_vs_cluster numeric, avg_vs_guild numeric, avg_vs_cluster_boss_only numeric, avg_vs_guild_boss_only numeric, bosses_played integer, boss_hits integer, prime_hits integer, primes_played integer, total_battles integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_player_mapping_id integer;
  v_player_id text;
  v_guild_code text;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT
    count(pm.id)::integer,
    max(pm.id),
    max(pm.player_id),
    max(pm.guild_code)
  INTO
    v_mapping_count,
    v_player_mapping_id,
    v_player_id,
    v_guild_code
  FROM public.player_mapping AS pm
  WHERE pm.user_id = auth.uid()
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    v_player_mapping_id,
    summary.avg_vs_cluster,
    summary.avg_vs_guild,
    summary.avg_vs_cluster_boss_only,
    summary.avg_vs_guild_boss_only,
    summary.bosses_played,
    summary.boss_hits,
    summary.prime_hits,
    summary.primes_played,
    summary.total_battles
  FROM public.get_player_performance_summary(
    v_guild_code,
    p_season,
    ARRAY['Legendary', 'Mythic']::text[]
  ) AS summary
  WHERE summary.user_id = v_player_id;
END;
$$;

ALTER FUNCTION public.get_command_center_self_performance_summary_v1(p_season text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_self_roster_v1(p_unit_ids text[]) RETURNS TABLE(player_mapping_id integer, unit_id text, hero_display_name text, category text, web_icon_url text, stars integer, progression_index integer, rarity text, rank_name text, xp_level integer, active_ability_level integer, passive_ability_level integer, synced_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_player_mapping_id integer;
  v_requested_count integer;
  v_unique_count integer;
  v_max_unit_id_bytes integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT
    count(requested)::integer,
    count(DISTINCT requested)::integer,
    coalesce(max(octet_length(requested)), 0)::integer
  INTO v_requested_count, v_unique_count, v_max_unit_id_bytes
  FROM unnest(p_unit_ids) AS requested;
  IF v_requested_count < 1
    OR v_requested_count > 64
    OR v_requested_count <> v_unique_count
    OR v_max_unit_id_bytes > 128
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023';
  END IF;

  SELECT count(pm.id)::integer, max(pm.id)
  INTO v_mapping_count, v_player_mapping_id
  FROM public.player_mapping AS pm
  WHERE pm.user_id = auth.uid()
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    pm.id,
    hm.unit_id,
    hm.display_name,
    hm.category,
    hm.web_icon_url,
    pr.stars,
    pr.progression_index,
    pr.rarity,
    pr.rank_name,
    pr.xp_level,
    pr.active_ability_level,
    pr.passive_ability_level,
    pr.synced_at
  FROM public.player_mapping AS pm
  JOIN public.player_roster AS pr
    ON pr.player_mapping_id = pm.id
  JOIN public.hero_mappings AS hm
    ON hm.id = pr.hero_mapping_id
  WHERE pm.id = v_player_mapping_id
    AND hm.unit_id = ANY(p_unit_ids)
  ORDER BY hm.unit_id
  LIMIT 64;
END;
$$;

ALTER FUNCTION public.get_command_center_self_roster_v1(p_unit_ids text[]) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_self_team_usage_v1(p_season text, p_boss_name text, p_rarity_set text) RETURNS TABLE(player_mapping_id integer, boss_name text, boss_type text, rarity text, set_num integer, rarity_set text, encounter_index integer, encounter_type text, team_hash text, team_composition text, attack_count bigint, avg_damage numeric, meta_team text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT count(pm.id)::integer
  INTO v_mapping_count
  FROM public.player_mapping AS pm
  WHERE pm.user_id = auth.uid()
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH current_season AS MATERIALIZED (
    SELECT max(e.season_num)::text AS season
    FROM public."EOT_GR_data" AS e
    WHERE e.season_num IS NOT NULL
  ),
  player_battles AS MATERIALIZED (
    SELECT
      pm.id AS player_mapping_id,
      e."Name" AS boss_name,
      e.type AS boss_type,
      e.rarity,
      e.set AS set_num,
      e."encounterIndex" AS encounter_index,
      e."encounterType" AS encounter_type,
      e."heroDetails" AS hero_details,
      e."machineOfWarDetails" AS mow_details,
      e."damageDealt" AS damage,
      md5(
        array_to_string(team.unit_ids, ',')
        || '|'
        || COALESCE(team.mow_unit_id, 'none')
      ) AS team_hash,
      team.hero_display
        || CASE
          WHEN team.mow_display IS NULL THEN ''
          ELSE ' + ' || team.mow_display
        END AS team_composition,
      team.hero_names
    FROM public.player_mapping AS pm
    JOIN public."EOT_GR_data" AS e
      ON e."Guild" = pm.guild_code
     AND e."userId" = pm.player_id
    CROSS JOIN current_season
    CROSS JOIN LATERAL (
      SELECT
        array_agg(hero.unit_id ORDER BY hero.unit_id) AS unit_ids,
        array_agg(
          COALESCE(hm.display_name, hero.unit_id)
          ORDER BY COALESCE(hm.display_name, hero.unit_id)
        ) AS hero_names,
        string_agg(
          COALESCE(hm.display_name, hero.unit_id),
          ', '
          ORDER BY COALESCE(hm.display_name, hero.unit_id)
        ) AS hero_display,
        mow.unit_id AS mow_unit_id,
        COALESCE(mow_mapping.display_name, mow.unit_id) AS mow_display
      FROM (
        SELECT hero_element ->> 'unitId' AS unit_id
        FROM jsonb_array_elements(e."heroDetails"::jsonb) AS hero_element
      ) AS hero
      LEFT JOIN public.hero_mappings AS hm
        ON hm.unit_id = hero.unit_id
      CROSS JOIN LATERAL (
        SELECT CASE
          WHEN e."machineOfWarDetails" IS NULL
            OR e."machineOfWarDetails" IN ('', 'null')
          THEN NULL::text
          ELSE e."machineOfWarDetails"::jsonb ->> 'unitId'
        END AS unit_id
      ) AS mow
      LEFT JOIN public.hero_mappings AS mow_mapping
        ON mow_mapping.unit_id = mow.unit_id
      WHERE hero.unit_id IS NOT NULL
      GROUP BY mow.unit_id, mow_mapping.display_name
    ) AS team
    WHERE pm.user_id = auth.uid()
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
      AND e."Season" = COALESCE(p_season, current_season.season)
      AND e."damageType" IN ('Battle', 'Bomb')
      AND e."heroDetails" IS NOT NULL
      AND e."heroDetails" NOT IN ('', '[]')
      AND (p_boss_name IS NULL OR e."Name" = p_boss_name)
  ),
  aggregated AS MATERIALIZED (
    SELECT
      battles.player_mapping_id,
      battles.boss_name,
      battles.boss_type,
      battles.rarity,
      battles.set_num,
      battles.encounter_index,
      battles.encounter_type,
      battles.team_hash,
      battles.team_composition,
      battles.hero_names,
      count(*)::bigint AS attack_count,
      avg(battles.damage)::numeric AS avg_damage
    FROM player_battles AS battles
    CROSS JOIN current_season
    WHERE battles.team_hash IS NOT NULL
      AND battles.team_composition IS NOT NULL
    GROUP BY
      battles.player_mapping_id,
      battles.boss_name,
      battles.boss_type,
      battles.rarity,
      battles.set_num,
      battles.encounter_index,
      battles.encounter_type,
      battles.team_hash,
      battles.team_composition,
      battles.hero_names,
      current_season.season
    HAVING count(*) >= CASE
      WHEN COALESCE(p_season, current_season.season) = current_season.season
        THEN 1
      ELSE 2
    END
  )
  SELECT
    aggregated.player_mapping_id,
    aggregated.boss_name,
    aggregated.boss_type,
    aggregated.rarity,
    aggregated.set_num,
    CASE
      WHEN aggregated.rarity = 'Legendary'
        THEN 'L' || (COALESCE(aggregated.set_num, 0) + 1)::text
      WHEN aggregated.rarity = 'Mythic'
        THEN 'M' || (COALESCE(aggregated.set_num, 0) + 1)::text
      ELSE NULL::text
    END,
    aggregated.encounter_index,
    aggregated.encounter_type,
    aggregated.team_hash,
    aggregated.team_composition,
    aggregated.attack_count,
    aggregated.avg_damage,
    meta.team_name
  FROM aggregated
  LEFT JOIN LATERAL (
    SELECT mt.team_name
    FROM public.meta_teams AS mt
    WHERE mt.is_meta IS TRUE
      AND mt.trigger_heroes IS NOT NULL
      AND jsonb_typeof(mt.trigger_heroes) = 'array'
      AND jsonb_array_length(mt.trigger_heroes) > 0
      AND CASE mt.match_type
        WHEN 'any' THEN (
          SELECT count(*) > 0
          FROM jsonb_array_elements_text(mt.trigger_heroes) AS trigger_hero
          WHERE trigger_hero = ANY(aggregated.hero_names)
        )
        WHEN 'all' THEN (
          SELECT count(*) = jsonb_array_length(mt.trigger_heroes)
          FROM jsonb_array_elements_text(mt.trigger_heroes) AS trigger_hero
          WHERE trigger_hero = ANY(aggregated.hero_names)
        )
        WHEN 'exact' THEN (
          SELECT
            count(*) = jsonb_array_length(mt.trigger_heroes)
            AND cardinality(aggregated.hero_names)
              = jsonb_array_length(mt.trigger_heroes)
          FROM jsonb_array_elements_text(mt.trigger_heroes) AS trigger_hero
          WHERE trigger_hero = ANY(aggregated.hero_names)
        )
        ELSE FALSE
      END
    ORDER BY mt.sort_order
    LIMIT 1
  ) AS meta
    ON TRUE
  WHERE p_rarity_set IS NULL
    OR CASE
      WHEN aggregated.rarity = 'Legendary'
        THEN 'L' || (COALESCE(aggregated.set_num, 0) + 1)::text
      WHEN aggregated.rarity = 'Mythic'
        THEN 'M' || (COALESCE(aggregated.set_num, 0) + 1)::text
      ELSE NULL::text
    END = p_rarity_set
  ORDER BY aggregated.attack_count DESC, aggregated.boss_name
  LIMIT 255;
END;
$$;

ALTER FUNCTION public.get_command_center_self_team_usage_v1(p_season text, p_boss_name text, p_rarity_set text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_command_center_self_token_usage_v1(p_season text) RETURNS TABLE(player_mapping_id integer, tokens_used integer, max_possible integer, tokens_below_offender boolean, tokens_below_abuser boolean, boss_tokens integer, prime_tokens integer, bombs_used integer, bombs_available integer, burned_tokens integer, time_over_cap_seconds integer, tokens_available integer, token_next_in_seconds integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_role text;
  v_mapping_count integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT count(pm.id)::integer
  INTO v_mapping_count
  FROM public.player_mapping AS pm
  WHERE pm.user_id = auth.uid()
    AND pm.is_active IS TRUE
    AND pm.is_current IS TRUE;
  IF v_mapping_count <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH caller AS MATERIALIZED (
    SELECT pm.id, pm.player_id, pm.guild_code
    FROM public.player_mapping AS pm
    WHERE pm.user_id = auth.uid()
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
  ),
  members AS MATERIALIZED (
    SELECT
      pm.player_id,
      pm.last_sync_tokens,
      pm.last_sync_bombs,
      pm.last_sync_at,
      pm.next_token_seconds,
      pm.next_bomb_seconds
    FROM public.player_mapping AS pm
    JOIN caller
      ON caller.guild_code = pm.guild_code
    WHERE pm.is_active IS TRUE
      AND pm.is_current IS TRUE
  ),
  config AS MATERIALIZED (
    SELECT
      COALESCE(gc.token_offender_threshold, 4)::integer AS offender_threshold,
      COALESCE(gc.token_abuser_threshold, 5)::integer AS abuser_threshold
    FROM public.guild_config AS gc
    JOIN caller
      ON caller.guild_code = gc.guild_code
  ),
  battle_usage AS MATERIALIZED (
    SELECT
      members.player_id,
      count(*) FILTER (
        WHERE e."Season" = p_season
          AND e."damageType" = 'Battle'
          AND e."damageDealt" > 0
      )::integer AS tokens_used,
      count(*) FILTER (
        WHERE e."Season" = p_season
          AND e."damageType" = 'Battle'
          AND e."damageDealt" > 0
          AND COALESCE(e."encounterId", 0) = 0
      )::integer AS boss_tokens,
      count(*) FILTER (
        WHERE e."Season" = p_season
          AND e."damageType" = 'Battle'
          AND e."damageDealt" > 0
          AND COALESCE(e."encounterId", 0) <> 0
      )::integer AS prime_tokens,
      count(*) FILTER (
        WHERE e."Season" = p_season
          AND e."damageType" = 'Bomb'
      )::integer AS bombs_used,
      count(DISTINCT coalesce(e."startedOn", e.timestamp)) FILTER (
        WHERE e."damageType" = 'Battle'
          AND coalesce(e."startedOn", e.timestamp)
            >= statement_timestamp() - interval '12 hours'
      )::integer AS recent_battles,
      max(coalesce(e."startedOn", e.timestamp)) FILTER (
        WHERE e."damageType" = 'Battle'
      ) AS last_battle_time,
      array_agg(
        DISTINCT coalesce(e."startedOn", e.timestamp)
        ORDER BY coalesce(e."startedOn", e.timestamp)
      ) FILTER (
        WHERE e."damageType" = 'Battle'
          AND members.last_sync_at IS NOT NULL
          AND coalesce(e."startedOn", e.timestamp) > members.last_sync_at
      ) AS battle_spend_times,
      array_agg(
        DISTINCT coalesce(e."startedOn", e.timestamp)
        ORDER BY coalesce(e."startedOn", e.timestamp)
      ) FILTER (
        WHERE e."damageType" = 'Bomb'
          AND members.last_sync_at IS NOT NULL
          AND coalesce(e."startedOn", e.timestamp) > members.last_sync_at
      ) AS bomb_spend_times
    FROM members
    JOIN caller
      ON TRUE
    LEFT JOIN public."EOT_GR_data" AS e
      ON e."Guild" = caller.guild_code
     AND (
       e."Season" = p_season
       OR (
         p_season ~ '^\d+$'
         AND e."Season" = (p_season::integer - 1)::text
       )
     )
     AND e."userId" = members.player_id
     AND e."displayName" IS NOT NULL
     AND e."damageType" IN ('Battle', 'Bomb')
    GROUP BY members.player_id, members.last_sync_at
  ),
  projection AS MATERIALIZED (
    SELECT
      members.player_id,
      members.last_sync_at,
      members.next_token_seconds,
      members.next_bomb_seconds,
      CASE
        WHEN members.last_sync_tokens IS NULL THEN NULL::integer
        ELSE GREATEST(0, LEAST(3, members.last_sync_tokens))::integer
      END AS synced_tokens,
      CASE
        WHEN members.last_sync_bombs IS NULL THEN NULL::integer
        ELSE GREATEST(0, LEAST(1, members.last_sync_bombs))::integer
      END AS synced_bombs,
      battle_usage.tokens_used,
      battle_usage.boss_tokens,
      battle_usage.prime_tokens,
      battle_usage.bombs_used,
      battle_usage.recent_battles,
      battle_usage.last_battle_time,
      battle_usage.battle_spend_times,
      battle_usage.bomb_spend_times
    FROM members
    JOIN battle_usage
      ON battle_usage.player_id = members.player_id
  ),
  state AS MATERIALIZED (
    SELECT
      projection.player_id,
      projection.tokens_used,
      CASE
        WHEN projection.last_sync_at IS NULL
          OR projection.synced_tokens IS NULL
        THEN CASE
          WHEN projection.last_battle_time IS NULL
            OR projection.last_battle_time
              <= statement_timestamp() - interval '12 hours'
          THEN 3
          ELSE GREATEST(0, 2 - projection.recent_battles)
        END
        ELSE token_projection.available
      END::integer AS tokens_available,
      CASE
        WHEN projection.last_sync_at IS NULL
          OR projection.synced_tokens IS NULL
        THEN NULL::integer
        ELSE token_projection.next_in_seconds
      END AS token_next_in_seconds,
      CASE
        WHEN projection.last_sync_at IS NULL
          OR projection.synced_bombs IS NULL
        THEN CASE
          WHEN projection.bombs_used = 0 THEN 1
          ELSE 0
        END
        ELSE bomb_projection.available
      END::integer AS bombs_available,
      COALESCE(burn.burned_tokens, 0)::integer AS burned_tokens,
      COALESCE(burn.time_over_cap_seconds, 0)::integer AS time_over_cap_seconds
    FROM projection
    JOIN caller
      ON TRUE
    CROSS JOIN LATERAL public.project_token_snapshot(
      projection.synced_tokens,
      projection.next_token_seconds,
      projection.last_sync_at,
      coalesce(
        projection.battle_spend_times,
        ARRAY[]::timestamptz[]
      ),
      statement_timestamp(),
      3,
      43200
    ) AS token_projection
    CROSS JOIN LATERAL public.project_token_snapshot(
      projection.synced_bombs,
      projection.next_bomb_seconds,
      projection.last_sync_at,
      coalesce(
        projection.bomb_spend_times,
        ARRAY[]::timestamptz[]
      ),
      statement_timestamp(),
      1,
      64800
    ) AS bomb_projection
    LEFT JOIN public.token_burn_state AS burn
      ON burn.guild_code = caller.guild_code
     AND burn.season = p_season
     AND burn.player_id = projection.player_id
  ),
  max_tokens AS (
    SELECT LEAST(
      28,
      COALESCE(max(state.tokens_used + state.tokens_available), 0)
    )::integer AS max_possible
    FROM state
  )
  SELECT
    caller.id,
    COALESCE(battle_usage.tokens_used, state.tokens_used, 0)::integer,
    max_tokens.max_possible,
    (max_tokens.max_possible - COALESCE(battle_usage.tokens_used, state.tokens_used, 0))
      >= config.offender_threshold,
    (max_tokens.max_possible - COALESCE(battle_usage.tokens_used, state.tokens_used, 0))
      >= config.abuser_threshold,
    COALESCE(battle_usage.boss_tokens, 0)::integer,
    COALESCE(battle_usage.prime_tokens, 0)::integer,
    COALESCE(battle_usage.bombs_used, 0)::integer,
    COALESCE(state.bombs_available, 0)::integer,
    COALESCE(state.burned_tokens, 0)::integer,
    COALESCE(state.time_over_cap_seconds, 0)::integer,
    COALESCE(state.tokens_available, 0)::integer,
    state.token_next_in_seconds::integer
  FROM caller
  JOIN state
    ON state.player_id = caller.player_id
  CROSS JOIN config
  CROSS JOIN max_tokens
  LEFT JOIN battle_usage
    ON battle_usage.player_id = caller.player_id;
END;
$_$;

ALTER FUNCTION public.get_command_center_self_token_usage_v1(p_season text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_core_compositions(p_guild_code text, p_side text DEFAULT 'offense'::text, p_min_core_size integer DEFAULT 3, p_max_core_size integer DEFAULT 5, p_min_uses integer DEFAULT 5, p_limit integer DEFAULT 20, p_season_count integer DEFAULT 4) RETURNS TABLE(core_id text, core_heroes jsonb, core_size integer, total_uses bigint, wins bigint, win_rate numeric, flex_options jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min_season INT;
BEGIN
  SELECT MAX(war_season) - p_season_count + 1 INTO v_min_season
  FROM guild_war_matches
  WHERE guild_code = p_guild_code;

  IF v_min_season IS NULL THEN
    v_min_season := 0;
  END IF;

  RETURN QUERY
  WITH battle_teams AS (
    SELECT
      b.id AS battle_id,
      -- Carry the capture verdict instead of the raw Loki flag. Note this is
      -- always computed from b.defender_units_json regardless of p_side: on
      -- defence rows those are OUR units, and "captured" still means the
      -- attacker took the zone.
      war_zone_captured(b.attempt_result, b.defender_units_json) AS is_capture,
      CASE WHEN p_side = 'offense'
        THEN b.attacker_units_json
        ELSE b.defender_units_json
      END AS units_json
    FROM guild_war_battles b
    JOIN guild_war_matches m ON m.war_id = b.war_id AND m.guild_code = b.guild_code
    WHERE b.guild_code = p_guild_code
      AND CASE WHEN p_side = 'offense'
        THEN b.is_guild_member = TRUE
        ELSE b.is_guild_member = FALSE
      END
      AND m.war_season >= v_min_season
      AND CASE WHEN p_side = 'offense'
        THEN b.attacker_units_json IS NOT NULL
        ELSE b.defender_units_json IS NOT NULL
      END
  ),
  hero_arrays AS (
    SELECT
      bt.battle_id,
      bt.is_capture,
      ARRAY_AGG(DISTINCT COALESCE(h->>'heroKey', h->>'unitId') ORDER BY COALESCE(h->>'heroKey', h->>'unitId')) AS hero_keys
    FROM battle_teams bt,
    LATERAL jsonb_array_elements(bt.units_json) AS h
    WHERE COALESCE(h->>'heroKey', h->>'unitId') IS NOT NULL
    GROUP BY bt.battle_id, bt.is_capture
  ),
  pair_stats AS (
    SELECT
      ha.hero_keys[i] AS h1,
      ha.hero_keys[j] AS h2,
      COUNT(*) AS pair_uses,
      COUNT(*) FILTER (WHERE
        CASE WHEN p_side = 'offense' THEN ha.is_capture ELSE NOT ha.is_capture END
      ) AS pair_wins
    FROM hero_arrays ha,
    LATERAL generate_series(1, array_length(ha.hero_keys, 1) - 1) AS i,
    LATERAL generate_series(i + 1, array_length(ha.hero_keys, 1)) AS j
    WHERE array_length(ha.hero_keys, 1) >= 2
    GROUP BY ha.hero_keys[i], ha.hero_keys[j]
    HAVING COUNT(*) >= p_min_uses
  ),
  top_pairs AS (
    SELECT
      ps.h1,
      ps.h2,
      ps.pair_uses,
      ps.pair_wins,
      ROUND((ps.pair_wins::NUMERIC / ps.pair_uses) * 100, 1) AS pair_win_rate
    FROM pair_stats ps
    ORDER BY ps.pair_uses DESC
    LIMIT 50
  ),
  core_with_flex AS (
    SELECT
      tp.h1,
      tp.h2,
      tp.pair_uses,
      tp.pair_wins,
      tp.pair_win_rate,
      (
        SELECT jsonb_agg(flex_row ORDER BY flex_row->>'uses' DESC)
        FROM (
          SELECT jsonb_build_object(
            'heroKey', h_key,
            'uses', COUNT(*)::TEXT,
            'frequency', ROUND((COUNT(*)::NUMERIC / tp.pair_uses) * 100, 1)::TEXT,
            'winRate', ROUND((COUNT(*) FILTER (WHERE
              CASE WHEN p_side = 'offense' THEN ha.is_capture ELSE NOT ha.is_capture END
            )::NUMERIC / NULLIF(COUNT(*), 0)) * 100, 1)::TEXT
          ) AS flex_row
          FROM hero_arrays ha,
          LATERAL UNNEST(ha.hero_keys) AS h_key
          WHERE tp.h1 = ANY(ha.hero_keys)
            AND tp.h2 = ANY(ha.hero_keys)
            AND h_key != tp.h1
            AND h_key != tp.h2
          GROUP BY h_key
          HAVING COUNT(*) >= 3
          ORDER BY COUNT(*) DESC
          LIMIT 5
        ) AS flex_heroes
      ) AS flex_options
    FROM top_pairs tp
  )
  SELECT
    md5(cwf.h1 || '-' || cwf.h2) AS core_id,
    jsonb_build_array(cwf.h1, cwf.h2) AS core_heroes,
    2 AS core_size,
    cwf.pair_uses AS total_uses,
    cwf.pair_wins AS wins,
    cwf.pair_win_rate AS win_rate,
    COALESCE(cwf.flex_options, '[]'::jsonb) AS flex_options
  FROM core_with_flex cwf
  WHERE cwf.pair_uses >= p_min_uses
  ORDER BY cwf.pair_uses DESC
  LIMIT p_limit;
END;
$$;

ALTER FUNCTION public.get_core_compositions(p_guild_code text, p_side text, p_min_core_size integer, p_max_core_size integer, p_min_uses integer, p_limit integer, p_season_count integer) OWNER TO postgres;

CREATE FUNCTION public.get_cron_secret() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  secret TEXT;
BEGIN
  secret := current_setting('app.settings.cron_secret', true);

  IF secret IS NULL OR secret = '' THEN
    RAISE WARNING 'Cron secret not configured. Set via: ALTER DATABASE postgres SET app.settings.cron_secret = ''your-secret'';';
    RETURN NULL;
  END IF;

  RETURN secret;
END;
$$;

ALTER FUNCTION public.get_cron_secret() OWNER TO postgres;

CREATE FUNCTION public.get_current_boss_status(p_guild_code text, p_season text) RETURNS TABLE(boss_name text, rarity text, set integer, encounter_id integer, max_hp numeric, remaining_hp numeric, loop_index integer, completed_on timestamp with time zone, lifecycle_state text, warded boolean, alive_primes integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH guild_rows AS (
    -- All battle/bomb rows for the guild+season — the WI-2650 base WHERE,
    -- hoisted into one CTE so the omitted-kill inference (b) can see rows
    -- outside the anchor scope (e.g. the next stage's first hits).
    SELECT
      "Name" AS row_name,
      rarity,
      "set",
      COALESCE("encounterId", 0) AS encounter_id,
      "maxHp" AS raw_max_hp,
      "remainingHp" AS raw_remaining_hp,
      COALESCE("loopIndex", 0) AS loop0,
      COALESCE("completedOn", "timestamp", "startedOn") AS ts
    FROM "EOT_GR_data"
    WHERE "Guild" = p_guild_code
      AND "Season" = p_season
      AND "damageType" IN ('Battle', 'Bomb')
      AND "Name" IS NOT NULL
  ),
  stage_anchor AS (
    -- Active stage = (rarity, set, loop) of the newest battle/bomb row across
    -- ALL encounters (WI-2590, unchanged): identical to a main-row anchor
    -- while a stage is in progress; re-anchors as soon as the next stage is
    -- engaged, so orphaned primes from a finished stage cannot occupy the
    -- prime slots.
    SELECT
      rarity AS a_rarity,
      "set" AS a_set,
      loop0 AS a_loop
    FROM guild_rows
    ORDER BY ts DESC NULLS LAST
    LIMIT 1
  ),
  scoped AS (
    -- Main (encounter 0): keep the global-latest row (the current main).
    -- Primes (encounter 1, 2): only rows belonging to the SAME stage + loop
    -- as the newest activity. (WI-2590, unchanged.)
    SELECT g.*
    FROM guild_rows g
    LEFT JOIN stage_anchor a ON TRUE
    WHERE g.encounter_id = 0
      OR (
        a.a_set IS NOT NULL
        AND g.rarity IS NOT DISTINCT FROM a.a_rarity
        AND g."set" IS NOT DISTINCT FROM a.a_set
        AND g.loop0 = a.a_loop
      )
  ),
  latest AS (
    SELECT
      row_name AS boss_name,
      rarity,
      "set",
      encounter_id,
      NULLIF(raw_max_hp, 0) AS max_hp,
      NULLIF(raw_remaining_hp, 0) AS remaining_hp,
      NULLIF(loop0, 0) AS loop_index,
      ts AS completed_on,
      -- Raw stage tuple carried for the (b) inference comparison.
      rarity AS stage_rarity,
      "set" AS stage_set,
      loop0 AS stage_loop,
      -- (a) WI-2670: a kill row ANYWHERE in this encounter's stage counts —
      -- not just the newest row.
      bool_or(raw_remaining_hp IS NOT NULL AND raw_remaining_hp <= 0) OVER (
        PARTITION BY encounter_id, rarity, "set", loop0
      ) AS stage_kill_seen,
      row_number() OVER (
        PARTITION BY encounter_id
        ORDER BY ts DESC NULLS LAST
      ) AS rn
    FROM scoped
  ),
  current_rows AS (
    SELECT
      l.boss_name,
      l.rarity,
      l."set",
      l.encounter_id,
      l.max_hp,
      l.remaining_hp,
      l.loop_index,
      l.completed_on,
      (
        -- (a) kill row seen in this encounter's stage.
        l.stage_kill_seen
        OR (
          -- (b) a strictly LATER stage has been engaged: any battle/bomb row
          -- in a different (rarity, set, loop) tuple newer than this
          -- encounter's newest row. Only rows with a real HP pool can be
          -- inferred defeated ('upcoming' stays 'upcoming').
          l.max_hp IS NOT NULL AND l.max_hp > 0
          AND EXISTS (
            SELECT 1
            FROM guild_rows n
            WHERE (n.rarity, n."set", n.loop0)
                  IS DISTINCT FROM (l.stage_rarity, l.stage_set, l.stage_loop)
              AND n.ts > l.completed_on
          )
        )
      ) AS is_defeated
    FROM latest l
    WHERE l.rn = 1
  ),
  decorated AS (
    SELECT
      cr.*,
      (cr.max_hp IS NOT NULL AND cr.max_hp > 0 AND NOT cr.is_defeated)
        AS is_active
    FROM current_rows cr
  ),
  prime_counts AS (
    SELECT count(*)::integer AS alive_primes
    FROM decorated
    WHERE encounter_id IN (1, 2) AND is_active
  )
  SELECT
    d.boss_name,
    d.rarity,
    d."set",
    d.encounter_id,
    d.max_hp,
    d.remaining_hp,
    d.loop_index,
    d.completed_on,
    CASE
      WHEN d.is_defeated THEN 'defeated'
      WHEN d.encounter_id = 0 AND pc.alive_primes > 0 AND d.is_active THEN 'warded'
      WHEN d.is_active THEN 'active'
      ELSE 'upcoming'
    END::text AS lifecycle_state,
    (d.encounter_id = 0 AND pc.alive_primes > 0 AND NOT d.is_defeated) AS warded,
    pc.alive_primes
  FROM decorated d
  CROSS JOIN prime_counts pc
  ORDER BY d.encounter_id;
$$;

