    AS $$
  SELECT MAX(season_num)::text
  FROM "EOT_GR_data"
  WHERE season_num IS NOT NULL;
$$;

ALTER FUNCTION public.get_current_season() OWNER TO postgres;

CREATE FUNCTION public.get_current_war_status(p_guild_code text) RETURNS TABLE(war_id text, war_status text, opponent_name text, guild_score integer, opponent_score integer, war_phase text, time_remaining interval, players_participated integer, total_tokens_used integer)
    LANGUAGE sql STABLE
    AS $$
WITH current_war AS (
  SELECT *
  FROM guild_war_matches
  WHERE guild_code = p_guild_code
  ORDER BY
    CASE WHEN war_status = 'active' THEN 0 ELSE 1 END,
    war_start_date DESC NULLS LAST,
    updated_at DESC NULLS LAST
  LIMIT 1
),
battle_rollup AS (
  SELECT
    COUNT(*)::INTEGER AS total_tokens_used,
    COUNT(DISTINCT attacker_player_id)::INTEGER AS players_participated
  FROM guild_war_battles
  WHERE guild_code = p_guild_code
    AND war_id = (SELECT war_id FROM current_war)
)
SELECT
  c.war_id,
  c.war_status,
  c.opponent_guild_name AS opponent_name,
  c.guild_score,
  c.opponent_score,
  CASE WHEN c.war_status = 'active' THEN 'active' ELSE c.war_status END AS war_phase,
  CASE
    WHEN c.war_end_date IS NOT NULL AND c.war_status = 'active' THEN c.war_end_date - NOW()
    ELSE NULL
  END AS time_remaining,
  COALESCE(b.players_participated, 0) AS players_participated,
  COALESCE(b.total_tokens_used, 0) AS total_tokens_used
FROM current_war c
LEFT JOIN battle_rollup b ON TRUE;
$$;

ALTER FUNCTION public.get_current_war_status(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_damage_by_boss_loop(p_guild_code text, p_season text) RETURNS TABLE(loop_index integer, boss_display_name text, avg_damage numeric, max_damage numeric, total_damage bigint, hit_count integer, start_time timestamp with time zone, end_time timestamp with time zone, is_prime boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH boss_data AS (
    SELECT
      d."loopIndex",
      d."Name",
      d."damageDealt",
      d."timestamp",
      d."startedOn",
      d."completedOn",
      d.rarity,
      d.set,
      d."encounterId",
      CASE
        WHEN d.rarity = 'Mythic' THEN 'M' || (COALESCE(d.set, 0) + 1)::TEXT
        ELSE 'L' || (COALESCE(d.set, 0) + 1)::TEXT
      END || ' ' || d."Name" AS display_name,
      (d."encounterId" != 0) AS is_prime_enemy
    FROM "EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND d.rarity IN ('Legendary', 'Mythic')
      AND d."loopIndex" IS NOT NULL
  )
  SELECT
    bd."loopIndex"::INTEGER AS loop_index,
    bd.display_name AS boss_display_name,
    ROUND(AVG(bd."damageDealt") FILTER (WHERE bd."damageDealt" > 0), 0) AS avg_damage,
    MAX(bd."damageDealt") FILTER (WHERE bd."damageDealt" > 0)::NUMERIC AS max_damage,
    SUM(bd."damageDealt") FILTER (WHERE bd."damageDealt" > 0)::BIGINT AS total_damage,
    COUNT(*)::INTEGER AS hit_count,
    MIN(COALESCE(bd."startedOn", bd."timestamp")) AS start_time,
    MAX(COALESCE(bd."completedOn", bd."timestamp")) AS end_time,
    bd.is_prime_enemy AS is_prime
  FROM boss_data bd
  GROUP BY bd."loopIndex", bd.display_name, bd.is_prime_enemy
  ORDER BY bd."loopIndex", bd.display_name;
END;
$$;

ALTER FUNCTION public.get_damage_by_boss_loop(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_discord_channel_mapping(p_discord_guild_id text, p_discord_channel_id text) RETURNS TABLE(game_guild_code text, cluster_code text, default_for_tokens boolean, default_for_notifications boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        dcg.game_guild_code,
        dcg.cluster_code,
        dcg.default_for_tokens,
        dcg.default_for_notifications,
        dcg.created_at
    FROM public.discord_channel_guilds dcg
    WHERE dcg.discord_channel_id = p_discord_channel_id
      AND dcg.discord_guild_id = p_discord_guild_id;
END;
$$;

