CREATE FUNCTION public.get_discord_guild_mapping(p_discord_guild_id text) RETURNS TABLE(game_guild_code text, cluster_code text, is_active boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        dsg.game_guild_code,
        dsg.cluster_code,
        dsg.is_active
    FROM public.discord_server_guilds dsg
    WHERE dsg.discord_guild_id = p_discord_guild_id
      AND dsg.is_active = true
    ORDER BY dsg.linked_at ASC
    LIMIT 1;
END;
$$;

ALTER FUNCTION public.get_discord_guild_mapping(p_discord_guild_id text) OWNER TO postgres;

CREATE FUNCTION public.get_discord_guild_mappings_all(p_discord_guild_id text) RETURNS TABLE(game_guild_code text, cluster_code text, display_name text, is_active boolean, linked_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        dsg.game_guild_code,
        dsg.cluster_code,
        gc.display_name,
        dsg.is_active,
        dsg.linked_at
    FROM public.discord_server_guilds dsg
    JOIN public.guild_config gc ON dsg.game_guild_code = gc.guild_code
    WHERE dsg.discord_guild_id = p_discord_guild_id
      AND dsg.is_active = true
    ORDER BY dsg.linked_at ASC;
END;
$$;

