CREATE FUNCTION public.get_distinct_seasons() RETURNS TABLE(season text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT DISTINCT "EOT_GR_data"."Season"
  FROM "EOT_GR_data"
  WHERE "EOT_GR_data"."Season" IS NOT NULL
  ORDER BY "EOT_GR_data"."Season" DESC;
END;
$$;

ALTER FUNCTION public.get_distinct_seasons() OWNER TO postgres;

CREATE FUNCTION public.get_distinct_seasons_for_guild(p_guild text, p_cluster_code text DEFAULT NULL::text) RETURNS text[]
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  SELECT COALESCE(array_agg(s ORDER BY s::int DESC), ARRAY[]::text[])
  FROM (
    SELECT DISTINCT "Season" AS s
    FROM public."EOT_GR_data"
    WHERE "Season" ~ '^\d+$'
      AND "Guild" = p_guild
      AND (p_cluster_code IS NULL OR cluster_code = p_cluster_code)
  ) AS sub;
$_$;

ALTER FUNCTION public.get_distinct_seasons_for_guild(p_guild text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_duplicate_display_labels(p_guild_code text DEFAULT NULL::text) RETURNS TABLE(player_id text, display_name text, original_display_name text, previous_name text, friendly_label text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
  WITH request_context AS MATERIALIZED (
    SELECT
      COALESCE(
        NULLIF(NULLIF(current_setting('role', true), ''), 'none'),
        NULLIF(session_user, '')
      ) AS request_role,
      (SELECT auth.uid()) AS caller_uid
  ),
  caller_guilds AS MATERIALIZED (
    SELECT pm.guild_code
    FROM public.player_mapping pm
    CROSS JOIN request_context rc
    WHERE rc.request_role = 'authenticated'
      AND rc.caller_uid IS NOT NULL
      AND pm.user_id = rc.caller_uid
      AND pm.is_current
      AND pm.guild_code IS NOT NULL
  ),
  dup AS (
    SELECT
      pm.player_id,
      pm.guild_code,
      pm.display_name,
      pm.original_display_name AS base
    FROM public.player_mapping pm
    CROSS JOIN request_context rc
    WHERE pm.is_current
      AND pm.has_duplicate_name
      AND pm.original_display_name IS NOT NULL
      AND btrim(pm.original_display_name) <> ''
      AND (p_guild_code IS NULL OR pm.guild_code = p_guild_code)
      AND (
        rc.request_role = 'service_role'
        OR (
          rc.request_role = 'authenticated'
          AND pm.guild_code IN (SELECT cg.guild_code FROM caller_guilds cg)
        )
      )
  ),
  resolved AS (
    SELECT
      d.player_id,
      d.guild_code,
      d.display_name,
      d.base,
      (
        SELECT e."displayName"
        FROM public."EOT_GR_data" e
        WHERE e."userId" = d.player_id
          AND e."displayName" IS NOT NULL
          AND btrim(e."displayName") <> ''
          AND e."displayName" <> d.base
          AND NOT starts_with(e."displayName", d.base || ' (')
          AND NOT starts_with(e."displayName", 'Player#')
          AND e."displayName" !~ ' \([^()]*_[0-9]+\)$'
        ORDER BY COALESCE(e."completedOn", e."startedOn", e."timestamp") DESC NULLS LAST
        LIMIT 1
      ) AS previous_name
    FROM dup d
  ),
  counted AS (
    SELECT
      r.*,
      count(*) FILTER (WHERE r.previous_name IS NOT NULL)
        OVER (PARTITION BY r.guild_code, r.base, r.previous_name) AS same_prev_count
    FROM resolved r
  )
  SELECT
    c.player_id,
    c.display_name,
    c.base AS original_display_name,
    c.previous_name,
    c.base || ' (' ||
      CASE
        WHEN c.previous_name IS NOT NULL AND c.same_prev_count = 1
          THEN c.previous_name
        ELSE upper(substr(c.player_id, 1, 6))
      END
    || ')' AS friendly_label
  FROM counted c;
$_$;

ALTER FUNCTION public.get_duplicate_display_labels(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_effective_token_notification_preference(p_guild_code text, p_player_id text, p_channel text) RETURNS TABLE(preference_id uuid, enabled boolean, notify_on_capped boolean, notify_on_near_cap boolean, near_cap_threshold_seconds integer, dedupe_window_seconds integer, discord_channel_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pref public.token_notification_preferences%rowtype;
  v_channel text := lower(coalesce(p_channel, 'discord'));
  v_discord_default_enabled boolean := false;
begin
  if v_channel not in ('discord', 'in_app', 'push', 'sms') then
    raise exception 'Unsupported token notification channel: %', p_channel;
  end if;

  select *
  into v_pref
  from public.token_notification_preferences
  where guild_code = p_guild_code
    and player_id = p_player_id
    and channel = v_channel
  limit 1;

  if found then
    return query
    select
      v_pref.id,
      v_pref.enabled,
      v_pref.notify_on_capped,
      v_pref.notify_on_near_cap,
      v_pref.near_cap_threshold_seconds,
      v_pref.dedupe_window_seconds,
      v_pref.discord_channel_id;
    return;
  end if;

  select *
  into v_pref
  from public.token_notification_preferences
  where guild_code = p_guild_code
    and player_id is null
    and channel = v_channel
  limit 1;

  if found then
    return query
    select
      v_pref.id,
      v_pref.enabled,
      v_pref.notify_on_capped,
      v_pref.notify_on_near_cap,
      v_pref.near_cap_threshold_seconds,
      v_pref.dedupe_window_seconds,
      v_pref.discord_channel_id;
    return;
  end if;

  if v_channel = 'discord' then
    select exists (
      select 1
      from public.webhook_config wc
      where wc.guild_code = p_guild_code
        and wc.webhook_type = 'token_cap_notification'
        and wc.enabled = true
        and wc.webhook_url is not null
        and trim(wc.webhook_url) <> ''
    )
    into v_discord_default_enabled;

    return query
    select
      null::uuid,
      v_discord_default_enabled,
      true,
      true,
      7200,
      21600,
      null::text;
    return;
  end if;

  return query
  select
    null::uuid,
    true,
    true,
    true,
    7200,
    21600,
    null::text;
end;
$$;

ALTER FUNCTION public.get_effective_token_notification_preference(p_guild_code text, p_player_id text, p_channel text) OWNER TO postgres;

CREATE FUNCTION public.get_features_with_access(p_user_id uuid) RETURNS TABLE(feature_key text, display_name text, description text, release_stage text, icon text, route text, value_proposition text, sort_order integer, has_access boolean, access_reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH mapping_context AS MATERIALIZED (
    SELECT
      coalesce(max(pm.is_app_admin::integer), 0) = 1 AS is_app_admin
    FROM public.player_mapping AS pm
    WHERE pm.user_id = p_user_id
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
  ),
  grant_context AS MATERIALIZED (
    SELECT
      count(fag.user_id) FILTER (
        WHERE fag.access_level = 'alpha_tester'
          AND (fag.expires_at IS NULL OR fag.expires_at > now())
      ) > 0 AS is_alpha,
      count(fag.user_id) FILTER (
        WHERE fag.access_level = 'beta_tester'
          AND (fag.expires_at IS NULL OR fag.expires_at > now())
      ) > 0 AS is_beta
    FROM public.feature_access_grants AS fag
    WHERE fag.user_id = p_user_id
  )
  SELECT
    fr.feature_key,
    fr.display_name,
    fr.description,
    fr.release_stage,
    fr.icon,
    fr.route,
    fr.value_proposition,
    fr.sort_order,
    CASE fr.release_stage
      WHEN 'public' THEN true
      WHEN 'alpha' THEN coalesce(
        mapping_context.is_app_admin OR grant_context.is_alpha,
        false
      )
      WHEN 'beta' THEN coalesce(
        mapping_context.is_app_admin
          OR grant_context.is_alpha
          OR grant_context.is_beta,
        false
      )
      ELSE false
    END,
    CASE
      WHEN fr.release_stage = 'public' THEN 'public_feature'
      WHEN mapping_context.is_app_admin THEN 'admin'
      WHEN grant_context.is_alpha THEN 'alpha_tester'
      WHEN grant_context.is_beta THEN 'beta_tester'
      ELSE fr.release_stage || '_only'
    END
  FROM public.feature_releases AS fr
  CROSS JOIN mapping_context
  CROSS JOIN grant_context
  ORDER BY fr.feature_key;
END;
$$;

ALTER FUNCTION public.get_features_with_access(p_user_id uuid) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_five_season_averages(p_guild_code text, p_current_season integer) RETURNS TABLE(boss_name text, "Season" text, avg_damage numeric, battle_count bigint, rarity text, tier integer, encounter_id integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH season_range AS (
    SELECT generate_series(
      GREATEST(p_current_season - 4, 1),
      p_current_season
    )::TEXT as season_num
  ),
  boss_stats AS (
    SELECT
      e."Name" as boss_name,
      e."Season",
      e."rarity",
      e."tier",
      e."encounterId",
      AVG(e."damageDealt") as avg_damage,
      COUNT(*) as battle_count
    FROM "EOT_GR_data" e
    JOIN season_range sr ON e."Season" = sr.season_num
    WHERE e."Guild" = p_guild_code
      AND e."damageType" = 'Battle'
      AND e."damageDealt" > 0
      AND e."rarity" IN ('Legendary', 'Mythic')
    GROUP BY e."Name", e."Season", e."rarity", e."tier", e."encounterId"
  )
  SELECT
    bs.boss_name::TEXT,
    bs."Season"::TEXT,
    bs.avg_damage,
    bs.battle_count,
    bs.rarity::TEXT,
    bs.tier,
    bs.encounterId
  FROM boss_stats bs
  ORDER BY bs."Season" DESC, bs.boss_name;
END;
$$;

ALTER FUNCTION public.get_five_season_averages(p_guild_code text, p_current_season integer) OWNER TO postgres;

CREATE FUNCTION public.get_flexible_assignment_stats(guild_code_param text, season_param text DEFAULT NULL::text) RETURNS TABLE(boss_name text, total_tokens_assigned integer, players_assigned integer, max_tokens_per_boss integer, avg_tokens_per_player numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_season TEXT;
BEGIN
  -- Get current season if not provided
  IF season_param IS NULL THEN
    SELECT COALESCE(MAX("Season"), 'current') INTO current_season
    FROM "EOT_GR_data"
    WHERE "Guild" = guild_code_param;
  ELSE
    current_season := season_param;
  END IF;

  RETURN QUERY
  WITH flexible_assignments AS (
    -- Extract boss names and token counts from JSONB token_allocations
    SELECT
      usa.display_name,
      jsonb_each_text(usa.token_allocations) AS boss_token_pair
    FROM upcoming_season_assignments usa
    WHERE usa.guild_code = guild_code_param
      AND usa.season_number = current_season
      AND usa.uses_flexible_tokens = true
      AND usa.token_allocations IS NOT NULL
      AND usa.token_allocations != '{}'
  ),
  boss_token_data AS (
    SELECT
      fa.display_name,
      (fa.boss_token_pair).key AS boss_name,
      CAST((fa.boss_token_pair).value AS INTEGER) AS tokens_assigned
    FROM flexible_assignments fa
    WHERE CAST((fa.boss_token_pair).value AS INTEGER) > 0
  )
  SELECT
    btd.boss_name,
    SUM(btd.tokens_assigned)::INTEGER AS total_tokens_assigned,
    COUNT(DISTINCT btd.display_name)::INTEGER AS players_assigned,
    MAX(btd.tokens_assigned)::INTEGER AS max_tokens_per_boss,
    AVG(btd.tokens_assigned)::NUMERIC AS avg_tokens_per_player
  FROM boss_token_data btd
  GROUP BY btd.boss_name
  ORDER BY total_tokens_assigned DESC;
END;
$$;

ALTER FUNCTION public.get_flexible_assignment_stats(guild_code_param text, season_param text) OWNER TO postgres;

CREATE FUNCTION public.get_flexible_token_coverage(guild_code_param text, season_param text DEFAULT NULL::text) RETURNS TABLE(boss_name text, boss_level text, estimated_hp bigint, estimated_tokens_needed integer, tokens_assigned integer, coverage_percentage numeric, players_assigned integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_season TEXT;
  guild_avg_damage NUMERIC := 0;
BEGIN
  -- Get current season if not provided
  IF season_param IS NULL THEN
    SELECT COALESCE(MAX("Season"), 'current') INTO current_season
    FROM "EOT_GR_data"
    WHERE "Guild" = guild_code_param;
  ELSE
    current_season := season_param;
  END IF;

  -- Get guild average damage from recent data
  SELECT AVG("damageDealt") INTO guild_avg_damage
  FROM "EOT_GR_data"
  WHERE "Guild" = guild_code_param
    AND "damageType" = 'Battle'
    AND "damageDealt" > 0
    AND "remainingHp" > 0  -- Exclude sweeps
  LIMIT 1000;  -- Use recent data sample

  -- Default to reasonable fallback if no data
  IF guild_avg_damage IS NULL OR guild_avg_damage = 0 THEN
    guild_avg_damage := 500000;  -- 500k default
  END IF;

  RETURN QUERY
  WITH boss_hp_data AS (
    -- Get boss HP estimates from recent battle data
    SELECT
      e."Name" as boss_name,
      CASE
        WHEN e.rarity = 'Mythic' THEN 'M' || (e.set + 1)
        ELSE 'L' || (e.set + 1)
      END as boss_level,
      MAX(e."damageDealt" + e."remainingHp") as estimated_hp
    FROM "EOT_GR_data" e
    WHERE e."Guild" = guild_code_param
      AND e."Season" = current_season
      AND e."damageType" = 'Battle'
      AND e."encounterId" = 0  -- Main bosses only
      AND e.rarity IN ('Legendary', 'Mythic')
    GROUP BY e."Name", e.set
  ),
  flexible_token_stats AS (
    SELECT * FROM get_flexible_assignment_stats(guild_code_param, current_season)
  )
  SELECT
    stats.boss_name,
    COALESCE(hp.boss_level, 'Unknown') as boss_level,
    COALESCE(hp.estimated_hp, 0) as estimated_hp,
    CASE
      WHEN COALESCE(hp.estimated_hp, 0) > 0 AND guild_avg_damage > 0
      THEN CEIL(COALESCE(hp.estimated_hp, 0)::NUMERIC / guild_avg_damage)::INTEGER
      ELSE 10  -- Default estimate
    END as estimated_tokens_needed,
    COALESCE(stats.total_tokens_assigned, 0) as tokens_assigned,
    CASE
      WHEN COALESCE(hp.estimated_hp, 0) > 0 AND guild_avg_damage > 0
      THEN (COALESCE(stats.total_tokens_assigned, 0)::NUMERIC / CEIL(COALESCE(hp.estimated_hp, 0)::NUMERIC / guild_avg_damage)) * 100
      ELSE 0
    END as coverage_percentage,
    COALESCE(stats.players_assigned, 0) as players_assigned
  FROM flexible_token_stats stats
  LEFT JOIN boss_hp_data hp ON hp.boss_name = stats.boss_name
  ORDER BY estimated_tokens_needed DESC;
END;
$$;

ALTER FUNCTION public.get_flexible_token_coverage(guild_code_param text, season_param text) OWNER TO postgres;

