CREATE FUNCTION public.get_guild_api_key_coverage(p_guild_code text) RETURNS TABLE(guild_code text, total_players bigint, active_players bigint, players_claimed bigint, players_with_api_key bigint, coverage_percentage numeric, guild_api_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_guild_code IS NULL OR length(trim(p_guild_code)) = 0 THEN
    RAISE EXCEPTION 'p_guild_code is required'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.player_mapping pm
      WHERE pm.user_id = (SELECT auth.uid())
        AND pm.is_current = true
        AND pm.guild_code = p_guild_code
    ) THEN
      RAISE EXCEPTION 'Access denied: guild membership required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    cov.guild_code::text,
    cov.total_players::bigint,
    cov.active_players::bigint,
    cov.players_claimed::bigint,
    cov.players_with_api_key::bigint,
    cov.coverage_percentage::numeric,
    cov.guild_api_status::text
  FROM public.api_key_coverage cov
  JOIN public.guild_config gc ON gc.guild_code = cov.guild_code
  WHERE cov.guild_code = p_guild_code
    AND gc.enabled = true;
END;
$$;

ALTER FUNCTION public.get_guild_api_key_coverage(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_api_key_info(p_guild_code text) RETURNS TABLE(guild_code text, api_owner text, api_key_is_valid boolean, api_key_last_validated timestamp with time zone, has_api_key boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT gc.guild_code, gc."API_Owner", gc.api_key_is_valid,
         gc.api_key_last_validated, (gc.api_key_encrypted IS NOT NULL)
  FROM public.guild_config gc
  WHERE gc.guild_code = p_guild_code
    AND (
      COALESCE((SELECT auth.jwt() ->> 'role'), '') = 'service_role'
      OR EXISTS (
        SELECT 1 FROM public.player_mapping pm
        WHERE pm.user_id = (SELECT auth.uid())
          AND pm.is_current = true
          AND pm.guild_code = gc.guild_code
          AND lower(pm.role::text) IN ('officer','leader'))
      OR public._pm_caller_is_app_admin()
    );
$$;

ALTER FUNCTION public.get_guild_api_key_info(p_guild_code text) OWNER TO postgres;

