CREATE FUNCTION public.get_guild_battle_counts() RETURNS TABLE(guild_code text, battle_count bigint, current_season_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    "Guild" as guild_code,
    COUNT(*)::BIGINT as battle_count,
    -- LEX-FIX 2026-05-07: was (SELECT MAX("Season") FROM "EOT_GR_data") -> '99' at S100.
    COUNT(CASE WHEN "Season" = (SELECT MAX(season_num)::text FROM "EOT_GR_data") THEN 1 END)::BIGINT as current_season_count
  FROM "EOT_GR_data"
  WHERE "damageType" = 'Battle'
    AND "damageDealt" > 0
  GROUP BY "Guild";
$$;

