CREATE FUNCTION public.get_guild_bombs_available(p_guild_code text) RETURNS TABLE(bombs_available integer, roster_size integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH roster AS MATERIALIZED (
    SELECT DISTINCT pm.player_id
    FROM public.player_mapping AS pm
    WHERE pm.guild_code = p_guild_code
      AND pm.is_active IS TRUE
      AND pm.is_current IS TRUE
      AND pm.player_id IS NOT NULL
  ),
  recent_bombs AS MATERIALIZED (
    SELECT DISTINCT e."userId" AS player_id
    FROM public."EOT_GR_data" AS e
    WHERE e."Guild" = p_guild_code
      AND e."damageType" = 'Bomb'
      AND e."userId" IS NOT NULL
      AND coalesce(e."startedOn", e."completedOn", e.timestamp)
        > statement_timestamp() - interval '64800 seconds'
  )
  SELECT
    count(*) FILTER (
      WHERE recent_bombs.player_id IS NULL
    )::integer,
    count(*)::integer
  FROM roster
  LEFT JOIN recent_bombs
    ON recent_bombs.player_id = roster.player_id;
END;
$$;

ALTER FUNCTION public.get_guild_bombs_available(p_guild_code text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_guild_boss_averages(p_guild_code text, p_season text) RETURNS TABLE(boss_name text, encounter_id integer, set_num integer, rarity text, avg_damage numeric, hit_count bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    "Name" as boss_name,
    "encounterId" as encounter_id,
    "set" as set_num,
    "rarity" as rarity,
    COALESCE(AVG("damageDealt"), 0)::numeric as avg_damage,
    COUNT(*)::bigint as hit_count
  FROM "EOT_GR_data"
  WHERE "Guild" = p_guild_code
    AND "Season" = p_season
    AND "damageDealt" > 0
  GROUP BY "Name", "encounterId", "set", "rarity"
$$;

ALTER FUNCTION public.get_guild_boss_averages(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_boss_averages_batch(p_guild_code text, p_seasons text[]) RETURNS TABLE(season text, boss_key text, avg_damage numeric, total_damage numeric, battle_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    e."Season"::text AS season,
    e."Name" || '_' || e.rarity || '_' || e.set AS boss_key,
    ROUND(AVG(e."damageDealt")::numeric, 2) AS avg_damage,
    ROUND(SUM(e."damageDealt")::numeric, 2) AS total_damage,
    COUNT(*)::integer AS battle_count
  FROM "EOT_GR_data" e
  WHERE e."Guild" = p_guild_code
    AND e."Season" = ANY(p_seasons)
    AND e."damageType" = 'Battle'
    AND e.rarity IN ('Legendary', 'Mythic')
    AND e."damageDealt" > 0
    AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
  GROUP BY e."Season", e."Name", e.rarity, e.set
  ORDER BY e."Season" DESC, total_damage DESC;
$$;

ALTER FUNCTION public.get_guild_boss_averages_batch(p_guild_code text, p_seasons text[]) OWNER TO postgres;

CREATE FUNCTION public.get_guild_boss_avg_damage(p_guild_code text, p_season text, p_boss_name text, p_encounter_id integer, p_set integer, p_rarity text) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
