  FROM "EOT_GR_data"
  WHERE "Guild" = p_guild_code
    AND "Season" = p_season
    AND "Name" = p_boss_name
    AND "encounterId" = p_encounter_id
    AND "set" = p_set
    AND "rarity" = p_rarity
    AND "damageDealt" > 0
$$;

