CREATE FUNCTION public.get_guild_boss_leaderboard(p_guild_code text, p_season text DEFAULT '83'::text, p_boss_name text DEFAULT NULL::text) RETURNS TABLE("displayName" text, "Guild" text, "bossName" text, "encounterIndex" integer, "maxDamage" bigint, "battleCount" bigint, "bombsUsed" bigint, "avgDamage" numeric, "heroDetails" jsonb, "machineOfWarDetails" jsonb, categories text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.player_mapping pm
      WHERE pm.user_id = (SELECT auth.uid())
        AND pm.guild_code = p_guild_code
        AND pm.is_current = true
    ) THEN
      RAISE EXCEPTION 'Access denied: guild membership required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH boss_stats AS (
    SELECT
      d."displayName",
      d."Guild",
      d."Name" AS boss_name,
      d."encounterIndex",
      MAX(d."damageDealt") AS max_damage,
      COUNT(*) AS battle_count,
      SUM(CASE WHEN d."damageType" = 'Bomb' THEN 1 ELSE 0 END) AS bombs_used,
      -- WI-2520: displayed average is Battle-only and sweep-free (one-shots
      -- kept); max/counts stay raw.
      AVG(d."damageDealt") FILTER (
        WHERE d."damageType" = 'Battle'
          AND NOT (
            COALESCE(d."remainingHp", 0) = 0
            AND COALESCE(d."maxHp", 0) > 0
            AND d."damageDealt" < d."maxHp"
          )
      ) AS avg_damage,
      (ARRAY_AGG(d."heroDetails" ORDER BY d."damageDealt" DESC))[1] AS hero_details,
      (ARRAY_AGG(d."machineOfWarDetails" ORDER BY d."damageDealt" DESC))[1] AS mow_details
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageDealt" > 0
      AND (p_boss_name IS NULL OR d."Name" = p_boss_name)
    GROUP BY d."displayName", d."Guild", d."Name", d."encounterIndex"
  )
  SELECT
    bs."displayName"::text,
    bs."Guild"::text,
    bs.boss_name::text,
    bs."encounterIndex"::integer,
    bs.max_damage::bigint,
    bs.battle_count::bigint,
    bs.bombs_used::bigint,
    COALESCE(ROUND(bs.avg_damage::numeric, 0), 0),
    bs.hero_details::jsonb,
    bs.mow_details::jsonb,
    ARRAY[]::text[] AS categories
  FROM boss_stats bs
  ORDER BY bs.boss_name, bs."encounterIndex", bs.max_damage DESC;
END;
$$;

ALTER FUNCTION public.get_guild_boss_leaderboard(p_guild_code text, p_season text, p_boss_name text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_boss_leaderboard_v2(p_guild_code text, p_season text, p_boss_name text DEFAULT NULL::text) RETURNS TABLE(displayname text, guild text, boss_name text, encounter_index integer, total_damage bigint, battle_count bigint, avg_damage numeric, current_rank bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH player_boss_stats AS (
    SELECT
      e."userId" as player_id,
      pm.display_name as current_display_name,
      e."Guild",
      e."Name" as boss_name,
      e."encounterId",
      SUM(e."damageDealt") as total_damage,
      COUNT(*) as battle_count,
      AVG(e."damageDealt") as avg_damage
    FROM "EOT_GR_data" e
    LEFT JOIN player_mapping pm ON e."userId" = pm.player_id AND pm.is_current = true
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageDealt" > 0
      AND e."userId" IS NOT NULL
      AND (p_boss_name IS NULL OR e."Name" = p_boss_name)
    GROUP BY e."userId", pm.display_name, e."Guild", e."Name", e."encounterId"
  ),
  ranked_stats AS (
    SELECT
      pbs.*,
      ROW_NUMBER() OVER (
        PARTITION BY pbs.boss_name, pbs.encounterId
        ORDER BY pbs.total_damage DESC
      ) as current_rank
    FROM player_boss_stats pbs
  )
  SELECT
    COALESCE(rs.current_display_name, 'Unknown Player')::TEXT as displayName,
    rs.Guild::TEXT,
    rs.boss_name::TEXT,
    rs.encounterId,
    rs.total_damage,
    rs.battle_count,
    rs.avg_damage,
    rs.current_rank
  FROM ranked_stats rs
  ORDER BY rs.boss_name, rs.encounterId, rs.current_rank;
END;
$$;

ALTER FUNCTION public.get_guild_boss_leaderboard_v2(p_guild_code text, p_season text, p_boss_name text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_config_by_guild_id(p_guild_id text) RETURNS TABLE(guild_code text, guild_id text, guild_tag text, display_name text, cluster_code text, enabled boolean, onboarding_completed boolean, onboarding_source text, has_api_key boolean, claimed_by_user boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    gc.guild_code,
    gc.guild_id,
    gc.guild_tag,
    gc.display_name,
    gc.cluster_code,
    gc.enabled,
    gc.onboarding_completed,
    gc.onboarding_source,
    (gc.api_key_encrypted IS NOT NULL) AS has_api_key,
    EXISTS (
      SELECT 1 FROM player_mapping pm
      WHERE pm.guild_code = gc.guild_code
        AND pm.user_id IS NOT NULL
        AND pm.role IN ('leader', 'officer')
    ) AS claimed_by_user
  FROM guild_config gc
  WHERE gc.guild_id = p_guild_id
  LIMIT 1;
$$;

ALTER FUNCTION public.get_guild_config_by_guild_id(p_guild_id text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_historical_performance(p_guild_code text, p_season_count integer DEFAULT 10) RETURNS TABLE(season text, unique_players bigint, total_battles bigint, avg_damage_per_player numeric, total_damage bigint, veteran_players bigint)
    LANGUAGE plpgsql
    AS $_$
BEGIN
  RETURN QUERY
  WITH recent_seasons AS (
    SELECT DISTINCT "Season"
    FROM "EOT_GR_data"
    WHERE Guild = p_guild_code
      AND "Season" ~ '^\d+$'
    ORDER BY "Season"::INTEGER DESC
    LIMIT p_season_count
  ),
  season_stats AS (
    SELECT
      e."Season",
      COUNT(DISTINCT e."userId") FILTER (WHERE e."userId" IS NOT NULL) as unique_players,
      COUNT(*) as total_battles,
      SUM(e."damageDealt") as total_damage
    FROM "EOT_GR_data" e
    JOIN recent_seasons rs ON e."Season" = rs."Season"
    WHERE e."Guild" = p_guild_code
      AND e."damageDealt" > 0
    GROUP BY e."Season"
  ),
  season_veterans AS (
    SELECT
      e."Season",
      COUNT(DISTINCT e."userId") as veteran_count
    FROM "EOT_GR_data" e
    JOIN recent_seasons rs ON e."Season" = rs."Season"
    WHERE e."Guild" = p_guild_code
      AND e."damageDealt" > 0
      AND e."userId" IS NOT NULL
      AND e."userId" IN (
        SELECT DISTINCT e2."userId"
        FROM "EOT_GR_data" e2
        WHERE e2."Guild" = p_guild_code
          AND e2."damageDealt" > 0
          AND e2."Season" ~ '^\d+$'
        GROUP BY e2."userId"
        HAVING COUNT(DISTINCT e2."Season") >= 5
      )
    GROUP BY e."Season"
  )
  SELECT
    ss."Season"::TEXT,
    ss.unique_players,
    ss.total_battles,
    ROUND((ss.total_damage::NUMERIC / NULLIF(ss.unique_players, 0)), 0) as avg_damage_per_player,
    ss.total_damage,
    COALESCE(sv.veteran_count, 0) as veteran_players
  FROM season_stats ss
  LEFT JOIN season_veterans sv ON ss."Season" = sv."Season"
  ORDER BY ss."Season"::INTEGER DESC;
END;
$_$;

ALTER FUNCTION public.get_guild_historical_performance(p_guild_code text, p_season_count integer) OWNER TO postgres;

CREATE FUNCTION public.get_guild_member_counts() RETURNS TABLE(guild_code character varying, member_count bigint, officer_count bigint, leader_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pm.guild_code,
    COUNT(*) as member_count,
    COUNT(*) FILTER (WHERE pm.role = 'officer') as officer_count,
    COUNT(*) FILTER (WHERE pm.role = 'leader') as leader_count
  FROM player_mapping pm
  WHERE pm.is_current = true
  GROUP BY pm.guild_code
  ORDER BY pm.guild_code;
END;
$$;

