CREATE FUNCTION public.get_guild_members(p_guild_code text) RETURNS TABLE(user_id uuid, player_id text, display_name text, guild_code text, role text, is_current boolean, last_sync_tokens integer, last_sync_bombs integer, tacticus_username text, discord_username text, discord_user_id text, last_sync_at timestamp without time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
    SELECT
        pm.user_id, pm.player_id, pm.display_name, pm.guild_code,
        pm.role::TEXT, pm.is_current, pm.last_sync_tokens, pm.last_sync_bombs,
        pm.display_name AS tacticus_username, pm.discord_username,
        pm.discord_user_id, pm.last_sync_at
    FROM player_mapping pm
    WHERE pm.guild_code = p_guild_code
      AND pm.is_current = true
      AND (
        COALESCE((SELECT auth.jwt() ->> 'role'), '') = 'service_role'
        OR p_guild_code IN (SELECT public._pm_caller_guild_codes())
        OR p_guild_code IN (SELECT public._pm_caller_cluster_guild_codes())
        OR public._pm_caller_is_app_admin()
      )
    ORDER BY pm.display_name;
$$;

