CREATE FUNCTION public.get_guild_members_browser_safe() RETURNS TABLE(user_id uuid, is_claimed boolean, player_id text, display_name text, guild_code text, role text, is_current boolean, last_sync_tokens integer, last_sync_bombs integer, tacticus_username text, last_sync_at timestamp without time zone, has_api_key boolean, api_key_is_valid boolean, primary_boss text, secondary_boss text, assignment_notes text, officer_notes text, player_notes text, primary_team text, secondary_team text, tertiary_team text, boss_preferences json, avatar_unit_id text, player_level integer, last_login_at timestamp with time zone, last_battle_time timestamp with time zone, last_bomb_time timestamp with time zone, timezone text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_caller_count integer;
  v_caller_guild text;
  v_caller_role text;
  v_cluster_code text;
  v_guild_list text[];
  v_is_officer boolean;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  SELECT count(*)::integer,
         (array_agg(verified.guild_code ORDER BY verified.mapping_id))[1],
         (array_agg(verified.role::text ORDER BY verified.mapping_id))[1]
  INTO v_caller_count, v_caller_guild, v_caller_role
  FROM public.resolve_verified_players(ARRAY[v_user_id]) AS verified;
  IF v_caller_count <> 1 OR v_caller_guild IS NULL THEN
    RAISE EXCEPTION 'Exact current player membership is required'
      USING ERRCODE = '42501';
  END IF;
  v_is_officer := lower(coalesce(v_caller_role, '')) IN ('leader', 'officer');

  SELECT config.cluster_code INTO v_cluster_code
  FROM public.guild_config AS config
  WHERE config.guild_code = v_caller_guild;
  IF lower(coalesce(v_caller_role, '')) = 'leader'
    AND v_cluster_code IS NOT NULL
  THEN
    SELECT coalesce(array_agg(config.guild_code ORDER BY config.guild_code),
                    ARRAY[v_caller_guild])
    INTO v_guild_list
    FROM public.guild_config AS config
    WHERE config.cluster_code = v_cluster_code;
  ELSE
    v_guild_list := ARRAY[v_caller_guild];
  END IF;

  RETURN QUERY
  WITH latest_battles AS (
    SELECT raid."displayName" AS player_name,
           raid."Guild" AS member_guild_code,
           max(raid."startedOn") AS last_battle
    FROM public."EOT_GR_data" AS raid
    WHERE raid."damageType" = 'Battle'
      AND raid."Guild" = ANY(v_guild_list)
    GROUP BY raid."displayName", raid."Guild"
  ), latest_bombs AS (
    SELECT raid."displayName" AS player_name,
           raid."Guild" AS member_guild_code,
           max(raid."startedOn") AS last_bomb
    FROM public."EOT_GR_data" AS raid
    WHERE raid."damageType" = 'Bomb'
      AND raid."Guild" = ANY(v_guild_list)
    GROUP BY raid."displayName", raid."Guild"
  )
  SELECT
    CASE WHEN v_is_officer OR mapping.user_id = v_user_id
      THEN mapping.user_id ELSE NULL END,
    mapping.user_id IS NOT NULL,
    mapping.player_id::text,
    mapping.display_name::text,
    mapping.guild_code::text,
    mapping.role::text,
    mapping.is_current,
    mapping.last_sync_tokens,
    mapping.last_sync_bombs,
    mapping.display_name::text,
    mapping.last_sync_at::timestamp without time zone,
    CASE WHEN v_is_officer
      THEN mapping.tacticus_api_key_encrypted IS NOT NULL ELSE NULL END,
    CASE WHEN v_is_officer THEN mapping.api_key_is_valid ELSE NULL END,
    mapping.primary_boss::text,
    mapping.secondary_boss::text,
    mapping.assignment_notes::text,
    CASE WHEN v_is_officer THEN mapping.officer_notes::text ELSE NULL END,
    CASE WHEN v_is_officer THEN mapping.player_notes::text ELSE NULL END,
    mapping.primary_team::text,
    mapping.secondary_team::text,
    mapping.tertiary_team::text,
    mapping.boss_preferences::json,
    mapping.avatar_unit_id::text,
    mapping.player_level,
    mapping.last_active_at,
    battle.last_battle,
    bomb.last_bomb,
    mapping.timezone::text
  FROM public.player_mapping AS mapping
  LEFT JOIN latest_battles AS battle
    ON battle.player_name = mapping.display_name
   AND battle.member_guild_code = mapping.guild_code
  LEFT JOIN latest_bombs AS bomb
    ON bomb.player_name = mapping.display_name
   AND bomb.member_guild_code = mapping.guild_code
  WHERE mapping.is_current IS TRUE
    AND mapping.guild_code = ANY(v_guild_list)
  ORDER BY CASE WHEN mapping.user_id IS NOT NULL THEN 0 ELSE 1 END,
           mapping.display_name;
END
$$;

ALTER FUNCTION public.get_guild_members_browser_safe() OWNER TO postgres;

CREATE FUNCTION public.get_guild_members_debug(p_guild_code text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, player_id text, display_name text, guild_code text, role text, is_current boolean, claimed_status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
    SELECT
        pm.user_id,
        pm.player_id,
        pm.display_name,
        pm.guild_code,
        pm.role::TEXT,
        pm.is_current,
        CASE WHEN pm.user_id IS NOT NULL THEN 'CLAIMED' ELSE 'UNCLAIMED' END as claimed_status
    FROM player_mapping pm
    WHERE pm.is_current = true
    AND (p_guild_code IS NULL OR pm.guild_code = p_guild_code)
    ORDER BY
        pm.guild_code,
        CASE WHEN pm.user_id IS NOT NULL THEN 0 ELSE 1 END,
        pm.display_name;
$$;

ALTER FUNCTION public.get_guild_members_debug(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_members_simple() RETURNS TABLE(user_id uuid, player_id text, display_name text, guild_code text, role text, is_current boolean, last_sync_tokens integer, last_sync_bombs integer, tacticus_username text, discord_user_id text, last_sync_at timestamp without time zone, api_key_encrypted text, tacticus_api_key_encrypted text, api_key_is_valid boolean, primary_boss text, secondary_boss text, assignment_notes text, officer_notes text, player_notes text, primary_team text, secondary_team text, tertiary_team text, boss_preferences json, avatar_unit_id text, player_level integer, last_login_at timestamp with time zone, last_battle_time timestamp with time zone, last_bomb_time timestamp with time zone, timezone text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_guild TEXT;
    v_user_role TEXT;
    v_cluster_code TEXT;
    v_guild_list TEXT[];
    v_is_officer BOOLEAN;
BEGIN
    SELECT pm.guild_code, pm.role::TEXT, gc.cluster_code
    INTO v_user_guild, v_user_role, v_cluster_code
    FROM player_mapping pm
    LEFT JOIN guild_config gc ON gc.guild_code = pm.guild_code
    WHERE pm.user_id = auth.uid()
    AND pm.is_current = true
    LIMIT 1;

    v_is_officer := lower(COALESCE(v_user_role, '')) IN ('officer', 'leader');

    IF lower(COALESCE(v_user_role, '')) = 'leader' AND v_cluster_code IS NOT NULL THEN
        SELECT array_agg(gc.guild_code) INTO v_guild_list
        FROM guild_config gc
        WHERE gc.cluster_code = v_cluster_code;
    ELSE
        v_guild_list := ARRAY[v_user_guild];
    END IF;

    RETURN QUERY
    WITH latest_battles AS (
        SELECT
            grd."displayName" as player_name,
            grd."Guild" as gld_code,
            MAX(grd."startedOn") as last_battle
        FROM "EOT_GR_data" grd
        WHERE grd."damageType" = 'Battle'
        AND grd."Guild" = ANY(v_guild_list)
        GROUP BY grd."displayName", grd."Guild"
    ),
    latest_bombs AS (
        SELECT
            grd."displayName" as player_name,
            grd."Guild" as gld_code,
            MAX(grd."startedOn") as last_bomb
        FROM "EOT_GR_data" grd
        WHERE grd."damageType" = 'Bomb'
        AND grd."Guild" = ANY(v_guild_list)
        GROUP BY grd."displayName", grd."Guild"
    )
    SELECT
        pm.user_id,
        pm.player_id::TEXT,
        pm.display_name::TEXT,
        pm.guild_code::TEXT,
        pm.role::TEXT,
        pm.is_current,
        pm.last_sync_tokens,
        pm.last_sync_bombs,
        pm.display_name::TEXT as tacticus_username,
        pm.discord_user_id::TEXT,
        pm.last_sync_at,
        NULL::TEXT as api_key_encrypted,
        CASE WHEN v_is_officer THEN pm.tacticus_api_key_encrypted::TEXT ELSE NULL END,
        pm.api_key_is_valid,
        pm.primary_boss::TEXT,
        pm.secondary_boss::TEXT,
        pm.assignment_notes::TEXT,
        CASE WHEN v_is_officer THEN pm.officer_notes::TEXT ELSE NULL END,
        CASE WHEN v_is_officer THEN pm.player_notes::TEXT ELSE NULL END,
        pm.primary_team::TEXT,
        pm.secondary_team::TEXT,
        pm.tertiary_team::TEXT,
        pm.boss_preferences::JSON,
        pm.avatar_unit_id::TEXT,
        pm.player_level,
        pm.last_active_at as last_login_at,
        lb.last_battle as last_battle_time,
        lbomb.last_bomb as last_bomb_time,
        pm.timezone::TEXT
    FROM player_mapping pm
    LEFT JOIN latest_battles lb ON lb.player_name = pm.display_name AND lb.gld_code = pm.guild_code
    LEFT JOIN latest_bombs lbomb ON lbomb.player_name = pm.display_name AND lbomb.gld_code = pm.guild_code
    WHERE pm.is_current = true
    AND pm.guild_code = ANY(v_guild_list)
    ORDER BY
        CASE WHEN pm.user_id IS NOT NULL THEN 0 ELSE 1 END,
        pm.display_name;
END;
$$;

ALTER FUNCTION public.get_guild_members_simple() OWNER TO postgres;

CREATE FUNCTION public.get_guild_meta_analysis(p_guild_code text, p_season text DEFAULT '83'::text, p_boss_name text DEFAULT NULL::text) RETURNS TABLE(bossname text, encounterindex integer, teamcomposition jsonb, avgdamage numeric, maxdamage bigint, battlecount bigint, winrate numeric, consistency numeric, categories text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM player_mapping pm
    WHERE pm.user_id = auth.uid() AND pm.is_current = true AND pm.guild_code = p_guild_code
  ) THEN
    RAISE EXCEPTION 'Access denied: you must be a member of this guild to access guild-specific data';
  END IF;

  -- Body repair (see header WHAT #2): the live body referenced an unquoted
  -- table (folds to the non-existent lowercase `eot_gr_data`) and a non-existent
  -- `bossName` column. Quote the mixed-case table + columns and map the boss
  -- name to the real "Name" column (mirrors get_meta_analysis_compositions).
  -- CTE aliases keep the folded names so the RETURNS TABLE output is unchanged.
  RETURN QUERY
  WITH team_stats AS (
    SELECT eot."Name" AS bossname, eot."encounterIndex" AS encounterindex,
      eot."heroDetails" AS herodetails, eot."machineOfWarDetails" AS machineofwardetails,
      AVG(eot."damageDealt") as avg_damage, MAX(eot."damageDealt") as max_damage, COUNT(*) as battle_count,
      ROUND((COUNT(CASE WHEN eot."remainingHp" = 0 THEN 1 END)::NUMERIC / COUNT(*)::NUMERIC * 100)::NUMERIC, 1) as win_rate,
      ROUND(STDDEV(eot."damageDealt")::NUMERIC / AVG(eot."damageDealt")::NUMERIC * 100, 1) as consistency_score
    FROM public."EOT_GR_data" eot
    WHERE eot."Guild" = p_guild_code AND eot."Season" = p_season
      AND eot."damageType" = 'Battle' -- exclude Bomb rows (match sibling get_meta_analysis_compositions)
      AND eot."damageDealt" > 0
      AND (p_boss_name IS NULL OR eot."Name" = p_boss_name) AND eot."heroDetails" IS NOT NULL
    GROUP BY eot."Name", eot."encounterIndex", eot."heroDetails", eot."machineOfWarDetails"
    HAVING COUNT(*) >= 3
  )
  SELECT ts.bossname::TEXT, ts.encounterindex::INTEGER,
    jsonb_build_object('heroDetails', ts.herodetails, 'machineOfWarDetails', ts.machineofwardetails) as teamComposition,
    ROUND(ts.avg_damage::numeric, 0) as avgDamage, ts.max_damage::BIGINT, ts.battle_count::BIGINT,
    ts.win_rate::NUMERIC, ts.consistency_score::NUMERIC, ARRAY[]::TEXT[] as categories
  FROM team_stats ts
  ORDER BY ts.bossname, ts.encounterindex, ts.avg_damage DESC;
END;
$$;

ALTER FUNCTION public.get_guild_meta_analysis(p_guild_code text, p_season text, p_boss_name text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_overall_leaderboard(p_guild_code text, p_season text DEFAULT '83'::text) RETURNS TABLE("displayName" text, "Guild" text, "totalDamage" bigint, "battleCount" bigint, "avgDamage" numeric, "bombsUsed" bigint, "bossesKilled" bigint, "percentVsCluster" numeric, "currentRank" integer, "priorSeasonRank" integer, "rankChange" integer, "fiveSeasonAvgRank" numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.player_mapping pm
      WHERE pm.user_id = (SELECT auth.uid())
        AND pm.guild_code = p_guild_code
        AND pm.is_current = true
    ) THEN
      RAISE EXCEPTION 'Access denied: guild membership required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH guild_stats AS (
    SELECT
      d."displayName",
      d."Guild",
      SUM(d."damageDealt") AS total_damage,
      COUNT(*) AS battle_count,
      -- WI-2520: displayed average is Battle-only and sweep-free (one-shots
      -- kept); totals/counts stay raw.
      AVG(d."damageDealt") FILTER (
        WHERE d."damageType" = 'Battle'
          AND NOT (
            COALESCE(d."remainingHp", 0) = 0
            AND COALESCE(d."maxHp", 0) > 0
            AND d."damageDealt" < d."maxHp"
          )
      ) AS avg_damage,
      SUM(CASE WHEN d."damageType" = 'Bomb' THEN 1 ELSE 0 END) AS bombs_used,
      SUM(CASE WHEN d."remainingHp" = 0 THEN 1 ELSE 0 END) AS bosses_killed
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageDealt" > 0
    GROUP BY d."displayName", d."Guild"
  ),
  cluster_avg AS (
    SELECT AVG(gs.total_damage) AS cluster_avg_damage
    FROM guild_stats gs
  ),
  ranked_stats AS (
    SELECT
      gs.*,
      ROUND((gs.total_damage / NULLIF(ca.cluster_avg_damage, 0) * 100)::numeric, 1)
        AS percent_vs_cluster,
      ROW_NUMBER() OVER (ORDER BY gs.total_damage DESC) AS current_rank
    FROM guild_stats gs
    CROSS JOIN cluster_avg ca
  )
  SELECT
    rs."displayName"::text,
    rs."Guild"::text,
    rs.total_damage::bigint,
    rs.battle_count::bigint,
    COALESCE(ROUND(rs.avg_damage::numeric, 0), 0),
    rs.bombs_used::bigint,
    rs.bosses_killed::bigint,
    rs.percent_vs_cluster::numeric,
    rs.current_rank::integer,
    NULL::integer,
    NULL::integer,
    NULL::numeric
  FROM ranked_stats rs
  ORDER BY rs.total_damage DESC;
END;
$$;

ALTER FUNCTION public.get_guild_overall_leaderboard(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_overall_leaderboard_v2(p_guild_code text, p_season text) RETURNS TABLE(displayname text, guild text, total_damage bigint, battle_count bigint, avg_damage numeric, bombs_used bigint, bosses_killed bigint, percent_vs_cluster numeric, current_rank bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH player_stats AS (
    SELECT
      e."userId" as player_id,
      pm.display_name as current_display_name,
      e."Guild",
      SUM(e."damageDealt") as total_damage,
      COUNT(*) as battle_count,
      AVG(e."damageDealt") as avg_damage,
      0 as bombs_used,  -- bomb column not available in this table
      SUM(CASE WHEN e."remainingHp" = 0 THEN 1 ELSE 0 END) as bosses_killed
    FROM "EOT_GR_data" e
    LEFT JOIN player_mapping pm ON e."userId" = pm.player_id AND pm.is_current = true
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageDealt" > 0
      AND e."userId" IS NOT NULL
    GROUP BY e."userId", pm.display_name, e."Guild"
  ),
  cluster_avg AS (
    SELECT AVG(total_damage) as cluster_avg_damage
    FROM player_stats
  ),
  ranked_stats AS (
    SELECT
      ps.*,
      ROUND((ps.total_damage / NULLIF(ca.cluster_avg_damage, 0) * 100)::numeric, 1) as percent_vs_cluster,
      ROW_NUMBER() OVER (ORDER BY ps.total_damage DESC) as current_rank
    FROM player_stats ps
    CROSS JOIN cluster_avg ca
  )
  SELECT
    COALESCE(rs.current_display_name, 'Unknown Player')::TEXT as displayName,
    rs.Guild::TEXT,
    rs.total_damage,
    rs.battle_count,
    rs.avg_damage,
    rs.bombs_used,
    rs.bosses_killed,
    rs.percent_vs_cluster,
    rs.current_rank
  FROM ranked_stats rs
  ORDER BY rs.current_rank;
END;
$$;

ALTER FUNCTION public.get_guild_overall_leaderboard_v2(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_player_scores_batch(p_guild_code text, p_seasons text[]) RETURNS TABLE(season text, user_id text, weighted_vs_guild numeric, battle_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH guild_averages AS (
    SELECT
      e."Season",
      e."Name" || '_' || e.rarity || '_' || e.set AS boss_key,
      AVG(e."damageDealt") AS avg_damage
    FROM "EOT_GR_data" e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = ANY(p_seasons)
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
    GROUP BY e."Season", e."Name", e.rarity, e.set
  ),
  player_boss_stats AS (
    SELECT
      e."Season",
      e."userId",
      e."Name" || '_' || e.rarity || '_' || e.set AS boss_key,
      AVG(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS player_avg,
      COUNT(*) FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS battle_count,
      SUM(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS non_sweep_damage,
      array_agg(e."damageDealt"::numeric) FILTER (
        WHERE e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp"
      ) AS sweep_damages
    FROM "EOT_GR_data" e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = ANY(p_seasons)
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
    GROUP BY e."Season", e."userId", e."Name", e.rarity, e.set
  ),
  -- Weighted performance using shared functions
  player_weighted AS (
    SELECT
      pbs."Season",
      pbs."userId",
      SUM(
        calc_boss_performance_pct(pbs.non_sweep_damage, pbs.battle_count, pbs.sweep_damages, ga.avg_damage::numeric, pbs.player_avg::numeric)
        * calc_effective_battle_count(pbs.battle_count, pbs.sweep_damages, ga.avg_damage::numeric, pbs.player_avg::numeric)
      ) / NULLIF(SUM(
        calc_effective_battle_count(pbs.battle_count, pbs.sweep_damages, ga.avg_damage::numeric, pbs.player_avg::numeric)
      ), 0) AS weighted_vs_guild,
      -- total_battles: count all effective battles (LEFT JOIN safe — returns 0 for NULL avg)
      SUM(COALESCE(pbs.battle_count, 0) + COALESCE(qualifying_sweep_count(pbs.sweep_damages, GREATEST(pbs.player_avg::numeric, ga.avg_damage::numeric)), 0))::integer AS total_battles
    FROM player_boss_stats pbs
    LEFT JOIN guild_averages ga ON ga."Season" = pbs."Season" AND ga.boss_key = pbs.boss_key
    GROUP BY pbs."Season", pbs."userId"
  )
  SELECT
    pw."Season"::text AS season,
    pw."userId" AS user_id,
    pw.weighted_vs_guild,
    pw.total_battles AS battle_count
  FROM player_weighted pw
  WHERE pw.weighted_vs_guild IS NOT NULL
  ORDER BY pw."Season" DESC, pw.weighted_vs_guild DESC;
$$;

ALTER FUNCTION public.get_guild_player_scores_batch(p_guild_code text, p_seasons text[]) OWNER TO postgres;

CREATE FUNCTION public.get_guild_rarities(p_guild_code text, p_season text DEFAULT NULL::text) RETURNS TABLE(rarity text, battle_count bigint)
    LANGUAGE plpgsql STABLE
    AS $$
begin
  return query
  select
    d."rarity"::text as rarity,
    count(*)::bigint as battle_count
  from "EOT_GR_data" d
  where d."Guild" = p_guild_code
    and d."damageType" = 'Battle'
    and (p_season is null or d."Season" = p_season)
    and d."rarity" is not null
  group by d."rarity"
  order by count(*) desc;
end;
$$;

ALTER FUNCTION public.get_guild_rarities(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_season_forecast(p_guild_code text, p_include_per_player boolean DEFAULT false, p_season_number integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  -- Loki season schedule constants — mirror packages/app-core/src/season-timing.ts.
  -- season N starts at: epoch + GAP + (N + SEASON_NUMBER_OFFSET - 1) * SEASON_CYCLE_SECONDS
  -- Active duration excludes the 24h gap between seasons.
  c_first_season_start_epoch CONSTANT BIGINT := 1646128800;
  c_season_number_offset     CONSTANT INT    := 10;  -- WI-1840: was 11 (13d-late window)
  c_season_gap_seconds       CONSTANT BIGINT := 86400;     -- 24h gap before each season
  c_season_cycle_seconds     CONSTANT BIGINT := 1209600;  -- 14d
  c_season_active_seconds    CONSTANT BIGINT := 1123200;  -- 13d
  c_max_tokens               CONSTANT INT    := 3;
  c_token_regen_seconds      CONSTANT BIGINT := 43200;    -- 12h
  c_bomb_max_per_player      CONSTANT INT    := 1;
  c_bomb_regen_seconds       CONSTANT BIGINT := 64800;    -- 18h fallback (Loki: bombs.regenerationSeconds)
  c_last_n_laps              CONSTANT INT    := 2;

  v_season_number INT;
  v_starts_at TIMESTAMPTZ;
  v_ends_at   TIMESTAMPTZ;
  v_seconds_remaining BIGINT;

  v_caller_player_id TEXT;

  v_tokens_available_now INT;
  v_tokens_yet_to_regen INT;
  v_tokens_capacity INT;
  v_cap_bound_players INT;
  v_estimated_cap_waste INT;

  v_bombs_available_now INT;
  v_bombs_yet_to_regen INT;
  v_bombs_capacity INT;

  v_current_lap INT;
  v_tokens_into_current_lap INT;
  v_projected_lap_cost NUMERIC;
  v_completed_lap_count INT;

  v_has_solver_data BOOLEAN;
  v_basis TEXT;
  v_confidence TEXT;

  v_tokens_to_finish_current_lap NUMERIC;
  v_post_current_lap_tokens NUMERIC;
  v_projected_finish_lap INT;
  v_projected_finish_pct NUMERIC;

  v_per_player JSONB;
  v_lap_projection JSONB;
BEGIN
  -- Resolve season number: explicit param wins; otherwise compute current.
  IF p_season_number IS NULL THEN
    v_season_number := FLOOR(
      GREATEST(0, EXTRACT(EPOCH FROM NOW())::BIGINT - c_first_season_start_epoch - c_season_gap_seconds)::NUMERIC
        / c_season_cycle_seconds
    )::INT + 1 - c_season_number_offset;
  ELSE
    v_season_number := p_season_number;
  END IF;

  -- Season window
  v_starts_at := to_timestamp(
    c_first_season_start_epoch + c_season_gap_seconds
      + ((v_season_number + c_season_number_offset - 1)::BIGINT * c_season_cycle_seconds)
  );
  v_ends_at := v_starts_at + (c_season_active_seconds || ' seconds')::INTERVAL;
  v_seconds_remaining := CASE
    WHEN NOW() < v_starts_at THEN 0  -- WI-1840: don't show a positive countdown pre-start
    ELSE GREATEST(0, EXTRACT(EPOCH FROM (v_ends_at - NOW()))::BIGINT)
  END;

  -- Caller's player_id (used to gate per_player when p_include_per_player=false).
  -- May be NULL for service_role / cluster-officer cross-guild views; in that
  -- case includes-self produces an empty per_player array.
  SELECT pm.player_id INTO v_caller_player_id
  FROM public.player_mapping pm
  WHERE pm.user_id = auth.uid()
    AND pm.is_current = TRUE
  LIMIT 1;

  -- Per-player current state (live-ish snapshot from player_with_cluster).
  -- token_burn_state.season is text, so cast on join.
  WITH players AS (
    SELECT
      pwc.player_id,
      pwc.display_name,
      COALESCE(pwc.last_sync_tokens, 0)::INT AS tokens_now,
      GREATEST(COALESCE(pwc.next_token_seconds, 0), 0)::BIGINT AS next_token_seconds,
      COALESCE(pwc.last_sync_bombs, 0)::INT AS bombs_now,
      GREATEST(COALESCE(pwc.next_bomb_seconds, 0), 0)::BIGINT AS next_bomb_seconds,
      COALESCE(tbs.time_over_cap_seconds, 0)::BIGINT AS time_over_cap_seconds
    FROM public.player_with_cluster pwc
    LEFT JOIN public.token_burn_state tbs
      ON tbs.guild_code = pwc.guild_code
     AND tbs.player_id  = pwc.player_id
     AND tbs.season     = v_season_number::TEXT
    WHERE pwc.guild_code = p_guild_code
      AND pwc.is_current = TRUE
      AND pwc.player_id IS NOT NULL
  ),
  computed AS (
    SELECT
      p.player_id,
      p.display_name,
      p.tokens_now,
      p.next_token_seconds::INT AS next_token_seconds,
      p.bombs_now,
      p.next_bomb_seconds::INT AS next_bomb_seconds,
      p.time_over_cap_seconds,
      -- tokens_will_regen: 1 + floor((seconds_remaining - next_token_seconds) / 12h),
      -- clamped to [0, MAX_TOKENS - tokens_now]. Mirrors the spreadsheet formula
      -- 1 + INT((countdown - timeToNext) / regen_min). Returns 0 when next token
      -- won't arrive before season end.
      GREATEST(0, LEAST(
        (c_max_tokens - p.tokens_now),
        CASE
          WHEN v_seconds_remaining > p.next_token_seconds THEN
            FLOOR((v_seconds_remaining - p.next_token_seconds)::NUMERIC / c_token_regen_seconds)::INT + 1
          ELSE 0
        END
      ))::INT AS tokens_will_regen,
      -- theoretical_regen: ignores per-player next_token_seconds, just floor(remaining/12h).
      FLOOR(v_seconds_remaining::NUMERIC / c_token_regen_seconds)::INT AS theoretical_regen,
      -- bombs_will_regen: 1 if currently below cap AND next_bomb_seconds < remaining.
      CASE
        WHEN p.bombs_now < c_bomb_max_per_player
         AND v_seconds_remaining > p.next_bomb_seconds
        THEN c_bomb_max_per_player - p.bombs_now
        ELSE 0
      END::INT AS bombs_will_regen
    FROM players p
  ),
  full_player AS (
    SELECT
      c.*,
      LEAST(c_max_tokens, c.tokens_now + c.tokens_will_regen)::INT AS tokens_at_season_end,
      (c.tokens_now + c.tokens_will_regen >= c_max_tokens
        AND c.time_over_cap_seconds > 0) AS will_cap,
      GREATEST(0, c.theoretical_regen - c.tokens_will_regen)::INT AS estimated_cap_waste
    FROM computed c
  )
  SELECT
    SUM(tokens_now)::INT,
    SUM(tokens_will_regen)::INT,
    (SUM(tokens_now) + SUM(tokens_will_regen))::INT,
    SUM(CASE WHEN will_cap THEN 1 ELSE 0 END)::INT,
    SUM(estimated_cap_waste)::INT,
    SUM(bombs_now)::INT,
    SUM(bombs_will_regen)::INT,
    (SUM(bombs_now) + SUM(bombs_will_regen))::INT
  INTO
    v_tokens_available_now,
    v_tokens_yet_to_regen,
    v_tokens_capacity,
    v_cap_bound_players,
    v_estimated_cap_waste,
    v_bombs_available_now,
    v_bombs_yet_to_regen,
    v_bombs_capacity
  FROM full_player;

  -- Aggregates may be NULL when the guild has no players in player_with_cluster.
  v_tokens_available_now := COALESCE(v_tokens_available_now, 0);
  v_tokens_yet_to_regen  := COALESCE(v_tokens_yet_to_regen, 0);
  v_tokens_capacity      := COALESCE(v_tokens_capacity, 0);
  v_cap_bound_players    := COALESCE(v_cap_bound_players, 0);
  v_estimated_cap_waste  := COALESCE(v_estimated_cap_waste, 0);
  v_bombs_available_now  := COALESCE(v_bombs_available_now, 0);
  v_bombs_yet_to_regen   := COALESCE(v_bombs_yet_to_regen, 0);
  v_bombs_capacity       := COALESCE(v_bombs_capacity, 0);

  -- Build per_player array, gated by p_include_per_player. When false, only
  -- the caller's own row is returned. When the caller has no player_mapping,
  -- the array is empty.
  WITH players AS (
    SELECT
      pwc.player_id,
      pwc.display_name,
      COALESCE(pwc.last_sync_tokens, 0)::INT AS tokens_now,
      GREATEST(COALESCE(pwc.next_token_seconds, 0), 0)::BIGINT AS next_token_seconds,
      COALESCE(pwc.last_sync_bombs, 0)::INT AS bombs_now,
      GREATEST(COALESCE(pwc.next_bomb_seconds, 0), 0)::BIGINT AS next_bomb_seconds,
      COALESCE(tbs.time_over_cap_seconds, 0)::BIGINT AS time_over_cap_seconds
    FROM public.player_with_cluster pwc
    LEFT JOIN public.token_burn_state tbs
      ON tbs.guild_code = pwc.guild_code
     AND tbs.player_id  = pwc.player_id
     AND tbs.season     = v_season_number::TEXT
    WHERE pwc.guild_code = p_guild_code
      AND pwc.is_current = TRUE
      AND pwc.player_id IS NOT NULL
      AND (p_include_per_player OR pwc.player_id = v_caller_player_id)
  ),
  computed AS (
    SELECT
      p.player_id,
      p.display_name,
      p.tokens_now,
      p.next_token_seconds::INT AS next_token_seconds,
      p.time_over_cap_seconds,
      GREATEST(0, LEAST(
        (c_max_tokens - p.tokens_now),
        CASE
          WHEN v_seconds_remaining > p.next_token_seconds THEN
            FLOOR((v_seconds_remaining - p.next_token_seconds)::NUMERIC / c_token_regen_seconds)::INT + 1
          ELSE 0
        END
      ))::INT AS tokens_will_regen,
      FLOOR(v_seconds_remaining::NUMERIC / c_token_regen_seconds)::INT AS theoretical_regen
    FROM players p
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'player_id', c.player_id,
    'display_name', c.display_name,
    'tokens_now', c.tokens_now,
    'next_token_seconds', c.next_token_seconds,
    'tokens_will_regen', c.tokens_will_regen,
    'tokens_at_season_end', LEAST(c_max_tokens, c.tokens_now + c.tokens_will_regen),
    'will_cap', (c.tokens_now + c.tokens_will_regen >= c_max_tokens AND c.time_over_cap_seconds > 0),
    'estimated_cap_waste', GREATEST(0, c.theoretical_regen - c.tokens_will_regen)
  ) ORDER BY c.display_name), '[]'::JSONB)
  INTO v_per_player
  FROM computed c;

  -- Lap projection: current lap, tokens spent on it, last-N-laps avg cost.
  -- "Lap N" display = loopIndex + 1; loopIndex is 0-based per progression-config-shared.ts.
  SELECT
    COALESCE(MAX(d."loopIndex"), 0)::INT
  INTO v_current_lap
  FROM public."EOT_GR_data" d
  WHERE d."Guild" = p_guild_code
    AND d."Season"::INT = v_season_number
    AND d."damageType" = 'Battle'
    AND d."loopIndex" IS NOT NULL;

  IF v_current_lap IS NULL THEN
    v_current_lap := 0;
    v_tokens_into_current_lap := 0;
  ELSE
    SELECT COUNT(*)::INT
    INTO v_tokens_into_current_lap
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season"::INT = v_season_number
      AND d."damageType" = 'Battle'
      AND d."loopIndex" = v_current_lap;
  END IF;
  v_tokens_into_current_lap := COALESCE(v_tokens_into_current_lap, 0);

  -- Last-N-laps avg cost, excluding the current (in-progress) lap.
  WITH lap_costs AS (
    SELECT
      d."loopIndex" AS lap,
      COUNT(*)::INT AS tokens_used
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season"::INT = v_season_number
      AND d."damageType" = 'Battle'
      AND d."loopIndex" IS NOT NULL
      AND d."loopIndex" < v_current_lap
    GROUP BY d."loopIndex"
    ORDER BY d."loopIndex" DESC
    LIMIT c_last_n_laps
  )
  SELECT AVG(tokens_used)::NUMERIC, COUNT(*)::INT
    INTO v_projected_lap_cost, v_completed_lap_count
  FROM lap_costs;

  -- Solver basis: WI-737 medians available for the current loop?
  -- Wrapped in a try-catch shim because get_stage_kill_duration_medians
  -- may return zero rows for a fresh guild — that's a 'last_n_laps' fallback,
  -- not an error.
  v_has_solver_data := FALSE;
  IF v_completed_lap_count IS NOT NULL AND v_completed_lap_count > 0 THEN
    BEGIN
      SELECT EXISTS (
        SELECT 1
        FROM public.get_stage_kill_duration_medians(p_guild_code, v_season_number, 60)
        WHERE loop_index = v_current_lap
      ) INTO v_has_solver_data;
    EXCEPTION WHEN OTHERS THEN
      v_has_solver_data := FALSE;
    END;
  END IF;

  v_basis := CASE WHEN v_has_solver_data THEN 'wi737_solver' ELSE 'last_n_laps' END;

  -- Confidence label: 0-1 → low, 2-3 → medium, 4+ → high. 0 completed laps
  -- yields NULL projection (omitted from envelope).
  v_confidence := CASE
    WHEN v_completed_lap_count IS NULL OR v_completed_lap_count <= 1 THEN 'low'
    WHEN v_completed_lap_count <= 3 THEN 'medium'
    ELSE 'high'
  END;

  IF v_completed_lap_count IS NULL OR v_completed_lap_count = 0 OR v_projected_lap_cost IS NULL THEN
    v_lap_projection := NULL;
  ELSE
    v_tokens_to_finish_current_lap := GREATEST(v_projected_lap_cost - v_tokens_into_current_lap, 0);
    v_post_current_lap_tokens := v_tokens_capacity - v_tokens_to_finish_current_lap;

    IF v_post_current_lap_tokens >= 0 THEN
      -- Finish current lap; partial = leftover / projected_lap_cost.
      v_projected_finish_lap := v_current_lap;
      v_projected_finish_pct := LEAST(
        v_post_current_lap_tokens / NULLIF(v_projected_lap_cost, 0),
        0.999
      );
    ELSE
      -- Don't finish current lap; progress within it = (already_in + capacity) / cost.
      v_projected_finish_lap := GREATEST(0, v_current_lap - 1);
      v_projected_finish_pct := LEAST(
        (v_tokens_into_current_lap + v_tokens_capacity)::NUMERIC
          / NULLIF(v_projected_lap_cost, 0),
        0.999
      );
    END IF;

    v_lap_projection := jsonb_build_object(
      'current_lap', v_current_lap,
      'tokens_into_current_lap', v_tokens_into_current_lap,
      'projected_lap_cost', ROUND(v_projected_lap_cost, 2),
      'basis', v_basis,
      'n', v_completed_lap_count,
      'projected_finish_lap', v_projected_finish_lap,
      'projected_finish_pct', ROUND(v_projected_finish_pct, 4),
      'confidence', v_confidence
    );
  END IF;

  -- Final envelope. jsonb_strip_nulls drops lap_projection when NULL so
  -- consumers can use `'lap_projection' in envelope` to detect availability.
  RETURN jsonb_strip_nulls(jsonb_build_object(
    'season', jsonb_build_object(
      'number', v_season_number,
      'starts_at', v_starts_at,
      'ends_at', v_ends_at,
      'seconds_remaining', v_seconds_remaining
    ),
    'tokens', jsonb_build_object(
      'available_now', v_tokens_available_now,
      'yet_to_regen', v_tokens_yet_to_regen,
      'capacity', v_tokens_capacity,
      'cap_bound_players', v_cap_bound_players,
      'estimated_cap_waste', v_estimated_cap_waste
    ),
    'bombs', jsonb_build_object(
      'available_now', v_bombs_available_now,
      'yet_to_regen', v_bombs_yet_to_regen,
      'capacity', v_bombs_capacity
    ),
    'lap_projection', v_lap_projection,
    'per_player', v_per_player
  ));
END;
$$;

ALTER FUNCTION public.get_guild_season_forecast(p_guild_code text, p_include_per_player boolean, p_season_number integer) OWNER TO postgres;

CREATE FUNCTION public.get_guild_season_summary(p_guild_code text, p_season text) RETURNS TABLE(total_damage numeric, total_battles integer, max_hit numeric, boss_kills integer, recent_activity integer, avg_damage_per_hour numeric)
    LANGUAGE sql STABLE
    AS $$
with base as (
  select
    coalesce(sum("damageDealt"), 0) as total_damage,
    count(*) filter (where "damageType" = 'Battle') as total_battles,
    max(nullif("damageDealt", 0)) as max_hit,
    count(*) filter (
      where "damageType" = 'Battle'
        and "remainingHp" = 0
        and "maxHp" > 0
        and "damageDealt" >= "maxHp"
    ) as boss_kills
  from "EOT_GR_data"
  where "Guild" = p_guild_code
    and "Season" = p_season
    and "damageType" in ('Battle', 'Bomb')
),
recent AS (
  -- recent activity = battles in last 24h (optional heuristic)
  select count(*) as recent_activity
  from "EOT_GR_data"
  where "Guild" = p_guild_code
    and "Season" = p_season
    and "damageType" in ('Battle', 'Bomb')
    and coalesce("completedOn", "timestamp", "startedOn") >= (now() - interval '1 day')
),
duration as (
  select
    extract(epoch from (max(coalesce("completedOn", "timestamp", "startedOn")) - min(coalesce("completedOn", "timestamp", "startedOn")))) / 3600.0 as hours_span
  from "EOT_GR_data"
  where "Guild" = p_guild_code
    and "Season" = p_season
    and "damageType" in ('Battle', 'Bomb')
    and coalesce("completedOn", "timestamp", "startedOn") is not null
)
select
  base.total_damage,
  base.total_battles,
  base.max_hit,
  base.boss_kills,
  coalesce(recent.recent_activity, 0) as recent_activity,
  case
    when duration.hours_span is not null and duration.hours_span > 0 then base.total_damage / duration.hours_span
    else null::numeric
  end as avg_damage_per_hour
from base, recent, duration;
$$;

ALTER FUNCTION public.get_guild_season_summary(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_season_veterans(p_guild_code text, p_season_count integer DEFAULT 5) RETURNS TABLE(display_name text, seasons text[])
    LANGUAGE sql STABLE
    AS $_$
  with distinct_seasons as (
    -- Order numerically — Season is stored as text but represents an
    -- integer (e.g. "47", "48"). Lexical ordering would put "9" after
    -- "47", which is wrong. Matches the parseInt sort in the JS legacy path.
    -- Postgres requires the ORDER BY expr in SELECT for SELECT DISTINCT,
    -- so we project the int alongside the text season.
    select distinct "Season" as season, ("Season")::int as season_int
    from "EOT_GR_data"
    where "Guild" = p_guild_code
      and "Season" is not null
      and "Season" ~ '^\d+$'
  ),
  last_seasons as (
    select season
    from distinct_seasons
    order by season_int desc
    limit greatest(coalesce(p_season_count, 5), 1)
  ),
  -- Capture the actual list of seasons we operate on, so callers can verify
  -- the guild had enough history (if fewer than p_season_count exist, no
  -- veterans are returned — matches the JS guard `last5Seasons.length < 5`).
  season_list as (
    select array_agg(season order by season desc) as season_arr,
           count(*)::int as season_n
    from last_seasons
  ),
  per_player_seasons as (
    select
      coalesce(d."displayName", 'Unknown') as display_name,
      count(distinct d."Season") as distinct_season_count
    from "EOT_GR_data" d
    join last_seasons ls on ls.season = d."Season"
    where d."Guild" = p_guild_code
    group by coalesce(d."displayName", 'Unknown')
  )
  select
    p.display_name,
    sl.season_arr as seasons
  from per_player_seasons p
  cross join season_list sl
  where sl.season_n = coalesce(p_season_count, 5)  -- only return when we have enough seasons
    and p.distinct_season_count = sl.season_n
  order by p.display_name asc;
$_$;

ALTER FUNCTION public.get_guild_season_veterans(p_guild_code text, p_season_count integer) OWNER TO postgres;

CREATE FUNCTION public.get_guild_team_roster(p_guild_code text, p_unit_ids text[]) RETURNS TABLE(player_display_name text, guild_role text, unit_id text, hero_display_name text, category text, web_icon_url text, stars integer, progression_index integer, rarity text, rank_name text, xp_level integer, active_ability_level integer, passive_ability_level integer, synced_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_effective_role text := COALESCE(
    NULLIF(
      NULLIF(pg_catalog.current_setting('role', true), ''),
      'none'
    ),
    NULLIF(session_user, '')
  );
  v_uid uuid;
  v_mapping_count integer := 0;
  v_mapping record;
  v_caller_guild_code text;
  v_caller_role text;
  v_caller_is_app_admin boolean := false;
  v_caller_config_count integer := 0;
  v_caller_config record;
  v_caller_cluster_id uuid;
  v_target_config_count integer := 0;
  v_target_config record;
  v_target_cluster_id uuid;
  v_self_only boolean := false;
BEGIN
  -- Malformed or unscoped requests never enter the private roster query.
  IF p_guild_code IS NULL
     OR p_unit_ids IS NULL
     OR pg_catalog.cardinality(p_unit_ids) = 0 THEN
    RETURN;
  END IF;

  -- A target must resolve to exactly one server-owned guild_config row.
  BEGIN
    FOR v_target_config IN
      SELECT gc.cluster_id
      FROM public.guild_config AS gc
      WHERE gc.guild_code = p_guild_code
    LOOP
      v_target_config_count := v_target_config_count + 1;
      IF v_target_config_count > 1 THEN
        RETURN;
      END IF;
      v_target_cluster_id := v_target_config.cluster_id;
    END LOOP;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN;
  END;

  IF v_target_config_count <> 1 THEN
    RETURN;
  END IF;

  IF v_effective_role <> 'service_role' THEN
    -- auth.uid() and membership lookup errors fail closed before roster reads.
    BEGIN
      v_uid := auth.uid();
      IF v_uid IS NULL THEN
        RETURN;
      END IF;

      FOR v_mapping IN
        SELECT
          pm.guild_code,
          pg_catalog.lower(pg_catalog.btrim(pm.role::text)) AS normalized_role,
          COALESCE(pm.is_app_admin, false) AS is_app_admin
        FROM public.player_mapping AS pm
        WHERE pm.user_id = v_uid
          AND pm.is_current IS TRUE
      LOOP
        v_mapping_count := v_mapping_count + 1;
        IF v_mapping_count > 1 THEN
          RETURN;
        END IF;
        v_caller_guild_code := v_mapping.guild_code;
        v_caller_role := v_mapping.normalized_role;
        v_caller_is_app_admin := v_mapping.is_app_admin;
      END LOOP;
    EXCEPTION
      WHEN OTHERS THEN
        RETURN;
    END;

    IF v_mapping_count <> 1
       OR v_caller_guild_code IS NULL
       OR v_caller_role IS NULL
       OR v_caller_role NOT IN ('member', 'officer', 'leader') THEN
      RETURN;
    END IF;

    IF v_caller_is_app_admin THEN
      -- Current app-admins retain the full requested-guild projection.
      NULL;
    ELSIF v_caller_role = 'member' THEN
      -- Ordinary members may see only their own row in their own guild.
      IF p_guild_code IS DISTINCT FROM v_caller_guild_code THEN
        RETURN;
      END IF;
      v_self_only := true;
    ELSIF p_guild_code IS DISTINCT FROM v_caller_guild_code THEN
      -- Officer/leader foreign-guild access requires an exact, non-null,
      -- server-derived cluster match for the current and target guilds.
      BEGIN
        FOR v_caller_config IN
          SELECT gc.cluster_id
          FROM public.guild_config AS gc
          WHERE gc.guild_code = v_caller_guild_code
        LOOP
          v_caller_config_count := v_caller_config_count + 1;
          IF v_caller_config_count > 1 THEN
            RETURN;
          END IF;
          v_caller_cluster_id := v_caller_config.cluster_id;
        END LOOP;
      EXCEPTION
        WHEN OTHERS THEN
          RETURN;
      END;

      IF v_caller_config_count <> 1
         OR v_caller_cluster_id IS NULL
         OR v_target_cluster_id IS NULL
         OR v_caller_cluster_id IS DISTINCT FROM v_target_cluster_id THEN
        RETURN;
      END IF;
    END IF;
  END IF;

  RETURN QUERY
    SELECT
      pm.display_name,
      pm.role::text,
      hm.unit_id,
      hm.display_name,
      hm.category,
      hm.web_icon_url,
      pr.stars,
      pr.progression_index,
      pr.rarity,
      pr.rank_name,
      pr.xp_level,
      pr.active_ability_level,
      pr.passive_ability_level,
      pr.synced_at
    FROM public.player_mapping AS pm
    CROSS JOIN public.hero_mappings AS hm
    LEFT JOIN LATERAL (
      SELECT
        r.stars,
        r.progression_index,
        r.rarity,
        r.rank_name,
        r.xp_level,
        r.active_ability_level,
        r.passive_ability_level,
        r.synced_at
      FROM public.player_roster AS r
      WHERE r.hero_mapping_id = hm.id
        AND (
          r.player_mapping_id = pm.id
          OR (
            r.player_mapping_id IS NULL
            AND pm.user_id IS NOT NULL
            AND r.user_id = pm.user_id
          )
        )
      ORDER BY
        r.synced_at DESC NULLS LAST,
        ((r.player_mapping_id = pm.id) IS TRUE) DESC
      LIMIT 1
    ) AS pr ON true
    WHERE pm.guild_code = p_guild_code
      AND pm.is_current IS TRUE
      AND hm.unit_id = ANY(p_unit_ids)
      AND (NOT v_self_only OR pm.user_id = v_uid)
    ORDER BY pm.display_name, hm.display_name;
END;
$$;

ALTER FUNCTION public.get_guild_team_roster(p_guild_code text, p_unit_ids text[]) OWNER TO postgres;

CREATE FUNCTION public.get_guild_token_status(p_guild_code text, p_season text DEFAULT NULL::text) RETURNS TABLE(player_name text, tokens_available integer, battles_today integer, last_battle_time timestamp with time zone, is_capped boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT
        pm.display_name,
        COALESCE(calc.tokens_available, 3) as tokens_available,
        COALESCE(calc.battles_today, 0) as battles_today,
        calc.last_battle_time,
        COALESCE(calc.is_capped, FALSE) as is_capped
    FROM player_mapping pm
    LEFT JOIN LATERAL (
        SELECT * FROM calculate_player_tokens(pm.display_name, pm.guild_code, p_season)
    ) calc ON TRUE
    WHERE pm.guild_code = p_guild_code
    AND pm.is_current = true
    ORDER BY tokens_available DESC, pm.display_name;
END;
$$;

ALTER FUNCTION public.get_guild_token_status(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_trends_batch(p_guild_code text, p_seasons text[]) RETURNS TABLE(season text, total_damage numeric, total_battles integer, max_hit bigint, boss_kills integer, active_players integer, guild_member_count integer, participation_rate numeric, avg_damage_per_token numeric, vs_cluster_percent numeric, guild_rank_in_cluster integer, total_guilds_in_cluster integer, reliability_score numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH guild_cluster AS (
    SELECT cluster_code
    FROM guild_config
    WHERE guild_code = p_guild_code
    LIMIT 1
  ),
  cluster_guilds AS (
    SELECT guild_code
    FROM guild_config
    WHERE cluster_code = (SELECT cluster_code FROM guild_cluster)
      AND (SELECT cluster_code FROM guild_cluster) IS NOT NULL
  ),
  -- Unfiltered token counts: ALL battle tokens (no damage filter)
  all_token_counts AS (
    SELECT
      e."Season",
      COUNT(*)::integer AS token_count,
      COUNT(DISTINCT e."userId")::integer AS active_players
    FROM "EOT_GR_data" e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = ANY(p_seasons)
      AND e."damageType" = 'Battle'
    GROUP BY e."Season"
  ),
  -- Filtered battle data for damage metrics + cluster comparison
  battle_data AS (
    SELECT
      e."Season",
      e."userId",
      e."damageDealt",
      e."remainingHp",
      e."Name" AS boss_name,
      e."encounterId"
    FROM "EOT_GR_data" e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = ANY(p_seasons)
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      AND e."encounterId" = 0
  ),
  season_agg AS (
    SELECT
      bd."Season",
      SUM(bd."damageDealt")::numeric AS total_damage,
      COUNT(*)::integer AS filtered_battles,
      MAX(bd."damageDealt") AS max_hit,
      COUNT(*) FILTER (WHERE bd."remainingHp" = 0)::integer AS boss_kills
    FROM battle_data bd
    GROUP BY bd."Season"
  ),
  member_count AS (
    SELECT COUNT(*)::integer AS cnt
    FROM player_mapping
    WHERE guild_code = p_guild_code
      AND is_current = true
  ),
  guild_boss_avgs AS (
    SELECT
      bd."Season",
      bd.boss_name,
      AVG(bd."damageDealt")::numeric AS guild_avg,
      COUNT(*)::integer AS battle_count
    FROM battle_data bd
    GROUP BY bd."Season", bd.boss_name
  ),
  cluster_boss_avgs AS (
    SELECT
      e."Season",
      e."Name" AS boss_name,
      AVG(e."damageDealt")::numeric AS cluster_avg
    FROM "EOT_GR_data" e
    WHERE e."Season" = ANY(p_seasons)
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      AND e."encounterId" = 0
      AND (
        e."Guild" IN (SELECT guild_code FROM cluster_guilds)
        OR e.cluster_code = (SELECT cluster_code FROM guild_cluster)
      )
      AND (SELECT cluster_code FROM guild_cluster) IS NOT NULL
    GROUP BY e."Season", e."Name"
  ),
  guild_vs_cluster AS (
    SELECT
      g."Season",
      CASE
        WHEN SUM(g.battle_count) > 0 THEN
          ROUND(
            SUM(
              CASE WHEN c.cluster_avg > 0
                THEN ((g.guild_avg / c.cluster_avg) - 1) * 100 * g.battle_count
                ELSE 0
              END
            ) / SUM(g.battle_count),
          1)
        ELSE NULL
      END AS vs_cluster_pct
    FROM guild_boss_avgs g
    LEFT JOIN cluster_boss_avgs c
      ON g."Season" = c."Season" AND g.boss_name = c.boss_name
    GROUP BY g."Season"
  ),
  guild_reliability AS (
    SELECT
      g."Season",
      CASE
        WHEN COUNT(g.guild_avg) >= 2 AND AVG(g.guild_avg) > 0 THEN
          ROUND(GREATEST(0, 100 - (STDDEV_POP(g.guild_avg) / AVG(g.guild_avg)) * 100), 1)
        ELSE NULL
      END AS reliability
    FROM guild_boss_avgs g
    GROUP BY g."Season"
  ),
  -- Total damage per guild in the cluster: ALL rows, no damageType /
  -- rarity / encounterId filter, so it matches the in-game leaderboard
  -- and cluster-analytics "Guild Performance Metrics" (totalDamage).
  cluster_guild_totals AS (
    SELECT
      e."Season",
      e."Guild" AS guild_code,
      SUM(e."damageDealt")::numeric AS total_damage
    FROM "EOT_GR_data" e
    WHERE e."Season" = ANY(p_seasons)
      AND (
        e."Guild" IN (SELECT guild_code FROM cluster_guilds)
        OR e.cluster_code = (SELECT cluster_code FROM guild_cluster)
      )
      AND (SELECT cluster_code FROM guild_cluster) IS NOT NULL
    GROUP BY e."Season", e."Guild"
  ),
  guild_rankings AS (
    SELECT
      cgt."Season",
      cgt.guild_code,
      RANK() OVER (PARTITION BY cgt."Season" ORDER BY cgt.total_damage DESC)::integer AS rank_in_cluster,
      COUNT(*) OVER (PARTITION BY cgt."Season")::integer AS total_guilds
    FROM cluster_guild_totals cgt
    WHERE cgt.total_damage IS NOT NULL
  )
  SELECT
    sa."Season"::text AS season,
    sa.total_damage,
    atc.token_count AS total_battles,
    sa.max_hit,
    sa.boss_kills,
    atc.active_players,
    mc.cnt AS guild_member_count,
    CASE WHEN mc.cnt > 0
      THEN LEAST(100.0, ROUND((atc.active_players::numeric / mc.cnt) * 100, 1))
      ELSE NULL
    END AS participation_rate,
    CASE WHEN sa.filtered_battles > 0
      THEN ROUND(sa.total_damage / sa.filtered_battles, 2)
      ELSE NULL
    END AS avg_damage_per_token,
    gvc.vs_cluster_pct AS vs_cluster_percent,
    gr.rank_in_cluster AS guild_rank_in_cluster,
    gr.total_guilds AS total_guilds_in_cluster,
    grel.reliability AS reliability_score
  FROM season_agg sa
  JOIN all_token_counts atc ON sa."Season" = atc."Season"
  CROSS JOIN member_count mc
  LEFT JOIN guild_vs_cluster gvc ON sa."Season" = gvc."Season"
  LEFT JOIN guild_rankings gr ON sa."Season" = gr."Season" AND gr.guild_code = p_guild_code
  LEFT JOIN guild_reliability grel ON sa."Season" = grel."Season"
  ORDER BY sa."Season" DESC;
$$;

ALTER FUNCTION public.get_guild_trends_batch(p_guild_code text, p_seasons text[]) OWNER TO postgres;

CREATE FUNCTION public.get_guild_vs_cluster_boss_performance(p_guild_code text, p_season text, p_rarities text[] DEFAULT ARRAY['Legendary'::text, 'Mythic'::text]) RETURNS TABLE(boss_name text, encounter_type text, guild_avg_damage numeric, cluster_avg_damage numeric, vs_cluster_percent numeric, set integer, rarity text)
    LANGUAGE sql
    AS $$
WITH cluster_ctx AS (
  SELECT cluster_code
  FROM guild_config
  WHERE guild_code = p_guild_code
  LIMIT 1
),
cluster_guilds AS (
  SELECT guild_code
  FROM guild_config
  WHERE cluster_code IN (SELECT cluster_code FROM cluster_ctx)
),
guild_agg AS (
  SELECT
    "Name" as boss_name,
    "encounterId" as encounter_id,
    "set",
    rarity,
    sum("damageDealt") as total_damage,
    count(*) as battle_count
  FROM "EOT_GR_data"
  WHERE "Season" = p_season
    AND "Guild" = p_guild_code
    AND "damageType" = 'Battle'
    AND rarity = ANY(p_rarities)
    AND "damageDealt" > 0
    AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp" AND "damageType" = 'Battle')
    AND "encounterId" IN (0, 1, 2)
  GROUP BY "Name", "encounterId", "set", rarity
),
cluster_agg AS (
  SELECT
    "Name" as boss_name,
    "encounterId" as encounter_id,
    "set",
    rarity,
    avg("damageDealt") as cluster_avg
  FROM "EOT_GR_data"
  WHERE "Season" = p_season
    AND "damageType" = 'Battle'
    AND rarity = ANY(p_rarities)
    AND "damageDealt" > 0
    AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp" AND "damageType" = 'Battle')
    AND "encounterId" IN (0, 1, 2)
    AND (
      coalesce(cluster_code, '') = coalesce((SELECT cluster_code FROM cluster_ctx LIMIT 1), '')
      OR "Guild" IN (SELECT guild_code FROM cluster_guilds)
    )
  GROUP BY "Name", "encounterId", "set", rarity
)
SELECT
  g.boss_name,
  CASE WHEN g.encounter_id IN (1,2) THEN 'Prime' ELSE 'Boss' END as encounter_type,
  (g.total_damage / nullif(g.battle_count,0)) as guild_avg_damage,
  c.cluster_avg as cluster_avg_damage,
  CASE
    WHEN c.cluster_avg > 0 THEN ((g.total_damage / nullif(g.battle_count,0)) / c.cluster_avg - 1) * 100
    ELSE 0
  END as vs_cluster_percent,
  g."set",
  g.rarity
FROM guild_agg g
LEFT JOIN cluster_agg c ON
  g.boss_name = c.boss_name
  AND coalesce(g.encounter_id, -1) = coalesce(c.encounter_id, -1)
  AND g."set" = c."set"
  AND g.rarity = c.rarity
ORDER BY vs_cluster_percent DESC NULLS LAST;
$$;

ALTER FUNCTION public.get_guild_vs_cluster_boss_performance(p_guild_code text, p_season text, p_rarities text[]) OWNER TO postgres;

CREATE FUNCTION public.get_guild_vs_cluster_performance(p_guild_code text, p_season text DEFAULT NULL::text) RETURNS TABLE(boss_name text, boss_level text, guild_damage bigint, cluster_avg_damage numeric, performance_ratio numeric)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_season TEXT;
  v_cluster_code TEXT;
BEGIN
  -- Get the latest season if not provided
  IF p_season IS NULL THEN
    SELECT MAX("Season") INTO v_season
    FROM "EOT_GR_data"
    WHERE "Season" ~ '^\d+$';
  ELSE
    v_season := p_season;
  END IF;

  -- Get the cluster code for this guild
  SELECT cluster_code INTO v_cluster_code
  FROM guild_config
  WHERE guild_code = p_guild_code;

  -- Return the comparison data
  RETURN QUERY
  WITH guild_performance AS (
    SELECT
      "Name" as boss_name,
      CASE
        WHEN rarity = 'Mythic' THEN 'M' || (set + 1)::text
        WHEN rarity = 'Legendary' THEN 'L' || (set + 1)::text
        ELSE rarity || (set + 1)::text
      END as boss_level,
      SUM("damageDealt") as total_damage
    FROM "EOT_GR_data"
    WHERE "Guild" = p_guild_code
      AND "Season" = v_season
      AND rarity IN ('Mythic', 'Legendary')
    GROUP BY "Name", rarity, set
  ),
  cluster_performance AS (
    SELECT
      e."Name" as boss_name,
      CASE
        WHEN e.rarity = 'Mythic' THEN 'M' || (e.set + 1)::text
        WHEN e.rarity = 'Legendary' THEN 'L' || (e.set + 1)::text
        ELSE e.rarity || (e.set + 1)::text
      END as boss_level,
      AVG(e."damageDealt") as avg_damage
    FROM "EOT_GR_data" e
    INNER JOIN guild_config gc ON gc.guild_code = e."Guild"
    WHERE e."Season" = v_season
      AND e.rarity IN ('Mythic', 'Legendary')
      AND COALESCE(gc.cluster_code, 'INDEPENDENT') = COALESCE(v_cluster_code, 'INDEPENDENT')
    GROUP BY e."Name", e.rarity, e.set
  )
  SELECT
    gp.boss_name::TEXT,
    gp.boss_level::TEXT,
    gp.total_damage::BIGINT,
    COALESCE(cp.avg_damage, 0)::NUMERIC,
    CASE
      WHEN cp.avg_damage > 0 THEN (gp.total_damage::NUMERIC / cp.avg_damage * 100)
      ELSE 100
    END::NUMERIC as performance_ratio
  FROM guild_performance gp
  LEFT JOIN cluster_performance cp
    ON cp.boss_name = gp.boss_name
    AND cp.boss_level = gp.boss_level
  ORDER BY gp.boss_level DESC, gp.boss_name;
END;
$_$;

ALTER FUNCTION public.get_guild_vs_cluster_performance(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_guild_vs_cluster_prime_performance(p_guild_code text, p_season text) RETURNS TABLE(prime_name text, guild_avg_damage numeric, cluster_avg_damage numeric, vs_cluster_percent numeric, set integer, rarity text)
    LANGUAGE sql
    AS $$
with cluster_ctx as (
  select cluster_code
  from guild_config
  where guild_code = p_guild_code
  limit 1
),
cluster_guilds as (
  select guild_code
  from guild_config
  where cluster_code in (select cluster_code from cluster_ctx)
),
guild_agg as (
  select
    "Name" as prime_name,
    "set",
    rarity,
    sum("damageDealt") as total_damage,
    count(*) as battle_count
  from "EOT_GR_data"
  where "Season" = p_season
    and "Guild" = p_guild_code
    and "damageType" = 'Battle'
    and rarity in ('Legendary','Mythic')
    and "damageDealt" > 0
    and not ("remainingHp" = 0 and "maxHp" > 0 and "damageDealt" < "maxHp" and "damageType" = 'Battle')
    and "encounterId" in (1, 2) -- primes only
  group by "Name", "set", rarity
),
cluster_agg as (
  select
    "Name" as prime_name,
    "set",
    rarity,
    avg("damageDealt") as cluster_avg
  from "EOT_GR_data"
  where "Season" = p_season
    and "damageType" = 'Battle'
    and rarity in ('Legendary','Mythic')
    and "damageDealt" > 0
    and not ("remainingHp" = 0 and "maxHp" > 0 and "damageDealt" < "maxHp" and "damageType" = 'Battle')
    and "encounterId" in (1, 2) -- primes only
    and (
      coalesce(cluster_code, '') = coalesce((select cluster_code from cluster_ctx limit 1), '')
      or "Guild" in (select guild_code from cluster_guilds)
    )
  group by "Name", "set", rarity
)
select
  g.prime_name,
  (g.total_damage / nullif(g.battle_count,0)) as guild_avg_damage,
  c.cluster_avg as cluster_avg_damage,
  case
    when c.cluster_avg > 0 then ((g.total_damage / nullif(g.battle_count,0)) / c.cluster_avg - 1) * 100
    else 0
  end as vs_cluster_percent,
  g."set",
  g.rarity
from guild_agg g
left join cluster_agg c on
  g.prime_name = c.prime_name
  and g."set" = c."set"
  and g.rarity = c.rarity
order by vs_cluster_percent desc nulls last;
$$;

ALTER FUNCTION public.get_guild_vs_cluster_prime_performance(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_hero_performance(p_guild_code text, p_side text, p_limit integer DEFAULT 20, p_season_count integer DEFAULT 4) RETURNS TABLE(hero_key text, uses bigint, wins bigint, losses bigint, win_rate numeric, avg_score numeric, avg_kills numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min_season INT;
BEGIN
  SELECT MAX(war_season) - p_season_count + 1 INTO v_min_season
  FROM guild_war_matches
  WHERE guild_code = p_guild_code;

  IF v_min_season IS NULL THEN
    v_min_season := 0;
  END IF;

  IF p_side = 'offense' THEN
    RETURN QUERY
    WITH battle_stats AS (
      SELECT
        b.attacker_units_json,
        b.score_earned,
        war_zone_captured(b.attempt_result, b.defender_units_json) AS is_capture,
        -- Kills ladder (20260406000002): stored count -> every defender dead on
        -- a capture -> count of defenders with no positive remainingHPAfter.
        -- NULL when there is no HP data to infer from, so avg_kills is absent
        -- rather than a misleading zero.
        CASE
          WHEN b.kill_count IS NOT NULL AND b.kill_count > 0 THEN b.kill_count::NUMERIC
          WHEN b.defender_units_json IS NOT NULL
            AND jsonb_typeof(b.defender_units_json) = 'array'
            AND jsonb_array_length(b.defender_units_json) > 0 THEN
            CASE
              WHEN b.attempt_result <> 'loss'
                AND NOT EXISTS (
                  SELECT 1 FROM jsonb_array_elements(b.defender_units_json) AS d
                  WHERE (d->>'remainingHPAfter') IS NOT NULL
                    AND (d->>'remainingHPAfter')::NUMERIC > 0
                ) THEN jsonb_array_length(b.defender_units_json)::NUMERIC
              WHEN EXISTS (
                SELECT 1 FROM jsonb_array_elements(b.defender_units_json) AS d
                WHERE (d->>'remainingHPAfter') IS NOT NULL
                  AND (d->>'remainingHPAfter')::NUMERIC > 0
              ) THEN (
                SELECT COUNT(*)::NUMERIC
                FROM jsonb_array_elements(b.defender_units_json) AS d
                WHERE NOT (
                  (d->>'remainingHPAfter') IS NOT NULL
                  AND (d->>'remainingHPAfter')::NUMERIC > 0
                )
              )
              ELSE NULL
            END
          ELSE NULL
        END AS inferred_kills
      FROM guild_war_battles b
      JOIN guild_war_matches m ON m.war_id = b.war_id AND m.guild_code = b.guild_code
      WHERE b.guild_code = p_guild_code
        AND b.is_guild_member = TRUE
        AND b.attacker_units_json IS NOT NULL
        AND m.war_season >= v_min_season
    ),
    hero_battles AS (
      SELECT
        COALESCE(h->>'heroKey', h->>'unitId') AS hero_key,
        bs.is_capture,
        bs.score_earned,
        bs.inferred_kills
      FROM battle_stats bs
      CROSS JOIN LATERAL jsonb_array_elements(bs.attacker_units_json) AS h
    )
    SELECT
      hb.hero_key,
      COUNT(*) AS uses,
      COUNT(*) FILTER (WHERE hb.is_capture) AS wins,
      COUNT(*) FILTER (WHERE NOT hb.is_capture) AS losses,
      CASE
        WHEN COUNT(*) > 0 THEN ROUND((COUNT(*) FILTER (WHERE hb.is_capture)::NUMERIC / COUNT(*)) * 100, 1)
        ELSE 0
      END AS win_rate,
      ROUND(AVG(hb.score_earned), 1) AS avg_score,
      CASE
        WHEN AVG(hb.inferred_kills) IS NOT NULL THEN ROUND(AVG(hb.inferred_kills), 1)
        ELSE NULL
      END AS avg_kills
    FROM hero_battles hb
    WHERE hb.hero_key IS NOT NULL
    GROUP BY hb.hero_key
    HAVING COUNT(*) >= 5
    ORDER BY uses DESC, win_rate DESC
    LIMIT p_limit;
  ELSE
    RETURN QUERY
    WITH battle_stats AS (
      SELECT
        b.defender_units_json,
        b.score_earned,
        war_zone_captured(b.attempt_result, b.defender_units_json) AS is_capture,
        -- Attacker units this defence killed.
        --
        -- 20260406000002 keyed this on `remainingHPBefore`. That field does
        -- not exist in this corpus -- 0 of 91,605 rows carry it (measured
        -- 2026-08-11), so re-landing that expression verbatim would have made
        -- avg_kills permanently NULL. The real convention is ABSENCE: a unit
        -- that survived carries remainingHPAfter (min observed 1, never 0), and
        -- a unit that died simply has no remainingHPAfter key. Validated
        -- against outcome: 2.97 inferred deaths on attacks that failed to
        -- capture vs 0.89 on attacks that captured.
        --
        -- Gated on at least one attacker entry HAVING HP data, so "no data to
        -- infer from" stays NULL instead of reading as a full 5-unit wipe.
        CASE
          WHEN b.attacker_units_json IS NOT NULL
            AND jsonb_typeof(b.attacker_units_json) = 'array'
            AND jsonb_array_length(b.attacker_units_json) > 0
            AND EXISTS (
              SELECT 1 FROM jsonb_array_elements(b.attacker_units_json) AS a
              WHERE (a->>'remainingHPAfter') IS NOT NULL
            ) THEN (
              SELECT COUNT(*)::NUMERIC
              FROM jsonb_array_elements(b.attacker_units_json) AS a
              WHERE NOT (
                (a->>'remainingHPAfter') IS NOT NULL
                AND (a->>'remainingHPAfter')::NUMERIC > 0
              )
            )
          ELSE NULL
        END AS inferred_kills
      FROM guild_war_battles b
      JOIN guild_war_matches m ON m.war_id = b.war_id AND m.guild_code = b.guild_code
      WHERE b.guild_code = p_guild_code
        AND b.is_guild_member = FALSE
        AND b.defender_units_json IS NOT NULL
        AND m.war_season >= v_min_season
    ),
    hero_battles AS (
      SELECT
        COALESCE(h->>'heroKey', h->>'unitId') AS hero_key,
        bs.is_capture,
        bs.score_earned,
        bs.inferred_kills
      FROM battle_stats bs
      CROSS JOIN LATERAL jsonb_array_elements(bs.defender_units_json) AS h
    )
    SELECT
      hb.hero_key,
      COUNT(*) AS uses,
      -- A defending hero "wins" when the attacker failed to capture.
      COUNT(*) FILTER (WHERE NOT hb.is_capture) AS wins,
      COUNT(*) FILTER (WHERE hb.is_capture) AS losses,
      CASE
        WHEN COUNT(*) > 0 THEN ROUND((COUNT(*) FILTER (WHERE NOT hb.is_capture)::NUMERIC / COUNT(*)) * 100, 1)
        ELSE 0
      END AS win_rate,
      -- Average score CONCEDED per attack against this hero (lower = better
      -- hold). Replaces `1000 - score_earned`, which had the wrong max and
      -- went negative -- the same correction WI-2790 made in get_lineup_stats.
      ROUND(AVG(hb.score_earned), 1) AS avg_score,
      CASE
        WHEN AVG(hb.inferred_kills) IS NOT NULL THEN ROUND(AVG(hb.inferred_kills), 1)
        ELSE NULL
      END AS avg_kills
    FROM hero_battles hb
    WHERE hb.hero_key IS NOT NULL
    GROUP BY hb.hero_key
    HAVING COUNT(*) >= 5
    ORDER BY uses DESC, win_rate DESC
    LIMIT p_limit;
  END IF;
END;
$$;

ALTER FUNCTION public.get_hero_performance(p_guild_code text, p_side text, p_limit integer, p_season_count integer) OWNER TO postgres;

CREATE FUNCTION public.get_hero_stat(base_stat integer, gear_level integer, stars integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    RETURN ROUND(
        base_stat * (1 + 0.25205 * (gear_level - 1)) * (1 + 0.1 * stars)
    )::INTEGER;
END;
$$;

ALTER FUNCTION public.get_hero_stat(base_stat integer, gear_level integer, stars integer) OWNER TO postgres;

CREATE FUNCTION public.get_homepage_statistics() RETURNS TABLE(active_players bigint, battles_tracked bigint, guilds bigint, total_damage bigint, veteran_players bigint, active_clusters bigint, latest_season text)
    LANGUAGE plpgsql
    AS $_$
BEGIN
  RETURN QUERY
  WITH base_stats AS (
    SELECT * FROM get_public_stats()
  ),
  additional_stats AS (
    SELECT
      COUNT(DISTINCT e."userId") as veterans,
      COUNT(DISTINCT gc.cluster_code) as clusters,
      MAX(e."Season") as latest_season
    FROM "EOT_GR_data" e
    LEFT JOIN guild_config gc ON e."Guild" = gc.guild_code
    WHERE e."userId" IS NOT NULL
      AND e."Season" ~ '^\d+$'
      AND e."userId" IN (
        SELECT e2."userId"
        FROM "EOT_GR_data" e2
        WHERE e2."userId" IS NOT NULL
          AND e2."Season" ~ '^\d+$'
        GROUP BY e2."userId"
        HAVING COUNT(DISTINCT e2."Season") >= 5
      )
  )
  SELECT
    bs.active_players,
    bs.battles_tracked,
    bs.guilds,
    bs.total_damage,
    ads.veterans as veteran_players,
    ads.clusters as active_clusters,
    ads.latest_season
  FROM base_stats bs
  CROSS JOIN additional_stats ads;
END;
$_$;

ALTER FUNCTION public.get_homepage_statistics() OWNER TO postgres;

CREATE FUNCTION public.get_hourly_activity(p_guild_code text, p_season text DEFAULT NULL::text, p_player_names text[] DEFAULT NULL::text[], p_roles text[] DEFAULT NULL::text[], p_boss_name text DEFAULT NULL::text, p_meta_team text DEFAULT NULL::text, p_rarities text[] DEFAULT NULL::text[]) RETURNS TABLE(hour_of_day integer, battle_count bigint, percentage numeric)
    LANGUAGE plpgsql STABLE
    AS $$
  declare
    total_battles bigint;
  begin
    select count(*) into total_battles
    from "EOT_GR_data" d
    left join player_mapping pm on pm.display_name = d."displayName" and pm.guild_code = d."Guild"
    where d."Guild" = p_guild_code
      and d."damageType" = 'Battle'
      and (p_season is null or d."Season" = p_season)
      and (p_player_names is null or d."displayName" = any(p_player_names))
      and (p_roles is null or pm.role::text = any(p_roles))
      and (p_boss_name is null or d."Name" ilike '%' || p_boss_name || '%')
      and (p_meta_team is null or pm.primary_team = p_meta_team or pm.secondary_team = p_meta_team or pm.tertiary_team = p_meta_team)
      and (p_rarities is null or d."rarity" = any(p_rarities))
      and coalesce(d."completedOn", d."timestamp", d."startedOn") is not null;

    if total_battles = 0 then
      total_battles := 1;
    end if;

    return query
    select
      extract(hour from coalesce(d."completedOn", d."timestamp", d."startedOn"))::int as hour_of_day,
      count(*)::bigint as battle_count,
      round((count(*)::numeric / total_battles) * 100, 1) as percentage
    from "EOT_GR_data" d
    left join player_mapping pm on pm.display_name = d."displayName" and pm.guild_code = d."Guild"
    where d."Guild" = p_guild_code
      and d."damageType" = 'Battle'
      and (p_season is null or d."Season" = p_season)
      and (p_player_names is null or d."displayName" = any(p_player_names))
      and (p_roles is null or pm.role::text = any(p_roles))
      and (p_boss_name is null or d."Name" ilike '%' || p_boss_name || '%')
      and (p_meta_team is null or pm.primary_team = p_meta_team or pm.secondary_team = p_meta_team or pm.tertiary_team = p_meta_team)
      and (p_rarities is null or d."rarity" = any(p_rarities))
      and coalesce(d."completedOn", d."timestamp", d."startedOn") is not null
    group by extract(hour from coalesce(d."completedOn", d."timestamp", d."startedOn"))::int
    order by hour_of_day;
  end;
  $$;

ALTER FUNCTION public.get_hourly_activity(p_guild_code text, p_season text, p_player_names text[], p_roles text[], p_boss_name text, p_meta_team text, p_rarities text[]) OWNER TO postgres;

CREATE FUNCTION public.get_invite_code_info(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invite RECORD;
BEGIN
  -- WI-6240 (B1): a possession-proof code must be indistinguishable from a
  -- nonexistent code through this anon-reachable probe.
  IF public.is_possession_proof_code(UPPER(p_code)) THEN
    RETURN jsonb_build_object(
      'valid', false,
      'error', 'Invite code not found'
    );
  END IF;

  SELECT
    pic.*,
    gc.display_name as guild_name
  INTO v_invite
  FROM player_invite_codes pic
  JOIN guild_config gc ON gc.guild_code = pic.guild_code
  WHERE pic.code = UPPER(p_code);

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'valid', false,
      'error', 'Invite code not found'
    );
  END IF;

  IF v_invite.used_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'valid', false,
      'error', 'This invite code has already been used'
    );
  END IF;

  IF v_invite.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'valid', false,
      'error', 'This invite code has been revoked'
    );
  END IF;

  IF v_invite.expires_at < NOW() THEN
    RETURN jsonb_build_object(
      'valid', false,
      'error', 'This invite code has expired'
    );
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'player_id', v_invite.player_id,
    'display_name', v_invite.display_name,
    'guild_code', v_invite.guild_code,
    'guild_name', v_invite.guild_name,
    'expires_at', v_invite.expires_at
  );
END;
$$;

ALTER FUNCTION public.get_invite_code_info(p_code text) OWNER TO postgres;

CREATE FUNCTION public.get_latest_guild_snapshots(p_cluster_code text DEFAULT NULL::text, p_guild_code text DEFAULT NULL::text) RETURNS TABLE(guild_code text, guild_name text, cluster_code text, cluster_name text, season integer, current_gr_ranking integer, total_battles bigint, active_players bigint, total_damage bigint, avg_damage_per_battle bigint, top_boss_hits json, veteran_count bigint, votlw_champions json, last_updated timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
  declare
      v_current_season integer;
  begin
      select coalesce(max("Season"), 1)
        into v_current_season
        from "EOT_GR_data"
       where "Season" is not null;

      return query
      with guild_stats as (
          select
              gc.guild_code,
              gc.display_name as guild_name,
              gc.cluster_code,
              cc.display_name as cluster_name,
              v_current_season as season,
              case when gc.current_rank ~ '^\d+$' then gc.current_rank::integer else null end as current_gr_ranking,
              count(distinct d."battleId")     as total_battles,
              count(distinct d."displayName")  as active_players,
              coalesce(sum(d."damageDealt"),0) as total_damage,
              case when count(d."battleId") > 0
                   then coalesce(sum(d."damageDealt"),0) / count(d."battleId")
                   else 0 end                  as avg_damage_per_battle,
              gc.last_updated
          from guild_config gc
          left join cluster_config cc on gc.cluster_code = cc.cluster_code
          left join "EOT_GR_data" d
            on d."Guild" = gc.guild_code
           and d."Season" = v_current_season
          where gc.is_active = true
            and (p_cluster_code is null or gc.cluster_code = p_cluster_code)
            and (p_guild_code   is null or gc.guild_code    = p_guild_code)
          group by
              gc.guild_code,
              gc.display_name,
              gc.cluster_code,
              cc.display_name,
              gc.current_rank,
              gc.last_updated
      ),
      top_hits as (
          select
              d."Guild" as guild_code,
              json_agg(
                  json_build_object(
                      'boss_name', d."Name",
                      'damage',    d."damageDealt",
                      'player',    d."displayName"
                  )
                  order by d."damageDealt" desc
              ) filter (where rn <= 5) as top_boss_hits
          from (
              select
                  "Guild",
                  "Name",
                  "damageDealt",
                  "displayName",
                  row_number() over (partition by "Guild" order by "damageDealt" desc) as rn
              from "EOT_GR_data"
              where "Season" = v_current_season
                and "damageDealt" > 0
          ) d
          where rn <= 5
          group by d."Guild"
      ),
      veterans as (
          select guild_code, count(*) as veteran_count
            from veteran_count_public
           group by guild_code
      ),
      votlw as (
          select
              guild_code,
              json_agg(
                  json_build_object(
                      'season', season,
                      'player', player_name
                  )
                  order by season desc
              ) as votlw_champions
            from votlw_winners_public
           where season >= v_current_season - 5
           group by guild_code
      )
      select
          gs.guild_code,
          gs.guild_name,
          gs.cluster_code,
          gs.cluster_name,
          gs.season,
          gs.current_gr_ranking,
          gs.total_battles,
          gs.active_players,
          gs.total_damage,
          gs.avg_damage_per_battle,
          coalesce(th.top_boss_hits, '[]'::json),
          coalesce(v.veteran_count, 0),
          coalesce(vw.votlw_champions, '[]'::json),
          gs.last_updated
      from guild_stats gs
      left join top_hits th on gs.guild_code = th.guild_code
      left join veterans v on gs.guild_code = v.guild_code
      left join votlw vw on gs.guild_code = vw.guild_code
      order by case when gs.current_gr_ranking is null then 999999 else gs.current_gr_ranking end;
  end;
  $_$;

ALTER FUNCTION public.get_latest_guild_snapshots(p_cluster_code text, p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_latest_season() RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- NULL when the table is empty / all season_num NULL (was COALESCE(..., 84)).
  -- season_num is the integer season column, so no lex-sort hazard.
  SELECT MAX(season_num)::text
  FROM public."EOT_GR_data";
$$;

ALTER FUNCTION public.get_latest_season() OWNER TO postgres;

