CREATE FUNCTION public.get_leader_analytics_guilds(p_access_level text DEFAULT 'global'::text, p_cluster_code text DEFAULT NULL::text, p_guild_code text DEFAULT NULL::text) RETURNS TABLE(guild_code text, display_name text, guild_tag text, enabled boolean, token_offender_threshold integer, token_abuser_threshold integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    gc.guild_code::text,
    gc.display_name::text,
    gc.guild_tag::text,
    gc.enabled,
    gc.token_offender_threshold,
    gc.token_abuser_threshold
  FROM public.guild_config gc
  WHERE gc.enabled = true
    AND (
      p_access_level = 'global'
      OR (p_access_level = 'cluster' AND p_cluster_code IS NOT NULL AND gc.cluster_code = p_cluster_code)
      OR (p_access_level = 'guild' AND p_guild_code IS NOT NULL AND gc.guild_code = p_guild_code)
    );
$$;

ALTER FUNCTION public.get_leader_analytics_guilds(p_access_level text, p_cluster_code text, p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_leader_analytics_player_mappings(p_access_level text DEFAULT 'global'::text, p_cluster_code text DEFAULT NULL::text, p_guild_code text DEFAULT NULL::text) RETURNS TABLE(display_name text, guild_code text, user_id uuid, primary_boss text, secondary_boss text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    pwc.display_name::text,
    pwc.guild_code::text,
    pwc.user_id,
    pwc.primary_boss::text,
    pwc.secondary_boss::text
  FROM public.player_with_cluster pwc
  WHERE (
    p_access_level = 'global'
    OR (p_access_level = 'cluster' AND p_cluster_code IS NOT NULL AND pwc.cluster_code = p_cluster_code)
    OR (p_access_level = 'guild' AND p_guild_code IS NOT NULL AND pwc.guild_code = p_guild_code)
  );
$$;

ALTER FUNCTION public.get_leader_analytics_player_mappings(p_access_level text, p_cluster_code text, p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_lineup_stats(p_guild_code text, p_side text DEFAULT 'offense'::text, p_limit integer DEFAULT 20, p_season_count integer DEFAULT 4) RETURNS TABLE(lineup_id text, units_json jsonb, machine_of_war jsonb, uses bigint, wins bigint, losses bigint, win_rate numeric, avg_score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min_season INT;
BEGIN
  SELECT MAX(war_season) - p_season_count + 1 INTO v_min_season
  FROM guild_war_matches
  WHERE guild_code = p_guild_code;

  IF v_min_season IS NULL THEN
    v_min_season := 0;
  END IF;

  IF p_side = 'offense' THEN
    RETURN QUERY
    SELECT
      b.attacker_lineup_id AS lineup_id,
      l.units_json,
      l.machine_of_war,
      COUNT(*) AS uses,
      COUNT(*) FILTER (WHERE war_zone_captured(b.attempt_result, b.defender_units_json)) AS wins,
      COUNT(*) FILTER (WHERE NOT war_zone_captured(b.attempt_result, b.defender_units_json)) AS losses,
      CASE
        WHEN COUNT(*) > 0 THEN ROUND(
          (COUNT(*) FILTER (WHERE war_zone_captured(b.attempt_result, b.defender_units_json))::NUMERIC / COUNT(*)) * 100, 1)
        ELSE 0
      END AS win_rate,
      ROUND(AVG(b.score_earned), 1) AS avg_score
    FROM guild_war_battles b
    JOIN guild_war_matches m ON m.war_id = b.war_id AND m.guild_code = b.guild_code
    LEFT JOIN guild_war_lineups l ON l.lineup_id = b.attacker_lineup_id
    WHERE b.guild_code = p_guild_code
      AND b.is_guild_member = TRUE
      AND b.attacker_lineup_id IS NOT NULL
      AND m.war_season >= v_min_season
    GROUP BY b.attacker_lineup_id, l.units_json, l.machine_of_war
    HAVING COUNT(*) >= 3
    ORDER BY uses DESC, win_rate DESC
    LIMIT p_limit;
  ELSE
    RETURN QUERY
    SELECT
      b.defender_lineup_id AS lineup_id,
      l.units_json,
      l.machine_of_war,
      COUNT(*) AS uses,
      -- Defensive win = the attacker failed to capture (zone held).
      COUNT(*) FILTER (WHERE NOT war_zone_captured(b.attempt_result, b.defender_units_json)) AS wins,
      COUNT(*) FILTER (WHERE war_zone_captured(b.attempt_result, b.defender_units_json)) AS losses,
      CASE
        WHEN COUNT(*) > 0 THEN ROUND(
          (COUNT(*) FILTER (WHERE NOT war_zone_captured(b.attempt_result, b.defender_units_json))::NUMERIC / COUNT(*)) * 100, 1)
        ELSE 0
      END AS win_rate,
      -- Average score CONCEDED per attack against this lineup (lower = better hold).
      ROUND(AVG(b.score_earned), 1) AS avg_score
    FROM guild_war_battles b
    JOIN guild_war_matches m ON m.war_id = b.war_id AND m.guild_code = b.guild_code
    LEFT JOIN guild_war_lineups l ON l.lineup_id = b.defender_lineup_id
    WHERE b.guild_code = p_guild_code
      AND b.is_guild_member = FALSE
      AND b.defender_lineup_id IS NOT NULL
      AND m.war_season >= v_min_season
    GROUP BY b.defender_lineup_id, l.units_json, l.machine_of_war
    HAVING COUNT(*) >= 3
    ORDER BY uses DESC, win_rate DESC
    LIMIT p_limit;
  END IF;
END;
$$;

ALTER FUNCTION public.get_lineup_stats(p_guild_code text, p_side text, p_limit integer, p_season_count integer) OWNER TO postgres;

CREATE FUNCTION public.get_meta_analysis_compositions(p_season text, p_rarity text, p_set integer, p_cluster_code text DEFAULT NULL::text, p_guild_code text DEFAULT NULL::text, p_encounter_id integer DEFAULT NULL::integer, p_min_battles integer DEFAULT 5, p_limit integer DEFAULT 20) RETURNS TABLE(boss_name text, encounter_id integer, composition_key text, hero_unit_ids text[], mow_unit_id text, avg_damage numeric, max_damage numeric, min_damage numeric, median_damage numeric, battles_count integer, stability_score numeric, stability_rank text, player_count integer, guild_count integer, coef_variation numeric, standard_deviation numeric, categories text[])
    LANGUAGE plpgsql
    AS $$
declare
  rec record;
  display_names text[];
  matched_categories text[];
  meta_rec record;
  trigger_arr text[];
  all_matched boolean;
  any_matched boolean;
begin
  for rec in
    with filtered as (
      select
        "Name" as boss_name,
        coalesce("encounterId", 0) as encounter_id,
        "heroDetails"::jsonb as hero_details,
        "machineOfWarDetails"::jsonb as mow_details,
        "damageDealt" as damage_dealt,
        "displayName" as display_name,
        "userId" as user_id,
        "Guild" as guild_code
      from "EOT_GR_data"
      where "Season" = p_season
        and "damageType" = 'Battle'
        and rarity = p_rarity
        and "set" = p_set
        and (p_encounter_id is null or "encounterId" = p_encounter_id)
        and "damageDealt" > 0
        and not ("remainingHp" = 0 and "maxHp" > 0 and "damageDealt" < "maxHp" and "damageType" = 'Battle')
        and "displayName" is not null
        and "userId" is not null
        and (
          (p_cluster_code is not null and cluster_code = p_cluster_code)
          or (p_cluster_code is null and p_guild_code is not null and "Guild" = p_guild_code)
        )
    ),
    parsed as (
      select
        f.boss_name,
        f.encounter_id,
        f.damage_dealt,
        f.display_name,
        f.user_id,
        f.guild_code,
        (select coalesce(array_agg(elem->>'unitId' order by elem->>'unitId'), '{}'::text[])
         from jsonb_array_elements(coalesce(f.hero_details, '[]'::jsonb)) as elem
         where elem ? 'unitId'
        ) as hero_unit_ids,
        (f.mow_details ->> 'unitId') as mow_unit_id
      from filtered f
    ),
    normalized as (
      select
        p.boss_name,
        p.encounter_id,
        p.damage_dealt,
        p.display_name,
        p.user_id,
        p.guild_code,
        p.hero_unit_ids,
        p.mow_unit_id,
        array_to_string(
          case
            when p.mow_unit_id is not null and p.mow_unit_id <> '' then p.hero_unit_ids || ('[MOW]' || p.mow_unit_id)
            else p.hero_unit_ids
          end,
          '|'
        ) as composition_key
      from parsed p
      where array_length(p.hero_unit_ids, 1) > 0
    ),
    compositions as (
      select
        n.boss_name,
        n.encounter_id,
        n.composition_key,
        n.hero_unit_ids,
        n.mow_unit_id,
        avg(n.damage_dealt) as avg_damage,
        max(n.damage_dealt) as max_damage,
        min(n.damage_dealt) as min_damage,
        percentile_cont(0.5) within group (order by n.damage_dealt) as median_damage,
        count(*) as battles_count,
        count(distinct n.user_id) as player_count,
        count(distinct n.guild_code) as guild_count,
        stddev_pop(n.damage_dealt) as std_dev,
        avg(n.damage_dealt) as mean_damage
      from normalized n
      group by n.boss_name, n.encounter_id, n.composition_key, n.hero_unit_ids, n.mow_unit_id
      having count(*) >= coalesce(p_min_battles, 5)
    ),
    with_stability as (
      select
        c.boss_name,
        c.encounter_id,
        c.composition_key,
        c.hero_unit_ids,
        c.mow_unit_id,
        c.avg_damage,
        c.max_damage,
        c.min_damage,
        c.median_damage,
        c.battles_count,
        c.player_count,
        c.guild_count,
        c.std_dev,
        case
          when c.mean_damage > 0 then (c.std_dev / c.mean_damage) * 100
          else 0
        end as coef_variation
      from compositions c
    ),
    scored as (
      select
        ws.boss_name,
        ws.encounter_id,
        ws.composition_key,
        ws.hero_unit_ids,
        ws.mow_unit_id,
        ws.avg_damage,
        ws.max_damage,
        ws.min_damage,
        ws.median_damage,
        ws.battles_count,
        ws.player_count,
        ws.guild_count,
        ws.coef_variation,
        ws.std_dev,
        case
          when ws.coef_variation < 15 then greatest(75, 100 - ws.coef_variation)
          when ws.coef_variation < 30 then greatest(50, 75 - (ws.coef_variation - 15))
          else greatest(0, 50 - (ws.coef_variation - 30))
        end as stability_score,
        case
          when ws.coef_variation < 15 then 'High'
          when ws.coef_variation < 30 then 'Medium'
          else 'Low'
        end as stability_rank
      from with_stability ws
    )
    select * from scored
    order by avg_damage desc, stability_score desc
    limit coalesce(p_limit, 20)
  loop
    select coalesce(array_agg(coalesce(hm.display_name, uid) order by coalesce(hm.display_name, uid)), '{}'::text[])
    into display_names
    from unnest(rec.hero_unit_ids) as uid
    left join hero_mappings hm on hm.unit_id = uid;

    matched_categories := '{}'::text[];

    for meta_rec in select team_name, trigger_heroes, match_type from meta_teams where trigger_heroes is not null
    loop
      select array_agg(val) into trigger_arr
      from jsonb_array_elements_text(meta_rec.trigger_heroes) as val;

      if trigger_arr is null or array_length(trigger_arr, 1) is null then
        continue;
      end if;

      if meta_rec.match_type = 'all' then
        all_matched := true;
        for i in 1..array_length(trigger_arr, 1) loop
          if not (trigger_arr[i] = any(display_names)) then
            all_matched := false;
            exit;
          end if;
        end loop;
        if all_matched then
          matched_categories := array_append(matched_categories, meta_rec.team_name);
        end if;
      elsif meta_rec.match_type = 'any' then
        any_matched := false;
        for i in 1..array_length(trigger_arr, 1) loop
          if trigger_arr[i] = any(display_names) then
            any_matched := true;
            exit;
          end if;
        end loop;
        if any_matched then
          matched_categories := array_append(matched_categories, meta_rec.team_name);
        end if;
      end if;
    end loop;

    boss_name := rec.boss_name;
    encounter_id := rec.encounter_id;
    composition_key := rec.composition_key;
    hero_unit_ids := rec.hero_unit_ids;
    mow_unit_id := rec.mow_unit_id;
    avg_damage := rec.avg_damage;
    max_damage := rec.max_damage;
    min_damage := rec.min_damage;
    median_damage := rec.median_damage;
    battles_count := rec.battles_count::int;
    stability_score := rec.stability_score;
    stability_rank := rec.stability_rank;
    player_count := rec.player_count::int;
    guild_count := rec.guild_count::int;
    coef_variation := rec.coef_variation;
    standard_deviation := rec.std_dev;
    categories := matched_categories;

    return next;
  end loop;
end;
$$;

ALTER FUNCTION public.get_meta_analysis_compositions(p_season text, p_rarity text, p_set integer, p_cluster_code text, p_guild_code text, p_encounter_id integer, p_min_battles integer, p_limit integer) OWNER TO postgres;

CREATE FUNCTION public.get_meta_atlas_anonymous(p_min_attacks integer DEFAULT 10, p_exclude_overkills boolean DEFAULT true, p_exclude_retreats boolean DEFAULT true, p_retreat_threshold integer DEFAULT 10000, p_seasons text[] DEFAULT NULL::text[]) RETURNS TABLE(team_hash text, team_composition text, meta_team text, boss_type text, boss_unit_id text, sub_boss_name text, encounter_index integer, encounter_type text, rarity text, set_num integer, rarity_set text, season text, attack_count bigint, damage_max bigint, damage_p90 numeric, damage_p75 numeric, damage_avg numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  -- Step 1: Get ALL battles (no overkill filtering yet), pre-compute team_hash
  WITH all_battles AS (
    SELECT
      d."heroDetails",
      d."machineOfWarDetails",
      d."type" as parent_boss_type,
      d."unitId" as d_boss_unit_id,
      COALESCE(d."encounterIndex", 0) as enc_index,
      d."encounterType",
      d.rarity as battle_rarity,
      d.set as battle_set,
      d."Season" as battle_season,
      d."damageDealt",
      d."remainingHp",
      generate_team_hash(d."heroDetails", d."machineOfWarDetails") as t_hash,
      (d."remainingHp" IS NOT NULL AND d."remainingHp" = 0) as is_overkill
    FROM "EOT_GR_data" d
    WHERE d."damageType" = 'Battle'
      AND d."heroDetails" IS NOT NULL
      AND d."heroDetails" != '[]'
      AND d."heroDetails" != ''
      AND d."type" IS NOT NULL
      AND d."type" != ''
      AND (NOT p_exclude_retreats OR d."damageDealt" >= p_retreat_threshold)
      AND (p_seasons IS NULL OR d."Season" = ANY(p_seasons))
  ),
  -- Step 2: Compute non-overkill averages per team+boss group (the baseline)
  group_baselines AS (
    SELECT
      ab.t_hash,
      ab.parent_boss_type,
      ab.enc_index,
      ab.battle_rarity,
      ab.battle_set,
      ab.battle_season,
      AVG(ab."damageDealt")::numeric as non_overkill_avg
    FROM all_battles ab
    WHERE NOT ab.is_overkill
      AND ab.t_hash IS NOT NULL
    GROUP BY ab.t_hash, ab.parent_boss_type, ab.enc_index,
             ab.battle_rarity, ab.battle_set, ab.battle_season
  ),
  -- Step 3: Filter — keep non-overkills + qualifying overkills (damage >= group avg)
  battle_data AS (
    SELECT ab.*
    FROM all_battles ab
    LEFT JOIN group_baselines gb
      ON gb.t_hash = ab.t_hash
      AND gb.parent_boss_type = ab.parent_boss_type
      AND gb.enc_index = ab.enc_index
      AND gb.battle_rarity = ab.battle_rarity
      AND gb.battle_set = ab.battle_set
      AND gb.battle_season = ab.battle_season
    WHERE ab.t_hash IS NOT NULL
      AND (
        NOT p_exclude_overkills           -- Flag off: include everything
        OR NOT ab.is_overkill             -- Always include non-overkills
        OR ab."damageDealt" >= COALESCE(gb.non_overkill_avg, 0)  -- Qualifying overkills
      )
  ),
  -- Step 4: Aggregate (same as before)
  aggregated AS (
    SELECT
      b.t_hash,
      get_team_display(b."heroDetails", b."machineOfWarDetails") as t_composition,
      get_meta_team(b."heroDetails") as t_meta_team,
      b.parent_boss_type as t_boss_type,
      mode() WITHIN GROUP (ORDER BY b.d_boss_unit_id) as t_boss_unit_id,
      b.enc_index as t_encounter_index,
      b."encounterType" as t_encounter_type,
      b.battle_rarity as t_rarity,
      b.battle_set as t_set,
      get_rarity_set(b.battle_rarity, b.battle_set) as t_rarity_set,
      b.battle_season as t_season,
      COUNT(*) as t_attack_count,
      MAX(b."damageDealt") as t_damage_max,
      PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY b."damageDealt")::numeric as t_damage_p90,
      PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY b."damageDealt")::numeric as t_damage_p75,
      AVG(b."damageDealt")::numeric as t_damage_avg
    FROM battle_data b
    GROUP BY
      b.t_hash,
      get_team_display(b."heroDetails", b."machineOfWarDetails"),
      get_meta_team(b."heroDetails"),
      b.parent_boss_type,
      b.enc_index,
      b."encounterType",
      b.battle_rarity,
      b.battle_set,
      get_rarity_set(b.battle_rarity, b.battle_set),
      b.battle_season
    HAVING COUNT(*) >= p_min_attacks
  )
  SELECT
    a.t_hash,
    a.t_composition,
    a.t_meta_team,
    a.t_boss_type,
    a.t_boss_unit_id,
    COALESCE(bm.boss_name, a.t_boss_type) as t_sub_boss_name,
    a.t_encounter_index,
    a.t_encounter_type,
    a.t_rarity,
    a.t_set,
    a.t_rarity_set,
    a.t_season,
    a.t_attack_count,
    a.t_damage_max,
    a.t_damage_p90,
    a.t_damage_p75,
    a.t_damage_avg
  FROM aggregated a
  LEFT JOIN boss_mapping bm ON bm.boss_type = a.t_boss_type AND bm.encounter_index = a.t_encounter_index
  ORDER BY a.t_attack_count DESC;
END;
$$;

ALTER FUNCTION public.get_meta_atlas_anonymous(p_min_attacks integer, p_exclude_overkills boolean, p_exclude_retreats boolean, p_retreat_threshold integer, p_seasons text[]) OWNER TO postgres;

CREATE FUNCTION public.get_meta_atlas_banded_by_player_power(p_min_attacks_per_band integer DEFAULT 10, p_exclude_overkills boolean DEFAULT true, p_exclude_retreats boolean DEFAULT true, p_retreat_threshold integer DEFAULT 10000, p_seasons text[] DEFAULT NULL::text[]) RETURNS TABLE(team_hash text, team_composition text, meta_team text, boss_type text, sub_boss_name text, encounter_type text, rarity text, tier bigint, season text, power_band integer, power_band_floor numeric, power_band_ceil numeric, attack_count bigint, damage_max bigint, damage_p90 numeric, damage_p75 numeric, damage_avg numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH banded AS (
    SELECT
      d."heroDetails",
      d."machineOfWarDetails",
      d."Name"                                                         AS boss_name,
      get_sub_boss_name(d."Name", d."encounterIndex")                  AS sub_boss,
      generate_team_hash(d."heroDetails", d."machineOfWarDetails")     AS team_hash_v,
      get_team_display(d."heroDetails", d."machineOfWarDetails")       AS team_disp,
      get_meta_team(d."heroDetails")                                   AS meta_team_v,
      d."encounterType",
      d.rarity                                                         AS battle_rarity,
      d.tier                                                           AS battle_tier,
      d."Season"                                                       AS battle_season,
      d."damageDealt",
      d."remainingHp",
      pm.player_power,
      NTILE(5) OVER (
        PARTITION BY
          d."Name",
          get_sub_boss_name(d."Name", d."encounterIndex"),
          d."encounterType",
          d.rarity, d.tier, d."Season",
          generate_team_hash(d."heroDetails", d."machineOfWarDetails")
        ORDER BY pm.player_power NULLS FIRST
      )                                                                AS power_band
    FROM "EOT_GR_data" d
    JOIN player_mapping pm
      ON d."userId" = pm.player_id
     AND pm.is_current = true
    WHERE d."damageType" = 'Battle'
      AND d."heroDetails" IS NOT NULL
      AND d."heroDetails" <> '[]'
      AND d."heroDetails" <> ''
      AND (NOT p_exclude_retreats OR d."damageDealt" >= p_retreat_threshold)
      AND (NOT p_exclude_overkills OR d."remainingHp" IS NULL OR d."remainingHp" > 0)
      AND (p_seasons IS NULL OR d."Season" = ANY(p_seasons))
      AND pm.player_power IS NOT NULL
  ),
  aggregated AS (
    SELECT
      b.team_hash_v                                                          AS t_hash,
      b.team_disp                                                            AS t_composition,
      b.meta_team_v                                                          AS t_meta_team,
      b.boss_name                                                            AS t_boss_type,
      b.sub_boss                                                             AS t_sub_boss_name,
      b."encounterType"                                                      AS t_encounter_type,
      b.battle_rarity                                                        AS t_rarity,
      b.battle_tier                                                          AS t_tier,
      b.battle_season                                                        AS t_season,
      b.power_band                                                           AS t_power_band,
      MIN(b.player_power)::numeric                                           AS t_band_floor,
      MAX(b.player_power)::numeric                                           AS t_band_ceil,
      COUNT(*)                                                               AS t_attack_count,
      MAX(b."damageDealt")                                                   AS t_damage_max,
      PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY b."damageDealt")::numeric AS t_damage_p90,
      PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY b."damageDealt")::numeric AS t_damage_p75,
      AVG(b."damageDealt")::numeric                                          AS t_damage_avg
    FROM banded b
    WHERE b.team_hash_v IS NOT NULL
    GROUP BY
      b.team_hash_v, b.team_disp, b.meta_team_v,
      b.boss_name, b.sub_boss, b."encounterType",
      b.battle_rarity, b.battle_tier, b.battle_season,
      b.power_band
    HAVING COUNT(*) >= p_min_attacks_per_band
  )
  SELECT
    a.t_hash, a.t_composition, a.t_meta_team, a.t_boss_type, a.t_sub_boss_name,
    a.t_encounter_type, a.t_rarity, a.t_tier, a.t_season,
    a.t_power_band, a.t_band_floor, a.t_band_ceil,
    a.t_attack_count, a.t_damage_max, a.t_damage_p90, a.t_damage_p75, a.t_damage_avg
  FROM aggregated a
  ORDER BY
    a.t_boss_type, a.t_meta_team, a.t_rarity, a.t_tier, a.t_power_band;
END;
$$;

ALTER FUNCTION public.get_meta_atlas_banded_by_player_power(p_min_attacks_per_band integer, p_exclude_overkills boolean, p_exclude_retreats boolean, p_retreat_threshold integer, p_seasons text[]) OWNER TO postgres;

CREATE FUNCTION public.get_meta_atlas_banded_by_team_power(p_min_attacks_per_band integer DEFAULT 10, p_exclude_overkills boolean DEFAULT true, p_exclude_retreats boolean DEFAULT true, p_retreat_threshold integer DEFAULT 10000, p_seasons text[] DEFAULT NULL::text[]) RETURNS TABLE(team_hash text, team_composition text, meta_team text, boss_type text, sub_boss_name text, encounter_type text, rarity text, tier bigint, season text, power_band integer, power_band_floor numeric, power_band_ceil numeric, mow_power_floor numeric, mow_power_ceil numeric, attack_count bigint, damage_max bigint, damage_p99 numeric, damage_p90 numeric, damage_p75 numeric, damage_p50 numeric, damage_avg numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH banded AS (
    SELECT
      d."heroDetails",
      d."machineOfWarDetails",
      d."Name"                                                         AS boss_name,
      get_sub_boss_name(d."Name", d."encounterIndex")                  AS sub_boss,
      generate_team_hash(d."heroDetails", d."machineOfWarDetails")     AS team_hash_v,
      get_team_display(d."heroDetails", d."machineOfWarDetails")       AS team_disp,
      get_meta_team(d."heroDetails")                                   AS meta_team_v,
      d."encounterType",
      d.rarity                                                         AS battle_rarity,
      d.tier                                                           AS battle_tier,
      d."Season"                                                       AS battle_season,
      d."damageDealt",
      get_team_hero_power(d."heroDetails")                             AS team_hero_power,
      get_mow_power(d."machineOfWarDetails")                           AS mow_power,
      NTILE(5) OVER (
        PARTITION BY
          d."Name",
          get_sub_boss_name(d."Name", d."encounterIndex"),
          d."encounterType",
          d.rarity, d.tier, d."Season",
          generate_team_hash(d."heroDetails", d."machineOfWarDetails")
        ORDER BY get_team_hero_power(d."heroDetails") NULLS FIRST
      )                                                                AS power_band
    FROM "EOT_GR_data" d
    WHERE d."damageType" = 'Battle'
      AND d."heroDetails" IS NOT NULL
      AND d."heroDetails" <> '[]'
      AND d."heroDetails" <> ''
      AND (NOT p_exclude_retreats OR d."damageDealt" >= p_retreat_threshold)
      AND (NOT p_exclude_overkills OR d."remainingHp" IS NULL OR d."remainingHp" > 0)
      AND (p_seasons IS NULL OR d."Season" = ANY(p_seasons))
  ),
  aggregated AS (
    SELECT
      b.team_hash_v                                                          AS t_hash,
      b.team_disp                                                            AS t_composition,
      b.meta_team_v                                                          AS t_meta_team,
      b.boss_name                                                            AS t_boss_type,
      b.sub_boss                                                             AS t_sub_boss_name,
      b."encounterType"                                                      AS t_encounter_type,
      b.battle_rarity                                                        AS t_rarity,
      b.battle_tier                                                          AS t_tier,
      b.battle_season                                                        AS t_season,
      b.power_band                                                           AS t_power_band,
      MIN(b.team_hero_power)::numeric                                        AS t_band_floor,
      MAX(b.team_hero_power)::numeric                                        AS t_band_ceil,
      MIN(b.mow_power)::numeric                                              AS t_mow_floor,
      MAX(b.mow_power)::numeric                                              AS t_mow_ceil,
      COUNT(*)                                                               AS t_attack_count,
      MAX(b."damageDealt")                                                   AS t_damage_max,
      PERCENTILE_CONT(0.99) WITHIN GROUP (ORDER BY b."damageDealt")::numeric AS t_damage_p99,
      PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY b."damageDealt")::numeric AS t_damage_p90,
      PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY b."damageDealt")::numeric AS t_damage_p75,
      PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY b."damageDealt")::numeric AS t_damage_p50,
      AVG(b."damageDealt")::numeric                                          AS t_damage_avg
    FROM banded b
    WHERE b.team_hash_v IS NOT NULL
      AND b.team_hero_power IS NOT NULL
    GROUP BY
      b.team_hash_v, b.team_disp, b.meta_team_v,
      b.boss_name, b.sub_boss, b."encounterType",
      b.battle_rarity, b.battle_tier, b.battle_season,
      b.power_band
    HAVING COUNT(*) >= p_min_attacks_per_band
  )
  SELECT
    a.t_hash, a.t_composition, a.t_meta_team, a.t_boss_type, a.t_sub_boss_name,
    a.t_encounter_type, a.t_rarity, a.t_tier, a.t_season,
    a.t_power_band, a.t_band_floor, a.t_band_ceil,
    a.t_mow_floor, a.t_mow_ceil,
    a.t_attack_count, a.t_damage_max,
    a.t_damage_p99, a.t_damage_p90, a.t_damage_p75, a.t_damage_p50, a.t_damage_avg
  FROM aggregated a
  ORDER BY
    a.t_boss_type, a.t_meta_team, a.t_rarity, a.t_tier, a.t_power_band;
END;
$$;

ALTER FUNCTION public.get_meta_atlas_banded_by_team_power(p_min_attacks_per_band integer, p_exclude_overkills boolean, p_exclude_retreats boolean, p_retreat_threshold integer, p_seasons text[]) OWNER TO postgres;

CREATE FUNCTION public.get_meta_atlas_coverage(p_min_attacks integer DEFAULT 10) RETURNS TABLE(total_team_boss_combos bigint, total_attacks bigint, boss_types_covered bigint, rarities_covered bigint, seasons_covered bigint, avg_attacks_per_combo numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  WITH stats AS (
    SELECT
      team_hash,
      boss_type,
      rarity,
      season,
      attack_count
    FROM get_meta_atlas_anonymous(p_min_attacks, true, true, 10000, NULL)
  )
  SELECT
    COUNT(*)::bigint as total_team_boss_combos,
    SUM(attack_count)::bigint as total_attacks,
    COUNT(DISTINCT boss_type)::bigint as boss_types_covered,
    COUNT(DISTINCT rarity)::bigint as rarities_covered,
    COUNT(DISTINCT season)::bigint as seasons_covered,
    AVG(attack_count)::numeric as avg_attacks_per_combo
  FROM stats;
$$;

ALTER FUNCTION public.get_meta_atlas_coverage(p_min_attacks integer) OWNER TO postgres;

