CREATE FUNCTION public.get_meta_atlas_distinct_rarity_sets() RETURNS TABLE(rarity_set text, sort_order integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  WITH sets AS (
    SELECT DISTINCT rarity_set
    FROM meta_atlas_data
    WHERE rarity_set IS NOT NULL
  )
  SELECT
    s.rarity_set,
    CASE
      WHEN s.rarity_set = 'L1' THEN 1
      WHEN s.rarity_set = 'L2' THEN 2
      WHEN s.rarity_set = 'L3' THEN 3
      WHEN s.rarity_set = 'L4' THEN 4
      WHEN s.rarity_set = 'L5' THEN 5
      WHEN s.rarity_set = 'M1' THEN 10
      WHEN s.rarity_set = 'M2' THEN 11
      WHEN s.rarity_set = 'M3' THEN 12
      WHEN s.rarity_set = 'M4' THEN 13
      WHEN s.rarity_set = 'M5' THEN 14
      ELSE 99
    END as sort_order
  FROM sets s
  ORDER BY sort_order;
$$;

