CREATE FUNCTION public.get_meta_atlas_team_floor(p_team_hash text, p_boss_type text, p_boss_unit_id text DEFAULT NULL::text, p_encounter_index integer DEFAULT 0, p_rarity_set text DEFAULT NULL::text, p_season text DEFAULT NULL::text, p_exclude_overkills boolean DEFAULT true, p_exclude_retreats boolean DEFAULT true, p_retreat_threshold integer DEFAULT 10000) RETURNS TABLE(team_hash text, unit_id text, min_rank_name text, min_rank_index integer, min_stars integer, sample_hits integer, sample_players integer, p90_damage numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_p90 numeric;
BEGIN
  SELECT damage_p90
  INTO v_p90
  FROM meta_atlas_data
  WHERE team_hash = p_team_hash
    AND boss_type = p_boss_type
    AND encounter_index = p_encounter_index
    AND rarity_set = p_rarity_set
    AND season = p_season
  LIMIT 1;

  IF v_p90 IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH team_hits AS (
    SELECT
      d."displayName" as display_name,
      d."damageDealt" as damage,
      d."heroDetails"::jsonb as hero_details,
      d."machineOfWarDetails"::jsonb as mow_details
    FROM "EOT_GR_data" d
    WHERE d."damageType" = 'Battle'
      AND d."heroDetails" IS NOT NULL
      AND d."heroDetails" != '[]'
      AND d."heroDetails" != ''
      AND (
        d."type" = p_boss_type
        OR ((d."type" IS NULL OR d."type" = '') AND d."Name" = p_boss_type)
      )
      AND COALESCE(d."encounterIndex", 0) = p_encounter_index
      AND get_rarity_set(d.rarity, d.set) = p_rarity_set
      AND d."Season" = p_season
      AND generate_team_hash(d."heroDetails", d."machineOfWarDetails") = p_team_hash
      AND (p_boss_unit_id IS NULL OR d."unitId" = p_boss_unit_id)
      AND (NOT p_exclude_retreats OR d."damageDealt" >= p_retreat_threshold)
      AND (NOT p_exclude_overkills OR d."remainingHp" IS NULL OR d."remainingHp" > 0)
      AND d."damageDealt" >= v_p90
  ),
  team_players AS (
    SELECT DISTINCT display_name
    FROM team_hits
    WHERE display_name IS NOT NULL AND display_name != ''
  ),
  player_ids AS (
    SELECT DISTINCT pm.user_id
    FROM player_mapping pm
    JOIN team_players tp
      ON lower(trim(pm.display_name)) = lower(trim(tp.display_name))
    WHERE pm.is_current = true AND pm.user_id IS NOT NULL
  ),
  team_units AS (
    SELECT DISTINCT unit_id
    FROM (
      SELECT jsonb_array_elements(th.hero_details) ->> 'unitId' as unit_id
      FROM team_hits th
      UNION ALL
      SELECT th.mow_details ->> 'unitId' as unit_id
      FROM team_hits th
      WHERE th.mow_details IS NOT NULL AND th.mow_details != 'null'
    ) units
    WHERE unit_id IS NOT NULL AND unit_id != ''
  ),
  roster_rows AS (
    SELECT
      hm.unit_id,
      pr.rank_name,
      pr.stars,
      pr.user_id
    FROM player_roster pr
    JOIN hero_mappings hm ON hm.id = pr.hero_mapping_id
    WHERE pr.user_id IN (SELECT user_id FROM player_ids)
      AND hm.unit_id IN (SELECT unit_id FROM team_units)
  ),
  roster_mapped AS (
    SELECT
      unit_id,
      user_id,
      stars,
      CASE rank_name
        WHEN 'Stone I' THEN 0
        WHEN 'Stone II' THEN 1
        WHEN 'Stone III' THEN 2
        WHEN 'Iron I' THEN 3
        WHEN 'Iron II' THEN 4
        WHEN 'Iron III' THEN 5
        WHEN 'Bronze I' THEN 6
        WHEN 'Bronze II' THEN 7
        WHEN 'Bronze III' THEN 8
        WHEN 'Silver I' THEN 9
        WHEN 'Silver II' THEN 10
        WHEN 'Silver III' THEN 11
        WHEN 'Gold I' THEN 12
        WHEN 'Gold II' THEN 13
        WHEN 'Gold III' THEN 14
        WHEN 'Diamond I' THEN 15
        WHEN 'Diamond II' THEN 16
        WHEN 'Diamond III' THEN 17
        WHEN 'Adamantium I' THEN 18
        WHEN 'Adamantium II' THEN 19
        WHEN 'Adamantium III' THEN 20
        WHEN 'Mythic I' THEN 21
        WHEN 'Mythic II' THEN 22
        WHEN 'Mythic III' THEN 23
        ELSE NULL
      END as rank_index
    FROM roster_rows
  ),
  roster_floor AS (
    SELECT
      unit_id,
      MIN(rank_index) as min_rank_index,
      MIN(stars) as min_stars
    FROM roster_mapped
    GROUP BY unit_id
  ),
  roster_resolved AS (
    SELECT
      rf.unit_id,
      rf.min_rank_index,
      rf.min_stars,
      CASE rf.min_rank_index
        WHEN 0 THEN 'Stone I'
        WHEN 1 THEN 'Stone II'
        WHEN 2 THEN 'Stone III'
        WHEN 3 THEN 'Iron I'
        WHEN 4 THEN 'Iron II'
        WHEN 5 THEN 'Iron III'
        WHEN 6 THEN 'Bronze I'
        WHEN 7 THEN 'Bronze II'
        WHEN 8 THEN 'Bronze III'
        WHEN 9 THEN 'Silver I'
        WHEN 10 THEN 'Silver II'
        WHEN 11 THEN 'Silver III'
        WHEN 12 THEN 'Gold I'
        WHEN 13 THEN 'Gold II'
        WHEN 14 THEN 'Gold III'
        WHEN 15 THEN 'Diamond I'
        WHEN 16 THEN 'Diamond II'
        WHEN 17 THEN 'Diamond III'
        WHEN 18 THEN 'Adamantium I'
        WHEN 19 THEN 'Adamantium II'
        WHEN 20 THEN 'Adamantium III'
        WHEN 21 THEN 'Mythic I'
        WHEN 22 THEN 'Mythic II'
        WHEN 23 THEN 'Mythic III'
        ELSE NULL
      END as min_rank_name
    FROM roster_floor rf
  ),
  sample_stats AS (
    SELECT
      COUNT(*)::int as sample_hits,
      (SELECT COUNT(*) FROM team_players)::int as sample_players
    FROM team_hits
  )
  SELECT
    p_team_hash as team_hash,
    tu.unit_id,
    rr.min_rank_name,
    rr.min_rank_index,
    rr.min_stars,
    ss.sample_hits,
    ss.sample_players,
    v_p90 as p90_damage
  FROM team_units tu
  LEFT JOIN roster_resolved rr ON rr.unit_id = tu.unit_id
  CROSS JOIN sample_stats ss;
END;
$$;

ALTER FUNCTION public.get_meta_atlas_team_floor(p_team_hash text, p_boss_type text, p_boss_unit_id text, p_encounter_index integer, p_rarity_set text, p_season text, p_exclude_overkills boolean, p_exclude_retreats boolean, p_retreat_threshold integer) OWNER TO postgres;

CREATE FUNCTION public.get_meta_team(hero_details text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  team_hero_names text[];
  meta_record RECORD;
  trigger_hero text;
  match_count int;
  required_count int;
BEGIN
  -- Return NULL for invalid/empty hero details
  IF hero_details IS NULL OR hero_details = '' OR hero_details = '[]' THEN
    RETURN NULL;
  END IF;

  BEGIN
    -- Get display names for all heroes in the team
    SELECT array_agg(COALESCE(hm.display_name, heroes.unit_id))
    INTO team_hero_names
    FROM (
      SELECT jsonb_array_elements(hero_details::jsonb) ->> 'unitId' as unit_id
    ) heroes
    LEFT JOIN hero_mappings hm ON hm.unit_id = heroes.unit_id
    WHERE heroes.unit_id IS NOT NULL;

    IF team_hero_names IS NULL THEN
      RETURN NULL;
    END IF;

    -- Check each meta team (filtered by is_meta=true, ordered by sort_order)
    FOR meta_record IN
      SELECT team_name, trigger_heroes, match_type
      FROM meta_teams
      WHERE is_meta = true
        AND trigger_heroes IS NOT NULL
        AND jsonb_array_length(trigger_heroes) > 0
      ORDER BY sort_order ASC
    LOOP
      required_count := jsonb_array_length(meta_record.trigger_heroes);
      match_count := 0;

      -- Count how many trigger heroes are in the team
      FOR trigger_hero IN
        SELECT jsonb_array_elements_text(meta_record.trigger_heroes)
      LOOP
        IF trigger_hero = ANY(team_hero_names) THEN
          match_count := match_count + 1;
        END IF;
      END LOOP;

      -- Check match based on match_type
      IF meta_record.match_type = 'any' AND match_count > 0 THEN
        RETURN meta_record.team_name;
      ELSIF meta_record.match_type = 'all' AND match_count = required_count THEN
        RETURN meta_record.team_name;
      ELSIF meta_record.match_type = 'exact' AND match_count = required_count AND array_length(team_hero_names, 1) = required_count THEN
        RETURN meta_record.team_name;
      END IF;
    END LOOP;

    RETURN NULL;
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
END;
$$;

ALTER FUNCTION public.get_meta_team(hero_details text) OWNER TO postgres;

CREATE FUNCTION public.get_mow_power(p_mow_details text) RETURNS bigint
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN p_mow_details IS NULL OR p_mow_details = '' OR p_mow_details = '{}' THEN NULL
    ELSE (p_mow_details::jsonb->>'power')::bigint
  END;
$$;

ALTER FUNCTION public.get_mow_power(p_mow_details text) OWNER TO postgres;

CREATE FUNCTION public.get_my_guild_membership() RETURNS TABLE(guild_code text, guild_display_name text, guild_enabled boolean, cluster_code text, cluster_set boolean, member_role text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := (SELECT auth.uid());
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Access denied: authentication required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    pm.guild_code,
    gc.display_name,
    COALESCE(gc.enabled, false),
    gc.cluster_code::text,
    gc.cluster_code IS NOT NULL,
    pm.role::text
  FROM public.player_mapping pm
  LEFT JOIN public.guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = v_user_id
    AND pm.is_current = true
  LIMIT 1;
END;
$$;

ALTER FUNCTION public.get_my_guild_membership() OWNER TO postgres;

CREATE FUNCTION public.get_my_onboarding_state() RETURNS TABLE(has_claimed_profile boolean, api_key_configured boolean, api_key_valid boolean, guild_resolved boolean, blocking_condition text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := (SELECT auth.uid());
  v_row record;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Access denied: authentication required'
      USING ERRCODE = '42501';
  END IF;

  SELECT
    pm.tacticus_api_key_encrypted IS NOT NULL AS key_configured,
    COALESCE(pm.api_key_is_valid, false) AS key_valid,
    pm.guild_code IS NOT NULL AND pm.guild_code <> 'GLOBAL' AS guild_ok
  INTO v_row
  FROM public.player_mapping pm
  WHERE pm.user_id = v_user_id
    AND pm.is_current = true
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      false, false, false, false, 'unclaimed_profile'::text;
    RETURN;
  END IF;

  RETURN QUERY SELECT
    true,
    v_row.key_configured,
    v_row.key_valid,
    v_row.guild_ok,
    CASE
      WHEN NOT v_row.key_configured THEN 'no_api_key'
      WHEN NOT v_row.key_valid THEN 'invalid_api_key'
      WHEN NOT v_row.guild_ok THEN 'no_guild'
      ELSE NULL
    END::text;
END;
$$;

ALTER FUNCTION public.get_my_onboarding_state() OWNER TO postgres;

CREATE FUNCTION public.get_my_sync_status() RETURNS TABLE(api_key_configured boolean, api_key_valid boolean, api_key_last_verified timestamp with time zone, last_sync_at timestamp with time zone, guild_code text, guild_sync_status text, guild_last_sync_at timestamp with time zone, guild_has_recent_error boolean, guild_coverage_pct numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := (SELECT auth.uid());
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Access denied: authentication required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    (pm.tacticus_api_key_encrypted IS NOT NULL) AS api_key_configured,
    COALESCE(pm.api_key_is_valid, false) AS api_key_valid,
    pm.api_key_last_verified,
    (pm.last_sync_at AT TIME ZONE 'UTC') AS last_sync_at,
    pm.guild_code,
    gss.status AS guild_sync_status,
    gss.last_sync AS guild_last_sync_at,
    (gss.last_error IS NOT NULL) AS guild_has_recent_error,
    cov.coverage_percentage AS guild_coverage_pct
  FROM public.player_mapping pm
  LEFT JOIN public.guild_sync_status gss ON gss.guild_code = pm.guild_code
  LEFT JOIN public.api_key_coverage cov ON cov.guild_code = pm.guild_code
  WHERE pm.user_id = v_user_id
    AND pm.is_current = true
  LIMIT 1;
END;
$$;

ALTER FUNCTION public.get_my_sync_status() OWNER TO postgres;

CREATE FUNCTION public.get_mythic_boss_hp() RETURNS TABLE(boss_name text, set_level integer, max_hp bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH mythic_battles AS (
    -- Get all Mythic boss battles with damage and remaining HP
    SELECT
      g."Name" as boss_name,
      g."set" as set_level,
      g."damageDealt" + g."remainingHp" as total_hp,
      g."encounterId"
    FROM "EOT_GR_data" g
    WHERE
      g."rarity" = 'Mythic'
      AND g."encounterId" = 0  -- Main bosses only
      AND g."damageType" = 'Battle'
      AND g."damageDealt" > 0
      AND g."Name" IS NOT NULL
  ),
  max_hp_per_boss AS (
    -- Get the maximum HP seen for each boss/level combination
    SELECT
      boss_name,
      set_level,
      MAX(total_hp) as max_hp
    FROM mythic_battles
    GROUP BY boss_name, set_level
  )
  SELECT
    boss_name::TEXT,
    set_level::INT,
    max_hp::BIGINT
  FROM max_hp_per_boss
  WHERE max_hp > 0
  ORDER BY set_level DESC, boss_name;
END;
$$;

ALTER FUNCTION public.get_mythic_boss_hp() OWNER TO postgres;

CREATE FUNCTION public.get_platform_summary_metrics() RETURNS TABLE(registered_users bigint, clusters_with_guilds bigint, distinct_guilds_battle bigint, player_mappings bigint, distinct_players_battle bigint, boss_battle_records bigint, guild_war_battles bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    (select count(*) from auth.users)::bigint,
    (select count(*) from public.clusters c
       where c.is_active is true
         and exists (
           select 1 from public.guild_config g
           where g.cluster_code = c.cluster_code
         ))::bigint,
    (select count(distinct "Guild") from public."EOT_GR_data")::bigint,
    (select count(*) from public.player_mapping)::bigint,
    (select count(distinct "userId") from public."EOT_GR_data")::bigint,
    (select count(*) from public."EOT_GR_data")::bigint,
    (select count(*) from public.guild_war_battles)::bigint;
$$;

ALTER FUNCTION public.get_platform_summary_metrics() OWNER TO postgres;

CREATE FUNCTION public.get_player_activity_summary(p_guild_code text, p_days integer DEFAULT 7) RETURNS TABLE(player_name text, total_activities bigint, last_activity_date date, last_activity_at timestamp with time zone, days_since_active integer, activity_types text[])
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    gwa.player_name::TEXT,
    COUNT(*)::BIGINT as total_activities,
    MAX(gwa.attempt_start_time::DATE) as last_activity_date,
    MAX(gwa.attempt_start_time) as last_activity_at,
    (CURRENT_DATE - MAX(gwa.attempt_start_time::DATE))::INT as days_since_active,
    ARRAY_AGG(DISTINCT gwa.attempt_status)::TEXT[] as activity_types
  FROM guild_war_player_attempts gwa
  WHERE gwa.guild_code = p_guild_code
    AND gwa.is_guild_member = TRUE
    AND gwa.attempt_start_time >= NOW() - (p_days || ' days')::INTERVAL
  GROUP BY gwa.player_name
  ORDER BY MAX(gwa.attempt_start_time) DESC;
END;
$$;

ALTER FUNCTION public.get_player_activity_summary(p_guild_code text, p_days integer) OWNER TO postgres;

CREATE FUNCTION public.get_player_boss_avg_damage(p_guild_code text) RETURNS TABLE(display_name text, boss_name text, boss_set integer, avg_damage numeric, battle_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        d."displayName" as display_name,
        d."Name" as boss_name,
        d."set" as boss_set,
        AVG(CASE WHEN d."damageDealt" > 0 THEN d."damageDealt" END)::numeric as avg_damage,
        COUNT(CASE WHEN d."damageDealt" > 0 THEN 1 END)::integer as battle_count
    FROM "EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
        AND d."encounterId" = 0  -- Main bosses only
        AND d."Name" IS NOT NULL
        AND d."rarity" IN ('Legendary', 'Mythic')  -- ✅ FIXED: Use rarity instead of tier >= 4
        AND d."damageType" = 'Battle'  -- Real battles only
        AND d."damageDealt" > 0  -- Valid damage only
    GROUP BY d."displayName", d."Name", d."set"
    HAVING COUNT(CASE WHEN d."damageDealt" > 0 THEN 1 END) >= 3  -- At least 3 battles for reliability
    ORDER BY d."displayName", d."set", d."Name";
END;
$$;

ALTER FUNCTION public.get_player_boss_avg_damage(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_player_boss_performance(guild_code_param text, season_param text) RETURNS TABLE(display_name text, boss_name text, encounter_id integer, player_avg numeric, battle_count integer, biggest_hit bigint, player_vs_guild_avg numeric, player_vs_cluster_avg numeric, set_num integer, tier integer, rarity text, boss_preference text)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cluster_code TEXT;
BEGIN
  SELECT cluster_code INTO v_cluster_code
  FROM guild_config
  WHERE guild_code = guild_code_param
  LIMIT 1;

  RETURN QUERY
  WITH player_boss_stats AS (
    SELECT
      e."displayName",
      e."Name" as name,
      COALESCE(e."encounterId", 0)::INTEGER as enc_id,
      e.tier as tier_val,
      e.set as set_val,
      e.rarity as rarity_val,
      SUM(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      )::NUMERIC as non_sweep_damage,
      COUNT(*) FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      )::INTEGER as non_sweep_count,
      array_agg(e."damageDealt"::numeric) FILTER (
        WHERE e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp"
      ) as sweep_damages,
      MAX(e."damageDealt") as b_hit
    FROM "EOT_GR_data" e
    WHERE e."Season" = season_param
      AND e."Guild" = guild_code_param
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
    GROUP BY e."displayName", e."Name", e."encounterId", e.tier, e.set, e.rarity
  ),
  -- Guild baseline averages: sweep-free
  -- IMPORTANT: alias EOT_GR_data as `e` so unqualified `rarity` / `tier`
  -- can't collide with the RETURNS TABLE OUT params of the same name.
  guild_avg AS (
    SELECT
      e."Name" as name,
      COALESCE(e."encounterId", 0)::INTEGER as enc_id,
      e.rarity as rarity_val,
      AVG(e."damageDealt")::NUMERIC as g_avg
    FROM "EOT_GR_data" e
    WHERE e."Season" = season_param
      AND e."Guild" = guild_code_param
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
    GROUP BY e."Name", e."encounterId", e.rarity
  ),
  cluster_avg AS (
    SELECT
      e."Name" as name,
      COALESCE(e."encounterId", 0)::INTEGER as enc_id,
      e.rarity as rarity_val,
      AVG(e."damageDealt")::NUMERIC as c_avg
    FROM "EOT_GR_data" e
    INNER JOIN guild_config gc ON gc.guild_code = e."Guild"
    WHERE e."Season" = season_param
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      AND gc.cluster_code = v_cluster_code
      AND gc.cluster_code IS NOT NULL
    GROUP BY e."Name", e."encounterId", e.rarity
  ),
  boss_prefs AS (
    SELECT
      pm.display_name,
      bp.boss_key,
      bp.preference
    FROM player_mapping pm
    CROSS JOIN LATERAL (
      SELECT key as boss_key, value as preference
      FROM jsonb_each_text(COALESCE(pm.boss_preferences, '{}'::jsonb))
    ) bp
    WHERE pm.guild_code = guild_code_param
      AND pm.is_current = true
  )
  SELECT
    p."displayName" as display_name,
    p.name as boss_name,
    p.enc_id as encounter_id,
    CASE
      WHEN COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0) > 0
      THEN (
        (COALESCE(p.non_sweep_damage, 0) + COALESCE(qualifying_sweep_sum(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))
        / (COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))
      )
      ELSE 0
    END as player_avg,
    (COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))::INTEGER as battle_count,
    p.b_hit as biggest_hit,
    CASE
      WHEN g.g_avg > 0 THEN ROUND((
        (
          (COALESCE(p.non_sweep_damage, 0) + COALESCE(qualifying_sweep_sum(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))
          / NULLIF(COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0), 0)
          / g.g_avg
        ) - 1) * 100, 2)
      ELSE 0
    END as player_vs_guild_avg,
    CASE
      WHEN c.c_avg > 0 THEN ROUND((
        (
          (COALESCE(p.non_sweep_damage, 0) + COALESCE(qualifying_sweep_sum(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), c.c_avg)), 0))
          / NULLIF(COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), c.c_avg)), 0), 0)
          / c.c_avg
        ) - 1) * 100, 2)
      ELSE 0
    END as player_vs_cluster_avg,
    p.set_val as set_num,
    p.tier_val::INTEGER as tier,
    p.rarity_val as rarity,
    COALESCE(bp.preference, 'neutral') as boss_preference
  FROM player_boss_stats p
  LEFT JOIN guild_avg g ON p.name = g.name AND p.enc_id = g.enc_id AND p.rarity_val = g.rarity_val
  LEFT JOIN cluster_avg c ON p.name = c.name AND p.enc_id = c.enc_id AND p.rarity_val = c.rarity_val
  LEFT JOIN boss_prefs bp ON p."displayName" = bp.display_name AND bp.boss_key = CONCAT('main_', p.name)
  ORDER BY p."displayName", p.rarity_val DESC, p.set_val, p.enc_id;
END;
$$;

ALTER FUNCTION public.get_player_boss_performance(guild_code_param text, season_param text) OWNER TO postgres;

CREATE FUNCTION public.get_player_boss_performance(p_guild_code text, p_season text, p_display_name text, p_rarities text[] DEFAULT ARRAY['Legendary'::text, 'Mythic'::text]) RETURNS TABLE(display_name text, user_id uuid, boss_name text, tier integer, set integer, rarity text, encounter_id integer, token_usage_label text, player_avg numeric, guild_avg numeric, cluster_avg numeric, battle_count integer, weighted_contribution numeric, vs_cluster_pct numeric, vs_guild_pct numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cluster_code TEXT;
BEGIN
  SELECT gc.cluster_code INTO v_cluster_code
  FROM guild_config gc
  WHERE gc.guild_code = p_guild_code
  LIMIT 1;

  RETURN QUERY
  WITH player_boss_stats AS (
    SELECT
      e."displayName" as dn,
      pm.user_id as uid,
      e."Name" as boss,
      COALESCE(e."encounterId", 0)::INTEGER as enc_id,
      e.tier as tier_val,
      e.set as set_val,
      e.rarity as rarity_val,
      -- Non-sweep aggregates
      SUM(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      )::NUMERIC as non_sweep_damage,
      COUNT(*) FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      )::INTEGER as non_sweep_count,
      -- Sweep damages array for qualifying exception
      array_agg(e."damageDealt"::numeric) FILTER (
        WHERE e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp"
      ) as sweep_damages,
      -- Total damage (all battles including sweeps) for weighted contribution
      SUM(e."damageDealt")::NUMERIC as total_dmg
    FROM "EOT_GR_data" e
    LEFT JOIN player_mapping pm ON pm.display_name = e."displayName"
      AND pm.guild_code = e."Guild"
      AND pm.is_current = true
    WHERE e."Season" = p_season
      AND e."Guild" = p_guild_code
      AND e."displayName" = p_display_name
      AND e."damageType" = 'Battle'
      AND e.rarity = ANY(p_rarities)
      AND e."damageDealt" > 0
    GROUP BY e."displayName", pm.user_id, e."Name", e."encounterId", e.tier, e.set, e.rarity
  ),
  -- Guild baseline averages: sweep-free (unchanged)
  guild_avg_cte AS (
    SELECT
      d."Name" as boss,
      COALESCE(d."encounterId", 0)::INTEGER as enc_id,
      d.rarity as rarity_val,
      AVG(d."damageDealt")::NUMERIC as g_avg
    FROM "EOT_GR_data" d
    WHERE d."Season" = p_season
      AND d."Guild" = p_guild_code
      AND d."damageType" = 'Battle'
      AND d.rarity = ANY(p_rarities)
      AND d."damageDealt" > 0
      AND NOT (d."remainingHp" = 0 AND d."maxHp" > 0 AND d."damageDealt" < d."maxHp")
    GROUP BY d."Name", d."encounterId", d.rarity
  ),
  -- Cluster baseline averages: sweep-free (unchanged)
  cluster_avg_cte AS (
    SELECT
      e."Name" as boss,
      COALESCE(e."encounterId", 0)::INTEGER as enc_id,
      e.rarity as rarity_val,
      AVG(e."damageDealt")::NUMERIC as c_avg
    FROM "EOT_GR_data" e
    INNER JOIN guild_config gc ON gc.guild_code = e."Guild"
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity = ANY(p_rarities)
      AND e."damageDealt" > 0
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      AND gc.cluster_code = v_cluster_code
    GROUP BY e."Name", e."encounterId", e.rarity
  ),
  guild_total_cte AS (
    SELECT SUM(d."damageDealt")::NUMERIC as total
    FROM "EOT_GR_data" d
    WHERE d."Season" = p_season
      AND d."Guild" = p_guild_code
      AND d."damageType" = 'Battle'
      AND d.rarity = ANY(p_rarities)
      AND d."damageDealt" > 0
  )
  SELECT
    p.dn,
    p.uid,
    CONCAT(p.boss, '_', p.rarity_val),
    p.tier_val::INTEGER,
    p.set_val,
    p.rarity_val,
    p.enc_id,
    CASE
      WHEN p.enc_id IN (1, 2) THEN 'Leg. Primes'
      ELSE CONCAT('L', p.set_val + 1, ' ', p.boss)
    END,
    -- player_avg: non-sweep + qualifying sweeps (vs guild avg)
    CASE
      WHEN COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0) > 0
      THEN (
        (COALESCE(p.non_sweep_damage, 0) + COALESCE(qualifying_sweep_sum(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))
        / (COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))
      )
      ELSE 0
    END,
    g.g_avg,
    c.c_avg,
    (COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))::INTEGER,
    CASE
      WHEN gt.total > 0 THEN (p.total_dmg / gt.total) * 100
      ELSE 0
    END,
    -- vs_cluster_pct: use cluster avg as threshold for qualifying sweeps
    CASE
      WHEN c.c_avg > 0 THEN ROUND((
        (
          (COALESCE(p.non_sweep_damage, 0) + COALESCE(qualifying_sweep_sum(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), c.c_avg)), 0))
          / NULLIF(COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), c.c_avg)), 0), 0)
          / c.c_avg
        ) - 1) * 100, 2)
      ELSE 0
    END,
    -- vs_guild_pct: use guild avg as threshold for qualifying sweeps
    CASE
      WHEN g.g_avg > 0 THEN ROUND((
        (
          (COALESCE(p.non_sweep_damage, 0) + COALESCE(qualifying_sweep_sum(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))
          / NULLIF(COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0), 0)
          / g.g_avg
        ) - 1) * 100, 2)
      ELSE 0
    END
  FROM player_boss_stats p
  LEFT JOIN guild_avg_cte g ON p.boss = g.boss AND p.enc_id = g.enc_id AND p.rarity_val = g.rarity_val
  LEFT JOIN cluster_avg_cte c ON p.boss = c.boss AND p.enc_id = c.enc_id AND p.rarity_val = c.rarity_val
  CROSS JOIN guild_total_cte gt
  ORDER BY p.rarity_val DESC, p.set_val, p.enc_id;
END;
$$;

ALTER FUNCTION public.get_player_boss_performance(p_guild_code text, p_season text, p_display_name text, p_rarities text[]) OWNER TO postgres;

CREATE FUNCTION public.get_player_boss_performance(p_guild_code text, p_season text, p_player_name text, p_boss_name text DEFAULT NULL::text, p_rarity text DEFAULT 'Legendary'::text) RETURNS TABLE(player_id text, player_name text, boss_name text, tier integer, encounter_id integer, rarity text, player_avg numeric, guild_avg numeric, cluster_avg numeric, vs_guild_pct numeric, vs_cluster_pct numeric, battle_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_player_id TEXT;
  cluster_code_var TEXT;
BEGIN
  -- Resolve player name to player_id
  SELECT pm.player_id INTO target_player_id
  FROM player_mapping pm
  WHERE pm.display_name = p_player_name
    AND pm.is_current = true
  LIMIT 1;

  IF target_player_id IS NULL THEN
    SELECT pm.player_id INTO target_player_id
    FROM player_mapping pm
    WHERE pm.display_name = p_player_name
    ORDER BY pm.updated_at DESC
    LIMIT 1;
  END IF;

  IF target_player_id IS NULL THEN
    RETURN;
  END IF;

  -- Get cluster code
  SELECT gc.cluster_code INTO cluster_code_var
  FROM guild_config gc
  WHERE gc.guild_code = p_guild_code;

  RETURN QUERY
  WITH player_stats AS (
    SELECT
      e."userId" as player_id,
      pm.display_name as current_player_name,
      e."Name" as boss_name,
      e."tier",
      e."encounterId",
      e."rarity",
      AVG(e."damageDealt") as avg_damage,
      COUNT(*) as battle_count
    FROM "EOT_GR_data" e
    LEFT JOIN player_mapping pm ON e."userId" = pm.player_id AND pm.is_current = true
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e."damageDealt" > 0
      AND e."userId" = target_player_id
      AND e."rarity" = p_rarity
      AND (p_boss_name IS NULL OR e."Name" = p_boss_name)
    GROUP BY e."userId", pm.display_name, e."Name", e."tier", e."encounterId", e."rarity"
  ),
  guild_stats AS (
    SELECT
      e."Name" as boss_name,
      e."tier",
      e."encounterId",
      e."rarity",
      AVG(e."damageDealt") as guild_avg
    FROM "EOT_GR_data" e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e."damageDealt" > 0
      AND e."rarity" = p_rarity
      AND (p_boss_name IS NULL OR e."Name" = p_boss_name)
    GROUP BY e."Name", e."tier", e."encounterId", e."rarity"
  ),
  cluster_stats AS (
    SELECT
      e."Name" as boss_name,
      e."tier",
      e."encounterId",
      e."rarity",
      AVG(e."damageDealt") as cluster_avg
    FROM "EOT_GR_data" e
    JOIN guild_config gc ON e."Guild" = gc.guild_code
    WHERE gc.cluster_code = cluster_code_var
      AND e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e."damageDealt" > 0
      AND e."rarity" = p_rarity
      AND (p_boss_name IS NULL OR e."Name" = p_boss_name)
    GROUP BY e."Name", e."tier", e."encounterId", e."rarity"
  )
  SELECT
    ps.player_id::TEXT,
    COALESCE(ps.current_player_name, 'Unknown Player')::TEXT as player_name,
    ps.boss_name::TEXT,
    ps.tier,
    ps.encounterId,
    ps.rarity::TEXT,
    ps.avg_damage as player_avg,
    gs.guild_avg,
    cs.cluster_avg,
    ROUND(((ps.avg_damage - gs.guild_avg) / NULLIF(gs.guild_avg, 0) * 100)::numeric, 1) as vs_guild_pct,
    ROUND(((ps.avg_damage - cs.cluster_avg) / NULLIF(cs.cluster_avg, 0) * 100)::numeric, 1) as vs_cluster_pct,
    ps.battle_count
  FROM player_stats ps
  LEFT JOIN guild_stats gs ON (
    ps.boss_name = gs.boss_name
    AND ps.tier = gs.tier
    AND ps.encounterId = gs.encounterId
    AND ps.rarity = gs.rarity
  )
  LEFT JOIN cluster_stats cs ON (
    ps.boss_name = cs.boss_name
    AND ps.tier = cs.tier
    AND ps.encounterId = cs.encounterId
    AND ps.rarity = cs.rarity
  )
  ORDER BY ps.boss_name, ps.tier, ps.encounterId;
END;
$$;

ALTER FUNCTION public.get_player_boss_performance(p_guild_code text, p_season text, p_player_name text, p_boss_name text, p_rarity text) OWNER TO postgres;

CREATE FUNCTION public.get_player_boss_performance_cluster(p_guild_code text, p_season text, p_cluster_code text DEFAULT NULL::text) RETURNS TABLE(player_name text, guild_code text, boss_level text, battles_fought integer, total_damage numeric, avg_damage numeric, max_damage numeric, min_damage numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    e."displayName" as player_name,
    e."Guild" as guild_code,
    CASE
      WHEN e.rarity = 'Mythic' THEN 'M' || (e.set + 1)::text
      WHEN e.rarity = 'Legendary' THEN 'L' || (e.set + 1)::text
      WHEN e.rarity = 'Epic' THEN 'E' || (e.set + 1)::text
      WHEN e.rarity = 'Rare' THEN 'R' || (e.set + 1)::text
      WHEN e.rarity = 'Uncommon' THEN 'U' || (e.set + 1)::text
      WHEN e.rarity = 'Common' THEN 'C' || (e.set + 1)::text
      ELSE e.rarity || (e.set + 1)::text
    END as boss_level,
    COUNT(*)::integer as battles,
    SUM(e."damageDealt") as total_dmg,
    ROUND(AVG(e."damageDealt"), 0) as avg_dmg,
    MAX(e."damageDealt") as max_dmg,
    MIN(CASE WHEN e."damageDealt" > 0 THEN e."damageDealt" END) as min_dmg
  FROM "EOT_GR_data" e
  WHERE e."Guild" = p_guild_code
    AND e."Season" = p_season
    AND (p_cluster_code IS NULL OR e.cluster_code = p_cluster_code)
    AND e."damageDealt" > 0
  GROUP BY e."displayName", e."Guild", e.rarity, e.set
  ORDER BY total_dmg DESC;
END;
$$;

ALTER FUNCTION public.get_player_boss_performance_cluster(p_guild_code text, p_season text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_player_boss_performance_flexible(guild_code_param text, min_battles_param integer DEFAULT 1) RETURNS TABLE(display_name text, boss_name text, avg_player_damage numeric, avg_guild_damage numeric, battle_count bigint, player_vs_guild_avg numeric, has_sufficient_data boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  WITH caller_authorization AS MATERIALIZED (
    SELECT
      COALESCE(
        NULLIF(NULLIF(current_setting('role', true), ''), 'none'),
        NULLIF(session_user, '')
      ) = 'service_role'
      OR (
        guild_code_param IS NOT NULL
        AND (
          guild_code_param IN (SELECT public._pm_caller_guild_codes())
          OR guild_code_param IN (SELECT public._pm_caller_cluster_guild_codes())
          OR public._pm_caller_is_app_admin()
        )
      ) AS allowed
  ),
  player_stats AS (
    -- Get player average damage per boss across ALL seasons
    SELECT
      "displayName",
      "Name" as boss_name,
      AVG("damageDealt") as avg_damage,
      COUNT(*) as battles
    FROM "EOT_GR_data"
    WHERE "Guild" = guild_code_param
      AND "damageType" = 'Battle'
      AND "rarity" IN ('Legendary', 'Mythic')
      AND "damageDealt" > 0
      AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp")  -- Exclude sweeps (FIXED)
      AND "Name" IS NOT NULL
    GROUP BY "displayName", "Name"
  ),
  guild_stats AS (
    -- Get guild average damage per boss across ALL seasons
    SELECT
      "Name" as boss_name,
      AVG("damageDealt") as avg_damage
    FROM "EOT_GR_data"
    WHERE "Guild" = guild_code_param
      AND "damageType" = 'Battle'
      AND "rarity" IN ('Legendary', 'Mythic')
      AND "damageDealt" > 0
      AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp")  -- Exclude sweeps (FIXED)
      AND "Name" IS NOT NULL
    GROUP BY "Name"
  )
  SELECT
    p."displayName" as display_name,
    p.boss_name,
    ROUND(p.avg_damage, 2) as avg_player_damage,
    ROUND(g.avg_damage, 2) as avg_guild_damage,
    p.battles as battle_count,
    CASE
      WHEN g.avg_damage > 0 THEN ROUND(((p.avg_damage / g.avg_damage) - 1) * 100, 1)
      ELSE 0
    END as player_vs_guild_avg,
    CASE
      WHEN p.battles >= 5 THEN true
      ELSE false
    END as has_sufficient_data
  FROM player_stats p
  LEFT JOIN guild_stats g ON p.boss_name = g.boss_name
  CROSS JOIN caller_authorization AS caller_scope
  WHERE caller_scope.allowed
    AND p.battles >= min_battles_param  -- Only require 1 battle by default
  ORDER BY p."displayName", p.boss_name;
$$;

ALTER FUNCTION public.get_player_boss_performance_flexible(guild_code_param text, min_battles_param integer) OWNER TO postgres;

CREATE FUNCTION public.get_player_boss_performance_historical(guild_code_param text) RETURNS TABLE(display_name text, boss_name text, avg_player_damage numeric, avg_guild_damage numeric, battle_count bigint, player_vs_guild_avg numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  WITH caller_authorization AS MATERIALIZED (
    SELECT
      COALESCE(
        NULLIF(NULLIF(current_setting('role', true), ''), 'none'),
        NULLIF(session_user, '')
      ) = 'service_role'
      OR (
        guild_code_param IS NOT NULL
        AND (
          guild_code_param IN (SELECT public._pm_caller_guild_codes())
          OR guild_code_param IN (SELECT public._pm_caller_cluster_guild_codes())
          OR public._pm_caller_is_app_admin()
        )
      ) AS allowed
  ),
  player_stats AS (
    -- Get player average damage per boss across ALL seasons
    SELECT
      "displayName",
      "Name" as boss_name,
      AVG("damageDealt") as avg_damage,
      COUNT(*) as battles
    FROM "EOT_GR_data"
    WHERE "Guild" = guild_code_param
      AND "damageType" = 'Battle'
      AND "rarity" IN ('Legendary', 'Mythic')
      AND "damageDealt" > 0
      AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp")  -- Exclude sweeps (FIXED)
      AND "Name" IS NOT NULL
    GROUP BY "displayName", "Name"
    HAVING COUNT(*) >= 5  -- Require at least 5 battles for historical
  ),
  guild_stats AS (
    -- Get guild average damage per boss across ALL seasons
    SELECT
      "Name" as boss_name,
      AVG("damageDealt") as avg_damage
    FROM "EOT_GR_data"
    WHERE "Guild" = guild_code_param
      AND "damageType" = 'Battle'
      AND "rarity" IN ('Legendary', 'Mythic')
      AND "damageDealt" > 0
      AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp")  -- Exclude sweeps (FIXED)
      AND "Name" IS NOT NULL
    GROUP BY "Name"
  )
  SELECT
    p."displayName" as display_name,
    p.boss_name,
    ROUND(p.avg_damage, 2) as avg_player_damage,
    ROUND(g.avg_damage, 2) as avg_guild_damage,
    p.battles as battle_count,
    CASE
      WHEN g.avg_damage > 0 THEN ROUND(((p.avg_damage / g.avg_damage) - 1) * 100, 1)
      ELSE 0
    END as player_vs_guild_avg
  FROM player_stats p
  LEFT JOIN guild_stats g ON p.boss_name = g.boss_name
  CROSS JOIN caller_authorization AS caller_scope
  WHERE caller_scope.allowed
  ORDER BY p."displayName", p.boss_name;
$$;

ALTER FUNCTION public.get_player_boss_performance_historical(guild_code_param text) OWNER TO postgres;

CREATE FUNCTION public.get_player_boss_performance_historical_cluster(p_guild_code text, p_cluster_code text DEFAULT NULL::text) RETURNS TABLE(player_name text, boss_level text, boss_name text, season text, battles_fought integer, avg_damage numeric, max_damage numeric, min_damage numeric, total_damage numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  WITH player_boss_stats AS (
    SELECT
      e."displayName" as player_name,
      CASE
        WHEN e.rarity = 'Mythic' THEN 'M' || (e.set + 1)::text
        WHEN e.rarity = 'Legendary' THEN 'L' || (e.set + 1)::text
        WHEN e.rarity = 'Epic' THEN 'E' || (e.set + 1)::text
        WHEN e.rarity = 'Rare' THEN 'R' || (e.set + 1)::text
        WHEN e.rarity = 'Uncommon' THEN 'U' || (e.set + 1)::text
        WHEN e.rarity = 'Common' THEN 'C' || (e.set + 1)::text
        ELSE e.rarity || (e.set + 1)::text
      END as boss_level,
      COALESCE(e."Name", 'Unknown Boss') as boss_name,
      e."Season" as season,
      COUNT(*)::integer as battles,
      ROUND(AVG(e."damageDealt"), 0) as avg_dmg,
      MAX(e."damageDealt") as max_dmg,
      MIN(CASE WHEN e."damageDealt" > 0 THEN e."damageDealt" END) as min_dmg,
      SUM(e."damageDealt") as total_dmg
    FROM "EOT_GR_data" e
    WHERE e."Guild" = p_guild_code
      AND (p_cluster_code IS NULL OR e.cluster_code = p_cluster_code)
      AND e."damageDealt" > 0
      AND e.rarity IN ('Legendary', 'Mythic')
    GROUP BY e."displayName", e.rarity, e.set, e."Name", e."Season"
    HAVING COUNT(*) >= 2  -- Minimum battles for reliability
  )
  SELECT * FROM player_boss_stats
  ORDER BY season DESC, boss_level, avg_dmg DESC;
END;
$$;

ALTER FUNCTION public.get_player_boss_performance_historical_cluster(p_guild_code text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_player_boss_rankings(p_player_name text, p_guild_code text, p_cluster_code text, p_season text) RETURNS TABLE(boss_name text, encounter_id integer, player_rank integer, total_players integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH boss_performances AS (
    SELECT
      CONCAT(COALESCE(resolve_boss_name(e."Name"), e."Name"), '_', e.rarity, '_', e.set) as boss_name,
      e."encounterId" as encounter_id,
      e."displayName" as player_name,
      e."Guild" as guild,
      AVG(e."damageDealt") as avg_damage
    FROM "EOT_GR_data" e
    LEFT JOIN guild_config gc ON gc.guild_code = e."Guild"
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND gc.cluster_code = p_cluster_code
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
    GROUP BY COALESCE(resolve_boss_name(e."Name"), e."Name"), e.rarity, e.set, e."encounterId", e."displayName", e."Guild"
  ),
  ranked_performances AS (
    SELECT
      bp.boss_name,
      bp.encounter_id,
      bp.player_name,
      bp.guild,
      bp.avg_damage,
      RANK() OVER (PARTITION BY bp.boss_name, bp.encounter_id ORDER BY bp.avg_damage DESC) as rank,
      COUNT(*) OVER (PARTITION BY bp.boss_name, bp.encounter_id) as total_players
    FROM boss_performances bp
  )
  SELECT
    rp.boss_name,
    rp.encounter_id,
    rp.rank::INTEGER as player_rank,
    rp.total_players::INTEGER
  FROM ranked_performances rp
  WHERE rp.player_name = p_player_name
    AND rp.guild = p_guild_code;
END;
$$;

ALTER FUNCTION public.get_player_boss_rankings(p_player_name text, p_guild_code text, p_cluster_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_player_context(p_player_name text, p_season text) RETURNS TABLE(player_name text, guild_code text, cluster_code text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Return the first matching player's guild and cluster
  -- This is public info visible in leaderboards
  RETURN QUERY
  SELECT DISTINCT
    e."displayName" as player_name,
    e."Guild" as guild_code,
    gc.cluster_code
  FROM "EOT_GR_data" e
  LEFT JOIN guild_config gc ON gc.guild_code = e."Guild"
  WHERE e."displayName" = p_player_name
    AND e."Season" = p_season
    AND e."damageDealt" > 0
  LIMIT 1;
END;
$$;

ALTER FUNCTION public.get_player_context(p_player_name text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_player_damage_by_boss_loop(p_guild_code text, p_season text, p_display_name text) RETURNS TABLE(loop_index integer, boss_display_name text, avg_damage numeric, max_damage numeric, total_damage bigint, hit_count integer, start_time timestamp with time zone, end_time timestamp with time zone, is_prime boolean, sweep_count integer, one_shot_count integer, crash_count integer, eff_avg_damage numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH boss_data AS (
    SELECT
      d."loopIndex",
      d."Name",
      d."damageDealt",
      d."remainingHp",
      d."maxHp",
      d."timestamp",
      d."startedOn",
      d."completedOn",
      d.rarity,
      d.set,
      d."encounterId",
      CASE
        WHEN d.rarity = 'Mythic' THEN 'M' || (COALESCE(d.set, 0) + 1)::TEXT
        ELSE 'L' || (COALESCE(d.set, 0) + 1)::TEXT
      END || ' ' || d."Name" AS display_name,
      (d."encounterId" != 0) AS is_prime_enemy
    FROM "EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."displayName" = p_display_name
      AND d."damageType" = 'Battle'
      AND d.rarity IN ('Legendary', 'Mythic')
      AND d."loopIndex" IS NOT NULL
  )
  SELECT
    bd."loopIndex"::INTEGER AS loop_index,
    bd.display_name AS boss_display_name,
    -- avg of non-crash hits (backward-compatible)
    ROUND(AVG(bd."damageDealt") FILTER (WHERE bd."damageDealt" > 0), 0) AS avg_damage,
    -- max of non-crash hits
    MAX(bd."damageDealt") FILTER (WHERE bd."damageDealt" > 0)::NUMERIC AS max_damage,
    SUM(bd."damageDealt")::BIGINT AS total_damage,
    -- non-crash hit count (backward-compatible)
    COUNT(*) FILTER (WHERE bd."damageDealt" > 0)::INTEGER AS hit_count,
    MIN(COALESCE(bd."startedOn", bd."timestamp")) AS start_time,
    MAX(COALESCE(bd."completedOn", bd."timestamp")) AS end_time,
    bd.is_prime_enemy AS is_prime,
    -- sweep: killing blow where damage < boss max HP (boss was weakened by guild)
    COUNT(*) FILTER (
      WHERE bd."damageDealt" > 0
        AND bd."remainingHp" = 0
        AND bd."maxHp" > 0
        AND bd."damageDealt" < bd."maxHp"
    )::INTEGER AS sweep_count,
    -- one-shot: single hit dealt >= boss max HP
    COUNT(*) FILTER (
      WHERE bd."maxHp" > 0
        AND bd."damageDealt" >= bd."maxHp"
    )::INTEGER AS one_shot_count,
    -- crash: zero damage token
    COUNT(*) FILTER (WHERE bd."damageDealt" = 0)::INTEGER AS crash_count,
    -- effective avg: excludes sweeps (and crashes) — used for %AVG vs Guild calc
    ROUND(AVG(bd."damageDealt") FILTER (
      WHERE bd."damageDealt" > 0
        AND NOT (bd."remainingHp" = 0 AND bd."maxHp" > 0 AND bd."damageDealt" < bd."maxHp")
    ), 0) AS eff_avg_damage
  FROM boss_data bd
  GROUP BY bd."loopIndex", bd.display_name, bd.is_prime_enemy
  ORDER BY bd."loopIndex", bd.display_name;
END;
$$;

ALTER FUNCTION public.get_player_damage_by_boss_loop(p_guild_code text, p_season text, p_display_name text) OWNER TO postgres;

CREATE FUNCTION public.get_player_damage_by_loop_for_boss(p_guild_code text, p_season text, p_boss_name text, p_level text) RETURNS TABLE(loop_index integer, display_name text, avg_damage numeric, max_damage numeric, total_damage bigint, hit_count integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_rarity TEXT;
  v_set_num INTEGER;
BEGIN
  v_rarity := CASE
    WHEN LEFT(p_level, 1) = 'M' THEN 'Mythic'
    ELSE 'Legendary'
  END;
  v_set_num := SUBSTRING(p_level FROM 2)::INTEGER - 1;

  RETURN QUERY
  SELECT
    (d."loopIndex" + 1)::INTEGER AS loop_index,
    d."displayName" AS display_name,
    ROUND(AVG(d."damageDealt"), 0) AS avg_damage,
    MAX(d."damageDealt")::NUMERIC AS max_damage,
    SUM(d."damageDealt")::BIGINT AS total_damage,
    COUNT(*)::INTEGER AS hit_count
  FROM "EOT_GR_data" d
  WHERE d."Guild" = p_guild_code
    AND d."Season" = p_season
    AND d."Name" = p_boss_name
    AND d.rarity = v_rarity
    AND d.set = v_set_num
    AND d."damageType" = 'Battle'
    AND d."damageDealt" > 0
    AND d."loopIndex" IS NOT NULL
  GROUP BY d."loopIndex", d."displayName"
  ORDER BY d."loopIndex", SUM(d."damageDealt") DESC;
END;
$$;

ALTER FUNCTION public.get_player_damage_by_loop_for_boss(p_guild_code text, p_season text, p_boss_name text, p_level text) OWNER TO postgres;

CREATE FUNCTION public.get_player_five_season_averages(p_guild_code text, p_current_season integer, p_tier_min integer DEFAULT NULL::integer, p_tier_max integer DEFAULT NULL::integer) RETURNS TABLE(player_id text, player_name text, boss_name text, "Season" text, avg_damage numeric, battle_count bigint, rarity text, tier integer, encounter_id integer, vs_guild_pct numeric, vs_cluster_pct numeric, is_current_member boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_loop_number integer;
  v_cluster_code text;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.player_mapping pm
       WHERE pm.user_id = auth.uid()
         AND pm.guild_code = p_guild_code
         AND COALESCE(pm.is_current, false) = true
     ) THEN
    RAISE EXCEPTION 'Not authorized for guild %', p_guild_code
      USING ERRCODE = '42501';
  END IF;

  SELECT gc.cluster_code INTO v_cluster_code
  FROM public.guild_config gc
  WHERE gc.guild_code = p_guild_code
    AND COALESCE(gc.enabled, true) = true;

  IF p_tier_min IS NOT NULL AND p_tier_max IS NOT NULL AND p_tier_min > p_tier_max THEN
    RAISE EXCEPTION 'p_tier_min must be less than or equal to p_tier_max';
  END IF;

  IF p_tier_min IS NOT NULL
     AND p_tier_max IS NOT NULL
     AND p_tier_min >= 4
     AND p_tier_max = p_tier_min + 1
     AND MOD(p_tier_min, 2) = 0 THEN
    v_loop_number := (p_tier_min - 4) / 2;
  END IF;

  RETURN QUERY
  WITH season_range AS (
    SELECT generate_series(
      GREATEST(p_current_season - 5, 1),
      p_current_season - 1
    )::text AS season_num
  ),
  player_current_names AS (
    SELECT
      pm.player_id,
      pm.display_name
    FROM public.player_mapping pm
    WHERE pm.guild_code = p_guild_code
      AND pm.is_current = true
  ),
  player_membership AS (
    SELECT
      pm.player_id,
      BOOL_OR(COALESCE(pm.is_current, false)) AS is_current_member
    FROM public.player_mapping pm
    WHERE pm.guild_code = p_guild_code
    GROUP BY pm.player_id
  ),
  player_boss_stats AS (
    SELECT
      e."userId" AS player_id,
      COALESCE(pcn.display_name, e."displayName", 'Unknown Player') AS player_name,
      e."Name" AS boss_name,
      e."Season",
      e."rarity",
      e."tier",
      CASE
        WHEN e."encounterId"::text ~ '^\d+$' THEN e."encounterId"::integer
        ELSE 0
      END AS encounter_id,
      COALESCE(pm_status.is_current_member, false) AS is_current_member,
      AVG(e."damageDealt") AS avg_damage,
      COUNT(*) AS battle_count
    FROM public."EOT_GR_data" e
    JOIN season_range sr ON e."Season" = sr.season_num
    LEFT JOIN player_current_names pcn ON pcn.player_id = e."userId"
    LEFT JOIN player_membership pm_status ON pm_status.player_id = e."userId"
    WHERE e."Guild" = p_guild_code
      AND e."damageType" = 'Battle'
      AND e."damageDealt" > 0
      AND e."rarity" IN ('Legendary', 'Mythic')
      AND e."userId" IS NOT NULL
      AND (
        v_loop_number IS NULL
        OR COALESCE(
          e."loopIndex"::integer,
          CASE
            WHEN e."tier" IS NULL THEN NULL
            WHEN e."tier" >= 4 THEN ((e."tier"::integer - 4) / 2)
            ELSE 0
          END
        ) = v_loop_number
      )
      AND (p_tier_min IS NULL OR e."tier" >= p_tier_min)
      AND (p_tier_max IS NULL OR e."tier" <= p_tier_max)
    GROUP BY
      e."userId",
      player_name,
      e."Name",
      e."Season",
      e."rarity",
      e."tier",
      encounter_id,
      pm_status.is_current_member
  ),
  guild_boss_averages AS (
    SELECT
      pbs_g.boss_name,
      pbs_g."Season",
      pbs_g.rarity,
      pbs_g.tier,
      pbs_g.encounter_id,
      AVG(pbs_g.avg_damage) AS guild_avg
    FROM player_boss_stats pbs_g
    GROUP BY
      pbs_g.boss_name,
      pbs_g."Season",
      pbs_g.rarity,
      pbs_g.tier,
      pbs_g.encounter_id
  ),
  cluster_boss_averages AS (
    SELECT
      e."Name" AS boss_name,
      e."Season",
      e."rarity",
      e."tier",
      CASE
        WHEN e."encounterId"::text ~ '^\d+$' THEN e."encounterId"::integer
        ELSE 0
      END AS encounter_id,
      AVG(e."damageDealt") AS cluster_avg
    FROM public."EOT_GR_data" e
    JOIN season_range sr ON e."Season" = sr.season_num
    JOIN public.guild_config gc ON e."Guild" = gc.guild_code
    WHERE COALESCE(gc.enabled, true) = true
      AND (
        (v_cluster_code IS NULL AND e."Guild" = p_guild_code)
        OR gc.cluster_code = v_cluster_code
      )
      AND e."damageType" = 'Battle'
      AND e."damageDealt" > 0
      AND e."rarity" IN ('Legendary', 'Mythic')
      AND (
        v_loop_number IS NULL
        OR COALESCE(
          e."loopIndex"::integer,
          CASE
            WHEN e."tier" IS NULL THEN NULL
            WHEN e."tier" >= 4 THEN ((e."tier"::integer - 4) / 2)
            ELSE 0
          END
        ) = v_loop_number
      )
      AND (p_tier_min IS NULL OR e."tier" >= p_tier_min)
      AND (p_tier_max IS NULL OR e."tier" <= p_tier_max)
    GROUP BY e."Name", e."Season", e."rarity", e."tier", encounter_id
  )
  SELECT
    pbs.player_id::text,
    pbs.player_name::text AS player_name,
    pbs.boss_name::text AS boss_name,
    pbs."Season"::text AS "Season",
    pbs.avg_damage AS avg_damage,
    pbs.battle_count AS battle_count,
    pbs.rarity::text AS rarity,
    pbs.tier::integer AS tier,
    pbs.encounter_id::integer AS encounter_id,
    ROUND(((pbs.avg_damage - gba.guild_avg) / NULLIF(gba.guild_avg, 0) * 100)::numeric, 1)
      AS vs_guild_pct,
    ROUND(((pbs.avg_damage - cba.cluster_avg) / NULLIF(cba.cluster_avg, 0) * 100)::numeric, 1)
      AS vs_cluster_pct,
    pbs.is_current_member
  FROM player_boss_stats pbs
  LEFT JOIN guild_boss_averages gba ON (
    pbs.boss_name = gba.boss_name
    AND pbs."Season" = gba."Season"
    AND pbs.rarity = gba.rarity
    AND pbs.tier = gba.tier
    AND pbs.encounter_id = gba.encounter_id
  )
  LEFT JOIN cluster_boss_averages cba ON (
    pbs.boss_name = cba.boss_name
    AND pbs."Season" = cba."Season"
    AND pbs.rarity = cba.rarity
    AND pbs.tier = cba.tier
    AND pbs.encounter_id = cba.encounter_id
  )
  ORDER BY pbs."Season" DESC, pbs.boss_name, pbs.player_id;
END;
$_$;

ALTER FUNCTION public.get_player_five_season_averages(p_guild_code text, p_current_season integer, p_tier_min integer, p_tier_max integer) OWNER TO postgres;

CREATE FUNCTION public.get_player_historical_performance(p_player_name text, p_guild_code text, p_cluster_code text DEFAULT NULL::text) RETURNS TABLE(season text, vs_cluster_pct numeric, vs_guild_pct numeric, cluster_rank integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    guild_codes text[];
BEGIN
    -- Get relevant guild codes
    IF p_cluster_code IS NOT NULL THEN
        SELECT array_agg(guild_code)
        INTO guild_codes
        FROM guild_config
        WHERE cluster_code = p_cluster_code
        AND enabled = true;
    ELSE
        guild_codes := ARRAY[p_guild_code];
    END IF;

    -- Return historical performance for last 10 seasons
    RETURN QUERY
    WITH recent_seasons AS (
        SELECT DISTINCT "Season"
        FROM "EOT_GR_data"
        WHERE "displayName" = p_player_name
        AND "Guild" = ANY(guild_codes)
        AND "Season" ~ '^\d+$'  -- LEX-FIX 2026-05-07: guard the int cast below
        ORDER BY ("Season"::int) DESC  -- LEX-FIX 2026-05-07: was ORDER BY "Season" DESC
        LIMIT 10
    )
    SELECT
        rs."Season",
        COALESCE(pc.vs_cluster_pct, 0)::numeric,
        COALESCE(pc.vs_guild_pct, 0)::numeric,
        COALESCE(pc.cluster_rank, 0)::integer
    FROM recent_seasons rs
    LEFT JOIN get_player_performance_in_cluster(
        p_player_name,
        p_guild_code,
        p_cluster_code,
        rs."Season"
    ) pc ON true
    WHERE p_cluster_code IS NOT NULL
    ORDER BY (rs."Season"::int) DESC;  -- LEX-FIX 2026-05-07: was ORDER BY rs."Season" DESC
END;
$_$;

ALTER FUNCTION public.get_player_historical_performance(p_player_name text, p_guild_code text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_player_mapping_debug(p_user_id uuid) RETURNS TABLE(player_id text, username text, display_name text, guild_code text, user_id uuid, role text, is_current boolean, joined_at timestamp with time zone, updated_at timestamp with time zone, officer_notes text, discord_username text, timezone text, tacticus_share_url text, theme_preference text, rls_check text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pm.player_id,
    pm.username,
    pm.display_name,
    pm.guild_code,
    pm.user_id,
    pm.role,
    pm.is_current,
    pm.joined_at,
    pm.updated_at,
    pm.officer_notes,
    pm.discord_username,
    pm.timezone,
    pm.tacticus_share_url,
    pm.theme_preference,
    CASE
      WHEN pm.user_id = p_user_id THEN 'Should be visible'
      ELSE 'Should not be visible'
    END as rls_check
  FROM player_mapping pm
  WHERE pm.user_id = p_user_id
  ORDER BY pm.is_current DESC, pm.updated_at DESC;
END;
$$;

ALTER FUNCTION public.get_player_mapping_debug(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.get_player_meta_team_engagement(p_guild_code text, p_player_ids text[], p_min_season integer, p_min_tokens integer DEFAULT 5) RETURNS TABLE(player_id text, meta_team text, token_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH classified AS (
    SELECT
      "userId" AS player_id,
      public.get_meta_team("heroDetails"::text) AS meta_team
    FROM public."EOT_GR_data"
    WHERE "Guild" = p_guild_code
      AND CAST("Season" AS integer) >= p_min_season
      AND "userId" = ANY(p_player_ids)
      AND "heroDetails" IS NOT NULL
      AND "heroDetails" <> ''
      AND "heroDetails" <> '[]'
  )
  SELECT
    player_id,
    meta_team,
    COUNT(*)::bigint AS token_count
  FROM classified
  WHERE meta_team IS NOT NULL
  GROUP BY player_id, meta_team
  HAVING COUNT(*) >= p_min_tokens;
$$;

ALTER FUNCTION public.get_player_meta_team_engagement(p_guild_code text, p_player_ids text[], p_min_season integer, p_min_tokens integer) OWNER TO postgres;

CREATE FUNCTION public.get_player_performance(p_player text, p_season text DEFAULT NULL::text) RETURNS TABLE("Guild" text, "Season" text, "displayName" text, hit_count bigint, total_damage bigint, avg_damage double precision, max_damage bigint, min_loop integer, max_loop integer, unique_bosses_hit bigint, damage_types_used text[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_season IS NULL THEN
        RETURN QUERY
        SELECT * FROM public.player_season_summary
        WHERE "displayName" = p_player
        ORDER BY "Season";
    ELSE
        RETURN QUERY
        SELECT * FROM public.player_season_summary
        WHERE "displayName" = p_player AND "Season" = p_season;
    END IF;
END;
$$;

ALTER FUNCTION public.get_player_performance(p_player text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_player_performance_in_cluster(p_user_id text, p_guild_code text, p_cluster_code text, p_season text) RETURNS TABLE(player_name text, guild_code text, total_damage bigint, battle_count integer, vs_guild_pct numeric, vs_cluster_pct numeric, guild_rank integer, total_players_in_guild integer, cluster_rank integer, total_players_in_cluster integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_target_cluster_code TEXT;
  v_target_cluster_id UUID;
  v_is_service BOOLEAN := COALESCE(
    NULLIF(
      NULLIF(current_setting('role', true), ''),
      'none'
    ),
    NULLIF(session_user, '')
  ) = 'service_role';
BEGIN
  IF NOT v_is_service
    AND NOT COALESCE(
      p_guild_code IN (
        SELECT public._pm_caller_guild_codes()
      )
      OR p_guild_code IN (
        SELECT public._pm_caller_cluster_guild_codes()
      )
      OR public._pm_caller_is_app_admin(),
      FALSE
    )
  THEN
    RETURN;
  END IF;

  SELECT gc.cluster_code, gc.cluster_id
  INTO v_target_cluster_code, v_target_cluster_id
  FROM public.guild_config AS gc
  WHERE gc.guild_code = p_guild_code
  LIMIT 1;

  RETURN QUERY
  WITH cluster_guilds AS (
    SELECT gc.guild_code
    FROM guild_config gc
    WHERE v_target_cluster_code IS NOT NULL
      AND v_target_cluster_id IS NOT NULL
      AND gc.cluster_code = v_target_cluster_code
      AND gc.cluster_id = v_target_cluster_id
  ),
  -- Reference averages: sweep-free baselines (unchanged)
  guild_averages AS (
    SELECT
      e."Name" || '_' || e.rarity AS boss_key,
      AVG(e."damageDealt") AS avg_damage
    FROM "EOT_GR_data" e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
    GROUP BY e."Name", e.rarity
  ),
  cluster_averages AS (
    SELECT
      e."Name" || '_' || e.rarity AS boss_key,
      AVG(e."damageDealt") AS avg_damage
    FROM "EOT_GR_data" e
    INNER JOIN cluster_guilds cg ON cg.guild_code = e."Guild"
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
    GROUP BY e."Name", e.rarity
  ),
  -- Target player's boss stats with sweep damages
  player_boss_stats AS (
    SELECT
      e."Name" || '_' || e.rarity AS boss_key,
      AVG(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS player_avg,
      COUNT(*) FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS battle_count,
      SUM(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS non_sweep_damage,
      array_agg(e."damageDealt"::numeric) FILTER (
        WHERE e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp"
      ) AS sweep_damages
    FROM "EOT_GR_data" e
    WHERE e."userId" = p_user_id
      AND e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
    GROUP BY e."Name", e.rarity
  ),
  -- Target player's overall performance with sweep exception
  player_performance AS (
    SELECT
      -- vs_guild: include sweeps >= guild_avg
      SUM(
        CASE WHEN ga.avg_damage > 0 THEN
          ((
            (coalesce(pbs.non_sweep_damage, 0) + coalesce(qualifying_sweep_sum(pbs.sweep_damages, GREATEST(pbs.player_avg, ga.avg_damage)::numeric), 0))
            / nullif(coalesce(pbs.battle_count, 0) + coalesce(qualifying_sweep_count(pbs.sweep_damages, GREATEST(pbs.player_avg, ga.avg_damage)::numeric), 0), 0)
            / ga.avg_damage
          ) - 1) * 100
          * (coalesce(pbs.battle_count, 0) + coalesce(qualifying_sweep_count(pbs.sweep_damages, GREATEST(pbs.player_avg, ga.avg_damage)::numeric), 0))
        ELSE 0 END
      ) / NULLIF(SUM(
        CASE WHEN ga.avg_damage > 0
          THEN coalesce(pbs.battle_count, 0) + coalesce(qualifying_sweep_count(pbs.sweep_damages, GREATEST(pbs.player_avg, ga.avg_damage)::numeric), 0)
          ELSE 0 END
      ), 0) AS vs_guild,
      -- vs_cluster: include sweeps >= cluster_avg
      SUM(
        CASE WHEN ca.avg_damage > 0 THEN
          ((
            (coalesce(pbs.non_sweep_damage, 0) + coalesce(qualifying_sweep_sum(pbs.sweep_damages, GREATEST(pbs.player_avg, ca.avg_damage)::numeric), 0))
            / nullif(coalesce(pbs.battle_count, 0) + coalesce(qualifying_sweep_count(pbs.sweep_damages, GREATEST(pbs.player_avg, ca.avg_damage)::numeric), 0), 0)
            / ca.avg_damage
          ) - 1) * 100
          * (coalesce(pbs.battle_count, 0) + coalesce(qualifying_sweep_count(pbs.sweep_damages, GREATEST(pbs.player_avg, ca.avg_damage)::numeric), 0))
        ELSE 0 END
      ) / NULLIF(SUM(
        CASE WHEN ca.avg_damage > 0
          THEN coalesce(pbs.battle_count, 0) + coalesce(qualifying_sweep_count(pbs.sweep_damages, GREATEST(pbs.player_avg, ca.avg_damage)::numeric), 0)
          ELSE 0 END
      ), 0) AS vs_cluster
    FROM player_boss_stats pbs
    LEFT JOIN guild_averages ga ON ga.boss_key = pbs.boss_key
    LEFT JOIN cluster_averages ca ON ca.boss_key = pbs.boss_key
  ),
  -- All guild players' boss stats with sweep damages
  all_guild_players_stats AS (
    SELECT
      e."userId",
      e."Name" || '_' || e.rarity AS boss_key,
      AVG(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS player_avg,
      COUNT(*) FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS battle_count,
      SUM(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS non_sweep_damage,
      array_agg(e."damageDealt"::numeric) FILTER (
        WHERE e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp"
      ) AS sweep_damages
    FROM "EOT_GR_data" e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
    GROUP BY e."userId", e."Name", e.rarity
  ),
  -- All guild players' weighted performance (vs guild, with sweep exception)
  all_guild_players_weighted AS (
    SELECT
      agps."userId",
      SUM(
        CASE WHEN ga.avg_damage > 0 THEN
          ((
            (coalesce(agps.non_sweep_damage, 0) + coalesce(qualifying_sweep_sum(agps.sweep_damages, GREATEST(agps.player_avg, ga.avg_damage)::numeric), 0))
            / nullif(coalesce(agps.battle_count, 0) + coalesce(qualifying_sweep_count(agps.sweep_damages, GREATEST(agps.player_avg, ga.avg_damage)::numeric), 0), 0)
            / ga.avg_damage
          ) - 1) * 100
          * (coalesce(agps.battle_count, 0) + coalesce(qualifying_sweep_count(agps.sweep_damages, GREATEST(agps.player_avg, ga.avg_damage)::numeric), 0))
        ELSE 0 END
      ) / NULLIF(SUM(
        CASE WHEN ga.avg_damage > 0
          THEN coalesce(agps.battle_count, 0) + coalesce(qualifying_sweep_count(agps.sweep_damages, GREATEST(agps.player_avg, ga.avg_damage)::numeric), 0)
          ELSE 0 END
      ), 0) AS weighted_vs_guild
    FROM all_guild_players_stats agps
    LEFT JOIN guild_averages ga ON ga.boss_key = agps.boss_key
    GROUP BY agps."userId"
  ),
  -- Guild rankings
  guild_rankings AS (
    SELECT
      "userId",
      weighted_vs_guild,
      RANK() OVER (ORDER BY weighted_vs_guild DESC NULLS LAST) AS rank,
      COUNT(*) OVER () AS total_players
    FROM all_guild_players_weighted
    WHERE weighted_vs_guild IS NOT NULL
  ),
  -- Player's guild rank
  player_guild_rank AS (
    SELECT
      rank,
      total_players
    FROM guild_rankings
    WHERE "userId" = p_user_id
  ),
  -- All cluster players' boss stats with sweep damages
  all_cluster_players_stats AS (
    SELECT
      e."userId",
      e."Guild",
      e."Name" || '_' || e.rarity AS boss_key,
      AVG(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS player_avg,
      COUNT(*) FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS battle_count,
      SUM(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS non_sweep_damage,
      array_agg(e."damageDealt"::numeric) FILTER (
        WHERE e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp"
      ) AS sweep_damages
    FROM "EOT_GR_data" e
    INNER JOIN cluster_guilds cg ON cg.guild_code = e."Guild"
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
    GROUP BY e."userId", e."Guild", e."Name", e.rarity
  ),
  -- All cluster players' weighted performance (vs cluster, with sweep exception)
  all_cluster_players_weighted AS (
    SELECT
      acps."userId",
      acps."Guild",
      SUM(
        CASE WHEN ca.avg_damage > 0 THEN
          ((
            (coalesce(acps.non_sweep_damage, 0) + coalesce(qualifying_sweep_sum(acps.sweep_damages, GREATEST(acps.player_avg, ca.avg_damage)::numeric), 0))
            / nullif(coalesce(acps.battle_count, 0) + coalesce(qualifying_sweep_count(acps.sweep_damages, GREATEST(acps.player_avg, ca.avg_damage)::numeric), 0), 0)
            / ca.avg_damage
          ) - 1) * 100
          * (coalesce(acps.battle_count, 0) + coalesce(qualifying_sweep_count(acps.sweep_damages, GREATEST(acps.player_avg, ca.avg_damage)::numeric), 0))
        ELSE 0 END
      ) / NULLIF(SUM(
        CASE WHEN ca.avg_damage > 0
          THEN coalesce(acps.battle_count, 0) + coalesce(qualifying_sweep_count(acps.sweep_damages, GREATEST(acps.player_avg, ca.avg_damage)::numeric), 0)
          ELSE 0 END
      ), 0) AS weighted_vs_cluster
    FROM all_cluster_players_stats acps
    LEFT JOIN cluster_averages ca ON ca.boss_key = acps.boss_key
    GROUP BY acps."userId", acps."Guild"
  ),
  -- Cluster rankings
  cluster_rankings AS (
    SELECT
      "userId",
      "Guild",
      weighted_vs_cluster,
      RANK() OVER (ORDER BY weighted_vs_cluster DESC NULLS LAST) AS rank,
      COUNT(*) OVER () AS total_players
    FROM all_cluster_players_weighted
    WHERE weighted_vs_cluster IS NOT NULL
  ),
  -- Player's cluster rank
  player_cluster_rank AS (
    SELECT
      rank,
      total_players
    FROM cluster_rankings
    WHERE "userId" = p_user_id AND "Guild" = p_guild_code
  )
  SELECT
    p_user_id,
    p_guild_code,
    (SELECT COALESCE(SUM("damageDealt"), 0) FROM "EOT_GR_data"
     WHERE "userId" = p_user_id
       AND "Guild" = p_guild_code
       AND "Season" = p_season
       AND "damageType" = 'Battle')::BIGINT AS total_damage,
    (SELECT COUNT(*) FROM "EOT_GR_data"
     WHERE "userId" = p_user_id
       AND "Guild" = p_guild_code
       AND "Season" = p_season
       AND "damageType" = 'Battle')::INTEGER AS battle_count,
    COALESCE((SELECT vs_guild FROM player_performance), 0)::NUMERIC AS vs_guild_pct,
    COALESCE((SELECT vs_cluster FROM player_performance), 0)::NUMERIC AS vs_cluster_pct,
    COALESCE((SELECT rank FROM player_guild_rank), 0)::INTEGER AS guild_rank,
    COALESCE((SELECT total_players FROM player_guild_rank), 0)::INTEGER AS total_players_in_guild,
    COALESCE((SELECT rank FROM player_cluster_rank), 0)::INTEGER AS cluster_rank,
    COALESCE((SELECT total_players FROM player_cluster_rank), 0)::INTEGER AS total_players_in_cluster;
END;
$$;

ALTER FUNCTION public.get_player_performance_in_cluster(p_user_id text, p_guild_code text, p_cluster_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_player_performance_in_cluster_v2(p_player_name text, p_guild_code text, p_cluster_code text, p_season text) RETURNS TABLE(player_avg numeric, guild_avg numeric, cluster_avg numeric, vs_guild_pct numeric, vs_cluster_pct numeric, cluster_rank integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_player_id TEXT;
BEGIN
  -- First resolve the player name to player_id
  SELECT pm.player_id INTO target_player_id
  FROM player_mapping pm
  WHERE pm.display_name = p_player_name
    AND pm.is_current = true
  LIMIT 1;

  -- If not found as current name, try as historical name
  IF target_player_id IS NULL THEN
    SELECT pm.player_id INTO target_player_id
    FROM player_mapping pm
    WHERE pm.display_name = p_player_name
    ORDER BY pm.updated_at DESC
    LIMIT 1;
  END IF;

  -- If still not found, return null
  IF target_player_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH player_stats AS (
    SELECT
      e."userId" as player_id,
      e."Guild",
      gc.cluster_code,
      AVG(e."damageDealt") as avg_damage
    FROM "EOT_GR_data" e
    JOIN guild_config gc ON e."Guild" = gc.guild_code
    WHERE e."Season" = p_season
      AND e."damageDealt" > 0
      AND e."userId" IS NOT NULL
      AND gc.cluster_code = p_cluster_code
    GROUP BY e."userId", e."Guild", gc.cluster_code
  ),
  target_player AS (
    SELECT avg_damage as player_avg_damage
    FROM player_stats ps
    WHERE ps.player_id = target_player_id
      AND ps.Guild = p_guild_code
  ),
  guild_avg AS (
    SELECT AVG(avg_damage) as guild_avg_damage
    FROM player_stats ps
    WHERE ps.Guild = p_guild_code
  ),
  cluster_avg AS (
    SELECT AVG(avg_damage) as cluster_avg_damage
    FROM player_stats ps
  ),
  player_rank AS (
    SELECT COUNT(*) + 1 as rank
    FROM player_stats ps
    CROSS JOIN target_player tp
    WHERE ps.avg_damage > tp.player_avg_damage
  )
  SELECT
    tp.player_avg_damage as player_avg,
    ga.guild_avg_damage as guild_avg,
    ca.cluster_avg_damage as cluster_avg,
    ROUND(((tp.player_avg_damage - ga.guild_avg_damage) / NULLIF(ga.guild_avg_damage, 0) * 100)::numeric, 1) as vs_guild_pct,
    ROUND(((tp.player_avg_damage - ca.cluster_avg_damage) / NULLIF(ca.cluster_avg_damage, 0) * 100)::numeric, 1) as vs_cluster_pct,
    pr.rank::INTEGER as cluster_rank
  FROM target_player tp
  CROSS JOIN guild_avg ga
  CROSS JOIN cluster_avg ca
  CROSS JOIN player_rank pr;
END;
$$;

ALTER FUNCTION public.get_player_performance_in_cluster_v2(p_player_name text, p_guild_code text, p_cluster_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_player_performance_ranks_for_players(p_player_ids text[], p_season text) RETURNS TABLE(player_id text, player_name text, "Guild" text, "Season" text, cluster_code character varying, avg_damage numeric, total_damage numeric, battle_count bigint, unique_bosses bigint, max_damage bigint, guild_rank bigint, cluster_rank bigint, performance_tier text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    WITH target_guilds AS (
        -- index probe on idx_eot_gr_data_user_season ("userId", "Season")
        SELECT DISTINCT e."Guild" AS guild_code
          FROM "EOT_GR_data" e
         WHERE e."Season" = p_season
           AND e."userId" = ANY (p_player_ids)
           AND e."damageType" = 'Battle'::text
           AND e."damageDealt" > 0
    ), target_clusters AS (
        SELECT DISTINCT gc.cluster_code
          FROM target_guilds tg
          LEFT JOIN guild_config gc ON gc.guild_code = tg.guild_code
    ), scope_guilds AS (
        -- every guild whose rank partition overlaps a requested player's:
        -- its own guild, plus every guild in the same cluster (NULL included,
        -- because window PARTITION BY groups NULLs together).
        SELECT tg.guild_code FROM target_guilds tg
        UNION
        SELECT gc.guild_code
          FROM guild_config gc
         WHERE EXISTS (
                   SELECT 1 FROM target_clusters tc
                    WHERE tc.cluster_code IS NOT DISTINCT FROM gc.cluster_code
               )
    ), player_stats AS (
        SELECT e."userId"        AS player_id,
               pm.display_name   AS current_player_name,
               e."Guild",
               e."Season",
               gc.cluster_code,
               avg(e."damageDealt")            AS avg_damage,
               sum(e."damageDealt")            AS total_damage,
               count(*)                        AS battle_count,
               count(DISTINCT e."Name")        AS unique_bosses,
               max(e."damageDealt")            AS max_damage
          FROM "EOT_GR_data" e
          JOIN scope_guilds sg ON sg.guild_code = e."Guild"
          LEFT JOIN player_mapping pm
                 ON e."userId" = pm.player_id
                AND pm.is_current = true
          LEFT JOIN guild_config gc
                 ON e."Guild" = gc.guild_code
         WHERE e."Season" = p_season
           AND e."damageDealt" > 0
           AND e."damageType" = 'Battle'::text
           AND e."userId" IS NOT NULL
         GROUP BY e."userId", pm.display_name, e."Guild", e."Season", gc.cluster_code
    ), performance_ranks AS (
        SELECT ps.*,
               row_number() OVER (PARTITION BY ps."Guild", ps."Season"
                                  ORDER BY ps.avg_damage DESC) AS guild_rank,
               row_number() OVER (PARTITION BY ps.cluster_code, ps."Season"
                                  ORDER BY ps.avg_damage DESC) AS cluster_rank
          FROM player_stats ps
    )
    SELECT pr.player_id,
           COALESCE(pr.current_player_name, 'Unknown Player'::text) AS player_name,
           pr."Guild",
           pr."Season",
           pr.cluster_code,
           pr.avg_damage,
           pr.total_damage,
           pr.battle_count,
           pr.unique_bosses,
           pr.max_damage,
           pr.guild_rank,
           pr.cluster_rank,
           CASE
               WHEN pr.guild_rank <= 10 THEN 'Top 10'::text
               WHEN pr.guild_rank <= 25 THEN 'Top 25'::text
               ELSE 'Other'::text
           END AS performance_tier
      FROM performance_ranks pr
     WHERE pr.player_id = ANY (p_player_ids);
$$;

ALTER FUNCTION public.get_player_performance_ranks_for_players(p_player_ids text[], p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_player_performance_summary(p_guild_code text, p_season text, p_rarities text[] DEFAULT ARRAY['Legendary'::text, 'Mythic'::text]) RETURNS TABLE(user_id text, display_name text, avg_vs_cluster numeric, avg_vs_guild numeric, avg_vs_cluster_boss_only numeric, avg_vs_guild_boss_only numeric, bosses_played integer, boss_hits integer, prime_hits integer, primes_played integer, total_battles integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH caller_authorization AS MATERIALIZED (
  SELECT
    COALESCE(
      NULLIF(
        NULLIF(current_setting('role', true), ''),
        'none'
      ),
      NULLIF(session_user, '')
    ) = 'service_role'
    OR (
      p_guild_code IS NOT NULL
      AND (
        p_guild_code IN (
          SELECT public._pm_caller_guild_codes()
        )
        OR p_guild_code IN (
          SELECT public._pm_caller_cluster_guild_codes()
        )
        OR public._pm_caller_is_app_admin()
      )
    ) AS allowed
),
guild_cluster AS (
  SELECT cluster_code
  FROM guild_config
  WHERE guild_code = p_guild_code
  LIMIT 1
),
latest_display_names AS (
  SELECT DISTINCT ON ("userId")
    "userId",
    "displayName"
  FROM "EOT_GR_data"
  WHERE "Season" = p_season
    AND "Guild" = p_guild_code
    AND "userId" IS NOT NULL
    AND "displayName" IS NOT NULL
  ORDER BY "userId", "completedOn" DESC NULLS LAST
),
player_boss_raw AS (
  SELECT
    e."userId" as uid,
    e."Name" as boss_name,
    e."encounterId",
    e.rarity as rarity_val,
    e.set as set_val,
    SUM(e."damageDealt") FILTER (
      WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
    ) as non_sweep_damage,
    COUNT(*) FILTER (
      WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
    ) as non_sweep_count,
    array_agg(e."damageDealt"::numeric) FILTER (
      WHERE e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp"
    ) as sweep_damages,
    AVG(e."damageDealt") FILTER (
      WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
    ) as player_avg
  FROM "EOT_GR_data" e
  WHERE e."Season" = p_season
    AND e."Guild" = p_guild_code
    AND e."damageType" = 'Battle'
    AND e.rarity = ANY(p_rarities)
    AND e."damageDealt" > 0
    AND e."userId" IS NOT NULL
  GROUP BY e."userId", e."Name", e."encounterId", e.rarity, e.set
),
guild_stats AS (
  SELECT
    "Name" as boss_name,
    "encounterId",
    rarity as rarity_val,
    set as set_val,
    avg("damageDealt") as guild_avg
  FROM "EOT_GR_data"
  WHERE "Season" = p_season
    AND "Guild" = p_guild_code
    AND "damageType" = 'Battle'
    AND rarity = ANY(p_rarities)
    AND "damageDealt" > 0
    AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp")
  GROUP BY "Name", "encounterId", rarity, set
),
cluster_stats AS (
  SELECT
    e."Name" as boss_name,
    e."encounterId",
    e.rarity as rarity_val,
    e.set as set_val,
    avg(e."damageDealt") as cluster_avg
  FROM "EOT_GR_data" e
  INNER JOIN guild_config gc ON gc.guild_code = e."Guild"
  WHERE e."Season" = p_season
    AND gc.cluster_code = (SELECT cluster_code FROM guild_cluster)
    AND e."damageType" = 'Battle'
    AND e.rarity = ANY(p_rarities)
    AND e."damageDealt" > 0
    AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
  GROUP BY e."Name", e."encounterId", e.rarity, e.set
),
-- Player comparisons using shared pct function
player_comparisons AS (
  SELECT
    p.uid as user_id,
    p.boss_name,
    p."encounterId",
    (COALESCE(p.non_sweep_count, 0)
      + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.player_avg, g.guild_avg::numeric)), 0)
    ) as guild_battle_count,
    (COALESCE(p.non_sweep_count, 0)
      + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.player_avg, c.cluster_avg::numeric)), 0)
    ) as cluster_battle_count,
    COALESCE(calc_boss_performance_pct(p.non_sweep_damage, p.non_sweep_count, p.sweep_damages, c.cluster_avg::numeric, GREATEST(p.player_avg, c.cluster_avg::numeric)), 0) as vs_cluster_pct,
    COALESCE(calc_boss_performance_pct(p.non_sweep_damage, p.non_sweep_count, p.sweep_damages, g.guild_avg::numeric, GREATEST(p.player_avg, g.guild_avg::numeric)), 0) as vs_guild_pct,
    CASE WHEN p."encounterId" = 0 THEN 1 ELSE 0 END as is_boss
  FROM player_boss_raw p
  LEFT JOIN guild_stats g ON p.boss_name = g.boss_name AND p."encounterId" = g."encounterId" AND p.rarity_val = g.rarity_val AND p.set_val = g.set_val
  LEFT JOIN cluster_stats c ON p.boss_name = c.boss_name AND p."encounterId" = c."encounterId" AND p.rarity_val = c.rarity_val AND p.set_val = c.set_val
)
SELECT
  pc.user_id,
  ldn."displayName" as display_name,
  ROUND(sum(pc.vs_cluster_pct * pc.cluster_battle_count) / NULLIF(sum(pc.cluster_battle_count), 0), 2) as avg_vs_cluster,
  ROUND(sum(pc.vs_guild_pct * pc.guild_battle_count) / NULLIF(sum(pc.guild_battle_count), 0), 2) as avg_vs_guild,
  ROUND(sum(CASE WHEN pc.is_boss = 1 THEN pc.vs_cluster_pct * pc.cluster_battle_count ELSE 0 END) /
    NULLIF(sum(CASE WHEN pc.is_boss = 1 THEN pc.cluster_battle_count ELSE 0 END), 0), 2) as avg_vs_cluster_boss_only,
  ROUND(sum(CASE WHEN pc.is_boss = 1 THEN pc.vs_guild_pct * pc.guild_battle_count ELSE 0 END) /
    NULLIF(sum(CASE WHEN pc.is_boss = 1 THEN pc.guild_battle_count ELSE 0 END), 0), 2) as avg_vs_guild_boss_only,
  count(DISTINCT pc.boss_name)::integer as bosses_played,
  sum(CASE WHEN pc.is_boss = 1 THEN pc.guild_battle_count ELSE 0 END)::integer as boss_hits,
  sum(CASE WHEN pc.is_boss = 0 THEN pc.guild_battle_count ELSE 0 END)::integer as prime_hits,
  count(DISTINCT CASE WHEN pc.is_boss = 0 THEN pc.boss_name END)::integer as primes_played,
  sum(pc.guild_battle_count)::integer as total_battles
FROM player_comparisons pc
JOIN latest_display_names ldn ON pc.user_id = ldn."userId"
CROSS JOIN caller_authorization AS caller_scope
WHERE caller_scope.allowed
GROUP BY pc.user_id, ldn."displayName"
ORDER BY avg_vs_guild DESC;
$$;

ALTER FUNCTION public.get_player_performance_summary(p_guild_code text, p_season text, p_rarities text[]) OWNER TO postgres;

CREATE FUNCTION public.get_player_performance_vs_cluster(p_guild text, p_season text) RETURNS TABLE(display_name text, boss_name text, encounter_type text, battle_count bigint, player_avg_damage numeric, guild_avg_damage numeric, cluster_avg_damage numeric, vs_guild_percent numeric, vs_cluster_percent numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH player_stats AS (
    -- Get each player's average damage per boss
    SELECT
      d."displayName"::TEXT,
      d."Name"::TEXT as boss_name,
      CASE
        WHEN d."encounterId" = 0 THEN 'Boss'::TEXT
        ELSE 'Prime'::TEXT
      END as encounter_type,
      COUNT(*)::BIGINT as battle_count,
      AVG(d."damageDealt")::NUMERIC as avg_damage
    FROM "EOT_GR_data" d
    WHERE d."Guild" = p_guild
      AND d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND d."rarity" IN ('Legendary', 'Mythic')
      AND d."damageDealt" > 0
    GROUP BY d."displayName", d."Name", d."encounterId"
    HAVING COUNT(*) >= 3  -- Minimum battles for meaningful comparison
  ),
  guild_avgs AS (
    -- Get guild's average damage per boss
    SELECT
      d."Name"::TEXT as boss_name,
      CASE
        WHEN d."encounterId" = 0 THEN 'Boss'::TEXT
        ELSE 'Prime'::TEXT
      END as encounter_type,
      AVG(d."damageDealt")::NUMERIC as avg_damage
    FROM "EOT_GR_data" d
    WHERE d."Guild" = p_guild
      AND d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND d."rarity" IN ('Legendary', 'Mythic')
      AND d."damageDealt" > 0
    GROUP BY d."Name", d."encounterId"
  ),
  cluster_avgs AS (
    -- Get cluster-wide average damage per boss (ALL guilds)
    SELECT
      d."Name"::TEXT as boss_name,
      CASE
        WHEN d."encounterId" = 0 THEN 'Boss'::TEXT
        ELSE 'Prime'::TEXT
      END as encounter_type,
      AVG(d."damageDealt")::NUMERIC as avg_damage
    FROM "EOT_GR_data" d
    WHERE d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND d."rarity" IN ('Legendary', 'Mythic')
      AND d."damageDealt" > 0
      AND d."Guild" NOT IN ('TEST', 'BA')  -- Exclude test and removed guilds
    GROUP BY d."Name", d."encounterId"
  )
  SELECT
    ps."displayName",
    ps.boss_name,
    ps.encounter_type,
    ps.battle_count,
    ps.avg_damage as player_avg_damage,
    ga.avg_damage as guild_avg_damage,
    ca.avg_damage as cluster_avg_damage,
    ROUND(((ps.avg_damage / NULLIF(ga.avg_damage, 0) - 1) * 100)::NUMERIC, 1) as vs_guild_percent,
    ROUND(((ps.avg_damage / NULLIF(ca.avg_damage, 0) - 1) * 100)::NUMERIC, 1) as vs_cluster_percent
  FROM player_stats ps
  JOIN guild_avgs ga ON ps.boss_name = ga.boss_name AND ps.encounter_type = ga.encounter_type
  JOIN cluster_avgs ca ON ps.boss_name = ca.boss_name AND ps.encounter_type = ca.encounter_type
  ORDER BY ps."displayName", ps.boss_name;
END;
$$;

ALTER FUNCTION public.get_player_performance_vs_cluster(p_guild text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_player_prime_performance(guild_code_param text, season_param text) RETURNS TABLE(display_name text, prime_name text, encounter_id integer, player_avg numeric, battle_count integer, biggest_hit bigint, player_vs_guild_avg numeric, player_vs_cluster_avg numeric, set_num integer, tier integer, rarity text, boss_preference text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  WITH player_prime_stats AS (
    SELECT
      e."displayName",
      CONCAT(e."Name", '_', e.rarity) AS prime_key,
      COALESCE(e."encounterId", 0)::integer AS enc_id,
      e.tier AS tier_val,
      e.set AS set_val,
      e.rarity AS rarity_val,
      -- Non-sweep damage/count: always counted.
      SUM(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      )::numeric AS non_sweep_damage,
      COUNT(*) FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      )::integer AS non_sweep_count,
      -- Sweep damages: re-included only if they clear the qualifying gate.
      array_agg(e."damageDealt"::numeric) FILTER (
        WHERE e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp"
      ) AS sweep_damages,
      -- biggest_hit stays non-sweep (matches the live prime def) so this migration
      -- changes ONLY player_avg / battle_count / vs%.
      MAX(e."damageDealt") FILTER (
        WHERE NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      ) AS b_hit
    FROM "EOT_GR_data" e
    WHERE e."Season" = season_param
      AND e."Guild" = guild_code_param
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary','Mythic')
      AND e."damageDealt" > 0
      AND COALESCE(e."encounterId", 0) IN (1,2)
    GROUP BY e."displayName", prime_key, enc_id, e.tier, e.set, e.rarity
  ),
  guild_avg AS (
    SELECT
      CONCAT("Name", '_', rarity) AS prime_key,
      COALESCE("encounterId", 0)::integer AS enc_id,
      rarity AS rarity_val,
      AVG("damageDealt")::numeric AS g_avg
    FROM "EOT_GR_data"
    WHERE "Season" = season_param
      AND "Guild" = guild_code_param
      AND "damageType" = 'Battle'
      AND rarity IN ('Legendary','Mythic')
      AND "damageDealt" > 0
      AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp")
      AND COALESCE("encounterId", 0) IN (1,2)
    GROUP BY prime_key, enc_id, rarity
  ),
  cluster_avg AS (
    SELECT
      CONCAT(e."Name", '_', e.rarity) AS prime_key,
      COALESCE(e."encounterId", 0)::integer AS enc_id,
      e.rarity AS rarity_val,
      AVG(e."damageDealt")::numeric AS c_avg
    FROM "EOT_GR_data" e
    LEFT JOIN guild_config gc ON gc.guild_code = e."Guild"
    WHERE e."Season" = season_param
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary','Mythic')
      AND e."damageDealt" > 0
      AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
      AND gc.cluster_code = (SELECT cluster_code FROM guild_config WHERE guild_code = guild_code_param LIMIT 1)
      AND COALESCE(e."encounterId", 0) IN (1,2)
    GROUP BY prime_key, enc_id, e.rarity
  )
  SELECT
    p."displayName" AS display_name,
    p.prime_key AS prime_name,
    p.enc_id AS encounter_id,
    -- player_avg with the qualifying-sweep gate = GREATEST(player non-sweep avg, guild avg)
    CASE
      WHEN COALESCE(p.non_sweep_count, 0)
           + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0) > 0
      THEN (
        (COALESCE(p.non_sweep_damage, 0) + COALESCE(qualifying_sweep_sum(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))
        / (COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))
      )
      ELSE 0
    END AS player_avg,
    (COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))::integer AS battle_count,
    p.b_hit AS biggest_hit,
    CASE
      WHEN g.g_avg > 0 THEN ROUND((
        (
          (COALESCE(p.non_sweep_damage, 0) + COALESCE(qualifying_sweep_sum(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0))
          / NULLIF(COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), g.g_avg)), 0), 0)
          / g.g_avg
        ) - 1) * 100, 1)
      ELSE 0
    END AS player_vs_guild_avg,
    CASE
      WHEN c.c_avg > 0 THEN ROUND((
        (
          (COALESCE(p.non_sweep_damage, 0) + COALESCE(qualifying_sweep_sum(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), c.c_avg)), 0))
          / NULLIF(COALESCE(p.non_sweep_count, 0) + COALESCE(qualifying_sweep_count(p.sweep_damages, GREATEST(p.non_sweep_damage / NULLIF(p.non_sweep_count, 0), c.c_avg)), 0), 0)
          / c.c_avg
        ) - 1) * 100, 1)
      ELSE 0
    END AS player_vs_cluster_avg,
    p.set_val AS set_num,
    p.tier_val AS tier,
    p.rarity_val AS rarity,
    'neutral' AS boss_preference
  FROM player_prime_stats p
  LEFT JOIN guild_avg g ON p.prime_key = g.prime_key AND p.enc_id = g.enc_id AND p.rarity_val = g.rarity_val
  LEFT JOIN cluster_avg c ON p.prime_key = c.prime_key AND p.enc_id = c.enc_id AND p.rarity_val = c.rarity_val
  ORDER BY p."displayName", p.rarity_val DESC, p.set_val, p.enc_id;
$$;

ALTER FUNCTION public.get_player_prime_performance(guild_code_param text, season_param text) OWNER TO postgres;

CREATE FUNCTION public.get_player_rankings(p_guild_code text, p_season integer DEFAULT NULL::integer, p_sort_by text DEFAULT 'win_rate'::text, p_limit integer DEFAULT 50) RETURNS TABLE(rank integer, player_id text, player_name text, total_attempts integer, wins integer, win_rate numeric, total_damage bigint, avg_tokens numeric)
    LANGUAGE sql STABLE
    AS $$
WITH war_scope AS (
  SELECT war_id
  FROM guild_war_matches
  WHERE guild_code = p_guild_code
    AND (p_season IS NULL OR war_season = p_season)
),
battle_rollup AS (
  SELECT
    war_id,
    attacker_player_id AS player_id,
    MAX(attacker_player_name) AS player_name,
    COUNT(*)::INTEGER AS total_attempts,
    SUM(CASE WHEN war_zone_captured(attempt_result, defender_units_json) THEN 1 ELSE 0 END)::INTEGER AS wins,
    SUM(COALESCE(damage_dealt, 0))::BIGINT AS total_damage,
    1::INTEGER AS wars_played
  FROM guild_war_battles
  WHERE guild_code = p_guild_code
    AND war_id IN (SELECT war_id FROM war_scope)
  GROUP BY war_id, attacker_player_id
),
battle_agg AS (
  SELECT
    player_id,
    MAX(player_name) AS player_name,
    SUM(total_attempts)::INTEGER AS total_attempts,
    SUM(wins)::INTEGER AS wins,
    SUM(total_damage)::BIGINT AS total_damage,
    SUM(wars_played)::INTEGER AS wars_played
  FROM battle_rollup
  GROUP BY player_id
),
participation_latest AS (
  SELECT DISTINCT ON (guild_code, war_id, user_id)
    war_id,
    user_id,
    attempts_used,
    attempts_remaining
  FROM guild_war_participation
  WHERE guild_code = p_guild_code
    AND war_id IN (SELECT war_id FROM war_scope)
  ORDER BY guild_code, war_id, user_id, snapshot_at DESC
),
participation_agg AS (
  SELECT
    user_id,
    SUM(COALESCE(attempts_used, 0))::INTEGER AS attempts_used,
    SUM(COALESCE(attempts_remaining, 0))::INTEGER AS attempts_remaining,
    BOOL_OR(attempts_used IS NOT NULL OR attempts_remaining IS NOT NULL) AS has_token_data
  FROM participation_latest
  GROUP BY user_id
),
joined AS (
  SELECT
    b.player_id,
    b.player_name,
    b.total_attempts,
    b.wins,
    b.total_damage,
    CASE WHEN b.total_attempts > 0 THEN b.wins::NUMERIC / b.total_attempts ELSE NULL END AS win_rate,
    COALESCE(
      CASE WHEN p.has_token_data THEN p.attempts_used END,
      b.total_attempts
    ) AS tokens_used,
    b.wars_played
  FROM battle_agg b
  LEFT JOIN participation_agg p ON p.user_id = b.player_id
),
ranked AS (
  SELECT
    *,
    CASE
      WHEN wars_played > 0 THEN tokens_used::NUMERIC / wars_played
      ELSE NULL
    END AS avg_tokens,
    ROW_NUMBER() OVER (
      ORDER BY
        CASE WHEN p_sort_by = 'win_rate' THEN win_rate END DESC NULLS LAST,
        CASE WHEN p_sort_by = 'damage' THEN total_damage END DESC NULLS LAST,
        CASE WHEN p_sort_by = 'attempts' THEN total_attempts END DESC NULLS LAST,
        CASE WHEN p_sort_by = 'wins' THEN wins END DESC NULLS LAST,
        total_attempts DESC
    ) AS rank
  FROM joined
)
SELECT
  rank,
  player_id,
  player_name,
  total_attempts,
  wins,
  win_rate,
  total_damage,
  avg_tokens
FROM ranked
ORDER BY rank
LIMIT p_limit;
$$;

ALTER FUNCTION public.get_player_rankings(p_guild_code text, p_season integer, p_sort_by text, p_limit integer) OWNER TO postgres;

CREATE FUNCTION public.get_player_stats_comprehensive(p_guild_code text, p_season text, p_display_name text) RETURNS jsonb
    LANGUAGE sql
    AS $$
WITH cluster_info AS (
  SELECT cluster_code
  FROM guild_config
  WHERE guild_code = p_guild_code
  LIMIT 1
),
battle AS (
  SELECT
    "Name" AS name,
    tier,
    set,
    "encounterId" AS encounter_id,
    "damageDealt" AS damage_dealt,
    "damageType" AS damage_type,
    "maxHp" AS max_hp,
    "remainingHp" AS remaining_hp,
    rarity,
    "loopIndex" AS loop_index,
    ( "remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp" AND "damageType" = 'Battle' ) AS is_sweep,
    ( "remainingHp" = 0 AND "damageDealt" >= "maxHp" AND "damageType" = 'Battle' ) AS is_one_shot,
    ( "damageType" = 'Battle' AND "damageDealt" = 0 ) AS is_crash
  FROM "EOT_GR_data"
  WHERE "Guild" = p_guild_code
    AND "Season" = p_season
    AND "displayName" = p_display_name
),
agg AS (
  SELECT
    coalesce(sum(CASE WHEN damage_type IN ('Battle','Bomb') THEN damage_dealt END), 0) AS total_damage,
    avg(nullif(CASE
      WHEN damage_type = 'Battle'
        AND NOT is_sweep
        AND damage_dealt > 0
      THEN damage_dealt
    END, 0)) AS avg_damage_per_hit,
    count(*) FILTER (WHERE damage_type = 'Battle') AS tokens_used,
    count(*) FILTER (WHERE damage_type = 'Bomb') AS bombs_used,
    count(*) FILTER (WHERE damage_type = 'Battle' AND rarity IN ('Legendary','Mythic')) AS legendary_tokens_used,
    count(*) FILTER (WHERE damage_type = 'Bomb' AND rarity IN ('Legendary','Mythic')) AS legendary_bombs_used,
    count(*) FILTER (WHERE remaining_hp = 0 AND damage_dealt > 0) AS kills,
    count(*) FILTER (WHERE is_sweep) AS sweeps,
    count(*) FILTER (WHERE is_one_shot) AS one_shots,
    count(*) FILTER (WHERE is_crash) AS crashes
  FROM battle
),
-- Reference averages: sweep-free baselines — per name+rarity+set
guild_avg AS (
  SELECT
    "Name" AS name,
    rarity,
    set AS set_val,
    CASE WHEN "encounterId" = 0 THEN 'boss' ELSE 'prime' END AS kind,
    avg("damageDealt")::numeric AS avg_damage
  FROM "EOT_GR_data"
  WHERE "Guild" = p_guild_code
    AND "Season" = p_season
    AND "damageType" = 'Battle'
    AND rarity IN ('Legendary', 'Mythic')
    AND "damageDealt" > 0
    AND NOT ("remainingHp" = 0 AND "maxHp" > 0 AND "damageDealt" < "maxHp")
  GROUP BY "Name", rarity, set, CASE WHEN "encounterId" = 0 THEN 'boss' ELSE 'prime' END
),
cluster_avg AS (
  SELECT
    e."Name" AS name,
    e.rarity,
    e.set AS set_val,
    CASE WHEN e."encounterId" = 0 THEN 'boss' ELSE 'prime' END AS kind,
    avg(e."damageDealt")::numeric AS avg_damage
  FROM "EOT_GR_data" e
  JOIN guild_config gc ON gc.guild_code = e."Guild"
  CROSS JOIN cluster_info ci
  WHERE e."Season" = p_season
    AND gc.cluster_code = ci.cluster_code
    AND e."damageType" = 'Battle'
    AND e.rarity IN ('Legendary', 'Mythic')
    AND e."damageDealt" > 0
    AND NOT (e."remainingHp" = 0 AND e."maxHp" > 0 AND e."damageDealt" < e."maxHp")
    AND ci.cluster_code IS NOT NULL
  GROUP BY e."Name", e.rarity, e.set, CASE WHEN e."encounterId" = 0 THEN 'boss' ELSE 'prime' END
),
-- Player per-boss stats: grouped by name+rarity+set
bosses AS (
  SELECT
    CASE WHEN min(encounter_id) = 0 THEN 'boss' ELSE 'prime' END AS kind,
    concat(name, '_', rarity, '_', set) AS boss_key,
    name,
    set AS set_val,
    max(tier) AS tier_max,
    rarity,
    min(encounter_id) AS encounter_id,
    sum(damage_dealt) FILTER ( WHERE NOT is_sweep ) AS damage,
    count(*) FILTER ( WHERE damage_type = 'Battle' AND NOT is_sweep ) AS tokens,
    max(damage_dealt) AS biggest_hit,
    count(*) FILTER (WHERE is_sweep) AS sweeps,
    count(*) FILTER (WHERE is_one_shot) AS one_shots,
    count(*) FILTER (WHERE is_crash) AS crashes,
    count(*) FILTER (WHERE damage_type = 'Battle') AS total_tokens,
    sum(damage_dealt) FILTER (WHERE damage_type = 'Battle') AS total_damage_with_sweeps,
    avg(damage_dealt) FILTER (WHERE damage_type = 'Battle' AND NOT is_sweep AND damage_dealt > 0)::numeric AS player_avg,
    array_agg(damage_dealt::numeric) FILTER (WHERE is_sweep AND damage_dealt > 0) AS sweep_damages
  FROM battle
  WHERE rarity IN ('Legendary','Mythic') AND damage_type = 'Battle'
  GROUP BY name, rarity, set
),
boss_with_vs AS (
  SELECT
    b.*,
    -- Metadata: qualifying sweep counts for JSON output
    coalesce(qualifying_sweep_count(b.sweep_damages, GREATEST(b.player_avg, ga.avg_damage)), 0) AS qualifying_sweeps_guild,
    coalesce(qualifying_sweep_count(b.sweep_damages, GREATEST(b.player_avg, ca.avg_damage)), 0) AS qualifying_sweeps_cluster,
    -- Adjusted damage/count for avgDamage display
    coalesce(b.damage, 0) + coalesce(qualifying_sweep_sum(b.sweep_damages, GREATEST(b.player_avg, ga.avg_damage)), 0) AS adj_damage_guild,
    (coalesce(b.tokens, 0) + coalesce(qualifying_sweep_count(b.sweep_damages, GREATEST(b.player_avg, ga.avg_damage)), 0)) AS adj_count_guild,
    -- Per-boss performance percentages (shared function)
    ROUND(COALESCE(calc_boss_performance_pct(b.damage, b.tokens, b.sweep_damages, ga.avg_damage, b.player_avg), 0)::numeric, 1) AS vs_guild,
    ROUND(COALESCE(calc_boss_performance_pct(b.damage, b.tokens, b.sweep_damages, ca.avg_damage, b.player_avg), 0)::numeric, 1) AS vs_cluster
  FROM bosses b
  LEFT JOIN guild_avg ga ON ga.name = b.name AND ga.rarity = b.rarity AND ga.set_val = b.set_val AND ga.kind = b.kind
  LEFT JOIN cluster_avg ca ON ca.name = b.name AND ca.rarity = b.rarity AND ca.set_val = b.set_val AND ca.kind = b.kind
),
overall_weighted AS (
  SELECT
    CASE WHEN sum(coalesce(tokens, 0) + qualifying_sweeps_guild) > 0
      THEN sum(vs_guild * (coalesce(tokens, 0) + qualifying_sweeps_guild)) / sum(coalesce(tokens, 0) + qualifying_sweeps_guild)
      ELSE 0 END AS weighted_vs_guild,
    CASE WHEN sum(coalesce(tokens, 0) + qualifying_sweeps_cluster) > 0
      THEN sum(vs_cluster * (coalesce(tokens, 0) + qualifying_sweeps_cluster)) / sum(coalesce(tokens, 0) + qualifying_sweeps_cluster)
      ELSE 0 END AS weighted_vs_cluster
  FROM boss_with_vs
  WHERE (coalesce(tokens, 0) + qualifying_sweeps_guild) > 0
     OR (coalesce(tokens, 0) + qualifying_sweeps_cluster) > 0
),
boss_map AS (
  SELECT coalesce(
    jsonb_object_agg(
      b.boss_key,
      jsonb_build_object(
        'damage', coalesce(b.damage,0),
        'tokens', coalesce(b.tokens,0),
        'avgDamage', CASE WHEN b.adj_count_guild > 0 THEN b.adj_damage_guild::float / b.adj_count_guild ELSE 0 END,
        'biggestHit', coalesce(b.biggest_hit,0),
        'sweeps', coalesce(b.sweeps,0),
        'oneShots', coalesce(b.one_shots,0),
        'crashes', coalesce(b.crashes,0),
        'totalTokens', coalesce(b.total_tokens,0),
        'totalDamageWithSweeps', coalesce(b.total_damage_with_sweeps,0),
        'avgDamageWithSweeps', CASE WHEN b.total_tokens > 0 THEN b.total_damage_with_sweeps::float / b.total_tokens ELSE 0 END,
        'set', b.set_val,
        'tier', b.tier_max,
        'rarity', b.rarity,
        'encounterId', b.encounter_id,
        'vsGuildAvg', b.vs_guild,
        'vsClusterAvg', b.vs_cluster,
        'qualifyingSweepsGuild', coalesce(b.qualifying_sweeps_guild, 0),
        'qualifyingSweepsCluster', coalesce(b.qualifying_sweeps_cluster, 0)
      )
    ) FILTER (WHERE b.kind = 'boss'),
    '{}'::jsonb
  ) AS boss_stats,
  coalesce(
    jsonb_object_agg(
      b.boss_key,
      jsonb_build_object(
        'damage', coalesce(b.damage,0),
        'tokens', coalesce(b.tokens,0),
        'avgDamage', CASE WHEN b.adj_count_guild > 0 THEN b.adj_damage_guild::float / b.adj_count_guild ELSE 0 END,
        'biggestHit', coalesce(b.biggest_hit,0),
        'sweeps', coalesce(b.sweeps,0),
        'oneShots', coalesce(b.one_shots,0),
        'crashes', coalesce(b.crashes,0),
        'totalTokens', coalesce(b.total_tokens,0),
        'totalDamageWithSweeps', coalesce(b.total_damage_with_sweeps,0),
        'avgDamageWithSweeps', CASE WHEN b.total_tokens > 0 THEN b.total_damage_with_sweeps::float / b.total_tokens ELSE 0 END,
        'set', b.set_val,
        'tier', b.tier_max,
        'rarity', b.rarity,
        'encounterId', b.encounter_id,
        'vsGuildAvg', b.vs_guild,
        'vsClusterAvg', b.vs_cluster,
        'qualifyingSweepsGuild', coalesce(b.qualifying_sweeps_guild, 0),
        'qualifyingSweepsCluster', coalesce(b.qualifying_sweeps_cluster, 0)
      )
    ) FILTER (WHERE b.kind = 'prime'),
    '{}'::jsonb
  ) AS prime_stats
  FROM boss_with_vs b
),
historical_tokens AS (
  SELECT coalesce(
    jsonb_object_agg(season, token_count),
    '{}'::jsonb
  ) AS season_tokens
  FROM (
    SELECT "Season" AS season, count(*) AS token_count
    FROM "EOT_GR_data"
    WHERE "Guild" = p_guild_code
      AND "displayName" = p_display_name
      AND "damageType" = 'Battle'
      AND "damageDealt" > 0
    GROUP BY "Season"
  ) t
)
SELECT jsonb_build_object(
  'totalDamage', agg.total_damage,
  'avgDamagePerHit', coalesce(agg.avg_damage_per_hit, 0),
  'tokensUsed', agg.tokens_used,
  'bombsUsed', agg.bombs_used,
  'legendaryTokensUsed', agg.legendary_tokens_used,
  'legendaryBombsUsed', agg.legendary_bombs_used,
  'maxPossibleTokens', 0,
  'maxPossibleBombs', 0,
  'isTokenOffender', false,
  'isTokenAbuser', false,
  'kills', agg.kills,
  'sweeps', agg.sweeps,
  'oneShots', agg.one_shots,
  'crashes', agg.crashes,
  'vsClusterAvg', coalesce(round(ow.weighted_vs_cluster::numeric, 1), 0),
  'vsGuildAvg', coalesce(round(ow.weighted_vs_guild::numeric, 1), 0),
  'weightedContribution', 0,
  'bossStats', coalesce(boss_map.boss_stats, '{}'::jsonb),
  'primeStats', coalesce(boss_map.prime_stats, '{}'::jsonb),
  'historicalTokens', coalesce(historical_tokens.season_tokens, '{}'::jsonb)
) AS result
FROM agg
CROSS JOIN boss_map
CROSS JOIN historical_tokens
CROSS JOIN overall_weighted ow;
$$;

ALTER FUNCTION public.get_player_stats_comprehensive(p_guild_code text, p_season text, p_display_name text) OWNER TO postgres;

CREATE FUNCTION public.get_player_team_compositions(p_guild_code text, p_season_limit integer DEFAULT 10) RETURNS TABLE(player_name text, boss_name text, team_compositions json, usage_count integer)
    LANGUAGE plpgsql
    AS $_$
BEGIN
  RETURN QUERY
  WITH recent_battles AS (
    -- Get recent battles for the guild
    SELECT DISTINCT
      battle."displayName" as player_name,
      CASE
        WHEN battle."encounterIndex" = 0 THEN battle."type"
        ELSE bm.boss_name
      END as boss,
      battle."heroDetails" as heroes_text,
      battle."Season" as season
    FROM "EOT_GR_data" battle
    LEFT JOIN boss_mapping bm ON
      battle."type" = bm.boss_type AND
      battle."encounterIndex" = bm.encounter_index
    WHERE
      battle."Guild" = p_guild_code
      AND battle."heroDetails" IS NOT NULL
      AND battle."heroDetails" != '[]'
      AND battle."Season" IN (
        SELECT DISTINCT season_data."Season"
        FROM "EOT_GR_data" season_data
        WHERE season_data."Guild" = p_guild_code
          AND season_data."Season" ~ '^\d+$'  -- LEX-FIX 2026-05-07: guard cast
        ORDER BY (season_data."Season"::int) DESC  -- LEX-FIX 2026-05-07: was ORDER BY "Season" DESC
        LIMIT p_season_limit
      )
  ),
  team_aggregation AS (
    -- Aggregate teams by player and boss without DISTINCT on JSON
    SELECT
      rb.player_name,
      rb.boss,
      json_agg(rb.heroes_text::json) as all_teams,  -- No DISTINCT, just aggregate all
      COUNT(*) as times_used
    FROM recent_battles rb
    WHERE rb.boss IS NOT NULL
    GROUP BY rb.player_name, rb.boss
  )
  SELECT
    ta.player_name,
    ta.boss as boss_name,
    ta.all_teams as team_compositions,
    ta.times_used::INT as usage_count
  FROM team_aggregation ta
  ORDER BY ta.player_name, ta.boss;
END;
$_$;

ALTER FUNCTION public.get_player_team_compositions(p_guild_code text, p_season_limit integer) OWNER TO postgres;

CREATE FUNCTION public.get_player_team_compositions_simple(p_guild_code text, p_season_limit integer DEFAULT 10) RETURNS TABLE(player_name text, boss_name text, team_compositions text, usage_count integer)
    LANGUAGE plpgsql
    AS $_$
BEGIN
  RETURN QUERY
  SELECT
    battle."displayName" as player_name,
    CASE
      WHEN battle."encounterIndex" = 0 THEN battle."type"
      ELSE bm.boss_name
    END as boss_name,
    string_agg(DISTINCT battle."heroDetails", '|||') as team_compositions,
    COUNT(*)::INT as usage_count
  FROM "EOT_GR_data" battle
  LEFT JOIN boss_mapping bm ON
    battle."type" = bm.boss_type AND
    battle."encounterIndex" = bm.encounter_index
  WHERE
    battle."Guild" = p_guild_code
    AND battle."heroDetails" IS NOT NULL
    AND battle."heroDetails" != '[]'
    AND battle."Season" IN (
      SELECT DISTINCT season_data."Season"
      FROM "EOT_GR_data" season_data
      WHERE season_data."Guild" = p_guild_code
        AND season_data."Season" ~ '^\d+$'  -- LEX-FIX 2026-05-07: guard cast
      ORDER BY (season_data."Season"::int) DESC  -- LEX-FIX 2026-05-07: was ORDER BY "Season" DESC
      LIMIT p_season_limit
    )
  GROUP BY
    battle."displayName",
    CASE
      WHEN battle."encounterIndex" = 0 THEN battle."type"
      ELSE bm.boss_name
    END
  ORDER BY player_name, boss_name;
END;
$_$;

ALTER FUNCTION public.get_player_team_compositions_simple(p_guild_code text, p_season_limit integer) OWNER TO postgres;

CREATE FUNCTION public.get_player_team_usage(p_player_name text, p_guild_code text, p_season text DEFAULT NULL::text) RETURNS TABLE(boss_name text, boss_type text, rarity text, set_num integer, rarity_set text, encounter_index integer, encounter_type text, team_hash text, team_composition text, attack_count bigint, avg_damage numeric, meta_team text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_season text;
  v_current_season text;
  v_min_attacks int := 2;
BEGIN
  SELECT get_current_season() INTO v_current_season;

  IF p_season IS NULL THEN
    v_season := v_current_season;
  ELSE
    v_season := p_season;
  END IF;

  IF v_current_season IS NOT NULL AND v_season = v_current_season THEN
    v_min_attacks := 1;
  END IF;

  RETURN QUERY
  WITH player_battles AS (
    SELECT
      d."Name" as p_boss_name,
      d.type as p_boss_type,
      d.rarity as p_rarity,
      d.set as p_set,
      d."encounterIndex" as p_encounter_index,
      d."encounterType" as p_encounter_type,
      d."heroDetails" as p_hero_details,
      d."machineOfWarDetails" as p_mow_details,
      d."damageDealt" as p_damage,
      generate_team_hash(d."heroDetails", d."machineOfWarDetails") as p_team_hash,
      get_team_display(d."heroDetails", d."machineOfWarDetails") as p_team_composition
    FROM "EOT_GR_data" d
    WHERE d."displayName" = p_player_name
      AND d."Guild" = p_guild_code
      AND d."Season" = v_season
      AND d."damageType" IN ('Battle', 'Bomb')
      AND d."heroDetails" IS NOT NULL
      AND d."heroDetails" != '[]'
      AND d."heroDetails" != ''
  ),
  aggregated AS (
    SELECT
      pb.p_boss_name,
      pb.p_boss_type,
      pb.p_rarity,
      pb.p_set,
      pb.p_encounter_index,
      pb.p_encounter_type,
      pb.p_team_hash,
      pb.p_team_composition,
      pb.p_hero_details,
      COUNT(*) as atk_count,
      AVG(pb.p_damage) as avg_dmg
    FROM player_battles pb
    WHERE pb.p_team_hash IS NOT NULL
      AND pb.p_team_composition IS NOT NULL
    GROUP BY
      pb.p_boss_name,
      pb.p_boss_type,
      pb.p_rarity,
      pb.p_set,
      pb.p_encounter_index,
      pb.p_encounter_type,
      pb.p_team_hash,
      pb.p_team_composition,
      pb.p_hero_details
    HAVING COUNT(*) >= v_min_attacks
  )
  SELECT
    a.p_boss_name as boss_name,
    a.p_boss_type as boss_type,
    a.p_rarity as rarity,
    a.p_set as set_num,
    get_rarity_set(a.p_rarity, a.p_set) as rarity_set,
    a.p_encounter_index as encounter_index,
    a.p_encounter_type as encounter_type,
    a.p_team_hash as team_hash,
    a.p_team_composition as team_composition,
    a.atk_count as attack_count,
    a.avg_dmg as avg_damage,
    get_meta_team(a.p_hero_details) as meta_team
  FROM aggregated a
  ORDER BY a.atk_count DESC;
END;
$$;

ALTER FUNCTION public.get_player_team_usage(p_player_name text, p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_player_token_burn_history(p_guild_code text, p_player_id text DEFAULT NULL::text, p_display_name text DEFAULT NULL::text, p_limit integer DEFAULT 24) RETURNS TABLE(player_id text, display_name text, season text, season_start_at timestamp with time zone, season_end_at timestamp with time zone, burned_tokens integer, time_over_cap_seconds integer, updated_at timestamp with time zone)
    LANGUAGE sql
    SET search_path TO 'public'
    AS $_$
  select
    s.player_id,
    s.display_name,
    s.season,
    sc.starts_at as season_start_at,
    sc.ends_at as season_end_at,
    coalesce(s.burned_tokens, 0) as burned_tokens,
    coalesce(s.time_over_cap_seconds, 0) as time_over_cap_seconds,
    s.updated_at
  from public.token_burn_state s
  left join public.season_calendar sc
    on s.season ~ '^\d+$'
   and sc.season_id = s.season::integer
  where s.guild_code = p_guild_code
    and (
      (p_player_id is not null and s.player_id = p_player_id)
      or (p_player_id is null and p_display_name is not null and upper(coalesce(s.display_name, '')) = upper(p_display_name))
      or (p_player_id is null and p_display_name is null)
    )
  order by
    case when s.season ~ '^\d+$' then s.season::integer else 0 end desc,
    s.updated_at desc
  limit greatest(1, least(coalesce(p_limit, 24), 200));
$_$;

ALTER FUNCTION public.get_player_token_burn_history(p_guild_code text, p_player_id text, p_display_name text, p_limit integer) OWNER TO postgres;

CREATE FUNCTION public.get_player_token_state(p_guild_code text, p_season text DEFAULT NULL::text, p_cluster_code text DEFAULT NULL::text, p_player_id text DEFAULT NULL::text) RETURNS TABLE(player_id text, display_name text, discord_user_id text, tokens_available integer, is_capped boolean, time_to_next_token interval, data_source text, token_next_in_seconds integer, last_sync_at timestamp with time zone, tokens_used integer, max_possible integer, burned_tokens integer, time_over_cap_seconds integer, last_battle_time timestamp with time zone, bombs_available integer, bomb_next_in_seconds integer, post_snapshot_spends integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
declare
  v_season text;
  v_is_service boolean := COALESCE(
    NULLIF(NULLIF(current_setting('role', true), ''), 'none'),
    NULLIF(session_user, '')
  ) = 'service_role';
  v_requester_id uuid := auth.uid();
  v_requester_role text := null;
  v_requester_guild text := null;
  v_requester_cluster text := null;
  v_target_cluster text := null;
begin
  -- WI-3139: authorization is bound to the EFFECTIVE DATABASE ROLE. Trusted
  -- service execution is proven only by the service_role database role; the
  -- former "null auth.uid() means trusted" bypass (WI-3660 partial guard) is
  -- removed. Every non-service caller must resolve to a current same-guild
  -- membership, or officer/admin in the same cluster. Belt-and-suspenders with
  -- the service_role-only ACL in this migration.
  if not v_is_service then
    if v_requester_id is null then
      return;
    end if;

    select pm.guild_code, pm.cluster_code, pm.role
      into v_requester_guild, v_requester_cluster, v_requester_role
    from public.player_with_cluster pm
    where pm.user_id = v_requester_id
      and pm.is_current = true
    limit 1;

    -- WI-3790: resolve the TARGET guild's cluster from guild_config (canonical,
    -- UNIQUE guild_code->cluster). p_cluster_code stays a downstream data filter
    -- only, NOT the auth boundary.
    select gc.cluster_code::text
      into v_target_cluster
    from public.guild_config gc
    where gc.guild_code = p_guild_code
    limit 1;

    if v_requester_guild is distinct from p_guild_code then
      if v_requester_role not in ('officer', 'admin') then
        return;
      end if;
      if v_target_cluster is null or v_requester_cluster is distinct from v_target_cluster then
        return;
      end if;
    end if;
  end if;

  -- Resolve season
  if p_season is null or trim(p_season) = '' then
    -- WI-2570 follow-up 2: numeric max — "Season" is TEXT, so max("Season")
    -- returns '99' once seasons reach 100 (lex-max; same defect as WI-1517).
    select max(d.season_num)::text into v_season
    from "EOT_GR_data" d
    where d."Guild" = p_guild_code
      and (p_cluster_code is null or d.cluster_code = p_cluster_code);
  else
    v_season := trim(p_season);
  end if;

  if v_season is null then
    return;
  end if;

  return query
  with members as (
    select
      pm.player_id,
      pm.display_name,
      pm.discord_user_id::text as discord_user_id,
      pm.last_sync_tokens,
      pm.next_token_seconds,
      pm.last_sync_at::timestamptz as last_sync_at,
      pm.api_key_is_valid,
      pm.tacticus_api_key_encrypted,
      pm.last_sync_bombs,
      pm.next_bomb_seconds
    from public.player_mapping pm
    where pm.guild_code = p_guild_code
      and pm.is_current = true
      and (p_player_id is null or pm.player_id = p_player_id)
  ),
  -- Spends the DB knows happened AFTER a member's last sync snapshot.
  -- WI-2640 Phase 3: these no longer INVALIDATE the snapshot — they are the
  -- projection input (ordered timestamp arrays) for project_token_snapshot.
  -- Scans the previous season too: at rollover a snapshot taken before the
  -- boundary can miss a previous-season spend after last_sync_at.
  -- DISTINCT on "startedOn" is REQUIRED: (userId, startedOn) is NOT unique in
  -- EOT_GR_data — one battle-start emits multiple rows (per-encounter
  -- rollups), and the projection decrements one token per array element. The
  -- authoritative replay walks SELECT DISTINCT "startedOn" for the same
  -- reason (see 20260716180000). With DISTINCT the agg ORDER BY must match
  -- the DISTINCT expression (and the helper re-sorts in its unnest anyway).
  recent_spend as (
    select
      m2.player_id,
      count(distinct d."startedOn") filter (where d."damageType" = 'Battle')::int as battles_after_sync,
      count(distinct d."startedOn") filter (where d."damageType" = 'Bomb')::int as bombs_after_sync,
      array_agg(distinct d."startedOn"::timestamptz)
        filter (where d."damageType" = 'Battle') as battle_spends,
      array_agg(distinct d."startedOn"::timestamptz)
        filter (where d."damageType" = 'Bomb') as bomb_spends
    from members m2
    join public."EOT_GR_data" d
      on d."userId" = m2.player_id
      and d."Guild" = p_guild_code
      and (
        d."Season" = v_season
        or (v_season ~ '^\d+$' and d."Season" = (v_season::int - 1)::text)
      )
      and d."damageType" in ('Battle', 'Bomb')
      and (p_cluster_code is null or d.cluster_code = p_cluster_code)
    where m2.last_sync_at is not null
      and d."startedOn"::timestamptz > m2.last_sync_at
    group by m2.player_id
  ),
  battle_rows as (
    select
      d."userId" as player_id,
      d."damageType" as damage_type,
      d."damageDealt" as damage_dealt,
      d."startedOn"::timestamptz as started_on
    from public."EOT_GR_data" d
    where d."Guild" = p_guild_code
      and d."Season" = v_season
      and d."damageType" in ('Battle', 'Bomb')
      and d."userId" is not null
      and (p_cluster_code is null or d.cluster_code = p_cluster_code)
  ),
  current_season_totals as (
    select
      b.player_id,
      count(*) filter (
        where b.damage_type = 'Battle'
      )::int as tokens_used,
      max(b.started_on) filter (where b.damage_type = 'Battle') as last_battle_time
    from battle_rows b
    group by b.player_id
  ),
  max_tokens as (
    select coalesce(max(c.tokens_used), 0)::int as max_possible
    from current_season_totals c
  ),
  calculated as (
    select
      m.player_id,
      calc.tokens_available as calc_tokens_available,
      calc.is_capped as calc_is_capped,
      calc.time_until_next_token as calc_time_until_next_token,
      calc.last_battle_time as calc_last_battle_time
    from members m
    left join lateral (
      -- WI-2570 follow-up 3: replay by player id, not display name, so
      -- renamed players' battles are not missed by the fallback.
      select *
      from public.calculate_player_tokens_by_user(m.player_id, p_guild_code, v_season)
      limit 1
    ) calc on true
  ),
  -- WI-3060: LIVE burn/over-cap via compute_player_token_burn (history + now()),
  -- the same source get_token_usage_for_guild uses, instead of the
  -- token_burn_state snapshot. Eliminates the ~30-min stale "Overcapped" split.
  burn_state as (
    select
      m.player_id,
      cb.burned_tokens,
      cb.time_over_cap_seconds
    from members m
    cross join lateral public.compute_player_token_burn(
      p_guild_code := p_guild_code,
      p_season := v_season,
      p_player_id := m.player_id
    ) cb
  ),
  -- Calculate bomb state from battle history (18h = 64800s cooldown)
  bomb_calc as (
    select
      b.player_id,
      max(b.started_on) as last_bomb_time,
      case
        when max(b.started_on) is not null
          and extract(epoch from (now() - max(b.started_on))) < 64800
        then 0
        else 1
      end as calc_bombs_available,
      case
        when max(b.started_on) is not null
          and extract(epoch from (now() - max(b.started_on))) < 64800
        then floor(64800 - extract(epoch from (now() - max(b.started_on))))::int
        else null
      end as calc_bomb_next_seconds
    from battle_rows b
    where b.damage_type = 'Bomb'
    group by b.player_id
  )
  select
    m.player_id,
    m.display_name,
    m.discord_user_id,
    case
      when live_source.token_spent then tok_spend_proj.spent_tokens
      when live_source.token_pure then tok_proj.proj_tokens
      else coalesce(c.calc_tokens_available, 3)
    end as tokens_available,
    case
      when live_source.token_spent then tok_spend_proj.spent_tokens >= 3
      when live_source.token_pure then tok_proj.proj_tokens >= 3
      else coalesce(c.calc_is_capped, coalesce(c.calc_tokens_available, 3) >= 3)
    end as is_capped,
    case
      when live_source.token_spent then
        case
          when tok_spend_proj.spent_next_seconds is null then null::interval
          else make_interval(secs => tok_spend_proj.spent_next_seconds)
        end
      when live_source.token_pure then
        case
          when tok_proj.proj_next_seconds is null then null::interval
          else make_interval(secs => tok_proj.proj_next_seconds)
        end
      else
        case
          when coalesce(c.calc_tokens_available, 3) >= 3 then null::interval
          else c.calc_time_until_next_token
        end
    end as time_to_next_token,
    -- WI-2640 Phase 3 (architect condition B1): data_source stays exactly
    -- 'live'/'calculated'. The projection path is visible ONLY through the
    -- additive post_snapshot_spends column below.
    case
      when live_source.token_live then 'live'::text
      else 'calculated'::text
    end as data_source,
    case
      when live_source.token_spent then tok_spend_proj.spent_next_seconds
      when live_source.token_pure then tok_proj.proj_next_seconds
      else floor(extract(epoch from c.calc_time_until_next_token))::int
    end as token_next_in_seconds,
    m.last_sync_at,
    coalesce(t.tokens_used, 0) as tokens_used,
    coalesce(mt.max_possible, 0) as max_possible,
    coalesce(bs.burned_tokens, 0) as burned_tokens,
    coalesce(bs.time_over_cap_seconds, 0) as time_over_cap_seconds,
    coalesce(t.last_battle_time, c.calc_last_battle_time) as last_battle_time,
    -- Bomb fields: prefer live API data (projected to now, and through
    -- post-snapshot Bomb spends when present), fall back to battle-history
    -- calculation.
    case
      when live_source.bomb_spent and bomb_spend_proj.spent_bombs is not null
        then bomb_spend_proj.spent_bombs
      when live_source.bomb_pure and bomb_proj.proj_bombs is not null
        then bomb_proj.proj_bombs
      else coalesce(bc.calc_bombs_available, 1)
    end as bombs_available,
    case
      when live_source.bomb_spent and bomb_spend_proj.spent_bombs is not null
        then bomb_spend_proj.spent_bomb_next
      when live_source.bomb_pure and bomb_proj.proj_bombs is not null
        then bomb_proj.proj_bomb_next
      else bc.calc_bomb_next_seconds
    end as bomb_next_in_seconds,
    -- WI-2640 Phase 3 (condition B1): additive audit column. Count of
    -- post-snapshot Battle rows for live rows (0 = pure snapshot projection);
    -- NULL for calculated rows.
    case
      when live_source.token_live then coalesce(rs.battles_after_sync, 0)
      else null::int
    end as post_snapshot_spends
  from members m
  left join calculated c
    on c.player_id = m.player_id
  left join current_season_totals t
    on t.player_id = m.player_id
  cross join max_tokens mt
  left join burn_state bs
    on bs.player_id = m.player_id
  left join bomb_calc bc
    on bc.player_id = m.player_id
  left join recent_spend rs
    on rs.player_id = m.player_id
  cross join lateral (
    select
      base_live.ok as base_live,
      -- WI-2640 Phase 3: a base-live member (valid key + snapshot present)
      -- STAYS live even with post-snapshot spends — the snapshot is projected
      -- through them instead of being invalidated. The 48h staleness guard
      -- was removed earlier (WI-2570 follow-up 3).
      base_live.ok as token_live,
      -- pure = no post-snapshot Battle spends: the original snapshot
      -- projection lateral below applies unchanged.
      (base_live.ok and coalesce(rs.battles_after_sync, 0) = 0) as token_pure,
      -- spent = walk the snapshot through the post-snapshot Battle rows.
      (base_live.ok and coalesce(rs.battles_after_sync, 0) > 0) as token_spent,
      -- bomb snapshot: same split, keyed on post-snapshot Bomb spends only.
      (base_live.ok and coalesce(rs.bombs_after_sync, 0) = 0) as bomb_pure,
      (base_live.ok and coalesce(rs.bombs_after_sync, 0) > 0) as bomb_spent
    from (
      select (
        m.tacticus_api_key_encrypted is not null
        and coalesce(m.api_key_is_valid, false)
        and m.last_sync_tokens is not null
        and m.last_sync_at is not null
      ) as ok
    ) base_live
  ) live_source
  -- WI-2570 projection: whole seconds since the snapshot was taken, plus the
  -- clamped snapshot itself. elapsed_secs is non-null only on the live branch.
  cross join lateral (
    select
      case
        when live_source.base_live
          then greatest(0::numeric, floor(extract(epoch from (now() - m.last_sync_at))))
        else null::numeric
      end as elapsed_secs,
      greatest(0, least(3, coalesce(m.last_sync_tokens, 3))) as synced_tokens
  ) sync_snap
  cross join lateral (
    select
      case
        when not live_source.token_pure then null::int
        -- capped at sync: regen is paused at 3/3, snapshot stays exact
        when sync_snap.synced_tokens >= 3 then 3
        -- below cap but no usable countdown: cannot project, keep snapshot
        when coalesce(m.next_token_seconds, 0) <= 0 then sync_snap.synced_tokens
        -- countdown not yet elapsed: no token popped since sync
        when sync_snap.elapsed_secs < m.next_token_seconds then sync_snap.synced_tokens
        -- one token at the synced countdown, then one per full 12h cycle
        else least(
          3,
          sync_snap.synced_tokens + 1 + floor(
            (sync_snap.elapsed_secs - m.next_token_seconds) / 43200.0
          )::int
        )
      end as proj_tokens,
      case
        when not live_source.token_pure then null::int
        when sync_snap.synced_tokens >= 3 then null::int
        when coalesce(m.next_token_seconds, 0) <= 0 then null::int
        -- countdown still running: decay it by the elapsed time
        when sync_snap.elapsed_secs < m.next_token_seconds
          then (m.next_token_seconds - sync_snap.elapsed_secs)::int
        -- countdown elapsed: remaining time in the in-progress 12h cycle
        else (43200 - ((sync_snap.elapsed_secs - m.next_token_seconds)::bigint % 43200))::int
      end as proj_next_raw
  ) tok_proj0
  cross join lateral (
    select
      tok_proj0.proj_tokens,
      -- once the projection reaches the cap, regen pauses: no countdown
      case
        when tok_proj0.proj_tokens is null then null::int
        when tok_proj0.proj_tokens >= 3 then null::int
        else tok_proj0.proj_next_raw
      end as proj_next_seconds
  ) tok_proj
  -- WI-2640 Phase 3: snapshot-through-spends projection (tokens). The helper
  -- is null-safe and always emits one row; a NULL p_count short-circuits it
  -- for rows that are not on the spent path.
  cross join lateral (
    select
      tsp.available as spent_tokens,
      tsp.next_in_seconds as spent_next_seconds
    from public.project_token_snapshot(
      case when live_source.token_spent then m.last_sync_tokens else null::int end,
      m.next_token_seconds,
      m.last_sync_at,
      coalesce(rs.battle_spends, array[]::timestamptz[]),
      now(),
      3,
      43200
    ) tsp
  ) tok_spend_proj
  cross join lateral (
    select
      case
        when not live_source.bomb_pure or m.next_bomb_seconds is null then null::int
        -- synced bomb cooldown elapsed: bomb is back
        when sync_snap.elapsed_secs >= m.next_bomb_seconds
          then greatest(1, coalesce(m.last_sync_bombs, 0))
        else greatest(0, coalesce(m.last_sync_bombs, 0))
      end as proj_bombs,
      case
        when not live_source.bomb_pure or m.next_bomb_seconds is null then null::int
        when sync_snap.elapsed_secs >= m.next_bomb_seconds then null::int
        else (m.next_bomb_seconds - sync_snap.elapsed_secs)::int
      end as proj_bomb_next
  ) bomb_proj
  -- WI-2640 Phase 3: snapshot-through-spends projection (bombs, cap 1,
  -- 18h = 64800s regen). NULL last_sync_bombs falls through to bomb_calc.
  cross join lateral (
    select
      bsp.available as spent_bombs,
      bsp.next_in_seconds as spent_bomb_next
    from public.project_token_snapshot(
      case when live_source.bomb_spent then m.last_sync_bombs else null::int end,
      m.next_bomb_seconds,
      m.last_sync_at,
      coalesce(rs.bomb_spends, array[]::timestamptz[]),
      now(),
      1,
      64800
    ) bsp
  ) bomb_spend_proj
  order by m.display_name;
end;
$_$;

ALTER FUNCTION public.get_player_token_state(p_guild_code text, p_season text, p_cluster_code text, p_player_id text) OWNER TO postgres;

CREATE FUNCTION public.get_player_token_summary(guild_code_param text, season_param text DEFAULT NULL::text) RETURNS TABLE(display_name text, total_tokens_used integer, max_tokens_allowed integer, bosses_assigned integer, token_allocations jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_season TEXT;
  default_max_tokens INTEGER := 5;
BEGIN
  -- Get current season if not provided
  IF season_param IS NULL THEN
    SELECT COALESCE(MAX("Season"), 'current') INTO current_season
    FROM "EOT_GR_data"
    WHERE "Guild" = guild_code_param;
  ELSE
    current_season := season_param;
  END IF;

  -- Get max tokens from guild config
  SELECT COALESCE(gc.primary_assignment_tokens, default_max_tokens) INTO default_max_tokens
  FROM guild_config gc
  WHERE gc.guild_code = guild_code_param;

  RETURN QUERY
  SELECT
    usa.display_name,
    usa.total_tokens_allocated,
    default_max_tokens as max_tokens_allowed,
    (SELECT COUNT(*) FROM jsonb_each_text(usa.token_allocations)
     WHERE CAST(value AS INTEGER) > 0)::INTEGER as bosses_assigned,
    usa.token_allocations
  FROM upcoming_season_assignments usa
  WHERE usa.guild_code = guild_code_param
    AND usa.season_number = current_season
    AND usa.uses_flexible_tokens = true
  ORDER BY usa.total_tokens_allocated DESC, usa.display_name;
END;
$$;

ALTER FUNCTION public.get_player_token_summary(guild_code_param text, season_param text) OWNER TO postgres;

CREATE FUNCTION public.get_prime_boss_hp() RETURNS TABLE(boss_name text, set_level integer, encounter_id integer, max_hp numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  SELECT
    "Name" as boss_name,
    "set" as set_level,
    "encounterId" as encounter_id,
    MAX("damageDealt" + "remainingHp") as max_hp  -- Calculate total HP from damage + remaining
  FROM "EOT_GR_data"
  WHERE "encounterId" IN (1, 2)  -- Prime bosses
    AND "rarity" IN ('Legendary', 'Mythic')
    AND "damageType" = 'Battle'
    AND "damageDealt" > 0
  GROUP BY "Name", "set", "encounterId"
  ORDER BY "set", "Name", "encounterId";
$$;

ALTER FUNCTION public.get_prime_boss_hp() OWNER TO postgres;

CREATE FUNCTION public.get_public_global_leaderboard(p_limit integer DEFAULT 10) RETURNS TABLE(rank bigint, display_name text, guild_display_name text, cluster_display_name text, battle_count bigint, total_damage numeric, avg_damage numeric, max_damage bigint, performance_score numeric, is_obfuscated boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH current_season AS (
    -- season_num, NOT max("Season"): the latter is text and lexicographic.
    SELECT max(e.season_num) AS season_num FROM public."EOT_GR_data" e
  ),
  visible AS (
    SELECT
      e."displayName"                                        AS display_name,
      gc.display_name                                        AS guild_display_name,
      COALESCE(c.display_name, 'Independent'::varchar)       AS cluster_display_name,
      count(*)                                               AS battle_count,
      sum(e."damageDealt")                                   AS total_damage,
      round(avg(e."damageDealt"), 0)                         AS avg_damage,
      max(e."damageDealt")                                   AS max_damage,
      COALESCE(gc.explore_privacy_mode, '["public"]'::jsonb) AS modes
    FROM public."EOT_GR_data" e
    CROSS JOIN current_season cs
    LEFT JOIN public.guild_config gc ON gc.guild_code = e."Guild"
    LEFT JOIN public.clusters c ON c.cluster_code::text = e.cluster_code::text
    WHERE e.season_num = cs.season_num
      AND e."damageDealt" > 0
      AND NOT (COALESCE(gc.explore_privacy_mode, '["public"]'::jsonb) ? 'hide_all')
    GROUP BY e."displayName", e."Guild", e.cluster_code,
             gc.display_name, c.display_name, gc.explore_privacy_mode
  ),
  scored AS (
    SELECT v.*,
      round(
          v.total_damage  / NULLIF(max(v.total_damage)  OVER (), 0::numeric) * 60::numeric
        + v.avg_damage    / NULLIF(max(v.avg_damage)    OVER (), 0::numeric) * 30::numeric
        + v.battle_count::numeric
                          / NULLIF(max(v.battle_count)  OVER (), 0)::numeric * 10::numeric
      , 1) AS performance_score
    FROM visible v
  ),
  masked AS (
    SELECT
      CASE WHEN v.modes ? 'hide_players' THEN 'Anonymous Warrior' ELSE v.display_name END AS display_name,
      v.guild_display_name,
      v.cluster_display_name::text AS cluster_display_name,
      v.battle_count,
      CASE WHEN v.modes ? 'obfuscate_values'
           THEN GREATEST(round(v.total_damage / 25000) * 25000, 0) ELSE v.total_damage END AS total_damage,
      CASE WHEN v.modes ? 'obfuscate_values'
           THEN GREATEST(round(v.avg_damage / 25000) * 25000, 0) ELSE v.avg_damage END AS avg_damage,
      CASE WHEN v.modes ? 'obfuscate_values'
           THEN GREATEST((round(v.max_damage::numeric / 25000) * 25000)::bigint, 0) ELSE v.max_damage END AS max_damage,
      v.performance_score,
      (v.modes ? 'obfuscate_values') AS is_obfuscated,
      v.total_damage AS sort_key
    FROM scored v
  )
  SELECT
    row_number() OVER (ORDER BY m.sort_key DESC) AS rank,
    m.display_name, m.guild_display_name, m.cluster_display_name,
    m.battle_count, m.total_damage, m.avg_damage, m.max_damage,
    m.performance_score, m.is_obfuscated
  FROM masked m
  ORDER BY m.sort_key DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 10), 1), 25);
$$;

ALTER FUNCTION public.get_public_global_leaderboard(p_limit integer) OWNER TO postgres;

CREATE FUNCTION public.get_public_stats() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT s
       FROM public.mv_public_stats
      WHERE cached_at > now() - interval '6 hours'
      LIMIT 1),
    public.get_public_stats_live()
  );
$$;

ALTER FUNCTION public.get_public_stats() OWNER TO postgres;

CREATE FUNCTION public.get_public_stats_cached() RETURNS TABLE(active_players bigint, battles_tracked bigint, guilds bigint, total_damage bigint, cached_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Try to get from cache table first (if it exists)
  BEGIN
    RETURN QUERY
    SELECT
      hc.active_players,
      hc.battles_tracked,
      hc.guilds,
      hc.total_damage,
      hc.updated_at as cached_at
    FROM homepage_cache hc
    WHERE hc.updated_at > NOW() - INTERVAL '1 hour'
    ORDER BY hc.updated_at DESC
    LIMIT 1;

    -- If we got results, return them
    IF FOUND THEN
      RETURN;
    END IF;
  EXCEPTION
    WHEN undefined_table THEN
      -- Cache table doesn't exist, continue to live calculation
      NULL;
  END;

  -- Fall back to live calculation using fixed method
  RETURN QUERY
  SELECT * FROM get_public_stats();
END;
$$;

ALTER FUNCTION public.get_public_stats_cached() OWNER TO postgres;

CREATE FUNCTION public.get_public_stats_live() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
    stats jsonb;
BEGIN
    SELECT jsonb_build_object(
        'active_players', (
            SELECT COUNT(DISTINCT "displayName")
            FROM "EOT_GR_data"
            WHERE "displayName" IS NOT NULL
        ),
        'battles_tracked', (
            SELECT COUNT(*)
            FROM "EOT_GR_data"
        ),
        'guild_count', (
            SELECT COUNT(DISTINCT "Guild")
            FROM "EOT_GR_data"
            WHERE "Guild" IS NOT NULL
              AND "Guild" NOT IN ('EOT', 'TEST')
        ),
        'total_damage', (
            SELECT COALESCE(SUM("damageDealt"::bigint), 0)
            FROM "EOT_GR_data"
        ),
        'current_season', (
            -- season_num is the integer mirror of the text "Season"
            -- column; MAX("Season") would sort lexicographically and
            -- return "99" once seasons go 3 digits.
            SELECT MAX(season_num)::text
            FROM "EOT_GR_data"
        )
    ) INTO stats;

    RETURN stats;
END;
$$;

ALTER FUNCTION public.get_public_stats_live() OWNER TO postgres;

CREATE FUNCTION public.get_public_stats_v2() RETURNS TABLE(active_players bigint, battles_tracked bigint, guilds bigint, total_damage bigint)
    LANGUAGE plpgsql
    AS $_$
BEGIN
  RETURN QUERY
  WITH recent_seasons AS (
    SELECT DISTINCT "Season"
    FROM "EOT_GR_data"
    WHERE "Season" ~ '^\d+$'
    ORDER BY "Season"::INTEGER DESC
    LIMIT 5
  ),
  stats AS (
    SELECT
      COUNT(DISTINCT e."userId") FILTER (WHERE e."userId" IS NOT NULL) as unique_players,
      COUNT(*) as total_battles,
      COUNT(DISTINCT e."Guild") as unique_guilds,
      SUM(e."damageDealt") as total_damage_dealt
    FROM "EOT_GR_data" e
    JOIN recent_seasons rs ON e."Season" = rs."Season"
    WHERE e."damageDealt" > 0
  )
  SELECT
    s.unique_players as active_players,
    s.total_battles as battles_tracked,
    s.unique_guilds as guilds,
    s.total_damage_dealt as total_damage
  FROM stats s;
END;
$_$;

ALTER FUNCTION public.get_public_stats_v2() OWNER TO postgres;

CREATE FUNCTION public.get_queue_stats() RETURNS TABLE(status text, count bigint, oldest_pending timestamp with time zone, avg_wait_time_seconds numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    q.status,
    COUNT(*)::BIGINT,
    MIN(CASE WHEN q.status = 'pending' THEN q.created_at END) as oldest_pending,
    AVG(CASE
      WHEN q.status = 'processing' THEN EXTRACT(EPOCH FROM (NOW() - q.started_at))
      WHEN q.status = 'completed' THEN EXTRACT(EPOCH FROM (q.completed_at - q.started_at))
      ELSE NULL
    END)::NUMERIC as avg_wait_time_seconds
  FROM sync_queue q
  WHERE q.created_at > NOW() - INTERVAL '24 hours'
  GROUP BY q.status;
END;
$$;

ALTER FUNCTION public.get_queue_stats() OWNER TO postgres;

