CREATE FUNCTION public.get_rarity_set(p_rarity text, p_set integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_rarity = 'Legendary' THEN 'L' || (COALESCE(p_set, 0) + 1)::text
    WHEN p_rarity = 'Mythic' THEN 'M' || (COALESCE(p_set, 0) + 1)::text
    ELSE NULL
  END;
$$;

ALTER FUNCTION public.get_rarity_set(p_rarity text, p_set integer) OWNER TO postgres;

CREATE FUNCTION public.get_recommended_teams_for_season(p_season text, p_guild_filter text DEFAULT NULL::text, p_cluster_code text DEFAULT NULL::text) RETURNS TABLE(rarity text, set integer, level_string text, team_composition text[], usage_count bigint, avg_damage numeric, success_rate numeric, category text)
    LANGUAGE plpgsql
    AS $_$
BEGIN
  RETURN QUERY
  WITH team_stats AS (
    SELECT
      e.rarity,
      e.set,
      CASE
        WHEN e.rarity = 'Mythic' THEN 'M' || (e.set + 1)::text
        WHEN e.rarity = 'Legendary' THEN 'L' || (e.set + 1)::text
        ELSE e.rarity || (e.set + 1)::text
      END as level_str,
      -- Extract team composition from heroDetails
      ARRAY(
        SELECT DISTINCT jsonb_array_elements_text(
          CASE
            WHEN e."heroDetails"::jsonb IS NOT NULL
            THEN jsonb_path_query_array(e."heroDetails"::jsonb, '$[*].unitId')
            ELSE '[]'::jsonb
          END
        )
      ) as team_comp,
      COUNT(*) as use_count,
      AVG(e."damageDealt") as avg_dmg,
      SUM(CASE WHEN e."damageDealt" > 0 THEN 1 ELSE 0 END)::numeric / COUNT(*)::numeric as success_rt
    FROM "EOT_GR_data" e
    WHERE e."Season" = p_season
      AND (p_cluster_code IS NULL OR e.cluster_code = p_cluster_code)
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
      AND (p_guild_filter IS NULL OR e."Guild" = p_guild_filter)
    GROUP BY e.rarity, e.set, team_comp
    HAVING COUNT(*) >= 3  -- Minimum usage threshold
  ),
  categorized AS (
    SELECT
      ts.*,
      COALESCE(
        (SELECT bc.single_category
         FROM batch_categorize_teams(ARRAY[ts.team_comp]) bc
         LIMIT 1),
        'Mixed'
      ) as team_category
    FROM team_stats ts
  )
  SELECT
    c.rarity,
    c.set,
    c.level_str,
    c.team_comp,
    c.use_count,
    ROUND(c.avg_dmg, 0),
    ROUND(c.success_rt * 100, 1),
    c.team_category
  FROM categorized c
  WHERE c.use_count >= 3
  ORDER BY c.rarity DESC, c.set DESC, c.use_count DESC
  LIMIT 50;
END;
$_$;

ALTER FUNCTION public.get_recommended_teams_for_season(p_season text, p_guild_filter text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_season_token_stats(p_guild_code text, p_season integer, p_include_cluster boolean DEFAULT false) RETURNS TABLE(context text, guild_code text, cluster_code text, season integer, tokens_possible bigint, tokens_spent bigint, tokens_remaining bigint, tokens_per_player_cap integer, ratio_spent numeric, updated_at timestamp with time zone, players jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_cluster_code TEXT;
  v_default_cap INTEGER := 28; -- fallback when nobody spent tokens this season
  v_now TIMESTAMPTZ := timezone('UTC', now());
  v_is_service BOOLEAN := COALESCE(
    NULLIF(
      NULLIF(current_setting('role', true), ''),
      'none'
    ),
    NULLIF(session_user, '')
  ) = 'service_role';
BEGIN
  IF NOT v_is_service
    AND NOT COALESCE(
      p_guild_code IN (
        SELECT public._pm_caller_guild_codes()
      )
      OR p_guild_code IN (
        SELECT public._pm_caller_cluster_guild_codes()
      )
      OR public._pm_caller_is_app_admin(),
      FALSE
    )
  THEN
    RETURN;
  END IF;

  IF p_guild_code IS NULL OR length(trim(p_guild_code)) = 0 THEN
    RAISE EXCEPTION 'p_guild_code is required';
  END IF;

  IF p_season IS NULL THEN
    RAISE EXCEPTION 'p_season is required';
  END IF;

  -- Determine cluster code for the guild (fall back to encounter data if config missing)
  SELECT gc.cluster_code
  INTO v_cluster_code
  FROM public.guild_config gc
  WHERE gc.guild_code = p_guild_code
  LIMIT 1;

  IF v_cluster_code IS NULL THEN
    SELECT d.cluster_code
    INTO v_cluster_code
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season::text
      AND d.cluster_code IS NOT NULL
    LIMIT 1;
  END IF;

  -- Guild-level payload
  RETURN QUERY
  WITH guild_candidates AS (
    SELECT DISTINCT
      NULLIF(trim(pm.player_id), '') AS player_id,
      trim(pm.display_name) AS display_name
    FROM public.player_with_cluster pm
    WHERE pm.guild_code = p_guild_code
    UNION
    SELECT DISTINCT
      NULLIF(trim(d."userId"), '') AS player_id,
      COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown') AS display_name
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season::text
      AND d."damageType" = 'Battle'
      AND d."damageDealt" > 0
  ),
  guild_tokens AS (
    SELECT
      NULLIF(trim(d."userId"), '') AS player_id,
      LOWER(COALESCE(NULLIF(trim(d."displayName"), ''), '')) AS name_key,
      COUNT(*)::BIGINT AS tokens_spent
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season::text
      AND d."damageType" = 'Battle'
      AND d."damageDealt" > 0
    GROUP BY NULLIF(trim(d."userId"), ''), LOWER(COALESCE(NULLIF(trim(d."displayName"), ''), ''))
  ),
  guild_players AS (
    SELECT
      gc.player_id,
      COALESCE(gc.display_name, 'Unknown') AS display_name,
      LOWER(COALESCE(gc.display_name, '')) AS name_key
    FROM guild_candidates gc
  ),
  guild_player_tokens AS (
    SELECT
      gp.player_id,
      gp.display_name,
      COALESCE(gt.tokens_spent, 0) AS tokens_spent,
      COALESCE(gt.tokens_spent, 0) AS tokens_spent_raw
    FROM guild_players gp
    LEFT JOIN guild_tokens gt
      ON (
        gp.player_id IS NOT NULL
        AND gt.player_id = gp.player_id
      )
      OR (
        gp.player_id IS NULL
        AND gt.player_id IS NULL
        AND gp.name_key = gt.name_key
      )
  ),
  guild_caps AS (
    SELECT
      COALESCE(NULLIF(MAX(gpt.tokens_spent), 0), v_default_cap)::NUMERIC AS max_tokens
    FROM guild_player_tokens gpt
  ),
  guild_player_adjusted AS (
    SELECT
      gpt.player_id,
      gpt.display_name,
      gpt.tokens_spent,
      gc.max_tokens::INTEGER AS tokens_possible_per_player,
      CASE
        WHEN gc.max_tokens > 0
          THEN LEAST(gpt.tokens_spent::NUMERIC / gc.max_tokens, 1)
        ELSE 0
      END AS ratio_spent
    FROM guild_player_tokens gpt
    CROSS JOIN guild_caps gc
  ),
  guild_totals AS (
    SELECT
      COALESCE(SUM(gpa.tokens_possible_per_player), 0)::BIGINT AS tokens_possible,
      COALESCE(SUM(gpa.tokens_spent), 0)::BIGINT AS tokens_spent,
      COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'player_id', gpa.player_id,
            'display_name', gpa.display_name,
            'tokens_possible', gpa.tokens_possible_per_player,
            'tokens_spent', gpa.tokens_spent,
            'ratio_spent', LEAST(gpa.ratio_spent, 1)
          )
          ORDER BY gpa.tokens_spent DESC, gpa.display_name
        ),
        '[]'::jsonb
      ) AS players
    FROM guild_player_adjusted gpa
    CROSS JOIN guild_caps gc
  )
  SELECT
    'guild'::TEXT AS context,
    p_guild_code AS guild_code,
    v_cluster_code,
    p_season,
    gt.tokens_possible,
    gt.tokens_spent,
    GREATEST(gt.tokens_possible - gt.tokens_spent, 0)::BIGINT AS tokens_remaining,
    (SELECT max_tokens::INTEGER FROM guild_caps) AS tokens_per_player_cap,
    CASE
      WHEN gt.tokens_possible > 0
        THEN LEAST(gt.tokens_spent::NUMERIC / gt.tokens_possible::NUMERIC, 1)
      ELSE 0
    END AS ratio_spent,
    v_now AS updated_at,
    gt.players
  FROM guild_totals gt;

  -- Cluster-level payload when requested
  IF COALESCE(p_include_cluster, FALSE) AND v_cluster_code IS NOT NULL THEN
    RETURN QUERY
    WITH cluster_candidates AS (
      SELECT DISTINCT
        NULLIF(trim(pm.player_id), '') AS player_id,
        trim(pm.display_name) AS display_name
      FROM public.player_with_cluster pm
      WHERE pm.cluster_code = v_cluster_code
      UNION
      SELECT DISTINCT
        NULLIF(trim(d."userId"), '') AS player_id,
        COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown') AS display_name
      FROM public."EOT_GR_data" d
      WHERE d.cluster_code = v_cluster_code
        AND d."Season" = p_season::text
        AND d."damageType" = 'Battle'
        AND d."damageDealt" > 0
    ),
    cluster_tokens AS (
      SELECT
        NULLIF(trim(d."userId"), '') AS player_id,
        LOWER(COALESCE(NULLIF(trim(d."displayName"), ''), '')) AS name_key,
        COUNT(*)::BIGINT AS tokens_spent
      FROM public."EOT_GR_data" d
      WHERE d.cluster_code = v_cluster_code
        AND d."Season" = p_season::text
        AND d."damageType" = 'Battle'
        AND d."damageDealt" > 0
      GROUP BY NULLIF(trim(d."userId"), ''), LOWER(COALESCE(NULLIF(trim(d."displayName"), ''), ''))
    ),
    cluster_players AS (
      SELECT
        cc.player_id,
        COALESCE(cc.display_name, 'Unknown') AS display_name,
        LOWER(COALESCE(cc.display_name, '')) AS name_key
      FROM cluster_candidates cc
    ),
    cluster_player_tokens AS (
      SELECT
        cp.player_id,
        cp.display_name,
        COALESCE(ct.tokens_spent, 0) AS tokens_spent,
        COALESCE(ct.tokens_spent, 0) AS tokens_spent_raw
      FROM cluster_players cp
      LEFT JOIN cluster_tokens ct
        ON (
          cp.player_id IS NOT NULL
          AND ct.player_id = cp.player_id
        )
        OR (
          cp.player_id IS NULL
          AND ct.player_id IS NULL
          AND cp.name_key = ct.name_key
        )
    ),
    cluster_caps AS (
      SELECT
        COALESCE(NULLIF(MAX(cpt.tokens_spent), 0), v_default_cap)::NUMERIC AS max_tokens
      FROM cluster_player_tokens cpt
    ),
    cluster_player_adjusted AS (
      SELECT
        cpt.player_id,
        cpt.display_name,
        cpt.tokens_spent,
        cc.max_tokens::INTEGER AS tokens_possible_per_player,
        CASE
          WHEN cc.max_tokens > 0
            THEN LEAST(cpt.tokens_spent::NUMERIC / cc.max_tokens, 1)
          ELSE 0
        END AS ratio_spent
      FROM cluster_player_tokens cpt
      CROSS JOIN cluster_caps cc
    ),
    cluster_totals AS (
      SELECT
        COALESCE(SUM(cpa.tokens_possible_per_player), 0)::BIGINT AS tokens_possible,
        COALESCE(SUM(cpa.tokens_spent), 0)::BIGINT AS tokens_spent,
        COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'player_id', cpa.player_id,
              'display_name', cpa.display_name,
              'tokens_possible', cpa.tokens_possible_per_player,
              'tokens_spent', cpa.tokens_spent,
              'ratio_spent', LEAST(cpa.ratio_spent, 1)
            )
            ORDER BY cpa.tokens_spent DESC, cpa.display_name
          ),
          '[]'::jsonb
        ) AS players
      FROM cluster_player_adjusted cpa
      CROSS JOIN cluster_caps cc
    )
    SELECT
      'cluster'::TEXT AS context,
      p_guild_code AS guild_code,
      v_cluster_code,
      p_season,
      ct.tokens_possible,
      ct.tokens_spent,
      GREATEST(ct.tokens_possible - ct.tokens_spent, 0)::BIGINT AS tokens_remaining,
      (SELECT max_tokens::INTEGER FROM cluster_caps) AS tokens_per_player_cap,
      CASE
        WHEN ct.tokens_possible > 0
          THEN LEAST(ct.tokens_spent::NUMERIC / ct.tokens_possible::NUMERIC, 1)
        ELSE 0
      END AS ratio_spent,
      v_now AS updated_at,
      ct.players
    FROM cluster_totals ct;
  END IF;
END;
$$;

ALTER FUNCTION public.get_season_token_stats(p_guild_code text, p_season integer, p_include_cluster boolean) OWNER TO postgres;

CREATE FUNCTION public.get_season_token_stats_batch(p_guild_code text, p_seasons text[]) RETURNS TABLE(season text, user_id text, display_name text, tokens_spent integer, tokens_possible integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH caller_authorization AS MATERIALIZED (
    SELECT
      COALESCE(
        NULLIF(
          NULLIF(current_setting('role', true), ''),
          'none'
        ),
        NULLIF(session_user, '')
      ) = 'service_role'
      OR (
        p_guild_code IS NOT NULL
        AND (
          p_guild_code IN (
            SELECT public._pm_caller_guild_codes()
          )
          OR p_guild_code IN (
            SELECT public._pm_caller_cluster_guild_codes()
          )
          OR public._pm_caller_is_app_admin()
        )
      ) AS allowed
  ),
  spent AS (
    SELECT
      e."Season"::text AS season,
      NULLIF(trim(e."userId"), '') AS user_id,
      COALESCE(MAX(NULLIF(trim(e."displayName"), '')), 'Unknown') AS display_name,
      COUNT(*)::integer AS tokens_spent
    FROM public."EOT_GR_data" e
    WHERE e."Guild" = p_guild_code
      AND e."Season" = ANY(p_seasons)
      AND e."damageType" = 'Battle'
      AND e."damageDealt" > 0
      AND NULLIF(trim(e."userId"), '') IS NOT NULL
    GROUP BY e."Season", NULLIF(trim(e."userId"), '')
  ),
  caps AS (
    SELECT
      season,
      COALESCE(NULLIF(MAX(tokens_spent), 0), 28)::integer AS tokens_possible
    FROM spent
    GROUP BY season
  )
  SELECT
    s.season,
    s.user_id,
    s.display_name,
    s.tokens_spent,
    c.tokens_possible
  FROM spent s
  JOIN caps c USING (season)
  CROSS JOIN caller_authorization AS caller_scope
  WHERE caller_scope.allowed;
$$;

ALTER FUNCTION public.get_season_token_stats_batch(p_guild_code text, p_seasons text[]) OWNER TO postgres;

CREATE FUNCTION public.get_seasonal_meta_atlas_top_teams(p_boss_types text[], p_rarity_sets text[], p_main_min_attacks integer DEFAULT 20, p_prime_min_attacks integer DEFAULT 10) RETURNS TABLE(boss_type text, encounter_index integer, rarity_set text, team_hash text, team_composition text, meta_team text, damage_p90 numeric, damage_p75 numeric, damage_avg numeric, attack_count bigint, season text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT ON (m.boss_type, m.rarity_set, COALESCE(m.encounter_index, 0))
    m.boss_type,
    COALESCE(m.encounter_index, 0) AS encounter_index,
    m.rarity_set,
    m.team_hash,
    m.team_composition,
    m.meta_team,
    m.damage_p90,
    m.damage_p75,
    m.damage_avg,
    m.attack_count,
    m.season
  FROM public.meta_atlas_data m
  WHERE m.boss_type = ANY (p_boss_types)
    AND m.rarity_set = ANY (p_rarity_sets)
    AND m.meta_team IS NOT NULL
    AND COALESCE(m.encounter_index, 0) BETWEEN 0 AND 2
    AND m.attack_count >= CASE
      WHEN COALESCE(m.encounter_index, 0) = 0 THEN p_main_min_attacks
      ELSE p_prime_min_attacks
    END
  ORDER BY
    m.boss_type,
    m.rarity_set,
    COALESCE(m.encounter_index, 0),
    m.damage_p90 DESC NULLS LAST,
    m.attack_count DESC;
$$;

ALTER FUNCTION public.get_seasonal_meta_atlas_top_teams(p_boss_types text[], p_rarity_sets text[], p_main_min_attacks integer, p_prime_min_attacks integer) OWNER TO postgres;

CREATE FUNCTION public.get_seasons_for_guild(p_guild text) RETURNS TABLE(season text, record_count bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    "Season" as season,
    COUNT(*) as record_count
  FROM "EOT_GR_data"
  WHERE "Guild" = p_guild
  GROUP BY "Season"
  ORDER BY "Season" DESC;
$$;

