CREATE FUNCTION public.get_stage_kill_duration_medians(p_guild_code text, p_current_season integer, p_window_days integer DEFAULT 60) RETURNS TABLE(stage_code text, loop_index bigint, median_seconds double precision, sample_count integer, source text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH attempts AS (
    SELECT
      d."Season"::int AS season,
      CASE
        WHEN lower(d.rarity) LIKE 'mythic%' THEN 'M' || (d.set + 1)::text
        ELSE 'L' || (d.set + 1)::text
      END AS stage_code,
      d."loopIndex" AS loop_index,
      d."startedOn" AS started_on
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."damageType" = 'Battle'
      AND d.set IS NOT NULL
      AND d.rarity IS NOT NULL
      AND d."startedOn" IS NOT NULL
      AND d."loopIndex" IS NOT NULL
      AND (
        d."Season"::int = p_current_season
        OR (
          d."Season"::int < p_current_season
          AND d."startedOn" >= NOW() - (p_window_days || ' days')::INTERVAL
        )
      )
  ),
  per_occurrence AS (
    SELECT
      season,
      stage_code,
      loop_index,
      EXTRACT(EPOCH FROM (MAX(started_on) - MIN(started_on)))::DOUBLE PRECISION AS span_seconds,
      MAX(started_on) AS occurrence_last_attack,
      COUNT(*) AS attempts
    FROM attempts
    GROUP BY season, stage_code, loop_index
    HAVING COUNT(*) >= 3
       AND MAX(started_on) > MIN(started_on)
  ),
  season_last_attack AS (
    SELECT season, MAX(started_on) AS last_attack
    FROM attempts
    GROUP BY season
  ),
  -- Current-season occurrences: only include those where the season has
  -- moved past them (later attacks exist on other stages). The latest
  -- in-progress stage is excluded.
  completed_current AS (
    SELECT po.*
    FROM per_occurrence po
    JOIN season_last_attack sla ON sla.season = po.season
    WHERE po.season = p_current_season
      AND po.occurrence_last_attack < sla.last_attack
  ),
  past AS (
    SELECT * FROM per_occurrence WHERE season < p_current_season
  ),
  current_medians AS (
    SELECT
      stage_code,
      loop_index,
      percentile_cont(0.5) WITHIN GROUP (ORDER BY span_seconds) AS median_seconds,
      COUNT(*)::int AS sample_count,
      'current_season'::text AS source
    FROM completed_current
    GROUP BY stage_code, loop_index
  ),
  rolling_medians AS (
    SELECT
      stage_code,
      loop_index,
      percentile_cont(0.5) WITHIN GROUP (ORDER BY span_seconds) AS median_seconds,
      COUNT(*)::int AS sample_count,
      'rolling_window'::text AS source
    FROM past
    GROUP BY stage_code, loop_index
  )
  SELECT * FROM current_medians
  UNION ALL
  SELECT * FROM rolling_medians;
$$;

ALTER FUNCTION public.get_stage_kill_duration_medians(p_guild_code text, p_current_season integer, p_window_days integer) OWNER TO postgres;

CREATE FUNCTION public.get_stale_players(p_guild_code text, p_inactivity_days integer DEFAULT 3) RETURNS TABLE(player_name text, last_activity_date date, last_activity_at timestamp with time zone, days_inactive integer, wars_since_active bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH player_last_activity AS (
    SELECT
      gwa.player_name,
      MAX(gwa.attempt_start_time::DATE) as last_activity_date,
      MAX(gwa.attempt_start_time) as last_activity_at
    FROM guild_war_player_attempts gwa
    WHERE gwa.guild_code = p_guild_code
      AND gwa.is_guild_member = TRUE
    GROUP BY gwa.player_name
  ),
  wars_since AS (
    SELECT
      pla.player_name,
      COUNT(DISTINCT gwm.war_id) as wars_since_active
    FROM player_last_activity pla
    LEFT JOIN guild_war_matches gwm ON gwm.guild_code = p_guild_code
      AND gwm.war_status = 'completed'
      AND gwm.war_end_date > pla.last_activity_at
    GROUP BY pla.player_name
  )
  SELECT
    pla.player_name::TEXT,
    pla.last_activity_date,
    pla.last_activity_at,
    (CURRENT_DATE - pla.last_activity_date)::INT as days_inactive,
    COALESCE(ws.wars_since_active, 0)::BIGINT
  FROM player_last_activity pla
  LEFT JOIN wars_since ws ON ws.player_name = pla.player_name
  WHERE (CURRENT_DATE - pla.last_activity_date) >= p_inactivity_days
  ORDER BY pla.last_activity_date ASC;
END;
$$;

ALTER FUNCTION public.get_stale_players(p_guild_code text, p_inactivity_days integer) OWNER TO postgres;

CREATE FUNCTION public.get_sub_boss_name(p_boss_type text, p_encounter_idx integer) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(bm.boss_name, p_boss_type)
  FROM (SELECT 1) dummy
  LEFT JOIN boss_mapping bm
    ON bm.boss_type = p_boss_type
    AND bm.encounter_index = p_encounter_idx;
$$;

