CREATE FUNCTION public.get_team_display(hero_details text, mow_details text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  hero_names text[];
  mow_name text;
  result text;
BEGIN
  -- Return NULL for invalid/empty hero details
  IF hero_details IS NULL OR hero_details = '' OR hero_details = '[]' THEN
    RETURN NULL;
  END IF;

  BEGIN
    -- Get display names for heroes, sorted alphabetically
    SELECT array_agg(COALESCE(hm.display_name, heroes.unit_id) ORDER BY COALESCE(hm.display_name, heroes.unit_id))
    INTO hero_names
    FROM (
      SELECT jsonb_array_elements(hero_details::jsonb) ->> 'unitId' as unit_id
    ) heroes
    LEFT JOIN hero_mappings hm ON hm.unit_id = heroes.unit_id
    WHERE heroes.unit_id IS NOT NULL;

    -- Return NULL if no valid heroes found
    IF hero_names IS NULL OR array_length(hero_names, 1) = 0 THEN
      RETURN NULL;
    END IF;

    result := array_to_string(hero_names, ', ');

    -- Add MoW if present
    IF mow_details IS NOT NULL AND mow_details != '' AND mow_details != 'null' THEN
      SELECT COALESCE(hm.display_name, mow_details::jsonb ->> 'unitId')
      INTO mow_name
      FROM (SELECT mow_details::jsonb ->> 'unitId' as unit_id) mow
      LEFT JOIN hero_mappings hm ON hm.unit_id = mow.unit_id;

      IF mow_name IS NOT NULL THEN
        result := result || ' + ' || mow_name;
      END IF;
    END IF;

    RETURN result;
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
END;
$$;

ALTER FUNCTION public.get_team_display(hero_details text, mow_details text) OWNER TO postgres;

CREATE FUNCTION public.get_team_hero_power(p_hero_details text) RETURNS bigint
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT COALESCE(SUM((elem->>'power')::bigint), 0)
  FROM jsonb_array_elements(p_hero_details::jsonb) elem;
$$;

ALTER FUNCTION public.get_team_hero_power(p_hero_details text) OWNER TO postgres;

CREATE FUNCTION public.get_token_allocation_settings(p_guild_code text) RETURNS TABLE(primary_tokens integer, secondary_tokens integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(gc.primary_assignment_tokens, 3) as primary_tokens,
    COALESCE(gc.secondary_assignment_tokens, 2) as secondary_tokens
  FROM guild_config gc
  WHERE gc.guild_code = p_guild_code
  LIMIT 1;

  -- If no config exists, return defaults
  IF NOT FOUND THEN
    RETURN QUERY SELECT 3, 2;
  END IF;
END;
$$;

ALTER FUNCTION public.get_token_allocation_settings(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_token_burn_state(p_guild_code text, p_season text, p_player_id text, p_display_name text) RETURNS TABLE(player_id text, display_name text, burned_tokens integer, time_over_cap_seconds integer, last_over_cap_started_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql
    AS $$
select
  player_id,
  display_name,
  burned_tokens,
  time_over_cap_seconds,
  last_over_cap_started_at,
  updated_at
from public.token_burn_state
where guild_code = p_guild_code
  and season = p_season
  and (
    (p_player_id is not null and player_id = p_player_id)
    or (p_player_id is null and display_name = p_display_name)
  )
limit 1;
$$;

ALTER FUNCTION public.get_token_burn_state(p_guild_code text, p_season text, p_player_id text, p_display_name text) OWNER TO postgres;

CREATE FUNCTION public.get_token_usage_by_loop(p_guild_code text, p_season text, p_rarities text[] DEFAULT ARRAY['Legendary'::text, 'Mythic'::text]) RETURNS TABLE(loop_index integer, bosses integer, primes integer, rarities text[])
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH battle_data AS (
    SELECT
      d."loopIndex",
      d."encounterId",
      d.rarity
    FROM "EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND d.rarity = ANY(p_rarities)
  ),
  loop_aggregates AS (
    SELECT
      bd."loopIndex"::INTEGER AS loop_idx,
      COUNT(*) FILTER (WHERE bd."encounterId" = 0)::INTEGER AS boss_count,
      COUNT(*) FILTER (WHERE bd."encounterId" != 0)::INTEGER AS prime_count,
      ARRAY_AGG(DISTINCT bd.rarity) AS rarity_list
    FROM battle_data bd
    WHERE bd."loopIndex" IS NOT NULL
    GROUP BY bd."loopIndex"
  )
  SELECT
    la.loop_idx,
    la.boss_count,
    la.prime_count,
    la.rarity_list
  FROM loop_aggregates la
  ORDER BY la.loop_idx;
END;
$$;

ALTER FUNCTION public.get_token_usage_by_loop(p_guild_code text, p_season text, p_rarities text[]) OWNER TO postgres;

CREATE FUNCTION public.get_token_usage_by_loop_and_set(p_guild_code text, p_season text, p_rarities text[] DEFAULT ARRAY['Legendary'::text, 'Mythic'::text]) RETURNS TABLE(loop_index integer, set_key text, token_count integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_count integer := 0;
  v_guild text;
  v_admin boolean := false;
  v_role text;
  v_caller_cluster uuid;
  v_target_cluster uuid;
BEGIN
  IF COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, '')) = 'service_role' THEN
    NULL;
  ELSE
    IF v_uid IS NULL THEN RETURN; END IF;
    SELECT count(*)::integer, max(NULLIF(trim(pm.guild_code), '')),
           max(lower(trim(pm.role::text))), bool_or(pm.is_app_admin IS TRUE)
    INTO v_count, v_guild, v_role, v_admin
    FROM public.player_mapping pm
    WHERE pm.user_id = v_uid AND pm.is_current IS TRUE;
    IF v_count <> 1 OR v_guild IS NULL OR v_role NOT IN ('member','officer','leader') THEN RETURN; END IF;
    IF v_admin OR p_guild_code = v_guild THEN
      NULL;
    ELSE
      SELECT cluster_id INTO v_caller_cluster FROM public.guild_config WHERE guild_code = v_guild LIMIT 1;
      SELECT cluster_id INTO v_target_cluster FROM public.guild_config WHERE guild_code = p_guild_code LIMIT 1;
      IF v_caller_cluster IS NULL OR v_target_cluster IS NULL OR v_caller_cluster <> v_target_cluster THEN RETURN; END IF;
    END IF;
  END IF;
  RETURN QUERY
  SELECT d."loopIndex"::integer,
         CASE WHEN d.rarity = 'Mythic' THEN 'M' || (coalesce(d.set, 0) + 1)::text
              ELSE 'L' || (coalesce(d.set, 0) + 1)::text END,
         count(*)::integer
  FROM public."EOT_GR_data" d
  WHERE d."Guild" = p_guild_code AND d."Season" = p_season
    AND d."damageType" = 'Battle' AND d.rarity = ANY(p_rarities)
    AND d."loopIndex" IS NOT NULL
  GROUP BY d."loopIndex", CASE WHEN d.rarity = 'Mythic' THEN 'M' || (coalesce(d.set, 0) + 1)::text
                                ELSE 'L' || (coalesce(d.set, 0) + 1)::text END
  ORDER BY d."loopIndex", set_key;
END;
$$;

ALTER FUNCTION public.get_token_usage_by_loop_and_set(p_guild_code text, p_season text, p_rarities text[]) OWNER TO postgres;

CREATE FUNCTION public.get_token_usage_for_guild(p_guild_code text, p_season text) RETURNS TABLE(player_id text, display_name text, tokens_used integer, max_possible integer, tokens_below_offender boolean, tokens_below_abuser boolean, boss_tokens integer, prime_tokens integer, bombs_used integer, bombs_available integer, burned_tokens integer, time_over_cap_seconds integer, tokens_available integer, token_next_in_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_max_possible_hard_cap integer := 28;
  v_regen_seconds numeric := 43200;
  v_is_service boolean := COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, '')) = 'service_role';
  v_uid uuid;
  v_mapping_count integer := 0;
  v_caller_guild text;
  v_caller_role text;
  v_is_admin boolean := false;
  v_caller_cluster uuid;
  v_target_cluster uuid;
  v_allowed boolean := false;
BEGIN
  IF NOT v_is_service THEN
    v_uid := auth.uid();
    IF v_uid IS NULL THEN
      RETURN;
    END IF;

    SELECT count(*)::integer,
           max(NULLIF(trim(pm.guild_code), '')),
           max(lower(trim(pm.role::text))),
           bool_or(pm.is_app_admin IS TRUE)
    INTO v_mapping_count, v_caller_guild, v_caller_role, v_is_admin
    FROM public.player_mapping pm
    WHERE pm.user_id = v_uid
      AND pm.is_current IS TRUE;

    IF v_mapping_count <> 1
      OR v_caller_guild IS NULL
      OR v_caller_role IS NULL
      OR v_caller_role NOT IN ('member', 'officer', 'leader')
    THEN
      RETURN;
    END IF;

    IF p_guild_code IS NULL OR trim(p_guild_code) = '' THEN
      RETURN;
    END IF;

    IF v_is_admin THEN
      v_allowed := true;
    ELSIF p_guild_code = v_caller_guild THEN
      v_allowed := true;
    ELSE
      SELECT gc.cluster_id INTO v_caller_cluster
      FROM public.guild_config gc
      WHERE gc.guild_code = v_caller_guild
      LIMIT 1;
      SELECT gc.cluster_id INTO v_target_cluster
      FROM public.guild_config gc
      WHERE gc.guild_code = p_guild_code
      LIMIT 1;
      v_allowed := v_caller_cluster IS NOT NULL
        AND v_target_cluster IS NOT NULL
        AND v_caller_cluster = v_target_cluster;
    END IF;

    IF NOT v_allowed THEN
      RETURN;
    END IF;
  END IF;

  IF p_guild_code IS NULL OR p_season IS NULL THEN
    RAISE EXCEPTION 'guild and season are required';
  END IF;

  RETURN QUERY
  WITH cfg AS (
    SELECT coalesce(gc.token_offender_threshold, 4) AS offender_threshold,
           coalesce(gc.token_abuser_threshold, 5) AS abuser_threshold
    FROM public.guild_config gc
    WHERE gc.guild_code = p_guild_code
    LIMIT 1
  ),
  battles AS (
    SELECT e."userId" AS user_id, e."displayName" AS display_name,
           coalesce(e."encounterId", 0) AS encounter_id
    FROM public."EOT_GR_data" e
    WHERE e."Guild" = p_guild_code AND e."Season" = p_season
      AND e."damageType" = 'Battle' AND e."displayName" IS NOT NULL
      AND e."userId" IS NOT NULL AND e."damageDealt" > 0
  ),
  bombs AS (
    SELECT e."userId" AS user_id, count(*) AS bombs_used
    FROM public."EOT_GR_data" e
    WHERE e."Guild" = p_guild_code AND e."Season" = p_season
      AND e."damageType" = 'Bomb' AND e."displayName" IS NOT NULL
      AND e."userId" IS NOT NULL
    GROUP BY e."userId"
  ),
  tokens_per_player AS (
    SELECT b.user_id AS tp_user_id, b.display_name AS tp_display_name,
           count(*) AS tp_tokens_used,
           count(*) FILTER (WHERE b.encounter_id = 0) AS tp_boss_tokens,
           count(*) FILTER (WHERE b.encounter_id <> 0) AS tp_prime_tokens
    FROM battles b
    GROUP BY b.user_id, b.display_name
  ),
  avail_per_player AS (
    SELECT t.tp_user_id AS ap_user_id,
           coalesce(av.tokens_available, 0) AS ap_tokens_available,
           av.token_next_in_seconds AS ap_token_next_in_seconds
    FROM tokens_per_player t
    CROSS JOIN LATERAL public.compute_player_tokens_available(
      p_guild_code := p_guild_code, p_season := p_season,
      p_player_id := t.tp_user_id
    ) av
  ),
  burn_per_player AS (
    SELECT t.tp_user_id AS bp_user_id,
           coalesce(cb.time_over_cap_seconds, 0)::int AS bp_time_over_cap_seconds
    FROM tokens_per_player t
    CROSS JOIN LATERAL public.compute_player_token_burn(
      p_guild_code := p_guild_code, p_season := p_season,
      p_player_id := t.tp_user_id
    ) cb
  ),
  max_tokens_cte AS (
    SELECT least(v_max_possible_hard_cap,
                 coalesce(max(t.tp_tokens_used + a.ap_tokens_available), 0))::integer AS mt_max_tokens
    FROM tokens_per_player t
    JOIN avail_per_player a ON a.ap_user_id = t.tp_user_id
  )
  SELECT t.tp_user_id::text, t.tp_display_name::text,
         t.tp_tokens_used::int,
         (SELECT mt_max_tokens FROM max_tokens_cte)::int,
         ((SELECT mt_max_tokens FROM max_tokens_cte) - t.tp_tokens_used) >= (SELECT offender_threshold FROM cfg),
         ((SELECT mt_max_tokens FROM max_tokens_cte) - t.tp_tokens_used) >= (SELECT abuser_threshold FROM cfg),
         t.tp_boss_tokens::int, t.tp_prime_tokens::int,
         coalesce(b.bombs_used, 0)::int, 0::int,
         greatest(0, floor((SELECT mt_max_tokens FROM max_tokens_cte)
           - t.tp_tokens_used - least(3, greatest(0, a.ap_tokens_available))
           - CASE WHEN least(3, greatest(0, a.ap_tokens_available)) >= 3 THEN 0
                  WHEN coalesce(a.ap_token_next_in_seconds, 0) <= 0 THEN 0
                  ELSE (v_regen_seconds - least(a.ap_token_next_in_seconds, v_regen_seconds)) / v_regen_seconds END))::int,
         coalesce(bp.bp_time_over_cap_seconds, 0)::int,
         a.ap_tokens_available::int, a.ap_token_next_in_seconds::int
  FROM tokens_per_player t
  LEFT JOIN bombs b ON b.user_id = t.tp_user_id
  LEFT JOIN avail_per_player a ON a.ap_user_id = t.tp_user_id
  LEFT JOIN burn_per_player bp ON bp.bp_user_id = t.tp_user_id;
END;
$$;

ALTER FUNCTION public.get_token_usage_for_guild(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.get_unmapped_players(p_guild_code text) RETURNS TABLE(player_id text, display_name text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT DISTINCT
    e."User" as player_id,
    e."displayName" as display_name
  FROM "EOT_GR_data" e
  WHERE e."Guild" = p_guild_code
    AND NOT EXISTS (
      SELECT 1 FROM player_mapping pm
      WHERE pm.player_id = e."User"
        AND pm.guild_code = p_guild_code
        AND pm.is_current = true
    )
  ORDER BY e."displayName";
END;
$$;

ALTER FUNCTION public.get_unmapped_players(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_user_access_levels(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_mapping_count integer;
  v_guild text;
  v_cluster text;
  v_guild_role text;
  v_is_app_admin boolean;
  v_is_alpha boolean;
  v_is_beta_tester boolean;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  IF v_role = 'authenticated'
    AND (
      auth.uid() IS NULL
      OR p_user_id IS NULL
      OR p_user_id IS DISTINCT FROM auth.uid()
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT
    count(pm.id)::integer,
    max(pm.guild_code),
    max(pm.cluster_code),
    max(pm.role::text),
    coalesce(max(pm.is_app_admin::integer), 0) = 1
  INTO
    v_mapping_count,
    v_guild,
    v_cluster,
    v_guild_role,
    v_is_app_admin
  FROM public.player_mapping AS pm
  WHERE pm.user_id = p_user_id
    AND pm.is_current IS TRUE;

  SELECT
    count(fag.user_id) FILTER (
      WHERE fag.access_level = 'alpha_tester'
        AND (fag.expires_at IS NULL OR fag.expires_at > now())
    ) > 0,
    count(fag.user_id) FILTER (
      WHERE fag.access_level = 'beta_tester'
        AND (fag.expires_at IS NULL OR fag.expires_at > now())
    ) > 0
  INTO v_is_alpha, v_is_beta_tester
  FROM public.feature_access_grants AS fag
  WHERE fag.user_id = p_user_id;

  RETURN jsonb_build_object(
    'is_app_admin', coalesce(v_is_app_admin, false),
    'is_admin', coalesce(v_is_app_admin OR v_guild_role = 'admin', false),
    'is_alpha_tester', coalesce(v_is_alpha, false),
    'is_beta_tester', coalesce(v_is_beta_tester, false),
    'has_premium', false,
    'cluster_code', v_cluster,
    'guild_code', v_guild,
    'max_access_level',
      CASE
        WHEN v_is_app_admin OR v_is_alpha THEN 'alpha'
        WHEN v_is_beta_tester THEN 'beta'
        ELSE 'public'
      END
  );
END;
$$;

ALTER FUNCTION public.get_user_access_levels(p_user_id uuid) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.get_user_accessible_guilds() RETURNS TABLE(guild_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  user_cluster_code text;
  user_guild_code text;
  user_role text;
BEGIN
  -- Get user's guild, cluster, and role
  SELECT
    pm.guild_code,
    gc.cluster_code,
    pm.role
  INTO
    user_guild_code,
    user_cluster_code,
    user_role
  FROM player_mapping pm
  LEFT JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = auth.uid()
    AND pm.is_current = true
  LIMIT 1;

  -- If no guild found, return empty
  IF user_guild_code IS NULL THEN
    RETURN;
  END IF;

  -- Leaders can see all guilds
  IF user_role = 'leader' THEN
    RETURN QUERY
    SELECT gc.guild_code
    FROM guild_config gc
    WHERE gc.enabled = true;
    RETURN;
  END IF;

  -- If user has a cluster, return all guilds in that cluster
  IF user_cluster_code IS NOT NULL AND user_cluster_code != 'INDEPENDENT' THEN
    RETURN QUERY
    SELECT gc.guild_code
    FROM guild_config gc
    WHERE gc.cluster_code = user_cluster_code
      AND gc.enabled = true;
  ELSE
    -- Otherwise, return only user's guild
    RETURN QUERY
    SELECT user_guild_code;
  END IF;
END;
$$;

ALTER FUNCTION public.get_user_accessible_guilds() OWNER TO postgres;

CREATE FUNCTION public.get_user_auth_context(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_profile RECORD;
  v_member_type TEXT;
BEGIN
  IF COALESCE((SELECT auth.jwt() ->> 'role'), '') = 'service_role' THEN
    v_uid := p_user_id;
  ELSE
    v_uid := (SELECT auth.uid());
  END IF;

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('authenticated', false, 'has_profile', false);
  END IF;

  SELECT
    pm.player_id, pm.display_name, pm.guild_code, pm.role, pm.username,
    gc.cluster_code, gc.display_name AS guild_display_name
  INTO v_profile
  FROM player_mapping pm
  LEFT JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = v_uid
    AND pm.is_current = true
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('authenticated', true, 'has_profile', false);
  END IF;

  IF v_profile.cluster_code IS NOT NULL THEN
    v_member_type := 'cluster';
  ELSIF v_profile.role = 'leader' AND v_profile.cluster_code IS NULL THEN
    v_member_type := 'prospective_leader';
  ELSE
    v_member_type := 'member';
  END IF;

  RETURN jsonb_build_object(
    'authenticated', true,
    'has_profile', true,
    'member_type', v_member_type,
    'cluster_code', v_profile.cluster_code,
    'guild_code', v_profile.guild_code,
    'role', v_profile.role,
    'player_id', v_profile.player_id,
    'display_name', v_profile.display_name,
    'username', v_profile.username,
    'guild_display_name', v_profile.guild_display_name
  );
END;
$$;

ALTER FUNCTION public.get_user_auth_context(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.get_user_cluster_code(p_user_id uuid DEFAULT auth.uid()) RETURNS character varying
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_cluster_code VARCHAR;
BEGIN
  SELECT gc.cluster_code INTO v_cluster_code
  FROM player_mapping pm
  JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = COALESCE(p_user_id, auth.uid())
  AND pm.is_current = true
  LIMIT 1;

  -- Return NULL if no cluster found - NO FALLBACK TO EOT
  RETURN v_cluster_code;
END;
$$;

ALTER FUNCTION public.get_user_cluster_code(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.get_user_cluster_context(p_user_id uuid) RETURNS TABLE(user_id uuid, guild_code text, cluster_code character varying, cluster_id uuid, cluster_name text, role public.app_role, is_leader boolean, is_officer boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pm.user_id,
    pm.guild_code,
    c.cluster_code,
    gc.cluster_id,
    -- clusters.display_name is character varying(100); the declared result
    -- column is text. RETURN QUERY demands exact base-type identity, so this
    -- cast is load-bearing -- without it the function raises 42804 on EVERY
    -- call, including zero-row ones. Do not "simplify" it away.
    c.display_name::text AS cluster_name,
    pm.role,
    pm.role = 'leader' AS is_leader,
    pm.role IN ('leader', 'officer') AS is_officer
  FROM player_mapping pm
  LEFT JOIN guild_config gc ON pm.guild_code = gc.guild_code
  LEFT JOIN clusters c ON gc.cluster_id = c.id
  WHERE pm.user_id = p_user_id
    AND pm.is_current = true
  LIMIT 1;
END;
$$;

ALTER FUNCTION public.get_user_cluster_context(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.get_user_data_for_export(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    result JSONB;
    user_data JSONB;
    player_data JSONB;
    battle_data JSONB;
    processing_data JSONB;
    alert_prefs_data JSONB;
    alert_state_data JSONB;
    caller_uid UUID;
BEGIN
    caller_uid := auth.uid();

    -- Allow service_role to pass through (scheduler / admin flows).
    -- Otherwise the caller's auth.uid() must match the requested user.
    IF caller_uid IS NULL AND current_setting('role', true) <> 'service_role' THEN
        RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
    END IF;

    IF caller_uid IS NOT NULL AND caller_uid <> p_user_id THEN
        RAISE EXCEPTION 'Forbidden: can only export your own data'
            USING ERRCODE = '42501';
    END IF;

    -- Get user profile data
    SELECT to_jsonb(auth.users.*) INTO user_data
    FROM auth.users
    WHERE id = p_user_id;

    -- Get player mapping data
    SELECT jsonb_agg(to_jsonb(pm.*)) INTO player_data
    FROM player_mapping pm
    WHERE pm.user_id = p_user_id;

    -- Get battle data (limited to last 1000 records)
    SELECT jsonb_agg(battle_subset.*)
    INTO battle_data
    FROM (
        SELECT gr.*
        FROM "EOT_GR_data" gr
        JOIN player_mapping pm ON gr."displayName" = pm.display_name
        WHERE pm.user_id = p_user_id
        ORDER BY COALESCE(gr."completedOn", gr."timestamp") DESC
        LIMIT 1000
    ) battle_subset;

    -- Get processing history (most recent 100).
    -- ORDER BY + LIMIT MUST live inside the subquery: you cannot ORDER BY a
    -- non-grouped column alongside a bare aggregate (jsonb_agg) at the same
    -- level — that raises "column ... must appear in the GROUP BY clause".
    -- Mirrors the battle_data subquery pattern above.
    SELECT jsonb_agg(processing_subset.*)
    INTO processing_data
    FROM (
        SELECT gpl.*
        FROM gdpr_processing_log gpl
        WHERE gpl.user_id = p_user_id
        ORDER BY gpl.timestamp DESC
        LIMIT 100
    ) processing_subset;

    -- Token alert preferences + delivery state (WI-3990)
    SELECT to_jsonb(utap.*) INTO alert_prefs_data
    FROM user_token_alert_prefs utap
    WHERE utap.user_id = p_user_id;

    SELECT to_jsonb(utas.*) INTO alert_state_data
    FROM user_token_alert_state utas
    WHERE utas.user_id = p_user_id;

    result := jsonb_build_object(
        'export_generated_at', NOW(),
        'user_id', p_user_id,
        'data', jsonb_build_object(
            'profile', COALESCE(user_data, '{}'),
            'player_mappings', COALESCE(player_data, '[]'),
            'battle_data', COALESCE(battle_data, '[]'),
            'processing_history', COALESCE(processing_data, '[]'),
            'token_alert_preferences', COALESCE(alert_prefs_data, '{}'),
            'token_alert_state', COALESCE(alert_state_data, '{}')
        ),
        'data_summary', jsonb_build_object(
            'total_battles', COALESCE(jsonb_array_length(battle_data), 0),
            'total_players', COALESCE(jsonb_array_length(player_data), 0),
            'data_retention_info', 'Battle data: indefinite, Processing logs: 7 years'
        )
    );

    RETURN result;
END;
$$;

ALTER FUNCTION public.get_user_data_for_export(p_user_id uuid) OWNER TO postgres;

