CREATE FUNCTION public.get_user_profile(p_user_id uuid) RETURNS TABLE(player_id text, username text, display_name text, guild_code text, user_id uuid, role text, is_current boolean, joined_at timestamp with time zone, updated_at timestamp with time zone, officer_notes text, discord_username text, timezone text, tacticus_share_url text, theme_preference text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pm.player_id,
    pm.username,
    pm.display_name,
    pm.guild_code,
    pm.user_id,
    pm.role,
    pm.is_current,
    pm.joined_at,
    pm.updated_at,
    pm.officer_notes,
    pm.discord_username,
    pm.timezone,
    pm.tacticus_share_url,
    pm.theme_preference
  FROM player_mapping pm
  WHERE pm.user_id = p_user_id
    AND pm.is_current = true
  LIMIT 1;
END;
$$;

ALTER FUNCTION public.get_user_profile(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.get_user_support_unread_count(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  DECLARE
    total_unread INTEGER;
  BEGIN
    SELECT COALESCE(SUM(user_unread_count), 0)
    INTO total_unread
    FROM support_tickets
    WHERE user_id = p_user_id
      AND status IN ('open', 'in_progress')
      AND user_unread_count > 0;

    RETURN total_unread;
  END;
  $$;

ALTER FUNCTION public.get_user_support_unread_count(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.get_users_needing_guild_update() RETURNS TABLE(user_id uuid, player_id text, display_name text, current_guild_code text, is_current boolean, last_battle_guild text, needs_update boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    WITH latest_battles AS (
        SELECT DISTINCT ON (d."userId")
            d."userId" as player_id,
            d."Guild" as guild_code,
            d."completedOn" as last_battle
        FROM "EOT_GR_data" d
        WHERE d."completedOn" > NOW() - INTERVAL '30 days'
        ORDER BY d."userId", d."completedOn" DESC
    )
    SELECT
        pm.user_id,
        pm.player_id,
        pm.display_name,
        pm.guild_code as current_guild_code,
        pm.is_current,
        lb.guild_code as last_battle_guild,
        (pm.guild_code != lb.guild_code) as needs_update
    FROM player_mapping pm
    JOIN latest_battles lb ON pm.player_id = lb.player_id
    WHERE pm.user_id IS NOT NULL
    AND pm.guild_code != lb.guild_code;
END;
$$;

ALTER FUNCTION public.get_users_needing_guild_update() OWNER TO postgres;

CREATE FUNCTION public.get_veteran_counts_by_guild(p_guild_codes text[], p_season_count integer DEFAULT 5) RETURNS TABLE(guild_code text, veteran_count integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
  WITH distinct_seasons_per_guild AS (
    SELECT DISTINCT
      "Guild" AS guild_code,
      "Season" AS season,
      ("Season")::int AS season_int
    FROM "EOT_GR_data"
    WHERE "Guild" = ANY(p_guild_codes)
      AND "Season" IS NOT NULL
      AND "Season" ~ '^\d+$'
  ),
  ranked AS (
    SELECT
      guild_code,
      season,
      row_number() OVER (PARTITION BY guild_code ORDER BY season_int DESC) AS rn
    FROM distinct_seasons_per_guild
  ),
  last_seasons_per_guild AS (
    SELECT guild_code, season
    FROM ranked
    WHERE rn <= greatest(coalesce(p_season_count, 5), 1)
  ),
  season_counts AS (
    SELECT guild_code, count(*)::int AS season_n
    FROM last_seasons_per_guild
    GROUP BY guild_code
  ),
  per_player_seasons AS (
    SELECT
      d."Guild" AS guild_code,
      coalesce(d."displayName", 'Unknown') AS display_name,
      count(DISTINCT d."Season") AS distinct_season_count
    FROM "EOT_GR_data" d
    JOIN last_seasons_per_guild ls
      ON ls.guild_code = d."Guild" AND ls.season = d."Season"
    WHERE d."Guild" = ANY(p_guild_codes)
    GROUP BY d."Guild", coalesce(d."displayName", 'Unknown')
  ),
  veterans AS (
    SELECT p.guild_code, count(*)::int AS veteran_count
    FROM per_player_seasons p
    JOIN season_counts sc ON sc.guild_code = p.guild_code
    WHERE sc.season_n = coalesce(p_season_count, 5)
      AND p.distinct_season_count = sc.season_n
    GROUP BY p.guild_code
  )
  SELECT
    gc::text AS guild_code,
    coalesce(v.veteran_count, 0)::integer AS veteran_count
  FROM unnest(p_guild_codes) AS gc
  LEFT JOIN veterans v ON v.guild_code = gc;
$_$;

ALTER FUNCTION public.get_veteran_counts_by_guild(p_guild_codes text[], p_season_count integer) OWNER TO postgres;

CREATE FUNCTION public.get_veteran_players_stats(p_guild_code text) RETURNS TABLE(player_id text, player_name text, seasons_played bigint, total_battles bigint, total_damage bigint, avg_damage_per_season numeric, first_season text, latest_season text)
    LANGUAGE plpgsql
    AS $_$
BEGIN
  RETURN QUERY
  WITH player_history AS (
    SELECT
      e."userId" as player_id,
      pm.display_name as current_player_name,
      COUNT(DISTINCT e."Season") as seasons_played,
      COUNT(*) as total_battles,
      SUM(e."damageDealt") as total_damage,
      MIN(e."Season"::INTEGER) as first_season_num,
      MAX(e."Season"::INTEGER) as latest_season_num
    FROM "EOT_GR_data" e
    LEFT JOIN player_mapping pm ON e."userId" = pm.player_id AND pm.is_current = true
    WHERE e."Guild" = p_guild_code
      AND e."damageDealt" > 0
      AND e."Season" ~ '^\d+$'
      AND e."userId" IS NOT NULL
    GROUP BY e."userId", pm.display_name
    HAVING COUNT(DISTINCT e."Season") >= 5
  )
  SELECT
    ph.player_id::TEXT,
    COALESCE(ph.current_player_name, 'Unknown Player')::TEXT as player_name,
    ph.seasons_played,
    ph.total_battles,
    ph.total_damage,
    ROUND((ph.total_damage::NUMERIC / ph.seasons_played), 0) as avg_damage_per_season,
    ph.first_season_num::TEXT as first_season,
    ph.latest_season_num::TEXT as latest_season
  FROM player_history ph
  ORDER BY ph.seasons_played DESC, ph.total_damage DESC;
END;
$_$;

ALTER FUNCTION public.get_veteran_players_stats(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_votlw_most_improved_player(p_guild_code text, p_season text, p_cluster_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_prev_season TEXT;
  v_result JSONB := jsonb_build_object('player', NULL, 'improvementPct', 0);
BEGIN
  IF p_guild_code IS NULL OR length(trim(p_guild_code)) = 0 THEN
    RAISE EXCEPTION 'p_guild_code is required';
  END IF;

  IF p_season IS NULL OR length(trim(p_season)) = 0 THEN
    RAISE EXCEPTION 'p_season is required';
  END IF;

  BEGIN
    v_prev_season := ( (trim(p_season))::integer - 1 )::text;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN v_result;
  END;

  WITH current_season AS (
    SELECT
      COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown') AS display_name,
      AVG(d."damageDealt") AS avg_damage,
      COUNT(*) AS tokens
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND d."damageDealt" IS NOT NULL
      AND d."damageDealt" > 0
      -- WI-2520: sweep-free average (one-shots kept) so sweep-heavy seasons
      -- can't manufacture fake improvement.
      AND NOT (
        COALESCE(d."remainingHp", 0) = 0
        AND COALESCE(d."maxHp", 0) > 0
        AND d."damageDealt" < d."maxHp"
      )
      AND (p_cluster_code IS NULL OR d.cluster_code = p_cluster_code)
    GROUP BY COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown')
  ),
  previous_season AS (
    SELECT
      COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown') AS display_name,
      AVG(d."damageDealt") AS avg_damage,
      COUNT(*) AS tokens
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = v_prev_season
      AND d."damageType" = 'Battle'
      AND d."damageDealt" IS NOT NULL
      AND d."damageDealt" > 0
      -- WI-2520: sweep-free average (one-shots kept) so sweep-heavy seasons
      -- can't manufacture fake improvement.
      AND NOT (
        COALESCE(d."remainingHp", 0) = 0
        AND COALESCE(d."maxHp", 0) > 0
        AND d."damageDealt" < d."maxHp"
      )
      AND (p_cluster_code IS NULL OR d.cluster_code = p_cluster_code)
    GROUP BY COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown')
  ),
  joined AS (
    SELECT
      curr.display_name,
      curr.avg_damage AS curr_avg,
      prev.avg_damage AS prev_avg,
      curr.tokens AS curr_tokens,
      prev.tokens AS prev_tokens
    FROM current_season curr
    JOIN previous_season prev
      ON curr.display_name = prev.display_name
    WHERE curr.tokens > 1
      AND prev.tokens > 1
      AND prev.avg_damage > 0
  ),
  ranked AS (
    SELECT
      display_name,
      ((curr_avg - prev_avg) / prev_avg) * 100 AS improvement_pct,
      ROW_NUMBER() OVER (
        ORDER BY ((curr_avg - prev_avg) / prev_avg) * 100 DESC,
                 curr_avg DESC
      ) AS rank_num
    FROM joined
  )
  SELECT
    jsonb_build_object(
      'player', display_name,
      'improvementPct', ROUND(improvement_pct::numeric, 2)
    )
  INTO v_result
  FROM ranked
  WHERE rank_num = 1;

  RETURN COALESCE(v_result, jsonb_build_object('player', NULL, 'improvementPct', 0));
END;
$$;

ALTER FUNCTION public.get_votlw_most_improved_player(p_guild_code text, p_season text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_votlw_season_awards_data(p_guild_code text, p_season text, p_cluster_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_last_hits JSONB := '[]'::jsonb;
  v_bomb_data JSONB := '[]'::jsonb;
  v_all_battles JSONB := '[]'::jsonb;
BEGIN
  IF p_guild_code IS NULL OR length(trim(p_guild_code)) = 0 THEN
    RAISE EXCEPTION 'p_guild_code is required';
  END IF;

  IF p_season IS NULL OR length(trim(p_season)) = 0 THEN
    RAISE EXCEPTION 'p_season is required';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(src)), '[]'::jsonb)
  INTO v_last_hits
  FROM (
    SELECT
      d."Guild" AS guild_code,
      d."Season" AS season,
      d.cluster_code,
      d.cluster_id,
      COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown') AS display_name,
      d."userId" AS user_id,
      d."Name" AS boss_name,
      d.rarity,
      d.tier,
      d.set,
      d."encounterId" AS encounter_id,
      d."encounterIndex" AS encounter_index,
      d."loopIndex" AS loop_index,
      d."damageDealt" AS damage_dealt,
      d."remainingHp" AS remaining_hp,
      d."maxHp" AS max_hp,
      d."startedOn" AS started_on,
      d."completedOn" AS completed_on
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND COALESCE(d."remainingHp", 0) = 0
      AND (p_cluster_code IS NULL OR d.cluster_code = p_cluster_code)
  ) src;

  SELECT COALESCE(jsonb_agg(to_jsonb(src)), '[]'::jsonb)
  INTO v_bomb_data
  FROM (
    SELECT
      d."Guild" AS guild_code,
      d."Season" AS season,
      d.cluster_code,
      d.cluster_id,
      COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown') AS display_name,
      d."userId" AS user_id,
      d."Name" AS boss_name,
      d.rarity,
      d.tier,
      d.set,
      d."encounterId" AS encounter_id,
      d."damageDealt" AS damage_dealt,
      d."startedOn" AS started_on,
      d."completedOn" AS completed_on
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageType" = 'Bomb'
      AND (p_cluster_code IS NULL OR d.cluster_code = p_cluster_code)
  ) src;

  SELECT COALESCE(jsonb_agg(to_jsonb(src)), '[]'::jsonb)
  INTO v_all_battles
  FROM (
    SELECT
      d.id,
      d."Guild" AS guild_code,
      d."Season" AS season,
      d.cluster_code,
      d.cluster_id,
      COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown') AS display_name,
      d."userId" AS user_id,
      d."Name" AS boss_name,
      d.rarity,
      d.tier,
      d.set,
      d."encounterId" AS encounter_id,
      d."encounterIndex" AS encounter_index,
      d."loopIndex" AS loop_index,
      d."damageType" AS damage_type,
      d."damageDealt" AS damage_dealt,
      d."remainingHp" AS remaining_hp,
      d."maxHp" AS max_hp,
      d."startedOn" AS started_on,
      d."completedOn" AS completed_on,
      d."timestamp" AS ingested_at
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND d."damageDealt" IS NOT NULL
      AND (p_cluster_code IS NULL OR d.cluster_code = p_cluster_code)
  ) src;

  RETURN jsonb_build_object(
    'last_hits', v_last_hits,
    'bomb_data', v_bomb_data,
    'all_battles', v_all_battles
  );
END;
$$;

ALTER FUNCTION public.get_votlw_season_awards_data(p_guild_code text, p_season text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_votlw_set_winners(p_guild_code text, p_season text, p_cluster_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_results JSONB := '[]'::jsonb;
BEGIN
  IF p_guild_code IS NULL OR length(trim(p_guild_code)) = 0 THEN
    RAISE EXCEPTION 'p_guild_code is required';
  END IF;

  IF p_season IS NULL OR length(trim(p_season)) = 0 THEN
    RAISE EXCEPTION 'p_season is required';
  END IF;

  WITH filtered_all AS (
    SELECT
      d."Guild" AS guild_code,
      d."Season" AS season,
      d.cluster_code,
      COALESCE(NULLIF(trim(d."displayName"), ''), 'Unknown') AS display_name,
      d."Name" AS boss_name,
      d.rarity,
      d.tier,
      d."set" AS set_num,
      d."encounterId" AS encounter_id,
      d."encounterIndex" AS encounter_index,
      d."loopIndex" AS loop_index,
      d."damageDealt" AS damage_dealt,
      d."remainingHp" AS remaining_hp,
      d."maxHp" AS max_hp,
      d."startedOn" AS started_on,
      d."completedOn" AS completed_on,
      CASE
        WHEN COALESCE(d."remainingHp", 0) = 0
          AND COALESCE(d."maxHp", 0) > 0
          AND COALESCE(d."damageDealt", 0) < d."maxHp"
          THEN TRUE
        ELSE FALSE
      END AS is_sweep,
      CASE
        WHEN COALESCE(d."remainingHp", 0) = 0
          AND COALESCE(d."maxHp", 0) > 0
          AND COALESCE(d."damageDealt", 0) >= d."maxHp"
          THEN TRUE
        ELSE FALSE
      END AS is_one_shot
    FROM public."EOT_GR_data" d
    WHERE d."Guild" = p_guild_code
      AND d."Season" = p_season
      AND d."damageType" = 'Battle'
      AND d."damageDealt" IS NOT NULL
      AND d."damageDealt" > 0
      AND d.rarity IN ('Legendary', 'Mythic')
      AND (p_cluster_code IS NULL OR d.cluster_code = p_cluster_code)
  ),
  -- WI-6590: where this season's loop restarts, taken from what was played.
  -- The lowest (rarity, set) seen at loopIndex >= 1 is the first boss the raid
  -- replays; everything below it is single-pass. Zero rows (guild never
  -- reached loop 1) leaves every set eligible.
  loop_start AS (
    SELECT rarity_rank, set_num
    FROM (
      SELECT
        CASE rarity WHEN 'Legendary' THEN 4 WHEN 'Mythic' THEN 5 ELSE 99 END AS rarity_rank,
        COALESCE(set_num, 0) AS set_num
      FROM filtered_all
      WHERE COALESCE(loop_index, 0) >= 1
    ) s
    ORDER BY rarity_rank, set_num
    LIMIT 1
  ),
  -- Single-pass bosses carry no awards, so they are dropped here rather than at
  -- the end: every downstream CTE (baselines, medals, side bosses, biggest hit,
  -- boss identity) then sees only award-bearing sets, and the RPC emits no row
  -- for the excluded ones.
  filtered AS (
    SELECT f.*
    FROM filtered_all f
    LEFT JOIN loop_start ls ON TRUE
    WHERE ls.rarity_rank IS NULL
       OR (
            CASE f.rarity WHEN 'Legendary' THEN 4 WHEN 'Mythic' THEN 5 ELSE 99 END,
            COALESCE(f.set_num, 0)
          ) >= (ls.rarity_rank, ls.set_num)
  ),
  -- Sweep-free guild baseline averages per boss (main boss only)
  guild_baseline AS (
    SELECT
      rarity,
      set_num,
      AVG(damage_dealt) AS avg_damage
    FROM filtered
    WHERE (encounter_id = 0 OR encounter_id IS NULL)
      AND (NOT is_sweep OR is_one_shot)
    GROUP BY rarity, set_num
  ),
  -- Sweep-free guild baseline averages per side boss
  side_boss_baseline AS (
    SELECT
      rarity,
      set_num,
      encounter_index,
      AVG(damage_dealt) AS avg_damage
    FROM filtered
    WHERE encounter_index IN (1, 2)
      AND (NOT is_sweep OR is_one_shot)
    GROUP BY rarity, set_num, encounter_index
  ),
  -- Main boss stats per player (encounter_id = 0 ONLY)
  base_stats AS (
    SELECT
      rarity,
      set_num,
      display_name,
      SUM(damage_dealt) FILTER (WHERE NOT is_sweep OR is_one_shot) AS non_sweep_damage,
      COUNT(*) FILTER (WHERE NOT is_sweep OR is_one_shot) AS meaningful_tokens,
      SUM(damage_dealt) AS total_damage,
      COUNT(*) AS token_count,
      MIN(started_on) AS first_token_time,
      array_agg(damage_dealt::numeric) FILTER (WHERE is_sweep AND NOT is_one_shot) AS sweep_damages
    FROM filtered
    WHERE encounter_id = 0 OR encounter_id IS NULL
    GROUP BY rarity, set_num, display_name
  ),
  -- Apply qualifying sweep exception to main boss averages
  adjusted_stats AS (
    SELECT
      bs.*,
      COALESCE(bs.non_sweep_damage, 0)
        + COALESCE(qualifying_sweep_sum(bs.sweep_damages, GREATEST(bs.non_sweep_damage / NULLIF(bs.meaningful_tokens, 0), gb.avg_damage)::numeric), 0) AS adj_damage,
      COALESCE(bs.meaningful_tokens, 0)
        + COALESCE(qualifying_sweep_count(bs.sweep_damages, GREATEST(bs.non_sweep_damage / NULLIF(bs.meaningful_tokens, 0), gb.avg_damage)::numeric), 0) AS adj_count,
      CASE
        WHEN (COALESCE(bs.meaningful_tokens, 0)
              + COALESCE(qualifying_sweep_count(bs.sweep_damages, GREATEST(bs.non_sweep_damage / NULLIF(bs.meaningful_tokens, 0), gb.avg_damage)::numeric), 0)) > 0
        THEN (COALESCE(bs.non_sweep_damage, 0)
              + COALESCE(qualifying_sweep_sum(bs.sweep_damages, GREATEST(bs.non_sweep_damage / NULLIF(bs.meaningful_tokens, 0), gb.avg_damage)::numeric), 0))::numeric
             / (COALESCE(bs.meaningful_tokens, 0)
                + COALESCE(qualifying_sweep_count(bs.sweep_damages, GREATEST(bs.non_sweep_damage / NULLIF(bs.meaningful_tokens, 0), gb.avg_damage)::numeric), 0))
        ELSE NULL
      END AS adj_avg
    FROM base_stats bs
    LEFT JOIN guild_baseline gb ON gb.rarity = bs.rarity AND gb.set_num = bs.set_num
  ),
  qualified_avg AS (
    SELECT
      *,
      ROW_NUMBER() OVER (
        PARTITION BY rarity, set_num
        ORDER BY adj_avg DESC NULLS LAST, adj_count DESC, first_token_time ASC
      ) AS avg_rank
    FROM adjusted_stats
    WHERE adj_count > 1 AND adj_avg IS NOT NULL
  ),
  total_damage_ranked AS (
    SELECT
      *,
      ROW_NUMBER() OVER (
        PARTITION BY rarity, set_num
        ORDER BY total_damage DESC, token_count DESC, first_token_time ASC
      ) AS total_rank
    FROM adjusted_stats
  ),
  -- Side boss stats with qualifying sweep exception
  side_boss_raw AS (
    SELECT
      rarity,
      set_num,
      CASE WHEN encounter_index = 1 THEN 'SideBoss1' ELSE 'SideBoss2' END AS encounter_label,
      display_name,
      SUM(damage_dealt) FILTER (WHERE NOT is_sweep OR is_one_shot) AS non_sweep_damage,
      COUNT(*) FILTER (WHERE NOT is_sweep OR is_one_shot) AS meaningful_tokens,
      MIN(started_on) AS first_token_time,
      array_agg(damage_dealt::numeric) FILTER (WHERE is_sweep AND NOT is_one_shot) AS sweep_damages,
      encounter_index
    FROM filtered
    WHERE encounter_index IN (1, 2)
    GROUP BY rarity, set_num, encounter_label, display_name, encounter_index
  ),
  side_boss_adjusted AS (
    SELECT
      sbr.rarity,
      sbr.set_num,
      sbr.encounter_label,
      sbr.display_name,
      CASE
        WHEN (COALESCE(sbr.meaningful_tokens, 0)
              + COALESCE(qualifying_sweep_count(sbr.sweep_damages, GREATEST(sbr.non_sweep_damage / NULLIF(sbr.meaningful_tokens, 0), sbb.avg_damage)::numeric), 0)) > 0
        THEN (COALESCE(sbr.non_sweep_damage, 0)
              + COALESCE(qualifying_sweep_sum(sbr.sweep_damages, GREATEST(sbr.non_sweep_damage / NULLIF(sbr.meaningful_tokens, 0), sbb.avg_damage)::numeric), 0))::numeric
             / (COALESCE(sbr.meaningful_tokens, 0)
                + COALESCE(qualifying_sweep_count(sbr.sweep_damages, GREATEST(sbr.non_sweep_damage / NULLIF(sbr.meaningful_tokens, 0), sbb.avg_damage)::numeric), 0))
        ELSE NULL
      END AS avg_damage,
      COALESCE(sbr.meaningful_tokens, 0)
        + COALESCE(qualifying_sweep_count(sbr.sweep_damages, GREATEST(sbr.non_sweep_damage / NULLIF(sbr.meaningful_tokens, 0), sbb.avg_damage)::numeric), 0) AS adj_count,
      sbr.first_token_time
    FROM side_boss_raw sbr
    LEFT JOIN side_boss_baseline sbb
      ON sbb.rarity = sbr.rarity AND sbb.set_num = sbr.set_num AND sbb.encounter_index = sbr.encounter_index
  ),
  side_boss_ranked AS (
    SELECT
      *,
      ROW_NUMBER() OVER (
        PARTITION BY rarity, set_num, encounter_label
        ORDER BY avg_damage DESC NULLS LAST, adj_count DESC, first_token_time ASC
      ) AS side_rank
    FROM side_boss_adjusted
    -- VOTLW side-boss Step 2 qualification: minimum 2 meaningful battles per side
    -- boss (matches the main-boss `adj_count > 1` gate above). If nobody
    -- qualifies, the side-boss award simply has no winner.
    WHERE avg_damage IS NOT NULL AND adj_count > 1
  ),
  boss_identity AS (
    SELECT
      rarity,
      set_num,
      MAX(
        CASE
          WHEN encounter_index IS NULL OR encounter_index = 0 THEN boss_name
          ELSE NULL
        END
      ) AS boss_name
    FROM filtered
    GROUP BY rarity, set_num
  ),
  biggest_hits AS (
    SELECT
      rarity,
      set_num,
      display_name,
      damage_dealt,
      ROW_NUMBER() OVER (
        PARTITION BY rarity, set_num
        ORDER BY damage_dealt DESC, started_on ASC
      ) AS hit_rank
    FROM filtered
    WHERE encounter_id = 0 OR encounter_id IS NULL
  ),
  aggregated AS (
    SELECT
      q.rarity,
      q.set_num,
      COALESCE(bi.boss_name, 'Unknown Boss') AS boss_name,
      MAX(CASE WHEN q.avg_rank = 1 THEN jsonb_build_object('player', q.display_name, 'value', ROUND(q.adj_avg))::text END)::jsonb AS gold,
      MAX(CASE WHEN q.avg_rank = 2 THEN jsonb_build_object('player', q.display_name, 'value', ROUND(q.adj_avg))::text END)::jsonb AS silver,
      MAX(CASE WHEN q.avg_rank = 3 THEN jsonb_build_object('player', q.display_name, 'value', ROUND(q.adj_avg))::text END)::jsonb AS bronze,
      MAX(CASE WHEN t.total_rank = 1 THEN jsonb_build_object('player', t.display_name, 'value', t.total_damage)::text END)::jsonb AS most_damage,
      MAX(CASE WHEN sb.encounter_label = 'SideBoss1' AND sb.side_rank = 1 THEN jsonb_build_object('player', sb.display_name, 'value', ROUND(sb.avg_damage))::text END)::jsonb AS side_boss1,
      MAX(CASE WHEN sb.encounter_label = 'SideBoss2' AND sb.side_rank = 1 THEN jsonb_build_object('player', sb.display_name, 'value', ROUND(sb.avg_damage))::text END)::jsonb AS side_boss2,
      MAX(CASE WHEN bh.hit_rank = 1 THEN jsonb_build_object('player', bh.display_name, 'value', bh.damage_dealt)::text END)::jsonb AS biggest_hit
    FROM qualified_avg q
    LEFT JOIN boss_identity bi
      ON bi.rarity = q.rarity AND bi.set_num = q.set_num
    LEFT JOIN total_damage_ranked t
      ON t.rarity = q.rarity AND t.set_num = q.set_num AND t.display_name = q.display_name
    LEFT JOIN side_boss_ranked sb
      ON sb.rarity = q.rarity AND sb.set_num = q.set_num
    LEFT JOIN biggest_hits bh
      ON bh.rarity = q.rarity AND bh.set_num = q.set_num
    GROUP BY q.rarity, q.set_num, bi.boss_name
  )
  SELECT
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'rarity', ag.rarity,
        'set', ag.set_num,
        'levelString',
          CASE WHEN ag.rarity = 'Legendary' THEN CONCAT('L', ag.set_num + 1)
               WHEN ag.rarity = 'Mythic' THEN CONCAT('M', ag.set_num + 1)
               ELSE CONCAT('S', ag.set_num + 1) END,
        'bossName', ag.boss_name,
        'gold', COALESCE(ag.gold, '{}'::jsonb),
        'silver', COALESCE(ag.silver, '{}'::jsonb),
        'bronze', COALESCE(ag.bronze, '{}'::jsonb),
        'mostDamage', COALESCE(ag.most_damage, '{}'::jsonb),
        'sideBoss1', COALESCE(ag.side_boss1, '{}'::jsonb),
        'sideBoss2', COALESCE(ag.side_boss2, '{}'::jsonb),
        'biggestHit', COALESCE(ag.biggest_hit, '{}'::jsonb)
      )
      ORDER BY ag.rarity, ag.set_num
    ), '[]'::jsonb)
  INTO v_results
  FROM aggregated ag;

  RETURN v_results;
END;
$$;

ALTER FUNCTION public.get_votlw_set_winners(p_guild_code text, p_season text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_war_analytics(p_guild_code text, p_season integer DEFAULT NULL::integer) RETURNS TABLE(war_id text, war_date timestamp with time zone, result text, guild_score integer, opponent_score integer, total_attempts integer, total_damage bigint, participation_rate numeric, cumulative_win_rate numeric)
    LANGUAGE sql STABLE
    AS $$
WITH war_scope AS (
  SELECT *
  FROM guild_war_matches
  WHERE guild_code = p_guild_code
    AND (p_season IS NULL OR war_season = p_season)
),
battle_rollup AS (
  SELECT
    war_id,
    COUNT(*)::INTEGER AS total_attempts,
    SUM(COALESCE(damage_dealt, 0))::BIGINT AS total_damage,
    COUNT(DISTINCT attacker_player_id)::INTEGER AS players_participated
  FROM guild_war_battles
  WHERE guild_code = p_guild_code
    AND war_id IN (SELECT war_id FROM war_scope)
  GROUP BY war_id
),
participation_latest AS (
  SELECT DISTINCT ON (guild_code, war_id, user_id)
    war_id,
    user_id,
    attempts_used,
    attempts_remaining
  FROM guild_war_participation
  WHERE guild_code = p_guild_code
    AND war_id IN (SELECT war_id FROM war_scope)
  ORDER BY guild_code, war_id, user_id, snapshot_at DESC
),
participation_rollup AS (
  SELECT
    war_id,
    SUM(COALESCE(attempts_used, 0))::INTEGER AS tokens_used,
    SUM(COALESCE(attempts_used, 0) + COALESCE(attempts_remaining, 0))::INTEGER AS max_tokens,
    BOOL_OR(attempts_used IS NOT NULL OR attempts_remaining IS NOT NULL) AS has_token_data
  FROM participation_latest
  GROUP BY war_id
),
joined AS (
  SELECT
    w.war_id,
    COALESCE(w.war_start_date, w.war_end_date) AS war_date,
    COALESCE(w.war_result, w.war_status) AS result,
    w.guild_score,
    w.opponent_score,
    b.total_attempts,
    b.total_damage,
    COALESCE(
      CASE WHEN p.has_token_data THEN p.max_tokens END,
      CASE WHEN b.players_participated IS NOT NULL THEN b.players_participated * 10 END
    ) AS max_tokens
  FROM war_scope w
  LEFT JOIN battle_rollup b ON b.war_id = w.war_id
  LEFT JOIN participation_rollup p ON p.war_id = w.war_id
),
ranked AS (
  SELECT
    *,
    SUM(CASE WHEN result = 'win' THEN 1 ELSE 0 END)
      OVER (ORDER BY war_date NULLS LAST) AS cumulative_wins,
    SUM(CASE WHEN result IN ('win', 'loss', 'draw') THEN 1 ELSE 0 END)
      OVER (ORDER BY war_date NULLS LAST) AS cumulative_wars
  FROM joined
)
SELECT
  war_id,
  war_date,
  result,
  guild_score,
  opponent_score,
  COALESCE(total_attempts, 0) AS total_attempts,
  COALESCE(total_damage, 0) AS total_damage,
  CASE
    WHEN COALESCE(max_tokens, 0) > 0 THEN COALESCE(total_attempts, 0)::NUMERIC / max_tokens
    ELSE NULL
  END AS participation_rate,
  CASE
    WHEN COALESCE(cumulative_wars, 0) > 0 THEN cumulative_wins::NUMERIC / cumulative_wars
    ELSE NULL
  END AS cumulative_win_rate
FROM ranked
ORDER BY war_date DESC NULLS LAST;
$$;

ALTER FUNCTION public.get_war_analytics(p_guild_code text, p_season integer) OWNER TO postgres;

CREATE FUNCTION public.get_war_battle_history(p_guild_code text, p_guild_war_id text DEFAULT NULL::text) RETURNS TABLE(battle_id text, guild_war_id text, attacker_display_name text, defender_display_name text, zone_type text, score integer, attacker_power integer, defender_power integer, attacker_units jsonb, defender_units jsonb, battle_time timestamp with time zone, is_guild_attack boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    b.battle_id,
    b.guild_war_id,
    b.attacker_display_name,
    b.defender_display_name,
    b.zone_type,
    b.score,
    b.attacker_power,
    b.defender_power,
    b.attacker_units,
    b.defender_units,
    b.battle_time,
    (b.attacker_team_index = 1) AS is_guild_attack
  FROM guild_war_battles b
  WHERE b.guild_code = p_guild_code
    AND (p_guild_war_id IS NULL OR b.guild_war_id = p_guild_war_id)
  ORDER BY b.battle_time DESC;
END;
$$;

ALTER FUNCTION public.get_war_battle_history(p_guild_code text, p_guild_war_id text) OWNER TO postgres;

CREATE FUNCTION public.get_war_participation_summary(p_guild_code text, p_guild_war_id text) RETURNS TABLE(player_id text, display_name text, opted_in boolean, attempts_used integer, attempts_remaining integer, score integer, last_activity_on timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY
  -- guild_war_participation is SNAPSHOT-keyed. Without DISTINCT ON this
  -- returns one row per snapshot per player, not one row per player.
  WITH latest AS (
    SELECT DISTINCT ON (wp.user_id)
      wp.user_id,
      wp.display_name,
      wp.opted_in,
      wp.attempts_used,
      wp.attempts_remaining,
      wp.score,
      wp.last_activity_on
    FROM guild_war_participation wp
    WHERE wp.guild_code = p_guild_code
      AND wp.war_id = p_guild_war_id
    ORDER BY wp.user_id, wp.snapshot_at DESC
  )
  SELECT
    latest.user_id::TEXT,
    latest.display_name::TEXT,
    latest.opted_in,
    latest.attempts_used,
    latest.attempts_remaining,
    latest.score,
    latest.last_activity_on
  FROM latest
  ORDER BY latest.score DESC NULLS LAST, latest.attempts_used DESC NULLS LAST;
END;
$$;

ALTER FUNCTION public.get_war_participation_summary(p_guild_code text, p_guild_war_id text) OWNER TO postgres;

CREATE FUNCTION public.get_war_participation_summary(p_guild_code text, p_season integer DEFAULT NULL::integer, p_war_id text DEFAULT NULL::text) RETURNS TABLE(player_id text, player_name text, tokens_used integer, max_tokens integer, attempts integer, wins integer, damage_dealt bigint, participation_rate numeric)
    LANGUAGE sql STABLE
    AS $$
WITH war_scope AS (
  SELECT war_id
  FROM guild_war_matches
  WHERE guild_code = p_guild_code
    AND (p_season IS NULL OR war_season = p_season)
    AND (p_war_id IS NULL OR war_id = p_war_id)
),
battle_rollup AS (
  SELECT
    war_id,
    attacker_player_id AS player_id,
    MAX(attacker_player_name) AS player_name,
    COUNT(*)::INTEGER AS attempts,
    SUM(CASE WHEN war_zone_captured(attempt_result, defender_units_json) THEN 1 ELSE 0 END)::INTEGER AS wins,
    SUM(COALESCE(damage_dealt, 0))::BIGINT AS damage_dealt,
    1::INTEGER AS wars_played
  FROM guild_war_battles
  WHERE guild_code = p_guild_code
    AND war_id IN (SELECT war_id FROM war_scope)
  GROUP BY war_id, attacker_player_id
),
battle_agg AS (
  SELECT
    player_id,
    MAX(player_name) AS player_name,
    SUM(attempts)::INTEGER AS attempts,
    SUM(wins)::INTEGER AS wins,
    SUM(damage_dealt)::BIGINT AS damage_dealt,
    SUM(wars_played)::INTEGER AS wars_played
  FROM battle_rollup
  GROUP BY player_id
),
participation_latest AS (
  SELECT DISTINCT ON (guild_code, war_id, user_id)
    war_id,
    user_id,
    display_name,
    attempts_used,
    attempts_remaining,
    total_attempts_left
  FROM guild_war_participation
  WHERE guild_code = p_guild_code
    AND war_id IN (SELECT war_id FROM war_scope)
  ORDER BY guild_code, war_id, user_id, snapshot_at DESC
),
participation_agg AS (
  SELECT
    user_id,
    MAX(display_name) AS display_name,
    SUM(COALESCE(attempts_used, 0))::INTEGER AS attempts_used,
    SUM(COALESCE(attempts_remaining, 0))::INTEGER AS attempts_remaining,
    BOOL_OR(attempts_used IS NOT NULL OR attempts_remaining IS NOT NULL) AS has_token_data
  FROM participation_latest
  GROUP BY user_id
)
SELECT
  COALESCE(p.user_id, b.player_id) AS player_id,
  COALESCE(p.display_name, b.player_name) AS player_name,
  COALESCE(p.attempts_used, b.attempts, 0) AS tokens_used,
  COALESCE(
    CASE WHEN p.has_token_data THEN COALESCE(p.attempts_used, 0) + COALESCE(p.attempts_remaining, 0) END,
    CASE WHEN b.wars_played IS NOT NULL THEN b.wars_played * 10 END,
    0
  ) AS max_tokens,
  COALESCE(b.attempts, 0) AS attempts,
  COALESCE(b.wins, 0) AS wins,
  COALESCE(b.damage_dealt, 0) AS damage_dealt,
  CASE
    WHEN COALESCE(
      CASE WHEN p.has_token_data THEN COALESCE(p.attempts_used, 0) + COALESCE(p.attempts_remaining, 0) END,
      CASE WHEN b.wars_played IS NOT NULL THEN b.wars_played * 10 END,
      0
    ) > 0 THEN
      COALESCE(b.attempts, 0)::NUMERIC
      / NULLIF(
          COALESCE(
            CASE WHEN p.has_token_data THEN COALESCE(p.attempts_used, 0) + COALESCE(p.attempts_remaining, 0) END,
            CASE WHEN b.wars_played IS NOT NULL THEN b.wars_played * 10 END,
            0
          ),
          0
        )
    ELSE NULL
  END AS participation_rate
FROM participation_agg p
FULL OUTER JOIN battle_agg b
  ON p.user_id = b.player_id
ORDER BY tokens_used DESC, attempts DESC;
$$;

ALTER FUNCTION public.get_war_participation_summary(p_guild_code text, p_season integer, p_war_id text) OWNER TO postgres;

CREATE FUNCTION public.get_war_player_stats(p_war_id text, p_guild_code text) RETURNS TABLE(player_id character varying, player_name character varying, is_guild_member boolean, total_attacks bigint, wins bigint, losses bigint, points bigint, perfect_hits bigint, failed_hits bigint, win_rate numeric, avg_score numeric, defended integer, held integer, breached integer, conceded numeric, hold_rate numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH scoped AS (
    SELECT
      b.attacker_player_id,
      b.attacker_player_name,
      b.defender_player_id,
      b.defender_player_name,
      b.is_guild_member AS side,
      b.score_earned,
      b.perfect_hit,
      war_zone_captured(b.attempt_result, b.defender_units_json) AS captured
    FROM guild_war_battles b
    WHERE b.war_id = p_war_id
      AND b.guild_code = p_guild_code
  ),
  attack AS (
    SELECT
      s.attacker_player_id AS pid,
      MIN(s.attacker_player_name) AS pname,
      s.side AS pside,
      COUNT(*)::BIGINT AS n_attacks,
      COUNT(*) FILTER (WHERE s.captured)::BIGINT AS n_wins,
      COUNT(*) FILTER (WHERE NOT s.captured)::BIGINT AS n_losses,
      COALESCE(SUM(s.score_earned), 0)::BIGINT AS n_points,
      COUNT(*) FILTER (WHERE s.perfect_hit = TRUE AND s.captured)::BIGINT AS n_perfect,
      COUNT(*) FILTER (WHERE NOT s.captured)::BIGINT AS n_failed
    FROM scoped s
    WHERE s.attacker_player_id IS NOT NULL
    GROUP BY s.attacker_player_id, s.side
  ),
  defense AS (
    -- NPC exclusion: a battle with no defender_player_id never produces a row.
    -- Side inversion: the defender sits opposite the attacker. A NULL attacker
    -- side is read as "theirs" (FALSE), the same convention get_war_stats uses,
    -- so the defender lands on our side (TRUE).
    SELECT
      s.defender_player_id AS pid,
      MIN(s.defender_player_name) AS pname,
      NOT COALESCE(s.side, FALSE) AS pside,
      COUNT(*)::BIGINT AS n_defended,
      COUNT(*) FILTER (WHERE s.captured)::BIGINT AS n_breached,
      COALESCE(SUM(s.score_earned), 0)::NUMERIC AS n_conceded
    FROM scoped s
    WHERE s.defender_player_id IS NOT NULL
    GROUP BY s.defender_player_id, NOT COALESCE(s.side, FALSE)
  )
  SELECT
    COALESCE(a.pid, d.pid)::varchar(255),
    COALESCE(a.pname, d.pname)::varchar(255),
    CASE WHEN a.pid IS NOT NULL THEN a.pside ELSE d.pside END,
    COALESCE(a.n_attacks, 0)::BIGINT,
    COALESCE(a.n_wins, 0)::BIGINT,
    COALESCE(a.n_losses, 0)::BIGINT,
    COALESCE(a.n_points, 0)::BIGINT,
    COALESCE(a.n_perfect, 0)::BIGINT,
    COALESCE(a.n_failed, 0)::BIGINT,
    CASE
      WHEN COALESCE(a.n_attacks, 0) > 0
        THEN ROUND((a.n_wins::NUMERIC / a.n_attacks) * 100, 1)
      ELSE 0
    END,
    CASE
      WHEN COALESCE(a.n_attacks, 0) > 0
        THEN ROUND(a.n_points::NUMERIC / a.n_attacks, 0)
      ELSE 0
    END,
    COALESCE(d.n_defended, 0)::INTEGER,
    (COALESCE(d.n_defended, 0) - COALESCE(d.n_breached, 0))::INTEGER,
    COALESCE(d.n_breached, 0)::INTEGER,
    COALESCE(d.n_conceded, 0)::NUMERIC,
    ROUND(
      (d.n_defended - d.n_breached)::NUMERIC / NULLIF(d.n_defended, 0) * 100,
      1
    )
  FROM attack a
  FULL OUTER JOIN defense d
    ON d.pid = a.pid
   AND d.pside IS NOT DISTINCT FROM a.pside
  -- Ordered by explicit expressions rather than output-column names to avoid
  -- any ambiguity with the RETURNS TABLE OUT parameters `points`/`wins`.
  -- (Review note 2026-08-10: the pre-WI-6270 `ORDER BY points DESC` DID sort
  -- correctly on the live primary -- verified monotonic over 60/60 rows -- so
  -- this is a clarity choice, not a bug fix.)
  ORDER BY COALESCE(a.n_points, 0) DESC, COALESCE(a.n_wins, 0) DESC;
END;
$$;

ALTER FUNCTION public.get_war_player_stats(p_war_id text, p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_war_stats(p_war_id text, p_guild_code text) RETURNS TABLE(our_attacks bigint, their_attacks bigint, perfect_hits bigint, failed_hits bigint, our_wins bigint, their_wins bigint, our_points bigint, their_points bigint, win_rate numeric, hold_rate numeric, avg_score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH battle_stats AS (
    SELECT
      COUNT(*) FILTER (WHERE is_guild_member = TRUE) AS our_attacks,
      COUNT(*) FILTER (WHERE is_guild_member = FALSE OR is_guild_member IS NULL) AS their_attacks,
      -- Perfect = parser flag AND the zone was actually captured (parser derives
      -- perfect_hit from the bad win definition; strip misclassified rows so the
      -- summary card matches the stripped detail list).
      COUNT(*) FILTER (
        WHERE perfect_hit = TRUE
          AND war_zone_captured(attempt_result, defender_units_json)
      ) AS perfect_hits,
      COUNT(*) FILTER (
        WHERE is_guild_member = TRUE
          AND NOT war_zone_captured(attempt_result, defender_units_json)
      ) AS failed_hits,
      COUNT(*) FILTER (
        WHERE is_guild_member = TRUE
          AND war_zone_captured(attempt_result, defender_units_json)
      ) AS our_wins,
      COUNT(*) FILTER (
        WHERE (is_guild_member = FALSE OR is_guild_member IS NULL)
          AND war_zone_captured(attempt_result, defender_units_json)
      ) AS their_wins,
      COALESCE(SUM(score_earned) FILTER (WHERE is_guild_member = TRUE), 0) AS our_points,
      COALESCE(SUM(score_earned) FILTER (WHERE is_guild_member = FALSE OR is_guild_member IS NULL), 0) AS their_points
    FROM guild_war_battles
    WHERE war_id = p_war_id
      AND guild_code = p_guild_code
  )
  SELECT
    bs.our_attacks,
    bs.their_attacks,
    bs.perfect_hits,
    bs.failed_hits,
    bs.our_wins,
    bs.their_wins,
    bs.our_points,
    bs.their_points,
    CASE WHEN bs.our_attacks > 0
      THEN ROUND((bs.our_wins::NUMERIC / bs.our_attacks) * 100, 1)
      ELSE 0
    END AS win_rate,
    -- Was hardcoded 0 (20260406000001) but displayed by WarSummaryClient.
    -- Hold rate = share of THEIR attacks that failed to capture.
    CASE WHEN bs.their_attacks > 0
      THEN ROUND(((bs.their_attacks - bs.their_wins)::NUMERIC / bs.their_attacks) * 100, 1)
      ELSE 0
    END AS hold_rate,
    CASE WHEN bs.our_attacks > 0
      THEN ROUND(bs.our_points::NUMERIC / bs.our_attacks, 0)
      ELSE 0
    END AS avg_score
  FROM battle_stats bs;
END;
$$;

ALTER FUNCTION public.get_war_stats(p_war_id text, p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.get_webhook_url(p_webhook_type text, p_guild_code text DEFAULT NULL::text, p_cluster_code text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_webhook_url text;
  v_cluster_id uuid;
BEGIN
  -- Try guild webhook first
  IF p_guild_code IS NOT NULL THEN
    SELECT webhook_url INTO v_webhook_url
    FROM webhook_config
    WHERE webhook_type = p_webhook_type
      AND guild_code = p_guild_code
      AND enabled = true
      AND webhook_url IS NOT NULL
      AND webhook_url != '';

    IF v_webhook_url IS NOT NULL THEN
      RETURN v_webhook_url;
    END IF;
  END IF;

  -- Try cluster webhook as fallback
  IF p_cluster_code IS NOT NULL THEN
    SELECT id INTO v_cluster_id
    FROM clusters
    WHERE cluster_code = p_cluster_code;

    SELECT webhook_url INTO v_webhook_url
    FROM webhook_config
    WHERE webhook_type = p_webhook_type
      AND cluster_id = v_cluster_id
      AND enabled = true
      AND webhook_url IS NOT NULL
      AND webhook_url != '';

    IF v_webhook_url IS NOT NULL THEN
      RETURN v_webhook_url;
    END IF;
  END IF;

  RETURN NULL;
END;
$$;

ALTER FUNCTION public.get_webhook_url(p_webhook_type text, p_guild_code text, p_cluster_code text) OWNER TO postgres;

CREATE FUNCTION public.get_write_queue_stats() RETURNS TABLE(status text, count bigint, oldest_pending timestamp with time zone, by_circuit jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT
        q.status,
        COUNT(*) as count,
        MIN(CASE WHEN q.status = 'pending' THEN q.queued_at END) as oldest_pending,
        (
            SELECT jsonb_object_agg(circuit, cnt)
            FROM (
                SELECT COALESCE(circuit_name, 'none') as circuit, COUNT(*) as cnt
                FROM write_queue
                WHERE write_queue.status = q.status
                GROUP BY circuit_name
            ) sub
        ) as by_circuit
    FROM write_queue q
    WHERE q.queued_at > NOW() - INTERVAL '24 hours'
    GROUP BY q.status;
$$;

ALTER FUNCTION public.get_write_queue_stats() OWNER TO postgres;

CREATE FUNCTION public.get_write_statistics() RETURNS TABLE(table_name text, writes_total bigint, inserts bigint, updates bigint, deletes bigint, table_size text, write_percentage numeric)
    LANGUAGE sql
    AS $$
    SELECT
        relname::text as table_name,
        (n_tup_ins + n_tup_upd + n_tup_del) as writes_total,
        n_tup_ins as inserts,
        n_tup_upd as updates,
        n_tup_del as deletes,
        pg_size_pretty(pg_table_size('public.'||relname)) as table_size,
        ROUND((n_tup_ins + n_tup_upd + n_tup_del)::numeric /
              NULLIF(n_tup_ins + n_tup_upd + n_tup_del + seq_scan + idx_scan, 0) * 100, 2) as write_percentage
    FROM pg_stat_user_tables
    WHERE schemaname = 'public'
    ORDER BY writes_total DESC
    LIMIT 20;
$$;

ALTER FUNCTION public.get_write_statistics() OWNER TO postgres;

CREATE FUNCTION public.get_zone_performance(p_guild_code text, p_season integer DEFAULT NULL::integer) RETURNS TABLE(zone_id text, zone_name text, total_attempts integer, wins integer, losses integer, win_rate numeric, avg_damage numeric)
    LANGUAGE sql STABLE
    AS $$
WITH war_scope AS (
  SELECT war_id
  FROM guild_war_matches
  WHERE guild_code = p_guild_code
    AND (p_season IS NULL OR war_season = p_season)
)
SELECT
  b.zone_type AS zone_id,
  COALESCE(MAX(z.zone_name), b.zone_type) AS zone_name,
  COUNT(*)::INTEGER AS total_attempts,
  SUM(CASE WHEN war_zone_captured(b.attempt_result, b.defender_units_json) THEN 1 ELSE 0 END)::INTEGER AS wins,
  SUM(CASE WHEN war_zone_captured(b.attempt_result, b.defender_units_json) THEN 0 ELSE 1 END)::INTEGER AS losses,
  CASE
    WHEN COUNT(*) > 0 THEN
      SUM(CASE WHEN war_zone_captured(b.attempt_result, b.defender_units_json) THEN 1 ELSE 0 END)::NUMERIC / COUNT(*)
    ELSE NULL
  END AS win_rate,
  AVG(COALESCE(b.damage_dealt, 0))::NUMERIC AS avg_damage
FROM guild_war_battles b
LEFT JOIN guild_war_zones z ON z.id = b.zone_id
WHERE b.guild_code = p_guild_code
  AND b.war_id IN (SELECT war_id FROM war_scope)
GROUP BY b.zone_type
ORDER BY total_attempts DESC, zone_id;
$$;

ALTER FUNCTION public.get_zone_performance(p_guild_code text, p_season integer) OWNER TO postgres;

CREATE FUNCTION public.get_zone_stats(p_guild_code text, p_days_back integer DEFAULT 30, p_season_count integer DEFAULT NULL::integer) RETURNS TABLE(zone_type text, zone_display_name text, map_code text, offense_attacks bigint, offense_wins bigint, offense_win_rate numeric, offense_avg_score numeric, defense_attacks bigint, defense_holds bigint, defense_hold_rate numeric, defense_avg_conceded numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min_season INT;
  v_cutoff_date TIMESTAMPTZ;
BEGIN
  IF p_season_count IS NOT NULL THEN
    SELECT MAX(war_season) - p_season_count + 1 INTO v_min_season
    FROM guild_war_matches
    WHERE guild_code = p_guild_code;

    IF v_min_season IS NULL THEN
      v_min_season := 0;
    END IF;
  END IF;

  IF p_days_back > 0 AND p_season_count IS NULL THEN
    v_cutoff_date := NOW() - (p_days_back || ' days')::INTERVAL;
  END IF;

  RETURN QUERY
  WITH offense_stats AS (
    SELECT
      b.zone_type,
      COUNT(*) AS attacks,
      -- Was the raw Loki result flag, which is set from score > 0.
      -- (Phrased without the literal so the WI-6470 pgTAP A6 assertion, which
      -- greps pg_get_functiondef, tests the code and not this comment.)
      COUNT(*) FILTER (
        WHERE war_zone_captured(b.attempt_result, b.defender_units_json)
      ) AS wins,
      AVG(b.score_earned) AS avg_score
    FROM guild_war_battles b
    LEFT JOIN guild_war_matches m ON m.war_id = b.war_id AND m.guild_code = b.guild_code
    WHERE b.guild_code = p_guild_code
      AND b.is_guild_member = TRUE
      AND b.zone_type IS NOT NULL
      AND (v_cutoff_date IS NULL OR b.attempt_start_time >= v_cutoff_date)
      AND (v_min_season IS NULL OR m.war_season >= v_min_season)
    GROUP BY b.zone_type
  ),
  defense_stats AS (
    SELECT
      b.zone_type,
      COUNT(*) AS attacks,
      -- Was: attempt_result = 'loss', which missed every enemy attack that
      -- scored partial damage without capturing -- those are holds.
      COUNT(*) FILTER (
        WHERE NOT war_zone_captured(b.attempt_result, b.defender_units_json)
      ) AS holds,
      AVG(b.score_earned) AS avg_conceded
    FROM guild_war_battles b
    LEFT JOIN guild_war_matches m ON m.war_id = b.war_id AND m.guild_code = b.guild_code
    WHERE b.guild_code = p_guild_code
      AND (b.is_guild_member = FALSE OR b.is_guild_member IS NULL)
      AND b.zone_type IS NOT NULL
      AND (v_cutoff_date IS NULL OR b.attempt_start_time >= v_cutoff_date)
      AND (v_min_season IS NULL OR m.war_season >= v_min_season)
    GROUP BY b.zone_type
  )
  SELECT
    COALESCE(o.zone_type, d.zone_type)::TEXT AS zone_type,
    INITCAP(REPLACE(COALESCE(o.zone_type, d.zone_type), '_', ' '))::TEXT AS zone_display_name,
    NULL::TEXT AS map_code,
    COALESCE(o.attacks, 0) AS offense_attacks,
    COALESCE(o.wins, 0) AS offense_wins,
    CASE
      WHEN COALESCE(o.attacks, 0) > 0 THEN ROUND((o.wins::NUMERIC / o.attacks) * 100, 1)
      ELSE 0
    END AS offense_win_rate,
    ROUND(COALESCE(o.avg_score, 0), 1) AS offense_avg_score,
    COALESCE(d.attacks, 0) AS defense_attacks,
    COALESCE(d.holds, 0) AS defense_holds,
    CASE
      WHEN COALESCE(d.attacks, 0) > 0 THEN ROUND((d.holds::NUMERIC / d.attacks) * 100, 1)
      ELSE 0
    END AS defense_hold_rate,
    ROUND(COALESCE(d.avg_conceded, 0), 1) AS defense_avg_conceded
  FROM offense_stats o
  FULL OUTER JOIN defense_stats d ON o.zone_type = d.zone_type
  ORDER BY (COALESCE(o.attacks, 0) + COALESCE(d.attacks, 0)) DESC;
END;
$$;

ALTER FUNCTION public.get_zone_stats(p_guild_code text, p_days_back integer, p_season_count integer) OWNER TO postgres;

