    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF TG_OP = 'UPDATE' THEN RAISE EXCEPTION 'quarantine PII may be erased, never rewritten' USING ERRCODE = '55000'; END IF; IF current_setting('player_identity.quarantine_pii_erasure', true) IS DISTINCT FROM OLD.quarantine_id::text THEN RAISE EXCEPTION 'quarantine PII deletion requires an explicit owner-authorized erasure context' USING ERRCODE = '42501'; END IF; RETURN OLD; END $$;

