CREATE FUNCTION public.guild_restricts_playbook_access(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_restricts BOOLEAN;
BEGIN
  SELECT gc.restrict_playbooks_to_assignments
  INTO v_restricts
  FROM player_mapping pm
  JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = p_user_id
    AND pm.is_current = true
  LIMIT 1;
  RETURN COALESCE(v_restricts, FALSE);
END;
$$;

ALTER FUNCTION public.guild_restricts_playbook_access(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.handle_boss_playbook_tactics_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    INSERT INTO public.boss_playbook_tactics_history (
        tactics_id,
        content,
        content_format,
        changed_by,
        changed_at,
        version
    ) VALUES (
        OLD.id,
        OLD.content,
        OLD.content_format,
        auth.uid(),
        now(),
        OLD.version
    );

    NEW.version := COALESCE(OLD.version, 0) + 1;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

ALTER FUNCTION public.handle_boss_playbook_tactics_update() OWNER TO postgres;

CREATE FUNCTION public.handle_guild_sync_request(p_guild_code text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    v_result JSONB;
    v_guild_exists BOOLEAN;
BEGIN
    -- Check if guild exists
    v_guild_exists := check_guild_exists(p_guild_code);

    IF NOT v_guild_exists THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Guild not found or not enabled',
            'guild_code', p_guild_code
        );
    END IF;

    -- Check if user has permission to sync this guild
    IF p_user_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1
            FROM player_mapping pm
            WHERE pm.user_id = p_user_id
            AND pm.guild_code = p_guild_code
            AND pm.is_current = true
            AND pm.role IN ('officer', 'leader')
        ) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Insufficient permissions to sync this guild'
            );
        END IF;
    END IF;

    -- Only create sync status if the table exists
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'guild_sync_status') THEN
        -- Create or update sync status entry
        INSERT INTO guild_sync_status (
            guild_code,
            status,
            started_at,
            updated_at
        )
        VALUES (
            p_guild_code,
            'pending',
            NOW(),
            NOW()
        )
        ON CONFLICT (guild_code) DO UPDATE
        SET status = 'pending',
            started_at = NOW(),
            updated_at = NOW();
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'guild_code', p_guild_code,
        'message', 'Sync request initiated'
    );
END;
$$;

ALTER FUNCTION public.handle_guild_sync_request(p_guild_code text, p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    default_guild_code text;
    default_username text;
    default_display_name text;
BEGIN
    -- Extract metadata from the signup process
    default_username := COALESCE(
        new.raw_user_meta_data->>'username',
        split_part(new.email, '@', 1)
    );

    default_display_name := COALESCE(
        new.raw_user_meta_data->>'display_name',
        default_username
    );

    -- For now, we'll store guild_code in metadata during signup
    -- This will be set in the signup form
    default_guild_code := new.raw_user_meta_data->>'guild_code';

    -- Only create profile if guild_code was provided
    IF default_guild_code IS NOT NULL THEN
        -- Check if guild exists
        IF EXISTS (SELECT 1 FROM public.guild_config WHERE guild_code = default_guild_code) THEN
            -- Create player mapping entry
            INSERT INTO public.player_mapping (
                user_id,
                guild_code,
                player_id,
                username,
                display_name,
                discord_username,
                role,
                created_at,
                updated_at
            ) VALUES (
                new.id,
                default_guild_code,
                COALESCE(new.raw_user_meta_data->>'player_id', default_username),
                default_username,
                default_display_name,
                new.raw_user_meta_data->>'discord_username',
                'member'::public.app_role,
                now(),
                now()
            );

            -- Log successful creation
            RAISE LOG 'Created player mapping for user % in guild %', new.id, default_guild_code;
        ELSE
            -- Log warning but don't fail the signup
            RAISE WARNING 'Guild code % not found for user %', default_guild_code, new.id;
        END IF;
    END IF;

    RETURN new;
END;
$$;

ALTER FUNCTION public.handle_new_user() OWNER TO postgres;

