CREATE FUNCTION public.invalidate_player_discord_on_auth_identity_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  v_affected integer := 0;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.provider = 'discord' THEN
      PERFORM pg_advisory_xact_lock(6208, hashtext(NEW.user_id::text));
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
    AND NEW.provider IS NOT DISTINCT FROM OLD.provider
    AND NEW.provider_id IS NOT DISTINCT FROM OLD.provider_id
    AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
  THEN
    RETURN NEW;
  END IF;

  -- Lock both authority keys in deterministic UUID text order on a reassignment.
  IF TG_OP = 'UPDATE' AND NEW.provider = 'discord'
    AND NEW.user_id IS DISTINCT FROM OLD.user_id
  THEN
    IF NEW.user_id::text < OLD.user_id::text THEN
      PERFORM pg_advisory_xact_lock(6208, hashtext(NEW.user_id::text));
      PERFORM pg_advisory_xact_lock(6208, hashtext(OLD.user_id::text));
    ELSE
      PERFORM pg_advisory_xact_lock(6208, hashtext(OLD.user_id::text));
      PERFORM pg_advisory_xact_lock(6208, hashtext(NEW.user_id::text));
    END IF;
  ELSE
    PERFORM pg_advisory_xact_lock(6208, hashtext(OLD.user_id::text));
  END IF;

  IF OLD.provider <> 'discord' THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  UPDATE public.player_mapping AS mapping
  SET discord_user_id = NULL,
      discord_username = NULL,
      updated_at = clock_timestamp()
  WHERE mapping.user_id = OLD.user_id
    AND mapping.discord_user_id = OLD.provider_id;
  GET DIAGNOSTICS v_affected = ROW_COUNT;

  INSERT INTO public.player_identity_discord_invalidation_events (
    operation, affected_mapping_count
  ) VALUES (TG_OP, v_affected);

  UPDATE auth.users AS target
  SET raw_user_meta_data = coalesce(target.raw_user_meta_data, '{}'::jsonb)
    - 'discord_user_id' - 'discord_username' - 'discord_synced'
  WHERE target.id = OLD.user_id;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;

ALTER FUNCTION public.invalidate_player_discord_on_auth_identity_change() OWNER TO postgres;

CREATE FUNCTION public.is_cluster_member(p_cluster_code text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1
    FROM public.player_mapping AS pm
    JOIN public.guild_config AS gc
      ON gc.guild_code = pm.guild_code
    WHERE pm.user_id = (SELECT auth.uid())
      AND pm.is_current IS TRUE
      AND gc.cluster_code IS NOT NULL
      AND gc.cluster_code::text = p_cluster_code
  )
  OR EXISTS (
    SELECT 1
    FROM public.player_mapping AS pm
    WHERE pm.user_id = (SELECT auth.uid())
      AND pm.is_current IS TRUE
      AND pm.is_app_admin IS TRUE
  );
END;
$$;

ALTER FUNCTION public.is_cluster_member(p_cluster_code text) OWNER TO postgres;

