CREATE FUNCTION public.is_user_assigned_to_boss(p_boss_id text, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_primary TEXT;
  v_secondary TEXT;
BEGIN
  SELECT pm.primary_boss, pm.secondary_boss
  INTO v_primary, v_secondary
  FROM player_mapping pm
  WHERE pm.user_id = p_user_id
  LIMIT 1;

  -- Check if boss_id matches primary or secondary assignment
  -- Use case-insensitive partial matching for flexibility
  RETURN (
    v_primary IS NOT NULL AND LOWER(v_primary) LIKE '%' || LOWER(p_boss_id) || '%'
  ) OR (
    v_secondary IS NOT NULL AND LOWER(v_secondary) LIKE '%' || LOWER(p_boss_id) || '%'
  );
END;
$$;

ALTER FUNCTION public.is_user_assigned_to_boss(p_boss_id text, p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.is_user_officer_or_leader(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_role app_role;
BEGIN
  SELECT ur.role
  INTO v_role
  FROM user_roles ur
  WHERE ur.user_id = p_user_id
  LIMIT 1;

  RETURN v_role IN ('officer', 'leader');
END;
$$;

ALTER FUNCTION public.is_user_officer_or_leader(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.list_active_player_invite_codes(p_guild_code text) RETURNS TABLE(player_id text, code text, expires_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_caller record;
  v_selected_guild text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '42501';
  END IF;
  IF p_guild_code IS NULL
    OR length(btrim(p_guild_code)) < 1
    OR length(p_guild_code) > 64
  THEN
    RAISE EXCEPTION 'Invalid guild code'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*)::integer AS match_count,
         bool_or(verified.is_app_admin) AS is_app_admin
  INTO v_caller
  FROM public.resolve_verified_players(ARRAY[v_user_id]) AS verified;
  IF v_caller.match_count <> 1
    OR coalesce(v_caller.is_app_admin, false) IS NOT TRUE
  THEN
    RAISE EXCEPTION 'Verified app-admin authority required'
      USING ERRCODE = '42501';
  END IF;

  v_selected_guild := btrim(p_guild_code);
  RETURN QUERY
  SELECT invite.player_id, invite.code, invite.expires_at
  FROM public.player_invite_codes AS invite
  WHERE invite.guild_code = v_selected_guild
    AND invite.used_at IS NULL
    AND invite.revoked_at IS NULL
    AND invite.expires_at > statement_timestamp()
  ORDER BY invite.player_id, invite.created_at DESC NULLS LAST, invite.id DESC;
END
$$;

ALTER FUNCTION public.list_active_player_invite_codes(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.list_player_invite_codes(p_guild_code text DEFAULT NULL::text) RETURNS TABLE(id uuid, code text, player_id text, display_name text, guild_code text, created_at timestamp with time zone, expires_at timestamp with time zone, used_at timestamp with time zone, revoked_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_caller record;
  v_selected_guild text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '42501';
  END IF;
  IF p_guild_code IS NOT NULL
    AND (length(btrim(p_guild_code)) < 1 OR length(p_guild_code) > 64)
  THEN
    RAISE EXCEPTION 'Invalid guild code'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*)::integer AS match_count,
         (array_agg(verified.guild_code ORDER BY verified.mapping_id))[1]
           AS guild_code,
         (array_agg(verified.role ORDER BY verified.mapping_id))[1] AS role,
         bool_or(verified.is_app_admin) AS is_app_admin
  INTO v_caller
  FROM public.resolve_verified_players(ARRAY[v_user_id]) AS verified;
  IF v_caller.match_count <> 1 THEN
    RAISE EXCEPTION 'Verified player ownership required'
      USING ERRCODE = '42501';
  END IF;

  IF v_caller.is_app_admin THEN
    v_selected_guild := nullif(btrim(p_guild_code), '');
  ELSE
    IF lower(v_caller.role::text) NOT IN ('leader', 'officer') THEN
      RAISE EXCEPTION 'Guild officer authority required'
        USING ERRCODE = '42501';
    END IF;
    IF p_guild_code IS NOT NULL
      AND btrim(p_guild_code) IS DISTINCT FROM v_caller.guild_code
    THEN
      RAISE EXCEPTION 'Invite-code listing is limited to the caller guild'
        USING ERRCODE = '42501';
    END IF;
    v_selected_guild := v_caller.guild_code;
  END IF;

  RETURN QUERY
  SELECT
    invite.id,
    CASE
      WHEN invite.used_at IS NULL
        AND invite.revoked_at IS NULL
        AND invite.expires_at > statement_timestamp()
      THEN invite.code
      ELSE NULL
    END AS code,
    invite.player_id, invite.display_name,
    invite.guild_code, invite.created_at, invite.expires_at,
    invite.used_at, invite.revoked_at
  FROM public.player_invite_codes AS invite
  WHERE v_selected_guild IS NULL OR invite.guild_code = v_selected_guild
  ORDER BY invite.created_at DESC, invite.id
  LIMIT 100;
END
$$;

ALTER FUNCTION public.list_player_invite_codes(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.log_edge_function_execution(p_cluster_code character varying, p_function_name character varying, p_status character varying, p_details jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  -- Create edge function logs table if it doesn't exist
  CREATE TABLE IF NOT EXISTS edge_function_logs (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    cluster_code VARCHAR,
    function_name VARCHAR,
    status VARCHAR,
    details JSONB,
    executed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
  );

  -- Insert log entry
  INSERT INTO edge_function_logs (
    cluster_code,
    function_name,
    status,
    details,
    executed_at
  ) VALUES (
    p_cluster_code,
    p_function_name,
    p_status,
    p_details,
    NOW()
  );

  -- Clean up old logs (keep only last 30 days)
  DELETE FROM edge_function_logs
  WHERE executed_at < NOW() - INTERVAL '30 days';
END;
$$;

ALTER FUNCTION public.log_edge_function_execution(p_cluster_code character varying, p_function_name character varying, p_status character varying, p_details jsonb) OWNER TO postgres;

CREATE FUNCTION public.manage_season_assignments(p_guild_code text, p_season_number text, p_mode text DEFAULT 'upcoming'::text, p_bosses jsonb DEFAULT '[]'::jsonb, p_assignments jsonb DEFAULT '[]'::jsonb, p_primary_secondary jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_role TEXT;
  v_user_guild_code TEXT;
  v_user_cluster TEXT;
  v_target_cluster TEXT;
  v_assigned_count INTEGER := 0;
  v_total_players INTEGER := 0;
  v_total_tokens INTEGER := 0;
  v_mode TEXT := lower(COALESCE(p_mode, 'upcoming'));
  v_bosses JSONB := COALESCE(p_bosses, '[]'::jsonb);
  v_assignments JSONB := COALESCE(p_assignments, '[]'::jsonb);
  v_primary_secondary JSONB := COALESCE(p_primary_secondary, '[]'::jsonb);
BEGIN
  IF p_guild_code IS NULL OR btrim(p_guild_code) = '' THEN
    RAISE EXCEPTION 'Invalid guild code';
  END IF;

  IF p_season_number IS NULL OR btrim(p_season_number) = '' THEN
    RAISE EXCEPTION 'Invalid season number';
  END IF;

  IF v_mode NOT IN ('current', 'upcoming') THEN
    RAISE EXCEPTION 'Invalid mode';
  END IF;

  IF jsonb_typeof(v_bosses) <> 'array' THEN
    v_bosses := '[]'::jsonb;
  END IF;

  IF jsonb_typeof(v_assignments) <> 'array' THEN
    v_assignments := '[]'::jsonb;
  END IF;

  IF jsonb_typeof(v_primary_secondary) <> 'array' THEN
    v_primary_secondary := '[]'::jsonb;
  END IF;

  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Auth required';
    END IF;

    SELECT role, guild_code
      INTO v_user_role, v_user_guild_code
    FROM player_mapping
    WHERE user_id = auth.uid()
      AND is_current = true
    LIMIT 1;

    IF v_user_role IS NULL THEN
      RAISE EXCEPTION 'User profile not found';
    END IF;

    IF v_user_role NOT IN ('officer', 'leader') THEN
      RAISE EXCEPTION 'Insufficient permissions';
    END IF;

    IF v_user_role = 'officer' THEN
      IF v_user_guild_code IS DISTINCT FROM p_guild_code THEN
        RAISE EXCEPTION 'Access denied for guild';
      END IF;
    ELSE
      SELECT gc.cluster_code INTO v_user_cluster
      FROM guild_config gc
      WHERE gc.guild_code = v_user_guild_code;

      SELECT gc.cluster_code INTO v_target_cluster
      FROM guild_config gc
      WHERE gc.guild_code = p_guild_code;

      IF v_user_guild_code IS DISTINCT FROM p_guild_code AND
         (v_user_cluster IS NULL OR v_target_cluster IS NULL OR v_user_cluster != v_target_cluster) THEN
        RAISE EXCEPTION 'Access denied for cluster';
      END IF;
    END IF;
  END IF;

  IF jsonb_array_length(v_bosses) > 0 THEN
    INSERT INTO upcoming_season_bosses (
      guild_code,
      season_number,
      level,
      boss_name,
      sub_bosses,
      selected_by,
      selected_at
    )
    SELECT
      p_guild_code,
      p_season_number,
      b.level,
      b.boss_name,
      b.sub_bosses,
      auth.uid(),
      NOW()
    FROM jsonb_to_recordset(v_bosses) AS b(
      level TEXT,
      boss_name TEXT,
      sub_bosses JSONB
    )
    WHERE b.boss_name IS NOT NULL AND btrim(b.boss_name) <> ''
    ON CONFLICT (guild_code, season_number, level)
    DO UPDATE SET
      boss_name = EXCLUDED.boss_name,
      sub_bosses = coalesce(upcoming_season_bosses.sub_bosses, '{}'::jsonb) || coalesce(excluded.sub_bosses, '{}'::jsonb),
      selected_by = EXCLUDED.selected_by,
      selected_at = NOW();
  END IF;

  IF jsonb_array_length(v_assignments) > 0 THEN
    INSERT INTO upcoming_season_assignments (
      guild_code,
      season_number,
      player_id,
      display_name,
      primary_boss,
      secondary_boss,
      token_allocations,
      uses_flexible_tokens,
      total_tokens_allocated,
      assigned_by,
      assigned_at
    )
    SELECT
      p_guild_code,
      p_season_number,
      a.player_id,
      a.display_name,
      a.primary_boss,
      a.secondary_boss,
      a.token_allocations,
      a.uses_flexible_tokens,
      a.total_tokens_allocated,
      auth.uid(),
      NOW()
    FROM jsonb_to_recordset(v_assignments) AS a(
      player_id TEXT,
      display_name TEXT,
      primary_boss TEXT,
      secondary_boss TEXT,
      token_allocations JSONB,
      uses_flexible_tokens BOOLEAN,
      total_tokens_allocated INTEGER
    )
    ON CONFLICT (guild_code, season_number, player_id)
    DO UPDATE SET
      display_name = EXCLUDED.display_name,
      primary_boss = EXCLUDED.primary_boss,
      secondary_boss = EXCLUDED.secondary_boss,
      token_allocations = EXCLUDED.token_allocations,
      uses_flexible_tokens = EXCLUDED.uses_flexible_tokens,
      total_tokens_allocated = EXCLUDED.total_tokens_allocated,
      assigned_by = EXCLUDED.assigned_by,
      assigned_at = NOW(),
      updated_at = NOW();
  END IF;

  IF v_mode = 'current' AND jsonb_array_length(v_primary_secondary) > 0 THEN
    UPDATE player_mapping pm
    SET
      primary_boss = u.primary_boss,
      secondary_boss = u.secondary_boss,
      assigned_at = NOW(),
      updated_at = NOW()
    FROM jsonb_to_recordset(v_primary_secondary) AS u(
      player_id TEXT,
      primary_boss TEXT,
      secondary_boss TEXT
    )
    WHERE pm.player_id = u.player_id
      AND pm.guild_code = p_guild_code
      AND pm.is_current = true;
  END IF;

  SELECT
    COUNT(*),
    COALESCE(SUM(COALESCE(a.total_tokens_allocated, 0)), 0),
    COALESCE(SUM(CASE WHEN COALESCE(a.total_tokens_allocated, 0) > 0 THEN 1 ELSE 0 END), 0)
  INTO v_total_players, v_total_tokens, v_assigned_count
  FROM jsonb_to_recordset(v_assignments) AS a(total_tokens_allocated INTEGER);

  BEGIN
    INSERT INTO audit_logs (action, user_id, details)
    VALUES (
      'assignment_save',
      auth.uid(),
      jsonb_build_object(
        'guild_code', p_guild_code,
        'season', p_season_number,
        'mode', v_mode,
        'assigned_count', v_assigned_count,
        'total_players', v_total_players,
        'total_tokens', v_total_tokens,
        'bosses', COALESCE(
          (
            SELECT jsonb_agg(b.boss_name)
            FROM jsonb_to_recordset(v_bosses) AS b(boss_name TEXT)
            WHERE b.boss_name IS NOT NULL AND btrim(b.boss_name) <> ''
          ),
          '[]'::jsonb
        )
      )
    );
  EXCEPTION WHEN OTHERS THEN
    -- Ignore audit log failures
  END;

  RETURN jsonb_build_object(
    'assignedCount', v_assigned_count,
    'totalPlayers', v_total_players,
    'totalTokens', v_total_tokens
  );
END;
$$;

ALTER FUNCTION public.manage_season_assignments(p_guild_code text, p_season_number text, p_mode text, p_bosses jsonb, p_assignments jsonb, p_primary_secondary jsonb) OWNER TO postgres;

CREATE FUNCTION public.manual_refresh_guild_snapshots() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamp;
  v_end timestamp;
  v_count integer;
  v_season integer;
BEGIN
  v_start := clock_timestamp();

  -- Call the comprehensive refresh function (not the simplified one)
  PERFORM public.refresh_public_guild_snapshots();

  -- Get the season from the refreshed data
  SELECT season INTO v_season FROM public_guild_snapshots LIMIT 1;

  -- Get count of refreshed snapshots
  SELECT COUNT(*) INTO v_count FROM public_guild_snapshots;

  v_end := clock_timestamp();

  RETURN jsonb_build_object(
    'success', true,
    'count', v_count,
    'season', v_season,
    'duration_ms', EXTRACT(EPOCH FROM (v_end - v_start)) * 1000,
    'message', 'Guild snapshots refreshed with comprehensive data'
  );
END;
$$;

ALTER FUNCTION public.manual_refresh_guild_snapshots() OWNER TO postgres;

CREATE FUNCTION public.mark_support_messages_read(p_ticket_id uuid, p_user_id uuid, p_is_admin boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  DECLARE
    messages_marked INTEGER;
  BEGIN
    IF p_is_admin THEN
      -- Admin marking messages as read
      UPDATE support_messages
      SET read_by_admin_at = NOW()
      WHERE ticket_id = p_ticket_id
        AND read_by_admin_at IS NULL
        AND NOT is_admin_response;

      GET DIAGNOSTICS messages_marked = ROW_COUNT;

      -- Reset admin unread counter
      UPDATE support_tickets
      SET admin_unread_count = 0
      WHERE id = p_ticket_id;
    ELSE
      -- User marking messages as read
      UPDATE support_messages
      SET read_by_user_at = NOW()
      WHERE ticket_id = p_ticket_id
        AND read_by_user_at IS NULL
        AND is_admin_response;

      GET DIAGNOSTICS messages_marked = ROW_COUNT;

      -- Reset user unread counter
      UPDATE support_tickets
      SET user_unread_count = 0
      WHERE id = p_ticket_id;
    END IF;

    RETURN messages_marked;
  END;
  $$;

ALTER FUNCTION public.mark_support_messages_read(p_ticket_id uuid, p_user_id uuid, p_is_admin boolean) OWNER TO postgres;

CREATE FUNCTION public.matview_refresh_health() RETURNS TABLE(signal text, detail text, is_unhealthy boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'cron'
    AS $$
begin
  -- (a) content-freshness of the flagship public matview (swallow-proof)
  return query
  select
    'mv_public_stats.cached_at'::text,
    case
      when mx.ts is null then 'never refreshed'
      else 'last refresh ' || round(extract(epoch from (now() - mx.ts)) / 60.0, 1) || ' min ago'
    end,
    (mx.ts is null or now() - mx.ts > interval '60 minutes')
  from (select max(cached_at) as ts from public.mv_public_stats) mx;

  -- (b) refresh/purge cron jobs whose latest terminal run failed
  return query
  select
    ('cron:' || j.jobname)::text,
    'latest terminal run ' || lt.status || coalesce(' at ' || lt.start_time::text, ''),
    (lt.status = 'failed')
  from cron.job j
  join lateral (
    select d.status, d.start_time
    from cron.job_run_details d
    where d.jobid = j.jobid
      and d.status in ('succeeded', 'failed')
    order by d.start_time desc
    limit 1
  ) lt on true
  where j.active
    and j.jobname ~* 'refresh'
    and j.jobname ~* 'stat|matview|rank|averag|veteran|member|guild-perf|snapshot';
end;
$$;

ALTER FUNCTION public.matview_refresh_health() OWNER TO postgres;

CREATE FUNCTION public.merge_duplicate_player_mappings() RETURNS TABLE(player_id text, records_merged integer, kept_guild_code text, preserved_user_id uuid, removed_guild_codes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    v_player record;
    v_primary record;
    v_removed_guilds text[];
    v_merge_count integer;
BEGIN
    -- Find all players with multiple records
    FOR v_player IN (
        SELECT pm.player_id, COUNT(*) as record_count
        FROM player_mapping pm
        GROUP BY pm.player_id
        HAVING COUNT(*) > 1
        ORDER BY pm.player_id
    ) LOOP
        -- Find the "primary" record to keep:
        -- Priority: 1) Has user_id, 2) is_current=true, 3) Most recently updated
        SELECT pm.* INTO v_primary
        FROM player_mapping pm
        WHERE pm.player_id = v_player.player_id
        ORDER BY
            (pm.user_id IS NOT NULL) DESC,
            pm.is_current DESC,
            pm.updated_at DESC NULLS LAST
        LIMIT 1;

        -- Collect guild codes that will be removed
        SELECT array_agg(pm.guild_code) INTO v_removed_guilds
        FROM player_mapping pm
        WHERE pm.player_id = v_player.player_id
        AND pm.id != v_primary.id;

        -- Merge important fields from other records into the primary record
        -- This preserves user_id, api_key, preferences from any record that has them
        UPDATE player_mapping pm_primary
        SET
            user_id = COALESCE(pm_primary.user_id, (
                SELECT pm2.user_id
                FROM player_mapping pm2
                WHERE pm2.player_id = v_player.player_id
                AND pm2.user_id IS NOT NULL
                LIMIT 1
            )),
            tacticus_api_key_encrypted = COALESCE(pm_primary.tacticus_api_key_encrypted, (
                SELECT pm2.tacticus_api_key_encrypted
                FROM player_mapping pm2
                WHERE pm2.player_id = v_player.player_id
                AND pm2.tacticus_api_key_encrypted IS NOT NULL
                LIMIT 1
            )),
            api_key_added_at = COALESCE(pm_primary.api_key_added_at, (
                SELECT pm2.api_key_added_at
                FROM player_mapping pm2
                WHERE pm2.player_id = v_player.player_id
                AND pm2.api_key_added_at IS NOT NULL
                LIMIT 1
            )),
            discord_username = COALESCE(pm_primary.discord_username, (
                SELECT pm2.discord_username
                FROM player_mapping pm2
                WHERE pm2.player_id = v_player.player_id
                AND pm2.discord_username IS NOT NULL
                LIMIT 1
            )),
            discord_user_id = COALESCE(pm_primary.discord_user_id, (
                SELECT pm2.discord_user_id
                FROM player_mapping pm2
                WHERE pm2.player_id = v_player.player_id
                AND pm2.discord_user_id IS NOT NULL
                LIMIT 1
            )),
            tacticus_share_url = COALESCE(pm_primary.tacticus_share_url, (
                SELECT pm2.tacticus_share_url
                FROM player_mapping pm2
                WHERE pm2.player_id = v_player.player_id
                AND pm2.tacticus_share_url IS NOT NULL
                LIMIT 1
            )),
            theme_preference = COALESCE(pm_primary.theme_preference, (
                SELECT pm2.theme_preference
                FROM player_mapping pm2
                WHERE pm2.player_id = v_player.player_id
                AND pm2.theme_preference IS NOT NULL
                LIMIT 1
            )),
            boss_preferences = CASE
                WHEN pm_primary.boss_preferences IS NULL OR pm_primary.boss_preferences = '{}'::jsonb
                THEN (
                    SELECT pm2.boss_preferences
                    FROM player_mapping pm2
                    WHERE pm2.player_id = v_player.player_id
                    AND pm2.boss_preferences IS NOT NULL
                    AND pm2.boss_preferences != '{}'::jsonb
                    LIMIT 1
                )
                ELSE pm_primary.boss_preferences
            END,
            is_app_admin = COALESCE(pm_primary.is_app_admin, (
                SELECT pm2.is_app_admin
                FROM player_mapping pm2
                WHERE pm2.player_id = v_player.player_id
                AND pm2.is_app_admin = true
                LIMIT 1
            )),
            protected = COALESCE(pm_primary.protected, (
                SELECT pm2.protected
                FROM player_mapping pm2
                WHERE pm2.player_id = v_player.player_id
                AND pm2.protected = true
                LIMIT 1
            )),
            updated_at = NOW()
        WHERE pm_primary.id = v_primary.id;

        -- Delete the duplicate records
        DELETE FROM player_mapping
        WHERE player_mapping.player_id = v_player.player_id
        AND player_mapping.id != v_primary.id;

        GET DIAGNOSTICS v_merge_count = ROW_COUNT;

        -- Return info about what was merged
        player_id := v_player.player_id;
        records_merged := v_merge_count;
        kept_guild_code := v_primary.guild_code;
        preserved_user_id := v_primary.user_id;
        removed_guild_codes := v_removed_guilds;
        RETURN NEXT;
    END LOOP;
END;
$$;

ALTER FUNCTION public.merge_duplicate_player_mappings() OWNER TO postgres;

CREATE TABLE public.upcoming_season_bosses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    guild_code text NOT NULL,
    season_number text NOT NULL,
    level text NOT NULL,
    boss_name text NOT NULL,
    selected_by uuid,
    selected_at timestamp with time zone DEFAULT now(),
    sub_bosses jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT upcoming_season_bosses_boss_name_nonempty CHECK ((boss_name <> ''::text)),
    CONSTRAINT upcoming_season_bosses_level_check CHECK ((level = ANY (ARRAY['L1'::text, 'L2'::text, 'L3'::text, 'L4'::text, 'L5'::text, 'M1'::text, 'M2'::text, 'M3'::text, 'M4'::text, 'M5'::text])))
);

ALTER TABLE public.upcoming_season_bosses OWNER TO postgres;

CREATE FUNCTION public.merge_season_boss_sub_bosses(p_guild_code text, p_season_number text, p_level text, p_patch jsonb, p_selected_by uuid) RETURNS public.upcoming_season_bosses
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_patch jsonb := coalesce(p_patch, '{}'::jsonb);
  v_row public.upcoming_season_bosses;
BEGIN
  -- Deliberately NOT declared STRICT: a STRICT function returns NULL on any
  -- NULL argument, which would turn a malformed call into a silent no-op --
  -- the same class of quiet failure this migration exists to remove.
  IF coalesce(btrim(p_guild_code), '') = ''
     OR coalesce(btrim(p_season_number), '') = ''
     OR coalesce(btrim(p_level), '') = '' THEN
    RAISE EXCEPTION
      'merge_season_boss_sub_bosses: p_guild_code, p_season_number and p_level are all required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- `jsonb 'null'` and jsonb scalars are not mergeable with `||` (the operator
  -- either errors or produces an array). Reject them with a clear message
  -- rather than leaking an operator-level error to the route.
  IF jsonb_typeof(v_patch) <> 'object' THEN
    RAISE EXCEPTION
      'merge_season_boss_sub_bosses: p_patch must be a JSON object, got %',
      jsonb_typeof(v_patch)
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- The arbiter is the table's own unique constraint
  -- upcoming_season_bosses_guild_code_season_number_level_key
  -- UNIQUE (guild_code, season_number, level), confirmed on the primary
  -- 2026-07-31. It is a plain (non-partial) constraint, so column-list
  -- inference resolves it -- the same form manage_season_assignments already
  -- uses against this table.
  INSERT INTO public.upcoming_season_bosses AS t
    (guild_code, season_number, level, boss_name, sub_bosses, selected_by)
  VALUES
    (p_guild_code, p_season_number, p_level, '__pending__', v_patch, p_selected_by)
  ON CONFLICT (guild_code, season_number, level)
  DO UPDATE SET
    sub_bosses  = coalesce(t.sub_bosses, '{}'::jsonb) || excluded.sub_bosses,
    selected_by = excluded.selected_by
  RETURNING t.* INTO v_row;

  RETURN v_row;
END;
$$;

ALTER FUNCTION public.merge_season_boss_sub_bosses(p_guild_code text, p_season_number text, p_level text, p_patch jsonb, p_selected_by uuid) OWNER TO postgres;

CREATE FUNCTION public.migrate_boss_target_tokens_legacy_names(p_apply boolean DEFAULT false) RETURNS TABLE(phase text, guild_code text, legacy_boss_name text, rarity text, set_num integer, encounter_id integer, target_tokens numeric, action text, resolved_boss_type text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Audit + plan: classify every legacy main-encounter row.
  RETURN QUERY
  WITH legacy AS (
    SELECT
      btt.guild_code,
      btt.boss_name AS legacy_name,
      btt.rarity,
      btt.set AS set_num,
      btt.encounter_id,
      btt.target_tokens
    FROM public.boss_target_tokens btt
    WHERE btt.encounter_id = 0
      AND btt.skip = false
      AND NOT EXISTS (
        SELECT 1
        FROM public.boss_mapping bm
        WHERE bm.boss_type = btt.boss_name
      )
  ),
  resolved AS (
    SELECT
      l.guild_code,
      l.legacy_name,
      l.rarity,
      l.set_num,
      l.encounter_id,
      l.target_tokens,
      -- boss_mapping is one-to-many on display name (e.g. "Belisarius Cawl"
      -- maps to both "Belisarius" and "BelisariusRW"). Prefer the boss_type
      -- that has actual EOT_GR_data activity for this guild at this slot.
      (
        SELECT bm.boss_type
        FROM public.boss_mapping bm
        WHERE bm.boss_name = l.legacy_name
          AND bm.encounter_index = 0
          AND EXISTS (
            SELECT 1
            FROM public."EOT_GR_data" e
            WHERE e."Guild" = l.guild_code
              AND e."Name" = bm.boss_type
              AND e."encounterId" = 0
              AND e.rarity = l.rarity
              AND e."set" = l.set_num - 1
          )
        LIMIT 1
      ) AS preferred_boss_type,
      (
        SELECT bm.boss_type
        FROM public.boss_mapping bm
        WHERE bm.boss_name = l.legacy_name
          AND bm.encounter_index = 0
        ORDER BY bm.boss_type
        LIMIT 1
      ) AS any_boss_type
    FROM legacy l
  ),
  planned AS (
    SELECT
      r.guild_code,
      r.legacy_name,
      r.rarity,
      r.set_num,
      r.encounter_id,
      r.target_tokens,
      COALESCE(r.preferred_boss_type, r.any_boss_type) AS resolved_boss_type,
      CASE
        WHEN r.preferred_boss_type IS NOT NULL AND NOT EXISTS (
          SELECT 1
          FROM public.boss_target_tokens existing
          WHERE existing.guild_code = r.guild_code
            AND existing.boss_name = r.preferred_boss_type
            AND existing.rarity = r.rarity
            AND existing.set = r.set_num
            AND existing.encounter_id = r.encounter_id
        ) THEN 'RENAME'
        WHEN r.preferred_boss_type IS NOT NULL THEN 'DELETE_COLLIDES_WITH_LIVE_ROW'
        WHEN r.any_boss_type IS NOT NULL THEN 'DELETE_NO_GUILD_HISTORY_FOR_MAPPING'
        ELSE 'DELETE_NO_MAPPING'
      END AS action
    FROM resolved r
  )
  SELECT
    'plan'::TEXT AS phase,
    p.guild_code,
    p.legacy_name AS legacy_boss_name,
    p.rarity,
    p.set_num,
    p.encounter_id,
    p.target_tokens,
    p.action,
    p.resolved_boss_type
  FROM planned p
  ORDER BY p.guild_code, p.rarity, p.set_num;

  IF p_apply THEN
    -- Apply RENAMEs first (UPDATEs), then DELETEs. Order matters because
    -- a RENAME could in theory collide with another row planned for DELETE;
    -- we already excluded that case in the planner (`existing` lookup) but
    -- keep the order for defensive predictability.
    -- Data-modifying CTEs must be at top level, so this is a single UPDATE
    -- with a computed-column subselect in the FROM clause.
    WITH rename_plan AS (
      SELECT
        btt.guild_code,
        btt.boss_name AS legacy_name,
        btt.rarity,
        btt.set,
        btt.encounter_id,
        (
          SELECT bm.boss_type
          FROM public.boss_mapping bm
          WHERE bm.boss_name = btt.boss_name
            AND bm.encounter_index = 0
            AND EXISTS (
              SELECT 1
              FROM public."EOT_GR_data" e
              WHERE e."Guild" = btt.guild_code
                AND e."Name" = bm.boss_type
                AND e."encounterId" = 0
                AND e.rarity = btt.rarity
                AND e."set" = btt.set - 1
            )
          LIMIT 1
        ) AS new_boss_type
      FROM public.boss_target_tokens btt
      WHERE btt.encounter_id = 0
        AND btt.skip = false
        AND NOT EXISTS (
          SELECT 1 FROM public.boss_mapping bm WHERE bm.boss_type = btt.boss_name
        )
    )
    UPDATE public.boss_target_tokens t
    SET boss_name = rp.new_boss_type,
        updated_at = now()
    FROM rename_plan rp
    WHERE rp.new_boss_type IS NOT NULL
      AND t.guild_code = rp.guild_code
      AND t.boss_name = rp.legacy_name
      AND t.rarity = rp.rarity
      AND t.set = rp.set
      AND t.encounter_id = rp.encounter_id
      AND NOT EXISTS (
        SELECT 1 FROM public.boss_target_tokens existing
        WHERE existing.guild_code = rp.guild_code
          AND existing.boss_name = rp.new_boss_type
          AND existing.rarity = rp.rarity
          AND existing.set = rp.set
          AND existing.encounter_id = rp.encounter_id
      );

    -- Anything still legacy after the rename is deleted.
    DELETE FROM public.boss_target_tokens btt
    WHERE btt.encounter_id = 0
      AND btt.skip = false
      AND NOT EXISTS (
        SELECT 1 FROM public.boss_mapping bm WHERE bm.boss_type = btt.boss_name
      );

    -- Re-emit audit so the caller can confirm zero remaining.
    RETURN QUERY
    SELECT
      'post_apply_remaining'::TEXT AS phase,
      btt.guild_code,
      btt.boss_name AS legacy_boss_name,
      btt.rarity,
      btt.set AS set_num,
      btt.encounter_id,
      btt.target_tokens,
      'STILL_PRESENT'::TEXT AS action,
      NULL::TEXT AS resolved_boss_type
    FROM public.boss_target_tokens btt
    WHERE btt.encounter_id = 0
      AND btt.skip = false
      AND NOT EXISTS (
        SELECT 1 FROM public.boss_mapping bm WHERE bm.boss_type = btt.boss_name
      );
  END IF;
END;
$$;

ALTER FUNCTION public.migrate_boss_target_tokens_legacy_names(p_apply boolean) OWNER TO postgres;

CREATE FUNCTION public.migrate_player_api_key(p_player_id text, p_encrypted_key text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Update the player mapping with encrypted key
  UPDATE player_mapping
  SET
    tacticus_api_key_encrypted = p_encrypted_key,
    api_key_migration_status = 'completed',
    updated_at = now()
  WHERE player_id = p_player_id
    AND tacticus_api_key IS NOT NULL
    AND tacticus_api_key != ''
    AND (api_key_migration_status = 'pending' OR api_key_migration_status IS NULL);

  -- Note: We don't clear the original tacticus_api_key yet for rollback safety
END;
$$;

ALTER FUNCTION public.migrate_player_api_key(p_player_id text, p_encrypted_key text) OWNER TO postgres;

CREATE FUNCTION public.migrate_to_v2_functions() RETURNS text
    LANGUAGE plpgsql
    AS $_$
BEGIN
  -- Drop and recreate the original function names to point to v2 implementations

  -- Guild overall leaderboard
  BEGIN
    DROP FUNCTION IF EXISTS get_guild_overall_leaderboard(text, text) CASCADE;

    CREATE OR REPLACE FUNCTION get_guild_overall_leaderboard(
      p_guild_code TEXT,
      p_season TEXT
    )
    RETURNS TABLE(
      displayName TEXT,
      guild TEXT,
      total_damage BIGINT,
      battle_count BIGINT,
      avg_damage NUMERIC,
      bombs_used BIGINT,
      bosses_killed BIGINT,
      percent_vs_cluster NUMERIC,
      current_rank BIGINT
    )
    LANGUAGE plpgsql
    AS $inner$
    BEGIN
      RETURN QUERY SELECT * FROM get_guild_overall_leaderboard_v2(p_guild_code, p_season);
    END;
    $inner$;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE NOTICE 'Could not migrate get_guild_overall_leaderboard: %', SQLERRM;
  END;

  -- Guild boss leaderboard
  BEGIN
    DROP FUNCTION IF EXISTS get_guild_boss_leaderboard(text, text, text) CASCADE;

    CREATE OR REPLACE FUNCTION get_guild_boss_leaderboard(
      p_guild_code TEXT,
      p_season TEXT,
      p_boss_name TEXT DEFAULT NULL
    )
    RETURNS TABLE(
      displayName TEXT,
      guild TEXT,
      boss_name TEXT,
      encounter_index INTEGER,
      total_damage BIGINT,
      battle_count BIGINT,
      avg_damage NUMERIC,
      current_rank BIGINT
    )
    LANGUAGE plpgsql
    AS $inner$
    BEGIN
      RETURN QUERY SELECT * FROM get_guild_boss_leaderboard_v2(p_guild_code, p_season, p_boss_name);
    END;
    $inner$;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE NOTICE 'Could not migrate get_guild_boss_leaderboard: %', SQLERRM;
  END;

  -- Player performance in cluster
  BEGIN
    DROP FUNCTION IF EXISTS get_player_performance_in_cluster(text, text, text, text) CASCADE;

    CREATE OR REPLACE FUNCTION get_player_performance_in_cluster(
      p_player_name TEXT,
      p_guild_code TEXT,
      p_cluster_code TEXT,
      p_season TEXT
    )
    RETURNS TABLE(
      player_avg NUMERIC,
      guild_avg NUMERIC,
      cluster_avg NUMERIC,
      vs_guild_pct NUMERIC,
      vs_cluster_pct NUMERIC,
      cluster_rank INTEGER
    )
    LANGUAGE plpgsql
    AS $inner$
    BEGIN
      RETURN QUERY SELECT * FROM get_player_performance_in_cluster_v2(p_player_name, p_guild_code, p_cluster_code, p_season);
    END;
    $inner$;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE NOTICE 'Could not migrate get_player_performance_in_cluster: %', SQLERRM;
  END;

  RETURN 'Migration to v2 functions completed. Check notices above for any errors.';
END;
$_$;

ALTER FUNCTION public.migrate_to_v2_functions() OWNER TO postgres;

CREATE FUNCTION public.mint_player_possession_invite(p_subject uuid, p_player_id text, p_upstream_digest text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $_$
DECLARE
  v_request_role text := coalesce(
    nullif(nullif(current_setting('role', true), ''), 'none'),
    session_user
  );
  v_player_id text := btrim(coalesce(p_player_id, ''));
  v_target record;
  v_invite_id uuid := gen_random_uuid();
  v_code text;
  v_attempt integer;
  v_expires_at timestamptz := clock_timestamp() + interval '10 minutes';
BEGIN
  IF v_request_role <> 'service_role' THEN
    RAISE EXCEPTION 'Possession proofs may only be minted by the server route'
      USING ERRCODE = '42501', DETAIL = 'MINT_ROLE_REQUIRED';
  END IF;
  IF p_subject IS NULL THEN
    RAISE EXCEPTION 'A proof subject is required'
      USING ERRCODE = '22023', DETAIL = 'MINT_SUBJECT_REQUIRED';
  END IF;
  IF length(v_player_id) < 1 OR length(v_player_id) > 128 THEN
    RAISE EXCEPTION 'A bounded target player id is required'
      USING ERRCODE = '22023', DETAIL = 'MINT_PLAYER_REQUIRED';
  END IF;
  -- The digest is a sha256 hex of the route's upstream verification evidence.
  -- Bounded and shaped on purpose: an unbounded caller-supplied blob is exactly
  -- what architect R1 criterion 7 refuses.
  IF p_upstream_digest IS NULL OR p_upstream_digest !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'A sha256 hex upstream digest is required'
      USING ERRCODE = '22023', DETAIL = 'MINT_DIGEST_REQUIRED';
  END IF;

  -- Deliberately NOT rate-limited here (S6c). Minting a proof grants no
  -- authority on its own -- the binding still requires the authenticated RPC,
  -- which IS rate-limited to one success per subject per 7 days, and every mint
  -- targets an UNCLAIMED row a same-guild officer could already mint an ordinary
  -- invite for. The rate meaning lives on the state-changing side, not here. If
  -- mint spam ever becomes a concern, cap mints-per-subject-per-hour from the
  -- profile/change-player-id/mint audit trail; not warranted for a single-
  -- operator homelab today.
  -- Same subject key the claim, deletion, and transfer corridors serialize on.
  PERFORM pg_advisory_xact_lock(6208, hashtext(p_subject::text));

  IF EXISTS (
    SELECT 1
    FROM public.player_identity_subject_authority_blocks AS block
    WHERE block.subject_user_id = p_subject
  ) THEN
    RAISE EXCEPTION 'Account authority is permanently blocked'
      USING ERRCODE = '42501', DETAIL = 'SUBJECT_AUTHORITY_BLOCKED';
  END IF;
  PERFORM 1
  FROM auth.users AS subject
  WHERE subject.id = p_subject
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Proof subject does not exist'
      USING ERRCODE = '42501', DETAIL = 'AUTH_SUBJECT_ABSENT';
  END IF;

  -- player_id is globally unique, so a current row is exact by construction.
  SELECT mapping.id, mapping.player_id, mapping.display_name,
         mapping.guild_code, mapping.user_id, mapping.ownership_attestation_id
  INTO v_target
  FROM public.player_mapping AS mapping
  WHERE mapping.player_id = v_player_id
    AND mapping.is_current IS TRUE
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'That player is not on a tracked guild roster yet'
      USING ERRCODE = '22023', DETAIL = 'PLAYER_NOT_ON_TRACKED_ROSTER';
  END IF;
  -- The subject re-proving a player they already hold is the idempotent retry
  -- the RPC answers with success; anyone else's row is a hard stop here.
  IF v_target.user_id IS NOT NULL AND v_target.user_id IS DISTINCT FROM p_subject
  THEN
    RAISE EXCEPTION 'That player profile is already claimed'
      USING ERRCODE = '22023', DETAIL = 'TARGET_ALREADY_CLAIMED';
  END IF;
  -- Mint-time mirror of the transfer's target predicate (user_id IS NULL AND
  -- ownership_attestation_id IS NULL). Without this conjunct, a row carrying a
  -- stale attestation id with no user binding mints forever and burns every
  -- proof downstream with a misleading TARGET_ALREADY_CLAIMED; fail it here,
  -- at mint time, instead.
  IF v_target.user_id IS NULL AND v_target.ownership_attestation_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'That player profile is already claimed'
      USING ERRCODE = '22023', DETAIL = 'TARGET_ALREADY_CLAIMED';
  END IF;

  FOR v_attempt IN 1..8 LOOP
    v_code := 'PP6240-' || upper(encode(extensions.gen_random_bytes(16), 'hex'));
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.player_invite_codes AS invite
      WHERE invite.code = v_code
    );
  END LOOP;
  IF EXISTS (
    SELECT 1 FROM public.player_invite_codes AS invite
    WHERE invite.code = v_code
  ) THEN
    RAISE EXCEPTION 'Could not allocate a unique proof code'
      USING ERRCODE = '40001', DETAIL = 'MINT_CODE_COLLISION';
  END IF;

  INSERT INTO public.player_invite_codes (
    id, code, player_id, display_name, guild_code,
    created_by, created_at, expires_at
  ) VALUES (
    v_invite_id, v_code, v_target.player_id, v_target.display_name,
    v_target.guild_code, p_subject, clock_timestamp(), v_expires_at
  );

  -- The mint receipt. It carries the digest (the invite row has nowhere to put
  -- one) and is the second discriminator consumption requires.
  INSERT INTO public.player_claim_audit (
    user_id, player_id, guild_code, source_path, outcome, details
  ) VALUES (
    p_subject, v_target.player_id, v_target.guild_code,
    'profile/change-player-id/mint', 'success',
    jsonb_build_object(
      'action', 'mint_possession_proof',
      'invite_id', v_invite_id::text,
      'target_mapping_id', v_target.id,
      'upstream_digest', p_upstream_digest,
      'expires_at', v_expires_at
    )
  );

  RETURN v_invite_id;
END
$_$;

ALTER FUNCTION public.mint_player_possession_invite(p_subject uuid, p_player_id text, p_upstream_digest text) OWNER TO postgres;

CREATE FUNCTION public.notify_capped_players() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_guild_code TEXT;
  v_display_name TEXT;
  v_cluster_code TEXT;
  v_capped_count INT;
  v_webhook_url TEXT;
BEGIN
  -- Only process if last_sync_tokens changed to 3 (capped)
  IF NEW.last_sync_tokens = 3 AND (OLD.last_sync_tokens IS NULL OR OLD.last_sync_tokens < 3) THEN
    -- Get guild info
    SELECT gc.cluster_code
    INTO v_cluster_code
    FROM guild_config gc
    WHERE gc.guild_code = NEW.guild_code
    LIMIT 1;

    -- Check how many players are now capped in this guild
    SELECT COUNT(*)
    INTO v_capped_count
    FROM player_mapping pm
    WHERE pm.guild_code = NEW.guild_code
    AND pm.is_current = true
    AND pm.last_sync_tokens = 3;

    -- Get the webhook URL for this guild
    SELECT webhook_url
    INTO v_webhook_url
    FROM webhook_config
    WHERE guild_code = NEW.guild_code
    AND webhook_type = 'gr_availability'
    AND enabled = true
    LIMIT 1;

    -- If we have a webhook and this is a significant event
    IF v_webhook_url IS NOT NULL THEN
      -- Insert a notification record (to be processed by edge function)
      INSERT INTO token_cap_notifications (
        player_id,
        display_name,
        guild_code,
        cluster_code,
        capped_at,
        total_capped_in_guild,
        notification_sent
      ) VALUES (
        NEW.player_id,
        NEW.display_name,
        NEW.guild_code,
        v_cluster_code,
        NOW(),
        v_capped_count,
        false
      );

      -- Notify edge function via pg_notify (optional - for real-time processing)
      PERFORM pg_notify('player_capped', json_build_object(
        'player_id', NEW.player_id,
        'display_name', NEW.display_name,
        'guild_code', NEW.guild_code,
        'cluster_code', v_cluster_code,
        'capped_count', v_capped_count
      )::text);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION public.notify_capped_players() OWNER TO postgres;

CREATE FUNCTION public.notify_season_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    last_known_season INTEGER;
    new_season INTEGER;
BEGIN
    -- Only check for season changes on battle inserts
    IF NEW."damageType" = 'Battle' AND NEW."Guild" NOT IN ('TEST', 'EOT', 'TBD') THEN
        -- Get the current max season before this insert
        SELECT COALESCE(MAX(season::integer), 0) INTO last_known_season
        FROM votlw_winners
        WHERE season ~ '^\d+$';

        new_season := NEW."Season"::integer;

        -- If we've moved to a season 2+ higher than last VOTLW calculation
        -- it means the previous season is complete and needs VOTLW calculation
        IF new_season > last_known_season + 1 THEN
            -- Log that VOTLW calculation is needed for the completed season
            INSERT INTO public.system_logs (
                log_type,
                message,
                metadata,
                created_at
            ) VALUES (
                'votlw_needed',
                format('Season %s is complete, VOTLW calculation needed', (new_season - 1)::text),
                jsonb_build_object(
                    'completed_season', new_season - 1,
                    'current_season', new_season,
                    'last_calculated', last_known_season
                ),
                NOW()
            ) ON CONFLICT DO NOTHING;
        END IF;
    END IF;

    RETURN NEW;
END;
$_$;

ALTER FUNCTION public.notify_season_change() OWNER TO postgres;

CREATE FUNCTION public.notify_unmapped_entity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  webhook_url TEXT;
  discord_payload JSONB;
  notification_type TEXT;
  embed_title TEXT;
  embed_description TEXT;
  embed_color INTEGER;
BEGIN
  -- Get the Discord webhook URL from database settings
  webhook_url := current_setting('app.settings.discord_webhook_url');

  -- Check if this is an unmapped player or boss notification
  IF TG_ARGV[0] = 'player' THEN
    notification_type := 'Unmapped Player';
    embed_title := 'Unmapped Player Detected in ' || NEW."Guild";
    embed_description := 'An unmapped player UUID has been detected:' || E'\n\n' ||
                      'Guild: ' || NEW."Guild" || E'\n' ||
                      'Player UUID: ' || NEW."displayName" || E'\n\n' ||
                      'Please add this player to the player_mapping table.';
    embed_color := 15158332; -- Red color in decimal
  ELSE
    notification_type := 'Unmapped Boss';
    embed_title := 'Unmapped Boss Detected';
    embed_description := 'An unmapped boss has been detected:' || E'\n\n' ||
                      'Boss Type: ' || NEW."boss_type" || E'\n' ||
                      'Encounter Index: ' || NEW."encounter_index" || E'\n' ||
                      'Auto-generated Name: ' || NEW."boss_name" || E'\n\n' ||
                      'Please review and update this boss in the boss_mapping table.';
    embed_color := 3447003; -- Blue color in decimal
  END IF;

  -- Construct the Discord webhook payload
  discord_payload := jsonb_build_object(
    'username', 'Tacticus Database Monitor',
    'embeds', jsonb_build_array(
      jsonb_build_object(
        'title', embed_title,
        'description', embed_description,
        'color', embed_color,
        'footer', jsonb_build_object(
          'text', 'Tacticus Analytics - ' || to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
        )
      )
    )
  );

  -- Send the webhook to Discord
  PERFORM net.http_post(
    url := webhook_url,
    headers := jsonb_build_object('Content-Type', 'application/json'),
    body := discord_payload::text
  );

  -- For audit purposes, log the notification
  INSERT INTO notification_log (
    notification_type,
    entity_id,
    guild,
    message,
    created_at
  ) VALUES (
    notification_type,
    CASE WHEN TG_ARGV[0] = 'player' THEN NEW."displayName" ELSE NEW."boss_type" || '_' || NEW."encounter_index" END,
    CASE WHEN TG_ARGV[0] = 'player' THEN NEW."Guild" ELSE NULL END,
    embed_description,
    now()
  );

  RETURN NEW;
END;
$$;

ALTER FUNCTION public.notify_unmapped_entity() OWNER TO postgres;

