CREATE FUNCTION public.prepare_discord_identity_unlink() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_identity_count integer;
  v_identity_id uuid;
  v_identity_provider_id text;
  v_identity_updated_at timestamptz;
  v_mapping_count integer;
  v_attestation_id uuid;
  v_generation bigint;
  v_unlink_id uuid := gen_random_uuid();
  v_relink_nonce uuid := gen_random_uuid();
  v_cleared integer;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(6208, hashtext(v_user_id::text));

  SELECT count(*),
         (array_agg(identity.id ORDER BY identity.id))[1],
         (array_agg(identity.provider_id ORDER BY identity.id))[1],
         (array_agg(identity.updated_at ORDER BY identity.id))[1]
  INTO v_identity_count, v_identity_id, v_identity_provider_id,
       v_identity_updated_at
  FROM auth.identities AS identity
  WHERE identity.user_id = v_user_id AND identity.provider = 'discord';
  IF v_identity_count > 1 THEN
    RAISE EXCEPTION 'Discord identity is ambiguous; unlink remains fail closed'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*),
         (array_agg(mapping.ownership_attestation_id ORDER BY mapping.id))[1]
  INTO v_mapping_count, v_attestation_id
  FROM public.player_mapping AS mapping
  WHERE mapping.is_current IS TRUE
    AND mapping.user_id = v_user_id
    AND mapping.ownership_attestation_id IS NOT NULL;
  IF v_mapping_count > 1 THEN
    RAISE EXCEPTION 'Player ownership is ambiguous; unlink remains fail closed'
      USING ERRCODE = '55000';
  END IF;

  SELECT coalesce(max(pending.generation), 0) + 1
  INTO v_generation
  FROM public.player_identity_discord_unlink_pending AS pending
  WHERE pending.subject_user_id = v_user_id;

  INSERT INTO public.player_identity_discord_unlink_pending (
    id, subject_user_id, generation, ownership_attestation_id,
    prior_auth_identity_id, prior_provider_id_sha256,
    prior_identity_updated_at, relink_nonce_sha256
  ) VALUES (
    v_unlink_id, v_user_id, v_generation, v_attestation_id,
    v_identity_id,
    CASE WHEN v_identity_provider_id IS NULL THEN NULL ELSE encode(
      extensions.digest(convert_to(v_identity_provider_id, 'UTF8'), 'sha256'),
      'hex'
    ) END,
    v_identity_updated_at,
    encode(extensions.digest(convert_to(v_relink_nonce::text, 'UTF8'), 'sha256'),
           'hex')
  );

  UPDATE public.player_mapping AS mapping
  SET discord_user_id = NULL,
      discord_username = NULL,
      updated_at = clock_timestamp()
  WHERE mapping.user_id = v_user_id
    AND (mapping.discord_user_id IS NOT NULL
         OR mapping.discord_username IS NOT NULL);
  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  UPDATE auth.users AS target
  SET raw_user_meta_data = coalesce(target.raw_user_meta_data, '{}'::jsonb)
    - 'discord_user_id' - 'discord_username' - 'discord_synced'
  WHERE target.id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'unlink_id', v_unlink_id,
    'relink_nonce', v_relink_nonce,
    'generation', v_generation,
    'cleared_mappings', v_cleared,
    'provider_unlink_required', v_identity_count = 1,
    'stale_sync_blocked', true
  );
END
$$;

ALTER FUNCTION public.prepare_discord_identity_unlink() OWNER TO postgres;

CREATE FUNCTION public.preserve_player_cluster_on_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.cluster_code IS NOT NULL AND NEW.cluster_code IS NULL THEN
    NEW.cluster_code := OLD.cluster_code;
  END IF;
  IF OLD.cluster_id IS NOT NULL AND NEW.cluster_id IS NULL THEN
    NEW.cluster_id := OLD.cluster_id;
  END IF;
  RETURN NEW;
END
$$;

ALTER FUNCTION public.preserve_player_cluster_on_sync() OWNER TO postgres;

CREATE FUNCTION public.prevent_cluster_authority_rewrite() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_auth_uid uuid := auth.uid();
  v_is_service boolean := current_user IN (
    'service_role',
    'postgres',
    'supabase_admin'
  );
BEGIN
  IF v_is_service THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required for cluster authority changes'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.created_by IS DISTINCT FROM v_auth_uid THEN
      RAISE EXCEPTION 'A cluster creator must be the authenticated user'
        USING ERRCODE = '42501';
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id
      OR NEW.cluster_code IS DISTINCT FROM OLD.cluster_code
      OR NEW.created_by IS DISTINCT FROM OLD.created_by
    THEN
      RAISE EXCEPTION 'cluster identity and ownership are immutable to end users'
        USING ERRCODE = '42501';
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.created_by IS DISTINCT FROM v_auth_uid THEN
      RAISE EXCEPTION 'Only the cluster creator may delete a cluster'
        USING ERRCODE = '42501';
    END IF;
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION public.prevent_cluster_authority_rewrite() OWNER TO postgres;

CREATE FUNCTION public.prevent_independent_cluster_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Only prevent the literal string "INDEPENDENT"
    -- Allow NULL cluster_code for truly independent guilds
    IF NEW.cluster_code IS NOT NULL AND UPPER(TRIM(NEW.cluster_code)) = 'INDEPENDENT' THEN
        RAISE EXCEPTION 'Cluster code cannot be set to "INDEPENDENT". Use NULL for independent guilds or specify a valid cluster code.';
    END IF;

    RETURN NEW;
END;
$$;

ALTER FUNCTION public.prevent_independent_cluster_code() OWNER TO postgres;

CREATE FUNCTION public.prevent_privilege_column_self_escalation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_service boolean := current_user IN (
    'service_role',
    'postgres',
    'supabase_admin'
  );
BEGIN
  IF v_is_service THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'player_mapping rows may only be created by server authority'
      USING ERRCODE = '42501';
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'player_mapping authority rows may only be deleted by server authority'
      USING ERRCODE = '42501';
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id
      OR NEW.player_id IS DISTINCT FROM OLD.player_id
      OR NEW.user_id IS DISTINCT FROM OLD.user_id
    THEN
      RAISE EXCEPTION 'player_mapping identity may only be modified by server authority'
        USING ERRCODE = '42501';
    END IF;

    IF NEW.guild_code IS DISTINCT FROM OLD.guild_code
      OR NEW.cluster_code IS DISTINCT FROM OLD.cluster_code
      OR NEW.cluster_id IS DISTINCT FROM OLD.cluster_id
      OR NEW.is_current IS DISTINCT FROM OLD.is_current
      OR NEW.is_active IS DISTINCT FROM OLD.is_active
      OR NEW.protected IS DISTINCT FROM OLD.protected
    THEN
      RAISE EXCEPTION 'player_mapping membership may only be modified by server authority'
        USING ERRCODE = '42501';
    END IF;

    IF NEW.is_app_admin IS DISTINCT FROM OLD.is_app_admin THEN
      RAISE EXCEPTION 'is_app_admin may only be modified by server authority'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.role IS DISTINCT FROM OLD.role THEN
      RAISE EXCEPTION 'role may only be modified by server authority'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.patreon_user_id IS DISTINCT FROM OLD.patreon_user_id THEN
      RAISE EXCEPTION 'patreon_user_id may only be modified by server authority'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION public.prevent_privilege_column_self_escalation() OWNER TO postgres;

CREATE FUNCTION public.process_cap_notifications(p_guild_code text DEFAULT NULL::text) RETURNS TABLE(guild_code text, capped_players jsonb, notification_count integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH pending_notifications AS (
    SELECT
      tcn.guild_code,
      jsonb_agg(
        jsonb_build_object(
          'player_id', tcn.player_id,
          'display_name', tcn.display_name,
          'capped_at', tcn.capped_at
        ) ORDER BY tcn.capped_at
      ) as players,
      COUNT(*) as count
    FROM token_cap_notifications tcn
    WHERE tcn.notification_sent = false
    AND (p_guild_code IS NULL OR tcn.guild_code = p_guild_code)
    GROUP BY tcn.guild_code
  )
  SELECT
    pn.guild_code,
    pn.players,
    pn.count::int
  FROM pending_notifications pn;

  -- Mark notifications as sent
  UPDATE token_cap_notifications
  SET notification_sent = true,
      sent_at = NOW()
  WHERE notification_sent = false
  AND (p_guild_code IS NULL OR token_cap_notifications.guild_code = p_guild_code);
END;
$$;

ALTER FUNCTION public.process_cap_notifications(p_guild_code text) OWNER TO postgres;

CREATE FUNCTION public.project_token_snapshot(p_count integer, p_next_seconds integer, p_snapshot_at timestamp with time zone, p_spends timestamp with time zone[], p_now timestamp with time zone, p_cap integer, p_regen_secs bigint) RETURNS TABLE(available integer, next_in_seconds integer)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  pts_now_secs bigint;
  pts_snap_secs bigint;
  pts_count int;
  pts_refresh bigint;      -- NULL while paused at cap with no spend yet
  pts_spend_ts timestamptz;
  pts_spend_secs bigint;
  pts_recharged int;
  pts_prev_count int;
  pts_elapsed bigint;
BEGIN
  -- Null-safe single-row contract: callers cross-join laterally per member,
  -- so the helper must always emit exactly one row.
  IF p_count IS NULL OR p_snapshot_at IS NULL OR p_now IS NULL
     OR p_cap IS NULL OR p_cap <= 0
     OR p_regen_secs IS NULL OR p_regen_secs <= 0 THEN
    available := NULL;
    next_in_seconds := NULL;
    RETURN NEXT;
    RETURN;
  END IF;

  pts_now_secs := EXTRACT(EPOCH FROM p_now)::bigint;
  pts_snap_secs := EXTRACT(EPOCH FROM p_snapshot_at)::bigint;
  pts_count := LEAST(p_cap, GREATEST(0, p_count));

  IF pts_count >= p_cap THEN
    -- Capped at snapshot: regen is paused, no refresh phase to seed.
    pts_refresh := NULL;
  ELSIF p_next_seconds IS NULL OR p_next_seconds <= 0 THEN
    -- Degenerate countdown below cap: treat the timer as just started.
    pts_refresh := pts_snap_secs;
  ELSE
    -- Next token due at snapshot + p_next_seconds.
    pts_refresh := pts_snap_secs + p_next_seconds - p_regen_secs;
  END IF;

  FOR pts_spend_ts IN
    SELECT u.spend_ts
    FROM unnest(p_spends) AS u(spend_ts)
    WHERE u.spend_ts IS NOT NULL
      AND u.spend_ts > p_snapshot_at
    ORDER BY u.spend_ts ASC
  LOOP
    pts_spend_secs := EXTRACT(EPOCH FROM pts_spend_ts)::bigint;

    -- Regen up to the spend time (same accrual form as the Phase 2 replay).
    IF pts_count < p_cap THEN
      pts_recharged := GREATEST(
        0,
        FLOOR((pts_spend_secs - pts_refresh)::numeric / p_regen_secs)
      )::int;

      IF pts_recharged + pts_count >= p_cap THEN
        pts_count := p_cap;
        pts_refresh := pts_spend_secs;
      ELSE
        pts_count := pts_count + pts_recharged;
        pts_refresh := pts_refresh + (pts_recharged::bigint * p_regen_secs);
      END IF;
    END IF;

    -- Spend one. Spending never resets the timer; a spend FROM cap starts it.
    pts_prev_count := pts_count;
    pts_count := GREATEST(0, pts_count - 1);
    IF pts_prev_count = p_cap THEN
      pts_refresh := pts_spend_secs;
    END IF;
  END LOOP;

  -- Regen the walked state to p_now.
  IF pts_count < p_cap AND pts_refresh IS NOT NULL THEN
    pts_recharged := GREATEST(
      0,
      FLOOR((pts_now_secs - pts_refresh)::numeric / p_regen_secs)
    )::int;

    IF pts_recharged + pts_count >= p_cap THEN
      pts_count := p_cap;
      pts_refresh := pts_now_secs;
    ELSE
      pts_count := pts_count + pts_recharged;
      pts_refresh := pts_refresh + (pts_recharged::bigint * p_regen_secs);
    END IF;
  END IF;

  available := LEAST(p_cap, GREATEST(0, pts_count));

  IF available >= p_cap OR pts_refresh IS NULL THEN
    next_in_seconds := NULL;
  ELSE
    -- Clamp elapsed at 0 so a (pathological) future refresh anchor can never
    -- push the countdown past a full regen period.
    pts_elapsed := GREATEST(0, pts_now_secs - pts_refresh);
    next_in_seconds := (p_regen_secs - (pts_elapsed % p_regen_secs))::int;
  END IF;

  RETURN NEXT;
END;
$$;

ALTER FUNCTION public.project_token_snapshot(p_count integer, p_next_seconds integer, p_snapshot_at timestamp with time zone, p_spends timestamp with time zone[], p_now timestamp with time zone, p_cap integer, p_regen_secs bigint) OWNER TO postgres;

CREATE FUNCTION public.purge_old_seasons(retention integer DEFAULT NULL::integer, min_season integer DEFAULT NULL::integer) RETURNS TABLE(deleted_eot_gr_data bigint, deleted_discord_tracking bigint, deleted_season_summary bigint, deleted_guild_snapshots bigint, deleted_votlw bigint, max_season integer, cutoff_season integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_max_season integer;
  v_cutoff integer;
  v_deleted_eot bigint := 0;
  v_deleted_discord bigint := 0;
  v_deleted_summary bigint := 0;
  v_deleted_snapshots bigint := 0;
  v_deleted_votlw bigint := 0;
BEGIN
  SELECT MAX("Season"::int)
    INTO v_max_season
  FROM "EOT_GR_data"
  WHERE "Season" ~ '^[0-9]+$';

  IF v_max_season IS NULL THEN
    RETURN QUERY SELECT 0::bigint, 0::bigint, 0::bigint, 0::bigint, 0::bigint, 0, 0;
    RETURN;
  END IF;

  -- Mode selection. min_season wins when both are provided. Both NULL = no-op.
  IF min_season IS NOT NULL THEN
    v_cutoff := min_season;
  ELSIF retention IS NOT NULL THEN
    v_cutoff := v_max_season - retention;
  ELSE
    -- No mode requested — explicit no-op.
    RETURN QUERY SELECT 0::bigint, 0::bigint, 0::bigint, 0::bigint, 0::bigint, v_max_season, NULL::integer;
    RETURN;
  END IF;

  -- Defensive: if the requested floor is >= max, nothing should be left
  -- behind. We refuse rather than wipe the table.
  IF v_cutoff >= v_max_season THEN
    RAISE NOTICE 'Refusing to purge: cutoff % >= max %; would empty the table.', v_cutoff, v_max_season;
    RETURN QUERY SELECT 0::bigint, 0::bigint, 0::bigint, 0::bigint, 0::bigint, v_max_season, v_cutoff;
    RETURN;
  END IF;

  IF v_cutoff < 0 THEN
    -- Sliding-window mode with retention >= max. No rows below 0; no-op.
    RETURN QUERY SELECT 0::bigint, 0::bigint, 0::bigint, 0::bigint, 0::bigint, v_max_season, v_cutoff;
    RETURN;
  END IF;

  RAISE NOTICE 'Purging seasons older than % (max: %, retention: %, min_season: %)',
    v_cutoff, v_max_season, retention, min_season;

  WITH deleted AS (
    DELETE FROM "EOT_GR_data"
    WHERE "Season" ~ '^[0-9]+$'
      AND "Season"::int < v_cutoff
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_deleted_eot FROM deleted;
  RAISE NOTICE 'Deleted % records from EOT_GR_data', v_deleted_eot;

  WITH deleted AS (
    DELETE FROM discord_message_tracking
    WHERE season ~ '^[0-9]+$'
      AND season::int < v_cutoff
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_deleted_discord FROM deleted;

  WITH deleted AS (
    DELETE FROM season_summary_tracking
    WHERE season ~ '^[0-9]+$'
      AND season::int < v_cutoff
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_deleted_summary FROM deleted;

  WITH deleted AS (
    DELETE FROM public_guild_snapshots
    WHERE season < v_cutoff
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_deleted_snapshots FROM deleted;

  WITH deleted AS (
    DELETE FROM votlw_winners
    WHERE season ~ '^[0-9]+$'
      AND season::int < v_cutoff
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_deleted_votlw FROM deleted;

  BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_public_stats;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Could not refresh mv_public_stats: %', SQLERRM;
  END;

  BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_season_summary;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Could not refresh mv_season_summary: %', SQLERRM;
  END;

  RETURN QUERY SELECT v_deleted_eot, v_deleted_discord, v_deleted_summary, v_deleted_snapshots, v_deleted_votlw, v_max_season, v_cutoff;
END;
$_$;

ALTER FUNCTION public.purge_old_seasons(retention integer, min_season integer) OWNER TO postgres;

CREATE FUNCTION public.qualifying_sweep_count(sweep_damages numeric[], threshold numeric) RETURNS integer
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT coalesce(count(*)::integer, 0) FROM unnest(sweep_damages) s WHERE s >= threshold;
$$;

ALTER FUNCTION public.qualifying_sweep_count(sweep_damages numeric[], threshold numeric) OWNER TO postgres;

CREATE FUNCTION public.qualifying_sweep_sum(sweep_damages numeric[], threshold numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT coalesce(sum(s), 0) FROM unnest(sweep_damages) s WHERE s >= threshold;
$$;

ALTER FUNCTION public.qualifying_sweep_sum(sweep_damages numeric[], threshold numeric) OWNER TO postgres;

CREATE FUNCTION public.queue_proactive_token_notifications(p_guild_code text DEFAULT NULL::text, p_season text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(guild_code text, season text, queued_discord integer, queued_in_app integer, queued_total integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_guild_code text;
  v_season text;
  v_queued_discord integer;
  v_queued_in_app integer;
  v_queued_total integer;
begin
  for v_guild_code in
    select gc.guild_code
    from public.guild_config gc
    where (p_guild_code is null or gc.guild_code = p_guild_code)
      and exists (
        select 1
        from public.player_mapping pm
        where pm.guild_code = gc.guild_code
          and pm.is_current = true
      )
    order by gc.guild_code
  loop
    if p_season is null then
      select e."Season"
      into v_season
      from public."EOT_GR_data" e
      where e."Guild" = v_guild_code
      order by e."timestamp" desc nulls last, e."startedOn" desc nulls last
      limit 1;
    else
      v_season := p_season;
    end if;

    if v_season is null then
      continue;
    end if;

    with token_state as (
      select *
      from public.get_player_token_state(v_guild_code, v_season, null, null)
      where player_id is not null
    ),
    channel_matrix as (
      select
        ts.player_id,
        ts.display_name,
        ts.tokens_available,
        ts.token_next_in_seconds,
        ts.data_source,
        ts.is_capped,
        ch.channel
      from token_state ts
      cross join (values ('discord'::text), ('in_app'::text)) as ch(channel)
    ),
    configured as (
      select
        cm.player_id,
        cm.display_name,
        cm.tokens_available,
        cm.token_next_in_seconds,
        cm.data_source,
        cm.is_capped,
        cm.channel as delivery_channel,
        pref.preference_id,
        pref.notify_on_capped,
        pref.notify_on_near_cap,
        pref.near_cap_threshold_seconds,
        greatest(pref.dedupe_window_seconds, 300) as dedupe_window_seconds,
        pref.discord_channel_id
      from channel_matrix cm
      join lateral public.get_effective_token_notification_preference(
        v_guild_code,
        cm.player_id,
        cm.channel
      ) pref on pref.enabled = true
    ),
    candidate_events as (
      select
        v_guild_code as guild_code,
        v_season as season,
        c.player_id,
        c.display_name,
        c.delivery_channel,
        c.preference_id,
        c.tokens_available,
        c.token_next_in_seconds,
        c.data_source,
        c.dedupe_window_seconds,
        c.discord_channel_id,
        'capped'::text as notification_type
      from configured c
      where c.notify_on_capped = true
        and (c.is_capped = true or c.tokens_available >= 3)
      union all
      select
        v_guild_code as guild_code,
        v_season as season,
        c.player_id,
        c.display_name,
        c.delivery_channel,
        c.preference_id,
        c.tokens_available,
        c.token_next_in_seconds,
        c.data_source,
        c.dedupe_window_seconds,
        c.discord_channel_id,
        'near_cap'::text as notification_type
      from configured c
      where c.notify_on_near_cap = true
        and c.tokens_available = 2
        and c.token_next_in_seconds is not null
        and c.token_next_in_seconds <= c.near_cap_threshold_seconds
    ),
    normalized as (
      select
        ce.*,
        to_timestamp(
          floor(extract(epoch from p_now) / ce.dedupe_window_seconds)
          * ce.dedupe_window_seconds
        ) as dedupe_window_started_at
      from candidate_events ce
    ),
    inserted as (
      insert into public.token_notification_events (
        guild_code,
        season,
        player_id,
        display_name,
        notification_type,
        delivery_channel,
        tokens_available,
        token_next_in_seconds,
        data_source,
        preference_id,
        dedupe_window_started_at,
        dedupe_window_seconds,
        dedupe_key,
        payload
      )
      select
        n.guild_code,
        n.season,
        n.player_id,
        n.display_name,
        n.notification_type,
        n.delivery_channel,
        n.tokens_available,
        n.token_next_in_seconds,
        n.data_source,
        n.preference_id,
        n.dedupe_window_started_at,
        n.dedupe_window_seconds,
        concat_ws(
          '|',
          n.guild_code,
          n.season,
          n.player_id,
          n.delivery_channel,
          n.notification_type,
          extract(epoch from n.dedupe_window_started_at)::bigint::text
        ) as dedupe_key,
        jsonb_build_object(
          'guild_code', n.guild_code,
          'season', n.season,
          'player_id', n.player_id,
          'display_name', n.display_name,
          'notification_type', n.notification_type,
          'delivery_channel', n.delivery_channel,
          'tokens_available', n.tokens_available,
          'token_next_in_seconds', n.token_next_in_seconds,
          'data_source', n.data_source,
          'discord_channel_id', n.discord_channel_id,
          'generated_at', p_now
        ) as payload
      from normalized n
      on conflict (dedupe_key) do nothing
      returning delivery_channel
    )
    select
      coalesce(count(*) filter (where delivery_channel = 'discord'), 0)::integer,
      coalesce(count(*) filter (where delivery_channel = 'in_app'), 0)::integer,
      coalesce(count(*), 0)::integer
    into v_queued_discord, v_queued_in_app, v_queued_total
    from inserted;

    guild_code := v_guild_code;
    season := v_season;
    queued_discord := coalesce(v_queued_discord, 0);
    queued_in_app := coalesce(v_queued_in_app, 0);
    queued_total := coalesce(v_queued_total, 0);

    return next;
  end loop;
end;
$$;

ALTER FUNCTION public.queue_proactive_token_notifications(p_guild_code text, p_season text, p_now timestamp with time zone) OWNER TO postgres;

CREATE FUNCTION public.queue_token_burn_notifications(p_guild_code text DEFAULT NULL::text, p_season text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(guild_code text, season text, queued_discord integer, queued_in_app integer, queued_total integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_guild_code text;
  v_season text;
begin
  for v_guild_code in
    select gc.guild_code
    from public.guild_config gc
    where (p_guild_code is null or gc.guild_code = p_guild_code)
      and exists (
        select 1
        from public.player_mapping pm
        where pm.guild_code = gc.guild_code
          and pm.is_current = true
      )
    order by gc.guild_code
  loop
    if p_season is null then
      select e."Season"
      into v_season
      from public."EOT_GR_data" e
      where e."Guild" = v_guild_code
      order by e."timestamp" desc nulls last, e."startedOn" desc nulls last
      limit 1;
    else
      v_season := p_season;
    end if;

    if v_season is null then
      continue;
    end if;

    -- WI-3990: this function now ONLY maintains public.token_burn_state via
    -- record_token_burn_state (burn stats feed /player-performance and
    -- get_player_token_state.burned_tokens). The token_notification_events
    -- inserts were removed with the WI-079 Discord dispatcher retirement
    -- (dead since 2026-06-16); the per-user DM lane replaces that delivery.
    perform 1
    from (
      select *
      from public.get_player_token_state(v_guild_code, v_season, null, null)
      where player_id is not null
    ) ts
    cross join lateral public.record_token_burn_state(
      p_guild_code := v_guild_code,
      p_season := v_season,
      p_player_id := ts.player_id,
      p_display_name := ts.display_name,
      p_tokens_available := ts.tokens_available,
      p_token_next_in_seconds := ts.token_next_in_seconds,
      p_now := p_now
    ) bs;

    guild_code := v_guild_code;
    season := v_season;
    queued_discord := 0;
    queued_in_app := 0;
    queued_total := 0;

    return next;
  end loop;
end;
$$;

ALTER FUNCTION public.queue_token_burn_notifications(p_guild_code text, p_season text, p_now timestamp with time zone) OWNER TO postgres;

CREATE FUNCTION public.reap_stuck_work_jobs(p_timeout_seconds integer DEFAULT 600) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  WITH reaped AS (
    UPDATE public.work_queue
    SET status      = CASE
                        WHEN attempts >= max_attempts THEN 'dead'
                        ELSE 'pending'
                      END,
        claimed_by  = CASE
                        WHEN attempts >= max_attempts THEN claimed_by
                        ELSE NULL
                      END,
        claimed_at  = CASE
                        WHEN attempts >= max_attempts THEN claimed_at
                        ELSE NULL
                      END,
        started_at  = NULL,
        completed_at = CASE
                        WHEN attempts >= max_attempts THEN now()
                        ELSE NULL
                      END,
        error       = COALESCE(error, '') || ' [reaped at ' || now()::text || ']',
        updated_at  = now()
    WHERE status = 'processing'
      AND claimed_at < now() - make_interval(secs => p_timeout_seconds)
    RETURNING id
  )
  SELECT COUNT(*)::int INTO v_count FROM reaped;
  RETURN v_count;
END;
$$;

ALTER FUNCTION public.reap_stuck_work_jobs(p_timeout_seconds integer) OWNER TO postgres;

CREATE FUNCTION public.recalculate_sync_tiers() RETURNS TABLE(guild_code text, old_tier text, new_tier text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH guild_activity AS (
    SELECT
      gc.guild_code,
      gc.sync_tier as current_tier,
      count(*) FILTER (WHERE pm.last_active_at > NOW() - INTERVAL '7 days') as visitors_7d,
      count(*) FILTER (WHERE pm.last_active_at > NOW() - INTERVAL '30 days') as visitors_30d
    FROM guild_config gc
    LEFT JOIN player_mapping pm ON pm.guild_code = gc.guild_code AND pm.is_current = true
    WHERE gc.enabled = true
    GROUP BY gc.guild_code, gc.sync_tier
  ),
  computed AS (
    SELECT
      ga.guild_code,
      ga.current_tier,
      CASE
        WHEN ga.visitors_7d >= 1 THEN 'active'
        WHEN ga.visitors_30d >= 1 THEN 'warm'
        ELSE 'dormant'
      END as computed_tier
    FROM guild_activity ga
  )
  UPDATE guild_config gc
  SET sync_tier = c.computed_tier, updated_at = NOW()
  FROM computed c
  WHERE gc.guild_code = c.guild_code AND gc.sync_tier IS DISTINCT FROM c.computed_tier
  RETURNING gc.guild_code, c.current_tier, c.computed_tier;
END;
$$;

ALTER FUNCTION public.recalculate_sync_tiers() OWNER TO postgres;

CREATE FUNCTION public.recommend_boss_teams(p_future_season text, p_boss_types text[]) RETURNS TABLE(boss_type text, boss_name text, player_name text, original_guild text, performance_score numeric, avg_damage numeric, best_season text, seasons_engaged integer, total_tokens_used integer, recommendation_strength text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH boss_performances AS (
        -- Gather player performance across all seasons for the specified boss types
        SELECT
            bm.boss_type,
            bm.boss_name,
            bl.player_name,
            bl.original_guild,
            bl.rank,
            bl.avg_damage,
            bl.tokens_used,
            bl.score AS performance_score,
            bl.season,
            -- Calculate a recency score (more recent seasons have higher weight)
            1.0 / (1.0 + (CAST(p_future_season AS INTEGER) - CAST(bl.season AS INTEGER))) AS recency_score
        FROM
            eot_boss_leaderboard bl
        JOIN
            boss_mapping bm ON bl.boss_id = bm.id
        WHERE
            bm.boss_type = ANY(p_boss_types)
            AND bl.tokens_used >= 2 -- Minimum requirement
    ),
    player_boss_stats AS (
        -- Aggregate player stats across seasons for each boss
        SELECT
            bp.boss_type,
            bp.boss_name,
            bp.player_name,
            bp.original_guild,
            -- Calculate weighted average score (more recent seasons have higher weight)
            SUM(bp.performance_score * bp.recency_score) / NULLIF(SUM(bp.recency_score), 0) AS weighted_score,
            AVG(bp.avg_damage) AS avg_damage_across_seasons,
            COUNT(DISTINCT bp.season)::INTEGER AS seasons_engaged,
            SUM(bp.tokens_used)::INTEGER AS total_tokens_used,
            MAX(bp.performance_score) AS best_performance_score,
            -- Find the season with the best performance
            (ARRAY_AGG(bp.season ORDER BY bp.performance_score DESC))[1] AS best_season,
            -- Calculate consistency score (lower variance is better)
            STDDEV(bp.performance_score) AS score_consistency,
            -- Calculate engagement score (how often they fight this boss)
            COUNT(DISTINCT bp.season)::DECIMAL /
                NULLIF((SELECT COUNT(DISTINCT ebl.season) FROM eot_boss_leaderboard ebl), 0) AS engagement_ratio
        FROM
            boss_performances bp
        GROUP BY
            bp.boss_type, bp.boss_name, bp.player_name, bp.original_guild
    ),
    ranked_players AS (
        -- Rank players for each boss
        SELECT
            pbs.boss_type,
            pbs.boss_name,
            pbs.player_name,
            pbs.original_guild,
            pbs.weighted_score,
            pbs.avg_damage_across_seasons,
            pbs.seasons_engaged,
            pbs.total_tokens_used,
            pbs.best_performance_score,
            pbs.best_season,
            pbs.score_consistency,
            pbs.engagement_ratio,
            -- Create a final recommendation score that considers:
            -- 1. Performance (50%)
            -- 2. Consistency (25%)
            -- 3. Engagement (25%)
            (
                COALESCE(pbs.weighted_score, 0) * 0.5 +
                (1.0 - COALESCE(pbs.score_consistency, 0)) * 0.25 +
                COALESCE(pbs.engagement_ratio, 0) * 0.25
            ) AS recommendation_score,
            -- Determine recommendation strength
            CASE
                WHEN COALESCE(pbs.weighted_score, 0) > 0.8 AND pbs.seasons_engaged > 1 THEN 'Strong'
                WHEN COALESCE(pbs.weighted_score, 0) > 0.7 OR pbs.seasons_engaged > 2 THEN 'Good'
                ELSE 'Moderate'
            END AS recommendation_strength,
            -- Rank within each boss
            ROW_NUMBER() OVER (
                PARTITION BY pbs.boss_type, pbs.boss_name
                ORDER BY
                    (COALESCE(pbs.weighted_score, 0) * 0.5 +
                     (1.0 - COALESCE(pbs.score_consistency, 0)) * 0.25 +
                     COALESCE(pbs.engagement_ratio, 0) * 0.25) DESC,
                    pbs.seasons_engaged DESC,
                    pbs.total_tokens_used DESC
            ) AS boss_rank
        FROM
            player_boss_stats pbs
    )
    SELECT
        rp.boss_type,
        rp.boss_name,
        rp.player_name,
        rp.original_guild,
        COALESCE(rp.weighted_score, 0) AS performance_score,
        rp.avg_damage_across_seasons AS avg_damage,
        rp.best_season,
        rp.seasons_engaged,
        rp.total_tokens_used,
        rp.recommendation_strength
    FROM
        ranked_players rp
    WHERE
        rp.boss_rank <= 6 -- Top 6 performers per boss
    ORDER BY
        rp.boss_type,
        rp.boss_name,
        rp.boss_rank;
END;
$$;

ALTER FUNCTION public.recommend_boss_teams(p_future_season text, p_boss_types text[]) OWNER TO postgres;

CREATE TABLE public.token_burn_state (
    id bigint NOT NULL,
    guild_code text NOT NULL,
    season text NOT NULL,
    player_id text,
    display_name text,
    burned_tokens integer DEFAULT 0 NOT NULL,
    time_over_cap_seconds integer DEFAULT 0 NOT NULL,
    last_over_cap_started_at timestamp with time zone,
    last_seen_tokens integer,
    last_seen_token_next_seconds integer,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_scale_factor='0.025');

ALTER TABLE ONLY public.token_burn_state FORCE ROW LEVEL SECURITY;

ALTER TABLE public.token_burn_state OWNER TO postgres;

CREATE FUNCTION public.record_token_burn_state(p_guild_code text, p_season text, p_player_id text, p_display_name text, p_tokens_available integer, p_token_next_in_seconds integer, p_now timestamp with time zone DEFAULT now()) RETURNS public.token_burn_state
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_now timestamptz := coalesce(p_now, now());
  v_regen_seconds integer := 12 * 60 * 60;
  v_max_tokens integer := 3;
  v_row public.token_burn_state;
  v_prev_over integer;
  v_new_over integer;
  v_max_over_seconds integer;
  v_elapsed integer := 0;
  v_start timestamptz;
  v_season_start_at timestamptz;
  v_season_end_at timestamptz;
  v_effective_now timestamptz;
  v_window_start timestamptz;
  v_season_is_closed boolean := false;
begin
  if p_guild_code is null or length(trim(p_guild_code)) = 0 then
    raise exception 'p_guild_code is required';
  end if;

  if p_season is null or length(trim(p_season)) = 0 then
    raise exception 'p_season is required';
  end if;

  if p_display_name is null and p_player_id is null then
    raise exception 'Either p_player_id or p_display_name is required';
  end if;

  -- Prefer explicit season boundaries seeded from LOKI timing when available.
  if to_regclass('public.season_calendar') is not null
     and p_season ~ '^\d+$' then
    select
      sc.starts_at,
      sc.ends_at
    into
      v_season_start_at,
      v_season_end_at
    from public.season_calendar sc
    where sc.season_id = p_season::integer
    limit 1;
  end if;

  -- Fallback: derive season start from observed battle data for this guild/season.
  if v_season_start_at is null then
    select min(d."startedOn")
    into v_season_start_at
    from public."EOT_GR_data" d
    where d."Guild" = p_guild_code
      and d."Season" = p_season
      and d."startedOn" is not null;
  end if;

  -- Fallback: derive season end from the first battle seen in the next season.
  if v_season_end_at is null
     and p_season ~ '^\d+$' then
    select min(d."startedOn")
    into v_season_end_at
    from public."EOT_GR_data" d
    where d."Guild" = p_guild_code
      and d."Season" = (p_season::integer + 1)::text
      and d."startedOn" is not null;

    if v_season_end_at is null then
      select min(d."startedOn")
      into v_season_end_at
      from public."EOT_GR_data" d
      where d."Season" = (p_season::integer + 1)::text
        and d."startedOn" is not null;
    end if;
  end if;

  if v_season_start_at is not null
     and v_season_end_at is not null
     and v_season_end_at < v_season_start_at then
    v_season_end_at := null;
  end if;

  -- Accrual computations are evaluated against a season-bounded clock.
  v_effective_now := v_now;
  if v_season_end_at is not null and v_effective_now > v_season_end_at then
    v_effective_now := v_season_end_at;
    v_season_is_closed := true;
  end if;
  if v_season_start_at is not null and v_effective_now < v_season_start_at then
    v_effective_now := v_season_start_at;
  end if;
  if v_season_start_at is not null then
    v_max_over_seconds := greatest(
      0,
      floor(extract(epoch from (v_effective_now - v_season_start_at)))::integer
    );
  else
    v_max_over_seconds := null;
  end if;

  perform pg_advisory_xact_lock(
    hashtext(concat_ws('|', p_guild_code, p_season, coalesce(p_player_id, p_display_name)))
  );

  if p_player_id is not null then
    insert into public.token_burn_state (
      guild_code,
      season,
      player_id,
      display_name,
      updated_at,
      created_at
    )
    values (
      p_guild_code,
      p_season,
      p_player_id,
      p_display_name,
      v_now,
      v_now
    )
    on conflict (guild_code, season, player_id) do update
      set display_name = coalesce(excluded.display_name, token_burn_state.display_name);
  else
    insert into public.token_burn_state (
      guild_code,
      season,
      player_id,
      display_name,
      updated_at,
      created_at
    )
    values (
      p_guild_code,
      p_season,
      null,
      p_display_name,
      v_now,
      v_now
    )
    on conflict do nothing;
  end if;

  select *
  into v_row
  from public.token_burn_state
  where guild_code = p_guild_code
    and season = p_season
    and (
      (p_player_id is not null and player_id = p_player_id)
      or (p_player_id is null and player_id is null and display_name = p_display_name)
    )
  order by updated_at desc, id desc
  limit 1
  for update;

  if not found then
    raise exception 'Unable to load token burn state row for guild %, season %, player %',
      p_guild_code,
      p_season,
      coalesce(p_player_id, p_display_name);
  end if;

  v_prev_over := coalesce(v_row.time_over_cap_seconds, 0);
  if v_max_over_seconds is not null then
    v_prev_over := least(v_prev_over, v_max_over_seconds);
  end if;

  if p_tokens_available is null then
    return v_row;
  end if;

  if p_tokens_available >= v_max_tokens then
    if v_row.last_over_cap_started_at is null then
      if not v_season_is_closed
         and p_token_next_in_seconds is not null
         and p_token_next_in_seconds between 0 and v_regen_seconds then
        v_start := v_now - make_interval(secs => greatest(0, v_regen_seconds - p_token_next_in_seconds));
      else
        -- Unknown/closed season countdown: avoid synthetic backfill.
        v_start := v_effective_now;
      end if;
    else
      v_start := v_row.last_over_cap_started_at;
    end if;

    if v_season_start_at is not null then
      v_start := greatest(v_start, v_season_start_at);
    end if;
    if v_season_end_at is not null then
      v_start := least(v_start, v_season_end_at);
    end if;

    if v_row.last_over_cap_started_at is null then
      v_elapsed := greatest(0, floor(extract(epoch from (v_effective_now - v_start)))::integer);
    else
      v_window_start := coalesce(v_row.updated_at, v_effective_now);
      if v_season_start_at is not null then
        v_window_start := greatest(v_window_start, v_season_start_at);
      end if;
      if v_season_end_at is not null then
        v_window_start := least(v_window_start, v_season_end_at);
      end if;
      v_elapsed := greatest(0, floor(extract(epoch from (v_effective_now - v_window_start)))::integer);
    end if;

    v_new_over := v_prev_over + v_elapsed;
    if v_max_over_seconds is not null then
      v_new_over := least(v_new_over, v_max_over_seconds);
    end if;

    update public.token_burn_state
    set
      display_name = coalesce(p_display_name, display_name),
      burned_tokens = floor(v_new_over::numeric / v_regen_seconds::numeric)::integer,
      time_over_cap_seconds = v_new_over,
      last_over_cap_started_at = v_start,
      last_seen_tokens = p_tokens_available,
      last_seen_token_next_seconds = p_token_next_in_seconds,
      updated_at = v_now
    where id = v_row.id
    returning * into v_row;
  else
    if v_row.last_over_cap_started_at is not null then
      v_window_start := coalesce(v_row.updated_at, v_effective_now);
      if v_season_start_at is not null then
        v_window_start := greatest(v_window_start, v_season_start_at);
      end if;
      if v_season_end_at is not null then
        v_window_start := least(v_window_start, v_season_end_at);
      end if;
      v_elapsed := greatest(0, floor(extract(epoch from (v_effective_now - v_window_start)))::integer);
      v_new_over := v_prev_over + v_elapsed;
      if v_max_over_seconds is not null then
        v_new_over := least(v_new_over, v_max_over_seconds);
      end if;
    else
      v_new_over := v_prev_over;
      if v_max_over_seconds is not null then
        v_new_over := least(v_new_over, v_max_over_seconds);
      end if;
    end if;

    update public.token_burn_state
    set
      display_name = coalesce(p_display_name, display_name),
      burned_tokens = floor(v_new_over::numeric / v_regen_seconds::numeric)::integer,
      time_over_cap_seconds = v_new_over,
      last_over_cap_started_at = null,
      last_seen_tokens = p_tokens_available,
      last_seen_token_next_seconds = p_token_next_in_seconds,
      updated_at = v_now
    where id = v_row.id
    returning * into v_row;
  end if;

  return v_row;
end;
$_$;

ALTER FUNCTION public.record_token_burn_state(p_guild_code text, p_season text, p_player_id text, p_display_name text, p_tokens_available integer, p_token_next_in_seconds integer, p_now timestamp with time zone) OWNER TO postgres;

CREATE FUNCTION public.refresh_all_materialized_views() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_duration INTERVAL;
BEGIN
    v_start_time := clock_timestamp();

    -- Refresh in order of dependency
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_latest_season;
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_public_stats;
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_global_leaderboard;
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_season_summary;
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_boss_performance;

    v_end_time := clock_timestamp();
    v_duration := v_end_time - v_start_time;

    RETURN format('All materialized views refreshed in %s', v_duration);
END;
$$;

ALTER FUNCTION public.refresh_all_materialized_views() OWNER TO postgres;

CREATE FUNCTION public.refresh_cluster_averages() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
      BEGIN
        REFRESH MATERIALIZED VIEW CONCURRENTLY mv_cluster_boss_averages;
      END;
      $$;

ALTER FUNCTION public.refresh_cluster_averages() OWNER TO postgres;

CREATE FUNCTION public.refresh_cluster_rankings() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_last_refreshed_at timestamptz;
BEGIN
  -- Do not queue PostgREST connections behind a refresh already in progress.
  IF NOT pg_try_advisory_xact_lock(
    hashtext('refresh_cluster_rankings')
  ) THEN
    RETURN;
  END IF;

  SELECT state.last_refreshed_at
  INTO v_last_refreshed_at
  FROM public.cluster_rankings_refresh_state AS state
  WHERE state.singleton;

  -- Every caller shares this durable window, including Edge Runtime replicas
  -- that cannot share the Next.js Redis/app-cache acquisition.
  IF v_last_refreshed_at IS NOT NULL
     AND v_last_refreshed_at >= clock_timestamp() - interval '15 minutes' THEN
    RETURN;
  END IF;

  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_cluster_season_rankings;

  INSERT INTO public.cluster_rankings_refresh_state (
    singleton,
    last_refreshed_at
  ) VALUES (
    true,
    clock_timestamp()
  )
  ON CONFLICT (singleton) DO UPDATE
  SET last_refreshed_at = EXCLUDED.last_refreshed_at;
END;
$$;

ALTER FUNCTION public.refresh_cluster_rankings() OWNER TO postgres;

