CREATE FUNCTION public.refresh_guild_snapshots(p_season integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
    v_season integer;
begin
    if p_season is null then
        select coalesce(max("Season"::integer), 1)
          into v_season
          from "EOT_GR_data"
         where "Season" is not null
           and "Season" ~ '^[0-9]+$';
    else
        v_season := p_season;
    end if;

    -- Clear all data for fresh refresh
    delete from public_guild_snapshots;

    with guild_stats as (
        select
            gc.guild_code,
            gc.display_name as guild_name,
            gc.cluster_code,
            cc.display_name as cluster_name,
            v_season as season,
            gc."GR_Ranking"::integer as rank,
            count(distinct d."encounterId")     as total_battles,
            count(distinct d."displayName")  as active_players,
            coalesce(sum(d."damageDealt"),0) as total_damage,
            case when count(distinct d."displayName") > 0
                 then coalesce(sum(d."damageDealt"),0) / count(distinct d."displayName")
                 else 0 end                  as average_damage,
            case when count(d."encounterId") > 0
                 then coalesce(sum(d."damageDealt"),0) / count(d."encounterId")
                 else 0 end                  as avg_damage_per_battle
        from guild_config gc
        left join cluster_config cc on gc.cluster_code = cc.cluster_code
        left join "EOT_GR_data" d
          on d."Guild" = gc.guild_code
         and d."Season" = v_season::text
        where gc.enabled = true
        group by
            gc.guild_code,
            gc.display_name,
            gc.cluster_code,
            cc.display_name,
            gc."GR_Ranking"
    ),
    top_hits as (
        select
            d."Guild" as guild_code,
            json_agg(
                json_build_object(
                    'boss_name', d."Name",
                    'damage',    d."damageDealt",
                    'player',    d."displayName"
                )
                order by d."damageDealt" desc
            ) filter (where rn <= 5) as top_boss_hits
        from (
            select
                "Guild",
                "Name",
                "damageDealt",
                "displayName",
                row_number() over (partition by "Guild" order by "damageDealt" desc) as rn
            from "EOT_GR_data"
            where "Season" = v_season::text
              and "damageDealt" > 0
              and "Name" is not null
        ) d
        where rn <= 5
        group by d."Guild"
    )
    insert into public_guild_snapshots (
        guild_code,
        guild_name,
        cluster_code,
        cluster_name,
        season,
        rank,
        total_damage,
        average_damage,
        total_battles,
        active_players,
        avg_damage_per_battle,
        member_count,
        veteran_count,
        votlw_count,
        top_boss_hits,
        votlw_champions,
        last_updated
    )
    select
        gs.guild_code,
        gs.guild_name,
        gs.cluster_code,
        gs.cluster_name,
        gs.season,
        gs.rank,
        gs.total_damage,
        gs.average_damage,
        gs.total_battles,
        gs.active_players,
        gs.avg_damage_per_battle,
        gs.active_players,
        0,
        0,
        coalesce(th.top_boss_hits, '[]'::json),
        '[]'::json,
        now()
    from guild_stats gs
    left join top_hits th on gs.guild_code = th.guild_code;
end;
$_$;

ALTER FUNCTION public.refresh_guild_snapshots(p_season integer) OWNER TO postgres;

