CREATE FUNCTION public.refresh_member_stats_summary() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  -- Refresh the materialized view
  REFRESH MATERIALIZED VIEW member_stats_summary;

  -- Log the refresh (only if system_logs exists)
  IF EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'system_logs') THEN
    INSERT INTO system_logs (operation, details, created_at)
    VALUES ('refresh_member_stats', 'Materialized view refreshed successfully', NOW())
    ON CONFLICT DO NOTHING;
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    -- Log any errors (only if system_logs exists)
    IF EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'system_logs') THEN
      INSERT INTO system_logs (operation, details, error, created_at)
      VALUES ('refresh_member_stats', 'Error refreshing materialized view', SQLERRM, NOW())
      ON CONFLICT DO NOTHING;
    END IF;

    -- Re-raise the error
    RAISE;
END;
$$;

ALTER FUNCTION public.refresh_member_stats_summary() OWNER TO postgres;

CREATE FUNCTION public.refresh_meta_atlas_all() RETURNS TABLE(season text, rows_inserted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  all_seasons text[];
BEGIN
  -- Distinct numeric seasons, newest first. DISTINCT is done in the subquery
  -- so the outer array_agg's numeric ORDER BY is legal (the LEX-FIX intent —
  -- numeric, not TEXT lexical, so '100' sorts after '99').
  SELECT array_agg(s ORDER BY s::int DESC)
  INTO all_seasons
  FROM (
    SELECT DISTINCT "Season" AS s
    FROM "EOT_GR_data"
    WHERE "Season" IS NOT NULL
      AND "Season" ~ '^\d+$'
  ) distinct_seasons;

  RETURN QUERY SELECT * FROM refresh_meta_atlas_seasons(all_seasons);
END;
$_$;

ALTER FUNCTION public.refresh_meta_atlas_all() OWNER TO postgres;

CREATE FUNCTION public.refresh_meta_atlas_season(p_season text) RETURNS TABLE(rows_affected bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET statement_timeout TO '120s'
    SET search_path TO 'public'
    AS $$
DECLARE
  upserted_count bigint;
BEGIN
  INSERT INTO meta_atlas_data (
    team_hash, team_composition, meta_team, boss_type, boss_unit_id, map_id, sub_boss_name,
    encounter_index, encounter_type, rarity, set_num, rarity_set, season, attack_count,
    damage_max, damage_p90, damage_p75, damage_avg, updated_at
  )
  SELECT
    team_hash, team_composition, meta_team, boss_type, boss_unit_id,
    extract_map_from_unit_id(boss_unit_id) as map_id,
    sub_boss_name, encounter_index, encounter_type, rarity, set_num, rarity_set, season, attack_count,
    damage_max, damage_p90, damage_p75, damage_avg, now()
  FROM get_meta_atlas_anonymous(10, true, true, 10000, ARRAY[p_season])
  --                                ^^^^ true = qualifying overkills only (damage >= group avg)
  ON CONFLICT (team_hash, boss_type, encounter_index, rarity, set_num, season)
  DO UPDATE SET
    team_composition = EXCLUDED.team_composition,
    meta_team = EXCLUDED.meta_team,
    boss_unit_id = EXCLUDED.boss_unit_id,
    map_id = EXCLUDED.map_id,
    sub_boss_name = EXCLUDED.sub_boss_name,
    encounter_type = EXCLUDED.encounter_type,
    rarity_set = EXCLUDED.rarity_set,
    attack_count = EXCLUDED.attack_count,
    damage_max = EXCLUDED.damage_max,
    damage_p90 = EXCLUDED.damage_p90,
    damage_p75 = EXCLUDED.damage_p75,
    damage_avg = EXCLUDED.damage_avg,
    updated_at = now()
  WHERE
    meta_atlas_data.attack_count IS DISTINCT FROM EXCLUDED.attack_count
    OR meta_atlas_data.damage_p90 IS DISTINCT FROM EXCLUDED.damage_p90
    OR meta_atlas_data.damage_max IS DISTINCT FROM EXCLUDED.damage_max
    OR meta_atlas_data.boss_unit_id IS DISTINCT FROM EXCLUDED.boss_unit_id
    OR meta_atlas_data.rarity_set IS DISTINCT FROM EXCLUDED.rarity_set
    OR meta_atlas_data.map_id IS DISTINCT FROM EXCLUDED.map_id
    OR meta_atlas_data.sub_boss_name IS DISTINCT FROM EXCLUDED.sub_boss_name;

  GET DIAGNOSTICS upserted_count = ROW_COUNT;

  RETURN QUERY SELECT upserted_count;
END;
$$;

ALTER FUNCTION public.refresh_meta_atlas_season(p_season text) OWNER TO postgres;

CREATE FUNCTION public.refresh_meta_atlas_seasons(p_seasons text[]) RETURNS TABLE(season text, rows_inserted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  s text;
  cnt bigint;
BEGIN
  FOREACH s IN ARRAY p_seasons
  LOOP
    SELECT * INTO cnt FROM refresh_meta_atlas_season(s);
    season := s;
    rows_inserted := cnt;
    RETURN NEXT;
  END LOOP;
END;
$$;

ALTER FUNCTION public.refresh_meta_atlas_seasons(p_seasons text[]) OWNER TO postgres;

