CREATE FUNCTION public.refresh_votlw_winners() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
DECLARE
  result json;
  latest_calculated_season text;
BEGIN
  -- Since we're now reading directly from votlw_winners table,
  -- this function just returns the status of what's available

  SELECT MAX(season) INTO latest_calculated_season
  FROM votlw_winners
  WHERE season ~ '^\d+$';

  result := json_build_object(
    'success', true,
    'message', 'VOTLW view now reads directly from votlw_winners table',
    'latest_calculated_season', latest_calculated_season,
    'note', 'Run VOTLW calculation process to update winners'
  );

  RETURN result;
EXCEPTION
  WHEN OTHERS THEN
    RETURN json_build_object(
      'success', false,
      'error', SQLERRM
    );
END;
$_$;

