CREATE FUNCTION public.resolve_discord_guild_context(p_discord_guild_id text, p_discord_user_id text DEFAULT NULL::text, p_discord_channel_id text DEFAULT NULL::text, p_scope text DEFAULT 'tokens'::text, p_requested_guild text DEFAULT NULL::text) RETURNS TABLE(guild_code text, cluster_code text, display_name text, source text, all_guilds jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linked jsonb;
  v_count int;
  v_gc text;
  v_cc text;
  v_dn text;
  v_requested text := NULLIF(trim(p_requested_guild), '');
BEGIN
  -- Step 1: Load all linked guilds. guildCode must remain canonical/stored case.
  SELECT jsonb_agg(
    jsonb_build_object(
      'guildCode', dsg.game_guild_code,
      'guildTag', gc.guild_tag,
      'clusterCode', COALESCE(dsg.cluster_code, gc.cluster_code),
      'displayName', gc.display_name
    )
    ORDER BY dsg.linked_at ASC
  )
  INTO v_linked
  FROM discord_server_guilds dsg
  LEFT JOIN guild_config gc ON gc.guild_code = dsg.game_guild_code
  WHERE dsg.discord_guild_id = p_discord_guild_id
    AND dsg.is_active = true;

  IF v_linked IS NULL THEN
    RETURN;
  END IF;

  v_count := jsonb_array_length(v_linked);

  -- Step 2: Explicit guild option. Accept canonical UUID, guild tag, or the
  -- pre-WI-825 legacy short code captured in guild_code_legacy_map.
  IF v_requested IS NOT NULL THEN
    SELECT dsg.game_guild_code, COALESCE(dsg.cluster_code, gc.cluster_code), gc.display_name
    INTO v_gc, v_cc, v_dn
    FROM discord_server_guilds dsg
    LEFT JOIN guild_config gc ON gc.guild_code = dsg.game_guild_code
    WHERE dsg.discord_guild_id = p_discord_guild_id
      AND dsg.is_active = true
      AND (
        lower(dsg.game_guild_code) = lower(v_requested)
        OR lower(gc.guild_tag) = lower(v_requested)
        OR lower(gc.guild_id::text) = lower(v_requested)
        OR EXISTS (
          SELECT 1
          FROM guild_code_legacy_map glm
          WHERE glm.canonical_guild_code = dsg.game_guild_code
            AND lower(glm.legacy_guild_code) = lower(v_requested)
        )
      )
    ORDER BY dsg.linked_at ASC
    LIMIT 1;

    IF v_gc IS NOT NULL THEN
      RETURN QUERY SELECT v_gc, v_cc, v_dn, 'option'::text, v_linked;
    ELSE
      RETURN QUERY SELECT NULL::text, NULL::text, NULL::text, 'not_found'::text, v_linked;
    END IF;
    RETURN;
  END IF;

  -- Single guild = return immediately.
  IF v_count = 1 THEN
    RETURN QUERY SELECT
      (v_linked->0->>'guildCode')::text,
      (v_linked->0->>'clusterCode')::text,
      (v_linked->0->>'displayName')::text,
      'default'::text,
      v_linked;
    RETURN;
  END IF;

  -- Step 3: User default.
  IF p_discord_user_id IS NOT NULL THEN
    SELECT dug.game_guild_code, COALESCE(dug.cluster_code, gc2.cluster_code), gc2.display_name
    INTO v_gc, v_cc, v_dn
    FROM discord_user_guild_defaults dug
    LEFT JOIN guild_config gc2 ON gc2.guild_code = dug.game_guild_code
    WHERE dug.discord_guild_id = p_discord_guild_id
      AND dug.discord_user_id = p_discord_user_id
      AND EXISTS (
        SELECT 1 FROM discord_server_guilds dsg_active
        WHERE dsg_active.discord_guild_id = p_discord_guild_id
          AND dsg_active.game_guild_code = dug.game_guild_code
          AND dsg_active.is_active = true
      )
    LIMIT 1;

    IF v_gc IS NOT NULL THEN
      RETURN QUERY SELECT v_gc, v_cc, v_dn, 'user'::text, v_linked;
      RETURN;
    END IF;
  END IF;

  -- Step 4: Channel default.
  IF p_discord_channel_id IS NOT NULL THEN
    IF p_scope = 'notifications' THEN
      SELECT dcg.game_guild_code, COALESCE(dcg.cluster_code, gc3.cluster_code), gc3.display_name
      INTO v_gc, v_cc, v_dn
      FROM discord_channel_guilds dcg
      LEFT JOIN guild_config gc3 ON gc3.guild_code = dcg.game_guild_code
      WHERE dcg.discord_guild_id = p_discord_guild_id
        AND dcg.discord_channel_id = p_discord_channel_id
        AND dcg.default_for_notifications = true
      AND EXISTS (
        SELECT 1 FROM discord_server_guilds dsg_active
        WHERE dsg_active.discord_guild_id = p_discord_guild_id
          AND dsg_active.game_guild_code = dcg.game_guild_code
          AND dsg_active.is_active = true
      )
      LIMIT 1;
    ELSE
      SELECT dcg.game_guild_code, COALESCE(dcg.cluster_code, gc3.cluster_code), gc3.display_name
      INTO v_gc, v_cc, v_dn
      FROM discord_channel_guilds dcg
      LEFT JOIN guild_config gc3 ON gc3.guild_code = dcg.game_guild_code
      WHERE dcg.discord_guild_id = p_discord_guild_id
        AND dcg.discord_channel_id = p_discord_channel_id
        AND dcg.default_for_tokens = true
      AND EXISTS (
        SELECT 1 FROM discord_server_guilds dsg_active
        WHERE dsg_active.discord_guild_id = p_discord_guild_id
          AND dsg_active.game_guild_code = dcg.game_guild_code
          AND dsg_active.is_active = true
      )
      LIMIT 1;
    END IF;

    IF v_gc IS NOT NULL THEN
      RETURN QUERY SELECT v_gc, v_cc, v_dn, 'channel'::text, v_linked;
      RETURN;
    END IF;
  END IF;

  -- Step 5: Ambiguous: multiple guilds, no default.
  RETURN QUERY SELECT NULL::text, NULL::text, NULL::text, 'ambiguous'::text, v_linked;
END;
$$;

ALTER FUNCTION public.resolve_discord_guild_context(p_discord_guild_id text, p_discord_user_id text, p_discord_channel_id text, p_scope text, p_requested_guild text) OWNER TO postgres;

CREATE FUNCTION public.resolve_season_boss_name(p_season integer, p_boss_position integer, p_encounter_id integer, p_fallback_name text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT sbl.boss_name
      FROM public.season_boss_lineup sbl
      WHERE sbl.season = p_season
        AND sbl.boss_position = p_boss_position
        AND sbl.encounter_id = p_encounter_id
    ),
    p_fallback_name
  );
$$;

ALTER FUNCTION public.resolve_season_boss_name(p_season integer, p_boss_position integer, p_encounter_id integer, p_fallback_name text) OWNER TO postgres;

CREATE FUNCTION public.resolve_verified_discord_identities(p_discord_user_ids text[]) RETURNS TABLE(mapping_id bigint, player_id text, user_id uuid, guild_code text, role public.app_role, is_app_admin boolean, ownership_attestation_id uuid, discord_user_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
BEGIN
  IF p_discord_user_ids IS NULL OR cardinality(p_discord_user_ids) IS NULL
    OR cardinality(p_discord_user_ids) < 1
    OR cardinality(p_discord_user_ids) > 1000
    OR EXISTS (
      SELECT 1 FROM unnest(p_discord_user_ids) AS requested(id)
      WHERE requested.id IS NULL OR requested.id !~ '^[0-9]{17,20}$'
    )
  THEN
    RAISE EXCEPTION 'p_discord_user_ids must contain 1..1000 strict snowflakes'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT
      mapping.id,
      mapping.player_id,
      mapping.user_id,
      mapping.guild_code,
      mapping.role,
      mapping.is_app_admin,
      mapping.ownership_attestation_id,
      mapping.discord_user_id::text,
      identity_proof.auth_identity_id
    FROM public.player_mapping AS mapping
    CROSS JOIN LATERAL (
      SELECT
        count(*) AS match_count,
        (array_agg(attestation.id ORDER BY attestation.id))[1]
          AS exact_attestation_id
      FROM public.player_identity_attestations AS attestation
      WHERE attestation.mapping_id = mapping.id
        AND attestation.player_id = mapping.player_id
        AND attestation.subject_user_id = mapping.user_id
        AND NOT EXISTS (
          SELECT 1
          FROM public.player_identity_attestation_revocations AS revoked
          WHERE revoked.attestation_id = attestation.id
        )
    ) AS ownership_proof
    CROSS JOIN LATERAL (
      SELECT
        count(*) AS match_count,
        (array_agg(identity.id ORDER BY identity.id))[1] AS auth_identity_id
      FROM auth.identities AS identity
      WHERE identity.provider = 'discord'
        AND identity.provider_id = mapping.discord_user_id
        AND identity.user_id = mapping.user_id
    ) AS identity_proof
    LEFT JOIN LATERAL (
      SELECT pending.id
      FROM public.player_identity_discord_unlink_pending AS pending
      WHERE pending.subject_user_id = mapping.user_id
      ORDER BY pending.generation DESC
      LIMIT 1
    ) AS latest_pending ON true
    LEFT JOIN public.player_identity_discord_generation_activations AS activation
      ON activation.pending_id = latest_pending.id
    WHERE mapping.is_current IS TRUE
      AND mapping.discord_user_id = ANY(p_discord_user_ids)
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_subject_authority_blocks AS block
        WHERE block.subject_user_id = mapping.user_id
      )
      AND mapping.discord_user_id ~ '^[0-9]{17,20}$'
      AND ownership_proof.match_count = 1
      AND ownership_proof.exact_attestation_id =
        mapping.ownership_attestation_id
      AND identity_proof.match_count = 1
      AND (
        latest_pending.id IS NULL
        OR (
          activation.pending_id IS NOT NULL
          AND activation.auth_identity_id = identity_proof.auth_identity_id
          AND activation.ownership_attestation_id =
            mapping.ownership_attestation_id
          AND activation.provider_id_sha256 = encode(extensions.digest(
            convert_to(mapping.discord_user_id, 'UTF8'), 'sha256'
          ), 'hex')
        )
      )
  ), exact_users AS (
    SELECT candidate.user_id
    FROM candidates AS candidate
    GROUP BY candidate.user_id
    HAVING count(*) = 1
  ), exact_discord_ids AS (
    SELECT candidate.discord_user_id
    FROM candidates AS candidate
    GROUP BY candidate.discord_user_id
    HAVING count(*) = 1
  )
  SELECT
    candidate.id::bigint,
    candidate.player_id,
    candidate.user_id,
    candidate.guild_code,
    candidate.role,
    coalesce(candidate.is_app_admin, false),
    candidate.ownership_attestation_id,
    candidate.discord_user_id
  FROM candidates AS candidate
  JOIN exact_users AS exact_user USING (user_id)
  JOIN exact_discord_ids AS exact_discord USING (discord_user_id)
  ORDER BY candidate.id;
END
$_$;

ALTER FUNCTION public.resolve_verified_discord_identities(p_discord_user_ids text[]) OWNER TO postgres;

CREATE FUNCTION public.resolve_verified_players(p_user_ids uuid[]) RETURNS TABLE(mapping_id bigint, player_id text, user_id uuid, guild_code text, role public.app_role, is_app_admin boolean, ownership_attestation_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user_ids IS NULL OR cardinality(p_user_ids) IS NULL
    OR cardinality(p_user_ids) < 1 OR cardinality(p_user_ids) > 1000
    OR array_position(p_user_ids, NULL) IS NOT NULL
  THEN
    RAISE EXCEPTION 'p_user_ids must contain 1..1000 non-null UUIDs'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT
      mapping.id,
      mapping.player_id,
      mapping.user_id,
      mapping.guild_code,
      mapping.role,
      mapping.is_app_admin,
      mapping.ownership_attestation_id
    FROM public.player_mapping AS mapping
    CROSS JOIN LATERAL (
      SELECT
        count(*) AS match_count,
        (array_agg(attestation.id ORDER BY attestation.id))[1]
          AS exact_attestation_id
      FROM public.player_identity_attestations AS attestation
      WHERE attestation.mapping_id = mapping.id
        AND attestation.player_id = mapping.player_id
        AND attestation.subject_user_id = mapping.user_id
        AND NOT EXISTS (
          SELECT 1
          FROM public.player_identity_attestation_revocations AS revoked
          WHERE revoked.attestation_id = attestation.id
        )
    ) AS proof
    WHERE mapping.is_current IS TRUE
      AND mapping.user_id = ANY(p_user_ids)
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_subject_authority_blocks AS block
        WHERE block.subject_user_id = mapping.user_id
      )
      AND proof.match_count = 1
      AND proof.exact_attestation_id = mapping.ownership_attestation_id
  ), unambiguous_users AS (
    SELECT candidate.user_id
    FROM candidates AS candidate
    GROUP BY candidate.user_id
    HAVING count(*) = 1
  )
  SELECT
    candidate.id::bigint,
    candidate.player_id,
    candidate.user_id,
    candidate.guild_code,
    candidate.role,
    coalesce(candidate.is_app_admin, false),
    candidate.ownership_attestation_id
  FROM candidates AS candidate
  JOIN unambiguous_users AS exact_user USING (user_id)
  ORDER BY candidate.id;
END
$$;

ALTER FUNCTION public.resolve_verified_players(p_user_ids uuid[]) OWNER TO postgres;

CREATE FUNCTION public.revoke_all_player_identity_for_subject(p_user_id uuid, p_reason text, p_actor_user_id uuid, p_source text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_attestation record;
  v_revoked integer := 0;
BEGIN
  IF p_user_id IS NULL OR p_reason NOT IN ('account_delete', 'gdpr_erasure')
    OR p_source IS NULL OR length(btrim(p_source)) < 3
    OR length(p_source) > 120
  THEN
    RAISE EXCEPTION 'Invalid subject-wide identity revocation request'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(6208, hashtext(p_user_id::text));
  FOR v_attestation IN
    SELECT attestation.id
    FROM public.player_identity_attestations AS attestation
    WHERE attestation.subject_user_id = p_user_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_attestation_revocations AS revoked
        WHERE revoked.attestation_id = attestation.id
      )
    ORDER BY attestation.id
    FOR UPDATE
  LOOP
    PERFORM public.append_player_identity_revocation(
      v_attestation.id, p_reason, p_actor_user_id, p_source
    );
    v_revoked := v_revoked + 1;
  END LOOP;

  -- Clear current and inactive attachments after every subject attestation is
  -- revoked. The ownership trigger observes the revocations in this transaction.
  UPDATE public.player_mapping AS mapping
  SET user_id = NULL,
      ownership_attestation_id = NULL,
      discord_user_id = NULL,
      discord_username = NULL,
      is_app_admin = false,
      updated_at = clock_timestamp()
  WHERE mapping.user_id = p_user_id
     OR mapping.ownership_attestation_id IN (
       SELECT attestation.id
       FROM public.player_identity_attestations AS attestation
       WHERE attestation.subject_user_id = p_user_id
     );

  RETURN v_revoked;
END
$$;

ALTER FUNCTION public.revoke_all_player_identity_for_subject(p_user_id uuid, p_reason text, p_actor_user_id uuid, p_source text) OWNER TO postgres;

CREATE FUNCTION public.revoke_player_identity_on_auth_user_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  PERFORM public.block_player_identity_subject_authority(
    OLD.id, 'auth_delete', 'auth.users_before_delete'
  );
  PERFORM public.revoke_all_player_identity_for_subject(
    OLD.id, 'account_delete', NULL, 'auth.users_before_delete'
  );

  -- An Auth subject can appear in all three invite audit columns. Delete only
  -- unused, unpinned invitations it issued. A consumed invite pinned by an
  -- immutable ownership attestation remains durable evidence, with issuer,
  -- consumer, and revoker PII redacted. All original Auth foreign keys remain
  -- intact; created_by is nullable solely so redaction never needs a sentinel
  -- or fabricated replacement subject.
  DELETE FROM public.player_invite_codes AS invite
  WHERE invite.created_by = OLD.id
    AND invite.used_at IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.player_identity_attestations AS attestation
      WHERE attestation.source_invite_id = invite.id
    );

  UPDATE public.player_invite_codes AS invite
  SET created_by = CASE
        WHEN invite.created_by = OLD.id THEN NULL ELSE invite.created_by
      END,
      used_by = CASE WHEN invite.used_by = OLD.id THEN NULL ELSE invite.used_by END,
      revoked_by = CASE
        WHEN invite.revoked_by = OLD.id THEN NULL ELSE invite.revoked_by
      END
  WHERE invite.created_by = OLD.id
     OR invite.used_by = OLD.id
     OR invite.revoked_by = OLD.id;

  RETURN OLD;
END
$$;

ALTER FUNCTION public.revoke_player_identity_on_auth_user_delete() OWNER TO postgres;

CREATE FUNCTION public.revoke_player_invite_code(p_invite_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_caller record;
  v_invite record;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '42501';
  END IF;
  IF p_invite_id IS NULL OR p_reason IS NULL
    OR length(btrim(p_reason)) < 3 OR length(p_reason) > 500
  THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Invite and a 3-500 character reason are required',
      'error_code', 'INVALID_INPUT'
    );
  END IF;

  SELECT invite.id, invite.guild_code, invite.used_at, invite.revoked_at
  INTO v_invite
  FROM public.player_invite_codes AS invite
  WHERE invite.id = p_invite_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Invite code not found',
      'error_code', 'NOT_FOUND'
    );
  END IF;

  SELECT count(*)::integer AS match_count,
         (array_agg(verified.guild_code ORDER BY verified.mapping_id))[1]
           AS guild_code,
         (array_agg(verified.role ORDER BY verified.mapping_id))[1] AS role,
         bool_or(verified.is_app_admin) AS is_app_admin
  INTO v_caller
  FROM public.resolve_verified_players(ARRAY[v_user_id]) AS verified;
  IF v_caller.match_count <> 1 OR (
    NOT v_caller.is_app_admin
    AND (
      lower(v_caller.role::text) NOT IN ('leader', 'officer')
      OR v_caller.guild_code IS DISTINCT FROM v_invite.guild_code
    )
  ) THEN
    RAISE EXCEPTION 'Invite revocation is limited to caller-owned guild authority'
      USING ERRCODE = '42501';
  END IF;

  IF v_invite.used_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Consumed invites cannot be revoked',
      'error_code', 'ALREADY_USED'
    );
  END IF;
  IF v_invite.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true, 'invite_id', p_invite_id,
      'already_revoked', true
    );
  END IF;

  UPDATE public.player_invite_codes AS invite
  SET revoked_at = clock_timestamp(), revoked_by = v_user_id
  WHERE invite.id = p_invite_id;
  RETURN jsonb_build_object(
    'success', true, 'invite_id', p_invite_id,
    'already_revoked', false
  );
END
$$;

ALTER FUNCTION public.revoke_player_invite_code(p_invite_id uuid, p_reason text) OWNER TO postgres;

CREATE FUNCTION public.revoke_player_mapping_ownership(p_mapping_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_request_role text := coalesce(
    nullif(nullif(current_setting('role', true), ''), 'none'),
    session_user
  );
  v_mapping record;
  v_attestation record;
  v_revoked integer := 0;
BEGIN
  IF v_request_role NOT IN ('service_role', 'postgres') THEN
    RAISE EXCEPTION 'Mapping ownership revocation requires service authority'
      USING ERRCODE = '42501';
  END IF;
  IF p_mapping_id IS NULL OR p_mapping_id < -2147483648
     OR p_mapping_id > 2147483647
     OR p_reason NOT IN (
       'player_id_correction', 'mapping_delete', 'guild_delete',
       'support_reverify', 'authority_recovery'
     )
  THEN
    RAISE EXCEPTION 'A valid mapping and approved revocation reason are required'
      USING ERRCODE = '22023';
  END IF;

  SELECT mapping.id, mapping.user_id, mapping.ownership_attestation_id
  INTO v_mapping
  FROM public.player_mapping AS mapping
  WHERE mapping.id = p_mapping_id::integer
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Player mapping not found',
      'error_code', 'NOT_FOUND'
    );
  END IF;

  FOR v_attestation IN
    SELECT attestation.id
    FROM public.player_identity_attestations AS attestation
    WHERE attestation.mapping_id = v_mapping.id
      AND NOT EXISTS (
        SELECT 1
        FROM public.player_identity_attestation_revocations AS revoked
        WHERE revoked.attestation_id = attestation.id
      )
    ORDER BY attestation.id
    FOR UPDATE
  LOOP
    PERFORM public.append_player_identity_revocation(
      v_attestation.id,
      p_reason,
      v_mapping.user_id,
      'revoke_player_mapping_ownership'
    );
    v_revoked := v_revoked + 1;
  END LOOP;
  UPDATE public.player_mapping AS mapping
  SET user_id = NULL,
      ownership_attestation_id = NULL,
      discord_user_id = NULL,
      discord_username = NULL,
      is_app_admin = false,
      updated_at = clock_timestamp()
  WHERE mapping.id = v_mapping.id;

  RETURN jsonb_build_object(
    'success', true,
    'mapping_id', v_mapping.id,
    'revoked_attestations', v_revoked,
    'binding_restorable', false
  );
END
$$;

ALTER FUNCTION public.revoke_player_mapping_ownership(p_mapping_id bigint, p_reason text) OWNER TO postgres;

CREATE FUNCTION public.schedule_tacticus_data_import(schedule_interval interval DEFAULT '06:00:00'::interval) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  job_id bigint;
BEGIN
  -- Check if the job already exists
  SELECT id INTO job_id FROM supabase_functions.cron_jobs
  WHERE name = 'tacticus_data_import';

  -- If it exists, update it
  IF FOUND THEN
    UPDATE supabase_functions.cron_jobs
    SET schedule = schedule_interval,
        command = 'INVOKE ' || (SELECT CASE WHEN value='local' THEN 'local/' ELSE '' END FROM supabase_functions.config WHERE key = 'ENVIRONMENT') || 'functions/tacticus-data-import'
    WHERE id = job_id;
  ELSE
    -- If it doesn't exist, create it
    INSERT INTO supabase_functions.cron_jobs (name, schedule, command)
    VALUES (
      'tacticus_data_import',
      schedule_interval,
      'INVOKE ' || (SELECT CASE WHEN value='local' THEN 'local/' ELSE '' END FROM supabase_functions.config WHERE key = 'ENVIRONMENT') || 'functions/tacticus-data-import'
    );
  END IF;
END;
$$;

ALTER FUNCTION public.schedule_tacticus_data_import(schedule_interval interval) OWNER TO postgres;

CREATE FUNCTION public.search_players_simple(search_text text DEFAULT ''::text) RETURNS TABLE(player_id text, display_name text, guild_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    user_role TEXT;
    user_guild TEXT;
    user_cluster TEXT;
BEGIN
    -- Get the calling user's info
    SELECT role, guild_code
    INTO user_role, user_guild
    FROM player_mapping
    WHERE user_id = auth.uid()
    AND is_current = true;

    -- Members only see themselves
    IF user_role = 'member' OR user_role IS NULL THEN
        RETURN QUERY
        SELECT
            pm.player_id,
            pm.display_name,
            pm.guild_code
        FROM player_mapping pm
        WHERE pm.user_id = auth.uid()
        AND pm.is_current = true;
        RETURN;
    END IF;

    -- For leaders, get their cluster
    IF user_role = 'leader' THEN
        SELECT cluster_code INTO user_cluster
        FROM guild_config
        WHERE guild_code = user_guild;
    END IF;

    -- Return search results based on role
    IF user_role = 'leader' AND user_cluster IS NOT NULL THEN
        -- Leaders see all cluster members
        RETURN QUERY
        SELECT
            pm.player_id,
            pm.display_name,
            pm.guild_code
        FROM player_mapping pm
        JOIN guild_config gc ON gc.guild_code = pm.guild_code
        WHERE gc.cluster_code = user_cluster
        AND pm.is_current = true
        AND (search_text = '' OR pm.display_name ILIKE '%' || search_text || '%')
        ORDER BY pm.display_name
        LIMIT 500;
    ELSE
        -- Officers see their guild
        RETURN QUERY
        SELECT
            pm.player_id,
            pm.display_name,
            pm.guild_code
        FROM player_mapping pm
        WHERE pm.guild_code = user_guild
        AND pm.is_current = true
        AND (search_text = '' OR pm.display_name ILIKE '%' || search_text || '%')
        ORDER BY pm.display_name
        LIMIT 500;
    END IF;
END;
$$;

ALTER FUNCTION public.search_players_simple(search_text text) OWNER TO postgres;

CREATE FUNCTION public.set_active_progression_config(p_id uuid, p_is_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_scope text;
BEGIN
  SELECT scope INTO v_scope
  FROM public.raid_progression_config
  WHERE id = p_id;

  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'progression config % not found', p_id
      USING ERRCODE = 'no_data_found';
  END IF;

  IF p_is_active THEN
    -- Deactivate the scope's other active rows FIRST, so the partial unique
    -- index never sees two active rows for the scope mid-statement.
    UPDATE public.raid_progression_config
       SET is_active = false, updated_at = now()
     WHERE scope = v_scope
       AND is_active
       AND id <> p_id;
  END IF;

  UPDATE public.raid_progression_config
     SET is_active = p_is_active, updated_at = now()
   WHERE id = p_id;
END;
$$;

ALTER FUNCTION public.set_active_progression_config(p_id uuid, p_is_active boolean) OWNER TO postgres;

