CREATE FUNCTION public.suggest_player_mapping_fixes() RETURNS TABLE(issue_type text, player_identifier text, suggested_action text, priority text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Find players in "EOT_GR_data" without player_mapping
  RETURN QUERY
  SELECT
    'Missing Mapping'::TEXT as issue_type,
    e."displayName"::TEXT as player_identifier,
    ('Create player_mapping entry for player_id: ' || e."userId")::TEXT as suggested_action,
    'HIGH'::TEXT as priority
  FROM (
    SELECT DISTINCT e."userId", e."displayName"
    FROM "EOT_GR_data" e
    WHERE e."userId" IS NOT NULL
      AND e."displayName" IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM player_mapping pm WHERE pm.player_id = e."userId"
      )
    LIMIT 100
  ) e;

  -- Find display names that might be the same player
  RETURN QUERY
  SELECT
    'Potential Duplicate'::TEXT as issue_type,
    array_to_string(dup.display_names, ', ')::TEXT as player_identifier,
    'Review if these are the same player and merge if needed'::TEXT as suggested_action,
    'MEDIUM'::TEXT as priority
  FROM (
    SELECT array_agg(DISTINCT e."displayName" ORDER BY e."displayName") as display_names
    FROM "EOT_GR_data" e
    WHERE e."displayName" IS NOT NULL
    GROUP BY LOWER(REGEXP_REPLACE(TRIM(e."displayName"), '[^a-zA-Z0-9]', '', 'g'))
    HAVING COUNT(DISTINCT e."displayName") > 1
      AND COUNT(DISTINCT e."displayName") <= 5  -- Only show manageable duplicates
    LIMIT 50
  ) dup;
END;
$$;

ALTER FUNCTION public.suggest_player_mapping_fixes() OWNER TO postgres;

CREATE FUNCTION public.test_boss_rankings_simple(p_player_name text, p_season text) RETURNS TABLE(boss_name text, player_damage numeric, player_rank integer, total_players integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH player_damage AS (
    SELECT
      COALESCE(resolve_boss_name(e."Name"), e."Name") as boss_name,
      AVG(e."damageDealt")::NUMERIC as avg_damage
    FROM "EOT_GR_data" e
    WHERE e."displayName" = p_player_name
      AND e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
    GROUP BY COALESCE(resolve_boss_name(e."Name"), e."Name")
  ),
  all_players AS (
    SELECT
      COALESCE(resolve_boss_name(e."Name"), e."Name") as boss_name,
      e."displayName" as player_name,
      AVG(e."damageDealt")::NUMERIC as avg_damage
    FROM "EOT_GR_data" e
    WHERE e."Season" = p_season
      AND e."damageType" = 'Battle'
      AND e.rarity IN ('Legendary', 'Mythic')
      AND e."damageDealt" > 0
    GROUP BY COALESCE(resolve_boss_name(e."Name"), e."Name"), e."displayName"
  ),
  ranked AS (
    SELECT
      ap.boss_name,
      ap.player_name,
      ap.avg_damage,
      RANK() OVER (PARTITION BY ap.boss_name ORDER BY ap.avg_damage DESC) as rank,
      COUNT(*) OVER (PARTITION BY ap.boss_name) as total
    FROM all_players ap
  )
  SELECT
    pd.boss_name,
    pd.avg_damage as player_damage,
    r.rank::INTEGER as player_rank,
    r.total::INTEGER as total_players
  FROM player_damage pd
  JOIN ranked r ON r.boss_name = pd.boss_name AND r.player_name = p_player_name;
END;
$$;

ALTER FUNCTION public.test_boss_rankings_simple(p_player_name text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.test_performance_calculations(p_guild_code text, p_season text) RETURNS TABLE(test_name text, expected_result numeric, actual_result numeric, difference_pct numeric, status text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  total_players_old BIGINT;
  total_players_new BIGINT;
  avg_damage_old NUMERIC;
  avg_damage_new NUMERIC;
BEGIN
  -- Test 1: Player count comparison (old vs new method)
  SELECT COUNT(DISTINCT displayName) INTO total_players_old
  FROM "EOT_GR_data"
  WHERE Guild = p_guild_code AND "Season" = p_season AND damageDealt > 0;

  SELECT COUNT(DISTINCT userId) INTO total_players_new
  FROM "EOT_GR_data"
  WHERE Guild = p_guild_code AND "Season" = p_season AND damageDealt > 0 AND userId IS NOT NULL;

  RETURN QUERY
  SELECT
    'Player Count Comparison'::TEXT as test_name,
    total_players_old::NUMERIC as expected_result,
    total_players_new::NUMERIC as actual_result,
    CASE
      WHEN total_players_old > 0
      THEN ABS(total_players_new - total_players_old)::NUMERIC / total_players_old * 100
      ELSE 0
    END as difference_pct,
    CASE
      WHEN total_players_new <= total_players_old THEN 'PASS'::TEXT
      ELSE 'FAIL'::TEXT
    END as status;

  -- Test 2: Average damage comparison
  SELECT AVG(subq.avg_damage) INTO avg_damage_old
  FROM (
    SELECT displayName, AVG(damageDealt) as avg_damage
    FROM "EOT_GR_data"
    WHERE Guild = p_guild_code AND "Season" = p_season AND damageDealt > 0
    GROUP BY displayName
  ) subq;

  SELECT AVG(subq.avg_damage) INTO avg_damage_new
  FROM (
    SELECT userId, AVG(damageDealt) as avg_damage
    FROM "EOT_GR_data"
    WHERE Guild = p_guild_code AND "Season" = p_season AND damageDealt > 0 AND userId IS NOT NULL
    GROUP BY userId
  ) subq;

  RETURN QUERY
  SELECT
    'Average Damage Comparison'::TEXT as test_name,
    avg_damage_old as expected_result,
    avg_damage_new as actual_result,
    CASE
      WHEN avg_damage_old > 0
      THEN ABS(avg_damage_new - avg_damage_old) / avg_damage_old * 100
      ELSE 0
    END as difference_pct,
    CASE
      WHEN ABS(avg_damage_new - avg_damage_old) / NULLIF(avg_damage_old, 0) * 100 < 5 THEN 'PASS'::TEXT
      ELSE 'WARN'::TEXT
    END as status;
END;
$$;

ALTER FUNCTION public.test_performance_calculations(p_guild_code text, p_season text) OWNER TO postgres;

CREATE FUNCTION public.test_player_search(p_search_term text) RETURNS TABLE(player_id text, current_name text, historical_names text[], guild_count bigint, season_count bigint, total_battles bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH matching_players AS (
    SELECT DISTINCT pm.player_id
    FROM player_mapping pm
    WHERE pm.display_name ILIKE '%' || p_search_term || '%'
  ),
  player_details AS (
    SELECT
      mp.player_id,
      pm_current.display_name as current_name,
      array_agg(DISTINCT pm_all.display_name ORDER BY pm_all.display_name) as historical_names,
      COUNT(DISTINCT e."Guild") as guild_count,
      COUNT(DISTINCT e."Season") as season_count,
      COUNT(*) as total_battles
    FROM matching_players mp
    LEFT JOIN player_mapping pm_current ON mp.player_id = pm_current.player_id AND pm_current.is_current = true
    LEFT JOIN player_mapping pm_all ON mp.player_id = pm_all.player_id
    LEFT JOIN "EOT_GR_data" e ON mp.player_id = e."userId"
    GROUP BY mp.player_id, pm_current.display_name
  )
  SELECT
    pd.player_id::TEXT,
    COALESCE(pd.current_name, 'Unknown Player')::TEXT as current_name,
    pd.historical_names,
    pd.guild_count,
    pd.season_count,
    pd.total_battles
  FROM player_details pd
  ORDER BY pd.total_battles DESC;
END;
$$;

ALTER FUNCTION public.test_player_search(p_search_term text) OWNER TO postgres;

CREATE FUNCTION public.toggle_webhook_cron_job(p_job_name text, p_enabled boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF p_enabled THEN
    -- Re-enable the job
    UPDATE cron.job
    SET active = true
    WHERE jobname = p_job_name;
  ELSE
    -- Disable the job
    UPDATE cron.job
    SET active = false
    WHERE jobname = p_job_name;
  END IF;

  -- Update our tracking table
  UPDATE webhook_cron_jobs
  SET enabled = p_enabled,
      updated_at = NOW()
  WHERE job_name = p_job_name;
END;
$$;

ALTER FUNCTION public.toggle_webhook_cron_job(p_job_name text, p_enabled boolean) OWNER TO postgres;

CREATE FUNCTION public.trigger_historical_backfill() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  kong_url TEXT := COALESCE(NULLIF(current_setting('app.settings.supabase_internal_url', true), ''), 'http://supabase-kong:8000');
  v_service_key TEXT;
  v_result BIGINT;
BEGIN
  -- Get service role key from database settings
  v_service_key := current_setting('app.settings.service_role_key', true);

  IF v_service_key IS NULL OR v_service_key = '' THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'Service role key not configured. Set via: ALTER DATABASE postgres SET app.settings.service_role_key = ''your-key'';',
      'timestamp', NOW()
    );
  END IF;

  -- Call local Edge Function via Kong gateway
  BEGIN
    SELECT net.http_post(
      url := kong_url || '/functions/v1/historical-backfill-modular',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_service_key
      ),
      body := jsonb_build_object(
        'all_clusters', true,
        'force_sync', false,
        'source', 'scheduled_cron'
      )::text,
      timeout_milliseconds := 60000
    ) INTO v_result;

    RETURN jsonb_build_object(
      'status', 'triggered',
      'request_id', v_result,
      'timestamp', NOW()
    );

  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'Failed to call edge function',
      'error_detail', SQLERRM,
      'timestamp', NOW()
    );
  END;
END;
$$;

ALTER FUNCTION public.trigger_historical_backfill() OWNER TO postgres;

