CREATE FUNCTION public.update_boss_playbook(p_boss_id text, p_content text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_user_id uuid;
  v_allowed boolean;
  v_old_boss_id text;
  v_old_content text;
  v_old_updated_by uuid;
  v_old_updated_at timestamptz;
  v_old_version integer;
  v_new_version integer;
BEGIN
  v_role := lower(trim(COALESCE(NULLIF(NULLIF(current_setting('role', true), ''), 'none'), NULLIF(session_user, ''))));
  IF v_role NOT IN ('authenticated') THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  v_allowed := public.can_edit_playbooks(v_user_id);

  IF NOT coalesce(v_allowed, false) THEN
    RAISE EXCEPTION USING ERRCODE = '42501';
  END IF;

  SELECT
    bp.boss_id,
    bp.content,
    bp.updated_by,
    bp.updated_at,
    bp.version
  INTO
    v_old_boss_id,
    v_old_content,
    v_old_updated_by,
    v_old_updated_at,
    v_old_version
  FROM public.boss_playbooks AS bp
  WHERE bp.boss_id = p_boss_id;

  IF FOUND THEN
    v_new_version := coalesce(v_old_version, 0) + 1;
    INSERT INTO public.boss_playbook_history (
      boss_id,
      content,
      changed_by,
      changed_at,
      version
    )
    VALUES (
      v_old_boss_id,
      v_old_content,
      v_user_id,
      coalesce(v_old_updated_at, now()),
      coalesce(v_old_version, 0)
    );

    UPDATE public.boss_playbooks AS bp
    SET
      content = p_content,
      updated_by = v_user_id,
      updated_at = now(),
      version = v_new_version
    WHERE bp.boss_id = p_boss_id
      AND (
        bp.updated_by = v_old_updated_by
        OR (bp.updated_by IS NULL AND v_old_updated_by IS NULL)
      );
  ELSE
    v_new_version := 1;
    INSERT INTO public.boss_playbooks (
      boss_id,
      content,
      updated_by,
      updated_at,
      version
    )
    VALUES (
      p_boss_id,
      p_content,
      v_user_id,
      now(),
      v_new_version
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'version', v_new_version,
    'boss_id', p_boss_id
  );
END;
$$;

ALTER FUNCTION public.update_boss_playbook(p_boss_id text, p_content text) OWNER TO command_center_rpc_owner;

CREATE FUNCTION public.update_cluster_identity(p_cluster_id uuid, p_updates jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_auth_uid uuid := auth.uid();
  v_request_role text := COALESCE(
    NULLIF(NULLIF(current_setting('role', true), ''), 'none'),
    NULLIF(session_user, '')
  );
  v_is_service boolean;
  v_updated_count integer;
BEGIN
  v_is_service := COALESCE(v_request_role, '') IN (
    'service_role', 'postgres', 'supabase_admin'
  );

  IF p_updates IS NULL OR jsonb_typeof(p_updates) <> 'object' THEN
    RAISE EXCEPTION 'Cluster identity updates must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM jsonb_object_keys(p_updates) AS requested(key)
     WHERE requested.key NOT IN (
       'display_name', 'short_name', 'tagline', 'description', 'logo_url',
       'banner_url', 'primary_color', 'secondary_color', 'accent_color',
       'discord_server_id', 'discord_invite_url', 'website_url', 'time_zone',
       'primary_language', 'public_notes'
     )
  ) THEN
    RAISE EXCEPTION 'Cluster identity update contains unsupported fields'
      USING ERRCODE = '22023';
  END IF;

  IF NOT v_is_service THEN
    IF v_auth_uid IS NULL OR NOT EXISTS (
      SELECT 1
        FROM public.clusters c
       WHERE c.id = p_cluster_id
         AND (
           c.created_by = v_auth_uid
           OR EXISTS (
             SELECT 1
               FROM public.player_mapping pm
               JOIN public.guild_config gc ON gc.guild_code = pm.guild_code
              WHERE pm.user_id = v_auth_uid
                AND pm.is_current = true
                AND pm.role = 'leader'::public.app_role
                AND gc.cluster_id = c.id
           )
           OR EXISTS (
             SELECT 1
               FROM public.player_mapping pm
              WHERE pm.user_id = v_auth_uid
                AND pm.is_current = true
                AND pm.is_app_admin = true
           )
         )
    ) THEN
      RAISE EXCEPTION 'Caller may not update the requested cluster identity'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  UPDATE public.clusters
     SET display_name = COALESCE(p_updates->>'display_name', display_name),
         short_name = COALESCE(p_updates->>'short_name', short_name),
         tagline = COALESCE(p_updates->>'tagline', tagline),
         description = COALESCE(p_updates->>'description', description),
         logo_url = COALESCE(p_updates->>'logo_url', logo_url),
         banner_url = COALESCE(p_updates->>'banner_url', banner_url),
         primary_color = COALESCE(p_updates->>'primary_color', primary_color),
         secondary_color = COALESCE(p_updates->>'secondary_color', secondary_color),
         accent_color = COALESCE(p_updates->>'accent_color', accent_color),
         discord_server_id = COALESCE(p_updates->>'discord_server_id', discord_server_id),
         discord_invite_url = COALESCE(p_updates->>'discord_invite_url', discord_invite_url),
         website_url = COALESCE(p_updates->>'website_url', website_url),
         time_zone = COALESCE(p_updates->>'time_zone', time_zone),
         primary_language = COALESCE(p_updates->>'primary_language', primary_language),
         public_notes = COALESCE(p_updates->>'public_notes', public_notes),
         updated_at = now()
   WHERE id = p_cluster_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> 1 THEN
    RAISE EXCEPTION 'Cluster identity update expected one row, updated %',
      v_updated_count USING ERRCODE = 'P0002';
  END IF;
END;
$$;

ALTER FUNCTION public.update_cluster_identity(p_cluster_id uuid, p_updates jsonb) OWNER TO postgres;

