CREATE FUNCTION public.update_guild_rankings_batch(p_rankings jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  updated_count integer;
BEGIN
  IF p_rankings IS NULL OR jsonb_array_length(p_rankings) = 0 THEN
    RETURN 0;
  END IF;

  WITH input AS (
    SELECT *
    FROM jsonb_to_recordset(p_rankings)
      AS x(guild_tag text, rank bigint)
    WHERE x.guild_tag IS NOT NULL AND x.rank IS NOT NULL
  ),
  upd AS (
    UPDATE public.guild_config gc
    SET "GR_Ranking" = input.rank,
        updated_at   = now()
    FROM input
    WHERE gc.guild_code = input.guild_tag
    RETURNING 1
  )
  SELECT count(*)::integer INTO updated_count FROM upd;

  RETURN updated_count;
END;
$$;

