CREATE FUNCTION public.update_player_api_key(p_player_id text, p_api_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_result json;
BEGIN
  -- Get the authenticated user
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Update the API key
  UPDATE player_mapping
  SET
    tacticus_api_key = p_api_key,
    api_key_added_at = CASE
      WHEN p_api_key IS NOT NULL THEN NOW()
      ELSE NULL
    END,
    api_key_last_verified = NULL,
    api_key_is_valid = true
  WHERE
    player_id = p_player_id
    AND user_id = v_user_id
    AND is_current = true;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Player not found or not authorized');
  END IF;

  RETURN json_build_object('success', true, 'message', 'API key updated successfully');
END;
$$;

ALTER FUNCTION public.update_player_api_key(p_player_id text, p_api_key text) OWNER TO postgres;

CREATE FUNCTION public.update_player_api_key_admin(p_player_id text, p_encrypted_api_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role text;
    v_user_guild_code text;
    v_target_guild_code text;
    v_user_cluster text;
    v_target_cluster text;
    v_target_display_name text;
    v_result json;
BEGIN
    -- Check if user is authenticated
    IF auth.uid() IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'You must be logged in',
            'code', 'AUTH_REQUIRED'
        );
    END IF;

    -- Get user's role and guild
    SELECT role, guild_code INTO v_user_role, v_user_guild_code
    FROM player_mapping
    WHERE user_id = auth.uid()
      AND is_current = true
    LIMIT 1;

    IF v_user_role IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'User profile not found',
            'code', 'PROFILE_NOT_FOUND'
        );
    END IF;

    -- Check if user has permission (officer or leader)
    IF v_user_role NOT IN ('officer', 'leader') THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Only officers and leaders can manage API keys',
            'code', 'INSUFFICIENT_PERMISSIONS'
        );
    END IF;

    -- Get target player's guild and display name
    SELECT guild_code, display_name INTO v_target_guild_code, v_target_display_name
    FROM player_mapping
    WHERE player_id = p_player_id
      AND is_current = true
    LIMIT 1;

    IF v_target_guild_code IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Player not found',
            'code', 'PLAYER_NOT_FOUND'
        );
    END IF;

    -- Check permissions based on role
    IF v_user_role = 'officer' THEN
        -- Officers can only manage players in their guild
        IF v_target_guild_code != v_user_guild_code THEN
            RETURN json_build_object(
                'success', false,
                'error', 'You can only manage API keys for players in your guild',
                'code', 'WRONG_GUILD'
            );
        END IF;
    ELSIF v_user_role = 'leader' THEN
        -- Leaders can manage players in their cluster
        -- Get user's cluster
        SELECT gc.cluster_code INTO v_user_cluster
        FROM guild_config gc
        WHERE gc.guild_code = v_user_guild_code;

        -- Get target player's cluster
        SELECT gc.cluster_code INTO v_target_cluster
        FROM guild_config gc
        WHERE gc.guild_code = v_target_guild_code;

        -- Allow same guild or same cluster
        IF v_target_guild_code != v_user_guild_code AND
           (v_user_cluster IS NULL OR v_target_cluster IS NULL OR v_user_cluster != v_target_cluster) THEN
            RETURN json_build_object(
                'success', false,
                'error', 'You can only manage API keys for players in your guild or cluster',
                'code', 'WRONG_CLUSTER'
            );
        END IF;
    END IF;

    -- Update the API key
    UPDATE player_mapping
    SET
        tacticus_api_key_encrypted = p_encrypted_api_key,
        api_key_is_valid = true,
        api_key_last_verified = now(),
        updated_at = now()
    WHERE player_id = p_player_id
      AND is_current = true;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Failed to update player record',
            'code', 'UPDATE_FAILED'
        );
    END IF;

    -- Return success
    RETURN json_build_object(
        'success', true,
        'message', 'API key successfully updated for ' || v_target_display_name,
        'player_id', p_player_id,
        'display_name', v_target_display_name
    );
END;
$$;

ALTER FUNCTION public.update_player_api_key_admin(p_player_id text, p_encrypted_api_key text) OWNER TO postgres;

