CREATE FUNCTION public.update_player_guild_membership(p_player_id text, p_new_guild_code text, p_display_name text DEFAULT NULL::text, p_role text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_existing record;
    v_old_guild text;
    v_result jsonb;
BEGIN
    -- Check if player exists
    SELECT * INTO v_existing
    FROM player_mapping
    WHERE player_id = p_player_id;

    IF v_existing IS NULL THEN
        -- New player - create record
        INSERT INTO player_mapping (
            player_id,
            display_name,
            guild_code,
            role,
            is_current,
            is_active,
            auto_generated,
            created_at,
            updated_at
        ) VALUES (
            p_player_id,
            COALESCE(p_display_name, p_player_id),
            p_new_guild_code,
            COALESCE(p_role, 'member')::app_role,
            true,
            true,
            true,
            NOW(),
            NOW()
        );

        RETURN jsonb_build_object(
            'action', 'created',
            'player_id', p_player_id,
            'guild_code', p_new_guild_code
        );
    END IF;

    v_old_guild := v_existing.guild_code;

    -- Update existing player
    UPDATE player_mapping
    SET
        guild_code = p_new_guild_code,
        display_name = COALESCE(p_display_name, display_name),
        role = COALESCE(p_role::app_role, role),
        is_current = true,
        is_active = true,
        updated_at = NOW()
    WHERE player_id = p_player_id;

    -- Return transfer info if guild changed
    IF v_old_guild != p_new_guild_code THEN
        RETURN jsonb_build_object(
            'action', 'transferred',
            'player_id', p_player_id,
            'old_guild', v_old_guild,
            'new_guild', p_new_guild_code,
            'user_id_preserved', v_existing.user_id IS NOT NULL
        );
    ELSE
        RETURN jsonb_build_object(
            'action', 'updated',
            'player_id', p_player_id,
            'guild_code', p_new_guild_code
        );
    END IF;
END;
$$;

ALTER FUNCTION public.update_player_guild_membership(p_player_id text, p_new_guild_code text, p_display_name text, p_role text) OWNER TO postgres;

