CREATE FUNCTION public.update_registration_progress(guild_code_param text, new_status text, mark_completed boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    rows_updated INTEGER;
BEGIN
    UPDATE guild_config
    SET
        onboarding_completed = mark_completed OR (new_status = 'completed'),
        last_resume_attempt_at = now(),
        onboarding_completed_at = CASE
            WHEN mark_completed OR new_status = 'completed' THEN now()
            ELSE onboarding_completed_at
        END,
        updated_at = now()
    WHERE guild_code = UPPER(guild_code_param);

    GET DIAGNOSTICS rows_updated = ROW_COUNT;
    RETURN rows_updated > 0;
END;
$$;

ALTER FUNCTION public.update_registration_progress(guild_code_param text, new_status text, mark_completed boolean) OWNER TO postgres;

CREATE FUNCTION public.update_support_ticket_updated_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  BEGIN
      NEW.updated_at = NOW();

      -- If status is being changed to resolved/closed, set resolved_at
      IF NEW.status IN ('resolved', 'closed') AND OLD.status NOT IN ('resolved', 'closed') THEN
          NEW.resolved_at = NOW();
      END IF;

      RETURN NEW;
  END;
  $$;

ALTER FUNCTION public.update_support_ticket_updated_at() OWNER TO postgres;

CREATE FUNCTION public.update_support_unread_counters() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  BEGIN
    -- Update last message timestamp
    UPDATE support_tickets
    SET last_message_at = NEW.created_at
    WHERE id = NEW.ticket_id;

    IF NEW.is_admin_response THEN
      -- Admin sent message - increment user unread counter, reset admin counter
      UPDATE support_tickets
      SET
        user_unread_count = user_unread_count + 1,
        admin_unread_count = 0,
        last_admin_message_at = NEW.created_at
      WHERE id = NEW.ticket_id;

      -- Mark message as read by admin immediately
      NEW.read_by_admin_at = NEW.created_at;
    ELSE
      -- User sent message - increment admin unread counter, reset user counter
      UPDATE support_tickets
      SET
        admin_unread_count = admin_unread_count + 1,
        user_unread_count = 0,
        last_user_message_at = NEW.created_at
      WHERE id = NEW.ticket_id;

      -- Mark message as read by user immediately
      NEW.read_by_user_at = NEW.created_at;
    END IF;

    RETURN NEW;
  END;
  $$;

ALTER FUNCTION public.update_support_unread_counters() OWNER TO postgres;

CREATE FUNCTION public.update_sync_health(p_guild_code text, p_success boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO sync_health (guild_code, total_syncs)
  VALUES (p_guild_code, 1)
  ON CONFLICT (guild_code) DO UPDATE
  SET
    last_successful_sync = CASE WHEN p_success THEN NOW() ELSE sync_health.last_successful_sync END,
    last_failed_sync = CASE WHEN NOT p_success THEN NOW() ELSE sync_health.last_failed_sync END,
    consecutive_failures = CASE
      WHEN p_success THEN 0
      ELSE sync_health.consecutive_failures + 1
    END,
    total_syncs = sync_health.total_syncs + 1,
    success_rate = ((sync_health.success_rate * sync_health.total_syncs) + CASE WHEN p_success THEN 100 ELSE 0 END) / (sync_health.total_syncs + 1),
    health_status = CASE
      WHEN p_success THEN 'healthy'
      WHEN sync_health.consecutive_failures >= 5 THEN 'critical'
      WHEN sync_health.consecutive_failures >= 3 THEN 'unhealthy'
      WHEN sync_health.consecutive_failures >= 1 THEN 'degraded'
      ELSE 'healthy'
    END,
    updated_at = NOW();
END;
$$;

ALTER FUNCTION public.update_sync_health(p_guild_code text, p_success boolean) OWNER TO postgres;

CREATE FUNCTION public.update_token_burn_state_for_guild(p_guild_code text, p_season text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_season text;
  rec record;
  v_tokens int;
  v_next_seconds int;
begin
  if p_guild_code is null or length(trim(p_guild_code)) = 0 then
    return;
  end if;

  if p_season is null then
    select max("Season") into v_season
    from "EOT_GR_data"
    where "Guild" = p_guild_code;
  else
    v_season := p_season;
  end if;

  if v_season is null then
    return;
  end if;

  for rec in
    select distinct display_name, user_id
    from (
      select distinct "displayName" as display_name, "userId" as user_id
      from "EOT_GR_data"
      where "Guild" = p_guild_code
        and "Season" = v_season
        and "displayName" is not null
        and "userId" is not null
      union all
      select pm.display_name, pm.player_id as user_id
      from player_mapping pm
      where pm.guild_code = p_guild_code
        and pm.is_current = true
        and pm.display_name is not null
        and pm.player_id is not null
    ) src
  loop
    select tokens_available,
           floor(extract(epoch from time_until_next_token)) as next_seconds
    into v_tokens, v_next_seconds
    from calculate_player_tokens(rec.display_name, p_guild_code, v_season)
    limit 1;

    if v_tokens is null then
      continue;
    end if;

    perform record_token_burn_state(
      p_guild_code := p_guild_code,
      p_season := v_season,
      p_player_id := rec.user_id,
      p_display_name := rec.display_name,
      p_tokens_available := v_tokens,
      p_token_next_in_seconds := v_next_seconds
    );
  end loop;
end;
$$;

ALTER FUNCTION public.update_token_burn_state_for_guild(p_guild_code text, p_season text) OWNER TO postgres;

