ALTER FUNCTION public.upsert_herald_boss_config(p_guild_code text, p_boss_id text, p_rarity_set text, p_enabled boolean, p_webhook_config_ids uuid[], p_discord_role_ids text[], p_pinned_replay_ids uuid[], p_replay_auto_count integer, p_replay_link_mode text, p_extra_links jsonb, p_extra_videos jsonb, p_custom_message_url text, p_notes text, p_side1_notes text, p_side2_notes text, p_side1_behaviour text, p_side2_behaviour text, p_side1_threshold_hp_pct smallint, p_side2_threshold_hp_pct smallint, p_ping_mode text, p_updated_by uuid) OWNER TO postgres;

CREATE FUNCTION public.upsert_herald_boss_config(p_guild_code text, p_boss_id text, p_rarity_set text, p_enabled boolean, p_webhook_config_ids uuid[], p_discord_role_ids text[], p_discord_role_labels jsonb, p_pinned_replay_ids uuid[], p_replay_auto_count integer, p_replay_link_mode text, p_extra_links jsonb, p_extra_videos jsonb, p_custom_message_url text, p_notes text, p_side1_notes text, p_side2_notes text, p_side1_behaviour text, p_side2_behaviour text, p_side1_threshold_hp_pct smallint, p_side2_threshold_hp_pct smallint, p_ping_mode text, p_updated_by uuid) RETURNS public.herald_boss_config
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_row public.herald_boss_config;
  v_custom_url text := NULLIF(TRIM(COALESCE(p_custom_message_url, '')), '');
  v_side1_behaviour text := COALESCE(NULLIF(TRIM(COALESCE(p_side1_behaviour, '')), ''), 'kill');
  v_side2_behaviour text := COALESCE(NULLIF(TRIM(COALESCE(p_side2_behaviour, '')), ''), 'kill');
  v_ping_mode text := COALESCE(NULLIF(TRIM(COALESCE(p_ping_mode, '')), ''), 'per_side');
  v_replay_link_mode text := COALESCE(NULLIF(TRIM(COALESCE(p_replay_link_mode, '')), ''), 'inherit');
  v_role_labels jsonb := COALESCE(p_discord_role_labels, '{}'::jsonb);
  v_label_key text;
  v_label_value jsonb;
  v_label_text text;
BEGIN
  IF jsonb_typeof(v_role_labels) <> 'object' THEN
    RAISE EXCEPTION 'discord_role_labels must be an object';
  END IF;
  FOR v_label_key, v_label_value IN
    SELECT key, value FROM jsonb_each(v_role_labels)
  LOOP
    v_label_text := v_label_value #>> '{}';
    IF v_label_key !~ '^\d{17,20}$' THEN
      RAISE EXCEPTION 'discord_role_labels keys must be Discord role IDs';
    END IF;
    IF jsonb_typeof(v_label_value) <> 'string' THEN
      RAISE EXCEPTION 'discord_role_labels values must be strings';
    END IF;
    IF LENGTH(BTRIM(v_label_text)) = 0 OR LENGTH(BTRIM(v_label_text)) > 80 THEN
      RAISE EXCEPTION 'discord_role_labels values must be 1-80 characters';
    END IF;
    IF NOT v_label_key = ANY(COALESCE(p_discord_role_ids, ARRAY[]::text[])) THEN
      RAISE EXCEPTION 'discord_role_labels keys must also be present in discord_role_ids';
    END IF;
  END LOOP;
  IF v_custom_url IS NOT NULL AND v_custom_url !~ '^https?://' THEN
    RAISE EXCEPTION 'custom_message_url must be an http(s) URL'
      USING HINT = 'expected https://discord.com/channels/<guild>/<channel>/<message>';
  END IF;

  IF v_side1_behaviour NOT IN ('skip', 'kill', 'threshold') THEN
    RAISE EXCEPTION 'side1_behaviour must be skip, kill, or threshold';
  END IF;
  IF v_side2_behaviour NOT IN ('skip', 'kill', 'threshold') THEN
    RAISE EXCEPTION 'side2_behaviour must be skip, kill, or threshold';
  END IF;
  IF v_ping_mode NOT IN ('combined', 'per_side', 'skip_all') THEN
    RAISE EXCEPTION 'ping_mode must be combined, per_side, or skip_all';
  END IF;
  IF v_replay_link_mode NOT IN ('inherit', 'off', 'pinned', 'featured', 'all') THEN
    RAISE EXCEPTION 'replay_link_mode must be inherit, off, pinned, featured, or all';
  END IF;
  IF v_side1_behaviour = 'threshold'
     AND (p_side1_threshold_hp_pct IS NULL OR p_side1_threshold_hp_pct NOT BETWEEN 1 AND 100) THEN
    RAISE EXCEPTION 'side1_threshold_hp_pct is required when side1_behaviour is threshold';
  END IF;
  IF v_side2_behaviour = 'threshold'
     AND (p_side2_threshold_hp_pct IS NULL OR p_side2_threshold_hp_pct NOT BETWEEN 1 AND 100) THEN
    RAISE EXCEPTION 'side2_threshold_hp_pct is required when side2_behaviour is threshold';
  END IF;

  IF p_rarity_set IS NULL THEN
    INSERT INTO public.herald_boss_config AS t
      (guild_code, boss_id, rarity_set, enabled, webhook_config_ids,
       discord_role_ids, discord_role_labels, pinned_replay_ids,
       replay_auto_count, replay_link_mode, extra_links, extra_videos,
       custom_message_url, notes, side1_notes, side2_notes, side1_behaviour,
       side2_behaviour, side1_threshold_hp_pct, side2_threshold_hp_pct,
       ping_mode, ping_mode_explicit, updated_by, updated_at)
    VALUES
      (p_guild_code, p_boss_id, NULL, p_enabled, p_webhook_config_ids,
       p_discord_role_ids, v_role_labels, p_pinned_replay_ids,
       p_replay_auto_count, v_replay_link_mode, p_extra_links, p_extra_videos,
       v_custom_url, NULLIF(p_notes, ''), NULLIF(p_side1_notes, ''),
       NULLIF(p_side2_notes, ''), v_side1_behaviour, v_side2_behaviour,
       CASE WHEN v_side1_behaviour = 'threshold' THEN p_side1_threshold_hp_pct ELSE NULL END,
       CASE WHEN v_side2_behaviour = 'threshold' THEN p_side2_threshold_hp_pct ELSE NULL END,
       v_ping_mode, true, p_updated_by, now())
    ON CONFLICT (guild_code, boss_id) WHERE rarity_set IS NULL
    DO UPDATE SET
      enabled                 = EXCLUDED.enabled,
      webhook_config_ids      = EXCLUDED.webhook_config_ids,
      discord_role_ids        = EXCLUDED.discord_role_ids,
      discord_role_labels     = CASE
                                  WHEN p_discord_role_labels IS NULL THEN t.discord_role_labels
                                  ELSE EXCLUDED.discord_role_labels
                                END,
      pinned_replay_ids       = EXCLUDED.pinned_replay_ids,
      replay_auto_count       = EXCLUDED.replay_auto_count,
      replay_link_mode        = EXCLUDED.replay_link_mode,
      extra_links             = EXCLUDED.extra_links,
      extra_videos            = EXCLUDED.extra_videos,
      custom_message_url      = EXCLUDED.custom_message_url,
      notes                   = EXCLUDED.notes,
      side1_notes             = EXCLUDED.side1_notes,
      side2_notes             = EXCLUDED.side2_notes,
      side1_behaviour         = EXCLUDED.side1_behaviour,
      side2_behaviour         = EXCLUDED.side2_behaviour,
      side1_threshold_hp_pct  = EXCLUDED.side1_threshold_hp_pct,
      side2_threshold_hp_pct  = EXCLUDED.side2_threshold_hp_pct,
      ping_mode               = EXCLUDED.ping_mode,
      ping_mode_explicit      = true,
      updated_by              = EXCLUDED.updated_by,
      updated_at              = now()
    RETURNING t.* INTO v_row;
  ELSE
    INSERT INTO public.herald_boss_config AS t
      (guild_code, boss_id, rarity_set, enabled, webhook_config_ids,
       discord_role_ids, discord_role_labels, pinned_replay_ids,
       replay_auto_count, replay_link_mode, extra_links, extra_videos,
       custom_message_url, notes, side1_notes, side2_notes, side1_behaviour,
       side2_behaviour, side1_threshold_hp_pct, side2_threshold_hp_pct,
       ping_mode, ping_mode_explicit, updated_by, updated_at)
    VALUES
      (p_guild_code, p_boss_id, p_rarity_set, p_enabled, p_webhook_config_ids,
       p_discord_role_ids, v_role_labels, p_pinned_replay_ids,
       p_replay_auto_count, v_replay_link_mode, p_extra_links, p_extra_videos,
       v_custom_url, NULLIF(p_notes, ''), NULLIF(p_side1_notes, ''),
       NULLIF(p_side2_notes, ''), v_side1_behaviour, v_side2_behaviour,
       CASE WHEN v_side1_behaviour = 'threshold' THEN p_side1_threshold_hp_pct ELSE NULL END,
       CASE WHEN v_side2_behaviour = 'threshold' THEN p_side2_threshold_hp_pct ELSE NULL END,
       v_ping_mode, true, p_updated_by, now())
    ON CONFLICT (guild_code, boss_id, rarity_set) WHERE rarity_set IS NOT NULL
    DO UPDATE SET
      enabled                 = EXCLUDED.enabled,
      webhook_config_ids      = EXCLUDED.webhook_config_ids,
      discord_role_ids        = EXCLUDED.discord_role_ids,
      discord_role_labels     = CASE
                                  WHEN p_discord_role_labels IS NULL THEN t.discord_role_labels
                                  ELSE EXCLUDED.discord_role_labels
                                END,
      pinned_replay_ids       = EXCLUDED.pinned_replay_ids,
      replay_auto_count       = EXCLUDED.replay_auto_count,
      replay_link_mode        = EXCLUDED.replay_link_mode,
      extra_links             = EXCLUDED.extra_links,
      extra_videos            = EXCLUDED.extra_videos,
      custom_message_url      = EXCLUDED.custom_message_url,
      notes                   = EXCLUDED.notes,
      side1_notes             = EXCLUDED.side1_notes,
      side2_notes             = EXCLUDED.side2_notes,
      side1_behaviour         = EXCLUDED.side1_behaviour,
      side2_behaviour         = EXCLUDED.side2_behaviour,
      side1_threshold_hp_pct  = EXCLUDED.side1_threshold_hp_pct,
      side2_threshold_hp_pct  = EXCLUDED.side2_threshold_hp_pct,
      ping_mode               = EXCLUDED.ping_mode,
      ping_mode_explicit      = true,
      updated_by              = EXCLUDED.updated_by,
      updated_at              = now()
    RETURNING t.* INTO v_row;
  END IF;
  RETURN v_row;
END;
$_$;

ALTER FUNCTION public.upsert_herald_boss_config(p_guild_code text, p_boss_id text, p_rarity_set text, p_enabled boolean, p_webhook_config_ids uuid[], p_discord_role_ids text[], p_discord_role_labels jsonb, p_pinned_replay_ids uuid[], p_replay_auto_count integer, p_replay_link_mode text, p_extra_links jsonb, p_extra_videos jsonb, p_custom_message_url text, p_notes text, p_side1_notes text, p_side2_notes text, p_side1_behaviour text, p_side2_behaviour text, p_side1_threshold_hp_pct smallint, p_side2_threshold_hp_pct smallint, p_ping_mode text, p_updated_by uuid) OWNER TO postgres;

CREATE TABLE public.herald_meta_role_mapping (
    id bigint NOT NULL,
    guild_code text NOT NULL,
    meta_team_slug text NOT NULL,
    discord_role_id text,
    display_label text,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    active_boss_ids text[],
    auto_update boolean DEFAULT false NOT NULL,
    last_auto_updated_at timestamp with time zone,
    rarity_set text,
    prime_scope text DEFAULT 'all'::text NOT NULL,
    track_only boolean DEFAULT false NOT NULL,
    custom_message_only boolean DEFAULT false NOT NULL,
    CONSTRAINT herald_meta_role_mapping_prime_scope_check CHECK ((prime_scope = ANY (ARRAY['main'::text, 'prime_a'::text, 'prime_b'::text, 'all'::text]))),
    CONSTRAINT herald_meta_role_mapping_rarity_set_format CHECK (((rarity_set IS NULL) OR (rarity_set ~ '^[LM][1-5]$'::text))),
    CONSTRAINT herald_meta_role_mapping_role_id_format CHECK (((discord_role_id IS NULL) OR (discord_role_id ~ '^\d{17,20}$'::text))),
    CONSTRAINT herald_meta_role_mapping_slug_format CHECK (((meta_team_slug = TRIM(BOTH FROM meta_team_slug)) AND ((char_length(meta_team_slug) >= 1) AND (char_length(meta_team_slug) <= 80))))
);

ALTER TABLE public.herald_meta_role_mapping OWNER TO postgres;

CREATE FUNCTION public.upsert_herald_role_mapping(p_guild_code text, p_meta_team_slug text, p_rarity_set text, p_discord_role_id text, p_display_label text, p_enabled boolean, p_active_boss_ids text[], p_auto_update boolean, p_prime_scope text, p_track_only boolean, p_custom_message_only boolean, p_updated_by uuid) RETURNS public.herald_meta_role_mapping
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.herald_meta_role_mapping;
  v_prime_scope text := COALESCE(NULLIF(p_prime_scope, ''), 'all');
  v_track_only boolean := COALESCE(p_track_only, false);
  v_custom_only boolean := COALESCE(p_custom_message_only, false);
BEGIN
  IF v_prime_scope NOT IN ('main', 'prime_a', 'prime_b', 'all') THEN
    RAISE EXCEPTION 'invalid prime_scope: %', v_prime_scope
      USING HINT = 'must be one of: main, prime_a, prime_b, all';
  END IF;

  IF p_rarity_set IS NULL THEN
    INSERT INTO public.herald_meta_role_mapping AS t
      (guild_code, meta_team_slug, rarity_set, discord_role_id,
       display_label, enabled, active_boss_ids, auto_update,
       prime_scope, track_only, custom_message_only,
       updated_by, updated_at)
    VALUES
      (p_guild_code, p_meta_team_slug, NULL, p_discord_role_id,
       p_display_label, p_enabled, p_active_boss_ids, p_auto_update,
       v_prime_scope, v_track_only, v_custom_only,
       p_updated_by, now())
    ON CONFLICT (guild_code, meta_team_slug) WHERE rarity_set IS NULL
    DO UPDATE SET
      discord_role_id     = EXCLUDED.discord_role_id,
      display_label       = EXCLUDED.display_label,
      enabled             = EXCLUDED.enabled,
      active_boss_ids     = EXCLUDED.active_boss_ids,
      auto_update         = EXCLUDED.auto_update,
      prime_scope         = EXCLUDED.prime_scope,
      track_only          = EXCLUDED.track_only,
      custom_message_only = EXCLUDED.custom_message_only,
      updated_by          = EXCLUDED.updated_by,
      updated_at          = now()
    RETURNING t.* INTO v_row;
  ELSE
    INSERT INTO public.herald_meta_role_mapping AS t
      (guild_code, meta_team_slug, rarity_set, discord_role_id,
       display_label, enabled, active_boss_ids, auto_update,
       prime_scope, track_only, custom_message_only,
       updated_by, updated_at)
    VALUES
      (p_guild_code, p_meta_team_slug, p_rarity_set, p_discord_role_id,
       p_display_label, p_enabled, p_active_boss_ids, p_auto_update,
       v_prime_scope, v_track_only, v_custom_only,
       p_updated_by, now())
    ON CONFLICT (guild_code, meta_team_slug, rarity_set) WHERE rarity_set IS NOT NULL
    DO UPDATE SET
      discord_role_id     = EXCLUDED.discord_role_id,
      display_label       = EXCLUDED.display_label,
      enabled             = EXCLUDED.enabled,
      active_boss_ids     = EXCLUDED.active_boss_ids,
      auto_update         = EXCLUDED.auto_update,
      prime_scope         = EXCLUDED.prime_scope,
      track_only          = EXCLUDED.track_only,
      custom_message_only = EXCLUDED.custom_message_only,
      updated_by          = EXCLUDED.updated_by,
      updated_at          = now()
    RETURNING t.* INTO v_row;
  END IF;
  RETURN v_row;
END;
$$;

ALTER FUNCTION public.upsert_herald_role_mapping(p_guild_code text, p_meta_team_slug text, p_rarity_set text, p_discord_role_id text, p_display_label text, p_enabled boolean, p_active_boss_ids text[], p_auto_update boolean, p_prime_scope text, p_track_only boolean, p_custom_message_only boolean, p_updated_by uuid) OWNER TO postgres;

CREATE FUNCTION public.upsert_subscription_from_stripe(p_guild_code text, p_stripe_customer_id text, p_stripe_subscription_id text, p_status text, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean DEFAULT false, p_canceled_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    INSERT INTO guild_subscriptions (
        guild_code,
        tier,
        stripe_customer_id,
        stripe_subscription_id,
        status,
        current_period_start,
        current_period_end,
        cancel_at_period_end,
        canceled_at
    ) VALUES (
        p_guild_code,
        'premium',
        p_stripe_customer_id,
        p_stripe_subscription_id,
        p_status,
        p_current_period_start,
        p_current_period_end,
        p_cancel_at_period_end,
        p_canceled_at
    )
    ON CONFLICT (guild_code) DO UPDATE SET
        stripe_customer_id = EXCLUDED.stripe_customer_id,
        stripe_subscription_id = EXCLUDED.stripe_subscription_id,
        status = EXCLUDED.status,
        current_period_start = EXCLUDED.current_period_start,
        current_period_end = EXCLUDED.current_period_end,
        cancel_at_period_end = EXCLUDED.cancel_at_period_end,
        canceled_at = EXCLUDED.canceled_at,
        updated_at = now();

    RETURN jsonb_build_object('success', true);
END;
$$;

ALTER FUNCTION public.upsert_subscription_from_stripe(p_guild_code text, p_stripe_customer_id text, p_stripe_subscription_id text, p_status text, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_canceled_at timestamp with time zone) OWNER TO postgres;

CREATE FUNCTION public.user_guild_restricts_playbooks(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_restricts BOOLEAN;
BEGIN
  SELECT gc.restrict_playbooks_to_assignments
  INTO v_restricts
  FROM player_mapping pm
  JOIN guild_config gc ON gc.guild_code = pm.guild_code
  WHERE pm.user_id = p_user_id
  LIMIT 1;

  RETURN COALESCE(v_restricts, FALSE);
END;
$$;

ALTER FUNCTION public.user_guild_restricts_playbooks(p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.validate_and_use_invite_code(p_code text, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_auth_uid uuid := auth.uid();
  v_request_role text := coalesce(
    nullif(nullif(current_setting('role', true), ''), 'none'),
    session_user
  );
  v_invite record;
  v_invite_ids uuid[];
  v_mapping_ids integer[];
  v_mapping record;
  v_attestation_id uuid := gen_random_uuid();
BEGIN
  IF v_request_role <> 'authenticated' OR v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required to claim an invite code'
      USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL OR p_user_id IS DISTINCT FROM v_auth_uid THEN
    RAISE EXCEPTION 'Invite claims may only target the authenticated user'
      USING ERRCODE = '42501';
  END IF;
  IF p_code IS NULL OR length(btrim(p_code)) < 6 OR length(p_code) > 64 THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Invalid or expired invite code',
      'error_code', 'INVALID_CODE'
    );
  END IF;

  -- Claims, account preparation, and Auth deletion serialize on the same
  -- subject key. The Auth row lock prevents a successful claim from racing a
  -- concurrent DELETE; the append-only block survives provider deletion
  -- failure and stale JWTs.
  PERFORM pg_advisory_xact_lock(6208, hashtext(v_auth_uid::text));
  IF EXISTS (
    SELECT 1
    FROM public.player_identity_subject_authority_blocks AS block
    WHERE block.subject_user_id = v_auth_uid
  ) THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Account authority is permanently blocked',
      'error_code', 'SUBJECT_AUTHORITY_BLOCKED'
    );
  END IF;
  PERFORM 1
  FROM auth.users AS subject
  WHERE subject.id = v_auth_uid
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Authenticated account no longer exists',
      'error_code', 'AUTH_SUBJECT_ABSENT'
    );
  END IF;

  -- Deterministic order: exact invite first, then every candidate mapping by id.
  -- WI-6240: a possession-proof code (PP6240-) is NEVER an officer invite -- it
  -- belongs to the transfer corridor and must not resolve here.
  SELECT array_agg(locked.id ORDER BY locked.id)
  INTO v_invite_ids
  FROM (
    SELECT invite.id
    FROM public.player_invite_codes AS invite
    WHERE invite.code = upper(btrim(p_code))
      AND invite.used_at IS NULL
      AND invite.revoked_at IS NULL
      AND invite.expires_at > clock_timestamp()
      AND NOT public.is_possession_proof_code(invite.code)
    ORDER BY invite.id
    FOR UPDATE
  ) AS locked;
  IF cardinality(v_invite_ids) IS DISTINCT FROM 1 THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Invalid or expired invite code',
      'error_code', CASE
        WHEN cardinality(v_invite_ids) > 1 THEN 'INVITE_NOT_EXACT'
        ELSE 'INVALID_CODE'
      END
    );
  END IF;
  SELECT invite.id, invite.player_id, invite.display_name,
         invite.guild_code, invite.expires_at
  INTO STRICT v_invite
  FROM public.player_invite_codes AS invite
  WHERE invite.id = v_invite_ids[1];

  SELECT array_agg(locked.id ORDER BY locked.id)
  INTO v_mapping_ids
  FROM (
    SELECT mapping.id
    FROM public.player_mapping AS mapping
    WHERE mapping.player_id = v_invite.player_id
      AND mapping.guild_code = v_invite.guild_code
      AND mapping.is_current IS TRUE
    ORDER BY mapping.id
    FOR UPDATE
  ) AS locked;
  IF cardinality(v_mapping_ids) IS DISTINCT FROM 1 THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Invite does not identify one current mapping',
      'error_code', 'MAPPING_NOT_EXACT'
    );
  END IF;

  SELECT mapping.id, mapping.player_id, mapping.display_name,
         mapping.guild_code, mapping.user_id
  INTO v_mapping
  FROM public.player_mapping AS mapping
  WHERE mapping.id = v_mapping_ids[1];
  IF v_mapping.user_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'This player profile has already been claimed',
      'error_code', 'ALREADY_CLAIMED'
    );
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.player_mapping AS existing
    WHERE existing.user_id = v_auth_uid AND existing.is_current IS TRUE
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'You already have a claimed profile. Contact support to change it.',
      'error_code', 'USER_HAS_PROFILE'
    );
  END IF;

  INSERT INTO public.player_identity_attestations (
    id, mapping_id, player_id, subject_user_id, source_invite_id,
    consumed_at, attested_at, source, guild_code_snapshot
  ) VALUES (
    v_attestation_id, v_mapping.id, v_mapping.player_id, v_auth_uid,
    v_invite.id, clock_timestamp(), clock_timestamp(),
    'invite_consumption', v_mapping.guild_code
  );
  UPDATE public.player_invite_codes AS invite
  SET used_at = clock_timestamp(), used_by = v_auth_uid
  WHERE invite.id = v_invite.id;
  UPDATE public.player_mapping AS mapping
  SET user_id = v_auth_uid,
      ownership_attestation_id = v_attestation_id,
      updated_at = clock_timestamp()
  WHERE mapping.id = v_mapping.id;

  UPDATE auth.users AS target
  SET raw_user_meta_data = jsonb_set(
    coalesce(target.raw_user_meta_data, '{}'::jsonb),
    '{role}', '"member"'::jsonb, true
  )
  WHERE target.id = v_auth_uid
    AND target.raw_user_meta_data ->> 'role' = 'onboarding';

  INSERT INTO public.player_claim_audit (
    user_id, player_id, guild_code, source_path, outcome, details
  ) VALUES (
    v_auth_uid, v_mapping.player_id, v_mapping.guild_code,
    'invite/consume', 'success',
    jsonb_build_object(
      'mapping_id', v_mapping.id,
      'attestation_id', v_attestation_id,
      'invite_id', v_invite.id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'player_id', v_mapping.player_id,
    'display_name', v_mapping.display_name,
    'guild_code', v_mapping.guild_code,
    'mapping_id', v_mapping.id,
    'attestation_id', v_attestation_id
  );
EXCEPTION
  WHEN unique_violation OR exclusion_violation THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'The invite or user profile was claimed concurrently',
      'error_code', 'CLAIM_CONFLICT'
    );
END
$$;

ALTER FUNCTION public.validate_and_use_invite_code(p_code text, p_user_id uuid) OWNER TO postgres;

CREATE FUNCTION public.validate_guild_in_cluster(p_guild_code character varying, p_cluster_code character varying) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_exists BOOLEAN;
BEGIN
  SELECT EXISTS(
    SELECT 1
    FROM guild_config gc
    LEFT JOIN clusters c ON gc.cluster_id = c.id
    WHERE gc.guild_code = p_guild_code
    AND c.cluster_code = p_cluster_code
    AND gc.enabled = true
  ) INTO v_exists;

  RETURN v_exists;
END;
$$;

ALTER FUNCTION public.validate_guild_in_cluster(p_guild_code character varying, p_cluster_code character varying) OWNER TO postgres;

