    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN NOT EXISTS (
    SELECT 1 FROM guild_config
    WHERE guild_code = p_guild_code
  );
END;
$$;

