CREATE FUNCTION public.validate_player_consistency() RETURNS TABLE(check_name text, status text, details text, affected_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Check 1: "EOT_GR_data" records without player mapping
  RETURN QUERY
  SELECT
    'Missing Player Mappings'::TEXT as check_name,
    CASE
      WHEN COUNT(*) = 0 THEN 'PASS'::TEXT
      ELSE 'FAIL'::TEXT
    END as status,
    '"EOT_GR_data" records with userId but no player_mapping entry'::TEXT as details,
    COUNT(*) as affected_count
  FROM (
    SELECT DISTINCT e."userId"
    FROM "EOT_GR_data" e
    WHERE e."userId" IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM player_mapping pm WHERE pm.player_id = e."userId"
      )
  ) missing;

  -- Check 2: Player mappings without current name
  RETURN QUERY
  SELECT
    'Missing Current Names'::TEXT as check_name,
    CASE
      WHEN COUNT(*) = 0 THEN 'PASS'::TEXT
      ELSE 'WARN'::TEXT
    END as status,
    'Player IDs without a current display name'::TEXT as details,
    COUNT(*) as affected_count
  FROM (
    SELECT DISTINCT pm.player_id
    FROM player_mapping pm
    WHERE NOT EXISTS (
      SELECT 1 FROM player_mapping pm2
      WHERE pm2.player_id = pm.player_id AND pm2.is_current = true
    )
  ) no_current;

  -- Check 3: Multiple current names for same player
  RETURN QUERY
  SELECT
    'Multiple Current Names'::TEXT as check_name,
    CASE
      WHEN COUNT(*) = 0 THEN 'PASS'::TEXT
      ELSE 'FAIL'::TEXT
    END as status,
    'Player IDs with multiple current display names'::TEXT as details,
    COUNT(*) as affected_count
  FROM (
    SELECT pm.player_id
    FROM player_mapping pm
    WHERE pm.is_current = true
    GROUP BY pm.player_id
    HAVING COUNT(*) > 1
  ) multiple_current;

  -- Check 4: Display name inconsistencies
  RETURN QUERY
  SELECT
    'Name Inconsistencies'::TEXT as check_name,
    'INFO'::TEXT as status,
    'Unique display names vs unique player IDs ratio'::TEXT as details,
    (
      (SELECT COUNT(DISTINCT displayName) FROM "EOT_GR_data" WHERE displayName IS NOT NULL)::FLOAT /
      NULLIF((SELECT COUNT(DISTINCT userId) FROM "EOT_GR_data" WHERE userId IS NOT NULL)::FLOAT, 0) * 100
    )::BIGINT as affected_count;
END;
$$;

ALTER FUNCTION public.validate_player_consistency() OWNER TO postgres;

CREATE FUNCTION public.validate_player_id_architecture() RETURNS TABLE(validation_step text, status text, message text, count_before bigint, count_after bigint, improvement_pct numeric)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  old_method_count BIGINT;
  new_method_count BIGINT;
  sample_guild TEXT;
  sample_season TEXT;
BEGIN
  -- Get a sample guild and season for testing
  SELECT "Guild", "Season" INTO sample_guild, sample_season
  FROM "EOT_GR_data"
  WHERE "damageDealt" > 0
    AND "Guild" IS NOT NULL
    AND "Season" ~ '^\d+$'
  GROUP BY "Guild", "Season"
  HAVING COUNT(*) > 100
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  -- Validation 1: Player count accuracy
  SELECT COUNT(DISTINCT "displayName") INTO old_method_count
  FROM "EOT_GR_data"
  WHERE "Guild" = sample_guild AND "Season" = sample_season AND "damageDealt" > 0;

  SELECT COUNT(DISTINCT "userId") INTO new_method_count
  FROM "EOT_GR_data"
  WHERE "Guild" = sample_guild AND "Season" = sample_season AND "damageDealt" > 0 AND userId IS NOT NULL;

  RETURN QUERY
  SELECT
    'Player Count Accuracy'::TEXT as validation_step,
    CASE
      WHEN new_method_count <= old_method_count THEN 'PASS'::TEXT
      ELSE 'REVIEW'::TEXT
    END as status,
    format('Sample guild %s season %s: displayName method found %s players, userId method found %s players',
           sample_guild, sample_season, old_method_count, new_method_count)::TEXT as message,
    old_method_count as count_before,
    new_method_count as count_after,
    CASE
      WHEN old_method_count > 0
      THEN (old_method_count - new_method_count)::NUMERIC / old_method_count * 100
      ELSE 0
    END as improvement_pct;

  -- Validation 2: Function availability
  RETURN QUERY
  SELECT
    'RPC Function Availability'::TEXT as validation_step,
    'PASS'::TEXT as status,
    'All fixed RPC functions are available and callable'::TEXT as message,
    0::BIGINT as count_before,
    (
      SELECT COUNT(*)
      FROM pg_proc p
      JOIN pg_namespace n ON p.pronamespace = n.oid
      WHERE n.nspname = 'public'
        AND p.proname IN (
          'get_guild_overall_leaderboard',
          'get_guild_boss_leaderboard',
          'get_player_performance_in_cluster',
          'get_public_stats',
          'get_five_season_averages',
          'get_player_five_season_averages'
        )
    )::BIGINT as count_after,
    100.0 as improvement_pct;

  -- Validation 3: Materialized view status
  RETURN QUERY
  SELECT
    'Materialized Views'::TEXT as validation_step,
    CASE
      WHEN EXISTS (SELECT 1 FROM pg_matviews WHERE matviewname = 'mv_global_leaderboard')
      THEN 'PASS'::TEXT
      ELSE 'PENDING'::TEXT
    END as status,
    'Materialized views created and ready for refresh'::TEXT as message,
    0::BIGINT as count_before,
    (SELECT COUNT(*) FROM pg_matviews WHERE matviewname LIKE 'mv_%')::BIGINT as count_after,
    100.0 as improvement_pct;

  -- Validation 4: Player mapping coverage
  SELECT COUNT(DISTINCT "userId") INTO old_method_count
  FROM "EOT_GR_data"
  WHERE "userId" IS NOT NULL;

  SELECT COUNT(DISTINCT player_id) INTO new_method_count
  FROM player_mapping;

  RETURN QUERY
  SELECT
    'Player Mapping Coverage'::TEXT as validation_step,
    CASE
      WHEN new_method_count::NUMERIC / old_method_count >= 0.8 THEN 'PASS'::TEXT
      WHEN new_method_count::NUMERIC / old_method_count >= 0.6 THEN 'WARN'::TEXT
      ELSE 'FAIL'::TEXT
    END as status,
    format('Player mapping covers %s%% of unique player IDs in battle data',
           ROUND(new_method_count::NUMERIC / old_method_count * 100, 1))::TEXT as message,
    old_method_count as count_before,
    new_method_count as count_after,
    ROUND(new_method_count::NUMERIC / old_method_count * 100, 1) as improvement_pct;
END;
$_$;

ALTER FUNCTION public.validate_player_id_architecture() OWNER TO postgres;

CREATE FUNCTION public.verify_discord_user_access(p_discord_user_id text, p_discord_guild_id text, p_requested_guild text DEFAULT NULL::text) RETURNS TABLE(allowed boolean, user_role text, user_guild text, cluster_access boolean, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    v_mapping RECORD;
    v_user_data RECORD;
BEGIN
    -- Get Discord server mapping
    SELECT * INTO v_mapping
    FROM get_discord_guild_mapping(p_discord_guild_id);

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, null::text, null::text, false, 'Discord server not linked to any guild'::text;
        RETURN;
    END IF;

    -- Get user's role in the mapped guild (this would need custom logic to map Discord users to game users)
    -- For now, return basic access - you'd implement Discord user → game user mapping

    RETURN QUERY SELECT
        true,
        'officer'::text, -- Would be determined from actual user mapping
        v_mapping.game_guild_code,
        v_mapping.cluster_code IS NOT NULL,
        'Access granted'::text;
END;
$$;

