);

ALTER TABLE monitoring.application_slow_queries OWNER TO postgres;

CREATE VIEW monitoring.app_query_summary AS
 SELECT query_name,
    count(*) AS execution_count,
    avg(duration_ms) AS avg_duration_ms,
    max(duration_ms) AS max_duration_ms,
    min(duration_ms) AS min_duration_ms,
    percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((duration_ms)::double precision)) AS median_duration_ms,
    percentile_cont((0.95)::double precision) WITHIN GROUP (ORDER BY ((duration_ms)::double precision)) AS p95_duration_ms,
    percentile_cont((0.99)::double precision) WITHIN GROUP (ORDER BY ((duration_ms)::double precision)) AS p99_duration_ms,
    count(DISTINCT user_id) AS unique_users,
    count(
        CASE
            WHEN (error IS NOT NULL) THEN 1
            ELSE NULL::integer
        END) AS error_count,
    max(logged_at) AS last_executed
   FROM monitoring.application_slow_queries
  WHERE (logged_at >= (now() - '24:00:00'::interval))
  GROUP BY query_name
  ORDER BY (avg(duration_ms)) DESC;

ALTER VIEW monitoring.app_query_summary OWNER TO postgres;

