CREATE TABLE monitoring.slow_queries (
    id integer NOT NULL,
    query_id bigint,
    query text,
    duration_ms numeric(10,2),
    calls bigint,
    mean_ms numeric(10,2),
    min_ms numeric(10,2),
    max_ms numeric(10,2),
    total_ms numeric(10,2),
    stddev_ms numeric(10,2),
    rows_returned bigint,
    shared_blks_hit bigint,
    shared_blks_read bigint,
    logged_at timestamp without time zone DEFAULT now(),
    query_fingerprint text GENERATED ALWAYS AS (md5(query)) STORED
);

ALTER TABLE monitoring.slow_queries OWNER TO postgres;

CREATE VIEW monitoring.current_slow_queries AS
 SELECT query_fingerprint,
    count(*) AS occurrences,
    avg(duration_ms) AS avg_duration_ms,
    max(duration_ms) AS max_duration_ms,
    min(duration_ms) AS min_duration_ms,
    sum(calls) AS total_calls,
    max(logged_at) AS last_seen,
    ("substring"(max(query), 1, 100) || '...'::text) AS query_sample
   FROM monitoring.slow_queries
  WHERE (logged_at >= (now() - '24:00:00'::interval))
  GROUP BY query_fingerprint
  ORDER BY (avg(duration_ms)) DESC;

ALTER VIEW monitoring.current_slow_queries OWNER TO postgres;

