    last_triggered timestamp without time zone
);

ALTER TABLE monitoring.query_alerts OWNER TO postgres;

CREATE SEQUENCE monitoring.query_alerts_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE monitoring.query_alerts_id_seq OWNER TO postgres;

ALTER SEQUENCE monitoring.query_alerts_id_seq OWNED BY monitoring.query_alerts.id;

CREATE VIEW monitoring.query_performance_trends AS
 SELECT date_trunc('hour'::text, logged_at) AS hour,
    count(DISTINCT query_fingerprint) AS unique_slow_queries,
    avg(duration_ms) AS avg_duration_ms,
    max(duration_ms) AS max_duration_ms,
    min(duration_ms) AS min_duration_ms,
    count(*) AS total_slow_queries
   FROM monitoring.slow_queries
  WHERE (logged_at >= (now() - '7 days'::interval))
  GROUP BY (date_trunc('hour'::text, logged_at))
  ORDER BY (date_trunc('hour'::text, logged_at)) DESC;

ALTER VIEW monitoring.query_performance_trends OWNER TO postgres;

CREATE VIEW monitoring.resource_intensive_queries AS
 SELECT query_fingerprint,
    sum(total_ms) AS total_time_ms,
    sum(calls) AS total_calls,
    avg(duration_ms) AS avg_duration_ms,
    sum(rows_returned) AS total_rows,
        CASE
            WHEN (avg(duration_ms) > (0)::numeric) THEN avg(((rows_returned)::numeric / duration_ms))
            ELSE (0)::numeric
        END AS rows_per_ms,
    "substring"(max(query), 1, 200) AS query_text
   FROM monitoring.slow_queries
  WHERE (logged_at >= (now() - '7 days'::interval))
  GROUP BY query_fingerprint
  ORDER BY (sum(total_ms)) DESC
 LIMIT 20;

ALTER VIEW monitoring.resource_intensive_queries OWNER TO postgres;

