CREATE VIEW public.api_key_coverage AS
 SELECT gc.guild_code,
    gc.display_name AS guild_name,
    gc.cluster_code,
    count(DISTINCT pm.player_id) AS total_players,
    count(DISTINCT
        CASE
            WHEN (pm.is_active = true) THEN pm.player_id
            ELSE NULL::text
        END) AS active_players,
    count(DISTINCT
        CASE
            WHEN (pm.user_id IS NOT NULL) THEN pm.player_id
            ELSE NULL::text
        END) AS players_claimed,
    count(DISTINCT
        CASE
            WHEN ((pm.tacticus_api_key_encrypted IS NOT NULL) AND (pm.tacticus_api_key_encrypted <> ''::text) AND (pm.api_key_is_valid = true)) THEN pm.player_id
            ELSE NULL::text
        END) AS players_with_api_key,
        CASE
            WHEN (count(DISTINCT pm.player_id) > 0) THEN round((((count(DISTINCT
            CASE
                WHEN ((pm.tacticus_api_key_encrypted IS NOT NULL) AND (pm.tacticus_api_key_encrypted <> ''::text) AND (pm.api_key_is_valid = true)) THEN pm.player_id
                ELSE NULL::text
            END))::numeric / (count(DISTINCT pm.player_id))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS coverage_percentage,
    count(DISTINCT
        CASE
            WHEN ((pm.tacticus_api_key_encrypted IS NOT NULL) AND (pm.tacticus_api_key_encrypted <> ''::text) AND (pm.api_key_is_valid = true)) THEN pm.player_id
            ELSE NULL::text
        END) AS valid_keys,
    count(DISTINCT
        CASE
            WHEN ((pm.tacticus_api_key_encrypted IS NOT NULL) AND (pm.tacticus_api_key_encrypted <> ''::text) AND (pm.api_key_is_valid = false)) THEN pm.player_id
            ELSE NULL::text
        END) AS invalid_keys,
        CASE
            WHEN ((gc.api_key_encrypted IS NOT NULL) AND (gc.api_key_encrypted <> ''::text)) THEN 'configured'::text
            ELSE 'not_configured'::text
        END AS guild_api_status,
    max(pm.api_key_last_verified) AS last_verified
   FROM (public.guild_config gc
     LEFT JOIN public.player_mapping pm ON (((pm.guild_code = gc.guild_code) AND (pm.is_current = true))))
  WHERE (gc.enabled = true)
  GROUP BY gc.guild_code, gc.display_name, gc.cluster_code, gc.api_key_encrypted;

