CREATE VIEW public.global_leaderboard WITH (security_invoker='true') AS
 WITH current_season AS (
         SELECT max("EOT_GR_data"."Season") AS season
           FROM public."EOT_GR_data"
        ), player_stats AS (
         SELECT e."displayName" AS display_name,
            e."Guild" AS guild_code,
            e.cluster_code,
            gc.display_name AS guild_display_name,
            COALESCE(c.display_name, 'Independent'::character varying) AS cluster_display_name,
            count(*) AS battle_count,
            sum(e."damageDealt") AS total_damage,
            avg(e."damageDealt") AS avg_damage,
            max(e."damageDealt") AS max_damage
           FROM (((public."EOT_GR_data" e
             CROSS JOIN current_season cs)
             LEFT JOIN public.guild_config gc ON ((gc.guild_code = e."Guild")))
             LEFT JOIN public.clusters c ON (((c.cluster_code)::text = (e.cluster_code)::text)))
          WHERE ((e."Season" = cs.season) AND (e."damageDealt" > 0))
          GROUP BY e."displayName", e."Guild", e.cluster_code, gc.display_name, c.display_name
        )
 SELECT row_number() OVER (ORDER BY total_damage DESC) AS rank,
    display_name,
    guild_code,
    guild_display_name,
    cluster_display_name,
    battle_count,
    total_damage,
    round(avg_damage, 0) AS avg_damage,
    max_damage,
    round(((((total_damage / NULLIF(max(total_damage) OVER (), (0)::numeric)) * (60)::numeric) + ((avg_damage / NULLIF(max(avg_damage) OVER (), (0)::numeric)) * (30)::numeric)) + (((battle_count)::numeric / (NULLIF(max(battle_count) OVER (), 0))::numeric) * (10)::numeric)), 1) AS performance_score
   FROM player_stats
  ORDER BY total_damage DESC;

ALTER VIEW public.global_leaderboard OWNER TO postgres;

