CREATE MATERIALIZED VIEW public.guild_veterans_count AS
 WITH season_range AS (
         SELECT (max(("EOT_GR_data"."Season")::integer) - 5) AS start_season,
            (max(("EOT_GR_data"."Season")::integer) - 1) AS end_season
           FROM public."EOT_GR_data"
          WHERE ("EOT_GR_data"."Season" ~ '^\d+$'::text)
        ), player_season_guilds AS (
         SELECT DISTINCT d."displayName",
            d."Guild",
            d."Season"
           FROM (public."EOT_GR_data" d
             CROSS JOIN season_range sr)
          WHERE (((d."Season")::integer >= sr.start_season) AND ((d."Season")::integer <= sr.end_season) AND (d."damageType" = 'Battle'::text) AND (d."Guild" <> ALL (ARRAY['EOT'::text, 'TEST'::text, 'TBD'::text])))
        ), player_season_counts AS (
         SELECT player_season_guilds."displayName",
            count(DISTINCT player_season_guilds."Season") AS season_count
           FROM player_season_guilds
          GROUP BY player_season_guilds."displayName"
        ), five_season_players AS (
         SELECT player_season_counts."displayName"
           FROM player_season_counts
          WHERE (player_season_counts.season_count = 5)
        ), guild_veteran_counts AS (
         SELECT d."Guild" AS guild_code,
            count(DISTINCT d."displayName") AS veteran_count
           FROM public."EOT_GR_data" d
          WHERE ((d."Season" = ( SELECT (max(("EOT_GR_data"."Season")::integer))::text AS max
                   FROM public."EOT_GR_data"
                  WHERE ("EOT_GR_data"."Season" ~ '^\d+$'::text))) AND (d."Guild" <> ALL (ARRAY['EOT'::text, 'TEST'::text, 'TBD'::text])) AND (d."displayName" IN ( SELECT five_season_players."displayName"
                   FROM five_season_players)))
          GROUP BY d."Guild"
        )
 SELECT guild_code,
    veteran_count
   FROM guild_veteran_counts
  WITH NO DATA;

ALTER MATERIALIZED VIEW public.guild_veterans_count OWNER TO postgres;

