CREATE MATERIALIZED VIEW public.member_stats_summary AS
 SELECT "Guild",
    "Season",
    "displayName",
    count(
        CASE
            WHEN ("damageType" = 'Battle'::text) THEN 1
            ELSE NULL::integer
        END) AS total_battles,
    count(
        CASE
            WHEN ("damageType" = 'Bomb'::text) THEN 1
            ELSE NULL::integer
        END) AS total_bombs,
    count(
        CASE
            WHEN (("remainingHp" = 0) AND ("damageType" = 'Battle'::text)) THEN 1
            ELSE NULL::integer
        END) AS boss_kills,
    avg(
        CASE
            WHEN (("damageType" = 'Battle'::text) AND ("damageDealt" > 0)) THEN "damageDealt"
            ELSE NULL::bigint
        END) AS avg_damage,
    max("damageDealt") AS max_damage,
    sum("damageDealt") AS total_damage,
    count(DISTINCT "Name") AS unique_bosses_fought
   FROM public."EOT_GR_data" e
  GROUP BY "Guild", "Season", "displayName"
  WITH NO DATA;

