CREATE MATERIALIZED VIEW public.mv_boss_performance AS
 SELECT "Season",
    "Name" AS boss_name,
    rarity,
    "damageType",
    cluster_code,
    count(*) AS attempt_count,
    count(DISTINCT "displayName") AS unique_players,
    (avg("damageDealt"))::integer AS avg_damage,
    max("damageDealt") AS max_damage,
    min("damageDealt") AS min_damage,
    percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY (("damageDealt")::double precision)) AS median_damage,
    sum(
        CASE
            WHEN ("remainingHp" = 0) THEN 1
            ELSE 0
        END) AS kills,
    sum(
        CASE
            WHEN ("damageDealt" >= "maxHp") THEN 1
            ELSE 0
        END) AS one_shots
   FROM public."EOT_GR_data"
  WHERE (("damageDealt" > 0) AND ("Season" = ( SELECT max("EOT_GR_data_1"."Season") AS max
           FROM public."EOT_GR_data" "EOT_GR_data_1")))
  GROUP BY "Season", "Name", rarity, "damageType", cluster_code
 HAVING (count(*) > 10)
  WITH NO DATA;

ALTER MATERIALIZED VIEW public.mv_boss_performance OWNER TO postgres;

CREATE MATERIALIZED VIEW public.mv_cluster_boss_averages AS
 SELECT gc.cluster_code,
    e."Season",
    e."Name" AS boss_name,
    e."encounterId",
    e.rarity,
    e.set,
    avg(e."damageDealt") AS cluster_avg,
    count(*) AS battle_count
   FROM (public."EOT_GR_data" e
     JOIN public.guild_config gc ON ((gc.guild_code = e."Guild")))
  WHERE ((e."damageType" = 'Battle'::text) AND (e.rarity = ANY (ARRAY['Legendary'::text, 'Mythic'::text])) AND (e."damageDealt" > 0) AND (NOT ((e."remainingHp" = 0) AND (e."maxHp" > 0) AND (e."damageDealt" < e."maxHp"))) AND (gc.cluster_code IS NOT NULL))
  GROUP BY gc.cluster_code, e."Season", e."Name", e."encounterId", e.rarity, e.set
  WITH NO DATA;

ALTER MATERIALIZED VIEW public.mv_cluster_boss_averages OWNER TO postgres;

CREATE MATERIALIZED VIEW public.mv_cluster_season_rankings AS
 WITH filtered_battles AS (
         SELECT d."Season",
            d.cluster_code,
            COALESCE(d."userId", ((d."Guild" || '::'::text) || lower(TRIM(BOTH FROM d."displayName")))) AS stable_key,
            d."displayName",
            d."Guild",
            d."damageDealt",
            ((d."Name" || '_'::text) || d.rarity) AS boss_key
           FROM public."EOT_GR_data" d
          WHERE ((d."damageType" = 'Battle'::text) AND (d.rarity = ANY (ARRAY['Legendary'::text, 'Mythic'::text])) AND (d."damageDealt" > 0) AND (d.cluster_code IS NOT NULL) AND (NOT ((d."remainingHp" = 0) AND (d."maxHp" > 0) AND (d."damageDealt" < d."maxHp"))))
        ), boss_averages AS (
         SELECT filtered_battles."Season",
            filtered_battles.cluster_code,
            filtered_battles.boss_key,
            avg(filtered_battles."damageDealt") AS cluster_avg
           FROM filtered_battles
          GROUP BY filtered_battles."Season", filtered_battles.cluster_code, filtered_battles.boss_key
        ), player_boss_stats AS (
         SELECT fb."Season",
            fb.cluster_code,
            fb.stable_key,
            fb."displayName",
            fb."Guild",
            fb.boss_key,
            avg(fb."damageDealt") AS player_avg,
            count(*) AS battle_count
           FROM filtered_battles fb
          GROUP BY fb."Season", fb.cluster_code, fb.stable_key, fb."displayName", fb."Guild", fb.boss_key
        ), player_performance AS (
         SELECT pbs."Season",
            pbs.cluster_code,
            pbs.stable_key,
            pbs."displayName",
            pbs."Guild",
            (sum(((((pbs.player_avg / NULLIF(ba.cluster_avg, (0)::numeric)) - (1)::numeric) * (100)::numeric) * (pbs.battle_count)::numeric)) / NULLIF(sum(pbs.battle_count), (0)::numeric)) AS percent_vs_cluster,
            sum(pbs.battle_count) AS total_battles
           FROM (player_boss_stats pbs
             JOIN boss_averages ba ON (((ba.boss_key = pbs.boss_key) AND (ba."Season" = pbs."Season") AND ((ba.cluster_code)::text = (pbs.cluster_code)::text))))
          GROUP BY pbs."Season", pbs.cluster_code, pbs.stable_key, pbs."displayName", pbs."Guild"
         HAVING (sum(pbs.battle_count) > (0)::numeric)
        )
 SELECT "Season" AS season,
    cluster_code,
    stable_key,
    "displayName" AS display_name,
    "Guild" AS guild,
    round(percent_vs_cluster, 2) AS percent_vs_cluster,
    (total_battles)::integer AS battle_count,
    (row_number() OVER (PARTITION BY "Season", cluster_code ORDER BY pp.percent_vs_cluster DESC NULLS LAST, "displayName"))::integer AS season_rank
   FROM player_performance pp
  WITH NO DATA;

ALTER MATERIALIZED VIEW public.mv_cluster_season_rankings OWNER TO postgres;

CREATE MATERIALIZED VIEW public.mv_global_leaderboard AS
 WITH player_season_stats AS (
         SELECT e."userId" AS player_id,
            pm.display_name AS current_player_name,
            e."Season",
            e."Guild",
            e.rarity,
            gc.cluster_code,
            avg(e."damageDealt") AS avg_damage,
            sum(e."damageDealt") AS total_damage,
            count(*) AS battle_count,
            0 AS bombs_used
           FROM ((public."EOT_GR_data" e
             LEFT JOIN public.player_mapping pm ON (((e."userId" = pm.player_id) AND (pm.is_current = true))))
             LEFT JOIN public.guild_config gc ON ((e."Guild" = gc.guild_code)))
          WHERE ((e."damageDealt" > 0) AND (e."damageType" = 'Battle'::text) AND (e."Season" ~ '^\d+$'::text) AND (e."userId" IS NOT NULL))
          GROUP BY e."userId", pm.display_name, e."Season", e."Guild", e.rarity, gc.cluster_code
        ), ranked_players AS (
         SELECT pss.player_id,
            pss.current_player_name,
            pss."Season",
            pss."Guild",
            pss.rarity,
            pss.cluster_code,
            pss.avg_damage,
            pss.total_damage,
            pss.battle_count,
            pss.bombs_used,
            row_number() OVER (PARTITION BY pss."Season", pss."Guild", pss.rarity ORDER BY pss.avg_damage DESC) AS guild_rank,
            row_number() OVER (PARTITION BY pss."Season", pss.cluster_code, pss.rarity ORDER BY pss.avg_damage DESC) AS cluster_rank,
            row_number() OVER (PARTITION BY pss."Season", pss.rarity ORDER BY pss.avg_damage DESC) AS global_rank
           FROM player_season_stats pss
        )
 SELECT player_id,
    COALESCE(current_player_name, 'Unknown Player'::text) AS player_name,
    "Season",
    "Guild",
    rarity,
    cluster_code,
    avg_damage,
    total_damage,
    battle_count,
    bombs_used,
    guild_rank,
    cluster_rank,
    global_rank,
    now() AS last_updated
   FROM ranked_players rp
  WITH NO DATA;

ALTER MATERIALIZED VIEW public.mv_global_leaderboard OWNER TO postgres;

CREATE MATERIALIZED VIEW public.mv_guild_performance_cache AS
 WITH guild_season_stats AS (
         SELECT e."Guild",
            e."Season",
            gc.cluster_code,
            count(DISTINCT e."userId") FILTER (WHERE (e."userId" IS NOT NULL)) AS unique_players,
            count(*) AS total_battles,
            avg(e."damageDealt") AS avg_damage,
            sum(e."damageDealt") AS total_damage,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((e."damageDealt")::double precision)) AS median_damage
           FROM (public."EOT_GR_data" e
             LEFT JOIN public.guild_config gc ON ((e."Guild" = gc.guild_code)))
          WHERE ((e."damageDealt" > 0) AND (e."damageType" = 'Battle'::text) AND (e."Season" ~ '^\d+$'::text))
          GROUP BY e."Guild", e."Season", gc.cluster_code
        ), ranked_guilds AS (
         SELECT gss."Guild",
            gss."Season",
            gss.cluster_code,
            gss.unique_players,
            gss.total_battles,
            gss.avg_damage,
            gss.total_damage,
            gss.median_damage,
            row_number() OVER (PARTITION BY gss."Season", gss.cluster_code ORDER BY gss.avg_damage DESC) AS cluster_rank,
            row_number() OVER (PARTITION BY gss."Season" ORDER BY gss.avg_damage DESC) AS global_rank
           FROM guild_season_stats gss
        )
 SELECT "Guild",
    "Season",
    cluster_code,
    unique_players,
    total_battles,
    avg_damage,
    total_damage,
    median_damage,
    cluster_rank,
    global_rank,
    now() AS last_updated
   FROM ranked_guilds rg
  WITH NO DATA;

ALTER MATERIALIZED VIEW public.mv_guild_performance_cache OWNER TO postgres;

CREATE MATERIALIZED VIEW public.mv_public_stats AS
 SELECT s,
    now() AS cached_at
   FROM public.get_public_stats_live() s(s)
  WITH NO DATA;

ALTER MATERIALIZED VIEW public.mv_public_stats OWNER TO postgres;

CREATE MATERIALIZED VIEW public.mv_season_summary AS
 SELECT "Season",
    cluster_code,
    "Guild",
    count(DISTINCT "displayName") AS player_count,
    count(DISTINCT "Name") AS unique_bosses,
    sum(
        CASE
            WHEN ("damageDealt" >= "maxHp") THEN 1
            ELSE 0
        END) AS one_shots,
    sum(
        CASE
            WHEN ("remainingHp" = 0) THEN 1
            ELSE 0
        END) AS completed_battles,
    count(*) AS total_battles,
    sum("damageDealt") AS total_damage,
    (avg("damageDealt"))::integer AS avg_damage,
    max("completedOn") AS last_activity
   FROM public."EOT_GR_data"
  WHERE ("Season" IN ( SELECT DISTINCT "EOT_GR_data_1"."Season"
           FROM public."EOT_GR_data" "EOT_GR_data_1"
          ORDER BY "EOT_GR_data_1"."Season" DESC
         LIMIT 5))
  GROUP BY "Season", cluster_code, "Guild"
  WITH NO DATA;

ALTER MATERIALIZED VIEW public.mv_season_summary OWNER TO postgres;

