CREATE VIEW public.player_architecture_health AS
 SELECT 'Total Players (userId method)'::text AS metric,
    (count(DISTINCT "EOT_GR_data"."userId"))::text AS value,
    'players'::text AS unit
   FROM public."EOT_GR_data"
  WHERE ("EOT_GR_data"."userId" IS NOT NULL)
UNION ALL
 SELECT 'Players with Mapping'::text AS metric,
    (count(DISTINCT player_mapping.player_id))::text AS value,
    'players'::text AS unit
   FROM public.player_mapping
UNION ALL
 SELECT 'Mapping Coverage'::text AS metric,
    (round((((( SELECT count(DISTINCT player_mapping.player_id) AS count
           FROM public.player_mapping))::numeric / (NULLIF(( SELECT count(DISTINCT "EOT_GR_data"."userId") AS count
           FROM public."EOT_GR_data"
          WHERE ("EOT_GR_data"."userId" IS NOT NULL)), 0))::numeric) * (100)::numeric), 1))::text AS value,
    '%'::text AS unit
UNION ALL
 SELECT 'Fixed RPC Functions'::text AS metric,
    (count(*))::text AS value,
    'functions'::text AS unit
   FROM (pg_proc p
     JOIN pg_namespace n ON ((p.pronamespace = n.oid)))
