CREATE VIEW public.player_performance_summary AS
 WITH RECURSIVE season_walk(season_num, depth) AS (
         SELECT ( SELECT max(e.season_num) AS max
                   FROM public."EOT_GR_data" e) AS max,
            1 AS "?column?"
        UNION ALL
         SELECT ( SELECT max(e.season_num) AS max
                   FROM public."EOT_GR_data" e
                  WHERE (e.season_num < sw.season_num)) AS max,
            (sw.depth + 1)
           FROM season_walk sw
          WHERE ((sw.season_num IS NOT NULL) AND (sw.depth < 3))
        ), recent_seasons AS (
         SELECT sw.season_num
           FROM season_walk sw
          WHERE (sw.season_num IS NOT NULL)
        ), player_stats AS (
         SELECT e."userId" AS player_id,
            pm.display_name AS current_player_name,
            e."Guild",
            e."Season",
            gc.cluster_code,
            avg(e."damageDealt") AS avg_damage,
            sum(e."damageDealt") AS total_damage,
            count(*) AS battle_count,
            count(DISTINCT e."Name") AS unique_bosses,
            max(e."damageDealt") AS max_damage
           FROM ((public."EOT_GR_data" e
             LEFT JOIN public.player_mapping pm ON (((e."userId" = pm.player_id) AND (pm.is_current = true))))
             LEFT JOIN public.guild_config gc ON ((e."Guild" = gc.guild_code)))
          WHERE ((e."damageDealt" > 0) AND (e."damageType" = 'Battle'::text) AND (e."userId" IS NOT NULL) AND (e.season_num IN ( SELECT rs.season_num
                   FROM recent_seasons rs)))
          GROUP BY e."userId", pm.display_name, e."Guild", e."Season", gc.cluster_code
        ), performance_ranks AS (
         SELECT ps.player_id,
            ps.current_player_name,
            ps."Guild",
            ps."Season",
            ps.cluster_code,
            ps.avg_damage,
            ps.total_damage,
            ps.battle_count,
            ps.unique_bosses,
            ps.max_damage,
            row_number() OVER (PARTITION BY ps."Guild", ps."Season" ORDER BY ps.avg_damage DESC) AS guild_rank,
            row_number() OVER (PARTITION BY ps.cluster_code, ps."Season" ORDER BY ps.avg_damage DESC) AS cluster_rank
           FROM player_stats ps
        )
 SELECT player_id,
    COALESCE(current_player_name, 'Unknown Player'::text) AS player_name,
    "Guild",
    "Season",
    cluster_code,
    avg_damage,
    total_damage,
    battle_count,
    unique_bosses,
    max_damage,
    guild_rank,
    cluster_rank,
        CASE
            WHEN (guild_rank <= 10) THEN 'Top 10'::text
            WHEN (guild_rank <= 25) THEN 'Top 25'::text
            ELSE 'Other'::text
        END AS performance_tier
   FROM performance_ranks pr;

ALTER VIEW public.player_performance_summary OWNER TO postgres;

