CREATE VIEW public.player_with_cluster WITH (security_invoker='true') AS
 SELECT pm.player_id,
    pm.guild_code,
    pm.user_id,
    pm.role,
    pm.is_current,
    NULL::text AS tacticus_api_key_encrypted,
    pm.api_key_is_valid,
    pm.auto_generated,
    pm.last_sync_tokens,
    pm.last_sync_bombs,
    pm.last_sync_at,
    pm.next_token_seconds,
    pm.next_bomb_seconds,
    pm.cluster_id,
    pm.primary_boss,
    pm.secondary_boss,
    pm.theme_preference,
    pm.display_name,
    gc.cluster_code,
    gc.display_name AS guild_display_name,
    c.display_name AS cluster_display_name,
    c.is_active AS cluster_is_active
   FROM ((public.player_mapping pm
     LEFT JOIN public.guild_config gc ON ((pm.guild_code = gc.guild_code)))
     LEFT JOIN public.clusters c ON (((gc.cluster_code)::text = (c.cluster_code)::text)))
  WHERE (pm.is_current = true);

