CREATE VIEW public.season_token_usage AS
 WITH battle_entries AS (
         SELECT "EOT_GR_data"."Guild" AS guild_code,
            "EOT_GR_data"."Season" AS season_id,
            COALESCE("EOT_GR_data"."displayName", 'Unknown'::text) AS display_name,
            "EOT_GR_data".cluster_code,
            min("EOT_GR_data"."startedOn") AS first_token_time,
            max("EOT_GR_data"."completedOn") AS last_token_time,
            (count(*))::integer AS tokens_used
           FROM public."EOT_GR_data"
          WHERE ("EOT_GR_data"."damageType" = 'Battle'::text)
          GROUP BY "EOT_GR_data"."Guild", "EOT_GR_data"."Season", COALESCE("EOT_GR_data"."displayName", 'Unknown'::text), "EOT_GR_data".cluster_code
        )
 SELECT b.guild_code,
    b.season_id,
    b.cluster_code,
    b.display_name,
    b.tokens_used,
    COALESCE(sc.tokens_per_player_cap, 28) AS max_possible_tokens,
    GREATEST((COALESCE(sc.tokens_per_player_cap, 28) - b.tokens_used), 0) AS tokens_missing,
    b.first_token_time,
    b.last_token_time,
    sc.regen_interval_hours,
    sc.regen_tokens_per_interval
   FROM (battle_entries b
     LEFT JOIN public.season_calendar sc ON (((sc.season_id)::text = b.season_id)));

ALTER VIEW public.season_token_usage OWNER TO postgres;

