    created_at timestamp with time zone DEFAULT now() NOT NULL,
    guild_code text NOT NULL,
    player_id text NOT NULL,
    display_name text NOT NULL,
    season text NOT NULL,
    mode text NOT NULL,
    live_tokens integer NOT NULL,
    live_tokens_max integer NOT NULL,
    live_token_next_seconds integer,
    live_regen_delay_seconds integer NOT NULL,
    live_bombs integer,
    live_bomb_next_seconds integer,
    live_bomb_regen_delay_seconds integer,
    rpc_tokens integer,
    rpc_token_next_seconds integer,
    rpc_data_source text,
    cpta_tokens integer,
    cpta_tokens_delta integer,
    battle_rows_seen integer NOT NULL,
    rpc_tokens_delta integer,
    constants_ok boolean NOT NULL,
    rpc_post_snapshot_spends integer,
    CONSTRAINT token_audit_snapshots_mode_check CHECK ((mode = ANY (ARRAY['daily'::text, 'rollover'::text])))
);

ALTER TABLE public.token_audit_snapshots OWNER TO postgres;

