);

ALTER TABLE public.token_cap_notifications OWNER TO postgres;

CREATE TABLE public.token_notification_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    guild_code text NOT NULL,
    season text NOT NULL,
    player_id text NOT NULL,
    display_name text,
    notification_type text NOT NULL,
    delivery_channel text NOT NULL,
    tokens_available integer NOT NULL,
    token_next_in_seconds integer,
    data_source text,
    preference_id uuid,
    dedupe_window_started_at timestamp with time zone NOT NULL,
    dedupe_window_seconds integer NOT NULL,
    dedupe_key text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone,
    dispatched_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT token_notification_events_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT token_notification_events_data_source_check CHECK ((data_source = ANY (ARRAY['live'::text, 'calculated'::text]))),
    CONSTRAINT token_notification_events_dedupe_window_seconds_check CHECK ((dedupe_window_seconds >= 300)),
    CONSTRAINT token_notification_events_delivery_channel_check CHECK ((delivery_channel = ANY (ARRAY['discord'::text, 'in_app'::text, 'push'::text, 'sms'::text]))),
    CONSTRAINT token_notification_events_notification_type_check CHECK ((notification_type = ANY (ARRAY['capped'::text, 'near_cap'::text, 'burn_warning'::text, 'burn_occurred'::text]))),
    CONSTRAINT token_notification_events_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'failed'::text, 'skipped'::text]))),
    CONSTRAINT token_notification_events_tokens_available_check CHECK ((tokens_available >= 0))
);

ALTER TABLE public.token_notification_events OWNER TO postgres;

CREATE TABLE public.token_notification_preferences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    guild_code text NOT NULL,
    player_id text,
    channel text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    notify_on_capped boolean DEFAULT true NOT NULL,
    notify_on_near_cap boolean DEFAULT true NOT NULL,
    near_cap_threshold_seconds integer DEFAULT 7200 NOT NULL,
    dedupe_window_seconds integer DEFAULT 21600 NOT NULL,
    discord_channel_id text,
    created_by text,
    updated_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    notify_on_pre_burn boolean DEFAULT true NOT NULL,
    notify_on_post_burn boolean DEFAULT true NOT NULL,
    pre_burn_window_seconds integer DEFAULT 3600 NOT NULL,
    CONSTRAINT token_notification_preferences_channel_check CHECK ((channel = ANY (ARRAY['discord'::text, 'in_app'::text, 'push'::text, 'sms'::text]))),
    CONSTRAINT token_notification_preferences_dedupe_window_seconds_check CHECK (((dedupe_window_seconds >= 300) AND (dedupe_window_seconds <= 86400))),
    CONSTRAINT token_notification_preferences_near_cap_threshold_seconds_check CHECK (((near_cap_threshold_seconds >= 300) AND (near_cap_threshold_seconds <= 43200))),
    CONSTRAINT token_notification_preferences_pre_burn_window_check CHECK (((pre_burn_window_seconds >= 60) AND (pre_burn_window_seconds <= 43200)))
);

ALTER TABLE public.token_notification_preferences OWNER TO postgres;

