CREATE TABLE public.war_player_lineups (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    guild_code text NOT NULL,
    lineup_type text NOT NULL,
    lineup_name text DEFAULT 'Untitled Lineup'::text NOT NULL,
