    heroes text[] DEFAULT '{}'::text[],
    machine_of_war text,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT defensive_max_5 CHECK (((lineup_type <> 'defensive'::text) OR ((slot_number >= 1) AND (slot_number <= 5)))),
    CONSTRAINT max_5_heroes CHECK (((array_length(heroes, 1) IS NULL) OR (array_length(heroes, 1) <= 5))),
    CONSTRAINT offensive_max_10 CHECK (((lineup_type <> 'offensive'::text) OR ((slot_number >= 1) AND (slot_number <= 10)))),
    CONSTRAINT war_player_lineups_lineup_type_check CHECK ((lineup_type = ANY (ARRAY['defensive'::text, 'offensive'::text])))
);

