CREATE POLICY "Ability metadata is publicly readable" ON public.ability_metadata FOR SELECT USING (true);

CREATE POLICY "Allow authenticated cap notification creation" ON public.token_cap_notifications FOR INSERT TO authenticated WITH CHECK (true);

CREATE POLICY "Allow authenticated cap notification updates" ON public.token_cap_notifications FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.player_mapping pm
  WHERE ((pm.player_id = token_cap_notifications.player_id) AND (pm.is_current = true)))));

CREATE POLICY "Allow authenticated users to read guild snapshots" ON public.public_guild_snapshots FOR SELECT TO authenticated USING (true);

CREATE POLICY "Allow service role access to season tracking" ON public.season_tracking USING ((( SELECT auth.role() AS role) = 'service_role'::text));

CREATE POLICY "Allow service role to insert guild configs" ON public.guild_config FOR INSERT TO service_role WITH CHECK (true);

CREATE POLICY "Allow updates through function" ON public.bomb_tracking FOR UPDATE USING (false);

CREATE POLICY "Anyone authenticated can read progression config" ON public.raid_progression_config FOR SELECT USING ((( SELECT auth.role() AS role) = 'authenticated'::text));

CREATE POLICY "Anyone can read avatar frames" ON public.player_avatar_frames FOR SELECT USING (true);

CREATE POLICY "Anyone can view active carousel items" ON public.carousel_items FOR SELECT USING (((is_active = true) AND ((starts_at IS NULL) OR (starts_at <= now())) AND ((expires_at IS NULL) OR (expires_at > now()))));

