CREATE POLICY boss_target_tokens_read ON public.boss_target_tokens FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.player_mapping pm
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.guild_code = boss_target_tokens.guild_code) AND (pm.is_current = true)))));

CREATE POLICY boss_target_tokens_write ON public.boss_target_tokens TO authenticated USING (((EXISTS ( SELECT 1
   FROM public.player_mapping pm
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.guild_code = boss_target_tokens.guild_code) AND (pm.is_current = true) AND ((pm.role)::text = ANY (ARRAY['leader'::text, 'officer'::text]))))) OR (EXISTS ( SELECT 1
   FROM ((public.player_mapping pm
     JOIN public.guild_config gc_user ON ((gc_user.guild_code = pm.guild_code)))
     JOIN public.guild_config gc_target ON ((gc_target.guild_code = boss_target_tokens.guild_code)))
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (pm.role = 'leader'::public.app_role) AND (gc_user.cluster_code IS NOT NULL) AND ((gc_user.cluster_code)::text = (gc_target.cluster_code)::text)))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM public.player_mapping pm
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.guild_code = boss_target_tokens.guild_code) AND (pm.is_current = true) AND ((pm.role)::text = ANY (ARRAY['leader'::text, 'officer'::text]))))) OR (EXISTS ( SELECT 1
   FROM ((public.player_mapping pm
     JOIN public.guild_config gc_user ON ((gc_user.guild_code = pm.guild_code)))
     JOIN public.guild_config gc_target ON ((gc_target.guild_code = boss_target_tokens.guild_code)))
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (pm.role = 'leader'::public.app_role) AND (gc_user.cluster_code IS NOT NULL) AND ((gc_user.cluster_code)::text = (gc_target.cluster_code)::text))))));

