CREATE POLICY webhook_config_leader_cluster_manage ON public.webhook_config TO authenticated USING (((EXISTS ( SELECT 1
   FROM (public.player_mapping pm
     JOIN public.guild_config gc ON ((gc.guild_code = pm.guild_code)))
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (lower((pm.role)::text) = 'leader'::text) AND (((webhook_config.cluster_id IS NOT NULL) AND (webhook_config.cluster_id = gc.cluster_id)) OR ((webhook_config.guild_code IS NOT NULL) AND (webhook_config.guild_code IN ( SELECT g2.guild_code
           FROM public.guild_config g2
          WHERE (g2.cluster_id = gc.cluster_id)))))))) OR ((cluster_id IS NOT NULL) AND (cluster_id IN ( SELECT c.id
   FROM public.clusters c
  WHERE (c.created_by = ( SELECT auth.uid() AS uid))))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM (public.player_mapping pm
     JOIN public.guild_config gc ON ((gc.guild_code = pm.guild_code)))
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (lower((pm.role)::text) = 'leader'::text) AND (((webhook_config.cluster_id IS NOT NULL) AND (webhook_config.cluster_id = gc.cluster_id)) OR ((webhook_config.guild_code IS NOT NULL) AND (webhook_config.guild_code IN ( SELECT g2.guild_code
           FROM public.guild_config g2
          WHERE (g2.cluster_id = gc.cluster_id)))))))) OR ((cluster_id IS NOT NULL) AND (cluster_id IN ( SELECT c.id
   FROM public.clusters c
  WHERE (c.created_by = ( SELECT auth.uid() AS uid)))))));

CREATE POLICY webhook_config_member_read ON public.webhook_config FOR SELECT TO authenticated USING ((((guild_code IS NOT NULL) AND (guild_code IN ( SELECT public._pm_caller_guild_codes() AS _pm_caller_guild_codes))) OR ((cluster_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM (public.player_mapping pm
     JOIN public.guild_config gc ON ((gc.guild_code = pm.guild_code)))
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (gc.cluster_id = webhook_config.cluster_id)))))));

