CREATE POLICY wi3136_cluster_creators_delete ON public.clusters FOR DELETE TO authenticated USING (((created_by = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM public.player_mapping pm
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (pm.role = 'leader'::public.app_role))))));

CREATE POLICY wi3136_cluster_leaders_insert ON public.clusters FOR INSERT TO authenticated WITH CHECK (((created_by = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM public.player_mapping pm
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (pm.role = 'leader'::public.app_role))))));

CREATE POLICY wi3136_cluster_leaders_update ON public.clusters FOR UPDATE TO authenticated USING (((created_by = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM (public.player_mapping pm
     JOIN public.guild_config gc ON ((gc.guild_code = pm.guild_code)))
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (pm.role = 'leader'::public.app_role) AND (gc.cluster_id = clusters.id)))) OR (EXISTS ( SELECT 1
   FROM public.player_mapping pm
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (pm.is_app_admin = true)))))) WITH CHECK (((created_by = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM (public.player_mapping pm
     JOIN public.guild_config gc ON ((gc.guild_code = pm.guild_code)))
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (pm.role = 'leader'::public.app_role) AND (gc.cluster_id = clusters.id)))) OR (EXISTS ( SELECT 1
   FROM public.player_mapping pm
  WHERE ((pm.user_id = ( SELECT auth.uid() AS uid)) AND (pm.is_current = true) AND (pm.is_app_admin = true))))));

