-- Fail closed if a regeneration restores removed features or per-guild client secrets.
DO $clean_baseline_residue$
DECLARE
  residue text;
BEGIN
  SELECT pg_catalog.string_agg(item, E'\n' ORDER BY item)
    INTO residue
    FROM (
      SELECT pg_catalog.format('relation %I.%I', n.nspname, c.relname) AS item
        FROM pg_catalog.pg_class c
        JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
       WHERE n.nspname IN ('public', 'monitoring')
         AND c.relkind IN ('r', 'p', 'v', 'm', 'S', 'f')
         AND c.relname ~* '(captured_replay|competitive|^rival_|oracle|battle_sim|^sim_|^meta_run|recruit|showcase|war_sync|role_cleanup|managed_role|staging|shadow|^wi[0-9]+|backup|_bak$|_old$|_temp$|_tmp$)'
         AND NOT (
           n.nspname = 'monitoring'
           AND c.relname LIKE 'application_slow_queries%'
         )
      UNION ALL
      SELECT pg_catalog.format(
        'column %I.%I.%I', n.nspname, c.relname, a.attname
      )
        FROM pg_catalog.pg_attribute a
        JOIN pg_catalog.pg_class c ON c.oid = a.attrelid
        JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
       WHERE n.nspname = 'public'
         AND c.relkind IN ('r', 'p')
         AND a.attnum > 0
         AND NOT a.attisdropped
         AND a.attname ~* '(captured_replay|competitive|^rival_|oracle|battle_sim|^sim_|meta_run|recruit|showcase|war_sync|client_secret|role_cleanup|managed_role)'
    ) leftovers;

  IF residue IS NOT NULL THEN
    RAISE EXCEPTION 'clean baseline contains excluded residue:%', E'\n' || residue;
  END IF;

  RAISE NOTICE 'clean baseline loaded successfully';
END
$clean_baseline_residue$;

CREATE OR REPLACE FUNCTION public.consume_discord_bot_invite(
  p_invite_code text,
  p_discord_guild_id text,
  p_discord_user_id text
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_invite public.discord_invite_codes%ROWTYPE;
  v_guild public.guild_config%ROWTYPE;
  v_prior_mapping public.discord_server_guilds%ROWTYPE;
  v_existing_mapping public.discord_server_guilds%ROWTYPE;
BEGIN
  IF NULLIF(btrim(p_invite_code), '') IS NULL
     OR NULLIF(btrim(p_discord_guild_id), '') IS NULL THEN
    RETURN jsonb_build_object('status', 'invalid');
  END IF;

  SELECT invite.*
    INTO v_invite
    FROM public.discord_invite_codes AS invite
   WHERE invite.invite_code = p_invite_code
   FOR UPDATE;

  IF NOT FOUND OR v_invite.is_active IS DISTINCT FROM true THEN
    RETURN jsonb_build_object('status', 'invalid');
  END IF;

  IF COALESCE(v_invite.current_uses, 0) >= COALESCE(v_invite.max_uses, 0) THEN
    RETURN jsonb_build_object('status', 'exhausted');
  END IF;

  IF v_invite.expires_at IS NOT NULL AND v_invite.expires_at <= now() THEN
    RETURN jsonb_build_object('status', 'expired');
  END IF;

  SELECT config.*
    INTO v_guild
    FROM public.guild_config AS config
   WHERE config.guild_code = v_invite.guild_code;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'guild_missing');
  END IF;

  SELECT mapping.*
    INTO v_prior_mapping
    FROM public.discord_server_guilds AS mapping
   WHERE mapping.invited_with_code = p_invite_code
     AND mapping.is_active = true
   ORDER BY mapping.id
   LIMIT 1;

  IF FOUND
     AND (
       v_prior_mapping.discord_guild_id <> p_discord_guild_id
       OR v_prior_mapping.game_guild_code <> v_invite.guild_code
     ) THEN
    RETURN jsonb_build_object('status', 'already_used');
  END IF;

  SELECT mapping.*
    INTO v_existing_mapping
    FROM public.discord_server_guilds AS mapping
   WHERE mapping.discord_guild_id = p_discord_guild_id
     AND mapping.game_guild_code = v_invite.guild_code
     AND mapping.is_active = true;

  IF FOUND THEN
    UPDATE public.discord_invite_codes AS invite
       SET current_uses = COALESCE(invite.current_uses, 0) + 1,
           is_active = false
     WHERE invite.id = v_invite.id;

    RETURN jsonb_build_object(
      'status', 'already_linked',
      'guild_code', v_invite.guild_code
    );
  END IF;

  INSERT INTO public.discord_server_guilds (
    discord_guild_id,
    game_guild_code,
    cluster_code,
    invited_with_code,
    linked_by_user_id,
    is_active
  ) VALUES (
    p_discord_guild_id,
    v_invite.guild_code,
    v_guild.cluster_code,
    p_invite_code,
    p_discord_user_id,
    true
  )
  ON CONFLICT (discord_guild_id, game_guild_code)
  DO UPDATE SET
    cluster_code = EXCLUDED.cluster_code,
    invited_with_code = EXCLUDED.invited_with_code,
    linked_by_user_id = EXCLUDED.linked_by_user_id,
    is_active = true,
    linked_at = now();

  UPDATE public.discord_invite_codes AS invite
     SET current_uses = COALESCE(invite.current_uses, 0) + 1,
         is_active = false
   WHERE invite.id = v_invite.id;

  RETURN jsonb_build_object(
    'status', 'linked',
    'guild_code', v_invite.guild_code
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.consume_discord_bot_invite(text, text, text)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consume_discord_bot_invite(text, text, text)
  TO service_role;

-- pg_dump cannot express "PUBLIC has nothing": revoke PUBLIC EXECUTE on two destructive
-- definers; clients keep clear_season_assignments (officers call it). Guards use
-- IS DISTINCT FROM because `<>` skips them on JWT-less calls.

REVOKE EXECUTE ON FUNCTION public.clear_season_assignments(p_guild_code text, p_season_number text)
  FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.refresh_votlw_winners()
  FROM PUBLIC, anon, authenticated;
